def _coerce_operation(operation: Any) -> Dict[str, Any]:
    """Normalize workflow operations from dicts or Pydantic models to plain dicts."""
    if operation is None:
        return {}
    if isinstance(operation, dict):
        return dict(operation)

    if hasattr(operation, "model_dump"):
        try:
            data = operation.model_dump(exclude_unset=True)
            if isinstance(data, dict):
                return data
        except TypeError:
            pass

    if hasattr(operation, "dict"):
        try:
            data = operation.dict(exclude_unset=True)
            if isinstance(data, dict):
                return data
        except TypeError:
            pass

    result: Dict[str, Any] = {}
    for field_name in (
        "action",
        "targetStepId",
        "afterStepId",
        "beforeStepId",
        "prompt",
        "name",
        "toolType",
        "phaseName",
        "phaseType",
        "nodes",
        "clarificationAnswers",
        "inputBindings",
    ):
        if hasattr(operation, field_name):
            result[field_name] = getattr(operation, field_name)
    return result


def _coerce_operations(operations: Any) -> List[Dict[str, Any]]:
    if not operations:
        return []
    return [_coerce_operation(op) for op in operations]


def _extract_global_inputs(phase_graphs: list) -> list:
    """Extract global inputs from all phase graphs."""
    global_inputs = []
    seen = set()
    for phase in phase_graphs:
        graph = phase.get("graph", {})
        for g in graph.get("requiredGlobalInputs", []):
            if g not in seen:
                seen.add(g)
                global_inputs.append({"name": g, "dataType": "string"})
    return global_inputs


async def _load_current_codebase(project_id: str, workflow_id: str, phase_graphs: List[Dict[str, Any]] = None) -> Dict[str, str]:
    """
    Load existing generated code from workspace/database for surgical editing context.

    Loads Angular workspace code for all UI screens in the workflow.
    """
    from repositories.screen_repository import ScreenRepository
    from services.angular_generator import AngularAppGenerator

    code_files = {}
    screen_repo = ScreenRepository()
    angular_generator = AngularAppGenerator()

    if not phase_graphs:
        logger.warning(f"[load_codebase] No phase_graphs provided for project {project_id}")
        return code_files

    # Find all UI screens in the phase graphs
    for phase_entry in phase_graphs:
        graph = phase_entry.get("graph", {})
        for node in graph.get("nodes", []):
            cap_ref = node.get("capabilityRef") or {}
            if isinstance(cap_ref, dict) and cap_ref.get("capabilityId", "").startswith("ui:"):
                screen_id = cap_ref["capabilityId"][3:]
                try:
                    # Get screen state to find workspace directory
                    screen_state = await screen_repo.get_screen_state(project_id, screen_id)
                    logger.info(f"[load_codebase] Screen state for {screen_id}: {screen_state.get('angular_workspace_directory') if screen_state else 'None'}")
                    if screen_state and screen_state.get("angular_workspace_directory"):
                        workspace_dir = screen_state["angular_workspace_directory"]
                        logger.info(f"[load_codebase] Reading workspace for screen {screen_id}: {workspace_dir}")
                        screen_code = angular_generator._read_workspace_code(workspace_dir)
                        logger.info(f"[load_codebase] Loaded {len(screen_code)} files from {workspace_dir}")
                        # Prefix paths with screen_id to avoid conflicts
                        for path, content in screen_code.items():
                            code_files[f"{screen_id}/{path}"] = content
                    else:
                        logger.warning(f"[load_codebase] No angular_workspace_directory found for screen {screen_id} (project={project_id})")
                except Exception as e:
                    logger.error(f"[load_codebase] Failed to load code for screen {screen_id}: {type(e).__name__}: {e}")
                    import traceback
                    logger.error(f"[load_codebase] Traceback: {traceback.format_exc()}")
                    continue

    logger.info(f"[load_codebase] Total code files loaded: {len(code_files)} for project {project_id}")
    return code_files


_GENERIC_DECLARED_OUTPUT_NAMES: frozenset = frozenset({"formOutput", "output", "result"})

# Names matching these patterns are treated as generic placeholders regardless of
# the surrounding identifier — they are emitted by the AI processor as fallback
# outputs (see ``services/ai_processor.py``: ``add_output(f"{cid}_output", ...)``)
# when it cannot enumerate real per-field outputs.
_GENERIC_DECLARED_OUTPUT_SUFFIXES: tuple = (
    "_output",
    "_form_output",
    "_result",
    "_response",
    "_payload",
    "_data",
    "_value",
    "_values",
)

# Module-level prompt constraint — appended to every Angular IO-contract prompt
# sent to the LLM to forbid generic placeholders at the source. Keep wording
# tight and authoritative; it is included in the prompt verbatim.
#
# Two responsibilities:
#   (a) Forbid generic placeholders (formOutput / output / *_output / etc.).
#   (b) Force 1-to-1 coverage of EVERY real interactive field on the screen —
#       including selectors, dropdowns, radios, checkboxes, and any field
#       named in the screen description with phrases like "called X",
#       "named X", "labelled X", or wrapped in backticks/quotes.
_NORMAL_NUMBER_LIKE = (
    "number", "amount", "quantity", "count", "price", "value", "score",
    "age", "weight", "height", "total",
)
_SELECTOR_KEYWORDS = (
    "selector", "dropdown", "drop-down", "radio", "checkbox",
    "select ", "options", "operationselector", "operandselector",
    "combobox", "switch", "toggle",
)


_NO_GENERIC_OUTPUTS_CONSTRAINT: str = (
    "HARD CONSTRAINT:\n"
    "1. outputParameters MUST contain one entry per REAL interactive field on "
    "the screen. 'Real interactive field' includes, but is not limited to: "
    "number inputs, text inputs, textareas, selects/dropdowns, radios, "
    "checkboxes, date pickers, sliders, file pickers, and switch/toggles.\n"
    "2. NEVER emit generic placeholders such as 'formOutput', 'output', "
    "'result', or any '<component>_output' / '<component>_value' / "
    "'<component>_data' / '<component>_response' / '<component>_payload' "
    "shorthand.\n"
    "3. If the screen description (or the update request that produced it) "
    "introduces a new field — typically named with phrases like 'called X', "
    "'named X', 'labelled X', or wrapped in backticks/quotes (X) — that "
    "field MUST appear in outputParameters using the EXACT field name given. "
    "Do not invent alternate names like 'operation', 'selected_op', or "
    "'category_choice' if the user specified 'selected_operation', "
    "'category', etc.\n"
    "4. Constraint #1 applies EVEN IF inputParameters does not yet list the "
    "new field. inputParameters is the previous state; the screen description "
    "is the source of truth — outputParameters must agree with whatever the "
    "screen actually returns, not just whatever inputParameters happened to "
    "contain before the update.\n"
    "5. Order and naming MUST match: if the screen returns "
    "`number_1` (number), `number_2` (number), `selected_operation` (string), "
    "outputParameters MUST be exactly that list, in that field-name spelling, "
    "with the matching dataType.\n"
    "6. If the screen description is ambiguous and you cannot determine the "
    "exact field names, prefer to omit the entry rather than guess a wrong "
    "name — but in the common case where inputParameters names match the "
    "description, the entry MUST be present."
)


def _is_generic_declared_output(d: Any) -> bool:
    """True if ``d`` is a generic placeholder — either a known hardcoded name
    (``formOutput``/``output``/``result``) or a suffix match (``*_output``,
    ``*_value``, etc.). Also true for missing / blank names.
    """
    if not isinstance(d, dict):
        return True
    nm = (d.get("name") or "")
    if not isinstance(nm, str):
        return True
    nm = nm.strip()
    if not nm:
        return True
    if nm in _GENERIC_DECLARED_OUTPUT_NAMES:
        return True
    low = nm.lower()
    # Suffix-pattern match (case-insensitive): catches ``<cid>_output``,
    # ``<cid>_value``, ``<cid>_data`` etc. emitted by ai_processor fallback paths.
    for suf in _GENERIC_DECLARED_OUTPUT_SUFFIXES:
        if low.endswith(suf):
            return True
    return False


def _strip_generic_declared_outputs(outputs: list) -> list:
    """Drop generic placeholders (``formOutput``/``output``/``result``/``*_output``
    /``*_value``/empty) from a declaredOutputs list, but ONLY when at least one
    real, non-generic field is present. If everything is generic, leave the list
    untouched so the form still declares *something*.

    This is safe to apply repeatedly — running it on an already-clean list is a no-op.
    """
    if not outputs:
        return outputs
    real = [o for o in outputs if not _is_generic_declared_output(o)]
    if not real:
        return list(outputs)
    return real


# Identifier-shaped tokens inside a screen description that look like real
# field names. We deliberately only treat *lower-case snake_case-ish* tokens
# as field candidates to avoid grabbing UI-label words such as
# "First Number" or "Add the numbers".
_FIELD_NAME_TOKEN = __import__("re").compile(r"\b([a-z][a-z0-9_]{1,40})\b")

# Backticked identifiers in a user prompt are a STRONG signal that the user
# is naming a field the output MUST expose (e.g. "Add a ``selected_operation``
# field"). We also accept "called X" / "named X" prose because users usually
# don't bother with backticks in UPDATE prompts.
_BACKTICK_FIELD_RE = __import__("re").compile(r"`([a-zA-Z_][a-zA-Z0-9_]{1,40})`")
_CALLED_FIELD_RE = __import__("re").compile(
    r"\b(?:called|named|labeled|labelled)\s+([a-zA-Z_][a-zA-Z0-9_]{1,40})\b",
    __import__("re").IGNORECASE,
)


def _prune_declared_outputs_to_grounded_set(
    adopted: list,
    *,
    original_outputs: Optional[Iterable[Any]] = None,
    force_include_names: Optional[Iterable[str]] = None,
    text_sources: Optional[Iterable[str]] = None,
) -> list:
    """Final filter: keep only declaredOutputs that the user's intents can
    justify — names that were already present originally, names the user's
    UPDATE prompt force-named, or names textually mentioned in any of the
    ``text_sources`` (typically ``generationDescription``).

    ``adopted`` and the individual entries may be dicts or GenerationIOParam
    objects; we extract ``.name`` defensively.

    This guards against the IR LLM pulling in spurious backend-derived
    column names (``first_number``, ``second_number`` inferred from
    'First Number'/'Second Number' labels and a backend Mongo schema probe)
    that have no real meaning to the screen's binding synthesis. Without
    this prune, the LangGraph state machine grows orphan writes/bindings
    that look like real fields but reference nothing the user asked for.
    """
    import re as _re

    def _n(o):
        if isinstance(o, dict):
            return (o.get("name") or "").strip()
        if isinstance(o, str):
            return o.strip()
        return getattr(o, "name", "") or ""

    original_set = set()
    for o in (original_outputs or ()):
        nm = _n(o)
        if nm:
            original_set.add(nm)

    keep_set = set(original_set)
    for fn in (force_include_names or ()):
        if isinstance(fn, str) and fn.strip():
            keep_set.add(fn.strip())
    for src in (text_sources or ()):
        if not isinstance(src, str) or not src:
            continue
        for m in _re.finditer(r"`([a-zA-Z_][a-zA-Z0-9_]{1,40})`", src):
            keep_set.add(m.group(1))
        for m in _re.finditer(r"'([a-zA-Z_][a-zA-Z0-9_]{1,40})'", src):
            keep_set.add(m.group(1))
        for m in _re.finditer(r'"([a-zA-Z_][a-zA-Z0-9_]{1,40})"', src):
            keep_set.add(m.group(1))
        # "called/named/labelled X" introducers — case-insensitive but use
        # the original-case token from the source for accuracy.
        lower = src.lower()
        for intro in ("called", "named", "labelled", "labeled"):
            pat = _re.compile(rf"\b{_re.escape(intro)}\s+([a-zA-Z_][a-zA-Z0-9_]{{1,40}})\b")
            for m in pat.finditer(lower):
                real_start = m.start(1)
                real_end = m.end(1)
                keep_set.add(src[real_start:real_end])

    pruned = [o for o in (adopted or []) if _n(o) in keep_set]
    return pruned


def _extract_force_include_names(prompt_text: Any) -> List[str]:
    """Pull field-shape names from a user UPDATE prompt.

    Returns the deduplicated list of names that the screen MUST accept as a
    declaredOutput. Used at /plan/update call sites where we don't trust the
    LLM to enumerate them in declaredOutputs even though the user named them.
    """
    if not isinstance(prompt_text, str) or not prompt_text.strip():
        return []
    out: List[str] = []
    seen: set = set()
    for rx in (_BACKTICK_FIELD_RE, _CALLED_FIELD_RE):
        for m in rx.findall(prompt_text):
            n = (m or "").strip()
            if not n or n in seen:
                continue
            seen.add(n)
            out.append(n)
    return out


def _supplement_output_parameters_from_description(
    generation_description: Any,
    input_parameters: Any,
    output_parameters: Any,
    force_include_names: Optional[Iterable[str]] = None,
) -> list:
    """Defensive code-side safety net for the IO contract LLM call.

    Goal: ensure that every real field referenced by the screen description
    (and already accepted as an inputParameter) ends up in ``outputParameters``.
    Used after Angular IO contract LLM returns from the integrated pipeline —
    if the LLM model misses a field (e.g. a newly-added ``selected_operation``
    selector), this sidecar catches it deterministically without round-tripping.

    Backwards-compat: if ``force_include_names`` is None the function behaves
    exactly as before (description-only scanning). Callers in the
    /plan/update path pass an iterable of names extracted from the user's
    UPDATE prompt (backticks, "called X", "named X", "labelled X") so the
    rescue layer can hydrate declaredOutputs even when the screen's
    genDesc itself does not contain the field name.

    Heuristic, in priority order:

      1. Every name already present in ``input_parameters`` MUST appear in
         ``output_parameters``. If a name from inputs is missing from outputs,
         inject a type-mirrored copy (string OR number OR object — we default
         to 'string' since unknown inputs are most often selectors/dropdowns,
         but if inputParameters already has dataType, mirror it).
      2. Backticked/quoted field-name mentions in ``generation_description``
         that are not already covered by inputs or outputs are *also*
         candidates. We only inject a candidate if its surrounding text looks
         like selector/radio/dropdown/options context, to avoid hallucinating
         field names from garbled captions.

    The result preserves the original ordering: first existing non-generic
    outputs (in their original order), then injected supplements. Generic
    outputs (``formOutput``/etc.) are filtered out.

    Returns a *new* list — never mutates inputs.
    """
    import re as _re

    outs = output_parameters if isinstance(output_parameters, list) else []
    ins = input_parameters if isinstance(input_parameters, list) else []
    desc = (generation_description or "") if isinstance(generation_description, str) else ""
    desc_lower = desc.lower()

    def _name(o):
        if isinstance(o, dict):
            return (o.get("name") or "").strip()
        if isinstance(o, str):
            return o.strip()
        return ""

    # Drop generic placeholders first.
    real_outputs = [o for o in outs if not _is_generic_declared_output(o)]
    existing_names = {_name(o) for o in real_outputs if _name(o)}
    input_by_name = {}
    for o in ins:
        nm = _name(o)
        if nm and nm not in input_by_name:
            input_by_name[nm] = o if isinstance(o, dict) else {"name": nm}

    def _make_entry(name: str, *, hint_type: str = "string") -> dict:
        # Type resolution: prefer inputParameter type if known; else fall back
        # to description hints; else 'string' for selectors.
        rec = input_by_name.get(name)
        if rec and isinstance(rec.get("dataType"), str):
            data_type = rec["dataType"]
        elif name in {m.group(1) for m in _re.finditer(r"\b(\w+_result|\w+_output)\b", name)}:
            data_type = "object"
        elif name == "acknowledgement" or name.endswith("_ack") or "acknowledg" in name.lower():
            data_type = "boolean"
        elif _re.search(rf"\b{_re.escape(name)}\b.{0,40}\bnumber\b", desc_lower) \
             or any(kw in name for kw in _NORMAL_NUMBER_LIKE):
            data_type = "number"
        else:
            data_type = hint_type
        return {
            "name": name,
            "dataType": data_type,
            "required": True,
            "description": f"Auto-supplemented output for {name}."
            + (" (inferred from screen description)" if hint_type != "string" else ""),
        }

    supplemented = list(real_outputs)

    # Step 1 — honour caller-supplied force-include names only.
    # These come from the user's UPDATE prompt extracted upstream ("called X", backticks, etc).
    # The screen's genDesc may mention the concept ("operation selector")
    # without restating the field name. We need the field name to land in
    # declaredOutputs so downstream tool reconciliation has something to diff
    # against.
    for f_name in (force_include_names or ()):
        if isinstance(f_name, str) and f_name.strip():
            cand = f_name.strip()
            if cand not in existing_names:
                supplemented.append(_make_entry(cand, hint_type="string"))
                existing_names.add(cand)

    # Supplementer is now minimal - only adds force_include_names.
    # Let the LLM generate outputs naturally. No description scanning.

    return supplemented


# Module-level helper: coerce a list of dicts | GenerationIOParam | generic
# objects into a list of GenerationIOParam models. Pydantic v2 does NOT do
# this automatically on plain attribute assignment (unlike v1), so any time we
# assign to ``declaredOutputs`` from raw dicts we must run them through this
# helper first to avoid ``o.name`` AttributeError downstream.
try:
    from pydantic import TypeAdapter as _PydTypeAdapter
except ImportError:  # pragma: no cover — pydantic always present in this codebase
    _PydTypeAdapter = None  # type: ignore


def _list_item_io_fields(v: Any) -> dict:
    """Copy list-item annotation fields from a dict or GenerationIOParam-like object."""
    if isinstance(v, dict):
        get = v.get
    else:
        get = lambda k, d=None: getattr(v, k, d)
    out = {}
    for key in ("itemSchema", "itemType", "scalarItemDatatype", "enumValues"):
        val = get(key)
        if val is not None:
            out[key] = val
    return out


def _io_data_type(v: Any) -> str:
    """Read dataType from GenerationIOParam / NodeParam / dump dict."""
    if isinstance(v, dict):
        return str(v.get("dataType") or v.get("datatype") or v.get("type") or "Any")
    return str(
        getattr(v, "dataType", None)
        or getattr(v, "datatype", None)
        or "Any"
    )


def _coerce_io_params(values: Any) -> list:
    """Best-effort coercion of a list of dicts/objects into list[GenerationIOParam].
    Falls back to lightweight dicts shaped like GenerationIOParam if pydantic
    cannot import. Always returns a list of objects with at least ``name``
    accessible (attr-style).
    """
    if not values:
        return []
    out = []
    for v in values:
        if isinstance(v, GenerationIOParam):
            out.append(v)
            continue
        if isinstance(v, dict):
            nm = (v.get("name") or "").strip()
            if not nm:
                continue
            out.append(GenerationIOParam(
                name=nm,
                dataType=_io_data_type(v),
                required=bool(v.get("required", False)),
                description=str(v.get("description") or ""),
                **_list_item_io_fields(v),
            ))
            continue
        # Object with .name (duck-typed GenerationIOParam-like)
        nm = getattr(v, "name", None)
        if isinstance(nm, str) and nm.strip():
            out.append(GenerationIOParam(
                name=nm.strip(),
                dataType=_io_data_type(v),
                required=bool(getattr(v, "required", False)),
                description=str(getattr(v, "description", "") or ""),
                **_list_item_io_fields(v),
            ))
        # else: silently drop — caller already validated generic-stripping
    return out


def _build_available_vars_for_pipeline(phase_graphs: list, global_inputs: list) -> Dict[str, Any]:
    """
    Build available variables dict for surgical editing context.
    """
    available_vars = {
        'globals': [{'name': g['name'], 'dataType': g.get('dataType', 'string')} for g in global_inputs],
        'nodeOutputs': []
    }

    for phase in phase_graphs:
        graph = phase.get('graph', {})
        for node in graph.get('nodes', []):
            outputs = node.get('config', {}).get('declaredOutputs', [])
            if outputs:
                available_vars['nodeOutputs'].append({
                    'nodeId': node['nodeId'],
                    'outputs': outputs
                })

    return available_vars


def _apply_edit_plans_to_phase_graphs(phase_graphs: list, plans: list, updated_node_ids: set, proposed_changes: dict):
    """
    Update phase_graphs with new schemas from surgical edit plans using proposed_changes dict.
    """
    def _merge_declared_outputs(existing: list, incoming: list) -> list:
        """Merge existing and incoming declaredOutputs, preserving existing field names.

        The LLM edit plan sometimes replaces the existing outputs with a generic
        ``formOutput`` placeholder when it can't enumerate every field. To keep
        the workflow's field-level contract intact, we treat the *existing*
        declaredOutputs as authoritative for any field name already present and
        only adopt genuinely new fields from the LLM plan.
        """
        if not existing:
            return list(incoming or [])
        if not incoming:
            return list(existing)
        existing_names = {
            (o.get('name') or '').strip(): o
            for o in existing if isinstance(o, dict) and o.get('name')
        }
        incoming_names = {
            (o.get('name') or '').strip(): o
            for o in incoming if isinstance(o, dict) and o.get('name')
        }
        merged = []
        for name, eo in existing_names.items():
            if name in incoming_names:
                # Same name — prefer the incoming entry's fields but fall back
                # to the existing description/type if incoming lacks them.
                ic = incoming_names[name]
                merged.append({
                    'name': name,
                    'dataType': ic.get('dataType') or eo.get('dataType') or 'Any',
                    'required': ic.get('required') if ic.get('required') is not None else eo.get('required', False),
                    'description': ic.get('description') or eo.get('description') or '',
                })
            else:
                # Existing field not in incoming plan — keep it untouched.
                merged.append(dict(eo))
        # Append any genuinely new fields from the incoming plan.
        for name, ic in incoming_names.items():
            if name not in existing_names:
                merged.append(dict(ic))
        # Drop generic placeholders (``formOutput`` etc.) once at least one real
        # field is present — keeps declaredOutputs tidy for users.
        return _strip_generic_declared_outputs(merged)

    for pg in phase_graphs:
        graph = pg.get('graph', {})
        nodes = graph.get('nodes', [])

        for node in nodes:
            node_id = node.get('nodeId')
            if node_id in updated_node_ids and node_id in proposed_changes:
                changes = proposed_changes[node_id]

                # Update declaredOutputs — merge with existing instead of replacing.
                # Critical for ui_screens: the Angular generator must emit a form
                # whose submission shape matches the workflow's declaredOutputs.
                # The LLM edit plan occasionally proposes ``formOutput`` and discards
                # the existing field names; merging keeps the per-field contract.
                if 'declaredOutputs' in changes:
                    cfg = node.setdefault('config', {})
                    existing_dos = cfg.get('declaredOutputs') or []
                    new_dos = _merge_declared_outputs(existing_dos, changes.get('declaredOutputs') or [])
                    cfg['declaredOutputs'] = new_dos

                    # Also update the IR schema's outputParameters to match the
                    # MERGED declaredOutputs (so Angular generator sees them too).
                    generation = cfg.get('generation') if isinstance(cfg.get('generation'), dict) else None
                    if generation:
                        if 'outputParameters' in generation:
                            generation['outputParameters'] = new_dos
                        if 'outputs' in generation:
                            generation['outputs'] = new_dos

                # Update inputBindings
                if 'inputBindings' in changes:
                    cfg = node.get('config')
                    if not isinstance(cfg, dict):
                        cfg = {}
                        node['config'] = cfg
                    cfg['inputBindings'] = changes['inputBindings']

                # Update generationDescription
                if 'generationDescription' in changes:
                    cfg = node.get('config')
                    if not isinstance(cfg, dict):
                        cfg = {}
                        node['config'] = cfg
                    cfg['generationDescription'] = changes['generationDescription']

                # Record this user-prompt as already-applied so a retry of the
                # integrated pipeline (Phase 1+2+3 retry loop) does NOT re-apply
                # the same change — prevents "add one more number" from snowballing
                # into "add three numbers" when validation makes us iterate 3 times.
                applied_prompts = changes.get('_update_request') if isinstance(changes, dict) else None
                if applied_prompts and isinstance(applied_prompts, str) and applied_prompts.strip():
                    cfg = node.setdefault('config', {})
                    bucket = cfg.get('_applied_update_prompts')
                    if not isinstance(bucket, list):
                        bucket = []
                    if applied_prompts not in bucket:
                        bucket.append(applied_prompts)
                    # Cap to last 10 prompts to avoid unbounded growth.
                    cfg['_applied_update_prompts'] = bucket[-10:]

    logger.info(f"[plan/update] Applied {len(updated_node_ids)} edit plans to phase graphs")


def _trigger_angular_updates_for_ui_screens(
    phase_graphs: list,
    updated_node_ids: set,
    plans: Optional[list] = None,
    proposed_changes: Optional[dict] = None,
    already_updated_screen_ids: Optional[set] = None,
):
    """
    For updated UI screen nodes, add their capability IDs to gap_generations
    so the Angular generator runs on them. Only queues downstream screens that
    actually depend on the changed outputs.

    The ``plans`` and ``proposed_changes`` arguments are optional so this helper
    remains safe for both older and newer call sites.
    """
    already_updated = already_updated_screen_ids or set()
    # Build adjacency list from edges
    for pg in phase_graphs:
        graph = pg.get('graph', {})
        nodes = graph.get('nodes', [])
        edges = graph.get('edges', [])

        # Build adjacency list
        adjacency = {}
        for edge in edges:
            src = edge.get('fromNode')
            dst = edge.get('to')
            if src and dst:
                if src not in adjacency:
                    adjacency[src] = []
                adjacency[src].append(dst)

        # Find all nodes that depend on updated nodes (transitive closure)
        affected_nodes = set()
        queue = list(updated_node_ids)
        while queue:
            current = queue.pop(0)
            if current in affected_nodes:
                continue
            affected_nodes.add(current)
            for neighbor in adjacency.get(current, []):
                queue.append(neighbor)

        # Only add UI screens that are actually affected
        for node_id in affected_nodes:
            # Find the node
            node = None
            for n in graph.get('nodes', []):
                if n.get('nodeId') == node_id:
                    node = n
                    break

            if node and node.get('type') == 'ui_screen':
                cap_ref = node.get('capabilityRef', {})
                cap_id = cap_ref.get('capabilityId', '') if isinstance(cap_ref, dict) else ''
                if cap_id and cap_id.startswith('ui:'):
                    # Skip screens already updated in integrated pipeline
                    # screen_bumps values are without 'ui:' prefix, so strip it for comparison
                    cap_id_stripped = cap_id[3:]  # remove 'ui:' prefix
                    if cap_id_stripped in already_updated:
                        logger.info(f"[plan/update] Skipping already-updated screen {cap_id} in gap_generations")
                        continue
                    existing = pg.get('gap_generations', [])
                    if cap_id not in existing:
                        pg['gap_generations'] = list(set(existing) | {cap_id})
                        logger.info(f"[plan/update] Added UI screen {cap_id} to gap_generations for Angular update")


async def _finalize_ui_screen_update(
    *,
    phase_graphs: list,
    node: Dict[str, Any],
    old_screen_id: str,
    result: Optional[Dict[str, Any]],
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
    project_id: str,
    bumped_map: Dict[str, str],
    all_warnings: List[str],
) -> None:
    """
    After `update_angular_screen_async` runs for a ui_screen affected by an UPDATE,
    finalize the workflow-graph side: rewrite `node.capabilityRef` to the new
    screen_id produced by Angular, and (defensively) refresh `node.config.declaredOutputs`
    from the latest IR schema so downstream gap resolution / LangGraph compile uses
    the freshly-generated shape.

    If `update_angular_screen_async` failed (or returned no new screen_id), fall
    back to cloning the latest `screen_generations` row into a fresh
    screen_id + new version — preserves per-version rollback safety even when
    Angular generation itself is unavailable on the deploy env.
    """
    cap_ref = node.get("capabilityRef") or {}
    if not isinstance(cap_ref, dict):
        cap_ref = {}
        node["capabilityRef"] = cap_ref

    new_screen_id = (result or {}).get("screen_id") if isinstance(result, dict) else None
    success_flag = bool((result or {}).get("success")) if isinstance(result, dict) else False
    skipped_flag = bool((result or {}).get("skipped")) if isinstance(result, dict) else False

    # DEBUG: Log actual result type and content to diagnose fallback issues
    logger.warning(
        f"[plan/update] _finalize_ui_screen_update DEBUG: old_screen_id={old_screen_id}, "
        f"result_type={type(result).__name__}, isinstance_dict={isinstance(result, dict)}, "
        f"new_screen_id={new_screen_id}, success_flag={success_flag}, skipped_flag={skipped_flag}, "
        f"result_keys={list((result or {}).keys()) if isinstance(result, dict) else 'N/A'}, "
        f"result_success={result.get('success') if isinstance(result, dict) else 'N/A'}, "
        f"result_screen_id={result.get('screen_id') if isinstance(result, dict) else 'N/A'}"
    )

    # Handle case where result might be an HTTPException or other non-dict
    if isinstance(result, Exception):
        logger.error(f"[plan/update] _finalize_ui_screen_update: result is Exception: {result}")
        result = {}
        success_flag = False
        new_screen_id = None

    if success_flag and skipped_flag:
        # Angular update was skipped (no affected files) - no new version created.
        # Keep the old screen_id, don't change capabilityRef.
        logger.info(f"[plan/update] Angular update skipped for {old_screen_id}, keeping existing capabilityRef")
        logger.debug(f"[plan/update] SKIPPED path: preserving dashboardUrl for {old_screen_id}, NOT creating new version")
        # Still update declaredOutputs from result's IR if available
        latest_screen_doc = None
        return
    elif success_flag and new_screen_id and new_screen_id != old_screen_id:
        # Angular generation succeeded and produced a fresh screen_id.
        logger.info(f"[plan/update] SUCCESS PATH: Angular update succeeded for {old_screen_id} → {new_screen_id}")
        new_cap_id = f"ui:{new_screen_id}"
        cap_ref["capabilityId"] = new_cap_id
        # Fetch the newly created screen document to get the authoritative IR schema
        # (which includes outputParameters inferred from the generated UI components).
        latest_screen_doc = None
        try:
            from repositories.screen_repository import ScreenRepository
            screen_repo = ScreenRepository()
            latest_screen_doc = await screen_repo.get_latest_screen_doc(project_id, new_screen_id)
            if latest_screen_doc and latest_screen_doc.get("version"):
                cap_ref["version"] = latest_screen_doc["version"]
        except Exception as _e:
            logger.debug(f"[plan/update] Could not refresh capabilityRef.version: {_e}")
        # ALSO sync declaredOutputs, stateWrites, etc. from result (like fallback does)
        # This ensures the node.config is updated even on success path
        try:
            result_ir = (result or {}).get("updated_ir_schema") or {}
            if result_ir.get("outputParameters"):
                cfg = node.get("config") or {}
                existing_dos = cfg.get("declaredOutputs") or []
                ir_outputs = result_ir["outputParameters"]
                existing_names = {o.get("name") for o in existing_dos if isinstance(o, dict) and o.get("name")}
                merged_outs = list(existing_dos)
                for ir_out in ir_outputs:
                    if isinstance(ir_out, dict) and ir_out.get("name") and ir_out["name"] not in existing_names:
                        merged_outs.append(ir_out)
                target_outs = _strip_generic_declared_outputs(merged_outs)
                if target_outs:
                    cfg["declaredOutputs"] = target_outs
                    node_id = node.get("nodeId", "")
                    auto_state_writes = [
                        f"{node_id}__{out.get('name')}"
                        for out in target_outs
                        if isinstance(out, dict) and out.get("name")
                    ]
                    existing_writes = cfg.get("stateWrites", []) or []
                    merged_writes = list(existing_writes)
                    for sw in auto_state_writes:
                        if sw not in merged_writes:
                            merged_writes.append(sw)
                    cfg["stateWrites"] = merged_writes
                    node["config"] = cfg
                    logger.info(f"[plan/update] SUCCESS PATH: Synced declaredOutputs/stateWrites from result IR")
        except Exception as _e:
            logger.warning(f"[plan/update] SUCCESS PATH: Failed to sync from result IR: {_e}")
        return
    else:
        # Fallback: use old screen_id
        latest_screen_doc = None

        # For UI screen updates, the screen document's IR schema is the authoritative
        # source of what the screen outputs (includes outputParameters inferred from
        # generated UI components). Always adopt outputParameters from the screen doc's IR,
        # falling back to existing declaredOutputs only if IR has none.
        # Then strip generic placeholders (formOutput/output/result) and sync stateWrites.
        try:
            # Use the screen document's IR schema (authoritative after generation)
            ir = (latest_screen_doc or {}).get("ir_schema") or {}
            # Also merge in result's updated_ir_schema if it has outputParameters (for cases
            # where screen doc hasn't been updated yet but result has the IR)
            result_ir = (result or {}).get("updated_ir_schema") or {}
            if result_ir.get("outputParameters"):
                ir = {**ir, "outputParameters": result_ir["outputParameters"]}

            cfg = node.get("config") or {}
            existing_dos = cfg.get("declaredOutputs") or []

            def _is_generic(d):
                if not isinstance(d, dict):
                    return True
                nm = (d.get("name") or "").strip()
                return not nm or nm in ("formOutput", "output", "result")

            # Use IR's outputParameters as source of truth for UI screen updates,
            # but MERGE with existing declaredOutputs to preserve any outputs that
            # were synced from impact report (e.g., new outputs like number_3) but
            # may not have been generated by Angular yet.
            ir_outputs = ir.get("outputParameters") or []
            # Merge: keep all existing declaredOutputs, add any new ones from IR
            existing_names = {o.get("name") for o in existing_dos if isinstance(o, dict) and o.get("name")}
            merged_outs = list(existing_dos)
            for ir_out in ir_outputs:
                if isinstance(ir_out, dict) and ir_out.get("name") and ir_out["name"] not in existing_names:
                    merged_outs.append(ir_out)
            # Drop generic placeholders (e.g. ``formOutput``) so users see only
            # the real field names in declaredOutputs. No-ops when there's nothing
            # real to keep.
            target_outs = _strip_generic_declared_outputs(merged_outs)

            if target_outs:
                cfg["declaredOutputs"] = target_outs
                node_id = node.get("nodeId", "")
                auto_state_writes = [
                    f"{node_id}__{out.get('name')}"
                    for out in target_outs
                    if isinstance(out, dict) and out.get("name")
                ]
                existing_writes = cfg.get("stateWrites", []) or []
                merged_writes = list(existing_writes)
                for sw in auto_state_writes:
                    if sw not in merged_writes:
                        merged_writes.append(sw)
                cfg["stateWrites"] = merged_writes
                node["config"] = cfg

            # Sync inputBindings and stateReads for downstream screens
            # The updated IR schema contains inputParameters reflecting upstream outputs
            try:
                ir_input_params = ir.get("inputParameters") or []
                result_ir = (result or {}).get("updated_ir_schema") or {}
                if result_ir.get("inputParameters"):
                    ir_input_params = result_ir["inputParameters"]

                logger.debug(
                    f"[plan/update] inputBindings sync: node_id={node_id}, "
                    f"ir_input_params={len(ir_input_params)}, "
                    f"ir_input_names={[p.get('name') for p in ir_input_params if isinstance(p, dict)]}"
                )

                if ir_input_params:
                    # Build inputBindings from IR inputParameters
                    # inputParameters are the upstream outputs this screen consumes
                    new_input_bindings = {}
                    # Find upstream node IDs that flow to this node (for proper binding format)
                    upstream_node_ids = []
                    for pg in phase_graphs:
                        graph = pg.get("graph", {})
                        edges = graph.get("edges", [])
                        for edge in edges:
                            if edge.get("to") == node_id:
                                upstream_node_ids.append(edge.get("fromNode"))

                    logger.debug(f"[plan/update] inputBindings sync: upstream_node_ids={upstream_node_ids}")

                    for param in ir_input_params:
                        if isinstance(param, dict) and param.get("name"):
                            param_name = param["name"]
                            # The binding source should reference the upstream node's output
                            # For downstream screens, use format: "{{upstreamNodeId.paramName}}"
                            # We preserve existing binding if it exists and is valid
                            existing_binding = cfg.get("inputBindings", {}).get(param_name)
                            if existing_binding and isinstance(existing_binding, str) and existing_binding.startswith("{{"):
                                new_input_bindings[param_name] = existing_binding
                                logger.debug(f"[plan/update] inputBindings sync: preserved existing binding for {param_name}={existing_binding}")
                            else:
                                # Find which upstream node provides this output
                                binding_source = param_name  # fallback
                                for up_id in upstream_node_ids:
                                    # Check if this upstream node has this output in its declaredOutputs
                                    for pg in phase_graphs:
                                        for n in pg.get("graph", {}).get("nodes", []):
                                            if n.get("nodeId") == up_id:
                                                up_declared = (n.get("config", {}) or {}).get("declaredOutputs", [])
                                                for out in up_declared:
                                                    if isinstance(out, dict) and out.get("name") == param_name:
                                                        binding_source = f"{{{{{up_id}.{param_name}}}}}"
                                                        break
                                                break
                                        if binding_source != param_name:
                                            break
                                new_input_bindings[param_name] = binding_source
                                logger.debug(f"[plan/update] inputBindings sync: new binding for {param_name}={binding_source} (upstream_ids={upstream_node_ids})")

                    if new_input_bindings:
                        cfg["inputBindings"] = new_input_bindings
                        # Sync stateReads from inputBindings (use downstream node_id format)
                        state_reads = [f"{node_id}__{name}" for name in new_input_bindings.keys()]
                        existing_reads = cfg.get("stateReads", []) or []
                        # Replace existing reads with clean ones (avoid duplicates from old format)
                        merged_reads = []
                        for sr in existing_reads:
                            # Keep only reads that match the current node_id prefix
                            if sr.startswith(f"{node_id}__"):
                                merged_reads.append(sr)
                        for sr in state_reads:
                            if sr not in merged_reads:
                                merged_reads.append(sr)
                        cfg["stateReads"] = merged_reads
                        node["config"] = cfg
                        logger.info(
                            f"[plan/update] Synced inputBindings for {node_id}: {new_input_bindings}"
                        )
                        logger.info(
                            f"[plan/update] Synced stateReads for {node_id}: {merged_reads}"
                        )
                        logger.debug(
                            f"[plan/update] inputBindings sync complete: "
                            f"inputBindings={new_input_bindings}, stateReads={merged_reads}"
                        )
            except Exception as _e:
                logger.debug(f"[plan/update] Could not sync inputBindings/stateReads: {_e}")
        except Exception as _e:
            logger.debug(f"[plan/update] Could not sync declaredOutputs: {_e}")

        # Persist intent fields to screen document after Angular regeneration.
        # IMPORTANT: Preserve generationDescription / intentDescription — do NOT replace
        # them with a generic I/O sentence derived from IR field names.
        # The original UX + domain intent written at scratch-planning time is the
        # authoritative generation prompt; overwriting it causes subsequent regenerations
        # to lose all feature-level requirements (profile cards, filters, etc.).
        try:
            if latest_screen_doc:
                from repositories.screen_repository import ScreenRepository
                screen_repo = ScreenRepository()
                cfg = node.get("config") or {}

                # Prefer intentDescription (immutable original) stored on the node config.
                # Fall back to generationDescription if intentDescription not yet captured.
                existing_gen_desc = _frozen_intent_description(cfg)
                if not existing_gen_desc:
                    existing_gen_desc = _best_intent_description(
                        latest_screen_doc.get("intentDescription"),
                        latest_screen_doc.get("generationDescription"),
                        (cfg.get("generation") or {}).get("description") if isinstance(cfg.get("generation"), dict) else None,
                    )
                _ensure_intent_description(cfg)

                metadata_to_persist: Dict[str, Any] = {}
                if existing_gen_desc:
                    metadata_to_persist["generationDescription"] = existing_gen_desc
                    frozen_intent = (cfg.get("intentDescription") or existing_gen_desc).strip()
                    if frozen_intent:
                        metadata_to_persist["intentDescription"] = frozen_intent
                        cfg["intentDescription"] = frozen_intent
                    metadata_to_persist["generation"] = latest_screen_doc.get("generation") or {}
                    logger.info(
                        f"[plan/update] Preserving original generationDescription for "
                        f"{new_screen_id} ({len(existing_gen_desc)} chars)."
                    )
                else:
                    # No description at all — leave it; do not insert a generic sentence.
                    logger.debug(
                        f"[plan/update] No generationDescription to persist for {new_screen_id}."
                    )

                # Always persist binding/output metadata regardless of description.
                for key in ("inputBindings", "stateReads", "declaredOutputs", "stateWrites"):
                    if key in cfg and cfg[key] is not None:
                        metadata_to_persist[key] = cfg[key]

                if metadata_to_persist:
                    await screen_repo.update_screen_metadata(
                        project_id,
                        new_screen_id,
                        metadata_to_persist,
                    )
                    logger.info(
                        f"[plan/update] Persisted metadata for {new_screen_id}: "
                        f"{sorted(metadata_to_persist.keys())}"
                    )
        except Exception as _e:
            logger.warning(f"[plan/update] Could not persist description metadata for {new_screen_id}: {_e}")

        bumped_map[old_screen_id] = new_screen_id
        logger.info(
            f"[plan/update] UI screen {old_screen_id} → {new_screen_id} via Angular generation."
        )
        return

    # ============================================================
    # CLONE FALLBACK (inside else block)
    # Clone the current screen_generations row into a fresh screen_id so
    # per-version rollback is still safe. This DOES NOT regenerate Angular content;
    # it only creates a new immutable generation row.
    # ============================================================
    try:
        from repositories.screen_repository import ScreenRepository
        screen_repo = ScreenRepository()
        latest_doc = await screen_repo.get_latest_screen_doc(project_id, old_screen_id)
    except Exception as _e:
        latest_doc = None
        logger.warning(f"[plan/update] Screen fallback clone failed to load doc: {_e}")

    if not latest_doc:
        all_warnings.append(
            f"[Screens] Skipped bump for {old_screen_id}: no source doc and Angular "
            f"update did not produce a result."
        )
        return

    new_version = datetime.utcnow().strftime("%Y%m%d%H%M%S")
    fallback_screen_id = f"screen_{new_version}_{uuid.uuid4().hex[:8]}"
    new_cap_id = f"ui:{fallback_screen_id}"
    clone = dict(latest_doc)
    clone.pop("_id", None)
    clone["prompt"] = (
        f"[auto] Workflow update fallback — Angular generation unavailable. "
        f"Cloned from {old_screen_id} (workflow version bump)."
    )
    # Sync updated declaredOutputs and generationDescription from node.config
    # (which already reflects the proposed_changes)
    node_cfg = node.get("config", {})
    # Strip generic placeholders (formOutput/output/result) once at the source so
    # neither declaredOutputs nor the auto-derived stateWrites include them.
    declared_outputs = _strip_generic_declared_outputs(node_cfg.get("declaredOutputs") or [])
    # Fallback safety net: supplement from regenerationDescription / _update_request
    try:
        _gen_desc_fb = node_cfg.get("generationDescription") or ""
        _user_prompt_fb = node_cfg.get("_update_request") or ""
        _combined_source_fb = _gen_desc_fb + (
            ("\n\n" + _user_prompt_fb) if _user_prompt_fb else ""
        )
    except Exception as _fb_supp_err:
        logger.warning(
            f"[plan/update] Fallback supplementer skipped: {_fb_supp_err}"
        )
    if declared_outputs:
        node_cfg["declaredOutputs"] = declared_outputs
        clone["declaredOutputs"] = declared_outputs
        logger.info(f"[plan/update] Fallback clone synced declaredOutputs for {fallback_screen_id}: {[o.get('name') for o in declared_outputs]}")
        # Also sync stateWrites from node.config or auto-generate
        node_id = node.get("nodeId", "")
        auto_state_writes = [f"{node_id}__{out.get('name')}" for out in declared_outputs if out.get("name")]
        existing_writes = node_cfg.get("stateWrites", [])
        merged_writes = list(existing_writes)
        for sw in auto_state_writes:
            if sw not in merged_writes:
                merged_writes.append(sw)
        node_cfg["stateWrites"] = merged_writes
        node["config"] = node_cfg
        logger.info(f"[plan/update] Fallback clone synced stateWrites for {fallback_screen_id}: {merged_writes}")
    if node_cfg.get("generationDescription"):
        clone["generationDescription"] = node_cfg["generationDescription"]
        if "generation" not in clone or not isinstance(clone.get("generation"), dict):
            clone["generation"] = {}
        clone["generation"]["description"] = node_cfg["generationDescription"]
        logger.info(f"[plan/update] Fallback clone synced generationDescription for {fallback_screen_id}")
    if node_cfg.get("intentDescription"):
        clone["intentDescription"] = node_cfg["intentDescription"]

    # Also sync inputBindings and stateReads from node.config (critical for downstream screens)
    for key in ("inputBindings", "stateReads"):
        if key in node_cfg and node_cfg[key] is not None:
            clone[key] = node_cfg[key]
            logger.info(f"[plan/update] Fallback clone synced {key} for {fallback_screen_id}: {node_cfg[key]}")
    try:
        await screen_repo.insert_screen_version_doc(
            project_id,
            fallback_screen_id,
            new_version,
            "v1",
            clone,
            build_status="success",
            is_stable=True,
        )
        await screen_repo.update_screens_pointer(
            project_id,
            fallback_screen_id,
            new_version,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )
    except Exception as _e:
        all_warnings.append(f"[Screens] Fallback clone failed for {old_screen_id}: {_e}")
        return

    cap_ref["capabilityId"] = new_cap_id
    cap_ref["version"] = new_version
    node["capabilityRef"] = cap_ref
    bumped_map[old_screen_id] = fallback_screen_id
    logger.info(
        f"[plan/update] UI screen {old_screen_id} → {fallback_screen_id} via fallback clone."
    )
    return


async def _regenerate_downstream_ui_screen(
    *,
    downstream_node: Dict[str, Any],
    phase_graphs: list,
    updated_node_ids: set,
    proposed_changes: Dict[str, Dict[str, Any]],
    impact_report,
    project_id: str,
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
    all_warnings: list,
    screen_bumps: Dict[str, str],
) -> None:
    """
    Regenerate a downstream UI screen that was impacted by upstream changes.

    Unlike direct UPDATEs where the user provides a prompt, downstream screens
    need to update their INPUT BINDINGS to match the upstream's new outputs.
    The screen's own UI structure (fields, layout) stays the same — only the
    data contract (what inputs it receives) changes.

    This is called after the integrated pipeline succeeds and the upstream
    screen has been regenerated with new outputs.
    """
    from repositories.screen_repository import ScreenRepository
    import json

    node_id = downstream_node.get("nodeId", "")
    node_name = downstream_node.get("name", "Unknown Screen")

    # Get the current screen_id from capabilityRef
    cap_ref = downstream_node.get("capabilityRef") or {}
    old_cap_id = cap_ref.get("capabilityId", "") if isinstance(cap_ref, dict) else ""
    if not old_cap_id or not old_cap_id.startswith("ui:"):
        logger.warning(f"[plan/update] Downstream UI screen {node_id} has no valid capabilityRef")
        return
    old_screen_id = old_cap_id[3:]

    logger.debug(
        f"[plan/update] _regenerate_downstream_ui_screen START: "
        f"node_id={node_id}, node_name={node_name}, old_screen_id={old_screen_id}, "
        f"updated_node_ids={list(updated_node_ids)}, proposed_changes_keys={list(proposed_changes.keys())}"
    )

    # Build the gen_prompt for downstream screen regeneration
    # The prompt tells Angular generator: "Update input bindings to match upstream changes"
    # but preserve the existing UI structure
    config = downstream_node.get("config", {})
    gen_spec = config.get("generation") or {}  # Defensive: ensure dict, not None

    # Get the upstream changes that affect this downstream node
    upstream_changes = []
    for upstream_id in updated_node_ids:
        # Check if this upstream node flows to our downstream node
        for pg in phase_graphs:
            graph = pg.get("graph", {})
            edges = graph.get("edges", [])
            for edge in edges:
                if edge.get("fromNode") == upstream_id and edge.get("to") == node_id:
                    upstream_changes.append(upstream_id)
                    break

    logger.debug(f"[plan/update] _regenerate_downstream_ui_screen: upstream_changes={upstream_changes}")

    # Build description of what changed upstream
    upstream_desc = ""
    if upstream_changes:
        upstream_names = []
        for up_id in upstream_changes:
            up_node = None
            for pg in phase_graphs:
                for n in pg.get("graph", {}).get("nodes", []):
                    if n.get("nodeId") == up_id:
                        up_node = n
                        break
                if up_node:
                    break
            if up_node:
                upstream_names.append(up_node.get("name", up_id))

        # Get UPDATED outputs from upstream (after integrated pipeline has run)
        # The upstream nodes in phase_graphs have been updated with new declaredOutputs
        upstream_outputs_info = []
        for up_id in upstream_changes:
            # Find the upstream node in phase_graphs to get its UPDATED declaredOutputs
            up_node = None
            for pg in phase_graphs:
                for n in pg.get("graph", {}).get("nodes", []):
                    if n.get("nodeId") == up_id:
                        up_node = n
                        break
                if up_node:
                    break

            # Use the UPDATED declaredOutputs from the node's config (after pipeline)
            declared_outputs = []
            if up_node:
                declared_outputs = (up_node.get("config", {}) or {}).get("declaredOutputs", [])

            # Fallback to proposed_changes if node not found or no declaredOutputs
            if not declared_outputs:
                up_proposed = proposed_changes.get(up_id, {})
                declared_outputs = up_proposed.get("declaredOutputs", [])

            logger.info(
                f"[plan/update] _regenerate_downstream_ui_screen: up_id={up_id}, "
                f"declared_outputs_from_config={len(declared_outputs)}, "
                f"declared_outputs_names={[o.get('name') for o in declared_outputs if isinstance(o, dict)]}, "
                f"config_keys={list((up_node.get('config', {}) or {}).keys()) if up_node else 'NO_NODE'}"
            )

            for out in declared_outputs:
                if isinstance(out, dict) and out.get("name"):
                    upstream_outputs_info.append(f"{out['name']} ({out.get('dataType', 'any')})")

        upstream_desc = (
            f"UPSTREAM CHANGES (adapt input bindings to match):\n"
            f"Upstream screens updated: {', '.join(upstream_names)}\n"
            f"New/changed outputs available: {', '.join(upstream_outputs_info) or 'none specified'}\n\n"
        )

        logger.debug(f"[plan/update] _regenerate_downstream_ui_screen: upstream_desc built: {upstream_desc[:200]}")

    # Build NEW inputParameters from upstream's UPDATED declaredOutputs
    # This is the key fix: downstream screens must consume upstream's NEW outputs
    new_input_parameters = []
    if upstream_changes:
        for up_id in upstream_changes:
            # Find the upstream node in phase_graphs to get its UPDATED declaredOutputs
            up_node = None
            for pg in phase_graphs:
                for n in pg.get("graph", {}).get("nodes", []):
                    if n.get("nodeId") == up_id:
                        up_node = n
                        break
                if up_node:
                    break

            # Use the UPDATED declaredOutputs from the node's config (after pipeline)
            declared_outputs = []
            if up_node:
                declared_outputs = (up_node.get("config", {}) or {}).get("declaredOutputs", [])

            # Fallback to proposed_changes if node not found or no declaredOutputs
            if not declared_outputs:
                up_proposed = proposed_changes.get(up_id, {})
                declared_outputs = up_proposed.get("declaredOutputs", [])

            logger.info(
                f"[plan/update] _regenerate_downstream_ui_screen (inputs): up_id={up_id}, "
                f"declared_outputs={len(declared_outputs)}, "
                f"names={[o.get('name') for o in declared_outputs if isinstance(o, dict)]}, "
                f"up_node_config_keys={list((up_node.get('config', {}) or {}).keys()) if up_node else 'NO_NODE'}"
            )

            for out in declared_outputs:
                if isinstance(out, dict) and out.get("name"):
                    new_input_parameters.append({
                        "name": out["name"],
                        "dataType": out.get("dataType", "any"),
                        "required": True,
                        "description": f"Input from upstream {up_id}",
                    })

    # Also preserve any existing inputs that are not from upstream (e.g., global inputs)
    # But typically all inputs should come from upstream in a workflow
    existing_inputs = gen_spec.get("inputs", []) if gen_spec else []
    existing_input_names = {p.get("name") for p in existing_inputs if p.get("name")}
    for existing in existing_inputs:
        if existing.get("name") not in {p["name"] for p in new_input_parameters}:
            new_input_parameters.append(existing)

    # Update the downstream node's config with the NEW input parameters
    # This ensures the IR schema will have the updated inputParameters
    # Use safe dict access - handle case where config/generation might be None
    cfg = downstream_node.get("config")
    if not isinstance(cfg, dict):
        cfg = {}
        downstream_node["config"] = cfg
    gen = cfg.get("generation")
    if not isinstance(gen, dict):
        gen = {}
        cfg["generation"] = gen
    gen["inputs"] = new_input_parameters

    # ALSO update inputBindings - this is what _resolve_one_gap_node uses for sync
    new_input_bindings = {}
    for inp in new_input_parameters:
        # Find the upstream node ID for proper binding format {{upstreamNodeId.paramName}}
        for up_id in upstream_changes:
            # Check if this input comes from this upstream
            up_node = None
            for pg in phase_graphs:
                for n in pg.get("graph", {}).get("nodes", []):
                    if n.get("nodeId") == up_id:
                        up_node = n
                        break
                if up_node:
                    break
            if up_node:
                declared_outputs = (up_node.get("config", {}) or {}).get("declaredOutputs", [])
                for out in declared_outputs:
                    if isinstance(out, dict) and out.get("name") == inp.get("name"):
                        new_input_bindings[inp["name"]] = f"{{{{{up_id}.{inp['name']}}}}}"
                        break
    cfg["inputBindings"] = new_input_bindings
    logger.info(f"[plan/update] Updated inputBindings for downstream {node_id}: {new_input_bindings}")

    # Sync stateReads from inputBindings (use downstream node_id format)
    state_reads = [f"{node_id}__{name}" for name in new_input_bindings.keys()]
    existing_reads = cfg.get("stateReads", []) or []
    # Replace existing reads with clean ones (avoid duplicates from old format)
    merged_reads = []
    for sr in existing_reads:
        # Keep only reads that match the current node_id prefix
        if sr.startswith(f"{node_id}__"):
            merged_reads.append(sr)
    for sr in state_reads:
        if sr not in merged_reads:
            merged_reads.append(sr)
    cfg["stateReads"] = merged_reads
    logger.info(f"[plan/update] Synced stateReads for downstream {node_id}: {merged_reads}")

    # Helper function to convert params to I/O format
    def _io_params(params: list) -> list:
        out = []
        for p in (params or []):
            out.append({
                "name": p.get("name", ""),
                "dataType": p.get("dataType") or p.get("datatype") or "Any",
                "required": bool(p.get("required", False)),
                "description": p.get("description", "") or "",
                **_list_item_io_fields(p),
            })
        return out

    # Build I/O contract from GenerationSpec (now with updated inputs)
    # Also update outputParameters to pass through NEW upstream outputs
    # Downstream screens should declare all upstream outputs as their own outputs
    existing_outputs = gen_spec.get("outputs", []) if gen_spec else []
    existing_output_names = {p.get("name") for p in existing_outputs if p.get("name")}

    logger.debug(
        f"[plan/update] Downstream output pass-through: node={node_id}, "
        f"existing_outputs={len(existing_outputs)}, "
        f"existing_names={list(existing_output_names)}, "
        f"new_input_parameters={len(new_input_parameters)}, "
        f"new_input_names={[p.get('name') for p in new_input_parameters if p.get('name')]}"
    )

    # Add new upstream outputs that aren't already in existing outputs
    new_outputs = []
    for inp in new_input_parameters:
        if inp.get("name") not in existing_output_names:
            new_outputs.append({
                "name": inp["name"],
                "dataType": inp.get("dataType") or inp.get("datatype") or "any",
                "required": inp.get("required", False),
                "description": f"Pass-through from upstream: {inp.get('description', '')}",
                **_list_item_io_fields(inp),
            })

    all_outputs = existing_outputs + new_outputs

    # CRITICAL: Also update declaredOutputs so _resolve_one_gap_node syncs correct outputs
    # Downstream screens must pass through upstream outputs as their own declaredOutputs
    cfg["declaredOutputs"] = all_outputs
    logger.info(f"[plan/update] Updated declaredOutputs for downstream {node_id}: {[o.get('name') for o in all_outputs]}")

    logger.info(
        f"[plan/update] Downstream output pass-through RESULT: node={node_id}, "
        f"existing_outputs={len(existing_outputs)}, "
        f"new_outputs_added={len(new_outputs)}, "
        f"all_outputs_total={len(all_outputs)}, "
        f"all_output_names={[o.get('name') for o in all_outputs if o.get('name')]}"
    )

    # Preserve original generationDescription for downstream screen — do NOT replace with
    # a generic I/O sentence.  The original description encodes UX and domain intent that
    # the user specified; replacing it with field-name lists causes intent degradation.
    # Capture it into intentDescription for future-proof immutability.
    try:
        existing_gen_desc = _ensure_intent_description(cfg)
        if existing_gen_desc:
            logger.info(
                f"[plan/update] Preserved original generationDescription for downstream "
                f"{node_id} ({len(existing_gen_desc)} chars)."
            )
        # If there is truly no description yet, leave it empty — the generator will
        # receive the typed I/O contract block and can infer minimal context from it.
        # Do NOT insert a generic 'receives … produces …' sentence.
    except Exception as _desc_err:
        logger.warning(
            f"[plan/update] Failed to preserve generationDescription for downstream "
            f"{node_id}: {_desc_err}"
        )

    prev_screen_desc = _frozen_intent_description(cfg) or (gen_spec.get("description") or "").strip() if gen_spec else _frozen_intent_description(cfg)
    if gen_spec and gen_spec.get("outputs"):
        io_rows = {
            "inputParameters": _io_params(new_input_parameters),  # Use NEW inputs
            "outputParameters": _io_params(all_outputs),  # Include NEW upstream outputs
        }
        gen_prompt = (
            f"{upstream_desc}"
            f"INSTRUCTION: This is a DOWNSTREAM screen affected by upstream changes.\n"
            f"Preserve the existing UI layout, fields, and visual structure exactly.\n"
            f"Only update INPUT BINDINGS to consume the new/changed upstream outputs.\n"
            f"Also declare the new upstream outputs as this screen's outputs (pass-through).\n"
            f"Do NOT add/remove/change UI components unless explicitly required.\n\n"
            f"PREVIOUS SCREEN DESCRIPTION (context):\n"
            f"{prev_screen_desc}\n\n"
            f"{WORKFLOW_IO_CONTRACT_SCREEN_MARKER}\n"
            f"{json.dumps(io_rows, indent=2)}\n\n"
            f"{_NO_GENERIC_OUTPUTS_CONSTRAINT}\n\n"
            f"UI CHROME PROHIBITION (HARD CONSTRAINT):\n"
            f"- Do NOT introduce new page-level headings, titles, breadcrumbs, or section dividers.\n"
            f"- Preserve existing component scaffold, layout, Tailwind classes, div nesting exactly.\n"
            f"- Minimal surgical changes only — update bindings, do NOT restructure."
        ).strip()
    else:
        # Fallback if no generation spec
        io_rows = {
            "inputParameters": _io_params(new_input_parameters) if new_input_parameters else [],
            "outputParameters": _io_params(all_outputs),
        }
        gen_prompt = (
            f"{upstream_desc}"
            f"INSTRUCTION: This is a DOWNSTREAM screen affected by upstream changes.\n"
            f"Update input bindings to consume new upstream outputs.\n"
            f"Also declare the new upstream outputs as this screen's outputs (pass-through).\n"
            f"Preserve existing UI structure exactly.\n\n"
            f"{WORKFLOW_IO_CONTRACT_SCREEN_MARKER}\n"
            f"{json.dumps(io_rows, indent=2)}\n\n"
            f"{_NO_GENERIC_OUTPUTS_CONSTRAINT}\n\n"
            f"UI CHROME PROHIBITION (HARD CONSTRAINT):\n"
            f"- Do NOT introduce new page-level headings, titles, breadcrumbs, or section dividers.\n"
            f"- Preserve existing component scaffold, layout, Tailwind classes, div nesting exactly.\n"
            f"- Minimal surgical changes only — update bindings, do NOT restructure."
        ).strip()

    # NOTE: We do NOT call update_angular_screen_async here.
    # The downstream screen will be added to gap_generations by _trigger_angular_updates_for_ui_screens
    # and processed by the gap resolution pipeline, which will call update_angular_screen_async
    # with the UPDATED config (including the new inputBindings from upstream declaredOutputs).
    # This avoids double-processing and ensures the Angular generator sees the correct inputs.

    logger.info(
        f"[plan/update] _regenerate_downstream_ui_screen: Updated config for downstream {node_id} "
        f"(Angular update will be handled by gap resolution). "
        f"inputs={[p.get('name') for p in new_input_parameters]}, "
        f"outputs={[o.get('name') for o in all_outputs]}, "
        f"inputBindings={cfg.get('inputBindings', {})}"
    )

    logger.info(f"[plan/update] Downstream UI screen {node_name} ({old_screen_id}) config updated for input binding updates")


async def _bump_screen_version_for_workflow_update(
    phase_graphs: list,
    updated_node_ids: set,
    *,
    project_id: str,
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
) -> Dict[str, str]:
    """
    Force-create a NEW screen_generations row under a NEW screen_id for every
    `ui_screen` node in `updated_node_ids`.

    Why this exists
    ---------------
    The legacy pipeline always produced a new screen capability per workflow
    version, so each `Workflow_Versions` snapshot pinned a distinct
    `capabilityId` and `/plan/restore` could safely switch to the older one.

    The integrated pipeline (Phase 2) only re-runs Angular generation when the
    LLM-driven diff produces real content change. When the diff is empty (e.g.
    "make it accept one more number" when it already does), the node's
    `capabilityRef.capabilityId` is unchanged → restore-to-older-version would
    land on the same row as the latest, silently breaking per-version rollback.

    This helper closes the gap by cloning the latest `screen_generations` row
    of each affected ui_screen under a fresh screen_id + fresh version, then
    rewriting the workflow graph's `phaseGraphs[*].nodes[*].capabilityRef` to
    point at it, then shifting `screens.current_version` to the new row. The
    next snapshot capture (in /plan/update) will then store
    `screen_version_mapping[screen_id] = new_version` for the new screen_id,
    making the legacy rollback guarantee hold.

    Returns
    -------
    A dict mapping the *old* screen_id → *new* screen_id for every ui_screen
    we bumped. Caller may use this for logging / audit.
    """
    bumped: Dict[str, str] = {}
    if not updated_node_ids:
        return bumped

    try:
        from repositories.screen_repository import ScreenRepository
        screen_repo = ScreenRepository()
    except Exception as _import_err:
        logger.warning(
            f"[plan/update] Could not import ScreenRepository for screen-version bump: {_import_err}"
        )
        return bumped

    for pg in phase_graphs:
        graph = pg.get("graph") or {}
        nodes = graph.get("nodes") or []
        for node in nodes:
            if node.get("nodeId") not in updated_node_ids:
                continue
            if node.get("type") != "ui_screen":
                continue

            cap_ref = node.get("capabilityRef") or {}
            old_cap_id = cap_ref.get("capabilityId") if isinstance(cap_ref, dict) else ""
            if not old_cap_id or not old_cap_id.startswith("ui:"):
                continue
            old_screen_id = old_cap_id[3:]

            try:
                latest_doc = await screen_repo.get_latest_screen_doc(project_id, old_screen_id)
                if not latest_doc:
                    logger.warning(
                        f"[plan/update] Bump skipped — screen {old_screen_id} has no doc to clone."
                    )
                    continue

                # New identifiers
                new_version = datetime.utcnow().strftime("%Y%m%d%H%M%S")
                new_screen_id = f"screen_{new_version}_{uuid.uuid4().hex[:8]}"
                new_cap_id = f"ui:{new_screen_id}"

                # Determine the next version_label (e.g. v3 → v4 → v5 ...)
                try:
                    existing_versions = await screen_repo.count_versions(project_id, old_screen_id)
                except Exception:
                    existing_versions = 0
                # For a brand-new screen_id we'll just start at v1; it's an unrelated
                # artifact family under the cap_id rename.
                new_version_label = "v1"

                # Build the clone payload (do not carry _id forward)
                clone = dict(latest_doc)
                clone.pop("_id", None)
                clone["prompt"] = (
                    f"[auto] Workflow update bump — screen content unchanged. "
                    f"Cloned from {old_screen_id} (workflow version bump)."
                )
                clone["screen_name"] = clone.get("screen_name") or node.get("name") or old_screen_id

                await screen_repo.insert_screen_version_doc(
                    project_id,
                    new_screen_id,
                    new_version,
                    new_version_label,
                    clone,
                    build_status="success",
                    is_stable=True,
                )
                # Re-point screens.current_version to the new row
                await screen_repo.update_screens_pointer(
                    project_id,
                    new_screen_id,
                    new_version,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                )

                # Rewrite the workflow graph node in-place so downstream
                # gap-resolution / LangGraph compile sees the new capabilityId.
                cap_ref["capabilityId"] = new_cap_id
                cap_ref["version"] = new_version
                node["capabilityRef"] = cap_ref

                bumped[old_screen_id] = new_screen_id
                logger.info(
                    f"[plan/update] Bumped ui_screen {old_screen_id} → {new_screen_id} "
                    f"(version={new_version}) for workflow version independence."
                )
            except Exception as _sr_err:
                # Don't fail the whole update — just log and continue.
                logger.warning(
                    f"[plan/update] Screen-version bump failed for {old_screen_id}: {_sr_err}"
                )

    return bumped


import atexit
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s - %(message)s",
)
logger = logging.getLogger(__name__)

class JobManager:
    def __init__(self):
        self.active_jobs: Dict[str, asyncio.Queue] = {}

    def create_job(self) -> str:
        job_id = f"job_{uuid.uuid4().hex[:8]}"
        self.active_jobs[job_id] = asyncio.Queue()
        return job_id

    def get_queue(self, job_id: str) -> Optional[asyncio.Queue]:
        return self.active_jobs.get(job_id)

    def cleanup_job(self, job_id: str):
        if job_id in self.active_jobs:
            del self.active_jobs[job_id]

# Initialize global instance
job_manager = JobManager()
capability_repository = CapabilityRepository()

async def background_generator_task(job_id: str, generator_func, *args, **kwargs):
    """
    Wraps the heavy generation logic. Captures logs/retries and pushes them to the queue.
    Finally pushes the 'complete' event with the result payload.
    """
    queue = job_manager.get_queue(job_id)
    if not queue:
        return

    # Define the callback we will inject into the generator services
    async def progress_callback(level: str, message: str, details: Any = None):
        event_type = "log"
        if level == "RETRY":
            event_type = "retry"
        elif level == "ERROR":
            event_type = "error"
        elif level == "WARNING":
            event_type = "warning"
        
        await queue.put({
            "type": event_type,
            "message": message,
            "details": details
        })
        await asyncio.sleep(0.01)

    try:
        # Inject the callback into kwargs so the generator can use it
        kwargs['progress_callback'] = progress_callback
        
        # Run the actual heavy logic
        result = await generator_func(*args, **kwargs)
        
        # Success! Send the payload (The Final JSON)
        await queue.put({
            "type": "complete",
            "payload": result
        })
    except BillingError as exc:
        logger.error(f"Job {job_id} billing failed: {exc}")
        await queue.put({
            "type": "error",
            "message": str(exc),
            "code": exc.code,
        })
    except Exception as e:
        logger.error(f"Job {job_id} failed: {e}")
        traceback.print_exc()
        await queue.put({
            "type": "error",
            "message": str(e)
        })
    finally:
        # Signal stream to close
        await queue.put(None)

async def handle_editor_llm_call(messages):
    """
    Helper function to run LLM calls requested by the editor.py.
    This runs inside agent_new.py, so it has access to the authenticated 'llm' object.
    It runs the blocking LLM call in a thread to keep the async loop responsive.
    """
    loop = asyncio.get_running_loop()
    started_at = datetime.utcnow()
    # Execute the synchronous llm.call in a separate thread
    response = await loop.run_in_executor(None, lambda: llm.call(messages))
    finished_at = datetime.utcnow()
    prompt_str = str(messages) if not isinstance(messages, str) else messages
    response_str = str(response) if response else ""
    record_llm_call(
        org_id=None,
        subscriber_id=None,
        operation="editor",
        sub_operation="llm-call",
        model="gemini-3-flash-preview",
        prompt_tokens=len(prompt_str) // 4,
        completion_tokens=len(response_str) // 4,
        total_tokens=len(prompt_str) // 4 + len(response_str) // 4,
        status="success",
        started_at=started_at,
        finished_at=finished_at,
        metadata={},
    )
    return response

async def run_sync(func, *args, **kwargs):

    loop = asyncio.get_running_loop()
    # functools.partial handles kwargs which run_in_executor doesn't support natively
    pfunc = functools.partial(func, *args, **kwargs)
    return await loop.run_in_executor(None, pfunc)

async def async_llm_call(prompt):
    """Non-blocking wrapper for llm.call"""
    from services.workflow_budget_service import check_before_llm_call

    check_before_llm_call()
    return await run_sync(llm.call, prompt)

@asynccontextmanager
async def lifespan(app: FastAPI):
    """
    FastAPI lifespan event handler for startup and shutdown.
    """
    # Startup: Initialize database and reload functions
    print("🚀 Starting AI Screen Builder API...")
    print("🔖 DEPLOYED CODE VERSION: 2026-08-20-early-return-fix-v2")

    # Set DB env from config so sandbox subprocesses inherit (for subscriber DB isolation)
    os.environ.setdefault("MONGODB_URI", config.get("devDbLink", ""))
    os.environ.setdefault("MONGODB_DB_NAME", config.get("devDb", ""))

    try:
        loop = asyncio.get_running_loop()
        loop.set_default_executor(ThreadPoolExecutor(max_workers=100))
        print("🚀 Thread pool size set to 100 for high concurrency.")
    except Exception as e:
        print(f"⚠️ Failed to set thread pool size: {e}")
    
    # Connect to database
    Database.connect_db()
    
    # Create indexes for repositories
    await screen_repository.create_indexes()
    await function_repository.create_indexes()
    try:
        capability_repo = CapabilityRepository()
        await capability_repo.create_indexes()
        print("CapabilityRepository indexes created")
    except Exception as e:
        print(f"⚠️ Failed to create capability indexes: {e}")

    cred_svc = CredentialService.optional()
    if cred_svc:
        await cred_svc.create_indexes()
        print("CredentialService indexes created")

    try:
        await stage0_session_manager.create_indexes()
        print("Stage0SessionManager indexes created")
    except Exception as e:
        print(f"⚠️ Failed to create stage0_sessions indexes: {e}")
    
    try:
        ensure_checkpoint_indexes(db)
        print("workflow_build_checkpoints indexes created")
    except Exception as e:
        print(f"⚠️ Failed to create workflow_build_checkpoints indexes: {e}")

    if ensure_job_indexes is not None:
        try:
            ensure_job_indexes(db)
            print("workflow_build_jobs indexes created")
        except Exception as e:
            print(f"⚠️ Failed to create workflow_build_jobs indexes: {e}")

    # Reload all persisted backend functions into runtime cache
    print("Reloading persisted backend functions...")
    reload_results = await backend_generator.reload_all_functions()
    total_functions = sum(reload_results.values())
    print(f"Reloaded {total_functions} functions across {len(reload_results)} projects")

    # Initialize non-restrictive sandbox function worker pool
    print("Initializing sandbox function worker pool...")
    function_worker_pool = get_function_worker_pool()
    await function_worker_pool.initialize()
    print(f"Sandbox function worker pool initialized (size: {function_worker_pool.pool_size})")
    print("✅ Application started, database connected")
    
    yield  # Application runs here
    
    # Shutdown: Clean up resources
    print("🔄 Shutting down AI Screen Builder API...")
    Database.close_db()
    print("✅ Application shutdown, database closed")

