async def _fire_vr_load(project_id: str, subscriber_id: Optional[str], target_collections: List[str]) -> None:
    """
    Fire-and-forget notification to the VR service that fresh Process_Configs
    data is available to load for this project.

    Best-effort only: never raises, never blocks the caller. Intended to be
    scheduled via asyncio.create_task(...) immediately after a successful
    Process_Configs upsert in /agentic/plan/scratch/preview.
    """
    if not chat_base_url:
        logger.warning(
            "[vr/load] Skipped for project_id=%s — chat_base_url not configured in config.json",
            project_id,
        )
        return
    url = f"{chat_base_url.rstrip('/')}/vr/load"
    payload = {
        "project_id": project_id,
        "subscriber_id": subscriber_id,
        "target_collections": target_collections or [],
    }
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.post(url, json=payload)
        if resp.status_code >= 400:
            logger.warning(
                "[vr/load] Non-2xx response for project_id=%s subscriber_id=%s: "
                "status=%s body=%s",
                project_id, subscriber_id, resp.status_code, resp.text[:500],
            )
        else:
            logger.info(
                "[vr/load] OK project_id=%s subscriber_id=%s target_collections=%s status=%s",
                project_id, subscriber_id, target_collections, resp.status_code,
            )
    except Exception as exc:
        logger.warning(
            "[vr/load] Failed (non-fatal) for project_id=%s subscriber_id=%s: %s",
            project_id, subscriber_id, exc,
        )


