def _subscriber_id_from_project_id(project_id: str):
    """Resolve subscriber_id from project_id.

    Primary lookup: Query process_configs collection using project_id.
    Fallback: Parse from string convention ``<project_prefix>_sb_<subscriber_id>``.
    """
    if not project_id:
        return None

    # 1. Check process_configs collection first
    try:
        doc = db[PROCESS_CONFIGS_COLLECTION].find_one({
            "$or": [
                {"agentic_process.projectId": project_id},
                {"agentic_process.workflow_id": project_id}
            ]
        })
        if doc and doc.get("subscriberId"):
            return str(doc["subscriberId"]).strip()
    except Exception as e:
        logger.warning(f"Failed to query process_configs for subscriberId: {e}")

    # 2. Legacy fallback: parse from string
    separator = None
    if "_sb_" in project_id:
        separator = "_sb_"
    elif "-sb-" in project_id:
        separator = "-sb-"
    if not separator:
        return None
    parts = project_id.rsplit(separator, 1)
    if len(parts) != 2 or not (parts[1] or "").strip():
        return None
    return (parts[1] or "").strip()


def _routing_project_id_for_execute(path_project_id: str, payload: Dict[str, Any]) -> str:
    """Pick project_id used for registry lookup and subscriber DB routing.

    Subscriber id is parsed from ``<prefix>_sb_<subscriber_id>``. The URL path param is
    authoritative when it contains ``_sb_``; otherwise fall back to ``payload.project_id``
    (Angular often sends the same id in the JSON body).
    """
    path_project_id = (path_project_id or "").strip()
    body_project_id = ""
    if isinstance(payload, dict):
        body_project_id = (payload.get("project_id") or "").strip()

    if _subscriber_id_from_project_id(path_project_id):
        if body_project_id and body_project_id != path_project_id:
            logger.info(
                "Execute routing: URL project_id=%r (subscriber); body project_id=%r",
                path_project_id,
                body_project_id,
            )
        return path_project_id

    if body_project_id and _subscriber_id_from_project_id(body_project_id):
        if path_project_id and path_project_id != body_project_id:
            logger.warning(
                "Execute routing: URL project_id %r has no _sb_; using body project_id %r for subscriber DB",
                path_project_id,
                body_project_id,
            )
        return body_project_id

    return path_project_id or body_project_id

# Global aggregation for agent-level LLM calls (e.g., classification)
_llm_usage_agent: Dict[str, Dict[str, Any]] = {}


def reset_agent_llm_usage() -> None:
    """Reset aggregated LLM usage tracked at the agent level."""
    global _llm_usage_agent
    _llm_usage_agent = {}


def record_agent_llm_usage(
    model_name: str,
    prompt_tokens: int,
    completion_tokens: int,
    total_tokens: int,
) -> None:
    """Accumulate token usage for a given model used directly in this module."""
    global _llm_usage_agent
    if not model_name:
        return
    agg = _llm_usage_agent.setdefault(model_name, {
        "total_input_tokens": 0,
        "total_output_tokens": 0,
        "total_tokens": 0,
        "total_calls": 0,
        "input_cost_usd": 0.0,
        "output_cost_usd": 0.0,
        "total_cost_usd": 0.0,
    })
    agg["total_input_tokens"] += prompt_tokens
    agg["total_output_tokens"] += completion_tokens
    agg["total_tokens"] += total_tokens
    agg["total_calls"] += 1


def get_agent_llm_usage() -> Dict[str, Dict[str, Any]]:
    """Return a copy of aggregated agent-level LLM usage."""
    return _llm_usage_agent.copy()

