def generate_screen_id(prefix: str = "screen") -> str:
    """
    Generate a unique screen ID
    Format: prefix_timestamp_uuid
    Example: screen_20231009_a1b2c3d4
    """
    timestamp = datetime.utcnow().strftime("%Y%m%d%H%M%S")
    unique_id = uuid.uuid4().hex[:8]
    return f"{prefix}_{timestamp}_{unique_id}"


def build_prompt_from_payload(payload: Dict[str, Any]) -> Optional[str]:
    """
    Create a natural language prompt for Angular generation from structured payload fields.
    """
    sections: List[str] = []

    name = payload.get("name")
    details = payload.get("details")
    description = payload.get("description")
    component = payload.get("component")
    tool_data = payload.get("tool_data")

    if name:
        sections.append(f"Task Name: {name}")
    if description:
        sections.append(f"Task Description: {description}")
    if details:
        sections.append(f"Additional Details: {details}")
    if component:
        sections.append(f"Primary Component or Module: {component}")

    if tool_data:
        try:
            tool_data_str = json.dumps(tool_data, indent=2)
        except (TypeError, ValueError):
            tool_data_str = str(tool_data)
        sections.append(f"Tool Data:\n{tool_data_str}")

    if not sections:
        return None

    return (
        "Generate or update an Angular application based on the following requirements:\n"
        + "\n".join(sections)
    )


