class ParameterType(Enum):
    STRING = "string"
    INTEGER = "integer"
    FLOAT = "float"
    BOOLEAN = "boolean"
    DICT = "dict"
    LIST = "list"
    ANY = 'any'

@dataclass
class ToolParameter:
    name: str
    param_type: ParameterType
    description: str = ""
    required: bool = True
    default_value: Any = None
    inputVarDesc: str =""

@dataclass
class ToolDefinition:
    name: str
    description: str
    parameters: List[ToolParameter]
    keywords: List[str] = None
    function_code: str = ""
    imports: List[str] = None
    # Canonical output schema — persisted in JSON and synced to capability_repository
    # so the LangGraph planner knows what each tool returns.
    output_parameters: List[Dict[str, Any]] = None


