    # For langchain tools seeded via `tool_auto_extractor.py`, these are critical.
    source: Optional[str] = None  # e.g. "langchain_community"
    class_path: Optional[str] = None  # e.g. "langchain_community.tools.DuckDuckGoSearchRun"
