# ── LLM intermediate schemas (simplified for Gemini response_schema) ──────


class _LLMInputBinding(BaseModel):
    paramName: str
    sourceType: Literal["node_output", "constant"]
    sourceNodeId: Optional[str] = None
    sourceParam: Optional[str] = None
    value: Optional[str] = None
    dataType: str = "Any"

    @model_validator(mode="after")
    def _validate_source_fields(self) -> "_LLMInputBinding":
        if self.sourceType == "node_output":
            if not (self.sourceNodeId or "").strip() or not (self.sourceParam or "").strip():
                raise ValueError("node_output binding requires sourceNodeId and sourceParam")
            # Prefer structured wiring; ignore any accidental literal.
            self.value = None
        elif self.sourceType == "constant":
            if self.value is None:
                raise ValueError("constant binding requires value")
            # Prefer structured constant; clear node refs if present.
            self.sourceNodeId = None
            self.sourceParam = None
        return self


class _LLMRouterRule(BaseModel):
    condition: str
    targetNodeId: str


class _LLMGraphNode(BaseModel):
    nodeId: str
    type: str
    nodeReasoning: str = Field(
        ...,
        description=(
            "Explain: (1) Why this tool/ui/agent was chosen. "
            "(2) How EVERY required input is sourced (which prior node output or which constant). "
            "(3) If isGenerationNeeded=True or capabilityId starts with GENERATE:, explain exactly "
            "why NO existing capability fit (gap analysis)."
        ),
    )
    name: str
    stepId: str = ""
    capabilityId: str = ""
    capabilityKind: str = ""
    inputBindings: list[_LLMInputBinding] = Field(default_factory=list)
    declaredOutputs: list[GenerationIOParam] = Field(default_factory=list)
    routingRules: list[_LLMRouterRule] = Field(default_factory=list)
    defaultTarget: str = ""
    fallbackTarget: str = ""
    isGenerationNeeded: bool = False
    generationDescription: str = ""
    generationInputs: list[GenerationIOParam] = Field(default_factory=list)
    generationOutputs: list[GenerationIOParam] = Field(default_factory=list)

    @field_validator("generationInputs", "generationOutputs", "declaredOutputs", mode="before")
    @classmethod
    def _coerce_generation_io_params(cls, v: Any) -> Any:
        if v is None:
            return []
        if isinstance(v, list):
            coerced: list[Any] = []
            for item in v:
                if isinstance(item, str):
                    coerced.append({"name": item})
                else:
                    coerced.append(item)
            return coerced
        return v


class _LLMGraphEdge(BaseModel):
    fromNode: str
    to: str
    kind: str
    condition: str = ""


class _LLMGraphPlan(BaseModel):
    graphId: str = ""
