    # Shape: [{ storeType: "mongodb", readCollections: [], writeCollections: [], collections: [] }]
    dataStores: list[Dict[str, Any]] = Field(default_factory=list)
    # Optional shallow schema snapshots for collections referenced by this capability.
    # Shape: { "collection": { "fields": {field: typeTag}, "sampled": true|false } }
