class StepCapabilityMatch(BaseModel):
    """
    Capability match result for a single logical step.
    """
    stepId: str
    stepName: str
    stepDescription: str
    preferredKind: Optional[Literal["ui_screen", "tool", "agent"]] = None
    candidates: list[StepCapabilityCandidate] = Field(default_factory=list)


async def _match_capabilities_for_steps(
    steps: list[LogicalStep],
    *,
    tenant: Dict[str, Optional[str]],
    max_candidates_per_step: int = 10,
) -> list[StepCapabilityMatch]:
    """
    For each logical step, query capability_repository and compute ranked candidates.

    Key behaviors (per design notes):
      - Do NOT hard-filter by preferredKind.
      - Search using: "{step.name}. {step.description}".
      - Search across name, description, searchText, tags.
      - Apply capability scoring metric including:
          • textScore (from Mongo text search when available),
          • tag overlap boosting,
          • negative filtering (e.g. weather tools for non-weather steps).
      - Normalize tokens with a simple suffix-stripping stemmer for overlap.
    """
    capability_repository = CapabilityRepository()
    matches: list[StepCapabilityMatch] = []

    for step in steps:
        candidates_raw = await capability_repository.search_capabilities_for_step(
            tenant,
            step_name=step.name,
            step_description=step.description,
            max_results=max_candidates_per_step,
        )

        candidates: list[StepCapabilityCandidate] = []
        for doc in candidates_raw:
            candidates.append(
                StepCapabilityCandidate(
                    capabilityId=str(doc.get("capabilityId", "")),
                    kind=str(doc.get("kind", "")),
                    name=str(doc.get("name", "")),
                    description=str(doc.get("description", "")),
                    inputParameters=list(doc.get("inputParameters", []) or []),
                    outputParameters=list(doc.get("outputParameters", []) or []),
                    dataStores=list(doc.get("dataStores", []) or []),
                    collectionSchemas=dict(doc.get("collectionSchemas") or {}),
                    tags=[str(t) for t in (doc.get("tags") or [])],
                    capabilityScore=float(doc.get("capabilityScore", 0.0)),
                )
            )

        matches.append(
            StepCapabilityMatch(
                stepId=step.stepId,
                stepName=step.name,
                stepDescription=step.description,
                preferredKind=step.preferredKind,
                candidates=candidates,
            )
        )

    return matches


def _collect_global_capability_candidates(
    step_caps: list[StepCapabilityMatch],
    *,
    min_score: float = 2.0,
    top_n_per_step: int = 6,
) -> list[StepCapabilityCandidate]:
    """
    Flatten per-step capability matches into a single unique candidate list.

    - First, take only the top N candidates per step (by capabilityScore).
    - Keeps only candidates with capabilityScore >= min_score.
    - Deduplicates by capabilityId, keeping the highest-scoring instance.
    - Ignores step boundaries; the graph planner sees the global tool pool.
    """
    best_by_id: Dict[str, StepCapabilityCandidate] = {}
    for sm in step_caps:
        # Pick top-N candidates per step (already ranked in repository, but sort defensively)
        candidates = sorted(
            (sm.candidates or []),
            key=lambda c: float(getattr(c, "capabilityScore", 0.0) or 0.0),
            reverse=True,
        )
        if top_n_per_step and top_n_per_step > 0:
            candidates = candidates[:top_n_per_step]

        for c in candidates:
            if c.capabilityScore < min_score:
                continue
            existing = best_by_id.get(c.capabilityId)
            if existing is None or c.capabilityScore > existing.capabilityScore:
                best_by_id[c.capabilityId] = c
    return list(best_by_id.values())


# ============================================================================
# AGENTIC GRAPH PLANNER — PIPELINE FUNCTIONS (Steps 5-9)
# ============================================================================

# Pattern to find {{nodeId.paramName}} references in inputBinding values.
_BINDING_REF_PATTERN = re.compile(r"\{\{(\w+)\.(\w+)\}\}")

# Matches any bare X.Y token in a condition string (same as runtime _evaluate_condition).
# Used both for normalisation and for validation.
_CONDITION_REF_PATTERN = re.compile(r"\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\b")

# Keywords / Python built-ins that can appear as X in X.Y and are NOT node IDs.
_CONDITION_NON_NODE_TOKENS: frozenset[str] = frozenset({
    "true", "false", "none", "null",
    "and", "or", "not", "in", "is",
    "if", "else", "elif",
    "state", "global",
})


def _normalize_router_conditions(
    routing_rules: list,
    node_id: str,
    cap_id_to_node_id: dict[str, str],
    generate_name_to_node_id: dict[str, str],
    all_node_ids: set[str],
) -> list:
    """
    Rewrite router condition strings so they reference the actual nodeId instead of
    a capabilityId or a GENERATE name.

    The runtime evaluator (_evaluate_condition) does:
        state.get('node_outputs').get(node_id)
    so the left-hand token in X.param MUST be the nodeId, never the capabilityId
    (e.g. "ui:screen_abc…") or the GENERATE name if it differs from nodeId.

    Three rewrite cases handled:
      1. Exact capabilityId match         "ui:screen_abc.success"   → "node_foo.success"
      2. GENERATE:<Name> stripped match   "GENERATE:Bar.status"     → "node_bar.status"
      3. Bare GENERATE name               "CampaignSetup.status"    → "node_campaign.status"
         (only when the name is NOT already a valid nodeId)
    """
    if not routing_rules:
        return routing_rules

    rewritten: list = []
    for rule in routing_rules:
        cond = rule.condition or ""
        if not cond:
            rewritten.append(rule)
            continue

        changed = False

        # Build a single pass replacement: scan all X.Y tokens
        def _replace_ref(m: re.Match) -> str:
            nonlocal changed
            token = m.group(1)
            param  = m.group(2)

            # Already a valid nodeId — nothing to do
            if token in all_node_ids:
                return m.group(0)

            # Token is a Python/condition keyword — leave alone
            if token.lower() in _CONDITION_NON_NODE_TOKENS:
                return m.group(0)

            # Direct capabilityId → nodeId  (handles "ui:screen_..." via exact dict key)
            if token in cap_id_to_node_id:
                changed = True
                return f"{cap_id_to_node_id[token]}.{param}"

            # GENERATE:<Name> used verbatim  (e.g. "GENERATE:Foo.bar")
            gen_stripped = token[len("GENERATE:"):] if token.startswith("GENERATE:") else None
            if gen_stripped and gen_stripped in generate_name_to_node_id:
                changed = True
                return f"{generate_name_to_node_id[gen_stripped]}.{param}"

            # Bare GENERATE name (e.g. "CampaignSetupScreen.success")
            if token in generate_name_to_node_id:
                changed = True
                return f"{generate_name_to_node_id[token]}.{param}"

            # Unknown token — leave unchanged for the validator to flag
            return m.group(0)

        new_cond = _CONDITION_REF_PATTERN.sub(_replace_ref, cond)

        if changed:
            logger.debug(
                "[graph-planner] normalized router condition in '%s': %r → %r",
                node_id, cond, new_cond,
            )
            # Rebuild the rule with corrected condition (works for both Pydantic and dicts)
            if hasattr(rule, "model_copy"):
                rule = rule.model_copy(update={"condition": new_cond})
            else:
                rule = type(rule)(condition=new_cond, targetNodeId=rule.targetNodeId)

        rewritten.append(rule)
    return rewritten


def _canonical_graph_node_type(
    raw_type: str,
    *,
    capability_kind: str = "",
    node_id: str = "",
) -> str:
    """
    Normalize planner/emitter node types to a stable set:
      - tool
      - ui_screen
      - router
      - end
    """
    t = (raw_type or "").strip().lower()
    k = (capability_kind or "").strip().lower()
    n = (node_id or "").strip().lower()

    if t == "router":
        return "router"
    if t in {"end", "end_node", "terminal", "finish", "done"} or n in {"end", "end_node"}:
        return "end"

    if t in {"ui_screen", "ui", "screen", "page", "form"}:
        return "ui_screen"
    if t in {"tool", "tool_action", "tools", "tool_code", "llm_agent", "agent", "action"}:
        return "tool"

    # Generation placeholders should collapse to real execution categories.
    if t in {"generate", "generation", "llm_generation", "generated"}:
        if k in {"ui", "ui_screen", "screen", "page", "form"}:
            return "ui_screen"
        if k in {"tool", "tools", "backend_tool"}:
            return "tool"
        return "tool"

    # Fallback by capability kind when type is noisy or unexpected.
    if k in {"ui", "ui_screen", "screen", "page", "form"}:
        return "ui_screen"
    if k in {"tool", "tools", "backend_tool", "agent"}:
        return "tool"

    # Safe default for executable work nodes.
    return "tool"


def _llm_plan_to_graph_definition(
    plan: _LLMGraphPlan,
    phase_id: str,
    phase_name: str,
    description: str,
) -> GraphDefinition:
    """Convert the LLM's simplified _LLMGraphPlan output to a canonical GraphDefinition."""

    # Build capabilityId → nodeId and GENERATE_name → nodeId maps once up front.
    # These are used to rewrite router conditions that mistakenly reference a
    # capabilityId or GENERATE name instead of the actual runtime nodeId.
    all_node_ids: set[str] = {n.nodeId for n in plan.nodes}
    cap_id_to_node_id: dict[str, str] = {}
    generate_name_to_node_id: dict[str, str] = {}
    for n in plan.nodes:
        if n.capabilityId:
            cap_id_to_node_id[n.capabilityId] = n.nodeId
        # "GENERATE:CampaignSetupScreen" → bare name "CampaignSetupScreen"
        if n.capabilityId.startswith("GENERATE:"):
            bare = n.capabilityId[len("GENERATE:"):]
            if bare:
                generate_name_to_node_id[bare] = n.nodeId
        # Also map the node name itself (LLM sometimes uses the display name)
        if n.name:
            generate_name_to_node_id[n.name] = n.nodeId

    nodes: list[GraphNode] = []
    for n in plan.nodes:
        bindings: Dict[str, str] = {}
        for b in (n.inputBindings or []):
            if b.sourceType == "node_output":
                bindings[b.paramName] = f"{{{{{b.sourceNodeId}.{b.sourceParam}}}}}"
            else:
                bindings[b.paramName] = b.value or ""

        router_cfg: Optional[RouterConfig] = None
        if n.type == "router" and n.routingRules:
            normalized_rules = _normalize_router_conditions(
                n.routingRules,
                node_id=n.nodeId,
                cap_id_to_node_id=cap_id_to_node_id,
                generate_name_to_node_id=generate_name_to_node_id,
                all_node_ids=all_node_ids,
            )
            router_cfg = RouterConfig(
                routingRules=[
                    RouterRule(condition=r.condition, targetNodeId=r.targetNodeId)
                    for r in normalized_rules
                ],
                defaultTarget=n.defaultTarget or None,
                fallbackTarget=n.fallbackTarget or None,
            )

        gen_spec: Optional[GenerationSpec] = None
        if n.isGenerationNeeded:
            ck = (n.capabilityKind or "").strip().lower()
            if ck not in ("tool", "ui_screen"):
                nt = (n.type or "").strip().lower()
                if nt in ("ui_screen", "ui", "screen", "page", "form"):
                    ck = "ui_screen"
                elif nt == "tool":
                    ck = "tool"
                else:
                    ck = "tool"
            gen_spec = GenerationSpec(
                kind=ck,
                stepId=n.stepId or "",
                description=n.generationDescription or n.name,
                inputs=n.generationInputs,
                outputs=n.generationOutputs,
            )

        cap_ref: Optional[GraphCapabilityRef] = None
        if n.capabilityId:
            cap_ref = GraphCapabilityRef(
                capabilityId=n.capabilityId,
                kind=n.capabilityKind or "tool",
            )
        elif gen_spec is not None:
            # Backstop: if the planner marks generation needed but omits capabilityId,
            # treat it as a gap to be generated.
            raw = (n.name or n.stepId or n.nodeId or "GeneratedCapability").strip()
            pascal = "".join(w[:1].upper() + w[1:] for w in re.split(r"[^a-zA-Z0-9]+", raw) if w)
            cap_ref = GraphCapabilityRef(
                capabilityId=f"GENERATE:{pascal or 'GeneratedCapability'}",
                kind=gen_spec.kind,
            )

        canonical_type = _canonical_graph_node_type(
            n.type,
            capability_kind=n.capabilityKind or "",
            node_id=n.nodeId,
        )
        nodes.append(GraphNode(
            nodeId=n.nodeId,
            type=canonical_type,
            name=n.name,
            stepId=n.stepId or None,
            capabilityRef=cap_ref,
            config=GraphNodeConfig(
                inputBindings=bindings,
                declaredOutputs=n.declaredOutputs or [],
                router=router_cfg,
                generation=gen_spec,
            ),
        ))

    edges: list[GraphEdge] = [
        GraphEdge(fromNode=e.fromNode, to=e.to, kind=e.kind, condition=e.condition or None)
        for e in plan.edges
    ]

    graph_id = plan.graphId or f"{phase_id}_graph"
    return GraphDefinition(
        graphId=graph_id,
        phaseId=phase_id,
        phaseName=phase_name,
        name=f"{phase_name} Graph",
        description=description,
        goal=plan.goal or description,
        nodes=nodes,
        edges=edges,
        entryNodeId=plan.entryNodeId,
        endNodeId=plan.endNodeId,
    )



def _fmt_params(params: list[Dict[str, Any]]) -> str:
    """Render inputParameters / outputParameters as a compact readable string."""
    if not params:
        return "[]"
    parts = []
    for p in params:
        parts.append(
            f'{{name: "{p.get("name", "")}", '
            f'dataType: "{p.get("dataType", "")}", '
            f'required: {p.get("required", False)}, '
            f'description: "{(p.get("description") or "")}"}}'
        )
    return "[ " + ", ".join(parts) + " ]"


def _build_steps_text(steps: list[LogicalStep]) -> str:
    lines = [f"  - {s.stepId}: {s.name} — {s.description}" for s in steps]
    return "\n".join(lines) if lines else "  (no steps)"


def _build_caps_text(global_caps: list[StepCapabilityCandidate]) -> str:
    caps_lines: list[str] = []
    for c in global_caps:
        ds_text = json.dumps(c.dataStores or [], indent=2) if getattr(c, "dataStores", None) else "[]"
        cs_text = json.dumps(c.collectionSchemas or {}, indent=2) if getattr(c, "collectionSchemas", None) else "{}"
        caps_lines.append(
            f"  • {c.capabilityId} (kind={c.kind}, score={c.capabilityScore:.2f})\n"
            f"    name: {c.name}\n"
            f"    description: {c.description}\n"
            f"    dataStores: {ds_text}\n"
            f"    collectionSchemas: {cs_text}\n"
            f"    inputParameters: {_fmt_params(c.inputParameters or [])}\n"
            f"    outputParameters: {_fmt_params(c.outputParameters or [])}"
        )
    return "\n".join(caps_lines) if caps_lines else "  (no existing capabilities — most nodes will be GENERATE:*)"


def _build_prior_phase_section(prior_phase_outputs: Optional[Dict[str, list]]) -> str:
    if not prior_phase_outputs:
        return ""
    prior_lines = []
    for nid, keys in prior_phase_outputs.items():
        if not keys:
            continue
        pretty: list[str] = []
        for k in keys:
            if isinstance(k, dict):
                name = k.get("name") or ""
                dtype = k.get("datatype") or k.get("dataType") or "Any"
                item_type = k.get("itemType")
                if not item_type:
                    if k.get("itemSchema"):
                        item_type = "record"
                    elif k.get("enumValues"):
                        item_type = "enum"
                    elif k.get("scalarItemDatatype"):
                        item_type = "scalar"
                if item_type == "scalar":
                    type_str = f"list<{k.get('scalarItemDatatype') or 'string'}>"
                elif item_type == "enum":
                    type_str = "list<enum>"
                elif item_type == "record":
                    type_str = "list<record>"
                elif dtype == "list":
                    type_str = "list"
                else:
                    type_str = str(dtype)
                pretty.append(f"{name}:{type_str}" if name else "")
            else:
                pretty.append(str(k))
        pretty = [p for p in pretty if p]
        if pretty:
            prior_lines.append(f"  • {nid}: outputs=[{', '.join(pretty)}]")
    if not prior_lines:
        return ""
    return (
        "\nCROSS-PHASE OUTPUTS FROM PRIOR PHASES (already in node_outputs at runtime):\n"
        "  Reference these EXACTLY as nodeId.outputParamName in bindings.\n"
        "  Do NOT invent namespaces like __graph__.* or global.* — they live in\n"
        "  node_outputs keyed by nodeId.\n"
        + "\n".join(prior_lines)
    )


def _build_generate_specs_section(
    reasoning_document: str,
    steps: list[LogicalStep],  # kept for signature compatibility, not used for mapping
) -> str:
    """
    Pure-Python extraction pass between Call 1 and Call 2.

    Extracts the GENERATION SPEC that Call 1 wrote inline for every GENERATE node.
    Call 1 has the full original step context when it writes these specs, so it
    can correctly assign the right detail to each node it invents (main screens,
    error handlers, sub-tools, review screens) without any step-to-node mapping.

    We do NOT attempt to match generated nodes back to original LogicalSteps here,
    because one original step can expand into many nodes (main + error handlers +
    sub-screens) with different roles — mapping by name is wrong for auxiliary nodes.
    """
    # Match every GENERATE block and capture its GENERATION SPEC field.
    # The spec runs from "GENERATION SPEC:" to the next recognised field
    # header or block boundary.
    generate_block_re = re.compile(
        r"GENERATE\s+(?P<node_name>\w+)\s*\(kind:\s*(?P<kind>[^)]+)\)"
        r"(?P<block>.*?)"
        r"(?=\bGENERATE\s+\w+\s*\(|\bUSE\s+|\bThis step exposes|\Z)",
        re.DOTALL,
    )
    spec_re = re.compile(
        r"GENERATION SPEC:\s*\n(?P<spec>(?:[ \t]+[^\n]*\n?)+)",
        re.IGNORECASE,
    )

    entries: list[str] = []

    for m in generate_block_re.finditer(reasoning_document):
        node_name = m.group("node_name").strip()
        kind = m.group("kind").strip()
        block = m.group("block")

        spec_match = spec_re.search(block)
        if not spec_match:
            continue  # Call 1 didn't write a GENERATION SPEC for this node; skip

        raw_spec = spec_match.group("spec")
        # Dedent: strip the common leading whitespace so the spec reads cleanly.
        spec_lines = raw_spec.splitlines()
        stripped = [ln.rstrip() for ln in spec_lines]
        # Remove leading blank lines
        while stripped and not stripped[0]:
            stripped.pop(0)
        spec_text = "\n".join(stripped).strip()

        if not spec_text:
            continue

        entries.append(
            f"──────────────────────────────────────────────────────────────\n"
            f"GENERATE node: {node_name}  (kind: {kind})\n"
            f"\n"
            f"{spec_text}\n"
        )

    if not entries:
        return ""

    return (
        "════════════════════════════════════════════════════════════════\n"
        "GENERATE NODE SPECS\n"
        "════════════════════════════════════════════════════════════════\n"
        "MANDATORY: For each GENERATE node below, copy its spec VERBATIM\n"
        "into generationDescription. Do NOT summarise, abbreviate, or rephrase.\n"
        "Exact dropdown values, collection names, and schema field names must\n"
        "be preserved exactly as written.\n"
        "\n"
        + "\n".join(entries)
    )


def _extract_selected_caps_text(
    reasoning_document: str,
    global_caps: list[StepCapabilityCandidate],
) -> str:
    """
    Parse Call 1's reasoning document for finalised USE [capabilityId] decisions.
    Returns a formatted string with full schema info for only those capabilities.
    """
    cap_map = {c.capabilityId: c for c in global_caps}

    selected_ids: set[str] = set()
    for cap_id in cap_map:
        if re.search(rf'\bUSE\s+{re.escape(cap_id)}\b', reasoning_document):
            selected_ids.add(cap_id)

    if not selected_ids:
        return "  (no existing capabilities selected — all nodes are GENERATE)"

    lines: list[str] = []
    for cap_id in selected_ids:
        c = cap_map[cap_id]
        ds_text = json.dumps(c.dataStores or [], indent=2) if getattr(c, "dataStores", None) else "[]"
        cs_text = json.dumps(c.collectionSchemas or {}, indent=2) if getattr(c, "collectionSchemas", None) else "{}"
        lines.append(
            f"  • {c.capabilityId} (kind={c.kind})\n"
            f"    name: {c.name}\n"
            f"    description: {c.description}\n"
            f"    dataStores: {ds_text}\n"
            f"    collectionSchemas: {cs_text}\n"
            f"    inputParameters:  {_fmt_params(c.inputParameters or [])}\n"
            f"    outputParameters: {_fmt_params(c.outputParameters or [])}"
        )
    return "\n".join(lines)


def _build_call1_prompt(
    phase_name: str,
    phase_description: str,
    steps_text: str,
    caps_text: str,
    prior_phase_section: str,
    collection_schemas_section: str = "",
) -> str:
    schemas_block = ""
    if collection_schemas_section and collection_schemas_section.strip():
        schemas_block = f"\n{collection_schemas_section.strip()}\n"

    return f"""
╔══════════════════════════════════════════════════════════════════════╗
║  PRIMARY OBJECTIVE — READ THIS FIRST AND REFER BACK THROUGHOUT      ║
║                                                                      ║
║  Phase : {phase_name}
║  Goal  : {phase_description}
╚══════════════════════════════════════════════════════════════════════╝

You are a senior solution architect planning a LangGraph workflow graph.
Your output in this step is a REASONING DOCUMENT — NOT JSON, NOT code.
A second pass will convert your decisions to JSON.
Your job here is to think correctly and completely.

Do NOT produce JSON. Do NOT produce code.
Produce the five sections below in full, in order, without skipping any.

════════════════════════════════════════════════════════════════
CONTEXT
════════════════════════════════════════════════════════════════

LOGICAL STEPS:
{steps_text}
{prior_phase_section}{schemas_block}
AVAILABLE CAPABILITIES (score >= 2.0; higher = stronger match or previously used):
{caps_text}

════════════════════════════════════════════════════════════════
CAPABILITY SELECTION RULES (read before Section 2)
════════════════════════════════════════════════════════════════

★ ALWAYS PREFER EXISTING CAPABILITIES over generating new ones.
  Score >= 3.0 = strong signal this was previously used or closely matches.

  Before marking any node as GENERATE:
    1. Find candidate(s) whose name/description best matches the step.
    2. List every REQUIRED (not optional) inputParameter for that candidate.
    3. Check whether EVERY required input can be satisfied by:
         a) a prior node's output (name the exact node and output param), OR
         b) a constant literal you supply.
    4. If ONLY optional inputs are missing → supply them as constants ("" or null).
       Do NOT reject a capability just because an optional field is missing.
    5. Check whether outputParameters satisfy what downstream steps need.
    6. Only GENERATE when NO existing capability's core logic fits, OR when a
       required input/output cannot be satisfied by any upstream data.

  GENERATE node kinds:
    - "tool"      → pure server-side: no user interaction whatsoever
    - "ui_screen" → any user-visible interaction (forms, uploads, confirmations)
      A ui_screen is FULL-STACK: its description must cover both the frontend UI
      AND the backend handler. Do NOT create a separate tool node for a screen's
      backend — it is part of the screen.

  Node types (exactly one of):
    "tool" | "ui_screen" | "router" | "end"

  BACKEND CRUD contract (when persistence is involved):
    Name the exact collection/table, operation (insert/find/update/upsert/etc.),
    filter keys, and which prior node output supplies each identifier.
    Keep collection names CONSISTENT across steps that share data.

════════════════════════════════════════════════════════════════
GRAPH STRUCTURE RULES (read before Section 3)
════════════════════════════════════════════════════════════════

  RETRY LOOPS — required for every recoverable failure:
    ┌─ action_node
    │     ↓
    │   [action_result_router]
    │     success → next_step_node
    │     failure → error_handler_node   (ui_screen — shows error, asks retry)
    │                    ↓
    │               [error_retry_router]
    │                 retry_option_selected == true  → action_node  ← CYCLE BACK
    │                 retry_option_selected == false → end_node
    └──────────────────────────────────────────────────────────

  Rules:
    • Every error_handler_node MUST declare output: retry_option_selected (boolean).
    • NEVER wire error_handler_node directly to end_node — always via a retry_router.
    • Add a dedicated router AFTER every error_handler_node.
    • Only skip retry when failure is truly unrecoverable (document why).

  Router nodes:
    • At least one routingRule (condition + targetNodeId).
    • defaultTarget and fallbackTarget required on every router.

  Forward-reference rule (CRITICAL):
    • The entry node MUST have no inputBindings that reference downstream nodes.
    • Error screens that display a failure message must be DOWNSTREAM of the node
      that produced the error — never upstream.

════════════════════════════════════════════════════════════════
PRODUCE THE FOLLOWING REASONING DOCUMENT
════════════════════════════════════════════════════════════════

──────────────────────────────────────────────────────────────
SECTION 1 — REQUIREMENT INVENTORY
──────────────────────────────────────────────────────────────
List every distinct functional requirement from the PRIMARY OBJECTIVE above.
Number them. Be specific and concrete.

Example format:
  R1. User must fill a loan application form with personal and financial details.
  R2. System must validate credit score via external API before proceeding.
  R3. If credit score < 650, route to rejection path with reason shown to user.
  R4. Rejection screen must allow user to appeal.

──────────────────────────────────────────────────────────────
SECTION 2 — STEP-BY-STEP CAPABILITY DECISIONS
──────────────────────────────────────────────────────────────
Work through every logical step IN ORDER. For each step:

  STEP [stepId]: [stepName]
  Requirements covered: [R1, R2, ...]
  Node type: [tool | ui_screen]

  Candidate evaluation:
    [capabilityId]:
      Required inputs    : [list each required param]
      Satisfied by       : [for each: "param_name ← node_output: prior_node.param_name" OR "param_name ← constant: value"]
      Outputs match need : [yes/no — name what downstream steps need from this]
      VERDICT            : SELECT ✓  /  REJECT ✗ (exact reason)

    [next capabilityId]: ...

  Final decision:
    USE [capabilityId]
    — OR —
    GENERATE [PascalStepName] (kind: tool | ui_screen)
      Inputs  : [name | dataType | required | source (prior node.param or constant) | description]
      Outputs : [name | dataType | description — what this exposes downstream]
      Backend contract (if DB/API): [collection name, operation, keys, filters]
      Rejection reason: [why every existing cap was rejected — be specific]
      GENERATION SPEC:
        [Write a complete, self-contained specification ONLY for this specific node.
         This field is critical — it will be passed verbatim to the code generator.
         Rules:
           • Copy exact field labels, dropdown option values, and schema details
             verbatim from the step description. Do NOT paraphrase or abbreviate.
             Example: write "Campaign Type dropdown with options: Event, Webinar,
             Newsletter, Product Launch, Promo, Drip Sequence, Re-engagement,
             Retargeting; plus a free-text custom option" — not "dropdown+custom".
           • Include exact collection names, field names, and DB schemas mentioned
             in the step (e.g. Solutions schema: Product, Description, USP).
           • CRITICAL (existing collections): if this node reads/writes a MongoDB
             collection listed in KNOWN COLLECTION SCHEMAS (or named in the step),
             the GENERATION SPEC MUST include the full field:type schema, e.g.
             "Collection 'mna_leads' schema: {{company_name:string, current_tab:string,
             is_deleted:string}}". Naming the collection alone is INVALID — tools/UI
             generators cannot invent fields.
           • For ui_screen: describe the full frontend UI AND the backend handler
             for THIS screen only. Do not describe other screens.
           • For tool: describe the backend logic, API calls, DB ops for THIS tool.
           • For error handler / retry screens: describe only what the error screen
             shows (which error, what the retry button does) — do NOT copy the full
             original step description.
           • For sub-screens created from a single user step (e.g. a review screen
             split from a generation step): describe only the sub-screen's role.]

    ⚠ NAMING RULE (mandatory):
        • Always use the EXACT capabilityId string as-is (e.g. tool:send_email_notification_3a768d74_sb_86dc316c).
        • Never rename, shorten, or alias a selected capability — no "(renamed locally to ...)" or similar.
        • GENERATE node names use PascalCase of the step (e.g. GENERATE FillDoctorAppointmentForm).
        • nodeIds in Section 4 routers must also use exact capabilityIds for existing caps,
        and exact GENERATE names for generated nodes — no invented aliases.

  This step exposes downstream:
    [output_param_name] : [dataType] — [what it means for the next step]

  Failure modes:
    [condition] → [what the graph must do — show retry loop if recoverable]

──────────────────────────────────────────────────────────────
SECTION 3 — DATA FLOW LEDGER
──────────────────────────────────────────────────────────────
After finalising each step above (in execution order), update this table.
Before placing each step, verify every required input is already in the table.
If an input is not yet available → reorder steps or add a missing step.

  Start: available_variables = {{}}  (empty; prior phase outputs listed in CONTEXT are pre-seeded)

  | Variable                    | DataType  | Produced By          |
  |-----------------------------|-----------|----------------------|
  | [nodeId].[outputParamName]  | [type]    | [nodeId]             |
  | ...                         | ...       | ...                  |

  After each step, show the updated table (you may append rows rather than
  reproducing the whole table each time).

  If a required input for step N is not yet in available_variables and cannot
  be a constant → FLAG IT here and resolve it (reorder, add a step, or GENERATE
  with the correct inputs).

──────────────────────────────────────────────────────────────
SECTION 4 — BRANCH, ROUTER, AND RETRY MAP
──────────────────────────────────────────────────────────────
For every decision point and failure path in the workflow:

  DECISION [router_node_id]:
    Trigger variable : [nodeId.outputParamName]
    Condition        : [e.g., nodeId.status == "approved"]
    True/match path  : → [nodeId]
    False/else path  : → [nodeId]
    Recoverable?     : [yes / no]
    If yes, retry target: [nodeId the loop cycles back to]
    Retry router id  : [router_node_id]

List ALL routers including retry routers.
Confirm every error_handler_node routes through a retry_router (not directly to end).

──────────────────────────────────────────────────────────────
SECTION 5 — REQUIREMENT CLOSURE CHECK
──────────────────────────────────────────────────────────────
For every requirement listed in Section 1, name the node(s) that implement it.

  R1 → [nodeId(s)]
  R2 → [nodeId(s)]
  ...

If any requirement has NO implementing node:
  → Add a new step/node to the plan and update Sections 2–4 accordingly.
  → Do NOT close this section with an unimplemented requirement.

Final confirmation:
  All requirements covered: YES / NO
  If NO — list what is still missing and why.
""" + _GLOBAL_VARS_INSTRUCTION_AGENT


def _build_call2_prompt(
    reasoning_document: str,
    phase_name: str,
    phase_description: str,
    steps_text: str,
    selected_caps_text: str,
    prior_phase_section: str,
    generate_specs_section: str = "",
) -> str:
    return f"""
You previously produced the following REASONING DOCUMENT for a LangGraph workflow.
All decisions — capability selections, I/O contracts, bindings, routers, retry loops —
are already finalised in that document.

YOUR ONLY JOB: Convert the reasoning document faithfully into the required JSON schema.
Do NOT re-reason. Do NOT change capability selections. Do NOT alter I/O contracts.
Do NOT invent new nodes or bindings not present in the reasoning document.
If the reasoning document says USE [capabilityId] → use it exactly.
If the reasoning document says GENERATE [Name] → mark isGenerationNeeded=true exactly as specified.

════════════════════════════════════════════════════════════════
REASONING DOCUMENT (your decisions — transcribe these faithfully)
════════════════════════════════════════════════════════════════
{reasoning_document}

{generate_specs_section}
════════════════════════════════════════════════════════════════
ORIGINAL CONTEXT (for reference only — graph decisions already made above)
════════════════════════════════════════════════════════════════
Phase : {phase_name}
Goal  : {phase_description}

LOGICAL STEPS:
{steps_text}
{prior_phase_section}
SELECTED CAPABILITIES (finalised in reasoning document — copy outputParameters
EXACTLY into declaredOutputs, copy inputParameters for binding reference):
{selected_caps_text}

════════════════════════════════════════════════════════════════
JSON CONSTRUCTION RULES (follow exactly while transcribing)
════════════════════════════════════════════════════════════════

⚠ USE EXACT IDs — NO ALIASES:
  capabilityId for existing nodes must be the EXACT string from the reasoning document
  (e.g. "tool:send_email_notification_3a768d74_sb_86dc316c"), never a local alias or
  shortened name. If the reasoning document contains "(renamed locally to X)", ignore
  the alias — use only the original capabilityId that appears after "USE".

NODE TYPES — exactly one of:
  "tool" | "ui_screen" | "router" | "end"
  Never use aliases like "tool_action", "tools", "llm_generation", "tool_code".

declaredOutputs:
  • Existing capability → copy EXACTLY from capability.outputParameters (exact names).
  • GENERATE node      → use the outputs defined in the reasoning document Section 2.

inputBindings — structured fields, NOT template strings:
  {{
    "paramName": {{
      "sourceType"  : "node_output" | "constant",
      "sourceNodeId": "<nodeId>",          // only when sourceType="node_output"
      "sourceParam" : "<outputParamName>", // only when sourceType="node_output"
      "value"       : "<literal>",         // only when sourceType="constant"
      "dataType"    : "<type>"
    }}
  }}
  • Every required input MUST have an inputBinding.
  • Leaving a required param out of inputBindings is a CRITICAL FAILURE.
  • GENERATE nodes need inputBindings too — the generator receives no other data.

Router nodes:
  • routingRules: at least one entry with condition + targetNodeId.
  • defaultTarget and fallbackTarget: required, must reference real nodeIds.
  • condition MUST reference the source node's nodeId, never its capabilityId or
    GENERATE name. At runtime, outputs are stored under nodeId in node_outputs.
    Using the wrong identifier silently returns None → condition is always false.
      ✗ "ui:screen_20260519070655_a3d663fa.success == true"  ← capabilityId, BREAKS
      ✗ "CampaignSetupScreen.success == true"  ← GENERATE name (if nodeId differs), BREAKS
      ✓ "node_campaign_setup.success == true"  ← actual nodeId, CORRECT

Retry loops:
  • error_handler_node → retry_router → (true) back to action_node | (false) end_node.
  • error_handler_node MUST declare retry_option_selected (boolean) in declaredOutputs.

GENERATE node fields:
  • capabilityId      : "GENERATE:<PascalStepName>"
  • capabilityKind    : "tool" | "ui_screen"  (matches type field)
  • isGenerationNeeded: true
  • generationDescription:
      ▸ Find this node's name in GENERATE NODE SPECS (above the reasoning document).
        Copy its spec VERBATIM as the generationDescription.
        Do NOT summarise, shorten, or rephrase. Preserve every detail:
          – exact dropdown option values (e.g. "Event, Webinar, Newsletter …")
          – exact collection names and field/schema details
          – all conditional UI logic and backend operations
      ▸ If a node has no entry in GENERATE NODE SPECS (Call 1 did not write a spec
        for it), write a short description of what the node does based on its role
        in the reasoning document (inputs, outputs, and purpose).
  • generationInputs  : [{{name, dataType, required, description}}]
  • generationOutputs : [{{name, dataType, required, description}}]

Graph-level fields:
  • entryNodeId : first step node (NOT a router, NOT end_node)
  • endNodeId   : "end_node"
  • edges[].kind: "sequential" | "conditional" | "fallback"
  • Every non-end node must have at least one outgoing edge.

FORWARD-REFERENCE RULE (CRITICAL — will crash at runtime if violated):
  • The entry node must have NO inputBindings referencing downstream nodes.
  • Every inputBinding sourceNodeId must point to a node that executes BEFORE
    the current node in the graph flow.

FINAL CHECK BEFORE RETURNING JSON:
  ✓ Every required input has an inputBinding.
  ✓ Every node_output binding references a real declaredOutput of the source node
    (exact spelling match).
  ✓ Every router has defaultTarget and fallbackTarget pointing to real nodeIds.
  ✓ Every error_handler_node declares retry_option_selected.
  ✓ Entry node has no forward-reference bindings.
  ✓ declaredOutputs for existing capabilities match capability.outputParameters exactly.
  ✓ Every GENERATE node that appears in GENERATE NODE SPECS has a generationDescription
    that matches the spec verbatim — not a one-line summary.

Return the complete graph as valid JSON matching the required schema.
""" + _GLOBAL_VARS_INSTRUCTION_AGENT


async def _call_gemini_graph_planner(
    api_key: Optional[str],
    prompt: str,
    *,
    temperature: float,
    as_json: bool,
    response_schema: Any = None,
    model: str = "gemini-3.1-pro-preview",
) -> tuple[str, Any, dict]:
    """One Gemini call for graph planning. Returns (raw_text, parsed_or_None, usage)."""
    response = await async_generate(
        model,
        prompt,
        config=GeminiGenerateConfig(
            temperature=temperature,
            thinking_level="high",  # model_supports_thinking_level gates this
            response_mime_type="application/json" if as_json and response_schema is not None else None,
            response_schema=response_schema if as_json and response_schema is not None else None,
            fallback_profile="planner",
        ),
        api_key=api_key,
    )

    raw_text = ""
    try:
        raw_text = response.text or ""
    except Exception:
        pass

    parsed = None
    if as_json and response_schema is not None:
        parsed = response.parsed

    usage = extract_token_usage_from_response(response)
    return raw_text, parsed, usage


async def _plan_phase_graph_with_llm(
    phase_id: str,
    phase_name: str,
    phase_description: str,
    steps: list[LogicalStep],
    global_caps: list[StepCapabilityCandidate],
    *,
    prior_phase_outputs: Optional[Dict[str, list]] = None,
    project_id: Optional[str] = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    api_key: Optional[str] = None,
    collection_schemas_text: Optional[str] = None,
) -> GraphDefinition:
    """
    Two-call LangGraph graph planner.

    Call 1 — Pure reasoning (plain text, no schema).
              Forces structured thinking: requirement extraction →
              capability evaluation with I/O proof → data-flow ledger →
              branch/retry map → requirement closure.

    Call 2 — Mechanical JSON transcription of Call 1's decisions.
              Schema-enforced. No new reasoning.

    Raises RuntimeError if either call exhausts all retries without a
    valid result. No fallback graph is produced.
    """
    if api_key is None:
        api_key = get_gemini_api_key()

    # Shared context strings (built once, reused in both prompts)
    steps_text = _build_steps_text(steps)
    caps_text = _build_caps_text(global_caps)
    prior_phase_section = _build_prior_phase_section(prior_phase_outputs)

    schemas_section = (collection_schemas_text or "").strip()
    schemas_dict: Dict[str, Any] = {}
    if not schemas_section:
        try:
            from services.collection_schema import resolve_schemas_for_planner

            step_texts = [
                f"{getattr(s, 'name', '')}\n{getattr(s, 'description', '')}"
                for s in (steps or [])
            ]
            schemas_dict, schemas_section = await resolve_schemas_for_planner(
                texts=[phase_description, *step_texts, steps_text],
                project_id=project_id,
                subscriber_id=subscriber_id,
            )
            if schemas_section:
                logger.info(
                    "[Graph planner] Injected known collection schemas for phase=%s (%d chars)",
                    phase_id,
                    len(schemas_section),
                )
        except Exception as exc:
            logger.warning(
                "[Graph planner] Failed to resolve collection schemas: %s", exc
            )
            schemas_section = ""
            schemas_dict = {}

    _MAX_RETRIES = 3
    retry_group_id = str(uuid.uuid4())

    # CALL 1 — Pure Reasoning (plain text, no schema)
    call1_prompt = _build_call1_prompt(
        phase_name,
        phase_description,
        steps_text,
        caps_text,
        prior_phase_section,
        collection_schemas_section=schemas_section,
    )
    logger.info(f"[Graph planner] Call 1 prompt (phase='{phase_id}'):\n{call1_prompt}")

    reasoning_document: Optional[str] = None
    last_error: Optional[Exception] = None

    for attempt in range(1, _MAX_RETRIES + 1):
        temperature = round(0.3 + (attempt - 1) * 0.1, 2)
        started_at = datetime.utcnow()
        try:
            raw_text, _, usage = await _call_gemini_graph_planner(
                api_key,
                call1_prompt,
                temperature=temperature,
                as_json=False,
            )
            finished_at = datetime.utcnow()
            record_llm_call(
                project_id=project_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                operation="graph-planning",
                sub_operation="call1-reasoning",
                model="gemini-3.1-pro",
                prompt_tokens=int(usage.get("prompt_tokens", 0) or 0),
                completion_tokens=int(usage.get("completion_tokens", 0) or 0),
                total_tokens=int(usage.get("total_tokens", 0) or 0),
                status="success",
                attempt=attempt,
                is_retry=attempt > 1,
                retry_group_id=retry_group_id,
                started_at=started_at,
                finished_at=finished_at,
                metadata={
                    "phase_id": phase_id,
                    "phase_name": phase_name,
                    "temperature": temperature,
                },
            )
            if not raw_text or len(raw_text.strip()) < 100:
                raise ValueError(
                    f"Call 1 returned suspiciously short response "
                    f"({len(raw_text)} chars)."
                )
            reasoning_document = raw_text
            logger.info(
                f"[Graph planner] Call 1 reasoning document "
                f"(phase='{phase_id}'):\n{reasoning_document}"
            )
            break
        except BillingError:
            raise

        except BillingError:
            raise
        except Exception as e:
            finished_at = datetime.utcnow()
            last_error = e
            record_llm_call(
                project_id=project_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                operation="graph-planning",
                sub_operation="call1-reasoning",
                model="gemini-3.1-pro",
                prompt_tokens=0,
                completion_tokens=0,
                total_tokens=0,
                status="failed",
                attempt=attempt,
                is_retry=attempt > 1,
                retry_group_id=retry_group_id,
                started_at=started_at,
                finished_at=finished_at,
                metadata={
                    "phase_id": phase_id,
                    "phase_name": phase_name,
                    "temperature": temperature,
                    "error": str(e),
                },
            )
            logger.warning(
                f"[Graph planner] Call 1 attempt {attempt}/{_MAX_RETRIES} failed "
                f"for phase '{phase_id}': {e}"
            )
            if attempt < _MAX_RETRIES:
                await asyncio.sleep(1.5 * attempt)

    if reasoning_document is None:
        raise RuntimeError(
            f"Graph planner Call 1 (reasoning) failed after {_MAX_RETRIES} attempts "
            f"for phase '{phase_id}'. Last error: {last_error}"
        )

    selected_caps_text = _extract_selected_caps_text(reasoning_document, global_caps)
    logger.info(
        f"[Graph planner] Selected capabilities for Call 2 (phase='{phase_id}'):\n"
        f"{selected_caps_text}"
    )

    generate_specs_section = _build_generate_specs_section(reasoning_document, steps)
    logger.info(
        f"[Graph planner] Generate node specs for Call 2 (phase='{phase_id}'):\n"
        f"{generate_specs_section}"
    )

    # CALL 2 — JSON Transcription (schema-enforced)
    call2_prompt = _build_call2_prompt(
        reasoning_document,
        phase_name,
        phase_description,
        steps_text,
        selected_caps_text,
        prior_phase_section,
        generate_specs_section,
    )
    logger.info(f"[Graph planner] Call 2 prompt (phase='{phase_id}'):\n{call2_prompt}")

    plan: Optional[_LLMGraphPlan] = None
    last_error = None

    for attempt in range(1, _MAX_RETRIES + 1):
        temperature = round(0.1 + (attempt - 1) * 0.1, 2)
        started_at = datetime.utcnow()
        try:
            raw_text, parsed, usage = await _call_gemini_graph_planner(
                api_key,
                call2_prompt,
                temperature=temperature,
                as_json=True,
                response_schema=_LLMGraphPlan,
            )
            finished_at = datetime.utcnow()
            record_llm_call(
                project_id=project_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                operation="graph-planning",
                sub_operation="call2-transcription",
                model="gemini-3.1-pro",
                prompt_tokens=int(usage.get("prompt_tokens", 0) or 0),
                completion_tokens=int(usage.get("completion_tokens", 0) or 0),
                total_tokens=int(usage.get("total_tokens", 0) or 0),
                status="success",
                attempt=attempt,
                is_retry=attempt > 1,
                retry_group_id=retry_group_id,
                started_at=started_at,
                finished_at=finished_at,
                metadata={
                    "phase_id": phase_id,
                    "phase_name": phase_name,
                    "temperature": temperature,
                },
            )
            if parsed is None:
                raise ValueError(
                    f"Call 2 response.parsed is None (attempt {attempt}/{_MAX_RETRIES}). "
                    f"raw_text[:500]={raw_text[:500]!r}"
                )
            if not parsed.nodes:
                raise ValueError(
                    f"Call 2 returned empty nodes list (attempt {attempt}/{_MAX_RETRIES})."
                )
            plan = parsed
            for _n in plan.nodes:
                for _b in _n.inputBindings:
                    if _b.value and "system." in _b.value:
                        _b.value = _b.value.replace("system.", "global.")
            
            logger.info(
                f"[Graph planner] Call 2 parsed plan (phase='{phase_id}'): {plan}"
            )
            break
        except BillingError:
            raise

        except BillingError:
            raise
        except Exception as e:
            finished_at = datetime.utcnow()
            last_error = e
            record_llm_call(
                project_id=project_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                operation="graph-planning",
                sub_operation="call2-transcription",
                model="gemini-3.1-pro",
                prompt_tokens=0,
                completion_tokens=0,
                total_tokens=0,
                status="failed",
                attempt=attempt,
                is_retry=attempt > 1,
                retry_group_id=retry_group_id,
                started_at=started_at,
                finished_at=finished_at,
                metadata={
                    "phase_id": phase_id,
                    "phase_name": phase_name,
                    "temperature": temperature,
                    "error": str(e),
                },
            )
            logger.warning(
                f"[Graph planner] Call 2 attempt {attempt}/{_MAX_RETRIES} failed "
                f"for phase '{phase_id}': {e}"
            )
            if attempt < _MAX_RETRIES:
                await asyncio.sleep(1.5 * attempt)

    if plan is None:
        raise RuntimeError(
            f"Graph planner Call 2 (transcription) failed after {_MAX_RETRIES} attempts "
            f"for phase '{phase_id}'. Last error: {last_error}"
        )

    graph = _llm_plan_to_graph_definition(plan, phase_id, phase_name, phase_description)
    if schemas_dict:
        _enrich_graph_generation_descriptions_with_schemas(graph, schemas_dict)
    return graph


def _enrich_graph_generation_descriptions_with_schemas(
    graph: "GraphDefinition",
    schemas: Dict[str, Any],
) -> None:
    """Append missing field:type schema stanzas to GENERATE node descriptions (Task 6)."""
    if not graph or not schemas:
        return
    usable = {k: v for k, v in schemas.items() if k != "__meta__" and isinstance(v, dict)}
    if not usable:
        return
    for node in graph.nodes or []:
        cfg = getattr(node, "config", None)
        if cfg is None:
            continue
        gen = getattr(cfg, "generation", None)
        desc = ""
        if gen is not None and getattr(gen, "description", None):
            desc = gen.description or ""
        elif getattr(cfg, "generationDescription", None):
            desc = cfg.generationDescription or ""
        if not desc:
            continue
        enriched = desc
        append_parts: list[str] = []
        for coll_name, info in usable.items():
            if not _description_explicitly_mentions_collection(enriched, coll_name):
                continue
            fields = (info or {}).get("fields") or {}
            if not fields:
                continue
            if re.search(
                re.escape(coll_name) + r"[^\n]{0,80}schema\s*:",
                enriched,
                flags=re.IGNORECASE,
            ):
                continue
            parts = [f"{k}:{v}" for k, v in sorted(fields.items())[:60]]
            append_parts.append(
                f"Collection '{coll_name}' schema: {{{', '.join(parts)}}}."
            )
        if append_parts:
            extra = " ".join(append_parts)
            enriched = enriched.rstrip() + " " + extra
            if gen is not None:
                gen.description = enriched
            cfg.generationDescription = enriched
            # Schema facts are additive; keep intentDescription aligned so the
            # generator prompt (which prefers intent) does not lose them.
            intent = (getattr(cfg, "intentDescription", None) or "").strip()
            if intent and extra not in intent:
                cfg.intentDescription = intent.rstrip() + " " + extra
            elif not intent:
                cfg.intentDescription = enriched

def _get_capabilities_used_in_graph(
    graph: GraphDefinition,
    global_caps: list[StepCapabilityCandidate],
) -> list[StepCapabilityCandidate]:
    """Return only capabilities that are referenced by nodes in this graph (tool info from registry)."""
    used_ids = set()
    for node in graph.nodes:
        if node.capabilityRef and not node.capabilityRef.capabilityId.startswith("GENERATE:"):
            used_ids.add(node.capabilityRef.capabilityId)
    cap_by_id = {c.capabilityId: c for c in global_caps}
    return [cap_by_id[cid] for cid in used_ids if cid in cap_by_id]


def _log_capability_audit(
    global_caps: list[StepCapabilityCandidate],
    *,
    all_step_caps: Optional[list[StepCapabilityMatch]] = None,
    graph: Optional[GraphDefinition] = None,
    log_prefix: str = "[capabilities]",
    log_pool: bool = True,
) -> None:
    """
    Structured logs: pool size, per-item id/name/score, and (optional) graph selection
    with distinct capability count and node bindings.
    """
    pool = list(global_caps or [])
    if log_pool:
        pool_sorted = sorted(
            pool,
            key=lambda c: float(getattr(c, "capabilityScore", 0.0) or 0.0),
            reverse=True,
        )
        if all_step_caps is not None:
            raw_total = sum(len(sm.candidates or []) for sm in all_step_caps)
            logger.info(
                "%s match_summary raw_candidates_across_steps=%d global_pool_unique=%d",
                log_prefix,
                raw_total,
                len(pool_sorted),
            )
        else:
            logger.info("%s global_pool_unique=%d", log_prefix, len(pool_sorted))

        for c in pool_sorted:
            logger.info(
                "%s pool id=%s name=%r kind=%s score=%.4f",
                log_prefix,
                c.capabilityId,
                c.name,
                c.kind,
                float(getattr(c, "capabilityScore", 0.0) or 0.0),
            )

    if graph is None:
        return

    cap_by_id = {c.capabilityId: c for c in pool}
    bindings: list[tuple[str, str]] = []
    for node in graph.nodes:
        ref = node.capabilityRef
        if not ref or not ref.capabilityId:
            continue
        if ref.capabilityId.startswith("GENERATE:"):
            continue
        bindings.append((node.nodeId, ref.capabilityId))

    distinct_ids = {cid for _, cid in bindings}
    logger.info(
        "%s selection_summary node_bindings=%d distinct_capabilities=%d",
        log_prefix,
        len(bindings),
        len(distinct_ids),
    )
    for node_id, cid in bindings:
        cap = cap_by_id.get(cid)
        if cap is not None:
            logger.info(
                "%s selected nodeId=%s id=%s name=%r score=%.4f",
                log_prefix,
                node_id,
                cid,
                cap.name,
                float(getattr(cap, "capabilityScore", 0.0) or 0.0),
            )
        else:
            logger.info(
                "%s selected nodeId=%s id=%s name=%r score=n/a (not in global pool)",
                log_prefix,
                node_id,
                cid,
                "(unknown)",
            )


# ============================================================================
# STEP 6s — STRUCTURAL VALIDATOR (pure Python, no LLM)
# ============================================================================

def _validate_graph_structure(
    graph: GraphDefinition,
) -> tuple[GraphDefinition, list[GraphValidationError]]:
    """
    Step 6s — Pure-Python structural validator.

    Auto-fixes what it can deterministically (wrong entryNodeId/endNodeId,
    'END' edge normalisation).  Returns the (possibly auto-fixed) graph and
    the list of structural errors that could NOT be fixed programmatically.
    """
    errors: list[GraphValidationError] = []
    graph = graph.model_copy(deep=True)

    node_ids = {n.nodeId for n in graph.nodes}

    # ── Auto-fix helpers ────────────────────────────────────────────────────
    def _entry_candidates() -> list[str]:
        """Nodes with no incoming edges (excluding end-type nodes)."""
        has_incoming = {e.to for e in graph.edges}
        return [
            n.nodeId for n in graph.nodes
            if n.nodeId not in has_incoming and n.type != "end"
        ]

    def _infer_entry() -> Optional[str]:
        candidates = _entry_candidates()
        return candidates[0] if len(candidates) == 1 else None

    def _end_candidates() -> list[str]:
        return [n.nodeId for n in graph.nodes if n.type == "end"]

    def _infer_end() -> Optional[str]:
        candidates = _end_candidates()
        if len(candidates) == 1:
            return candidates[0]
        if "end_node" in node_ids:
            return "end_node"
        return None

    # ── 1. Fix entryNodeId ──────────────────────────────────────────────────
    if graph.entryNodeId not in node_ids:
        fixed = _infer_entry()
        if fixed:
            errors.append(GraphValidationError(
                nodeId="graph",
                errorType="structural",
                field="entryNodeId",
                message=f"entryNodeId '{graph.entryNodeId}' not in nodes; auto-corrected to '{fixed}'.",
                autoFixed=True,
            ))
            graph.entryNodeId = fixed
        else:
            candidates = _entry_candidates()
            errors.append(GraphValidationError(
                nodeId="graph",
                errorType="structural",
                field="entryNodeId",
                message=(
                    f"entryNodeId '{graph.entryNodeId}' not in nodes and cannot be "
                    f"inferred automatically. "
                    f"Entry candidates (no incoming, non-end): {sorted(candidates)}. "
                    f"Node IDs: {sorted(node_ids)}."
                ),
            ))

    # ── 2b. Flag ambiguous entry even if entryNodeId is present ─────────────
    entry_candidates = _entry_candidates()
    if len(entry_candidates) > 1:
        errors.append(GraphValidationError(
            nodeId="graph",
            errorType="structural",
            field="entryNodeId",
            message=(
                "Ambiguous entry: multiple nodes have no incoming edges "
                f"(excluding end nodes): {sorted(entry_candidates)}. "
                "Set entryNodeId explicitly or connect the graph so only one entry remains."
            ),
        ))

    # ── 2. Fix endNodeId ────────────────────────────────────────────────────
    if graph.endNodeId not in node_ids:
        fixed = _infer_end()
        if fixed:
            errors.append(GraphValidationError(
                nodeId="graph",
                errorType="structural",
                field="endNodeId",
                message=f"endNodeId '{graph.endNodeId}' not in nodes; auto-corrected to '{fixed}'.",
                autoFixed=True,
            ))
            graph.endNodeId = fixed
        else:
            candidates = _end_candidates()
            errors.append(GraphValidationError(
                nodeId="graph",
                errorType="structural",
                field="endNodeId",
                message=(
                    f"endNodeId '{graph.endNodeId}' not in nodes and cannot be "
                    f"inferred automatically. "
                    f"End candidates (type=end): {sorted(candidates)}. "
                    f"Node IDs: {sorted(node_ids)}."
                ),
            ))

    # ── 2b. Flag ambiguous end even if endNodeId is present ─────────────────
    end_candidates = _end_candidates()
    if len(end_candidates) > 1:
        errors.append(GraphValidationError(
            nodeId="graph",
            errorType="structural",
            field="endNodeId",
            message=(
                "Ambiguous end: multiple nodes are marked as type 'end': "
                f"{sorted(end_candidates)}. "
                "Set endNodeId explicitly and ensure only one end node exists."
            ),
        ))

    # ── 3. Normalise 'END' / 'end_node' edge targets AFTER endNodeId fix ───
    # At this point, if we have a resolvable end node, rewrite sentinel edge targets
    # to that concrete node ID to avoid stale normalization.
    actual_end = graph.endNodeId if graph.endNodeId in node_ids else _infer_end()
    if actual_end:
        for edge in graph.edges:
            if edge.to in ("END", "end_node") and edge.to != actual_end:
                edge.to = actual_end

    # ── 4. Edge endpoint existence ──────────────────────────────────────────
    # Only allow sentinel targets if we truly cannot resolve an end node.
    valid_edge_targets = node_ids | ({"end_node", "END"} if not actual_end else set())
    for edge in graph.edges:
        if edge.fromNode not in node_ids:
            errors.append(GraphValidationError(
                nodeId=edge.fromNode,
                errorType="structural",
                field=f"edge:{edge.fromNode}→{edge.to}",
                message=f"Edge source '{edge.fromNode}' does not exist in nodes.",
            ))
        if edge.to not in valid_edge_targets:
            errors.append(GraphValidationError(
                nodeId=edge.fromNode,
                errorType="structural",
                field=f"edge:{edge.fromNode}→{edge.to}",
                message=(
                    f"Edge target '{edge.to}' does not exist in nodes. "
                    f"Valid IDs: {sorted(node_ids)}."
                ),
            ))

    # ── 5. Router target existence ──────────────────────────────────────────
    for node in graph.nodes:
        if not node.config or not node.config.router:
            continue
        r = node.config.router
        for rule in (r.routingRules or []):
            if rule.targetNodeId not in node_ids:
                errors.append(GraphValidationError(
                    nodeId=node.nodeId,
                    errorType="structural",
                    field=f"routingRule.targetNodeId={rule.targetNodeId}",
                    message=(
                        f"Router node '{node.nodeId}' rule targets '{rule.targetNodeId}' "
                        f"which does not exist. Valid IDs: {sorted(node_ids)}."
                    ),
                ))
        if r.defaultTarget and r.defaultTarget not in node_ids:
            errors.append(GraphValidationError(
                nodeId=node.nodeId,
                errorType="structural",
                field="router.defaultTarget",
                message=(
                    f"Router '{node.nodeId}' defaultTarget '{r.defaultTarget}' not in nodes."
                ),
            ))
        if r.fallbackTarget and r.fallbackTarget not in node_ids:
            errors.append(GraphValidationError(
                nodeId=node.nodeId,
                errorType="structural",
                field="router.fallbackTarget",
                message=(
                    f"Router '{node.nodeId}' fallbackTarget '{r.fallbackTarget}' not in nodes."
                ),
            ))

    # ── 6. Orphan detection (no outgoing edge for non-end nodes) ───────────
    nodes_with_outgoing = {e.fromNode for e in graph.edges}
    for node in graph.nodes:
        if node.type == "end":
            continue
        if node.nodeId not in nodes_with_outgoing:
            errors.append(GraphValidationError(
                nodeId=node.nodeId,
                errorType="structural",
                field="edges",
                message=(
                    f"Node '{node.nodeId}' (type={node.type}) has no outgoing edges "
                    f"and is not the end node."
                ),
            ))

    # ── 7. Unreachable nodes (no incoming edge for non-entry nodes) ────────
    nodes_with_incoming = {e.to for e in graph.edges} | {graph.entryNodeId}
    for node in graph.nodes:
        if node.nodeId == graph.entryNodeId:
            continue
        if node.nodeId not in nodes_with_incoming:
            errors.append(GraphValidationError(
                nodeId=node.nodeId,
                errorType="structural",
                field="edges",
                message=(
                    f"Node '{node.nodeId}' (type={node.type}) has no incoming edges "
                    f"and is not the entry node — it is unreachable."
                ),
            ))

    return graph, errors

# ============================================================================
# STEP 6s (repair) — STRUCTURAL REPAIR LLM CALL (targeted patches)
# ============================================================================

async def _repair_graph_structure_with_llm(
    graph: GraphDefinition,
    errors: list[GraphValidationError],
    global_caps: list[StepCapabilityCandidate],
    steps: Optional[list[LogicalStep]] = None,
    *,
    project_id: Optional[str] = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    api_key: Optional[str] = None,
) -> GraphDefinition:
    """
    Step 6s (repair) — Ask the LLM to return targeted structural patches.

    Uses GraphStructuralPatchResult (typed patch ops), NOT full regeneration,
    to preserve all valid bindings the planner already produced.
    """
    if api_key is None:
        api_key = get_gemini_api_key()
    node_ids = sorted(n.nodeId for n in graph.nodes)
    steps_summary = ""
    if steps:
        steps_summary = "\n".join(
            f"  - {s.stepId}: {s.name} — {s.description}"
            for s in steps
        )
    else:
        steps_summary = "  (not provided)"
    node_summary = "\n".join(
        f"  • {n.nodeId} (type={n.type}, cap={n.capabilityRef.capabilityId if n.capabilityRef else 'none'})"
        for n in graph.nodes
    )
    edges_summary = "\n".join(
        f"  • {e.fromNode} → {e.to} (kind={e.kind})" for e in graph.edges
    ) or "  (none)"
    errors_text = "\n".join(f"  - {e.message}" for e in errors)

    prompt = f"""You are fixing structural issues in a LangGraph capability graph.

REQUIREMENT STEPS (intent):
{steps_summary}

GRAPH NODES:
{node_summary}

GRAPH EDGES:
{edges_summary}

Current entryNodeId: {graph.entryNodeId!r}
Current endNodeId:   {graph.endNodeId!r}

STRUCTURAL ERRORS TO FIX:
{errors_text}

Return a list of targeted patch operations to fix the issues above.
Available ops:
  set_entry_node_id  → set value to the correct entry node ID
  set_end_node_id    → set value to the correct end node ID
  add_edge           → add a missing edge (fromNode, toNode, edgeKind)
  remove_edge        → remove a bad edge (fromNode, toNode)
  set_router_default_target → set nodeId router's defaultTarget to value
  set_router_fallback_target → set nodeId router's fallbackTarget to value

Only use node IDs from the list above. Do NOT invent new nodes.
Return patches in the specified JSON schema."""

    started_at = datetime.utcnow()
    try:
        response = await async_generate(
            "gemini-3-flash-preview",
            prompt,
            config=GeminiGenerateConfig(
                temperature=0.1,
                response_mime_type="application/json",
                response_schema=GraphStructuralPatchResult,
            ),
            api_key=api_key,
        )
        finished_at = datetime.utcnow()
        usage = extract_token_usage_from_response(response)
        record_llm_call(
            project_id=project_id, org_id=org_id,
            subscriber_id=subscriber_id, user_id=user_id,
            operation="graph-validation", sub_operation="repair-graph-structure",
            model="gemini-3-flash-preview",
            prompt_tokens=int(usage.get("prompt_tokens", 0) or 0),
            completion_tokens=int(usage.get("completion_tokens", 0) or 0),
            total_tokens=int(usage.get("total_tokens", 0) or 0),
            status="success", attempt=1, is_retry=False,
            started_at=started_at, finished_at=finished_at,
            metadata={"graph_id": graph.graphId, "error_count": len(errors)},
        )
        patch_result: GraphStructuralPatchResult = response.parsed
        graph = _apply_structural_patches(graph, patch_result.patches)
    except Exception as e:
        finished_at = datetime.utcnow()
        record_llm_call(
            project_id=project_id, org_id=org_id,
            subscriber_id=subscriber_id, user_id=user_id,
            operation="graph-validation", sub_operation="repair-graph-structure",
            model="gemini-3-flash-preview",
            prompt_tokens=0, completion_tokens=0, total_tokens=0,
            status="failed", attempt=1, is_retry=False,
            started_at=started_at if "started_at" in locals() else None,
            finished_at=finished_at,
            metadata={"graph_id": graph.graphId, "error": str(e)},
        )
        logger.warning(f"[6s] Structural repair LLM error for graph '{graph.graphId}': {e}")

    return graph


def _apply_structural_patches(
    graph: GraphDefinition,
    patches: list[GraphStructuralPatch],
) -> GraphDefinition:
    """Apply a list of structural patches to a deep copy of the graph."""
    graph = graph.model_copy(deep=True)
    node_ids = {n.nodeId for n in graph.nodes}

    for patch in patches:
        op = patch.op
        try:
            if op == "set_entry_node_id":
                if patch.value in node_ids:
                    graph.entryNodeId = patch.value
                    logger.info(f"[6s patch] entryNodeId → '{patch.value}'")
                else:
                    logger.warning(f"[6s patch] set_entry_node_id: '{patch.value}' not in nodes, skipped.")

            elif op == "set_end_node_id":
                if patch.value in node_ids:
                    graph.endNodeId = patch.value
                    logger.info(f"[6s patch] endNodeId → '{patch.value}'")
                else:
                    logger.warning(f"[6s patch] set_end_node_id: '{patch.value}' not in nodes, skipped.")

            elif op == "add_edge":
                if patch.fromNode in node_ids and (patch.toNode in node_ids or patch.toNode in ("end_node", "END")):
                    existing = any(e.fromNode == patch.fromNode and e.to == patch.toNode for e in graph.edges)
                    if not existing:
                        graph.edges.append(GraphEdge(
                            fromNode=patch.fromNode,
                            to=patch.toNode,
                            kind=patch.edgeKind or "sequential",
                        ))
                        logger.info(f"[6s patch] add_edge {patch.fromNode} → {patch.toNode}")
                else:
                    logger.warning(f"[6s patch] add_edge: node(s) not found ({patch.fromNode}→{patch.toNode}), skipped.")

            elif op == "remove_edge":
                before = len(graph.edges)
                graph.edges = [
                    e for e in graph.edges
                    if not (e.fromNode == patch.fromNode and e.to == patch.toNode)
                ]
                logger.info(f"[6s patch] remove_edge {patch.fromNode}→{patch.toNode}: removed {before - len(graph.edges)}")

            elif op in ("set_router_default_target", "set_router_fallback_target"):
                for node in graph.nodes:
                    if node.nodeId == patch.nodeId and node.config and node.config.router:
                        if op == "set_router_default_target":
                            node.config.router.defaultTarget = patch.value
                        else:
                            node.config.router.fallbackTarget = patch.value
                        logger.info(f"[6s patch] {op} on '{patch.nodeId}' → '{patch.value}'")

        except Exception as ex:
            logger.warning(f"[6s patch] op='{op}' failed: {ex}")

    return graph


def _format_tool_spec_for_context(c: StepCapabilityCandidate) -> str:
    """Format one capability (tool/screen) with full input/output params for LLM context."""
    def fmt_params(params: list[Dict[str, Any]]) -> str:
        if not params:
            return "  (none)"
        return "\n".join(
            f"    - name: {p.get('name', '')}, dataType: {p.get('dataType', '')}, "
            f"required: {p.get('required', False)}, description: {(p.get('description') or '')[:100]}"
            for p in params
        )
    in_block = fmt_params(c.inputParameters or [])
    out_block = fmt_params(c.outputParameters or [])
    # Persistence summary (optional)
    ds_lines: list[str] = []
    for ds in (c.dataStores or []):
        if not isinstance(ds, dict):
            continue
        st = ds.get("storeType") or "unknown"
        reads = ds.get("readCollections") or []
        writes = ds.get("writeCollections") or []
        cols = ds.get("collections") or []
        ds_lines.append(
            f"    - storeType: {st}, reads: {reads}, writes: {writes}, collections: {cols}"
        )
    ds_block = "\n".join(ds_lines) if ds_lines else "  (none)"
    # Collection schema snapshot (optional). Keep it compact.
    cs_preview: Dict[str, Any] = {}
    try:
        if isinstance(c.collectionSchemas, dict):
            for coll_name, meta in c.collectionSchemas.items():
                if not isinstance(meta, dict):
                    continue
                fields = meta.get("fields")
                if isinstance(fields, dict):
                    # truncate to first ~30 fields for prompt size
                    items = list(fields.items())[:30]
                    cs_preview[str(coll_name)] = {"fields": dict(items), "sampled": bool(meta.get("sampled", False))}
                else:
                    cs_preview[str(coll_name)] = {"fields": {}, "sampled": bool(meta.get("sampled", False))}
    except Exception:
        cs_preview = {}
    cs_block = json.dumps(cs_preview, indent=2) if cs_preview else "  (none)"
    return (
        f"  • {c.capabilityId} (kind={c.kind})\n"
        f"    name: {c.name}\n"
        f"    description: {c.description[:200]}\n"
        f"    dataStores:\n{ds_block}\n"
        f"    collectionSchemas:\n{cs_block}\n"
        f"    inputParameters:\n{in_block}\n"
        f"    outputParameters:\n{out_block}"
    )


# ============================================================================
# STEP 6a — _collect_graph_issues  (pure Python, programmatic-first)
# ============================================================================

def _prior_phase_output_names(outs: Optional[list]) -> set:
    """Normalize prior_phase_outputs value to a set of param names (legacy str or metadata dict)."""
    if not outs:
        return set()
    names: set = set()
    for item in outs:
        if isinstance(item, dict):
            n = item.get("name")
            if n:
                names.add(n)
        elif item:
            names.add(str(item))
    return names


def _declared_outputs_as_prior_phase_entries(node: Any) -> list:
    """
    Build rich prior-phase handoff entries from a node's declaredOutputs
    (fallback: generation.outputs). Each entry is
    {name, datatype, description} so later phases can select/bind with context.
    Legacy consumers that only need names can use _prior_phase_output_names.
    """
    declared: list = []
    cfg = getattr(node, "config", None)
    if cfg is not None:
        declared = list(getattr(cfg, "declaredOutputs", None) or [])
        if not declared:
            gen = getattr(cfg, "generation", None)
            if gen is not None:
                declared = list(getattr(gen, "outputs", None) or [])
    entries: list = []
    for o in declared:
        if isinstance(o, dict):
            name = o.get("name") or ""
            if not name:
                continue
            dtype = o.get("dataType") or o.get("datatype") or "Any"
            desc = o.get("description") or ""
        else:
            name = getattr(o, "name", None) or ""
            if not name:
                continue
            dtype = (
                getattr(o, "dataType", None)
                or getattr(o, "datatype", None)
                or "Any"
            )
            desc = getattr(o, "description", None) or ""
        entry = {
            "name": name,
            "datatype": dtype or "Any",
            "description": desc or "",
        }
        entry.update(_list_item_io_fields(o))
        entries.append(entry)
    return entries


def _log_binding_audit(event: str, **fields: Any) -> None:
    """Grep-friendly audit log — search logs with: grep '[binding-audit]'."""
    parts: list[str] = []
    for key in sorted(fields.keys()):
        val = fields[key]
        if isinstance(val, (list, dict)):
            try:
                s = json.dumps(val, ensure_ascii=False, default=str)
            except Exception:
                s = str(val)
            if len(s) > 4000:
                s = s[:4000] + "..."
            parts.append(f"{key}={s}")
        else:
            parts.append(f"{key}={val!r}")
    logger.info(f"[binding-audit] {event} | " + " ".join(parts))


def _log_prior_phase_handoff_update(
    *,
    completed_phase_id: str,
    next_phase_id: str,
    prior_phase_outputs: dict,
    context: str,
) -> None:
    """Log rich cross-phase registry after a phase completes."""
    summary: list[dict] = []
    for node_id, entries in (prior_phase_outputs or {}).items():
        if not entries:
            continue
        for item in entries:
            if isinstance(item, dict):
                summary.append({
                    "sourceNode": node_id,
                    "name": item.get("name"),
                    "datatype": item.get("datatype") or item.get("dataType"),
                    "description": (item.get("description") or "")[:120],
                })
            else:
                summary.append({
                    "sourceNode": node_id,
                    "name": str(item),
                    "datatype": "Any",
                    "description": "",
                })
    _log_binding_audit(
        "prior_phase_handoff_updated",
        completedPhase=completed_phase_id,
        nextPhase=next_phase_id,
        context=context,
        outputCount=len(summary),
        outputs=summary,
    )


def _summarize_graph_definition_bindings(graph: "GraphDefinition") -> list[dict]:
    """Compact binding summary from GraphDefinition for audit logs."""
    rows: list[dict] = []
    for node in graph.nodes:
        if not node.nodeId or node.config is None:
            continue
        gen = node.config.generation
        required_names: set = set()
        if gen and gen.inputs:
            required_names = {
                ip.name for ip in gen.inputs if ip.required and ip.name
            }
        bindings = node.config.inputBindings or {}
        for pname, val in bindings.items():
            val_s = str(val or "")
            inner = val_s.strip("{} ").strip() if val_s else ""
            if "pick:" in inner:
                kind = "pick"
            elif inner.startswith("global."):
                kind = "global"
            elif inner:
                kind = "node"
            elif pname in required_names:
                kind = "EMPTY_REQUIRED"
            else:
                kind = "optional_empty"
            rows.append({
                "nodeId": node.nodeId,
                "param": pname,
                "required": pname in required_names,
                "kind": kind,
                "binding": val_s or None,
            })
        for pname in required_names:
            if pname not in bindings:
                rows.append({
                    "nodeId": node.nodeId,
                    "param": pname,
                    "required": True,
                    "kind": "MISSING_REQUIRED",
                    "binding": None,
                })
    return rows


def _prior_phase_binding_is_valid(
    prior_phase_outputs: Optional[Dict[str, list]],
    ref_node_id: str,
    ref_param: str,
) -> bool:
    """
    True if ref_node_id.ref_param can come from a completed prior phase
    (keys match codegen: canonical nodeId with non-word chars → '_').
    """
    if not prior_phase_outputs:
        return False
    canon = re.sub(r"[^a-zA-Z0-9_]", "_", ref_node_id)
    for key in (ref_node_id, canon):
        outs = prior_phase_outputs.get(key)
        if outs is None:
            continue
        if not outs:
            return True
        return ref_param in _prior_phase_output_names(outs)
    return False


def _collect_graph_issues(
    graph: GraphDefinition,
    global_caps: list[StepCapabilityCandidate],
    prior_phase_outputs: Optional[Dict[str, list]] = None,
) -> tuple[GraphDefinition, list[GraphValidationError]]:
    """
    Step 6a — Comprehensive programmatic graph validator.

    Applies every fix that can be derived deterministically from the capability
    registry without calling an LLM:
      A. Auto-correct declaredOutputs for existing tool nodes (registry is authoritative).
      B. Auto-populate declaredOutputs for GENERATE nodes from generation.outputs.
      C. Validate binding keys (do NOT rename programmatically).
      D. Detect missing required inputs (emit error — LLM must pick correct source).
      E. Validate {{nodeId.param}} references + dataType compatibility (emit errors).
      F. Scan router conditions for bad refs (emit errors).
      G. Inventory {{global.X}} references → graph.requiredGlobalInputs + typo detection.

    Returns (auto_fixed_graph, remaining_errors_for_llm).
    Only errors with autoFixed=False are returned; auto-fixed items are already
    applied to the returned graph.
    """
    graph = graph.model_copy(deep=True)
    errors: list[GraphValidationError] = []

    # ── Build capability lookups ─────────────────────────────────────────────
    caps_used = _get_capabilities_used_in_graph(graph, global_caps)
    cap_in_params:  Dict[str, Dict[str, Dict]] = {}
    cap_out_params: Dict[str, Dict[str, Dict]] = {}
    for c in caps_used:
        cid = c.capabilityId
        if cid not in cap_in_params:
            cap_in_params[cid]  = {p["name"]: p for p in (c.inputParameters  or [])}
            cap_out_params[cid] = {p["name"]: p for p in (c.outputParameters or [])}

    # ── A+B. Fix declaredOutputs ─────────────────────────────────────────────
    for node in graph.nodes:
        if node.type in ("router", "fallback_router", "end"):
            continue
        cap_ref = node.capabilityRef
        if cap_ref and not cap_ref.capabilityId.startswith("GENERATE:"):
            # A: Existing tool — replace with authoritative registry outputs.
            registry_outs = cap_out_params.get(cap_ref.capabilityId, {})
            if registry_outs:
                current_names = {p.name for p in (node.config.declaredOutputs or [])}
                registry_names = set(registry_outs.keys())
                if current_names != registry_names:
                    node.config.declaredOutputs = [
                        _generation_io_param_from_any(pmeta, name=pname)
                        for pname, pmeta in registry_outs.items()
                    ]
                    if current_names:
                        errors.append(GraphValidationError(
                            nodeId=node.nodeId,
                            errorType="bad_declared_output",
                            field="declaredOutputs",
                            message=(
                                f"declaredOutputs corrected from {sorted(current_names)} "
                                f"to registry values {sorted(registry_names)} "
                                f"for capability '{cap_ref.capabilityId}'."
                            ),
                            autoFixed=True,
                        ))
        elif cap_ref and cap_ref.capabilityId.startswith("GENERATE:"):
            # B: GENERATE node — populate declaredOutputs from generation.outputs.
            gen = node.config.generation
            if not node.config.declaredOutputs and gen and gen.outputs:
                node.config.declaredOutputs = list(gen.outputs)

    # Rebuild node_map after declaredOutputs corrections.
    node_map: Dict[str, GraphNode] = {n.nodeId: n for n in graph.nodes}

    # Helper: get valid output names for a node (uses corrected declaredOutputs).
    def _valid_outputs(n: GraphNode) -> list[str]:
        if n.config and n.config.declaredOutputs:
            return [p.name for p in n.config.declaredOutputs if getattr(p, "name", None)]
        return []

    # Helper: get output dataType for a given node + param.
    def _output_dtype(n: GraphNode, param: str) -> str:
        if n.config and n.config.declaredOutputs:
            for p in n.config.declaredOutputs:
                if p.name == param:
                    return p.dataType or "Any"
        if n.capabilityRef and not n.capabilityRef.capabilityId.startswith("GENERATE:"):
            return cap_out_params.get(n.capabilityRef.capabilityId, {}).get(param, {}).get("dataType", "Any")
        return "Any"

    # ── C. Validate binding key names for existing tool nodes ───────────────
    # IMPORTANT: Do not do fuzzy/closest-match renames here. If the key is invalid,
    # keep it as-is and let the LLM repair pick the correct param name.
    for node in graph.nodes:
        cap_ref = node.capabilityRef
        if not cap_ref or cap_ref.capabilityId.startswith("GENERATE:"):
            continue
        in_params = cap_in_params.get(cap_ref.capabilityId, {})
        if not in_params:
            continue

        for key, val in (node.config.inputBindings or {}).items():
            if key not in in_params:
                # Cannot auto-fix — keep original key so LLM can correct it. Do NOT drop.
                errors.append(GraphValidationError(
                    nodeId=node.nodeId,
                    errorType="bad_key",
                    field=key,
                    message=(
                        f"Binding key '{key}' is not a valid inputParameter of "
                        f"'{cap_ref.capabilityId}'. Valid keys: {sorted(in_params.keys())}."
                    ),
                    autoFixed=False,
                ))

    # ── D. Missing required inputs ───────────────────────────────────────────
    # Pre-compute: for each node, which other nodes have an edge pointing to it
    # (i.e., which nodes come before it in the flow).
    edges_to: Dict[str, set] = {}  # nodeId → set of nodeIds that have an edge INTO this node
    for edge in graph.edges:
        edges_to.setdefault(edge.to, set()).add(edge.fromNode)

    def _upstream_node_ids(node_id: str, visited: Optional[set] = None) -> set:
        """BFS/DFS to collect all transitive predecessors of node_id."""
        if visited is None:
            visited = set()
        for pred in edges_to.get(node_id, set()):
            if pred not in visited:
                visited.add(pred)
                _upstream_node_ids(pred, visited)
        return visited

    for node in graph.nodes:
        cap_ref = node.capabilityRef
        if not cap_ref or cap_ref.capabilityId.startswith("GENERATE:"):
            continue
        in_params = cap_in_params.get(cap_ref.capabilityId, {})
        current_keys = set(node.config.inputBindings or {})

        # Build upstream outputs using only nodes that are topological predecessors.
        upstream_ids = _upstream_node_ids(node.nodeId)
        upstream_outputs: list[str] = []
        for other in graph.nodes:
            if other.nodeId not in upstream_ids:
                continue
            for pname in _valid_outputs(other):
                upstream_outputs.append(f"{other.nodeId}.{pname}")
        upstream_str = ", ".join(upstream_outputs) if upstream_outputs else "(none)"

        for pname, pmeta in in_params.items():
            if pmeta.get("required") and pname not in current_keys:
                errors.append(GraphValidationError(
                    nodeId=node.nodeId,
                    errorType="missing_input",
                    field=pname,
                    message=(
                        f"Required input '{pname}' (dataType={pmeta.get('dataType','Any')}) "
                        f"has no binding on node '{node.nodeId}' "
                        f"(capability '{cap_ref.capabilityId}'). "
                        f"Available upstream outputs: {upstream_str}."
                    ),
                    autoFixed=False,
                ))

    # ── D2. Missing bindings for GENERATE nodes' generationInputs ────────────
    # The planner often creates GENERATE nodes with generationInputs but forgets
    # to add corresponding inputBindings. We detect them here and report as errors
    # so the LLM repair loop can fix them with full semantic context.
    # We do NOT auto-bind because multiple upstream nodes may produce identically
    # named outputs (e.g. two different "score" producers) — only the LLM has
    # enough workflow context to pick the correct source.
    for node in graph.nodes:
        cap_ref = node.capabilityRef
        if not cap_ref or not cap_ref.capabilityId.startswith("GENERATE:"):
            continue
        gen = node.config.generation
        if not gen or not gen.inputs:
            continue
        current_keys = set(node.config.inputBindings or {})
        required_gen_inputs = [
            p for p in gen.inputs
            if getattr(p, "name", None) and getattr(p, "required", False)
        ]
        entry_node_id = getattr(graph, "entryNodeId", None)
        upstream_ids = set() if node.nodeId == entry_node_id else _upstream_node_ids(node.nodeId)
        for gen_param in required_gen_inputs:
            pname = gen_param.name
            binding_val = (node.config.inputBindings or {}).get(pname)
            if pname not in current_keys:
                # Build upstream output list for the error message so the repair LLM
                # knows exactly which sources are available.
                upstream_outputs: list[str] = []
                for other in graph.nodes:
                    if other.nodeId not in upstream_ids:
                        continue
                    for op in _valid_outputs(other):
                        upstream_outputs.append(f"{other.nodeId}.{op}")
                if prior_phase_outputs:
                    for pnid, pkeys in prior_phase_outputs.items():
                        for pk in _prior_phase_output_names(pkeys):
                            upstream_outputs.append(f"{pnid}.{pk}")
                upstream_str = ", ".join(upstream_outputs) if upstream_outputs else "(none)"
                errors.append(GraphValidationError(
                    nodeId=node.nodeId,
                    errorType="missing_input",
                    field=pname,
                    message=(
                        f"Required GENERATE input '{pname}' "
                        f"(dataType={getattr(gen_param, 'dataType', 'Any')}) "
                        f"has no binding on GENERATE node '{node.nodeId}'. "
                        f"Available upstream outputs: {upstream_str}."
                    ),
                    autoFixed=False,
                ))
            elif (str(binding_val or "")).strip() == "":
                errors.append(GraphValidationError(
                    nodeId=node.nodeId,
                    errorType="empty_required",
                    field=pname,
                    message=(
                        f"Required GENERATE input '{pname}' on node '{node.nodeId}' "
                        f"has an empty binding. Set to {{{{nodeId.outputParam}}}}, "
                        f"{{{{global.param}}}}, or {{{{pick:nodeA.param,nodeB.param}}}}."
                    ),
                    autoFixed=False,
                ))

    # ── E. {{nodeId.param}} reference validation + dataType check ────────────
    global_refs: list[str] = []

    # E.pre: Detect bare {{param}} references (no node. prefix).
    # Do NOT auto-normalize to {{global.param}} because it can silently introduce
    # semantic bugs (the correct source might be a prior node output).
    _BARE_REF_PATTERN = re.compile(r"\{\{(\w+)\}\}")
    for node in graph.nodes:
        if node.config is None or node.config.inputBindings is None:
            continue
        for param_key, binding_val in list(node.config.inputBindings.items()):
            bv_str = str(binding_val)
            bare_names = _BARE_REF_PATTERN.findall(bv_str)
            # Filter out names that are already part of a valid {{node.param}} pattern
            dotted_names = {m[0] for m in _BINDING_REF_PATTERN.findall(bv_str)}
            for bare in bare_names:
                if bare in dotted_names:
                    continue  # already captured as valid dotted ref — skip
                errors.append(GraphValidationError(
                    nodeId=node.nodeId,
                    errorType="bad_ref",
                    field=param_key,
                    message=(
                        f"Binding '{param_key}' on node '{node.nodeId}' contains bare reference "
                        f"'{{{{{bare}}}}}' without a node prefix. Use '{{{{global.{bare}}}}}' "
                        f"or '{{{{<nodeId>.{bare}}}}}'."
                    ),
                    autoFixed=False,
                ))

    for node in graph.nodes:
        cap_ref = node.capabilityRef
        this_cap_id = cap_ref.capabilityId if cap_ref else ""

        for param_key, binding_val in list((node.config.inputBindings or {}).items()):
            for ref_node_id, ref_param in iter_template_binding_refs(str(binding_val)):
                if ref_node_id == "global":
                    global_refs.append(ref_param)
                    continue

                if ref_node_id not in node_map:
                    # Cross-phase: source lives in a prior phase's graph (same workflow).
                    if _prior_phase_binding_is_valid(
                        prior_phase_outputs, ref_node_id, ref_param
                    ):
                        continue
                    errors.append(GraphValidationError(
                        nodeId=node.nodeId,
                        errorType="bad_ref",
                        field=param_key,
                        message=(
                            f"Binding '{param_key}' references node '{ref_node_id}' which does "
                            f"not exist in this graph. Valid node IDs: {sorted(node_map.keys())}. "
                            f"If this is cross-phase data, the node must appear in prior-phase "
                            f"outputs registry."
                        ),
                        autoFixed=False,
                    ))
                    continue

                ref_node = node_map[ref_node_id]

                # ── Forward-reference check ──────────────────────────────────
                # A binding {{X.param}} on node N is only valid when X is in
                # N's transitive upstream (X must execute before N).  If X is
                # downstream (or unreachable), the binding will crash at runtime
                # because node_outputs['X'] doesn't exist when N runs.
                #
                # Special handling: routers are pass-through lambda nodes with
                # no outputs; they can appear in the "from" side of an edge but
                # never produce data, so skip the ordering check for them.
                #
                # Cycle-aware upstream: graphs with retry loops have cycle-back
                # edges (e.g. error_retry_router → entry_node). A simple DFS on
                # edges_to follows those back-edges and makes downstream nodes
                # appear "upstream" of the entry node — incorrectly allowing
                # forward references. Fix: for the graph's declared entry node,
                # force upstream = {} (nothing is truly upstream of the entry on
                # first execution, regardless of cycle-back edges).
                if ref_node.type not in ("router", "fallback_router", "end"):
                    entry_node_id = getattr(graph, "entryNodeId", None)
                    if node.nodeId == entry_node_id:
                        upstream_of_node = set()  # entry node has no real upstream
                    else:
                        upstream_of_node = _upstream_node_ids(node.nodeId)
                    if ref_node_id not in upstream_of_node:
                        # Auto-fix: if the binding is on a parameter that is
                        # NOT required, drop it silently (common pattern: entry
                        # node binds error_message from a downstream error node
                        # for the retry path, but it's optional so we can strip it).
                        cap_ref_local = node.capabilityRef
                        cap_id_local = cap_ref_local.capabilityId if cap_ref_local else ""
                        is_required = (
                            cap_in_params.get(cap_id_local, {})
                            .get(param_key, {})
                            .get("required", False)
                        )
                        if not is_required:
                            del node.config.inputBindings[param_key]
                            errors.append(GraphValidationError(
                                nodeId=node.nodeId,
                                errorType="bad_ref",
                                field=param_key,
                                message=(
                                    f"Binding '{param_key}' on node '{node.nodeId}' references "
                                    f"'{ref_node_id}' which executes AFTER this node "
                                    f"(forward reference). The parameter is optional — "
                                    f"binding removed automatically."
                                ),
                                autoFixed=True,
                            ))
                        else:
                            errors.append(GraphValidationError(
                                nodeId=node.nodeId,
                                errorType="bad_ref",
                                field=param_key,
                                message=(
                                    f"Binding '{param_key}' on node '{node.nodeId}' references "
                                    f"'{ref_node_id}' which executes AFTER this node "
                                    f"(forward reference — will crash at runtime). "
                                    f"Use a prior node's output or a constant literal instead. "
                                    f"Upstream nodes available: {sorted(upstream_of_node)}."
                                ),
                                autoFixed=False,
                            ))
                        continue

                valid_outs = _valid_outputs(ref_node)
                if valid_outs and ref_param not in valid_outs:
                    ref_cap = ref_node.capabilityRef.capabilityId if ref_node.capabilityRef else "unknown"
                    errors.append(GraphValidationError(
                        nodeId=node.nodeId,
                        errorType="bad_ref",
                        field=param_key,
                        message=(
                            f"Binding '{param_key}' references '{ref_node_id}.{ref_param}' but "
                            f"'{ref_param}' is not in '{ref_node_id}' declaredOutputs "
                            f"(capability '{ref_cap}'). Valid outputs: {valid_outs}."
                        ),
                        autoFixed=False,
                    ))
                    continue

                # dataType compatibility check.
                src_dtype = _output_dtype(ref_node, ref_param)
                dst_dtype = (
                    cap_in_params.get(this_cap_id, {}).get(param_key, {}).get("dataType", "Any")
                    if this_cap_id and not this_cap_id.startswith("GENERATE:") else "Any"
                )
                if (
                    src_dtype not in ("Any", "")
                    and dst_dtype not in ("Any", "")
                    and src_dtype != dst_dtype
                ):
                    errors.append(GraphValidationError(
                        nodeId=node.nodeId,
                        errorType="type_mismatch",
                        field=param_key,
                        message=(
                            f"Type mismatch: node '{node.nodeId}' input '{param_key}' expects "
                            f"'{dst_dtype}' but '{ref_node_id}.{ref_param}' produces '{src_dtype}'. "
                            f"Consider using a different source or adding a type conversion."
                        ),
                        autoFixed=False,
                    ))

        # Also check empty-value bindings for required params (all node types).
        in_params: Dict[str, Dict] = {}
        if cap_ref and not this_cap_id.startswith("GENERATE:"):
            in_params = cap_in_params.get(this_cap_id, {})
        elif cap_ref and this_cap_id.startswith("GENERATE:") and node.config.generation:
            in_params = {
                p.name: {"required": p.required, "dataType": p.dataType}
                for p in (node.config.generation.inputs or [])
                if getattr(p, "name", None)
            }
        if in_params:
            for param_key, binding_val in (node.config.inputBindings or {}).items():
                if (binding_val or "").strip() == "" and in_params.get(param_key, {}).get("required"):
                    errors.append(GraphValidationError(
                        nodeId=node.nodeId,
                        errorType="empty_required",
                        field=param_key,
                        message=(
                            f"Required input '{param_key}' on node '{node.nodeId}' has an empty "
                            f"binding. Set to {{nodeId.outputParam}} or a literal value."
                        ),
                        autoFixed=False,
                    ))

    # ── F. Router condition scanning ─────────────────────────────────────────
    # We scan two forms because:
    #   • {{nodeId.param}} — explicit template refs (checked against node_map)
    #   • bare nodeId.param — what _evaluate_condition actually looks up at runtime
    # Both must reference real nodeIds and declared outputs.
    for node in graph.nodes:
        if not node.config or not node.config.router:
            continue
        for rule in (node.config.router.routingRules or []):
            cond = rule.condition or ""
            if not cond:
                continue

            # Collect refs from both forms; de-duplicate
            template_refs = set(iter_template_binding_refs(cond))
            bare_refs = {
                (nid, param)
                for nid, param in _CONDITION_REF_PATTERN.findall(cond)
                if nid.lower() not in _CONDITION_NON_NODE_TOKENS
            }
            # Union; template refs already validated structurally ({{}} present)
            all_refs = template_refs | bare_refs

            for ref_node_id, ref_param in all_refs:
                if ref_node_id == "global":
                    global_refs.append(ref_param)
                    continue
                if ref_node_id not in node_map:
                    errors.append(GraphValidationError(
                        nodeId=node.nodeId,
                        errorType="bad_router_condition",
                        field=f"condition:{cond}",
                        message=(
                            f"Router '{node.nodeId}' condition references node '{ref_node_id}' "
                            f"which does not exist. "
                            f"Valid node IDs: {sorted(node_map.keys())}. "
                            f"Hint: use the nodeId, never the capabilityId or GENERATE name."
                        ),
                        autoFixed=False,
                    ))
                    continue
                ref_node = node_map[ref_node_id]
                valid_outs = _valid_outputs(ref_node)
                if valid_outs and ref_param not in valid_outs:
                    errors.append(GraphValidationError(
                        nodeId=node.nodeId,
                        errorType="bad_router_condition",
                        field=f"condition:{cond}",
                        message=(
                            f"Router '{node.nodeId}' condition references '{ref_node_id}.{ref_param}' "
                            f"but '{ref_param}' is not in '{ref_node_id}' declaredOutputs. "
                            f"Valid outputs: {valid_outs}."
                        ),
                        autoFixed=False,
                    ))

    # ── G. Global input inventory + typo detection ───────────────────────────
    unique_global_refs = sorted(set(global_refs))
    # Caller start-inputs only. Namespaced prior-phase keys (nodeId.field) resolve
    # from node_outputs, not from the instance start form.
    graph.requiredGlobalInputs = [g for g in unique_global_refs if "." not in g]

    # Typo detection: flag pairs of *caller* global keys that are very similar.
    # Skip namespaced prior-phase keys (nodeId.field) — colliding fields like
    # n1.status vs n2.status differ by 1 character and are not typos.
    bare_global_refs = [g for g in unique_global_refs if "." not in g]
    for i, a in enumerate(bare_global_refs):
        for b in bare_global_refs[i + 1:]:
            dist = sum(x != y for x, y in zip(a.ljust(30), b.ljust(30)))
            if dist <= 2:
                errors.append(GraphValidationError(
                    nodeId="graph",
                    errorType="global_ref",
                    field=f"global.{a} vs global.{b}",
                    message=(
                        f"Possible typo: '{{{{global.{a}}}}}' and '{{{{global.{b}}}}}' "
                        f"are both used in this graph and differ by only {dist} character(s). "
                        f"Verify these are intentionally different keys."
                    ),
                    autoFixed=False,
                ))

    # Return only errors that were NOT auto-fixed (they need LLM repair).
    remaining = [e for e in errors if not e.autoFixed]
    if remaining:
        by_type: dict[str, int] = defaultdict(int)
        for e in remaining:
            by_type[e.errorType] += 1
        _log_binding_audit(
            "collect_graph_issues_remaining",
            graphId=getattr(graph, "graphId", None),
            phaseId=getattr(graph, "phaseId", None),
            total=len(remaining),
            byErrorType=dict(by_type),
            samples=[
                {"nodeId": e.nodeId, "type": e.errorType, "field": e.field, "msg": e.message[:200]}
                for e in remaining[:15]
            ],
            globalRefs=unique_global_refs,
        )
    else:
        _log_binding_audit(
            "collect_graph_issues_clean",
            graphId=getattr(graph, "graphId", None),
            phaseId=getattr(graph, "phaseId", None),
            globalRefs=unique_global_refs,
            bindings=_summarize_graph_definition_bindings(graph),
        )
    return graph, remaining


# ============================================================================
# STEP 6b — _repair_graph_with_llm  (targeted LLM repair, called only when
#            _collect_graph_issues still has unresolved errors)
# ============================================================================

async def _repair_graph_with_llm(
    graph: GraphDefinition,
    errors: list[GraphValidationError],
    user_context: str,
    global_caps: list[StepCapabilityCandidate],
    *,
    prior_phase_outputs: Optional[Dict[str, list]] = None,
    attempt: int = 1,
    max_attempts: int = 3,
    project_id: Optional[str] = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    api_key: Optional[str] = None,
) -> GraphDefinition:
    """
    Step 6b (repair) — Ask the LLM to fix remaining issues that programmatic
    correction (_collect_graph_issues) could not resolve.

    Hardened against:
      - Invalid paramName / nodeId from LLM
      - Bad correctedValue references
      - No post-fix validation
      - Silent partial failure
      - Retry on bad/empty output
      - Over-fixing of already-valid bindings
    """
    # Work on a deep copy per attempt to avoid partial mutation leaks.
    base_graph = graph.model_copy(deep=True)
    graph = base_graph

    if api_key is None:
        api_key = get_gemini_api_key()

    caps_used = _get_capabilities_used_in_graph(graph, global_caps)

    # ── Build node→outputs map (single source of truth) ─────────────────────
    node_outputs_map_lines: list[str] = []

    # Pre-compute: node_id → set of valid output param names (for fix validation)
    valid_node_outputs: Dict[str, set[str]] = {}
    # Pre-compute: node_id → set of valid input param names (for paramName validation)
    valid_node_inputs: Dict[str, set[str]] = {}
    # Pre-compute: node_id → param → dataType for outputs/inputs (type checks)
    valid_node_output_types: Dict[str, Dict[str, str]] = {}
    valid_node_input_types: Dict[str, Dict[str, str]] = {}

    for n in graph.nodes:
        out_names: set[str] = set()
        out_with_types: list[str] = []
        out_types: Dict[str, str] = {}
        for p in (n.config.declaredOutputs or []):
            if getattr(p, "name", None):
                out_names.add(p.name)
                dtype = getattr(p, "dataType", None) or "Any"
                out_types[p.name] = dtype
                out_with_types.append(f"{p.name} ({dtype})")
        valid_node_outputs[n.nodeId] = out_names
        valid_node_output_types[n.nodeId] = out_types

        cap_id = n.capabilityRef.capabilityId if n.capabilityRef else "none"
        node_outputs_map_lines.append(
            f"  • {n.nodeId} (cap={cap_id}): outputs=[{', '.join(out_with_types) or 'none'}]"
        )

    # Allow bindingFix correctedValue to reference prior-phase nodeIds (runtime
    # node_outputs keys) — same registry as _collect_graph_issues cross-phase check.
    if prior_phase_outputs:
        for _pnid, _pkeys in prior_phase_outputs.items():
            _ks = _prior_phase_output_names(_pkeys)
            valid_node_outputs.setdefault(_pnid, set()).update(_ks)

    # Build valid input param names per node from capability specs
    cap_by_id: Dict[str, StepCapabilityCandidate] = {c.capabilityId: c for c in caps_used}
    for n in graph.nodes:
        cap_id = n.capabilityRef.capabilityId if n.capabilityRef else None
        cap = cap_by_id.get(cap_id) if cap_id else None
        if cap and hasattr(cap, "inputParameters"):
            valid_node_inputs[n.nodeId] = {p.name for p in (cap.inputParameters or []) if getattr(p, "name", None)}
            valid_node_input_types[n.nodeId] = {
                p.name: (getattr(p, "dataType", None) or "Any")
                for p in (cap.inputParameters or [])
                if getattr(p, "name", None)
            }
        else:
            valid_node_inputs[n.nodeId] = set()
            valid_node_input_types[n.nodeId] = {}

    # Prepend prior-phase outputs so the repair LLM knows cross-phase references
    # are valid. These are keyed the same way as node_outputs at runtime, so
    # {{nodeId.param}} bindings referencing them are structurally correct.
    if prior_phase_outputs:
        prior_output_lines = []
        for nid, keys in prior_phase_outputs.items():
            if not keys:
                continue
            pretty = []
            for k in keys:
                if isinstance(k, dict):
                    name = k.get("name") or ""
                    dtype = k.get("datatype") or k.get("dataType") or "Any"
                    if name:
                        pretty.append(f"{name}:{dtype}")
                else:
                    pretty.append(str(k))
            if pretty:
                prior_output_lines.append(
                    f"  [PRIOR PHASE] • {nid}: outputs=[{', '.join(pretty)}]"
                )
        prior_output_block = "\n".join(prior_output_lines)
        node_outputs_map_lines = [prior_output_block] + node_outputs_map_lines

    node_outputs_map = "\n".join(node_outputs_map_lines) or "  (no nodes)"

    # ── Graph connectivity context (edges + execution order) ────────────────
    node_ids_set: set[str] = {n.nodeId for n in graph.nodes}
    edges_summary = "\n".join(
        f"  • {e.fromNode} → {e.to} (kind={getattr(e, 'kind', 'sequential')})"
        for e in (graph.edges or [])
        if getattr(e, "fromNode", None) in node_ids_set and getattr(e, "to", None) in node_ids_set
    ) or "  (none)"

    # Best-effort topological execution order (routers/cycles may prevent full ordering).
    # We compute an order that is stable and starts from entryNodeId when possible.
    adjacency: Dict[str, set[str]] = {nid: set() for nid in node_ids_set}
    indeg: Dict[str, int] = {nid: 0 for nid in node_ids_set}
    for e in (graph.edges or []):
        frm = getattr(e, "fromNode", None)
        to = getattr(e, "to", None)
        if frm in node_ids_set and to in node_ids_set and to not in adjacency.get(frm, set()):
            adjacency[frm].add(to)
            indeg[to] += 1

    # Kahn with deterministic ordering.
    ready = sorted([nid for nid, d in indeg.items() if d == 0])
    exec_order: list[str] = []
    while ready:
        # Prefer entry node early if it is available.
        if graph.entryNodeId in ready:
            nid = graph.entryNodeId
            ready.remove(nid)
        else:
            nid = ready.pop(0)
        exec_order.append(nid)
        for nxt in sorted(adjacency.get(nid, set())):
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                ready.append(nxt)
                ready.sort()

    remaining = sorted([nid for nid in node_ids_set if nid not in exec_order])
    if remaining:
        exec_order.extend(remaining)

    execution_order_text = "\n".join(
        f"  {i}. {nid}" for i, nid in enumerate(exec_order, start=1)
    ) or "  (none)"

    # ── Tool registry context ────────────────────────────────────────────────
    tools_context = "\n\n".join(_format_tool_spec_for_context(c) for c in caps_used)
    if not tools_context:
        tools_context = "  (no existing tools in graph; only GENERATE nodes or end node.)"

    # ── Snapshot of current valid bindings (anti-over-fix) ──────────────────
    # We'll protect bindings that are already error-free from being changed.
    errored_node_params: set[tuple[str, str]] = set()
    for e in errors:
        if e.nodeId and e.field:
            errored_node_params.add((e.nodeId, e.field))

    # ── Format errors by type ────────────────────────────────────────────────
    binding_errors = [
        e for e in errors
        if e.errorType in ("bad_ref", "bad_key", "type_mismatch", "missing_input", "empty_required")
    ]
    router_errors = [e for e in errors if e.errorType == "bad_router_condition"]
    other_errors  = [e for e in errors if e not in binding_errors and e not in router_errors]

    def _fmt_errors(errs: list[GraphValidationError]) -> str:
        return "\n".join(
            f"  [{e.errorType}] node='{e.nodeId}' field='{e.field}' → {e.message.replace('global.', 'system.')}"
            for e in errs
        ) or "  (none)"

    allowed_binding_targets = "\n".join(
        f"  • nodeId='{e.nodeId}' paramName='{e.field}'"
        for e in binding_errors
        if e.nodeId and e.field
    ) or "  (none — do not produce any bindingFixes)"

    allowed_router_targets = "\n".join(
        f"  • nodeId='{e.nodeId}' (only fix ruleIndex values that correspond to router errors above)"
        for e in router_errors
        if e.nodeId
    ) or "  (none — do not produce any routerConditionFixes)"

    fix_prompt = f"""You are fixing a LangGraph capability graph.

USER CONTEXT (phase goal): {user_context}

GRAPH EDGES (connectivity):
{edges_summary}

EXECUTION ORDER (best-effort topological; may include remaining nodes last if cycles/routers exist):
{execution_order_text}

AVAILABLE NODE OUTPUTS (single source of truth — ONLY these references are valid):
{node_outputs_map}

TOOL REGISTRY SPECS (for existing capabilities):
{tools_context}

BINDING ERRORS TO FIX (bad_ref / bad_key / type_mismatch / missing_input / empty_required):
{_fmt_errors(binding_errors)}

ROUTER CONDITION ERRORS TO FIX (bad_router_condition):
{_fmt_errors(router_errors)}

OTHER ERRORS:
{_fmt_errors(other_errors)}

STRICT INSTRUCTIONS:
  bindingFixes:
    - You MUST ONLY produce fixes for the exact (nodeId, paramName) pairs listed below.
      Any fix for a pair NOT in this list will be rejected by the validator.

    ALLOWED BINDING FIX TARGETS (the ONLY nodeId+paramName pairs you may fix):
{allowed_binding_targets}

    - FORWARD-REF / ORDER RULE: correctedValue MUST NOT reference a node that executes
      AFTER the target node in this graph's flow (check EXECUTION ORDER). A binding is
      only valid when the source node is a transitive predecessor of the target node.
      Examples of fatal bugs:
        • binding on fill_ekyc_form using {{stage_2_step_1_validate_form_data.*}} — validate runs AFTER fill
        • binding on the ENTRY NODE (first node) using ANY node that runs after it
      The entry node can only use: global inputs ({{global.X}}) or literal constants.
      For data from a prior phase, use ONLY "[PRIOR PHASE]" lines in AVAILABLE NODE OUTPUTS.

    - For each fix: correctedValue must use ONLY "{{{{nodeId.outputParamName}}}}" references
      where nodeId.outputParamName appears in AVAILABLE NODE OUTPUTS (including [PRIOR PHASE]).
    - Use a literal string ONLY when the destination param is a scalar type (string/integer/float/boolean)
      AND no upstream output can satisfy it. The literal must be a real, non-placeholder value.
    - paramName MUST exactly match one of the ALLOWED BINDING FIX TARGETS above.
    - nodeId MUST exactly match one of the ALLOWED BINDING FIX TARGETS above.
    - DO NOT produce fixes for bindings that are not in the ALLOWED list, even if you think
      they look wrong. The validator will reject them and they waste tokens.

  routerConditionFixes:
    - You MUST ONLY produce fixes for the exact nodeId values listed below.
      Any fix for a nodeId NOT in this list will be rejected.

    ALLOWED ROUTER FIX TARGETS:
{allowed_router_targets}

    - ONLY reference nodeId.param pairs present in AVAILABLE NODE OUTPUTS, and ONLY in the strict template form "{{{{nodeId.param}}}}".
    - correctedCondition MUST be a valid boolean expression (balanced parentheses, valid syntax).
    - Fix ONLY the broken param reference; preserve the rest of the condition logic exactly.
    - ruleIndex is the 0-based index into the node's routingRules list.

Return ONLY the JSON matching the required schema. No commentary."""

    logger.info(f"[6b] Repair LLM (attempt {attempt}) — {len(errors)} errors, graph='{graph.graphId}'")
    started_at = datetime.utcnow()

    repair: Optional[_LLMRepairResult] = None

    try:
        response = await async_generate(
            "gemini-3-flash-preview",
            fix_prompt,
            config=GeminiGenerateConfig(
                temperature=0.1,
                response_mime_type="application/json",
                response_schema=_LLMRepairResult,
            ),
            api_key=api_key,
        )
        finished_at = datetime.utcnow()
        usage = extract_token_usage_from_response(response)
        record_llm_call(
            project_id=project_id, org_id=org_id,
            subscriber_id=subscriber_id, user_id=user_id,
            operation="graph-validation", sub_operation="repair-graph-bindings",
            model="gemini-3-flash-preview",
            prompt_tokens=int(usage.get("prompt_tokens", 0) or 0),
            completion_tokens=int(usage.get("completion_tokens", 0) or 0),
            total_tokens=int(usage.get("total_tokens", 0) or 0),
            status="success", attempt=attempt, is_retry=attempt > 1,
            started_at=started_at, finished_at=finished_at,
            metadata={
                "graph_id": graph.graphId,
                "error_count": len(errors),
                "binding_errors": len(binding_errors),
                "router_errors": len(router_errors),
            },
        )
        repair = response.parsed
        if repair and repair.bindingFixes:
            for _fix in repair.bindingFixes:
                if _fix.correctedValue and "system." in _fix.correctedValue:
                    _fix.correctedValue = _fix.correctedValue.replace("system.", "global.")
    except BillingError:
        raise

    except BillingError:
        raise
    except Exception as e:
        finished_at = datetime.utcnow()
        record_llm_call(
            project_id=project_id, org_id=org_id,
            subscriber_id=subscriber_id, user_id=user_id,
            operation="graph-validation", sub_operation="repair-graph-bindings",
            model="gemini-3-flash-preview",
            prompt_tokens=0, completion_tokens=0, total_tokens=0,
            status="failed", attempt=attempt, is_retry=attempt > 1,
            started_at=started_at if "started_at" in locals() else None,
            finished_at=finished_at,
            metadata={"graph_id": graph.graphId, "error": str(e)},
        )
        logger.warning(f"[6b] Repair LLM call failed (attempt {attempt}) for graph '{graph.graphId}': {e}")
        return graph  # Return as-is; caller decides retry

    # ── Guard: empty or null repair result ──────────────────────────────────
    if repair is None:
        logger.warning(f"[6b] LLM returned null repair result (attempt {attempt}), graph '{graph.graphId}'")
        if attempt < max_attempts:
            logger.info(f"[6b] Retrying repair (attempt {attempt + 1})…")
            return await _repair_graph_with_llm(
                graph, errors, user_context, global_caps,
                attempt=attempt + 1, max_attempts=max_attempts,
                project_id=project_id, org_id=org_id,
                subscriber_id=subscriber_id, user_id=user_id, api_key=api_key,
            )
        logger.error(f"[6b] Max repair attempts reached for graph '{graph.graphId}', returning as-is.")
        return graph

    no_binding_fixes  = not repair.bindingFixes
    no_router_fixes   = not repair.routerConditionFixes
    has_pending_errors = bool(binding_errors or router_errors)

    if no_binding_fixes and no_router_fixes and has_pending_errors:
        logger.warning(
            f"[6b] LLM returned empty fixes but {len(errors)} errors remain "
            f"(attempt {attempt}), graph '{graph.graphId}'"
        )
        if attempt < max_attempts:
            logger.info(f"[6b] Retrying repair (attempt {attempt + 1})…")
            return await _repair_graph_with_llm(
                graph, errors, user_context, global_caps,
                attempt=attempt + 1, max_attempts=max_attempts,
                project_id=project_id, org_id=org_id,
                subscriber_id=subscriber_id, user_id=user_id, api_key=api_key,
            )

    node_by_id: Dict[str, GraphNode] = {n.nodeId: n for n in graph.nodes}
    # Snapshot unresolved signatures for progress detection (avoid pointless retries)
    pre_unresolved_sig: set[tuple[str, str, str]] = {(e.nodeId, e.field, e.errorType) for e in errors}

    def _dtype_norm(dt: str) -> str:
        dt = (dt or "Any").strip()
        low = dt.lower()
        if low in ("any", ""):
            return "Any"
        if low in ("str", "string", "text"):
            return "string"
        if low in ("int", "integer"):
            return "integer"
        if low in ("float", "double", "decimal", "number"):
            return "float"
        if low in ("bool", "boolean"):
            return "boolean"
        if low in ("dict", "object", "map"):
            return "dict"
        if low in ("list", "array"):
            return "list"
        return dt

    def _dtype_compatible(src: str, dst: str) -> bool:
        """
        Best-effort compatibility. We avoid "smart coercion" and only allow:
          - Any ↔ anything
          - exact match
          - integer → float (numeric widening)
        """
        s = _dtype_norm(src)
        d = _dtype_norm(dst)
        if "Any" in (s, d):
            return True
        if s == d:
            return True
        if s == "integer" and d == "float":
            return True
        return False

    # ── Apply binding fixes with full validation ─────────────────────────────
    applied_binding_fixes = 0
    skipped_binding_fixes = 0

    for fix in (repair.bindingFixes or []):
        # 1. nodeId must be real
        target = node_by_id.get(fix.nodeId)
        if not target:
            logger.warning(f"[6b] bindingFix SKIPPED: node '{fix.nodeId}' does not exist.")
            skipped_binding_fixes += 1
            continue

        # 2. paramName must be a valid input param for this node's capability
        allowed_inputs = valid_node_inputs.get(fix.nodeId, set())
        if allowed_inputs and fix.paramName not in allowed_inputs:
            logger.warning(
                f"[6b] bindingFix SKIPPED: '{fix.paramName}' is not a valid input param "
                f"for node '{fix.nodeId}' (valid: {sorted(allowed_inputs)})."
            )
            skipped_binding_fixes += 1
            continue

        # 3. Over-fix guard — hard reject anything not in the error-derived allowlist
        if (fix.nodeId, fix.paramName) not in errored_node_params:
            logger.error(
                f"[6b] bindingFix REJECTED (over-fix): ({fix.nodeId}, {fix.paramName}) was NOT "
                f"in the error list. LLM ignored the ALLOWED TARGETS constraint. "
                f"Allowed set: {sorted(errored_node_params)}"
            )
            skipped_binding_fixes += 1
            continue

        # 4. If correctedValue is a template ref, validate the reference is real
        corrected = fix.correctedValue
        if isinstance(corrected, str):
            import re
            # {{node.param}}, {{global.field}}, and {{global.nodeId.field}} are valid.
            any_templates = re.findall(r"\{\{([^}]+)\}\}", corrected)
            invalid_refs: list[str] = []
            parsed_refs: list[tuple[str, str]] = []
            for inner in any_templates:
                inner_s = (inner or "").strip()
                if inner_s.startswith("pick:"):
                    continue
                refs = iter_template_binding_refs("{{" + inner_s + "}}")
                if not refs:
                    invalid_refs.append(inner_s)
                    continue
                parsed_refs.extend(refs)

            for ref_node, ref_param in parsed_refs:
                if ref_node == "global":
                    # Global inputs are allowed; types are treated as Any.
                    continue
                if ref_node not in valid_node_outputs:
                    invalid_refs.append(f"{ref_node}.{ref_param}")
                elif ref_param not in valid_node_outputs[ref_node]:
                    invalid_refs.append(f"{ref_node}.{ref_param}")
                else:
                    # Type compatibility check: src output dtype vs dst input dtype.
                    src_dtype = (valid_node_output_types.get(ref_node, {}) or {}).get(ref_param, "Any") or "Any"
                    dst_dtype = (valid_node_input_types.get(fix.nodeId, {}) or {}).get(fix.paramName, "Any") or "Any"
                    if not _dtype_compatible(src_dtype, dst_dtype):
                        invalid_refs.append(f"{ref_node}.{ref_param} (type {src_dtype}→{dst_dtype})")
            if invalid_refs:
                logger.warning(
                    f"[6b] bindingFix SKIPPED: correctedValue '{corrected}' for "
                    f"'{fix.nodeId}.{fix.paramName}' contains invalid refs: {invalid_refs}. "
                    f"Available: { {k: sorted(v) for k, v in valid_node_outputs.items()} }"
                )
                skipped_binding_fixes += 1
                continue

        # ── NEW: literal value guard ─────────────────────────────────────────
        # A value with no {{}} templates is a bare literal.
        # Only accept it if:
        #   (a) the destination param's dataType is a scalar (string/int/float/bool)
        #   (b) the literal is non-empty and parses as that type
        #   (c) it is NOT a suspicious placeholder (e.g. "TODO", "PLACEHOLDER", "your_value")
        if not any_templates:
            dst_dtype = _dtype_norm(
                (valid_node_input_types.get(fix.nodeId, {}) or {}).get(fix.paramName, "Any") or "Any"
            )
            SCALAR_TYPES = {"string", "integer", "float", "boolean", "Any"}
            SUSPICIOUS_LITERALS = {
                "todo", "placeholder", "your_value", "fix_me", "fixme",
                "none", "null", "undefined", "example", "value", "input",
            }

            # Block non-scalar destinations outright — literals can't satisfy dict/list params.
            if dst_dtype not in SCALAR_TYPES:
                logger.warning(
                    f"[6b] bindingFix SKIPPED: literal value '{corrected}' cannot satisfy "
                    f"non-scalar param '{fix.nodeId}.{fix.paramName}' (type={dst_dtype})."
                )
                skipped_binding_fixes += 1
                continue

            # Block empty literals.
            if not corrected.strip():
                logger.warning(
                    f"[6b] bindingFix SKIPPED: empty literal for '{fix.nodeId}.{fix.paramName}'."
                )
                skipped_binding_fixes += 1
                continue

            # Block known placeholder strings (case-insensitive).
            if corrected.strip().lower() in SUSPICIOUS_LITERALS:
                logger.warning(
                    f"[6b] bindingFix SKIPPED: suspicious placeholder literal '{corrected}' "
                    f"for '{fix.nodeId}.{fix.paramName}'."
                )
                skipped_binding_fixes += 1
                continue

            # Type-parse check for typed scalar destinations.
            parse_error: Optional[str] = None
            if dst_dtype == "integer":
                try:
                    int(corrected.strip())
                except ValueError:
                    parse_error = f"cannot parse '{corrected}' as integer"
            elif dst_dtype == "float":
                try:
                    float(corrected.strip())
                except ValueError:
                    parse_error = f"cannot parse '{corrected}' as float"
            elif dst_dtype == "boolean":
                if corrected.strip().lower() not in ("true", "false", "1", "0"):
                    parse_error = f"cannot parse '{corrected}' as boolean"

            if parse_error:
                logger.warning(
                    f"[6b] bindingFix SKIPPED: literal type mismatch for "
                    f"'{fix.nodeId}.{fix.paramName}' ({dst_dtype}): {parse_error}."
                )
                skipped_binding_fixes += 1
                continue

            logger.info(
                f"[6b] bindingFix: literal accepted for '{fix.nodeId}.{fix.paramName}' "
                f"(type={dst_dtype}, value={corrected!r})"
            )
        # ── END literal guard ────────────────────────────────────────────────

        # All checks passed — apply
        if target.config.inputBindings is None:
            target.config.inputBindings = {}
        target.config.inputBindings[fix.paramName] = corrected
        applied_binding_fixes += 1
        logger.info(f"[6b] bindingFix APPLIED: {fix.nodeId}.{fix.paramName} → {corrected!r}")

    # ── Apply router condition fixes with validation ──────────────────────────
    applied_router_fixes = 0
    skipped_router_fixes = 0

    for fix in (repair.routerConditionFixes or []):
        # 1. nodeId must be real and must be a router
        target = node_by_id.get(fix.nodeId)
        if not target or not target.config or not target.config.router:
            logger.warning(f"[6b] routerFix SKIPPED: node '{fix.nodeId}' is not a router or does not exist.")
            skipped_router_fixes += 1
            continue

        # 2. ruleIndex must be in-bounds
        rules = target.config.router.routingRules
        if not (0 <= fix.ruleIndex < len(rules)):
            logger.warning(
                f"[6b] routerFix SKIPPED: ruleIndex {fix.ruleIndex} out of range for "
                f"'{fix.nodeId}' (has {len(rules)} rules)."
            )
            skipped_router_fixes += 1
            continue

        # 3. Over-fix guard: only touch router conditions that were flagged
        if (fix.nodeId, f"routingRules[{fix.ruleIndex}].condition") not in errored_node_params:
            # Fallback: check if nodeId appears in any router error at all
            node_has_router_error = any(e.nodeId == fix.nodeId for e in router_errors)
            if not node_has_router_error:
                logger.warning(
                    f"[6b] routerFix SKIPPED: node '{fix.nodeId}' had no router errors — refusing to over-fix."
                )
                skipped_router_fixes += 1
                continue

        # 4. Validate refs in correctedCondition are real and strictly formatted
        import re
        import ast
        cond = str(fix.correctedCondition or "")
        strict_refs = re.findall(r"\{\{(\w+)\.(\w+)\}\}", cond)
        any_templates = re.findall(r"\{\{([^}]+)\}\}", cond)
        invalid_refs: list[str] = []
        if any_templates and len(strict_refs) != len(any_templates):
            invalid_refs.extend(any_templates)  # includes invalid shapes like a.b.c
        for ref_node, ref_param in strict_refs:
            if ref_node == "global":
                continue
            if ref_node not in valid_node_outputs:
                invalid_refs.append(f"{ref_node}.{ref_param}")
            elif ref_param not in valid_node_outputs[ref_node]:
                invalid_refs.append(f"{ref_node}.{ref_param}")
        if invalid_refs:
            logger.warning(
                f"[6b] routerFix SKIPPED: correctedCondition '{fix.correctedCondition}' for "
                f"'{fix.nodeId}[{fix.ruleIndex}]' contains invalid refs: {invalid_refs}."
            )
            skipped_router_fixes += 1
            continue

        # 5. Basic syntax guard: condition should be a valid boolean expression.
        # Replace all {{node.param}} templates with True and ensure AST parses.
        try:
            scrubbed = re.sub(r"\{\{\w+\.\w+\}\}", "True", cond)
            parsed = ast.parse(scrubbed, mode="eval")
            allowed_nodes = (
                ast.Expression, ast.BoolOp, ast.UnaryOp, ast.BinOp, ast.Compare,
                ast.Name, ast.Load, ast.Constant, ast.And, ast.Or, ast.Not,
                ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.In, ast.NotIn,
                ast.Is, ast.IsNot,
            )
            for n in ast.walk(parsed):
                if not isinstance(n, allowed_nodes):
                    raise ValueError(f"disallowed AST node: {type(n).__name__}")
        except Exception as ex:
            logger.warning(
                f"[6b] routerFix SKIPPED: correctedCondition '{fix.correctedCondition}' for "
                f"'{fix.nodeId}[{fix.ruleIndex}]' is not a safe/valid boolean expression: {ex}"
            )
            skipped_router_fixes += 1
            continue

        # All checks passed — apply
        old_cond = rules[fix.ruleIndex].condition
        rules[fix.ruleIndex].condition = fix.correctedCondition
        applied_router_fixes += 1
        logger.info(
            f"[6b] routerFix APPLIED: {fix.nodeId}[{fix.ruleIndex}] "
            f"'{old_cond}' → '{fix.correctedCondition}'"
        )

    logger.info(
        f"[6b] Repair summary (attempt {attempt}): "
        f"binding fixes applied={applied_binding_fixes} skipped={skipped_binding_fixes}, "
        f"router fixes applied={applied_router_fixes} skipped={skipped_router_fixes}"
    )

    # ── Post-fix validation: re-run issue collector ──────────────────────────
    _, post_fix_errors = _collect_graph_issues(
        graph, global_caps, prior_phase_outputs=prior_phase_outputs
    )
    unresolved = [e for e in post_fix_errors if not getattr(e, "autoFixed", False)]

    if unresolved:
        logger.warning(
            f"[6b] Post-repair validation: {len(unresolved)} errors remain after attempt {attempt}. "
            f"Graph '{graph.graphId}': {[e.errorType for e in unresolved]}"
        )
        # Retry if we still have budget AND made some progress this attempt
        post_unresolved_sig: set[tuple[str, str, str]] = {(e.nodeId, e.field, e.errorType) for e in unresolved}
        made_progress = len(post_unresolved_sig) < len(pre_unresolved_sig)
        if attempt < max_attempts and made_progress:
            logger.info(f"[6b] Progress was made; retrying repair (attempt {attempt + 1})…")
            return await _repair_graph_with_llm(
                graph, unresolved, user_context, global_caps,
                attempt=attempt + 1, max_attempts=max_attempts,
                project_id=project_id, org_id=org_id,
                subscriber_id=subscriber_id, user_id=user_id, api_key=api_key,
            )
        elif attempt < max_attempts and not made_progress:
            logger.warning(
                f"[6b] No progress made on attempt {attempt}; stopping retry to avoid loop. "
                f"Graph '{graph.graphId}' returned with {len(unresolved)} remaining errors."
            )
            # Discard partial mutations from this attempt if they didn't reduce errors.
            return base_graph
        else:
            logger.error(
                f"[6b] Max repair attempts ({max_attempts}) exhausted. "
                f"Graph '{graph.graphId}' has {len(unresolved)} unresolved errors."
            )
    else:
        logger.info(f"[6b] Post-repair validation PASSED — graph '{graph.graphId}' is clean.")

    return graph


# ============================================================================
# STEP 6 — _validate_and_fix_loop  (orchestrator: programmatic → LLM, max 3 rounds)
# ============================================================================

async def _validate_and_fix_loop(
    graph: GraphDefinition,
    user_context: str,
    global_caps: list[StepCapabilityCandidate],
    *,
    prior_phase_outputs: Optional[Dict[str, list]] = None,
    max_rounds: int = 3,
    project_id: Optional[str] = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    api_key: Optional[str] = None,
) -> tuple[GraphDefinition, int, list[GraphValidationError]]:
    """
    Step 6 — Validate → programmatic fix → (if still errors) LLM repair → repeat.

    Round structure:
      1. _collect_graph_issues  — applies all deterministic fixes, returns remaining errors.
      2. If no remaining errors → done (zero or minimal LLM calls).
      3. If errors remain → _repair_graph_with_llm → go to 1 (next round).

    Max rounds = 3. After the loop, any still-remaining errors are returned as warnings.

    Returns (fixed_graph, total_issues_fed_to_llm, remaining_unresolved_errors).
    """
    total_llm_issues = 0
    last_errors: list[GraphValidationError] = []

    for round_num in range(1, max_rounds + 1):
        # Programmatic pass (always runs — free and fast).
        graph, errors = _collect_graph_issues(
            graph, global_caps, prior_phase_outputs=prior_phase_outputs
        )

        if not errors:
            logger.info(
                f"[validate_loop] Graph '{graph.graphId}' clean after "
                f"programmatic pass (round {round_num})."
            )
            last_errors = []
            break

        logger.info(
            f"[validate_loop] Graph '{graph.graphId}': {len(errors)} issue(s) "
            f"after programmatic pass (round {round_num}) → LLM repair."
        )
        last_errors = errors
        total_llm_issues += len(errors)

        graph = await _repair_graph_with_llm(
            graph, errors, user_context, global_caps,
            prior_phase_outputs=prior_phase_outputs,
            attempt=round_num,
            project_id=project_id, org_id=org_id,
            subscriber_id=subscriber_id, user_id=user_id, api_key=api_key,
        )
        # Next iteration of the loop will re-run _collect_graph_issues to verify.

    else:
        # Ran all rounds — do one final programmatic check to report remaining issues.
        graph, last_errors = _collect_graph_issues(
            graph, global_caps, prior_phase_outputs=prior_phase_outputs
        )
        if last_errors:
            logger.warning(
                f"[validate_loop] Graph '{graph.graphId}': {len(last_errors)} issue(s) "
                f"remain after {max_rounds} rounds. Proceeding with warnings."
            )

    return graph, total_llm_issues, last_errors


def _gap_infer_generation_kind(node: GraphNode, gen: GenerationSpec) -> str:
    """Resolve gap generation as backend tool vs UI screen (defaults prefer tool)."""
    k = (gen.kind or "").strip().lower()
    if k in ("tool", "ui_screen"):
        return k
    if node.capabilityRef:
        kr = (node.capabilityRef.kind or "").strip().lower()
        if kr in ("tool", "ui_screen"):
            return kr
    nt = (node.type or "").strip().lower()
    if nt in ("ui_screen", "ui", "screen", "page", "form"):
        return "ui_screen"
    if nt == "tool":
        return "tool"
    return "tool"


