from services.gap_tool_generator import (  # noqa: E402
    GAP_TOOL_GENERATION_MODEL,
    async_gap_tool_llm_call,
    _gap_unique_dynamic_tool_key,
    _gap_generation_io_contract_dict,
    _parse_gap_tool_llm_response,
    _detect_mock_code,
    _validate_gap_tool_executable,
    _build_gap_tool_prompt,
    _generate_gap_tool_and_upsert_capability,
)




class UnresolvedGapGenerationError(Exception):
    """Raised when one or more GENERATE:* nodes could not be resolved to real capabilities."""

    def __init__(
        self,
        *,
        phase_id: Optional[str] = None,
        unresolved: Optional[List[Dict[str, Any]]] = None,
        failures: Optional[Dict[str, str]] = None,
    ) -> None:
        self.phase_id = phase_id
        self.unresolved = unresolved or []
        self.failures = failures or {}
        parts = [
            f"{item.get('nodeId') or 'unknown'}"
            f" ({item.get('capabilityId') or 'no capabilityId'})"
            for item in self.unresolved
        ]
        detail = ", ".join(parts) if parts else "unknown node(s)"
        if phase_id:
            detail = f"phase '{phase_id}': {detail}"
        super().__init__(f"Unresolved gap generation for {detail}")


def _node_needs_gap_resolution(node: GraphNode) -> bool:
    """True when a node still requires gap generation before persistence."""
    cap_id = (node.capabilityRef.capabilityId or "").strip() if node.capabilityRef else ""
    if cap_id.startswith("GENERATE:"):
        return True
    if node.config and node.config.generation:
        return True
    return False


def _collect_unresolved_gap_nodes(graph: GraphDefinition) -> List[Dict[str, Any]]:
    unresolved: List[Dict[str, Any]] = []
    for node in graph.nodes:
        if not _node_needs_gap_resolution(node):
            continue
        cap_id = (node.capabilityRef.capabilityId or "").strip() if node.capabilityRef else ""
        gen = node.config.generation if node.config else None
        unresolved.append({
            "nodeId": node.nodeId,
            "name": node.name,
            "capabilityId": cap_id or None,
            "generationKind": (
                (gen.kind if gen else None)
                or (node.capabilityRef.kind if node.capabilityRef else None)
            ),
            "hasGenerationSpec": gen is not None,
        })
    return unresolved


def _validate_phase_graphs_gaps_resolved(
    phase_results: List[PhaseGraphResult],
    *,
    failures_by_phase: Optional[Dict[str, Dict[str, str]]] = None,
) -> None:
    """
    Fail fast before persisting Process_Configs if any GENERATE:* nodes remain.
    """
    all_unresolved: List[Dict[str, Any]] = []
    for pr in phase_results:
        graph = pr.graph
        phase_id = (graph.phaseId or graph.graphId or "unknown_phase") if graph else "unknown_phase"
        unresolved = _collect_unresolved_gap_nodes(graph) if graph else []
        for item in unresolved:
            item["phaseId"] = phase_id
            item["lastError"] = (failures_by_phase or {}).get(phase_id, {}).get(item.get("nodeId") or "")
            all_unresolved.append(item)

    if not all_unresolved:
        return

    raise HTTPException(
        status_code=422,
        detail={
            "error": "unresolved_gap_generation",
            "message": (
                "One or more GENERATE:* nodes were not resolved to real capabilities. "
                "All gaps must be generated before the workflow can be saved."
            ),
            "unresolvedNodes": all_unresolved[:50],
            "count": len(all_unresolved),
        },
    )


def _ensure_gap_capability_ref(node: GraphNode, gen: GenerationSpec) -> None:
    if node.capabilityRef and not node.capabilityRef.capabilityId.startswith("GENERATE:"):
        return
    if node.capabilityRef:
        return
    raw = (node.name or node.stepId or node.nodeId or "GeneratedCapability").strip()
    pascal = "".join(w[:1].upper() + w[1:] for w in re.split(r"[^a-zA-Z0-9]+", raw) if w)
    inferred = _gap_infer_generation_kind(node, gen)
    node.capabilityRef = GraphCapabilityRef(
        capabilityId=f"GENERATE:{pascal or 'GeneratedCapability'}",
        kind=inferred,
    )


def _apply_gap_resolution_success(
    node: GraphNode,
    *,
    new_cap_id: str,
    capability_kind: str,
    new_version: Optional[str] = None,
    source: Optional[str] = None,
    class_path: Optional[str] = None,
) -> None:
    if not node.capabilityRef:
        node.capabilityRef = GraphCapabilityRef(
            capabilityId=new_cap_id,
            kind=capability_kind,
            version=new_version,
            source=source,
            class_path=class_path,
        )
    else:
        node.capabilityRef.capabilityId = new_cap_id
        node.capabilityRef.kind = capability_kind
        # Pin the version that was actually written so downstream executors
        # load this exact version of the screen/tool instead of falling back
        # to whatever the pointer says is "current" at lookup time.
        if new_version is not None:
            node.capabilityRef.version = new_version
        if source:
            node.capabilityRef.source = source
        if class_path:
            node.capabilityRef.class_path = class_path
    node.type = _canonical_graph_node_type(
        node.type,
        capability_kind=node.capabilityRef.kind,
        node_id=node.nodeId,
    )
    if node.config:
        _ensure_intent_description(node.config)
        intent = (node.config.intentDescription or "").strip()
        gen_desc = _best_intent_description(
            intent,
            (node.config.generation.description if node.config.generation else None),
            node.config.generationDescription,
        )
        node.config.generationDescription = gen_desc or None
        if intent:
            node.config.intentDescription = intent
        elif gen_desc and not _is_generic_io_summary_description(gen_desc):
            node.config.intentDescription = gen_desc
        node.config.generation = None


def _fallback_resolve_unresolved_gap_nodes(graph: GraphDefinition) -> tuple[list[str], list[str]]:
    """Gracefully resolve unresolved gap nodes for update flows when generation fails.

    This keeps workflow updates moving by assigning a safe synthetic capability id
    (ui:* or tool:*) and clearing the generation spec instead of failing the whole
    request with a 422. The caller can continue with warnings instead.
    """
    fallback_ids: list[str] = []
    fallback_warnings: list[str] = []

    for node in graph.nodes:
        if not _node_needs_gap_resolution(node):
            continue

        existing_cap_id = (node.capabilityRef.capabilityId or "").strip() if node.capabilityRef else ""
        assumed_kind = "ui_screen"
        if node.config and node.config.generation:
            assumed_kind = (node.config.generation.kind or "ui_screen").strip() or "ui_screen"

        if existing_cap_id.startswith(("ui:", "tool:")):
            new_cap_id = existing_cap_id
        elif assumed_kind == "tool":
            new_cap_id = f"tool:{(node.nodeId or 'tool').replace(' ', '_')}"
        else:
            new_cap_id = f"ui:{(node.nodeId or 'screen').replace(' ', '_')}"

        if assumed_kind == "tool" or new_cap_id.startswith("tool:"):
            tool_key = new_cap_id[5:] if new_cap_id.startswith("tool:") else new_cap_id
            _apply_gap_resolution_success(
                node,
                new_cap_id=new_cap_id,
                capability_kind="tool",
                new_version="1",
                source="gap_tool_llm",
                class_path=dynamic_tool_class_path(tool_key),
            )
        else:
            _apply_gap_resolution_success(node, new_cap_id=new_cap_id, capability_kind=assumed_kind)
        fallback_ids.append(new_cap_id)
        fallback_warnings.append(
            f"Fallback-resolved gap node '{node.nodeId}' to capability '{new_cap_id}'."
        )

    return fallback_ids, fallback_warnings


# ── Downstream tool reconciliation ────────────────────────────────────────────
# When an UPPER-STREAM node (e.g. screen_1) gains a new declaredOutput during a
# /plan/update, downstream tool nodes (e.g. tool_1) whose `inputBindings` don't
# already wire that output never get re-generated. As a result the tool's
# `function_code` keeps the old logic and silently ignores the newly-available
# data (the v4-regression class bug, surfaced when users added a
# `selected_operation` selector but tool_1 still only added).
#
# This helper:
#   1. Identifies all tool nodes that are downstream of a node whose
#      ``declaredOutputs`` grew during this /plan/update,
#   2. Mirrors the new output into the tool's ``inputBindings`` + ``stateReads``
#      so the LangGraph executor will actually feed it to ``execute_dynamic_tool``,
#   3. Re-runs ``_generate_gap_tool_and_upsert_capability`` when the tool's
#      declared output is *behavior* relevant (e.g. the user explicitly asked
#      the tool to use the new field) so the LLM can emit a fresh
#      ``function_code`` that consumes the new parameter.
#
# Idempotent — re-runs against an already-reconciled tool no-op because the
# new output is already in ``inputBindings``.

def _compute_unbound_upstream_outputs(
    graph: GraphDefinition,
    proposed_changes: Dict[str, Dict[str, Any]],
    *,
    pre_edit_declared_outputs: Optional[Dict[str, set]] = None,
) -> Dict[str, List[Dict[str, str]]]:
    """For every tool node in ``graph`` list the upstream outputs that:
       - exist in the *post-edit* declaredOutputs of the upstream node, AND
       - are NOT already wired via the tool's inputBindings, AND
       - (when ``pre_edit_declared_outputs`` is provided) were NOT in the
         pre-edit declaredOutputs of the same upstream — i.e. are *genuinely
         new* this update, not just freshly-discovered.

    Returns: {tool_node_id: [{"upstream_id": ..., "output_name": ..., "binding_template": ...}, ...]}.

    Why both signals:
      * ``proposed_changes`` alone is unreliable because the heuristic in
        ``create_proposed_changes_from_node_update`` only ADDS outputs when
        trigger words ("one more","another","additional","extra","add one",
        "add another") appear in the prompt — natural-language update
        requests like "add a field called selected_operation that carries the
        user's choice" miss those triggers, so ``proposed_changes[screen]``
        has unchanged declaredOutputs. Yet the integrated-pipeline Phase 2
        LLM DOES apply the addition (declaredOutputs grows post-edit). For
        the additive-impact reconciliation to fire we MUST diff against the
        pre-edit graph, not against ``proposed_changes``.
      * ``pre_edit_declared_outputs`` is captured at the start of
        ``/plan/update`` from ``doc["agentic_process"]["phaseGraphs"]``
        BEFORE Phase 2 mutates the graph.
    """
    # Build an adjacency: upstream_id -> list of downstream node_ids that
    # reference its outputs via inputBindings.
    downstream_edge: Dict[str, set] = {}
    nodes_by_id: Dict[str, GraphNode] = {}
    for node in (graph.nodes or []):
        nodes_by_id[node.nodeId] = node
        cfg_ib = (node.config.inputBindings or {}) if node.config else {}
        for _param, expr in cfg_ib.items():
            if not isinstance(expr, str):
                continue
            m = re.search(r"\{\{(\w+)\.(\w+)\}\}", expr)
            if not m:
                continue
            upstream_id = m.group(1)
            if upstream_id in ("global", "pick"):
                continue
            downstream_edge.setdefault(upstream_id, set()).add(node.nodeId)

    out: Dict[str, List[Dict[str, str]]] = {}
    for upstream_id, downstream_ids in downstream_edge.items():
        upstream_node = nodes_by_id.get(upstream_id)
        upstream_gen_desc = (upstream_node.config.generationDescription or "") if (
            upstream_node and upstream_node.config
        ) else ""
        # Source of "outputs that the upstream can now expose" — read from the
        # POST-EDIT graph (graph.nodes[upstream].config.declaredOutputs) because
        # proposed_changes is the untrustworthy heuristic (see docstring).
        if upstream_node and upstream_node.config:
            post_edit_outputs_raw = upstream_node.config.declaredOutputs or []
        else:
            post_edit_outputs_raw = []
        post_edit_outputs: List[Dict[str, str]] = []
        for o in post_edit_outputs_raw:
            if isinstance(o, dict):
                nm = (o.get("name") or "").strip()
            else:
                # Pydantic model in some call paths
                nm = (getattr(o, "name", "") or "").strip()
            if nm:
                post_edit_outputs.append({"name": nm})

        # Fall back to proposed_changes IF post_edit captured nothing useful
        # (defensive — keeps the legacy path alive for callers that don't
        # have a pre_edit map).
        if not post_edit_outputs:
            prop = (proposed_changes or {}).get(upstream_id) or {}
            post_edit_outputs = prop.get("declaredOutputs") or []

        # Subset to NEW outputs if we have a pre-edit map. This is what
        # converts "phantom heuristic mismatch" into "real world change".
        pre_set = (pre_edit_declared_outputs or {}).get(upstream_id) or set()
        if pre_edit_declared_outputs and pre_set:
            post_edit_outputs = [
                o for o in post_edit_outputs
                if o["name"] not in pre_set
            ]

        for downstream_id in downstream_ids:
            downstream_node = nodes_by_id.get(downstream_id)
            if not downstream_node or downstream_node.type != "tool":
                continue
            ib = dict((downstream_node.config.inputBindings or {}) if downstream_node.config else {})
            bound_names = set()
            for _k, expr in ib.items():
                if not isinstance(expr, str):
                    continue
                m = re.search(rf"\{{\{{{re.escape(upstream_id)}\.(\w+)\}}\}}", expr)
                if m:
                    bound_names.add(m.group(1))
            for new_output in post_edit_outputs:
                nm = new_output["name"]
                if not nm or nm in bound_names:
                    continue
                out.setdefault(downstream_id, []).append({
                    "upstream_id": upstream_id,
                    "output_name": nm,
                    "binding_template": f"{{{{{upstream_id}.{nm}}}}}",
                    "upstream_gen_desc": upstream_gen_desc,
                })
    return out


async def _reconcile_tool_inputs_from_upstream(
    graph: GraphDefinition,
    proposed_changes: Dict[str, Dict[str, Any]],
    *,
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
    project_id: str,
    available_credentials: Optional[List[Dict[str, Any]]] = None,
    llm_caller: Optional[Any] = None,
    pre_edit_declared_outputs: Optional[Dict[str, set]] = None,
) -> int:
    """Re-bind downstream tool nodes to newly-exposed upstream outputs.

    Returns the number of tool nodes re-bound. Safe to call repeatedly —
    idempotent.

    Step 1 (always runs) — wire the new fields into ``inputBindings`` and
    ``stateReads`` on the tool node so the LangGraph executor stops
    silently dropping them.

    Step 2 (LLM codegen, best-effort) — re-emit the tool's ``function_code``
    by feeding the LLM a richer io_contract that lists the new params, so
    the new field is actually consumed by the tool logic. We construct a
    synthetic ``GenerationSpec`` because ``_apply_gap_resolution_success``
    has by this point cleared ``node.config.generation`` to None.
    """
    unbound = _compute_unbound_upstream_outputs(
        graph,
        proposed_changes,
        pre_edit_declared_outputs=pre_edit_declared_outputs,
    )

    # ── Orphan-cap-ref probe ────────────────────────────────────────────────
    # A previous /plan/update may have pre-allocated `tool_node.capabilityRef
    # .capabilityId` to a hash (e.g. `tool_1_f7184d02_sb_86dc311c`) before its
    # own codegen finished — and the on-disk JSON was either never written or
    # has since been rotated out. In that case unhbound-upstream-outputs is
    # empty (bindings/names look fine) and Step 2 below would never fire,
    # leaving the orphan cap_ref stamped on the workflow. Detect that case
    # here and force a regen so the freshly-written JSON becomes the new
    # cap_ref.
    try:
        _tools_path = (config.get("tools_path") or "tools").strip() or "tools"
        if not os.path.isabs(_tools_path):
            _tools_path = os.path.abspath(_tools_path)
        if os.path.isdir(_tools_path):
            _orphan_tool_nodes: List[str] = []
            for _node in (graph.nodes or []):
                if _node.type != "tool" or not _node.capabilityRef:
                    continue
                _cid = (_node.capabilityRef.capabilityId or "").strip()
                if not _cid.startswith("tool:"):
                    continue
                _stem = _cid[len("tool:"):]
                _has_disk_file = False
                try:
                    for _f in os.listdir(_tools_path):
                        if _f.endswith(".json") and _stem in _f:
                            _has_disk_file = True
                            break
                except FileNotFoundError:
                    _has_disk_file = False
                if not _has_disk_file:
                    _orphan_tool_nodes.append(_node.nodeId)
            for _orphan_id in _orphan_tool_nodes:
                if _orphan_id in unbound:
                    # Avoid double-regen: a hook from upstream-output-rebind
                    # already covers this tool.
                    _unbound_hook = unbound[_orphan_id]
                else:
                    _unbound_hook = None
                unbound[_orphan_id] = (_unbound_hook or [])
                if not _unbound_hook:
                    # Inject a synthetic "no-new-inputs but force regen" marker.
                    # The Step-2 try-block below treats absence of `output_name`
                    # as "use the tool's existing inputBindings verbatim".
                    unbound[_orphan_id].append({
                        "upstream_id": "__orphan_cap_ref__",
                        "output_name": "__force_regen__",
                        "binding_template": "",
                        "upstream_gen_desc":
                            "Orphan capabilityRef: prior codegen pre-allocated "
                            "this tool_key but never wrote the JSON. Forcing a "
                            "regeneration so the node's capabilityRef points "
                            "at a real on-disk implementation.",
                    })
                    logger.warning(
                        f"[Tool reconciliation] Orphan tool cap_ref detected "
                        f"for node '{_orphan_id}' (capabilityId='{_cid}' has "
                        f"no matching JSON under {_tools_path}); queueing "
                        f"force-regen so cap_ref realigns with a fresh JSON."
                    )
    except Exception as _orphan_probe_err:
        logger.warning(
            f"[Tool reconciliation] Orphan-cap-ref probe skipped due to "
            f"error: {_orphan_probe_err}"
        )

    if not unbound:
        logger.info("[Tool reconciliation] No downstream tool nodes need rebinding.")
        return 0

    rebound_count = 0
    nodes_by_id = {n.nodeId: n for n in (graph.nodes or [])}
    for tool_node_id, hooks in unbound.items():
        tool_node = nodes_by_id.get(tool_node_id)
        if not tool_node or not tool_node.config:
            continue
        cfg = tool_node.config

        # Partition the hooks list: the orphan-cap-ref probe injects a single
        # synthetic hook with `output_name == "__force_regen__"` to force a
        # Step-2 codegen without binding rewrites. Strip those out of the
        # Step-1 binding-rewrite loop, but keep them for the Step-2 regen
        # signal below.
        real_hooks = [
            h for h in hooks
            if not (h.get("output_name") == "__force_regen__"
                    and h.get("upstream_id") == "__orphan_cap_ref__")
        ]
        is_force_regen_only = (len(real_hooks) == 0)

        # Step 1: mirror new bindings + stateReads into the tool node config.
        existing_ib = dict(cfg.inputBindings or {})
        existing_sr = list(cfg.stateReads or [])
        newly_added: List[str] = []
        for h in real_hooks:
            new_name = h["output_name"]
            if new_name not in existing_ib:
                existing_ib[new_name] = h["binding_template"]
            new_read = f"{h['upstream_id']}__{new_name}"
            if new_read not in existing_sr:
                existing_sr.append(new_read)
                newly_added.append(new_read)
            existing_desc = (cfg.generationDescription or "").strip()
            upstream_desc = (h.get("upstream_gen_desc") or "").strip()
            if upstream_desc and upstream_desc not in existing_desc:
                cfg.generationDescription = (
                    (existing_desc + "\n\nUpstream exposes: " if existing_desc else "Upstream exposes: ")
                    + upstream_desc
                )
        cfg.inputBindings = existing_ib
        cfg.stateReads = existing_sr

        if real_hooks:
            logger.info(
                f"[Tool reconciliation] Tool '{tool_node_id}' now reads "
                f"{[h['output_name'] for h in real_hooks]} from upstream "
                f"{real_hooks[0]['upstream_id']}; stateReads +{newly_added}."
            )
        rebound_count += 1

        # Step 2: best-effort LLM regeneration of function_code. We use the
        # existing lower-level helper but with a synthetic GenerationSpec.
        try:
            from types import SimpleNamespace

            # Load existing function_code from capability repository so LLM can extend it
            _existing_function_code = None
            if tool_node.capabilityRef and tool_node.capabilityRef.capabilityId:
                try:
                    tenant = {"orgId": org_id, "subscriberId": subscriber_id}
                    cap_doc = await capability_repository.get_latest_capability_by_id(
                        tenant, tool_node.capabilityRef.capabilityId
                    )
                    if cap_doc and cap_doc.get("runtime", {}).get("function_code"):
                        _existing_function_code = cap_doc["runtime"]["function_code"]
                        logger.info(
                            f"[Tool reconciliation] Loaded existing function_code for "
                            f"tool '{tool_node_id}' (capabilityId={tool_node.capabilityRef.capabilityId})"
                        )
                except Exception as _cap_load_err:
                    logger.warning(
                        f"[Tool reconciliation] Failed to load existing function_code for "
                        f"tool '{tool_node_id}': {_cap_load_err}"
                    )

            if is_force_regen_only:
                # Orphan-cap-ref path: there are no genuinely-new upstream
                # outputs. Pass the tool's existing inputBindings keys
                # straight through as the param list so the regenerated JSON
                # has the same shape as the bindings consumers expect.
                _new_param_names = list(existing_ib.keys())
                _existing_param_names = []
            else:
                _new_param_names = [h["output_name"] for h in real_hooks]
                _existing_param_names = [
                    k for k in existing_ib.keys()
                    if k not in _new_param_names
                ]
            io_contract = {
                "inputParameters": [
                    {"name": n, "dataType": "Any", "required": True}
                    for n in (_new_param_names + _existing_param_names)
                ],
                "outputParameters": [
                    {"name": (o.name if hasattr(o, "name") else o.get("name")),
                     "dataType": (o.dataType if hasattr(o, "dataType") else o.get("dataType", "Any")),
                     "required": True}
                    for o in (cfg.declaredOutputs or [])
                ],
            }
            synthetic_gen = SimpleNamespace(
                description=(
                    # Lead with the new param names so the LLM
                    # sees them on line ~1 and routes its code-gen through them.
                    # The previous version buried this in
                    # cfg.generationDescription (often a long paragraph), and
                    # the LLM produced a soft-no-op stub.
                    f"MANDATORY: function_code MUST accept and use each of the new "
                    f"input param(s): {', '.join(_new_param_names)}. "
                    f"Extend the existing logic to handle these new parameters "
                    f"while preserving all existing behavior. "
                    f"Inline elaboration: "
                    f"{(cfg.generationDescription or tool_node.name or '').strip()}"
                ),
                kind="tool",
                io_contract=io_contract,
                id="",
                timestamp="",
                status="",
            )
            tool_key = _gap_unique_dynamic_tool_key(
                tool_node, subscriber_id=subscriber_id
            )
            upsert_meta = await _generate_gap_tool_and_upsert_capability(
                tool_node,
                synthetic_gen,
                tool_key=tool_key,
                io_contract=io_contract,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                project_id=project_id,
                available_credentials=available_credentials,
                existing_function_code=_existing_function_code,
            )
            new_tool_cap_id = upsert_meta["capabilityId"]
            # Rewrite the workflow node's capabilityRef so the persisted
            # PhaseGraph and the regenerated LangGraph file reference THIS
            # freshly-written JSON (not the orphan hash that an earlier
            # codegen attempt pre-allocated before crashing). Mirrors the
            # cap-update branch of `_apply_gap_resolution_success` but
            # preserves `generationDescription` (reconciliation nodes do NOT
            # carry `node.config.generation`, so calling the helper directly
            # would clobber the upstream description we just appended).
            if not tool_node.capabilityRef:
                tool_node.capabilityRef = GraphCapabilityRef(
                    capabilityId=new_tool_cap_id,
                    kind="tool",
                    version=upsert_meta.get("version") or "1",
                    source=upsert_meta.get("source") or "gap_tool_llm",
                    class_path=upsert_meta.get("class_path") or dynamic_tool_class_path(tool_key),
                )
            elif new_tool_cap_id:
                tool_node.capabilityRef.capabilityId = new_tool_cap_id
                tool_node.capabilityRef.kind = "tool"
                tool_node.capabilityRef.version = upsert_meta.get("version") or "1"
                tool_node.capabilityRef.source = upsert_meta.get("source") or "gap_tool_llm"
                tool_node.capabilityRef.class_path = (
                    upsert_meta.get("class_path") or dynamic_tool_class_path(tool_key)
                )
            logger.info(
                f"[Tool reconciliation] Rewrote tool='{tool_node_id}' "
                f"capabilityRef → {new_tool_cap_id} "
                f"(regenerated function_code for new params {_new_param_names})."
            )
        except BillingError:
            # Don't swallow billing errors - let them propagate so checkpoint can be saved
            raise
        except Exception as _regen_err:
                logger.warning(
                    f"[Tool reconciliation] function_code regeneration failed for "
                    f"tool '{tool_node_id}' (inputBindings+stateReads still applied): "
                    f"{_regen_err}. capabilityRef still points at the previous "
                    f"tool '{tool_node.capabilityRef.capabilityId if tool_node.capabilityRef else None}'."
                )

    return rebound_count


async def _resolve_one_gap_node(
    node: GraphNode,
    *,
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
    project_id: str,
    available_credentials: Optional[List[Dict[str, Any]]] = None,
) -> str:
    """Generate one gap node. Returns the new capability id or raises."""
    gen = node.config.generation if node.config else None
    if not gen:
        cap_id = (node.capabilityRef.capabilityId or "").strip() if node.capabilityRef else ""
        raise RuntimeError(
            f"Node '{node.nodeId}' still has placeholder capabilityId '{cap_id}' "
            "but no config.generation spec to generate from."
        )

    _ensure_gap_capability_ref(node, gen)
    gen_kind = _gap_infer_generation_kind(node, gen)
    io_contract = _gap_generation_io_contract_dict(gen)

    if gen_kind == "tool":
        _ensure_intent_description(node.config)
        intent_for_tool = _best_intent_description(
            node.config.intentDescription if node.config else None,
            node.config.generationDescription if node.config else None,
            gen.description,
        )
        if intent_for_tool:
            gen.description = intent_for_tool
        tool_key = _gap_unique_dynamic_tool_key(node, subscriber_id=subscriber_id)
        upsert_meta = await _generate_gap_tool_and_upsert_capability(
            node,
            gen,
            tool_key=tool_key,
            io_contract=io_contract,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            project_id=project_id,
            available_credentials=available_credentials,
        )
        new_cap_id = upsert_meta["capabilityId"]
        # Pin version + class_path at resolution time so LangGraph emit never
        # sees nulls if enrichment lookup misses (Issue 12).
        _apply_gap_resolution_success(
            node,
            new_cap_id=new_cap_id,
            capability_kind="tool",
            new_version=upsert_meta.get("version") or "1",
            source=upsert_meta.get("source") or "gap_tool_llm",
            class_path=upsert_meta.get("class_path") or dynamic_tool_class_path(tool_key),
        )
        logger.info(f"[Gap resolution] Node '{node.nodeId}' tool generated → {new_cap_id}")
        return new_cap_id

    existing_screen_id = None
    if node.capabilityRef and node.capabilityRef.capabilityId and node.capabilityRef.capabilityId.startswith("ui:"):
        existing_screen_id = node.capabilityRef.capabilityId[3:]

    def _io_params(params: list[GenerationIOParam]) -> list[Dict[str, Any]]:
        out: list[Dict[str, Any]] = []
        for p in (params or []):
            out.append({
                "name": p.name,
                "dataType": getattr(p, "dataType", None),
                "required": bool(getattr(p, "required", False)),
                "description": getattr(p, "description", "") or "",
                **_list_item_io_fields(p),
            })
        return out

    # CRITICAL: Sync gen.inputs/gen.outputs from the workflow node's authoritative
    # declaredOutputs/inputBindings BEFORE building the IO contract. The integrated
    # pipeline's edit plan sets node.config.declaredOutputs (e.g. number_1,
    # number_2, number_3) but generation.outputs is a separate field and can be
    # stale/empty for ui_screens. Without this sync, the IR schema infers
    # `formOutput` as a single fallback output, and the generated Angular
    # component submits a single object instead of the per-field shape the
    # workflow contract requires.
    decl_outputs = _strip_generic_declared_outputs(
        (node.config.declaredOutputs or []) if node.config else []
    )
    # Build a name→param lookup from gen.inputs so we can preserve dataType /
    # itemSchema for list params when we later rebuild a GenerationSpec. Using
    # bare GenerationIOParam(name=k, dataType="Any") would silently drop the
    # itemSchema that the screen/tool generator needs to produce correct code.
    _gen_input_map: dict[str, GenerationIOParam] = {
        p.name: p for p in (gen.inputs or [])
    }
    decl_inputs: list[GenerationIOParam] = []
    if node.config and node.config.inputBindings:
        for k in (node.config.inputBindings or {}).keys():
            existing = _gen_input_map.get(str(k))
            if existing is not None:
                decl_inputs.append(existing)
            else:
                decl_inputs.append(GenerationIOParam(name=str(k), dataType="Any", required=False))
    if decl_outputs and not gen.outputs:
        # Replace gen.outputs with authoritative declaredOutputs (build new GenerationSpec
        # so we don't mutate the original object).
        gen = GenerationSpec(
            kind=gen.kind,
            stepId=gen.stepId,
            description=gen.description,
            inputs=decl_inputs or gen.inputs,
            outputs=[_generation_io_param_from_any(o) for o in decl_outputs]
        )
        logger.info(
            f"[plan/update] Synced gen.outputs from node.config.declaredOutputs "
            f"for node '{node.nodeId}': {[o.name for o in decl_outputs]}"
        )
    elif decl_outputs and gen.outputs:
        # Both exist — prefer declaredOutputs names so the Angular form submission
        # shape matches the workflow contract.
        decl_names = {str(o.name) for o in decl_outputs if getattr(o, "name", None)}
        gen_out_names = {str(getattr(o, "name", "")) for o in gen.outputs}
        if decl_names != gen_out_names:
            logger.info(
                f"[plan/update] Reconciling gen.outputs ({sorted(gen_out_names)}) "
                f"with declaredOutputs ({sorted(decl_names)}) for node '{node.nodeId}'."
            )
            gen = GenerationSpec(
                kind=gen.kind,
                stepId=gen.stepId,
                description=gen.description,
                inputs=decl_inputs or gen.inputs,
                outputs=[_generation_io_param_from_any(o) for o in decl_outputs],
            )

    io_rows = {
        "inputParameters": _io_params(gen.inputs or []),
        "outputParameters": _io_params(gen.outputs or []),
    }
    # Prefer the richest non-generic intent (original spec, possibly with schema
    # stanzas appended). Never send the machine-built I/O sentence to the generator.
    _ensure_intent_description(node.config)
    _gen_desc_text = _best_intent_description(
        node.config.intentDescription if node.config else None,
        node.config.generationDescription if node.config else None,
        gen.description,
    )
    if _gen_desc_text and _gen_desc_text != (gen.description or "").strip():
        logger.info(
            f"[Gap resolution] Using preserved intent as generation prompt for "
            f"'{node.nodeId}' ({len(_gen_desc_text)} chars, "
            f"gen.description={len((gen.description or '').strip())} chars)."
        )
    gen_prompt = (
        f"{_gen_desc_text}\n\n"
        f"{WORKFLOW_IO_CONTRACT_SCREEN_MARKER}\n"
        f"{json.dumps(io_rows, indent=2)}\n\n"
        f"{_NO_GENERIC_OUTPUTS_CONSTRAINT}\n"
    ).strip()
    try:
        from services.persistence_link import (
            format_pinned_persistence_spec,
            node_persistence_links,
        )
        _plinks = node_persistence_links(node)
        _pin = format_pinned_persistence_spec(_plinks, node_id=node.nodeId)
        if _pin:
            gen_prompt = f"{gen_prompt}\n\n{_pin}".strip()
    except Exception:
        pass

    if existing_screen_id:
        # Update existing screen — update_angular_screen_async now creates a NEW screen_id
        # for the new version, preserving the old screen_id + its versions for restore.
        screen_id = existing_screen_id
        payload: Dict[str, Any] = {
            "project_id": project_id,
            "screen_id": screen_id,
            "screen_name": node.name,
            "prompt": gen_prompt,
            "orgId": org_id,
            "subscriberId": subscriber_id,
            "userId": user_id,
        }
        result = await update_angular_screen_async(payload)
        if not result.get("success"):
            raise RuntimeError(f"Failed to update Angular screen: {result.get('error', 'Unknown error')}")
        # Use the NEW screen_id returned by update_angular_screen_async so the node's
        # capabilityRef points to the freshly generated screen (with the new version).
        new_screen_id = result.get("screen_id") or payload.get("_new_screen_id") or screen_id
        new_cap_id = f"ui:{new_screen_id}"
        logger.info(f"[Gap resolution] Node '{node.nodeId}' UI updated → {new_cap_id} (was {screen_id})")

        # Fetch updated IR schema from screen_generations. ONLY adopt it as the
        # node's declaredOutputs if the existing declaredOutputs are empty or
        # already consist solely of generic placeholders like ``formOutput``.
        # The workflow's per-field contract must be preserved end-to-end so the
        # LangGraph compile and Angular form submission agree on field names.
        updated_doc = None
        try:
            from repositories.screen_repository import ScreenRepository
            screen_repo = ScreenRepository()
            updated_doc = await screen_repo.get_latest_screen_doc(project_id, new_screen_id)
            # `get_latest_screen_doc` returns the raw screen_generations doc with
            # the IO contract stored under ``ir_schema`` (older wrappers named
            # this ``current_ir_schema`` — accept both shapes).
            _updated_ir = (
                (updated_doc or {}).get("current_ir_schema")
                or (updated_doc or {}).get("ir_schema")
            )
            if updated_doc and _updated_ir:
                updated_ir = _updated_ir
                # `outputParameters` may be a flat list of names (newer dump)
                # OR a list of {name, dataType} dicts (older dump). Normalize.
                raw_ir_outs = updated_ir.get("outputParameters") or []
                ir_outs = []
                for _o in raw_ir_outs:
                    if isinstance(_o, str):
                        ir_outs.append({"name": _o, "dataType": "string"})
                    elif isinstance(_o, dict):
                        _n = (_o.get("name") or "").strip()
                        if _n:
                            ir_outs.append(_o)
                raw_ir_ins = updated_ir.get("inputParameters") or []
                ir_ins = []
                for _i in raw_ir_ins:
                    if isinstance(_i, str):
                        ir_ins.append({"name": _i, "dataType": "string"})
                    elif isinstance(_i, dict):
                        ir_ins.append(_i)
                existing_dos = list(node.config.declaredOutputs or [])
                non_generic_existing = [
                    o for o in existing_dos
                    if isinstance(o, dict)
                    and (o.get('name') or '').strip()
                    and (o.get('name') or '').strip() not in ('formOutput', 'output', 'result')
                ]
                # Build a combined source string from the regenerated screen
                # description AND the user's original update request. The
                # LLM-rebuilt description often drops the user's "called X" /
                # "named X" phrasing and reduces it to "labelled 'X'",
                # which the supplementer's signal regex would miss. Folding
                # the raw user prompt in restores the signal.
                _gen_desc = node.config.generationDescription or ""
                _user_prompt = ""
                try:
                    _cfg_dict = node.config.model_dump() if hasattr(node.config, "model_dump") else {}
                    _user_prompt = _cfg_dict.get("_update_request") or ""
                except Exception:
                    _user_prompt = ""
                _combined_source = _gen_desc + (("\n\n" + _user_prompt) if _user_prompt else "")
                # Merge typed-field force_include_names into our local set so
                # that even if the runtime _user_prompt is empty (Pydantic
                # extras can be lost across dict→model→dict boundaries), the
                # user's intent survives.
                try:
                    _typed_force = list(getattr(node.config, "force_include_names", []) or [])
                except Exception:
                    _typed_force = []
                # Inputs use the IR's inputParameters (real source of truth
                # added by the LLM in the IO contract call), NOT names pinned
                # from existing_dos (which is what we already have as outputs).
                _sup_input_params = ir_ins
                # For UI screen updates, the IR (from regenerated screen) is the authoritative
                # source of truth for outputs. Always adopt from IR when it has outputs,
                # regardless of existing declaredOutputs (which may be stale from previous versions).
                if ir_outs:
                    # Adopt from IR, then strip generic placeholders so users see only real field names.
                    # Let LLM generate outputs; no supplementer needed.
                    adopted = _strip_generic_declared_outputs(ir_outs)
                    # IMPORTANT: in pydantic v2 a plain attribute assignment does
                    # NOT auto-coerce raw dicts into GenerationIOParam models, so
                    # downstream code that does ``o.name`` would crash with
                    # 'dict has no attribute name'. Force the coercion here.
                    node.config.declaredOutputs = _coerce_io_params(adopted)
                    logger.info(
                        f"[Gap resolution] Adopted declaredOutputs from IR for node "
                        f"'{node.nodeId}': {[o.name for o in node.config.declaredOutputs]}"
                    )
                # If IR has no outputs, fall back to existing (should be rare for UI screens)
                if not ir_outs:
                    node.config.declaredOutputs = _coerce_io_params(
                        _strip_generic_declared_outputs(existing_dos)
                    )
                    logger.info(
                        f"[Gap resolution] Fallback to existing declaredOutputs for node "
                        f"'{node.nodeId}': {[o.name for o in node.config.declaredOutputs]} "
                        f"(IR had no outputs)"
                    )
        except Exception as e:
            logger.warning(f"[Gap resolution] Failed to read IR schema for node '{node.nodeId}': {e}")

        # After we've potentially added new entries to declaredOutputs via the
        # supplementer, sync this node's stateWrites so any newly-added
        # declaredOutput name is reflected as ``<nodeId>__<name>``. Without
        # this the LangGraph compile will not see the new binding.
        try:
            _node_id = node.nodeId
            _auto_writes = [
                f"{_node_id}__{o.name}" for o in node.config.declaredOutputs
                if isinstance(o, GenerationIOParam) and o.name
            ]
            _existing_writes = list(node.config.stateWrites or [])
            _merged_writes = list(_existing_writes)
            for _sw in _auto_writes:
                if _sw not in _merged_writes:
                    _merged_writes.append(_sw)
            if _merged_writes != _existing_writes:
                node.config.stateWrites = _merged_writes
                logger.info(
                    f"[Gap resolution] Auto-synced stateWrites from declaredOutputs "
                    f"for node '{node.nodeId}': {_merged_writes}"
                )
        except Exception as _sw_err:
            logger.warning(
                f"[Gap resolution] stateWrites auto-sync failed for node '{node.nodeId}': {_sw_err}"
            )

        # Sync stateReads from inputBindings (for downstream screens)
        try:
            if node.config.inputBindings:
                state_reads = [f"{node.nodeId}__{name}" for name in node.config.inputBindings.keys()]
                existing_reads = node.config.stateReads or []
                merged_reads = []
                for sr in existing_reads:
                    if sr.startswith(f"{node.nodeId}__"):
                        merged_reads.append(sr)
                for sr in state_reads:
                    if sr not in merged_reads:
                        merged_reads.append(sr)
                if merged_reads != existing_reads:
                    node.config.stateReads = merged_reads
                    logger.info(f"[Gap resolution] Synced stateReads from inputBindings for node '{node.nodeId}': {merged_reads}")
        except Exception as _sr_err:
            logger.warning(f"[Gap resolution] stateReads sync failed for node '{node.nodeId}': {_sr_err}")

        # Persist the richest non-generic description. Do not invent an I/O sentence
        # when intentDescription or generation.description still hold the original spec.
        try:
            _ensure_intent_description(node.config)
            desc_to_persist = _best_intent_description(
                node.config.intentDescription,
                node.config.generationDescription,
                node.config.generation.description if node.config.generation else None,
            )
            if desc_to_persist and not _is_generic_io_summary_description(desc_to_persist):
                node.config.generationDescription = desc_to_persist
                logger.info(
                    f"[Gap resolution] Persisting preserved generationDescription for "
                    f"'{node.nodeId}' ({len(desc_to_persist)} chars)."
                )
            elif not desc_to_persist:
                ir = (updated_doc or {}).get("current_ir_schema") or (updated_doc or {}).get("ir_schema") or {}
                ir_outputs = ir.get("outputParameters") or []
                ir_inputs = ir.get("inputParameters") or []
                desc_parts = []
                if ir_inputs:
                    input_names = [p.get("name") for p in ir_inputs if isinstance(p, dict) and p.get("name")]
                    if input_names:
                        desc_parts.append(f"This screen receives inputs {', '.join(input_names)}")
                if ir_outputs:
                    output_names = [p.get("name") for p in ir_outputs if isinstance(p, dict) and p.get("name")]
                    if output_names:
                        desc_parts.append(f"and produces outputs {', '.join(output_names)}")
                desc_to_persist = (" ".join(desc_parts) + " to render a user interface.").strip() if desc_parts else ""
                if desc_to_persist:
                    node.config.generationDescription = desc_to_persist
                    logger.info(
                        f"[Gap resolution] No prior description for '{node.nodeId}' — "
                        f"set IR-derived fallback: {desc_to_persist[:100]}..."
                    )

            if desc_to_persist:
                try:
                    from repositories.screen_repository import ScreenRepository
                    screen_repo = ScreenRepository()
                    new_screen_id = new_cap_id[3:] if new_cap_id.startswith("ui:") else new_cap_id
                    persist_payload: Dict[str, Any] = {"generationDescription": desc_to_persist}
                    # Also persist intentDescription so it survives across plan/update cycles.
                    intent = (node.config.intentDescription or "").strip()
                    if intent:
                        persist_payload["intentDescription"] = intent
                    await screen_repo.update_screen_metadata(
                        project_id,
                        new_screen_id,
                        persist_payload,
                    )
                    logger.info(
                        f"[Gap resolution] Persisted generationDescription"
                        f"{' + intentDescription' if intent else ''} "
                        f"to screen document for {new_screen_id}."
                    )
                except Exception as _persist_err:
                    logger.warning(
                        f"[Gap resolution] Failed to persist description fields: {_persist_err}"
                    )
        except Exception as _desc_err:
            logger.warning(
                f"[Gap resolution] Failed to handle post-generation description "
                f"for node '{node.nodeId}': {_desc_err}"
            )

        _apply_gap_resolution_success(
            node,
            new_cap_id=new_cap_id,
            capability_kind="ui_screen",
            new_version=(result.get("angular") or {}).get("version"),
        )
        return new_cap_id

    else:
        # Create new screen
        screen_id = generate_screen_id("screen")
        payload: Dict[str, Any] = {
            "project_id": project_id,
            "screen_id": screen_id,
            "screen_name": node.name,
            "prompt": gen_prompt,
            "orgId": org_id,
            "subscriberId": subscriber_id,
            "userId": user_id,
        }
        result = await generate_angular_app_async(payload)
        new_cap_id = f"ui:{result.get('screen_id', screen_id)}"
        logger.info(f"[Gap resolution] Node '{node.nodeId}' UI generated → {new_cap_id}")

        try:
            _ensure_intent_description(node.config)
            desc_to_persist = _best_intent_description(
                node.config.intentDescription if node.config else None,
                node.config.generationDescription if node.config else None,
                gen.description,
            )
            if desc_to_persist and not _is_generic_io_summary_description(desc_to_persist):
                node.config.generationDescription = desc_to_persist
                from repositories.screen_repository import ScreenRepository
                persist_id = new_cap_id[3:] if new_cap_id.startswith("ui:") else new_cap_id
                persist_payload: Dict[str, Any] = {"generationDescription": desc_to_persist}
                intent = (node.config.intentDescription or "").strip()
                if intent:
                    persist_payload["intentDescription"] = intent
                await ScreenRepository().update_screen_metadata(
                    project_id, persist_id, persist_payload
                )
                logger.info(
                    f"[Gap resolution] Persisted generationDescription"
                    f"{' + intentDescription' if intent else ''} "
                    f"to screen document for {persist_id} (first generation)."
                )
        except Exception as _persist_err:
            logger.warning(
                f"[Gap resolution] Failed to persist description fields on first generation: {_persist_err}"
            )

        _apply_gap_resolution_success(
            node,
            new_cap_id=new_cap_id,
            capability_kind="ui_screen",
            new_version=result.get("version"),
        )
        return new_cap_id


async def _resolve_gap_generations(
    graph: GraphDefinition,
    *,
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
    project_id: str,
    available_credentials: Optional[List[Dict[str, Any]]] = None,
    max_rounds: int = 2,
    raise_on_failure: bool = True,
    node_checkpoint_fn: Optional[Any] = None,
    node_gap_start_fn: Optional[Any] = None,
) -> tuple[GraphDefinition, list[str]]:
    """
    Steps 7 + 8 — Gap resolution for GENERATE:* nodes.

    • kind ui_screen (default when user interaction is required): generate_angular_app_async.
    • kind tool (preferred for automation): LLM-writes a dynamic tool + capability_repository upsert.

    Updates each node's capabilityRef to the real capability id and clears generation.
    Retries failed nodes up to `max_rounds` times. Raises UnresolvedGapGenerationError
    when `raise_on_failure=True` and any gaps remain unresolved.
    Returns (updated_graph, list_of_generated_capability_ids).
    """
    generated_ids: list[str] = []
    failures: Dict[str, str] = {}
    phase_id = graph.phaseId or graph.graphId or "unknown_phase"

    for round_no in range(max(1, max_rounds)):
        pending = [n for n in graph.nodes if _node_needs_gap_resolution(n)]
        if not pending:
            break

        if round_no > 0:
            logger.info(
                f"[Gap resolution] Retry round {round_no + 1}/{max_rounds} for phase "
                f"'{phase_id}': {len(pending)} unresolved node(s)"
            )

        round_had_failure = False
        for node in pending:
            # Before resolving this node, if it's a downstream UI screen,
            # update its inputBindings from upstream nodes' CURRENT declaredOutputs
            # in the graph (which may have been updated by upstream gap resolution).
            if node.config and node.config.generation and node.config.generation.kind == "ui_screen":
                # Find upstream nodes that flow to this node
                upstream_node_ids = []
                for edge in graph.edges:
                    if edge.to == node.nodeId:
                        upstream_node_ids.append(edge.fromNode)

                if upstream_node_ids:
                    # Build new inputBindings from upstream nodes' CURRENT declaredOutputs
                    new_input_bindings = {}
                    for up_id in upstream_node_ids:
                        # Find upstream node in graph
                        up_node = None
                        for n in graph.nodes:
                            if n.nodeId == up_id:
                                up_node = n
                                break
                        if up_node and up_node.config and up_node.config.declaredOutputs:
                            for out in up_node.config.declaredOutputs:
                                out_name = getattr(out, "name", None)
                                if out_name:
                                    new_input_bindings[out_name] = f"{{{{{up_id}.{out_name}}}}}"

                    if new_input_bindings:
                        node.config.inputBindings = new_input_bindings
                        logger.info(
                            f"[Gap resolution] Updated inputBindings for downstream {node.nodeId} "
                            f"from upstream declaredOutputs: {new_input_bindings}"
                        )

                        # Sync stateReads from inputBindings
                        state_reads = [f"{node.nodeId}__{name}" for name in new_input_bindings.keys()]
                        existing_reads = node.config.stateReads or []
                        merged_reads = []
                        for sr in existing_reads:
                            if sr.startswith(f"{node.nodeId}__"):
                                merged_reads.append(sr)
                        for sr in state_reads:
                            if sr not in merged_reads:
                                merged_reads.append(sr)
                        node.config.stateReads = merged_reads
                        logger.info(f"[Gap resolution] Synced stateReads for downstream {node.nodeId}: {merged_reads}")

                        # Preserve the original intent description from scratch planning.
                        # NEVER overwrite generationDescription / generation.description with
                        # a generic I/O sentence — that destroys UX and domain requirements
                        # that the user specified and Stage 1.2 encoded.
                        # _resolve_one_gap_node already appends the typed I/O contract
                        # (WORKFLOW_IO_CONTRACT_SCREEN_MARKER + io_rows JSON) separately,
                        # so the generator receives full intent + current contract without
                        # this block needing to touch the description at all.
                        try:
                            intent = _ensure_intent_description(node.config)
                            if intent:
                                logger.info(
                                    f"[Gap resolution] Preserved original generationDescription "
                                    f"for downstream {node.nodeId} "
                                    f"({len(intent)} chars). "
                                    f"intentDescription captured."
                                )
                            elif not _best_intent_description(
                                node.config.generationDescription,
                                node.config.generation.description if node.config.generation else None,
                            ):
                                declared_outputs = node.config.declaredOutputs or []
                                input_names = [n for n in new_input_bindings.keys() if n]
                                output_names = [
                                    getattr(out, "name", None)
                                    for out in declared_outputs
                                    if getattr(out, "name", None)
                                ]
                                desc_parts = []
                                if input_names:
                                    desc_parts.append(f"This screen receives inputs {', '.join(input_names)}")
                                if output_names:
                                    desc_parts.append(f"and produces outputs {', '.join(output_names)}")
                                if desc_parts:
                                    gen_desc = " ".join(desc_parts) + " to render a user interface."
                                    if not (node.config.generationDescription or "").strip():
                                        node.config.generationDescription = gen_desc
                                    logger.info(
                                        f"[Gap resolution] No prior description for downstream "
                                        f"{node.nodeId} — set minimal I/O fallback: {gen_desc[:100]}..."
                                    )
                        except Exception as _desc_err:
                            logger.warning(
                                f"[Gap resolution] Failed to handle generationDescription "
                                f"for downstream {node.nodeId}: {_desc_err}"
                            )

            if node_gap_start_fn is not None:
                await node_gap_start_fn(node.nodeId or "")
            try:
                new_cap_id = await _resolve_one_gap_node(
                    node,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    project_id=project_id,
                    available_credentials=available_credentials,
                )
                generated_ids.append(new_cap_id)
                failures.pop(node.nodeId or "", None)
                if node_checkpoint_fn is not None:
                    await node_checkpoint_fn(graph, node.nodeId)
            except BillingError:
                raise
            except Exception as e:
                round_had_failure = True
                node_key = node.nodeId or "unknown"
                failures[node_key] = str(e)
                logger.warning(
                    f"[Gap resolution] Generation failed for node '{node_key}' "
                    f"(round {round_no + 1}/{max_rounds}): {e}"
                )

        if not round_had_failure:
            break

    unresolved = _collect_unresolved_gap_nodes(graph)
    if unresolved and raise_on_failure:
        raise UnresolvedGapGenerationError(
            phase_id=phase_id,
            unresolved=unresolved,
            failures=failures,
        )

    return graph, generated_ids


# ============================================================================
# STEP 6p — _revalidate_after_gap_gen
#   After GENERATE nodes are resolved to real capability IDs, fetch their real
#   outputParameters from capability_repository and re-run the validate loop.
# ============================================================================
async def _revalidate_after_gap_gen(
    graph: GraphDefinition,
    gen_ids: list[str],
    user_context: str,
    global_caps: list[StepCapabilityCandidate],   # kept for call-site compat, not used internally
    *,
    max_rounds: int = 2,                           # kept for call-site compat, not used internally
    project_id: Optional[str] = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    api_key: Optional[str] = None,
    _recursion_depth: int = 0,
    available_credentials: Optional[List[Dict[str, Any]]] = None,
) -> GraphDefinition:
    """
    Post-gap-generation re-validation.

    1.  Only touches nodes whose capabilityRef.capabilityId is in gen_ids.
        All other nodes are left completely untouched.
    2.  For every such node, fetches real inputParameters / outputParameters
        from the capability repository.
    3.  Validates contracts:
          a. Every name in declaredOutputs must appear in real outputParameters.
          b. Every key in inputBindings must appear in real inputParameters.
          c. Every required inputParameter has a binding.
          d. UI screens: declaredOutputs with required=true must not be
             required=false on the capability (Issue 7).
        Any mismatch flags the node.
    4.  Flagged nodes are sent to the LLM one-by-one:
          • "adapt"      → LLM returns an updatedNode; applied in-place.
          • "regenerate" → LLM returns a betterPrompt; UI nodes re-run generate_angular_app_async,
                           tool nodes re-run gap-tool LLM synthesis + register_tool, then
                           _revalidate_after_gap_gen recurses for the new cap-id.
    5.  _validate_and_fix_loop is NOT called.
    """

    MAX_RECURSION = 3
    if _recursion_depth > MAX_RECURSION:
        logger.warning(
            f"[6p] Max recursion depth ({MAX_RECURSION}) reached — "
            "stopping re-validation to avoid infinite loop."
        )
        return graph

    if not gen_ids:
        return graph

    graph = graph.model_copy(deep=True)
    gen_id_set = set(gen_ids)

    # ── 1. Identify only the nodes that correspond to gen_ids ────────────────
    # Use nodeId as the stable key — node objects are from the copied graph.
    generated_node_ids: set[str] = {
        node.nodeId for node in graph.nodes
        if node.capabilityRef and node.capabilityRef.capabilityId in gen_id_set
    }

    if not generated_node_ids:
        logger.info("[6p] No generated nodes found matching gen_ids — nothing to do.")
        return graph

    # ── 2. Fetch real capability docs ────────────────────────────────────────
    cap_map: Dict[str, StepCapabilityCandidate] = {}
    for cap_id in gen_ids:
        try:
            doc = await capability_repository.get_latest_capability_by_id(
                tenant={"orgId": org_id, "subscriberId": subscriber_id, "userId": user_id},
                capability_id=cap_id,
            )
            if not doc:
                logger.warning(f"[6p] Capability '{cap_id}' not found — skipping.")
                continue

            def _to_io_list(params: Any) -> list[Dict[str, Any]]:
                if not params:
                    return []
                return [p if isinstance(p, dict) else {} for p in params]

            cap_map[cap_id] = StepCapabilityCandidate(
                capabilityId=cap_id,
                kind=doc.get("kind", "ui_screen"),
                name=doc.get("name", cap_id),
                description=doc.get("description", ""),
                inputParameters=_to_io_list(doc.get("inputParameters")),
                outputParameters=_to_io_list(doc.get("outputParameters")),
                dataStores=[ds for ds in (doc.get("dataStores") or []) if isinstance(ds, dict)],
                collectionSchemas=dict(doc.get("collectionSchemas") or {}),
                tags=doc.get("tags") or [],
                capabilityScore=1.0,
            )
        except Exception as e:
            logger.warning(f"[6p] Failed to fetch capability '{cap_id}': {e}")

    # ── 3. Flag nodes whose contracts are violated ───────────────────────────
    # Work directly on the copied graph's node list so all mutations are in-place
    # on the same object we will return.
    flagged: list[tuple[GraphNode, StepCapabilityCandidate, list[str]]] = []
    from services.ir_response_requiredness import (
        capability_weakens_required_declared_outputs,
    )

    for node in graph.nodes:
        if node.nodeId not in generated_node_ids:
            continue  # ← only touch generated nodes

        cap_id = node.capabilityRef.capabilityId  # safe: we filtered by capabilityRef above
        real_cap = cap_map.get(cap_id)
        if not real_cap:
            logger.warning(
                f"[6p] Node '{node.nodeId}' references '{cap_id}' "
                "which was not fetched — skipping validation for this node."
            )
            continue

        real_output_names: set[str] = {
            p.get("name", "") for p in real_cap.outputParameters if p.get("name")
        }
        real_input_names: set[str] = {
            p.get("name", "") for p in real_cap.inputParameters if p.get("name")
        }

        reasons: list[str] = []

        # 3a — every declaredOutput must exist in real outputParameters
        for declared in (node.config.declaredOutputs or []):
            if declared.name not in real_output_names:
                reasons.append(
                    f"declaredOutput '{declared.name}' missing from real "
                    f"outputParameters {sorted(real_output_names)}"
                )

        # 3b — every inputBinding key must exist in real inputParameters
        for binding_key in (node.config.inputBindings or {}):
            if binding_key not in real_input_names:
                reasons.append(
                    f"inputBinding key '{binding_key}' missing from real "
                    f"inputParameters {sorted(real_input_names)}"
                )

        # 3c — every REQUIRED inputParameter must have a binding
        # This catches the gap where the planner created a GENERATE node with
        # empty inputBindings but the generated tool has required inputs.
        # We flag these as violations for the arbitration LLM to fix (with full
        # upstream context) rather than auto-binding, because multiple upstream
        # nodes may produce identically named outputs and only the LLM can
        # determine the correct semantic source.
        current_binding_keys = set(node.config.inputBindings or {})
        real_required_inputs = {
            p.get("name", "")
            for p in real_cap.inputParameters
            if p.get("name") and p.get("required", False)
        }
        missing_required = real_required_inputs - current_binding_keys
        if missing_required:
            reasons.append(
                f"Required inputParameters {sorted(missing_required)} have no binding. "
                f"The LLM arbitration must add inputBindings for these using "
                f"{{{{nodeId.paramName}}}} referencing the correct upstream node."
            )

        # 3d — Issue 7: required graph outputs must stay required on UI capabilities
        cap_kind = (real_cap.kind or node.type or "").strip().lower()
        if cap_kind in ("ui_screen", "ui", "screen"):
            reasons.extend(
                capability_weakens_required_declared_outputs(
                    node.config.declaredOutputs or [],
                    real_cap.outputParameters or [],
                )
            )

        if reasons:
            logger.info(
                f"[6p] Node '{node.nodeId}' flagged — {len(reasons)} violation(s): "
                + "; ".join(reasons)
            )
            flagged.append((node, real_cap, reasons))
        else:
            logger.info(f"[6p] Node '{node.nodeId}' passed contract validation ✓")

    if not flagged:
        logger.info("[6p] All generated nodes passed validation — no LLM fixup needed.")
        return graph

    # ── 4. LLM arbitration for each flagged node ─────────────────────────────
    new_gen_ids: list[str] = []

    for node, real_cap, reasons in flagged:
        node_dict = node.model_dump()
        cap_dict = {
            "inputParameters": real_cap.inputParameters,
            "outputParameters": real_cap.outputParameters,
        }
        violation_text = "\n".join(f"  - {r}" for r in reasons)

        cap_is_ui = (
            (real_cap.kind or "").strip().lower() in ("ui_screen", "ui")
            or real_cap.capabilityId.startswith("ui:")
        )
        artifact = "UI screen (Angular)" if cap_is_ui else "dynamic Python tool"
        regen_hint = (
            "a UI/Angular screen whose inputParameters and outputParameters match the node"
            if cap_is_ui
            else "a JSON-defined dynamic tool whose parameters and return shape match the node"
        )

        # Build upstream outputs context for the LLM
        _upstream_outputs_lines: list[str] = []
        for other in graph.nodes:
            if other.nodeId == node.nodeId or other.type in ("router", "fallback_router", "end"):
                continue
            _out_names = [p.name for p in (other.config.declaredOutputs or []) if getattr(p, "name", None)]
            if _out_names:
                _upstream_outputs_lines.append(f"  - {other.nodeId}: [{', '.join(_out_names)}]")
        _upstream_ctx = "\n".join(_upstream_outputs_lines) if _upstream_outputs_lines else "  (none)"

        arbitration_prompt = f"""
You are validating a workflow node definition against an already-generated capability ({artifact}).

## Node definition (from the graph)
{json.dumps(node_dict, indent=2)}

## Real capability IO (from the capability repository for '{real_cap.capabilityId}')
{json.dumps(cap_dict, indent=2)}

## Available upstream node outputs (use these for inputBindings)
{_upstream_ctx}

## Contract violations detected
{violation_text}

## Your task
Decide whether the node definition can be adapted to work with the existing capability's
real IO parameters, or whether the capability must be re-generated.

Respond with a JSON object — no markdown fences, no extra text — in EXACTLY one of
these two shapes:

Shape A  (the node CAN be adapted):
{{
  "decision": "adapt",
  "updatedNode": {{ <full updated node definition as JSON, same schema as the input node> }}
}}

Shape B  (the capability must be re-generated):
{{
  "decision": "regenerate",
  "betterPrompt": "<a clear, detailed prompt/instructions to produce {regen_hint}>"
}}

Rules for shape A:
- You may rename / remap inputBindings keys and declaredOutputs names to match the real
  capability's parameter names, as long as semantic intent is preserved.
- If required inputParameters are missing bindings, ADD them using {{{{nodeId.paramName}}}}
  template syntax, where nodeId and paramName come from the upstream outputs listed above.
- You must NOT change nodeId, type, or capabilityRef.capabilityId.
- If the mismatch is too deep (different data shapes, missing critical fields), choose B.

Rules for shape B:
- Write a betterPrompt that is self-contained and detailed enough for {regen_hint}.
"""

        try:
            llm_response = (await async_llm_call(arbitration_prompt)).strip()
            raw = _strip_llm_json_fences(llm_response)
            try:
                decision_obj = json.loads(raw)
            except json.JSONDecodeError:
                decision_obj = json.loads(repair_json(raw))
        except Exception as e:
            logger.warning(
                f"[6p] LLM arbitration failed for node '{node.nodeId}': {e} — skipping."
            )
            continue

        decision = decision_obj.get("decision")

        # ── 4d — adapt: apply the LLM-updated node definition in-place ───────
        if decision == "adapt":
            updated_raw = decision_obj.get("updatedNode")
            if not updated_raw:
                logger.warning(
                    f"[6p] LLM returned 'adapt' for node '{node.nodeId}' "
                    "but provided no updatedNode — skipping."
                )
                continue
            try:
                updated_node = GraphNode.model_validate(updated_raw)

                # ── FIX: capabilityRef may be None if LLM drops it ────────────
                if (
                    updated_node.nodeId != node.nodeId
                    or not updated_node.capabilityRef
                    or updated_node.capabilityRef.capabilityId != node.capabilityRef.capabilityId
                ):
                    logger.warning(
                        f"[6p] LLM tried to mutate nodeId or capabilityId for "
                        f"'{node.nodeId}' — rejected."
                    )
                    continue

                for i, gn in enumerate(graph.nodes):
                    if gn.nodeId == node.nodeId:
                        updated_node.type = _canonical_graph_node_type(
                            updated_node.type,
                            capability_kind=(updated_node.capabilityRef.kind if updated_node.capabilityRef else ""),
                            node_id=updated_node.nodeId,
                        )
                        graph.nodes[i] = updated_node
                        break
                logger.info(f"[6p] Node '{node.nodeId}' adapted via LLM ✓")
            except Exception as e:
                logger.warning(
                    f"[6p] Failed to parse LLM updatedNode for '{node.nodeId}': {e}"
                )

        # ── 4e — regenerate: DISABLED (causes duplicate full UI/tool rebuilds) ─
        # Temporarily skip 6p regenerate. Keep adapt path + validation above.
        elif decision == "regenerate":
            logger.warning(
                f"[6p] LLM returned 'regenerate' for node '{node.nodeId}' — "
                "regeneration is temporarily disabled; skipping."
            )
            continue
            # better_prompt_from_llm = decision_obj.get("betterPrompt", "").strip()
            # if not better_prompt_from_llm:
            #     logger.warning(
            #         f"[6p] LLM returned 'regenerate' for node '{node.nodeId}' "
            #         "but provided no betterPrompt — skipping."
            #     )
            #     continue
            #
            # # node.config.generation is already None (cleared by _resolve_gap_generations),
            # # so we use node.name as the context anchor for the prompt.
            # final_prompt = f"Node: {node.name}\n\n{better_prompt_from_llm}".strip()
            #
            # try:
            #     if cap_is_ui:
            #         new_screen_id = generate_screen_id("screen")
            #         payload: Dict[str, Any] = {
            #             "project_id": project_id,
            #             "screen_id": new_screen_id,
            #             "screen_name": node.name,
            #             "prompt": final_prompt,
            #             "orgId": org_id,
            #             "subscriberId": subscriber_id,
            #             "userId": user_id,
            #         }
            #         result = await generate_angular_app_async(payload)
            #         new_cap_id = f"ui:{result.get('screen_id', new_screen_id)}"
            #         new_kind = "ui_screen"
            #     else:
            #         in_params: list[GenerationIOParam] = []
            #         for k in (node.config.inputBindings or {}).keys():
            #             in_params.append(GenerationIOParam(name=k, dataType="Any", required=True))
            #         if not in_params:
            #             for p in real_cap.inputParameters or []:
            #                 nm = p.get("name")
            #                 if nm:
            #                     in_params.append(GenerationIOParam(
            #                         name=str(nm),
            #                         dataType=str(p.get("dataType") or "Any"),
            #                         required=bool(p.get("required", False)),
            #                         description=str(p.get("description") or ""),
            #                     ))
            #         outs = list(node.config.declaredOutputs or [])
            #         if not outs:
            #             for p in real_cap.outputParameters or []:
            #                 nm = p.get("name")
            #                 if nm:
            #                     outs.append(GenerationIOParam(
            #                         name=str(nm),
            #                         dataType=str(p.get("dataType") or "Any"),
            #                         required=False,
            #                         description=str(p.get("description") or ""),
            #                     ))
            #         gen_stub = GenerationSpec(
            #             kind="tool",
            #             stepId=node.stepId or "",
            #             description=final_prompt,
            #             inputs=in_params,
            #             outputs=outs,
            #         )
            #         tool_key = _gap_unique_dynamic_tool_key(node, subscriber_id=subscriber_id)
            #         io_contract = _gap_generation_io_contract_dict(gen_stub)
            #         new_cap_id = await _generate_gap_tool_and_upsert_capability(
            #             node,
            #             gen_stub,
            #             tool_key=tool_key,
            #             io_contract=io_contract,
            #             org_id=org_id,
            #             subscriber_id=subscriber_id,
            #             user_id=user_id,
            #             project_id=project_id or "",
            #             available_credentials=available_credentials,
            #         )
            #         new_kind = "tool"
            #
            #     for gn in graph.nodes:
            #         if gn.nodeId == node.nodeId:
            #             gn.capabilityRef.capabilityId = new_cap_id
            #             gn.capabilityRef.kind = new_kind
            #             gn.type = _canonical_graph_node_type(
            #                 gn.type,
            #                 capability_kind=new_kind,
            #                 node_id=gn.nodeId,
            #             )
            #             break
            #
            #     new_gen_ids.append(new_cap_id)
            #     logger.info(
            #         f"[6p] Node '{node.nodeId}' re-generated ({new_kind}) → {new_cap_id} "
            #         f"(depth {_recursion_depth})"
            #     )
            # except Exception as e:
            #     logger.warning(
            #         f"[6p] Re-generation failed for node '{node.nodeId}': {e}"
            #     )

        else:
            logger.warning(
                f"[6p] LLM returned unknown decision '{decision}' "
                f"for node '{node.nodeId}' — skipping."
            )

    # ── 5. Recurse only for nodes that were re-generated ─────────────────────
    if new_gen_ids:
        logger.info(
            f"[6p] Recursing for {len(new_gen_ids)} re-generated cap(s): {new_gen_ids} "
            f"(depth → {_recursion_depth + 1})"
        )
        graph = await _revalidate_after_gap_gen(
            graph,
            new_gen_ids,
            user_context,
            global_caps,
            max_rounds=max_rounds,
            project_id=project_id,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            api_key=api_key,
            _recursion_depth=_recursion_depth + 1,
            available_credentials=available_credentials,
        )

    return graph


async def _enrich_tool_nodes_with_source_and_class_path(
    graph: GraphDefinition,
    *,
    tenant: Dict[str, Optional[str]],
) -> GraphDefinition:
    """
    After the LLM produces the graph, attach tool execution metadata to each tool node:
      - `capabilityRef.source`
      - `capabilityRef.class_path`
      - `capabilityRef.version`

    Lookup uses the same tenant triple as registration (subscriber-scoped gap tools
    plus platform prebuilt tools). Missing class_path after lookup+fallback raises —
    LangGraph emit must never persist class_path: null on a resolved tool node.
    """
    if not graph or not getattr(graph, "nodes", None):
        return graph

    updated_graph = graph.model_copy(deep=True)

    tool_cap_ids: set[str] = set()
    for node in updated_graph.nodes:
        cap = node.capabilityRef
        if not cap:
            continue
        if (cap.kind or "").strip().lower() != "tool":
            continue
        cap_id = (cap.capabilityId or "").strip()
        if not cap_id or cap_id.startswith("GENERATE:"):
            continue
        tool_cap_ids.add(cap_id)

    if not tool_cap_ids:
        return updated_graph

    lookup_tenant = tenant or {}
    cap_docs: Dict[str, Dict[str, Any]] = {}
    lookup_misses: list[str] = []
    for cap_id in tool_cap_ids:
        try:
            doc = await capability_repository.get_latest_capability_by_id(
                tenant=lookup_tenant,
                capability_id=cap_id,
            )
        except Exception as e:
            logger.warning(f"[enrich_graph] capability fetch failed ({cap_id}): {e}")
            doc = None
        if doc:
            cap_docs[cap_id] = doc
        else:
            lookup_misses.append(cap_id)
            logger.error(
                "[enrich_graph] capability lookup missed cap_id=%s tenant=%s",
                cap_id,
                {
                    "orgId": lookup_tenant.get("orgId"),
                    "subscriberId": lookup_tenant.get("subscriberId"),
                },
            )

    missing_class_path: list[str] = []
    for node in updated_graph.nodes:
        cap = node.capabilityRef
        if not cap or (cap.kind or "").strip().lower() != "tool":
            continue
        cap_id = (cap.capabilityId or "").strip()
        if not cap_id or cap_id.startswith("GENERATE:"):
            continue
        doc = cap_docs.get(cap_id)
        merged = merge_tool_capability_ref_metadata(
            capability_id=cap_id,
            doc=doc,
            existing_source=cap.source,
            existing_class_path=cap.class_path,
            existing_version=cap.version,
            existing_wrapper_class=cap.wrapper_class,
            existing_wrapper_kwarg=cap.wrapper_kwarg,
        )
        cap.source = merged.get("source")
        cap.class_path = merged.get("class_path")
        cap.version = merged.get("version")
        if merged.get("wrapper_class"):
            cap.wrapper_class = merged["wrapper_class"]
        if merged.get("wrapper_kwarg"):
            cap.wrapper_kwarg = merged["wrapper_kwarg"]
        if not (cap.class_path or "").strip():
            missing_class_path.append(f"{node.nodeId}:{cap_id}")

    if missing_class_path:
        raise RuntimeError(
            "Tool capabilityRef.class_path is null after enrichment for: "
            + ", ".join(missing_class_path)
            + (f" (lookup missed: {', '.join(lookup_misses)})" if lookup_misses else "")
        )

    return updated_graph


def _generate_dynamic_phase_code(
    phase_result: "PhaseGraphResult",
    workflow_name: str,
    global_caps: Optional[list] = None,
) -> str:
    """
    Generates a complete, self-contained Python LangGraph module for a DYNAMIC phase.

    Architecture of the generated module
    ─────────────────────────────────────
    State  : DynamicAgentState  { messages, global_inputs, node_outputs, iteration_count }
    Tools  : one @tool per non-router / non-end node in the phase graph
               • ui_screen kind → calls interrupt()  (pauses graph for human)
               • tool kind      → calls execute_dynamic_tool()
               • agent kind     → returns a stub dict
    LLM    : Gemini (gemini-3.6-flash) bound to all tools
    Loop   : START → llm_node ↔ tool_node → END   (ReAct pattern)
    Guards : MAX_ITERATIONS=20, error-safe tool_node that re-raises GraphInterrupt
    """
    import json

    graph_def = phase_result.graph
    phase_id   = graph_def.phaseId or "dynamic_phase"
    phase_desc = graph_def.description or graph_def.goal or workflow_name

    # Build a lookup: capabilityId → StepCapabilityCandidate (for descriptions/params).
    cap_lookup: dict = {}
    if global_caps:
        for c in global_caps:
            cap_lookup[c.capabilityId] = c

    # Collect non-router, non-end nodes only.
    capability_nodes = [
        n for n in graph_def.nodes
        if n.type not in ("router", "fallback_router", "end")
        and n.capabilityRef is not None
    ]

    code: list[str] = []

    # ── Imports ──────────────────────────────────────────────────────────────
    code.append("from typing import TypedDict, Annotated, Sequence, Dict, Any, List, Optional")
    code.append("from langgraph.graph import StateGraph, START, END")
    # interrupt lives in langgraph.types; GraphInterrupt is the exception it raises,
    # which lives in langgraph.errors — keep them separate to avoid ImportError.
    code.append("from langgraph.types import interrupt")
    code.append("from langgraph.errors import GraphInterrupt")
    code.append("from langgraph.graph.message import add_messages")
    code.append("from langchain_core.messages import BaseMessage, HumanMessage, SystemMessage, ToolMessage, AIMessage")
    code.append("from langchain_core.tools import tool")
    code.append("from langchain_google_genai import ChatGoogleGenerativeAI")
    code.append("import os, json, traceback\n")

    # ── Fallback execute_dynamic_tool (injected at runtime by executor) ──────
    # Raises instead of returning an error dict so accidental direct execution
    # fails loudly rather than silently propagating an error payload as valid data.
    code.append("if 'execute_dynamic_tool' not in globals():")
    code.append("    def execute_dynamic_tool(tool_name: str, params: dict) -> Any:")
    code.append("        raise RuntimeError(")
    code.append("            f'execute_dynamic_tool is not injected. '")
    code.append("            f'This graph must be loaded via WorkflowExecutionController._load_graph(). '")
    code.append("            f'Tool {tool_name!r} cannot be called in standalone mode.'")
    code.append("        )\n")
    code.extend(_TOOL_RESULT_HELPERS)
    code.append("")

    # ── State helpers ─────────────────────────────────────────────────────────
    code.append("def _merge_node_outputs(a: Dict[str, Any], b: Dict[str, Any]) -> Dict[str, Any]:")
    code.append("    merged = dict(a) if a else {}")
    code.append("    if b:")
    code.append("        merged.update(b)")
    code.append("    return merged\n")

    # ── State ─────────────────────────────────────────────────────────────────
    code.append("class DynamicAgentState(TypedDict):")
    code.append("    messages: Annotated[Sequence[BaseMessage], add_messages]")
    code.append("    global_inputs: Dict[str, Any]")
    # Use a merge reducer so tool results accumulate across iterations.
    code.append("    node_outputs: Annotated[Dict[str, Any], _merge_node_outputs]")
    code.append("    iteration_count: int\n")

    # ── Guard ─────────────────────────────────────────────────────────────────
    code.append("MAX_ITERATIONS = 20\n")
    # Marker so the executor can detect the graph type at load time.
    code.append("GRAPH_TYPE = 'DYNAMIC'\n")

    # ── Tool definitions ──────────────────────────────────────────────────────
    tool_fn_names: list[str] = []

    for node in capability_nodes:
        cap_ref  = node.capabilityRef
        cap_id   = cap_ref.capabilityId if cap_ref else ""
        cap_kind = (cap_ref.kind if cap_ref else "") or node.type

        # Safe Python function name from nodeId
        fn_name = "tool_" + re.sub(r"\W", "_", node.nodeId)
        tool_fn_names.append(fn_name)

        # Determine parameter names from inputBindings keys.
        # For DYNAMIC ReAct, we expose every declared param so the LLM can fill them.
        ib_keys: list[str] = list((node.config.inputBindings or {}).keys())

        # Enrich with capability registry params if available.
        cap_doc = cap_lookup.get(cap_id)
        registry_params: list[dict] = []
        if cap_doc and cap_doc.inputParameters:
            registry_params = list(cap_doc.inputParameters)
            ib_keys = [p["name"] for p in registry_params if p.get("name")]
        elif not ib_keys and cap_id.startswith("tool:"):
            _tool_key = cap_id.replace("tool:", "", 1)
            _tool_def = tool_registry.tool_definitions.get(_tool_key)
            if _tool_def and getattr(_tool_def, "parameters", None):
                ib_keys = [p.name for p in _tool_def.parameters if getattr(p, "name", None)]

        # Build description — prefer capability_repository data, fall back to node name.
        if cap_doc and cap_doc.description:
            base_desc = cap_doc.description
        else:
            base_desc = node.name

        # For UI screens, tell the LLM this pauses the workflow for human input.
        if cap_kind == "ui_screen" or cap_id.startswith("ui:"):
            base_desc = f"[UI SCREEN] {base_desc}. Pauses the workflow and shows a UI screen to the user. Resumes when user submits their response."
        elif cap_id.startswith("agent:workflow:"):
            base_desc = f"[AGENT] {base_desc}. Invokes a sub-agent workflow."

        # Append output hints so the LLM knows what to expect back.
        out_hints = [o.name for o in (node.config.declaredOutputs or [])]
        if out_hints:
            base_desc += f" Returns: {', '.join(out_hints)}."

        # Produce a safe single-line docstring: normalise newlines, replace double
        # quotes with single quotes, and remove any triple-double-quote sequences
        # that would prematurely close the generated """...""" docstring.
        safe_desc = base_desc.replace("\n", " ").replace('"""', "'''").replace('"', "'")

        # Build param signature string — everything is str, LLM passes JSON if needed.
        if ib_keys:
            params_sig = ", ".join(f"{k}: str = ''" for k in ib_keys)
            params_dict_items = ", ".join(f'"{k}": {k}' for k in ib_keys)
            params_dict_code  = "{" + params_dict_items + "}"
        else:
            params_sig = "input_data: str = ''"
            params_dict_code = '{"input_data": input_data}'

        code.append(f"@tool")
        code.append(f"def {fn_name}({params_sig}) -> str:")
        code.append(f'    """{safe_desc}"""')

        if cap_kind == "ui_screen" or cap_id.startswith("ui:"):
            screen_id = cap_id.replace("ui:", "", 1) if cap_id.startswith("ui:") else cap_id
            code.append(f"    user_response = interrupt({{")
            code.append(f"        'screen_id': {json.dumps(screen_id)},")
            code.append(f"        'assigned_to': 'human_user',")
            code.append(f"        'ui_data': {params_dict_code}")
            code.append(f"    }})")
            code.append(f"    return json.dumps(user_response) if isinstance(user_response, dict) else str(user_response)")

        elif cap_kind in ("tool",) or cap_id.startswith("tool:"):
            raw_tool_name = cap_id.replace("tool:", "", 1) if cap_id.startswith("tool:") else node.name
            code.append(f"    result = execute_dynamic_tool({json.dumps(raw_tool_name)}, {params_dict_code})")
            code.append(f"    result = _await_successful_tool_result({json.dumps(raw_tool_name)}, result, lambda: execute_dynamic_tool({json.dumps(raw_tool_name)}, {params_dict_code}))")
            code.append(f"    return json.dumps(result) if isinstance(result, dict) else str(result)")

        elif cap_id.startswith("agent:workflow:"):
            wf_id = cap_id.replace("agent:workflow:", "", 1)
            code.append(f"    return json.dumps({{'status': 'agent_invoked', 'workflow_id': {json.dumps(wf_id)}}})")

        else:
            # Generic fallback — treat as tool
            code.append(f"    result = execute_dynamic_tool({json.dumps(node.name)}, {params_dict_code})")
            code.append(f"    result = _await_successful_tool_result({json.dumps(node.name)}, result, lambda: execute_dynamic_tool({json.dumps(node.name)}, {params_dict_code}))")
            code.append(f"    return json.dumps(result) if isinstance(result, dict) else str(result)")

        code.append("")

    # ── Tool list ─────────────────────────────────────────────────────────────
    tools_list_str = ", ".join(tool_fn_names) if tool_fn_names else ""
    code.append(f"_all_tools = [{tools_list_str}]\n")

    # Map tool function name → canonical nodeId for storing results correctly.
    fn_to_node_map = {}
    for node, fn in zip(capability_nodes, tool_fn_names):
        fn_to_node_map[fn] = node.nodeId
    code.append(f"_tool_fn_to_node_id = {repr(fn_to_node_map)}\n")

    # ── LLM setup (lazy — avoids constructor failure during postgen validation) ──
    code.append("_llm = None")
    code.append("def _get_llm():")
    code.append("    global _llm")
    code.append("    if _llm is None:")
    code.append("        _llm = ChatGoogleGenerativeAI(")
    code.append("            model='gemini-3.6-flash',")
    code.append("            google_api_key=os.getenv('GEMINI_API_KEY', ''),")
    code.append("            temperature=0,")
    code.append("        ).bind_tools(_all_tools)")
    code.append("    return _llm\n")

    # ── System prompt ─────────────────────────────────────────────────────────
    # Build the prompt as a plain Python string, then emit it via repr() so the
    # generated .py file is always syntactically valid regardless of quotes,
    # backslashes, or embedded JSON in capability descriptions.
    # Keep step descriptions concise (just name + kind hint) — the full IO
    # contract is already in each tool's docstring where the LLM can reference it
    # when deciding how to call the tool. Bloating the system prompt with raw JSON
    # degrades LLM reasoning and risks token-limit issues.
    step_lines_for_prompt: list[str] = []
    for i, n in enumerate(capability_nodes, 1):
        step_kind = ""
        if n.capabilityRef:
            cid = n.capabilityRef.capabilityId
            if cid.startswith("ui:"):
                step_kind = " [UI Screen — pauses for human input]"
            elif cid.startswith("agent:workflow:"):
                step_kind = " [Sub-Agent]"
        step_lines_for_prompt.append(f"{i}. {n.name}{step_kind}")

    steps_joined = " | ".join(step_lines_for_prompt)
    # Detect conditional/branching phases: if the graph has any router node,
    # the capability nodes are not all sequential — some are mutually exclusive.
    # Tell the LLM to pick the right branch rather than blindly calling every tool.
    has_branches = any(
        n.type in ("router", "fallback_router") for n in graph_def.nodes
    )
    conditional_note = (
        " Some steps are mutually exclusive branches — only invoke the tool whose"
        " name and description best matches the current outcome, do NOT call all tools."
        if has_branches else ""
    )

    full_prompt_value = (
        f'You are an AI agent executing the "{workflow_name}" workflow. '
        f'Phase goal: {phase_desc.replace(chr(10), " ")}. '
        f'Available tools: {steps_joined}. '
        f'Rules: '
        f'(1) Call tools one at a time in the specified order.{conditional_note} '
        f'(2) [UI Screen] tools pause execution and wait for human input — do NOT skip them. '
        f'(3) If a tool returns an error, report it and stop further execution. '
        f'(4) When ALL required steps are completed, stop calling tools and give a concise summary.'
    )
    code.append(f"_SYSTEM_PROMPT = {repr(full_prompt_value)}\n")

    # ── llm_node ──────────────────────────────────────────────────────────────
    code.append("def llm_node(state: DynamicAgentState) -> dict:")
    code.append("    iteration = state.get('iteration_count') or 0")
    code.append("    if iteration >= MAX_ITERATIONS:")
    code.append("        return {'messages': [AIMessage(content='Max iterations reached. Stopping.')], 'iteration_count': iteration}")
    code.append("    system_msg = SystemMessage(content=_SYSTEM_PROMPT)")
    code.append("    existing_msgs = list(state.get('messages') or [])")
    # On the very first call there are no user messages. Build a kickoff HumanMessage
    # from global_inputs so the LLM has full context (execution_id, workflow_id, any
    # user-supplied inputs).  Without this the LLM would only see the system prompt
    # and respond with 'How can I help?' instead of starting the workflow.
    code.append("    if not existing_msgs:")
    code.append("        gi = state.get('global_inputs') or {}")
    code.append("        kickoff_text = 'Start executing the workflow now.'")
    code.append("        if gi:")
    code.append("            kickoff_text += f' Workflow context: {json.dumps(gi, default=str)}'")
    code.append("        existing_msgs = [HumanMessage(content=kickoff_text)]")
    code.append("    response = _get_llm().invoke([system_msg] + existing_msgs)")
    code.append("    return {'messages': [response], 'iteration_count': iteration + 1}\n")

    # ── tool_node ─────────────────────────────────────────────────────────────
    code.append("def tool_node(state: DynamicAgentState) -> dict:")
    code.append("    last_msg = state['messages'][-1]")
    code.append("    tool_results: list = []")
    code.append("    _tool_map = {t.name: t for t in _all_tools}")
    code.append("    node_outputs_update: dict = {}")
    code.append("    for tc in getattr(last_msg, 'tool_calls', []):")
    code.append("        tool_fn = _tool_map.get(tc['name'])")
    code.append("        if not tool_fn:")
    code.append("            tool_results.append(ToolMessage(content=f\"Unknown tool: {tc['name']}\", tool_call_id=tc['id']))")
    code.append("            continue")
    code.append("        try:")
    code.append("            result = tool_fn.invoke(tc['args'])")
    code.append("            tool_results.append(ToolMessage(content=str(result), tool_call_id=tc['id']))")
    code.append("            node_id_key = _tool_fn_to_node_id.get(tc['name'], tc['name'])")
    code.append("            parsed = result")
    code.append("            if isinstance(result, str):")
    code.append("                try:")
    code.append("                    import json as _json; parsed = _json.loads(result)")
    code.append("                except Exception:")
    code.append("                    pass")
    code.append("            node_outputs_update[node_id_key] = parsed")
    code.append("        except GraphInterrupt:")
    code.append("            raise")
    code.append("        except RuntimeError:")
    code.append("            raise")
    code.append("        except Exception as exc:")
    code.append("            err_detail = traceback.format_exc()")
    code.append("            tool_results.append(ToolMessage(content=f'Tool error: {exc}\\n{err_detail}', tool_call_id=tc['id']))")
    code.append("    return {'messages': tool_results, 'node_outputs': node_outputs_update}\n")

    # ── should_continue ───────────────────────────────────────────────────────
    code.append("def should_continue(state: DynamicAgentState) -> str:")
    code.append("    if state.get('iteration_count', 0) >= MAX_ITERATIONS:")
    code.append("        return 'end'")
    code.append("    last_msg = state['messages'][-1]")
    code.append("    if getattr(last_msg, 'tool_calls', None):")
    code.append("        return 'continue'")
    code.append("    return 'end'\n")

    # ── Builder ───────────────────────────────────────────────────────────────
    code.append("builder = StateGraph(DynamicAgentState)")
    code.append("builder.add_node('llm_node', llm_node)")
    code.append("builder.add_node('tool_node', tool_node)")
    code.append("builder.add_edge(START, 'llm_node')")
    code.append("builder.add_conditional_edges(")
    code.append("    'llm_node', should_continue,")
    code.append("    {'continue': 'tool_node', 'end': END}")
    code.append(")")
    code.append("builder.add_edge('tool_node', 'llm_node')")

    return "\n".join(code)


def _build_freeze_phase_edges(
    phase_result: Any,
    builder_var: str,
    safe_phase_id: str,
    code: list,
) -> None:
    """
    Appends FREEZE phase node-function and edge code to `code`.
    Node functions are prefixed with `safe_phase_id` to avoid name collisions
    when multiple FREEZE phases live in the same module.
    `builder_var` is the name of the StateGraph variable to add nodes/edges to.
    """
    graph_def   = phase_result.graph
    nodes       = graph_def.nodes
    edges       = graph_def.edges

    entry_node: str = ""
    if graph_def.entryNodeId:
        entry_node = str(graph_def.entryNodeId).replace("-", "_")

    edges_by_source: dict = {}

    code.append(f"# Node functions for {safe_phase_id}")
    for node in nodes:
        n_id = node.nodeId
        if not n_id or node.type == "end":
            continue
        safe_n_id = str(n_id).replace("-", "_")

        if node.type in ("router", "fallback_router"):
            # Router nodes are pure control-flow — all logic lives in the conditional
            # edge function generated below.  A pass-through lambda keeps node_outputs
            # clean (no empty {} entries) and makes the intent explicit.
            code.append(f"{builder_var}.add_node('{safe_n_id}', lambda state: {{}})\n")
        else:
            fn_name   = f"node_{safe_phase_id}_{safe_n_id}"
            node_dict = node.model_dump()
            # repr() produces valid Python (None/True/False); json.dumps produces
            # JSON (null/true/false) which causes NameError at runtime.
            code.append(f"def {fn_name}(state):")
            code.append(f"    node_def = {repr(node_dict)}")
            code.append(f"    return _execute_dynamic_node(node_def, state)")
            code.append(f"{builder_var}.add_node('{safe_n_id}', {fn_name})\n")

    for edge in edges:
        src  = edge.fromNode
        tgt  = edge.to
        cond = edge.condition
        if not (src and tgt):
            continue
        safe_src = str(src).replace("-", "_")
        safe_tgt = str(tgt).replace("-", "_")
        target_node_obj = next((n for n in nodes if n.nodeId == tgt), None)
        if (target_node_obj and target_node_obj.type == "end") or safe_tgt == "end_node":
            safe_tgt = "END"
        edges_by_source.setdefault(safe_src, []).append({"target": safe_tgt, "condition": cond})

    if entry_node:
        code.append(f"{builder_var}.add_edge(START, '{entry_node}')")

    for src, target_list in edges_by_source.items():
        if len(target_list) == 1 and not target_list[0].get("condition"):
            tgt_val = target_list[0]["target"]
            tgt_fmt = f"'{tgt_val}'" if tgt_val != "END" else "END"
            code.append(f"{builder_var}.add_edge('{src}', {tgt_fmt})")
        else:
            router_fn   = f"route_{safe_phase_id}_{src}"
            cond_entries  = [(i, t) for i, t in enumerate(target_list) if t.get("condition")]
            uncond_entries = [(i, t) for i, t in enumerate(target_list) if not t.get("condition")]

            code.append(f"def {router_fn}(state):")
            for idx, t in cond_entries:
                code.append(f"    if _evaluate_condition({repr(t['condition'])}, state):")
                code.append(f"        return 'path_{idx}'")
            # Default: use the explicit unconditional edge if one exists; otherwise fall back
            # to the LAST conditional path (typically the error/failure branch), NOT path_0
            # (which is the success path).  Defaulting to path_0 when no condition matches
            # causes silent business-logic corruption (e.g. null status → takes success path).
            if uncond_entries:
                default_path = f"path_{uncond_entries[0][0]}"
            elif cond_entries:
                default_path = f"path_{cond_entries[-1][0]}"
            else:
                default_path = "path_0"
            code.append(f"    _GRAPH_LOG.warning('[GRAPH] event=router_no_match router=%r defaulting_to=%r', '{router_fn}', '{default_path}', extra={{'graph_event': 'router_no_match', 'router': '{router_fn}', 'default': '{default_path}'}})")
            code.append(f"    return '{default_path}'\n")

            cmap: dict = {}
            for idx, t in cond_entries:
                tv = t["target"]
                cmap[f"path_{idx}"] = tv if tv != "END" else "END"
            if uncond_entries:
                di, dt = uncond_entries[0]
                cmap[default_path] = dt["target"] if dt["target"] != "END" else "END"

            map_str = "{" + ", ".join(
                f"'{k}': {('END' if v == 'END' else repr(v))}" for k, v in cmap.items()
            ) + "}"
            code.append(f"{builder_var}.add_conditional_edges('{src}', {router_fn}, {map_str})\n")


def _build_dynamic_phase_block(
    phase_result: Any,
    workflow_name: str,
    safe_phase_id: str,
    builder_var: str,
    global_caps: Optional[list],
    code: list,
    cross_phase_node_outputs: Optional[dict] = None,
) -> None:
    """
    Appends DYNAMIC (ReAct) phase code to `code` in *integrated* mode:
    no standalone imports — those are already in the combined-file header.
    All generated identifiers are suffixed with `safe_phase_id` so multiple

    cross_phase_node_outputs: {node_id: [output_key, ...]} map built from ALL
    preceding phases.  Used to validate and auto-repair inputBinding templates
    whose source node reference is stale/wrong (e.g. LLM planner wrote
    {{start_node.ekyc_record_id}} instead of {{start_ekyc_process.ekyc_record_id}}).
    DYNAMIC phases can coexist in the same module without name collisions.
    `builder_var` is the StateGraph variable to build into.
    """
    graph_def   = phase_result.graph
    phase_desc  = graph_def.description or graph_def.goal or workflow_name

    cap_lookup: dict = {}
    if global_caps:
        for c in global_caps:
            cap_lookup[c.capabilityId] = c

    capability_nodes = [
        n for n in graph_def.nodes
        if n.type not in ("router", "fallback_router", "end")
        and n.capabilityRef is not None
    ]

    tool_fn_names: list = []
    _seen_tool_fn_names: dict = {}  # base_name → count, for deduplication

    for node in capability_nodes:
        cap_ref  = node.capabilityRef
        cap_id   = cap_ref.capabilityId if cap_ref else ""
        cap_kind = (cap_ref.kind if cap_ref else "") or node.type

        clean_node_id = re.sub(r"\W", "_", node.nodeId)
        base_fn_name = f"tool_{safe_phase_id}_{clean_node_id}"

        # Deduplicate: if two nodes produce the same function name (e.g. same
        # nodeId in different capabilities), the second one would silently shadow
        # the first in Python. Append _v2, _v3 … to keep both distinct.
        if base_fn_name not in _seen_tool_fn_names:
            _seen_tool_fn_names[base_fn_name] = 1
            fn_name = base_fn_name
        else:
            _seen_tool_fn_names[base_fn_name] += 1
            fn_name = f"{base_fn_name}_v{_seen_tool_fn_names[base_fn_name]}"
            logger.warning(
                f"[code_gen] {safe_phase_id}: duplicate tool fn name '{base_fn_name}' "
                f"→ renamed to '{fn_name}' (nodeId={node.nodeId!r}, cap={cap_id!r})"
            )

        tool_fn_names.append(fn_name)

        ib_keys: list = list((node.config.inputBindings or {}).keys())
        cap_doc = cap_lookup.get(cap_id)
        if cap_doc and cap_doc.inputParameters:
            # Use authoritative parameter names from the capability registry
            ib_keys = [p["name"] for p in cap_doc.inputParameters if p.get("name")]
        elif not ib_keys and cap_id.startswith("tool:"):
            # Fallback for gap-generated tools not yet in global_caps:
            # look up the in-process tool registry for required parameters.
            _tool_key = cap_id.replace("tool:", "", 1)
            _tool_def = tool_registry.tool_definitions.get(_tool_key)
            if _tool_def and getattr(_tool_def, "parameters", None):
                ib_keys = [p.name for p in _tool_def.parameters if getattr(p, "name", None)]
                logger.info(
                    f"[code_gen] {safe_phase_id}: gap-tool '{_tool_key}' params from registry: {ib_keys}"
                )

        if cap_doc and cap_doc.description:
            base_desc = cap_doc.description
        else:
            base_desc = node.name
        if cap_kind == "ui_screen" or cap_id.startswith("ui:"):
            base_desc = f"[UI SCREEN] {base_desc}. Pauses for human input."
        elif cap_id.startswith("agent:workflow:"):
            base_desc = f"[AGENT] {base_desc}. Invokes a sub-agent workflow."
        out_hints = [o.name for o in (node.config.declaredOutputs or [])]
        if out_hints:
            base_desc += f" Returns: {', '.join(out_hints)}."
        safe_desc = base_desc.replace("\n", " ").replace('"""', "'''").replace('"', "'")

        if ib_keys:
            params_sig  = ", ".join(f"{k}: str = ''" for k in ib_keys)
            params_dict = "{" + ", ".join(f'"{k}": {k}' for k in ib_keys) + "}"
        else:
            # Node has no input bindings — the screen/tool collects its own inputs.
            # Do NOT add a generic 'input_data' param: it confuses the LLM into
            # thinking it must supply a value, and passes {"input_data": ""} as
            # ui_data to the screen instead of the correct empty-dict payload.
            params_sig  = ""
            params_dict = "{}"

        if not (cap_doc and cap_doc.inputParameters) and ib_keys:
            code.append(
                f"# WARNING: capability '{cap_id}' not in registry; "
                f"tool params derived from inputBindings (may be incorrect)."
            )
        code.append(f"@tool")
        code.append(f"def {fn_name}({params_sig}) -> str:")
        code.append(f'    """{safe_desc}"""')

        if cap_kind == "ui_screen" or cap_id.startswith("ui:"):
            screen_id = cap_id.replace("ui:", "", 1) if cap_id.startswith("ui:") else cap_id
            code.append(f"    user_response = interrupt({{")
            code.append(f"        'screen_id': {json.dumps(screen_id)},")
            code.append(f"        'assigned_to': 'human_user',")
            code.append(f"        'ui_data': {params_dict}")
            code.append(f"    }})")
            code.append(f"    return json.dumps(user_response) if isinstance(user_response, dict) else str(user_response)")
        elif cap_kind in ("tool",) or cap_id.startswith("tool:"):
            raw_tool = cap_id.replace("tool:", "", 1) if cap_id.startswith("tool:") else node.name
            code.append(f"    result = execute_dynamic_tool({json.dumps(raw_tool)}, {params_dict})")
            code.append(f"    result = _await_successful_tool_result({json.dumps(raw_tool)}, result, lambda: execute_dynamic_tool({json.dumps(raw_tool)}, {params_dict}))")
            code.append(f"    return json.dumps(result) if isinstance(result, dict) else str(result)")
        elif cap_id.startswith("agent:workflow:"):
            wf_id = cap_id.replace("agent:workflow:", "", 1)
            code.append(f"    return json.dumps({{'status': 'agent_invoked', 'workflow_id': {json.dumps(wf_id)}}})")
        else:
            code.append(f"    result = execute_dynamic_tool({json.dumps(node.name)}, {params_dict})")
            code.append(f"    result = _await_successful_tool_result({json.dumps(node.name)}, result, lambda: execute_dynamic_tool({json.dumps(node.name)}, {params_dict}))")
            code.append(f"    return json.dumps(result) if isinstance(result, dict) else str(result)")
        code.append("")

    tools_list = ", ".join(tool_fn_names)
    code.append(f"_all_tools_{safe_phase_id} = [{tools_list}]\n")
    # Lazy-initialize the LLM so that module import (including postgen subprocess
    # validation) never calls the ChatGoogleGenerativeAI constructor without a
    # valid key. The object is created on first llm_node invocation instead.
    code.append(f"_llm_{safe_phase_id} = None")
    code.append(f"def _get_llm_{safe_phase_id}():")
    code.append(f"    global _llm_{safe_phase_id}")
    code.append(f"    if _llm_{safe_phase_id} is None:")
    code.append(f"        _llm_{safe_phase_id} = ChatGoogleGenerativeAI(")
    code.append(f"            model='gemini-3.6-flash',")
    code.append(f"            google_api_key=os.getenv('GEMINI_API_KEY', ''),")
    code.append(f"            temperature=0,")
    code.append(f"        ).bind_tools(_all_tools_{safe_phase_id})")
    code.append(f"    return _llm_{safe_phase_id}\n")

    # System prompt via repr() — safe against any quotes in descriptions.
    #
    # IMPORTANT: Do NOT imply a fixed linear "tool order". DYNAMIC phases may branch
    # (routers) and tools can be mutually exclusive depending on outcomes. The LLM
    # should decide the next tool based on current state and the phase steps.
    phase_name_for_prompt = (getattr(graph_def, "phaseName", None) or safe_phase_id or "").strip() or "phase"
    phase_goal_for_prompt = (getattr(graph_def, "goal", None) or phase_desc or "").strip()

    # "Steps involved" — best available source in codegen is the planned nodes themselves.
    # (The original frontend subSteps are not currently carried into PhaseGraphResult.)
    # Use stepId when present for traceability.
    planned_steps_lines: list[str] = []
    for n in capability_nodes:
        sid = (n.stepId or "").strip()
        if sid:
            planned_steps_lines.append(f"- {n.name}: {sid}")
        else:
            planned_steps_lines.append(f"- {n.name}")
    planned_steps_text = "\n".join(planned_steps_lines) if planned_steps_lines else "- (none)"

    # Available tools list with IO contracts
    # Use the already-deduplicated tool_fn_names (not a fresh re-derivation)
    # so the system prompt shows the exact function name the LLM must call.
    tools_desc_lines: list[str] = []
    for n, fn in zip(capability_nodes, tool_fn_names):
        cap_ref = n.capabilityRef
        cap_id = cap_ref.capabilityId if cap_ref else ""
        cap_kind = (cap_ref.kind if cap_ref else "") or n.type
        kind_label = "UI Screen" if (cap_kind == "ui_screen" or cap_id.startswith("ui:")) else ("Sub-Agent" if cap_id.startswith("agent:workflow:") else "Tool")

        cap_doc = cap_lookup.get(cap_id)
        in_params = []
        if cap_doc and cap_doc.inputParameters:
            for p in cap_doc.inputParameters:
                nm = (p.get("name") or "").strip()
                if nm:
                    req = bool(p.get("required", False))
                    in_params.append(f"{nm}{' (required)' if req else ''}")
        elif n.config.inputBindings:
            for k in n.config.inputBindings.keys():
                in_params.append(f"{k}")
        elif cap_id.startswith("tool:"):
            _tool_key = cap_id.replace("tool:", "", 1)
            _tool_def = tool_registry.tool_definitions.get(_tool_key)
            if _tool_def and getattr(_tool_def, "parameters", None):
                for p in _tool_def.parameters:
                    nm = getattr(p, "name", "")
                    req = getattr(p, "required", False)
                    if nm:
                        in_params.append(f"{nm}{' (required)' if req else ''}")
        out_params = [o.name for o in (n.config.declaredOutputs or []) if getattr(o, "name", None)]

        tools_desc_lines.append(
            f"- Tool name: {fn}\n"
            f"  Purpose: {n.name}\n"
            f"  Kind: {kind_label}\n"
            f"  Inputs: {in_params if in_params else []}\n"
            f"  Outputs: {out_params if out_params else []}"
        )
    tools_desc_text = "\n".join(tools_desc_lines) if tools_desc_lines else "- (no tools)"

    prompt_val = "\n".join([
        "You are an execution agent for ONE workflow phase.",
        "",
        "## Phase",
        f"- Name: {phase_name_for_prompt}",
        f"- Description: {(phase_desc or '').replace(chr(10), ' ').strip()}",
        f"- Goal: {phase_goal_for_prompt.replace(chr(10), ' ').strip()}",
        "",
        "## Steps involved in this phase (from user / plan)",
        "You must complete these steps in a reasonable way. They describe WHAT to achieve; you decide HOW.",
        planned_steps_text,
        "",
        "## Available tools",
        "You may only act by calling the tools listed below. Each tool has an IO contract.",
        tools_desc_text,
        "",
        "## Rules",
        "1) Decide the next best action based on the CURRENT STATE. Do NOT follow a fixed tool order unless the state requires it.",
        "2) Call exactly ONE tool at a time. After each tool result, reassess what remains.",
        "3) Branching is allowed and expected. Some tools are mutually exclusive depending on outcomes (success vs failure). Do NOT call both branches.",
        "4) Do NOT invent inputs. When calling a tool, use the exact parameter names and pass values from state/node_outputs or provided hints.",
        "5) UI Screen tools pause and wait for human input. Never skip them.",
        "6) Stop conditions:",
        "   - If all phase steps are completed, stop calling tools and provide a concise completion summary.",
        "   - If progress cannot continue due to missing required input, stop and clearly state what is missing.",
    ])
    code.append(f"_SYSTEM_PROMPT_{safe_phase_id} = {repr(prompt_val)}\n")

    # llm_node: on iteration==0 (first call of this phase), always inject a phase-kickoff
    # message that includes previous-phase node_outputs AND structurally pre-resolved
    # bindings.  Using iteration==0 (not "if not existing_msgs") is critical for MIXED
    # graphs: the executor seeds messages before the graph starts, so existing_msgs is
    # never empty at phase start — the old guard would silently skip the entire context
    # injection, leaving the LLM blind to all FREEZE-phase outputs.
    code.append(f"def llm_node_{safe_phase_id}(state) -> dict:")
    code.append(f"    iteration = state.get('iteration_count') or 0")
    code.append(f"    if iteration >= MAX_ITERATIONS:")
    code.append(f"        return {{'messages': [AIMessage(content='Max iterations reached. Stopping.')], 'iteration_count': iteration}}")
    code.append(f"    system_msg = SystemMessage(content=_SYSTEM_PROMPT_{safe_phase_id})")
    code.append(f"    existing_msgs = list(state.get('messages') or [])")
    code.append(f"    if iteration == 0:")
    code.append(f"        gi = state.get('global_inputs') or {{}}")
    code.append(f"        no = state.get('node_outputs') or {{}}")
    code.append(f"        kickoff = 'Starting phase. Use the system prompt instructions and available tool IO contracts as guidance.'")
    code.append(f"        if gi:")
    code.append(f"            kickoff += f' Workflow context: {{json.dumps(gi, default=str)}}'")
    code.append(f"        if no:")
    code.append(f"            kickoff += f' Previous phase outputs: {{json.dumps(no, default=str)}}'")
    # Resolve cross-phase bindings strictly from the validated graph definition.
    # NO fuzzy-bind: if the exact source node is not in node_outputs the validation
    # layer should have already caught it. Log a clear warning and skip the hint
    # so the LLM is not misled by a value from the wrong node.
    code.append(f"            _resolved_hints = {{}}")
    code.append(f"            for _fn, _bnds in _PHASE_BINDINGS_{safe_phase_id}.items():")
    code.append(r"                _fh = {}")
    code.append(r"                for _p, _t in _bnds.items():")
    code.append(r"                    if isinstance(_t, str) and '{{' in _t:")
    code.append(r"                        _inners = re.findall(r'\{\{([^}]+)\}\}', _t)")
    code.append(r"                        if len(_inners) == 1:")
    code.append(r"                            _inner = _inners[0].strip()")
    code.append(r"                            _val = None")
    code.append(r"                            _src, _key = '', ''")
    code.append(r"                            if _inner.startswith('global.'):")
    code.append(r"                                _src, _key = 'global', _inner[7:]")
    code.append(r"                                _val = gi.get(_key)")
    code.append(r"                                if _val is None and '.' in _key:")
    code.append(r"                                    _nid, _fld = _key.split('.', 1)")
    code.append(r"                                    _src_out = no.get(_nid)")
    code.append(r"                                    if not isinstance(_src_out, dict):")
    code.append(r"                                        _canon = re.sub(r'[^a-zA-Z0-9_]', '_', str(_nid or ''))")
    code.append(r"                                        _src_out = no.get(_canon) if _canon != _nid else None")
    code.append(r"                                    if isinstance(_src_out, dict):")
    code.append(r"                                        _val = _src_out.get(_fld)")
    code.append(r"                            elif '.' in _inner:")
    code.append(r"                                _src, _key = _inner.split('.', 1)")
    code.append(r"                                _src_out = no.get(_src)")
    code.append(r"                                if isinstance(_src_out, dict):")
    code.append(r"                                    _val = _src_out.get(_key)")
    code.append(r"                            if _val is not None:")
    code.append(r"                                _fh[_p] = _val")
    code.append(r"                            else:")
    code.append(r"                                _GRAPH_LOG.warning('[GRAPH] event=kickoff_hint_skipped param=%r template=%r src=%r key=%r', _p, _t, _src, _key, extra={'graph_event': 'kickoff_hint_skipped', 'param': _p, 'template': _t, 'src': _src})")
    code.append(r"                if _fh:")
    code.append(r"                    _resolved_hints[_fn] = _fh")
    code.append(r"            if _resolved_hints:")
    code.append(r"                kickoff += ' IMPORTANT \u2014 pass these exact pre-resolved values when calling the listed tools: ' + json.dumps(_resolved_hints, default=str)")
    # Persist the kickoff HumanMessage in state so all subsequent LLM calls
    # see the full conversation history (previous phase outputs, pre-resolved
    # hints, etc.).  Without this, the kickoff is only used as a local variable
    # for the first invoke — iteration 1+ sees a conversation missing that context.
    code.append(f"        _kickoff_msg = HumanMessage(content=kickoff)")
    code.append(f"        existing_msgs = existing_msgs + [_kickoff_msg]")
    code.append(f"    _out_msgs: list = []")
    code.append(f"    if iteration == 0:")
    code.append(f"        _out_msgs.append(_kickoff_msg)")
    # Provide a compact progress snapshot EVERY iteration so the LLM knows what already ran.
    # Use a SystemMessage to avoid creating extra HumanMessage turns.
    code.append(r"    try:")
    code.append(r"        _no = state.get('node_outputs') or {}")
    code.append(r"        _executed = list(_no.keys())[-8:] if isinstance(_no, dict) else []")
    code.append(r"        _summ = []")
    code.append(r"        for _nid in _executed:")
    code.append(r"            _out = _no.get(_nid)")
    code.append(r"            if isinstance(_out, dict):")
    code.append(r"                _picked = {_k: (str(_v)[:120] if isinstance(_v, str) and len(str(_v)) > 120 else _v) for _k, _v in list(_out.items())[:15]}")
    code.append(r"                _summ.append({'node': _nid, 'out': _picked})")
    code.append(r"            else:")
    code.append(r"                _summ.append({'node': _nid, 'out': str(_out)[:200]})")
    code.append(r"        _progress_txt = (")
    code.append(r"            '## Progress snapshot\n'")
    code.append(r"            f'- iteration: {iteration}/{MAX_ITERATIONS}\n'")
    code.append(r"            f'- executed_nodes: {_executed}\n'")
    code.append(r"            f'- recent_outputs: {json.dumps(_summ, default=str)[:1200]}\n'")
    code.append(r"            'Instruction: choose the next tool that matches the current state; do not repeat completed steps unnecessarily.'")
    code.append(r"        )")
    code.append(r"    except Exception as _pe:")
    code.append(r"        _progress_txt = f'## Progress snapshot\n- iteration: {iteration}/{MAX_ITERATIONS}\n(note: snapshot build failed: {_pe})'")
    code.append(r"    progress_msg = SystemMessage(content=_progress_txt)")
    code.append(f"    response = _get_llm_{safe_phase_id}().invoke([system_msg, progress_msg] + existing_msgs)")
    code.append(f"    _out_msgs.append(response)")
    code.append(f"    return {{'messages': _out_msgs, 'iteration_count': iteration + 1}}\n")

    # Build a tool-fn-name → nodeId map so results are stored under the canonical
    # nodeId in node_outputs.  This lets downstream FREEZE phase bindings like
    # {{credit_bureau_lookup.credit_score}} resolve correctly even though the LangGraph
    # @tool function is named tool_stage_2_credit_bureau_lookup.
    tool_fn_to_node_id: dict = {
        f"tool_{safe_phase_id}_{re.sub(r'[^a-zA-Z0-9_]', '_', n.nodeId)}": re.sub(r"[^a-zA-Z0-9_]", "_", n.nodeId)
        for n in capability_nodes
    }
    code.append(f"_tool_fn_to_node_id_{safe_phase_id} = {repr(tool_fn_to_node_id)}\n")

    # Translate inputBindings from the validated graph definition into the
    # _PHASE_BINDINGS_* dict used for runtime kickoff hints.
    #
    # This is PURE TRANSLATION — no repair, no guessing.
    # By this point the pipeline has already run:
    #   _validate_graph_structure → _repair_graph_structure_with_llm →
    #   _validate_and_fix_loop → _resolve_gap_generations → _revalidate_after_gap_gen
    # The definition is expected to be correct.  Any bad binding that reaches
    # here is a validation gap that must be fixed in the validation layer, not
    # papered over at codegen time.
    #
    # Guards kept:
    #   - None / non-string  → skip (cannot be represented in generated code)
    #   - empty string       → skip
    # Everything else is emitted verbatim with a diagnostic warning if it
    # looks suspicious (bare ref, unknown node, ALL-CAPS placeholder) so
    # problems surface clearly in logs instead of being silently "fixed".

    # After cross-phase collision namespacing, bindings reference THIS phase's
    # nodeIds (e.g. start_ekyc_verification_stage_2). Those are not listed in
    # cross_phase_node_outputs (prior phases only). Union them so we do not
    # false-warn on valid intra-phase references.
    same_phase_canonical_ids: set = {
        re.sub(r"[^a-zA-Z0-9_]", "_", n.nodeId)
        for n in capability_nodes
        if getattr(n, "nodeId", None)
    }

    phase_bindings: dict = {}
    for node, fn_name in zip(capability_nodes, tool_fn_names):
        raw_bindings = dict(node.config.inputBindings or {})
        translated_bindings: dict = {}

        for param, template in raw_bindings.items():
            # Guard: skip None / non-string (cannot be emitted as a template)
            if template is None or not isinstance(template, str):
                logger.warning(
                    f"[code_gen] {safe_phase_id}/{fn_name}: binding {param!r} "
                    f"has non-string value {template!r}; skipped. Fix in graph definition."
                )
                continue

            # Guard: skip empty string
            if not template.strip():
                logger.warning(
                    f"[code_gen] {safe_phase_id}/{fn_name}: binding {param!r} "
                    f"has empty value; skipped. Fix in graph definition."
                )
                continue

            # Diagnostic: bare {{param}} ref (no node. prefix) — the validation
            # layer should have normalised this to {{node.param}} already.
            if "{{" in template and not re.search(r"\{\{\w+\.\w+\}\}", template):
                logger.warning(
                    f"[code_gen] {safe_phase_id}/{fn_name}: binding {param!r} "
                    f"has bare ref pattern {template!r} (no node prefix). "
                    f"This should have been fixed by the graph validator. "
                    f"Emitting as-is — runtime resolution may fail."
                )

            # Diagnostic: ALL-CAPS placeholder (not a {{}} template)
            elif re.match(r'^[A-Z][A-Z0-9_]{2,}$', template):
                logger.warning(
                    f"[code_gen] {safe_phase_id}/{fn_name}: binding {param!r} "
                    f"has ALL-CAPS literal placeholder {template!r} — not a valid "
                    f"{{{{node.param}}}} template. This should have been fixed by the "
                    f"graph validator. Emitting as-is — runtime resolution will likely fail."
                )

            # Diagnostic: {{unknown_node.key}} — source not in prior phases AND
            # not a node in this DYNAMIC phase (and not global).
            elif "{{" in template:
                refs = iter_template_binding_refs(template)
                if len(refs) == 1:
                    src_node, src_key = refs[0]
                    prior = set(cross_phase_node_outputs or {})
                    valid_sources = prior | same_phase_canonical_ids | {"global"}
                    if src_node not in valid_sources:
                        logger.warning(
                            f"[code_gen] {safe_phase_id}/{fn_name}: binding {param!r} "
                            f"references unknown node {src_node!r} (not in prior phases "
                            f"{sorted(prior)!r} and not in this phase "
                            f"{sorted(same_phase_canonical_ids)!r}). "
                            f"Emitting as-is — runtime resolution may fail."
                        )

            translated_bindings[param] = template

        phase_bindings[fn_name] = translated_bindings

    code.append(f"_PHASE_BINDINGS_{safe_phase_id} = {repr(phase_bindings)}\n")

    # Detect node IDs that collide with preceding FREEZE phase outputs.
    # Emit compile-time warnings and a runtime constant for in-graph warnings.
    freeze_collision_ids: set = set()
    for node, fn_name in zip(capability_nodes, tool_fn_names):
        canonical_id = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
        if cross_phase_node_outputs and canonical_id in cross_phase_node_outputs:
            freeze_collision_ids.add(canonical_id)
            logger.warning(
                f"[code_gen] {safe_phase_id}: DYNAMIC tool '{fn_name}' writes to "
                f"node_outputs['{canonical_id}'] which already contains a FREEZE phase "
                f"result. The FREEZE result will be overwritten at runtime. "
                f"Use a distinct nodeId in the graph plan to avoid silent data corruption."
            )
    # Emit the collision set into the generated file so tool_node can warn at runtime.
    code.append(f"_FREEZE_COLLISION_IDS_{safe_phase_id} = {repr(freeze_collision_ids)}\n")

    # tool_node: store results ONLY under the canonical nodeId (never the raw tool fn name)
    # to avoid key pollution in node_outputs that confuses downstream binding resolution.
    code.append(f"def tool_node_{safe_phase_id}(state) -> dict:")
    code.append(f"    last_msg = state['messages'][-1]")
    code.append(f"    tool_results: list = []")
    code.append(f"    _tool_map = {{t.name: t for t in _all_tools_{safe_phase_id}}}")
    code.append(f"    node_outputs_update: dict = {{}}")
    code.append(f"    for tc in getattr(last_msg, 'tool_calls', []):")
    code.append(f"        tool_fn = _tool_map.get(tc['name'])")
    code.append(f"        if not tool_fn:")
    code.append(f"            tool_results.append(ToolMessage(content=f\"Unknown tool: {{tc['name']}}\", tool_call_id=tc['id']))")
    code.append(f"            continue")
    code.append(f"        try:")
    code.append(f"            _GRAPH_LOG.info('[GRAPH] event=tool_invoke tool=%r args_preview=%r', tc['name'], json.dumps(tc.get('args') or {{}}, default=str)[:400], extra={{'graph_event': 'tool_invoke', 'tool': tc['name']}})")
    code.append(f"            _gi = state.get('global_inputs', {{}})")
    code.append(f"            for _k, _v in _gi.items():")
    code.append(f"                if _k not in tc['args']:")
    code.append(f"                    tc['args'][_k] = _v")
    code.append(f"            result = tool_fn.invoke(tc['args'])")
    code.append(f"            tool_results.append(ToolMessage(content=str(result), tool_call_id=tc['id']))")
    code.append(f"            # Store ONLY under canonical nodeId — tool fn name must not pollute node_outputs")
    code.append(f"            node_id_key = _tool_fn_to_node_id_{safe_phase_id}.get(tc['name'], tc['name'])")
    code.append(f"            parsed = result")
    code.append(f"            if isinstance(result, str):")
    code.append(f"                try:")
    code.append(f"                    import json as _json; parsed = _json.loads(result)")
    code.append(f"                except Exception:")
    code.append(f"                    pass")
    # Warn at runtime when a DYNAMIC result is about to overwrite an existing FREEZE output.
    code.append(f"            if node_id_key in _FREEZE_COLLISION_IDS_{safe_phase_id} and node_id_key in (state.get('node_outputs') or {{}}):")
    code.append(f"                _GRAPH_LOG.warning('[GRAPH] event=freeze_overwrite tool=%r node_id=%r', tc['name'], node_id_key, extra={{'graph_event': 'freeze_overwrite', 'tool': tc['name'], 'node_id': node_id_key}})")
    code.append(f"            node_outputs_update[node_id_key] = parsed")
    code.append(f"            _GRAPH_LOG.info('[GRAPH] event=tool_complete tool=%r node_id=%r result_preview=%r', tc['name'], node_id_key, str(parsed)[:200], extra={{'graph_event': 'tool_complete', 'tool': tc['name'], 'node_id': node_id_key}})")
    code.append(f"        except GraphInterrupt:")
    code.append(f"            raise")
    code.append(f"        except RuntimeError:")
    code.append(f"            raise")
    code.append(f"        except Exception as exc:")
    code.append(f"            err_detail = traceback.format_exc()")
    code.append(f"            tool_results.append(ToolMessage(content=f'Tool error: {{exc}}\\n{{err_detail}}', tool_call_id=tc['id']))")
    code.append(f"    return {{'messages': tool_results, 'node_outputs': node_outputs_update}}\n")

    code.append(f"def should_continue_{safe_phase_id}(state) -> str:")
    code.append(f"    if state.get('iteration_count', 0) >= MAX_ITERATIONS:")
    code.append(f"        return 'end'")
    code.append(f"    msgs = state.get('messages') or []")
    code.append(f"    if not msgs:")
    code.append(f"        return 'end'")
    code.append(f"    if getattr(msgs[-1], 'tool_calls', None):")
    code.append(f"        return 'continue'")
    code.append(f"    return 'end'\n")

    code.append(f"{builder_var} = StateGraph(DynamicAgentState)")
    code.append(f"{builder_var}.add_node('llm_node', llm_node_{safe_phase_id})")
    code.append(f"{builder_var}.add_node('tool_node', tool_node_{safe_phase_id})")
    code.append(f"{builder_var}.add_edge(START, 'llm_node')")
    code.append(f"{builder_var}.add_conditional_edges('llm_node', should_continue_{safe_phase_id}, {{'continue': 'tool_node', 'end': END}})")
    code.append(f"{builder_var}.add_edge('tool_node', 'llm_node')\n")


def _check_generated_code(code: str, filepath: str) -> tuple[bool, str]:
    """
    Validate generated Python code in two steps:
      1. ast.parse()  — instant SyntaxError detection (no subprocess needed).
      2. subprocess   — run the file to catch NameError, ImportError, empty-graph
                        compilation errors, and other runtime issues that only
                        surface when Python actually executes the module-level code.

    The generated files only build LangGraph structure in module scope (no IO,
    no API calls at import time), so running them in a subprocess is safe.

    Returns (is_valid, error_message).
    """
    import ast as _ast
    import subprocess as _sp
    import sys as _sys

    # ── Step 1: fast syntax check ─────────────────────────────────────────────
    try:
        _ast.parse(code)
    except SyntaxError as exc:
        return False, f"SyntaxError at line {exc.lineno}: {exc.msg}\n  {exc.text}"

    # ── Step 2: run the file in a subprocess ─────────────────────────────────
    try:
        import os as _os
        # Provide a dummy API key so that any module-level LLM construction
        # that wasn't fully lazy doesn't fail with "missing credentials".
        # The subprocess only validates structure — no real API calls are made.
        _validation_env = dict(_os.environ)
        if not _validation_env.get('GEMINI_API_KEY'):
            _validation_env['GEMINI_API_KEY'] = 'dummy-validation-key-not-real'
        result = _sp.run(
            [_sys.executable, filepath],
            capture_output=True,
            text=True,
            timeout=25,
            env=_validation_env,
        )
        if result.returncode != 0:
            stderr = (result.stderr or "").strip()
            return False, stderr
    except _sp.TimeoutExpired:
        return False, "Subprocess timed out after 25 s (possible infinite loop at module level)"
    except Exception as exc:
        return False, f"Subprocess execution error: {exc}"

    return True, ""


async def _fix_generated_code_with_llm(
    code: str,
    error: str,
    filepath: str,
    *,
    api_key: Optional[str] = None,
    project_id: Optional[str] = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
) -> str:
    """
    Ask the LLM to fix a generated LangGraph file that has runtime errors.
    Returns the corrected Python source (or the original code on failure).
    """
    prompt = f"""You are an expert Python / LangGraph developer.

The auto-generated LangGraph workflow file below has errors when executed.

═══ ERROR ══════════════════════════════════════════════════════════════════
{error}
════════════════════════════════════════════════════════════════════════════

═══ FULL GENERATED FILE ════════════════════════════════════════════════════
{code}
════════════════════════════════════════════════════════════════════════════

INSTRUCTIONS (follow exactly):
• Fix ONLY the error(s) shown above. Do NOT restructure, rename nodes, or
  rewrite logic that is not broken.
• Common fixes to consider:
  - Empty-graph error → ensure nodes are added to the correct StateGraph
    variable (e.g. _b_stage_1, not a different `builder`).
  - NameError → define the missing name before it is used.
  - ImportError → add the missing import at the top of the file.
  - Duplicate definition conflicts → remove the duplicate block.
• Return ONLY the complete corrected Python source code.
• Do NOT wrap the code in markdown fences or add any explanatory text.
"""

    started_at = datetime.utcnow()
    try:
        response = await async_generate(
            "gemini-3.6-flash",
            prompt,
            config=GeminiGenerateConfig(
                temperature=0.1,
                response_mime_type="text/plain",
            ),
            api_key=api_key,
        )
        finished_at = datetime.utcnow()
        usage = extract_token_usage_from_response(response)
        record_llm_call(
            project_id=project_id, org_id=org_id,
            subscriber_id=subscriber_id, user_id=user_id,
            operation="code-generation", sub_operation="fix-generated-code",
            model="gemini-3.6-flash",
            prompt_tokens=int(usage.get("prompt_tokens", 0) or 0),
            completion_tokens=int(usage.get("completion_tokens", 0) or 0),
            total_tokens=int(usage.get("total_tokens", 0) or 0),
            status="success", attempt=1, is_retry=False,
            started_at=started_at, finished_at=finished_at,
            metadata={"filepath": str(filepath), "error_snippet": error[:300]},
        )
        fixed = response.text or ""
        # Strip any markdown fences the LLM might have included
        fixed = re.sub(r"^```(?:python)?\s*\n?", "", fixed.strip(), flags=re.MULTILINE)
        fixed = re.sub(r"\n?```\s*$", "", fixed, flags=re.MULTILINE)
        return fixed.strip()
    except Exception as exc:
        finished_at = datetime.utcnow()
        record_llm_call(
            project_id=project_id, org_id=org_id,
            subscriber_id=subscriber_id, user_id=user_id,
            operation="code-generation", sub_operation="fix-generated-code",
            model="gemini-3.6-flash",
            prompt_tokens=0, completion_tokens=0, total_tokens=0,
            status="failed", attempt=1, is_retry=False,
            started_at=started_at, finished_at=finished_at,
            metadata={"filepath": str(filepath), "error": str(exc)},
        )
        logger.warning(f"[postgen] Code-fix LLM call failed: {exc}")
        return code  # return original on failure


async def _postgen_validate_and_fix(
    code: str,
    filepath: str,
    *,
    max_rounds: int = 2,
    api_key: Optional[str] = None,
    project_id: Optional[str] = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
) -> tuple[str, list[str]]:
    """
    Post-generation quality gate: compile/run the generated file, feed any
    errors to the LLM for targeted repair, and re-check.  Repeats up to
    `max_rounds` times.

    Returns (final_code, warnings) — warnings is empty if the code is clean.
    """
    warnings_out: list[str] = []
    current_code = code

    for round_num in range(1, max_rounds + 1):
        is_valid, error = _check_generated_code(current_code, filepath)

        if is_valid:
            logger.info(f"[postgen] Round {round_num}: generated code is valid — no errors detected.")
            return current_code, warnings_out

        # Truncate very long tracebacks for logging/warnings
        error_snippet = error[:600] if len(error) > 600 else error
        logger.warning(f"[postgen] Round {round_num}: errors found:\n{error_snippet}")
        warnings_out.append(f"[postgen-round-{round_num}] Runtime error: {error_snippet}")

        fixed_code = await _fix_generated_code_with_llm(
            current_code, error, filepath,
            api_key=api_key, project_id=project_id,
            org_id=org_id, subscriber_id=subscriber_id, user_id=user_id,
        )

        if not fixed_code or fixed_code.strip() == current_code.strip():
            warnings_out.append(
                f"[postgen-round-{round_num}] LLM returned identical code — stopping early."
            )
            break

        current_code = fixed_code
        # Overwrite the on-disk file with the LLM-fixed version
        try:
            with open(filepath, "w", encoding="utf-8") as _f:
                _f.write(current_code)
            logger.info(f"[postgen] Round {round_num}: fixed code written to {filepath}")
            warnings_out.append(f"[postgen-round-{round_num}] LLM fix applied and saved.")
        except Exception as exc:
            warnings_out.append(f"[postgen-round-{round_num}] Failed to write fixed code: {exc}")
            break

    # Final check after the loop (covers the case where max_rounds was exhausted)
    is_valid, error = _check_generated_code(current_code, filepath)
    if not is_valid:
        error_snippet = error[:400] if len(error) > 400 else error
        warnings_out.append(
            f"[postgen] Code still has errors after {max_rounds} repair round(s): {error_snippet}"
        )
    else:
        logger.info("[postgen] Final check passed — generated code is clean.")

    return current_code, warnings_out


def _generate_langgraph_code_for_phases(phase_results: List[Any], workflow_name: str, global_caps: Optional[list] = None) -> str:
    """
    Generates the combined LangGraph Python file for all phases.

    Single-phase  → standalone file with its own `builder` (per-phase files).
    Multi-phase   → each phase compiles into its own mini-graph (subgraph);
                    a parent StateGraph(WorkflowState) chains them sequentially.
                    Execution order: phase_1 → phase_2 → … → END.
                    UI interrupts propagate from subgraphs to the parent graph.
    """
    import json

    # ── single phase: use standalone generators (per-phase files) ─────────────
    if len(phase_results) == 1:
        pr = phase_results[0]
        if getattr(pr, "phaseType", "FREEZE") == "DYNAMIC":
            return _generate_dynamic_phase_code(pr, workflow_name, global_caps=global_caps)
        # Single FREEZE phase
        code: list = []
        code.append("from typing import TypedDict, Annotated, Dict, Any")
        code.append("from langgraph.graph import StateGraph, START, END")
        code.append("from langgraph.types import interrupt")
        code.append("import logging, re\n")
        code.append("if 'execute_dynamic_tool' not in globals():")
        code.append("    def execute_dynamic_tool(tool_name: str, params: dict) -> Any:")
        code.append("        raise RuntimeError(")
        code.append("            f'execute_dynamic_tool is not injected. '")
        code.append("            f'This graph must be loaded via WorkflowExecutionController._load_graph(). '")
        code.append("            f'Tool {tool_name!r} cannot be called in standalone mode.'")
        code.append("        )\n")
        code.append("def _merge_node_outputs(a: Dict[str, Any], b: Dict[str, Any]) -> Dict[str, Any]:")
        code.append("    merged = dict(a) if a else {}")
        code.append("    if b:")
        code.append("        merged.update(b)")
        code.append("    return merged\n")
        code.append("class AgenticState(TypedDict):")
        code.append("    global_inputs: Dict[str, Any]")
        code.append("    node_outputs: Annotated[Dict[str, Any], _merge_node_outputs]\n")
        code.extend(_FREEZE_HELPERS)
        code.append("GRAPH_TYPE = 'FREEZE'\n")
        code.append("builder = StateGraph(AgenticState)\n")
        _build_freeze_phase_edges(pr, "builder", "p0", code)
        return "\n".join(code)

    # ── multi-phase: subgraph-chained combined file ────────────────────────────
    has_dynamic = any(getattr(p, "phaseType", "FREEZE") == "DYNAMIC" for p in phase_results)
    has_freeze  = any(getattr(p, "phaseType", "FREEZE") != "DYNAMIC" for p in phase_results)

    graph_type = "MIXED" if (has_dynamic and has_freeze) else ("DYNAMIC" if has_dynamic else "FREEZE")

    code = []
    # ── Common header (imports + shared utilities + all needed state types) ───
    code.append("from typing import TypedDict, Annotated, Sequence, Dict, Any, List, Optional")
    code.append("from langgraph.graph import StateGraph, START, END")
    code.append("from langgraph.types import interrupt")
    code.append("from langgraph.errors import GraphInterrupt")
    code.append("from langgraph.graph.message import add_messages")
    code.append("from langchain_core.messages import BaseMessage, HumanMessage, SystemMessage, ToolMessage, AIMessage")
    code.append("from langchain_core.tools import tool")
    code.append("from langchain_google_genai import ChatGoogleGenerativeAI")
    code.append("import os, json, re, traceback, logging\n")

    code.append("if 'execute_dynamic_tool' not in globals():")
    code.append("    def execute_dynamic_tool(tool_name: str, params: dict) -> Any:")
    code.append("        raise RuntimeError(")
    code.append("            f'execute_dynamic_tool is not injected. '")
    code.append("            f'This graph must be loaded via WorkflowExecutionController._load_graph(). '")
    code.append("            f'Tool {tool_name!r} cannot be called in standalone mode.'")
    code.append("        )\n")
    code.extend(_TOOL_RESULT_HELPERS)
    code.append("")

    code.append("def _merge_node_outputs(a: Dict[str, Any], b: Dict[str, Any]) -> Dict[str, Any]:")
    code.append("    merged = dict(a) if a else {}")
    code.append("    if b:")
    code.append("        merged.update(b)")
    code.append("    return merged\n")

    code.append("MAX_ITERATIONS = 20\n")

    # State types — always emit both so each mini-graph can use the right one
    code.append("class AgenticState(TypedDict):")
    code.append("    global_inputs: Dict[str, Any]")
    code.append("    node_outputs: Annotated[Dict[str, Any], _merge_node_outputs]\n")

    code.append("class DynamicAgentState(TypedDict):")
    code.append("    messages: Annotated[Sequence[BaseMessage], add_messages]")
    code.append("    global_inputs: Dict[str, Any]")
    code.append("    node_outputs: Annotated[Dict[str, Any], _merge_node_outputs]")
    code.append("    iteration_count: int\n")

    # Parent graph state = superset of both phase state types so LangGraph
    # auto-maps matching keys when invoking subgraphs.
    code.append("class WorkflowState(TypedDict):")
    code.append("    global_inputs: Dict[str, Any]")
    code.append("    node_outputs: Annotated[Dict[str, Any], _merge_node_outputs]")
    code.append("    messages: Annotated[Sequence[BaseMessage], add_messages]")
    code.append("    iteration_count: int\n")

    # GRAPH_TYPE used by the executor to seed the correct initial state.
    # MIXED and DYNAMIC both need all WorkflowState fields seeded.
    code.append(f"GRAPH_TYPE = {repr(graph_type)}\n")

    # FREEZE helpers (shared by all FREEZE mini-graphs)
    if has_freeze:
        code.extend(_FREEZE_HELPERS)

    # ── Per-phase mini-graph code ─────────────────────────────────────────────
    phase_graph_vars: list = []   # (safe_phase_id, graph_var, phase_type)

    # Build a running registry of {node_id: [output_keys]} from all FREEZE phases
    # processed so far.  Passed to each DYNAMIC phase builder so it can validate
    # and auto-repair cross-phase inputBinding templates whose source node reference
    # is wrong (e.g. LLM planner wrote {{start_node.X}} instead of {{start_ekyc_process.X}}).
    # We also include intra-DYNAMIC tool → nodeId output keys so a later DYNAMIC phase
    # can reference an earlier DYNAMIC phase's outputs.
    cross_phase_node_outputs: dict = {}  # {node_id: [declared_output_key, ...]}

    for pr in phase_results:
        raw_phase_id = (getattr(pr.graph, "phaseId", None) or "phase")
        safe_phase_id = re.sub(r"\W", "_", raw_phase_id)
        phase_type    = getattr(pr, "phaseType", "FREEZE")
        builder_var   = f"_b_{safe_phase_id}"
        graph_var     = f"_g_{safe_phase_id}"

        code.append(f"# {'─' * 60}")
        code.append(f"# Phase: {raw_phase_id}  ({phase_type})")
        code.append(f"# {'─' * 60}")

        if phase_type == "DYNAMIC":
            # ── Cross-phase nodeId namespacing ───────────────────────────────────
            # Re-using the same logical nodeId across stages/phases is valid.
            # However, `node_outputs` is a single flat dict shared across the combined
            # workflow state; writing to the same key in a later phase would overwrite
            # earlier phase results (silent state corruption).
            #
            # To support same nodeIds across phases safely, we namespace colliding
            # DYNAMIC nodeIds by appending the phase id. We also rewrite all intra-phase
            # bindings that reference the old nodeId so the phase remains internally
            # consistent.
            for node in pr.graph.nodes:
                if node.type in ("router", "fallback_router", "end") or not node.nodeId:
                    continue
                canonical = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
                if canonical not in cross_phase_node_outputs:
                    continue  # no collision — leave untouched
                old_id = node.nodeId
                new_id = f"{node.nodeId}_{safe_phase_id}"
                node.nodeId = new_id
                logger.warning(
                    f"[code_gen] nodeId collision across phases: '{old_id}' exists in a "
                    f"preceding phase and also in DYNAMIC phase '{safe_phase_id}'. "
                    f"Namespacing DYNAMIC nodeId to '{new_id}' to prevent node_outputs "
                    f"overwrite."
                )
                old_prefix = "{{" + old_id + "."
                new_prefix = "{{" + new_id + "."
                for other in pr.graph.nodes:
                    if not other.config or not other.config.inputBindings:
                        continue
                    for bp, bt in list(other.config.inputBindings.items()):
                        if isinstance(bt, str) and old_prefix in bt:
                            other.config.inputBindings[bp] = bt.replace(old_prefix, new_prefix)

            _build_dynamic_phase_block(
                pr, workflow_name, safe_phase_id, builder_var, global_caps, code,
                cross_phase_node_outputs=cross_phase_node_outputs,
            )
            # After building, register DYNAMIC phase tool outputs so later phases can
            # reference them. Use the canonical node_id (not tool fn name).
            for node in pr.graph.nodes:
                if node.type not in ("router", "fallback_router", "end") and node.nodeId:
                    safe_nid = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
                    out_keys = [o.name for o in (node.config.declaredOutputs or [])]
                    cross_phase_node_outputs[safe_nid] = out_keys
        else:
            code.append(f"{builder_var} = StateGraph(AgenticState)")
            _build_freeze_phase_edges(pr, builder_var, safe_phase_id, code)
            # Register every non-router FREEZE node's declared outputs.
            for node in pr.graph.nodes:
                if node.type not in ("router", "fallback_router", "end") and node.nodeId:
                    safe_nid = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
                    out_keys = [o.name for o in (node.config.declaredOutputs or [])]
                    cross_phase_node_outputs[safe_nid] = out_keys

        # Compile into a subgraph (no checkpointer — parent graph provides it)
        code.append(f"{graph_var} = {builder_var}.compile()\n")
        phase_graph_vars.append((safe_phase_id, graph_var, phase_type))

    # ── Parent graph: chain all phase subgraphs sequentially ─────────────────
    code.append("# Parent graph — chains all phases; executor compiles this with checkpointer")
    code.append("builder = StateGraph(WorkflowState)")

    for safe_id, gvar, _ in phase_graph_vars:
        code.append(f"builder.add_node('phase_{safe_id}', {gvar})")

    # Between phases we need two kinds of interstitial nodes:
    #
    # 1. BRIDGE node (every phase transition except into the first phase):
    #    Flattens all accumulated node_outputs into global_inputs so that
    #    {{global.X}} bindings in the upcoming phase resolve correctly.
    #    Without this, only the initial caller-supplied global_inputs are
    #    visible to {{global.*}} refs in later phases — prior-phase outputs
    #    sit in node_outputs and are never promoted to global_inputs.
    #
    # 2. RESET node (DYNAMIC→DYNAMIC transition only):
    #    Zeroes iteration_count so the new ReAct loop always starts fresh.
    #
    # Resulting chain for a 3-phase graph:
    #   START → phase_1 → bridge_before_phase_2 → phase_2
    #         → bridge_before_phase_3 → phase_3 → END
    prev_type = None
    phase_node_sequence: list = []   # ordered list of node names to chain with add_edge

    for i, (safe_id, _, phase_type) in enumerate(phase_graph_vars):
        if i > 0:
            # ── Bridge: promote all prior node_outputs → global_inputs ───────
            bridge_fn   = f"_bridge_before_{safe_id}"
            bridge_node = f"bridge_before_{safe_id}"
            code.append(f"def {bridge_fn}(state: WorkflowState) -> dict:")
            code.append(f'    """Flatten prior node_outputs into global_inputs before phase {safe_id}."""')
            code.append(f"    _no = state.get('node_outputs') or {{}}")
            code.append(f"    _promoted = dict(state.get('global_inputs') or {{}})")
            code.append(f"    for _nid, _nout in _no.items():")
            code.append(f"        if isinstance(_nout, dict):")
            code.append(f"            _promoted.update(_nout)")
            code.append(f"            for _k, _v in _nout.items():")
            code.append(f"                _promoted[str(_nid) + '.' + str(_k)] = _v")
            code.append(f"    return {{'global_inputs': _promoted}}")
            code.append(f"builder.add_node('{bridge_node}', {bridge_fn})\n")
            phase_node_sequence.append(bridge_node)

        if phase_type == "DYNAMIC" and prev_type == "DYNAMIC":
            # ── Reset: zero iteration_count for fresh ReAct loop ─────────────
            reset_fn   = f"_reset_before_{safe_id}"
            reset_node = f"reset_{safe_id}"
            code.append(f"def {reset_fn}(state: WorkflowState) -> dict:")
            code.append(f"    return {{'iteration_count': 0}}")
            code.append(f"builder.add_node('{reset_node}', {reset_fn})")
            phase_node_sequence.append(reset_node)

        phase_node_sequence.append(f"phase_{safe_id}")
        prev_type = phase_type

    # Wire START → phase_1 → bridge_before_phase_2 → phase_2 → … → END
    code.append(f"builder.add_edge(START, '{phase_node_sequence[0]}')")
    for i in range(len(phase_node_sequence) - 1):
        code.append(f"builder.add_edge('{phase_node_sequence[i]}', '{phase_node_sequence[i + 1]}')")
    code.append(f"builder.add_edge('{phase_node_sequence[-1]}', END)")

    return "\n".join(code)


# ── Shared FREEZE helper functions (emitted verbatim into generated files) ─────
# Generated modules must `import logging` before these helpers (see _generate_langgraph_code_for_phases).
# Issue 5: classify tool dicts as success vs failure. Injected interpret_tool_result
# from the executor wins; this fallback keeps generated graphs self-contained.
_TOOL_RESULT_HELPERS: list = [
    "if 'interpret_tool_result' not in globals():",
    "    def interpret_tool_result(raw):",
    "        if not isinstance(raw, dict):",
    "            return {'ok': True, 'data': raw, 'error': None, 'code': None, 'retryable': False}",
    "        if isinstance(raw.get('ok'), bool):",
    "            ok = raw['ok']",
    "            data = raw.get('data')",
    "            if data is None:",
    "                data = {k: v for k, v in raw.items() if k not in ('ok', 'error', 'code', 'retryable')}",
    "            err = raw.get('error')",
    "            err_s = str(err).strip() if err not in (None, '') else None",
    "            return {",
    "                'ok': ok,",
    "                'data': data if data is not None else {},",
    "                'error': None if ok else (err_s or 'Tool failed'),",
    "                'code': None if ok else (raw.get('code') or 'TOOL_FAILED'),",
    "                'retryable': False if ok else bool(raw.get('retryable', True)),",
    "            }",
    "        err = raw.get('error')",
    "        if isinstance(err, str) and err.strip():",
    "            return {",
    "                'ok': False,",
    "                'data': raw,",
    "                'error': err.strip(),",
    "                'code': raw.get('code') or 'TOOL_FAILED',",
    "                'retryable': bool(raw.get('retryable', True)),",
    "            }",
    "        status = str(raw.get('status') or '').strip().lower()",
    "        _meta = {'ok', 'error', 'code', 'retryable', 'data', 'status', 'message', 'traceback'}",
    "        _substantive = any(v not in (None, '', [], {}, False) for k, v in raw.items() if k not in _meta)",
    "        if status in ('error', 'failed', 'failure') and not _substantive:",
    "            msg = str(raw.get('message') or raw.get('error') or 'Tool failed')",
    "            return {'ok': False, 'data': raw, 'error': msg, 'code': raw.get('code') or 'TOOL_FAILED', 'retryable': True}",
    "        return {'ok': True, 'data': raw, 'error': None, 'code': None, 'retryable': False}",
    "",
    "def _await_successful_tool_result(tool_name, result, retry_call=None):",
    "    while True:",
    "        _env = interpret_tool_result(result)",
    "        if _env.get('ok', True):",
    "            if isinstance(result, dict) and result.get('ok') is True and 'data' in result:",
    "                _data = result.get('data')",
    "                return {} if _data is None else _data",
    "            return result",
    "        _resume = interrupt({",
    "            'type': 'tool_error',",
    "            'tool_name': tool_name,",
    "            'error': _env.get('error'),",
    "            'code': _env.get('code'),",
    "            'retryable': _env.get('retryable', True),",
    "            'assigned_to': 'human_user',",
    "            'ui_data': {",
    "                'error': _env.get('error'),",
    "                'code': _env.get('code'),",
    "                'retryable': _env.get('retryable', True),",
    "                'tool_name': tool_name,",
    "                '_tool_error': True,",
    "            },",
    "        })",
    "        _action = ''",
    "        if isinstance(_resume, dict):",
    "            if _resume.get('retry') is True:",
    "                _action = 'retry'",
    "            else:",
    "                _action = str(_resume.get('action') or '').strip().lower()",
    "        if _action in ('abort', 'cancel', 'fail'):",
    "            raise RuntimeError(_env.get('error') or ('Tool %s failed' % tool_name))",
    "        if retry_call is None:",
    "            raise RuntimeError(_env.get('error') or ('Tool %s failed' % tool_name))",
    "        result = retry_call()",
    "",
]


_FREEZE_HELPERS: list = [
    "_GRAPH_LOG = logging.getLogger(__name__)\n",
] + _TOOL_RESULT_HELPERS + [
    "def _lookup_node_field(state, node_id, field):",
    "    no = state.get('node_outputs') or {}",
    "    _ids = [node_id]",
    "    _canon = re.sub(r'[^a-zA-Z0-9_]', '_', str(node_id or ''))",
    "    if _canon and _canon not in _ids:",
    "        _ids.append(_canon)",
    "    for _nid in _ids:",
    "        node_out = no.get(_nid)",
    "        if isinstance(node_out, dict):",
    "            if field in node_out:",
    "                return node_out.get(field)",
    "            continue",
    "        if isinstance(node_out, str):",
    "            try:",
    "                import json as _json",
    "                _parsed = _json.loads(node_out)",
    "                if isinstance(_parsed, dict) and field in _parsed:",
    "                    return _parsed.get(field)",
    "            except Exception:",
    "                continue",
    "    return None",
    "def _lookup_global_key(state, key):",
    "    # Keep in sync with services.global_bindings.lookup_global_binding_value",
    "    gi = state.get('global_inputs') or {}",
    "    key = (key or '').strip()",
    "    if not key:",
    "        return None",
    "    if '.' in key:",
    "        nid, field = key.split('.', 1)",
    "        val = _lookup_node_field(state, nid, field)",
    "        if val is not None:",
    "            return val",
    "        if key in gi:",
    "            return gi.get(key)",
    "        return None",
    "    if key in gi:",
    "        return gi.get(key)",
    "    return None",
    "def _resolve_bindings(bindings: dict, state) -> dict:",
    "    resolved = {}",
    "    for param, template in bindings.items():",
    "        if not isinstance(template, str) or '{{' not in template:",
    "            resolved[param] = template",
    "            continue",
    "        _stripped = template.strip()",
    "        _pick_inner = _stripped[2:-2] if _stripped.startswith('{{') and _stripped.endswith('}}') else _stripped",
    "        if _pick_inner.startswith('pick:'):",
    "            _pick_refs = [r.strip() for r in _pick_inner[5:].split(',') if r.strip()]",
    "            _found = []",
    "            _node_outputs_all = state.get('node_outputs', {}) or {}",
    "            for _pref in _pick_refs:",
    "                if '.' not in _pref:",
    "                    continue",
    "                _ref_source, _ref_param = _pref.split('.', 1)",
    "                if _ref_source not in _node_outputs_all:",
    "                    continue",
    "                _node_out = _node_outputs_all.get(_ref_source)",
    "                _val = None",
    "                if isinstance(_node_out, dict):",
    "                    _val = _node_out.get(_ref_param)",
    "                elif isinstance(_node_out, str):",
    "                    try:",
    "                        import json as _json",
    "                        _val = _json.loads(_node_out).get(_ref_param)",
    "                    except Exception:",
    "                        _val = None",
    "                if _val is not None and _val != '':",
    "                    _found.append((_ref_source, _val))",
    "            if len(_found) == 1:",
    "                resolved[param] = _found[0][1]",
    "            elif len(_found) == 0:",
    "                _GRAPH_LOG.warning(",
    "                    '[GRAPH] event=pick_resolve_empty binding_param=%r template=%r pick_refs=%r',",
    "                    param, template, _pick_refs,",
    "                    extra={'graph_event': 'pick_resolve_empty', 'binding_param': param},",
    "                )",
    "                continue",
    "            else:",
    "                _GRAPH_LOG.warning(",
    "                    '[GRAPH] event=pick_resolve_ambiguous binding_param=%r found=%r — using first',",
    "                    param, [f[0] for f in _found],",
    "                    extra={'graph_event': 'pick_resolve_ambiguous', 'binding_param': param},",
    "                )",
    "                resolved[param] = _found[0][1]",
    "            continue",
    "        # Normalize bare {{param}} (no node. prefix) → {{global.param}}.",
    "        # These can be produced by LLM repair emitting '{{ekyc_record_id}}' instead",
    "        # of '{{global.ekyc_record_id}}'; without this the re.sub below returns the",
    "        # literal template string as the resolved value — a silent failure.",
    "        _bare = re.findall(r'\\{\\{(\\w+)\\}\\}', template)",
    "        for _b in _bare:",
    "            template = template.replace('{{' + _b + '}}', '{{global.' + _b + '}}')",
    "            _GRAPH_LOG.warning(",
    "                '[GRAPH] event=binding_bare_ref_normalized binding_param=%r bare_key=%r',",
    "                param, _b,",
    "                extra={'graph_event': 'binding_bare_ref_normalized', 'binding_param': param, 'bare_key': _b},",
    "            )",
    "        _inners = re.findall(r'\\{\\{([^}]+)\\}\\}', template)",
    "        if len(_inners) == 1 and template.strip() == '{{' + _inners[0] + '}}':",
    "            # Pure single reference — resolve and preserve original Python type",
    "            _inner = _inners[0].strip()",
    "            if _inner.startswith('global.'):",
    "                ref_source, ref_param = 'global', _inner[7:]",
    "            elif '.' in _inner:",
    "                ref_source, ref_param = _inner.split('.', 1)",
    "            else:",
    "                ref_source, ref_param = '', _inner",
    "            if ref_source == 'global':",
    "                resolved[param] = _lookup_global_key(state, ref_param)",
    "            elif ref_source:",
    "                _node_outputs_all = state.get('node_outputs', {})",
    # When the source node has no entry in node_outputs it means it hasn't run yet.
    # Two valid scenarios:
    #   1. Retry-cycle path: the binding is on an entry-like node that is re-entered
    #      after a failure (e.g. login_screen re-entered after perform_login failed).
    #      On first execution perform_login hasn't run → skip gracefully.
    #   2. Genuine graph-ordering bug: wrong edge / wrong nodeId in the binding.
    #      The validator should have caught this at code-gen time.
    # In both cases we skip the binding (don't include it in resolved) and log a
    # warning so it's visible in logs without crashing the graph.
    "                if ref_source not in _node_outputs_all:",
    "                    _GRAPH_LOG.warning(",
    "                        '[GRAPH] event=binding_source_not_yet_run param=%r template=%r ref_source=%r available=%r',",
    "                        param, template, ref_source, sorted(_node_outputs_all.keys()),",
    "                        extra={'graph_event': 'binding_source_not_yet_run', 'param': param, 'ref_source': ref_source},",
    "                    )",
    "                    continue  # skip — source hasn't run yet (retry-cycle path)",
    "                node_out = _node_outputs_all.get(ref_source)",
    "                if isinstance(node_out, dict):",
    "                    resolved[param] = node_out.get(ref_param)",
    "                elif isinstance(node_out, str):",
    "                    try:",
    "                        import json as _json",
    "                        resolved[param] = _json.loads(node_out).get(ref_param)",
    "                    except Exception:",
    "                        resolved[param] = None",
    "                else:",
    "                    resolved[param] = None",
    "            else:",
    "                resolved[param] = None",
    "            if resolved.get(param) is None:",
    "                _GRAPH_LOG.warning(",
    "                    '[GRAPH] event=binding_resolve_none binding_param=%r template=%r ref_source=%r ref_key=%r — skipping (value not produced by upstream)',",
    "                    param, template, ref_source, ref_param,",
    "                    extra={'graph_event': 'binding_resolve_none', 'binding_param': param, 'binding_template': template, 'ref_source': ref_source, 'ref_key': ref_param},",
    "                )",
    "                del resolved[param]  # remove None entry so it's not passed as input",
    "        else:",
    "            # Composite template — Example - template = 'User {{global.user_id}} placed order {{node1.order_id}}' will be replaced as 'User 42 placed order 999' when golbal.user_id iis 42 and node1.order_id is 999",
    "            def _sub(m):",
    "                inner = (m.group(1) or '').strip()",
    "                if inner.startswith('global.'):",
    "                    src, prm = 'global', inner[7:]",
    "                    v = _lookup_global_key(state, prm)",
    "                elif '.' in inner:",
    "                    src, prm = inner.split('.', 1)",
    "                    v = _lookup_node_field(state, src, prm)",
    "                else:",
    "                    src, prm = '', inner",
    "                    v = None",
    "                if v is None:",
    "                    _GRAPH_LOG.warning(",
    "                        '[GRAPH] event=binding_composite_ref_none binding_param=%r template=%r ref=%r.%r — using empty string',",
    "                        param, template, src, prm,",
    "                        extra={'graph_event': 'binding_composite_ref_none', 'binding_param': param, 'binding_template': template, 'ref_source': src, 'ref_key': prm},",
    "                    )",
    "                    return ''",
    "                return str(v)",
    "            resolved[param] = re.sub(r'\\{\\{([^}]+)\\}\\}', _sub, template)",
    "    return resolved\n",
    "def _evaluate_condition(condition_str: str, state) -> bool:",
    "    if not condition_str or condition_str.strip() == '':",
    "        return True",
    "    try:",
    "        cond = condition_str.replace('&&', ' and ').replace('||', ' or ')",
    "        cond = cond.replace('!= null', 'is not None').replace('== null', 'is None')",
    "        # Use word-boundary replacement so 'true'/'false' inside identifiers are not corrupted",
    "        cond = re.sub(r'\\btrue\\b', 'True', cond)",
    "        cond = re.sub(r'\\bfalse\\b', 'False', cond)",
    "        # Collect all nodeId.param references from the ORIGINAL condition string then",
    "        # substitute them into `cond` one by one (cond may already be partially rewritten).",
    "        for match in re.finditer(r'([a-zA-Z0-9_]+)\\.([a-zA-Z0-9_]+)', condition_str):",
    "            full_match = match.group(0)",
    "            node_id = match.group(1)",
    "            param = match.group(2)",
    "            node_out = state.get('node_outputs', {}).get(node_id)",
    "            if isinstance(node_out, dict):",
    "                val = node_out.get(param)",
    "            elif isinstance(node_out, str):",
    "                try:",
    "                    import json as _json",
    "                    val = _json.loads(node_out).get(param)",
    "                except Exception:",
    "                    val = None",
    "            else:",
    "                val = None",
    "            # Normalise string booleans so they compare correctly to Python booleans",
    "            if isinstance(val, str) and val.lower() in ('true', 'false'):",
    "                replacement = 'True' if val.lower() == 'true' else 'False'",
    "            elif isinstance(val, str):",
    "                replacement = repr(val)",
    "            else:",
    "                replacement = str(val)",
    # Use regex with negative lookaround instead of str.replace to avoid partial-match
    # substitutions (e.g. replacing 'a.b' inside 'foo.a.b') and to safely handle
    # replacement strings that contain backslashes or regex metacharacters.
    r"            cond = re.sub(r'(?<![a-zA-Z0-9_])' + re.escape(full_match) + r'(?![a-zA-Z0-9_])', lambda _m: replacement, cond)",
    "        result = eval(cond, {}, {})",
    "        _GRAPH_LOG.debug(",
    "            '[GRAPH] event=condition_evaluated condition=%r result=%r',",
    "            condition_str, bool(result),",
    "            extra={'graph_event': 'condition_evaluated', 'condition': condition_str, 'result': bool(result)},",
    "        )",
    "        return bool(result)",
    "    except Exception:",
    "        return False\n",
    "def _normalize_node_def(raw: dict) -> dict:",
    "    if not isinstance(raw, dict):",
    "        return {}",
    "    node = dict(raw)",
    "    cap_ref = node.get('capabilityRef')",
    "    if isinstance(cap_ref, dict):",
    "        cid = cap_ref.get('capabilityId')",
    "        if cid and not node.get('capabilityId'):",
    "            node['capabilityId'] = cid",
    "        kind = cap_ref.get('kind')",
    "        if kind and not node.get('capabilityKind'):",
    "            node['capabilityKind'] = kind",
    "    cfg = node.get('config')",
    "    if isinstance(cfg, dict) and not node.get('inputBindings'):",
    "        ib = cfg.get('inputBindings')",
    "        if ib is not None:",
    "            node['inputBindings'] = ib",
    "    return node\n",
    "def _execute_dynamic_node(node_def: dict, state) -> dict:",
    "    node_def = _normalize_node_def(node_def)",
    "    node_id = node_def.get('id', node_def.get('nodeId'))",
    "    node_type = node_def.get('type')",
    "    capability_kind = node_def.get('capabilityKind')",
    "    capability_id = str(node_def.get('capabilityId') or '')\n",
    "    if node_type == 'router':",
    "        return {'node_outputs': {node_id: {}}}\n",
    "    resolved_inputs = _resolve_bindings(node_def.get('inputBindings', {}), state)\n",
    "    _GRAPH_LOG.info(",
    "        '[GRAPH] event=node_start node_id=%r type=%r capability_id=%r kind=%r',",
    "        node_id, node_type, capability_id, capability_kind,",
    "        extra={'graph_event': 'node_start', 'node_id': node_id, 'node_type': node_type, 'capability_id': capability_id, 'capability_kind': capability_kind},",
    "    )",
    "    if resolved_inputs:",
    "        _GRAPH_LOG.info(",
    "            '[GRAPH] event=node_inputs node_id=%r input_keys=%r inputs_preview=%r',",
    "            node_id, list(resolved_inputs.keys()), str(resolved_inputs)[:500],",
    "            extra={'graph_event': 'node_inputs', 'node_id': node_id, 'input_keys': list(resolved_inputs.keys())},",
    "        )",
    "    else:",
    "        _GRAPH_LOG.warning(",
    "            '[GRAPH] event=node_no_inputs node_id=%r type=%r capability_id=%r kind=%r',",
    "            node_id, node_type, capability_id, capability_kind,",
    "            extra={'graph_event': 'node_no_inputs', 'node_id': node_id, 'node_type': node_type, 'capability_id': capability_id, 'capability_kind': capability_kind},",
    "        )",
    "    if capability_id.startswith('ui:') or capability_kind == 'ui_screen':",
    "        screen_id = capability_id.replace('ui:', '', 1) if capability_id.startswith('ui:') else capability_id",
    "        _GRAPH_LOG.info(",
    "            '[GRAPH] event=ui_interrupt node_id=%r screen_id=%r', node_id, screen_id,",
    "            extra={'graph_event': 'ui_interrupt', 'node_id': node_id, 'screen_id': screen_id},",
    "        )",
    "        user_response = interrupt({'screen_id': screen_id, 'assigned_to': 'human_user', 'ui_data': resolved_inputs})",
    "        _GRAPH_LOG.info(",
    "            '[GRAPH] event=ui_resume node_id=%r response_preview=%r', node_id, str(user_response)[:300],",
    "            extra={'graph_event': 'ui_resume', 'node_id': node_id},",
    "        )",
    "        return {'node_outputs': {node_id: user_response}}\n",
    "    elif capability_id.startswith('tool:') or capability_kind == 'tool' or node_type == 'tool':",
    "        if capability_id.startswith('tool:'):",
    "            tool_name = capability_id.replace('tool:', '', 1)",
    "        else:",
    "            tool_name = node_def.get('name', '').lower().replace(' ', '_')",
    "        _GRAPH_LOG.info(",
    "            '[GRAPH] event=tool_call node_id=%r tool_name=%r', node_id, tool_name,",
    "            extra={'graph_event': 'tool_call', 'node_id': node_id, 'tool_name': tool_name},",
    "        )",
    "        _gi = state.get('global_inputs', {})",
    "        for _k, _v in _gi.items():",
    "            if _k not in resolved_inputs:",
    "                resolved_inputs[_k] = _v",
    "        result = execute_dynamic_tool(tool_name, resolved_inputs)",
    "        result = _await_successful_tool_result(",
    "            tool_name, result,",
    "            lambda: execute_dynamic_tool(tool_name, resolved_inputs),",
    "        )",
    "        _GRAPH_LOG.info(",
    "            '[GRAPH] event=tool_result node_id=%r result_preview=%r', node_id, str(result)[:300],",
    "            extra={'graph_event': 'tool_result', 'node_id': node_id},",
    "        )",
    "        return {'node_outputs': {node_id: result}}\n",
    "    elif capability_id.startswith('agent:workflow:'):",
    "        workflow_id = capability_id.replace('agent:workflow:', '', 1)",
    "        _GRAPH_LOG.info(",
    "            '[GRAPH] event=agent_invoke node_id=%r workflow_id=%r', node_id, workflow_id,",
    "            extra={'graph_event': 'agent_invoke', 'node_id': node_id, 'workflow_id': workflow_id},",
    "        )",
    "        return {'node_outputs': {node_id: {'status': 'agent_invoked', 'workflow_id': workflow_id}}}\n",
    # Return node_id key so downstream bindings like {{unknown_node.param}} resolve to {}
    # rather than silently resolving to None (which would propagate through the graph undetected).
    "    _GRAPH_LOG.warning(",
    "        '[GRAPH] event=unknown_capability node_id=%r capability_id=%r kind=%r',",
    "        node_id, capability_id, capability_kind,",
    "        extra={'graph_event': 'unknown_capability', 'node_id': node_id, 'capability_id': capability_id, 'capability_kind': capability_kind},",
    "    )\n",
    "    return {'node_outputs': {node_id: {}}}\n",
]


from nl_builder.plan_generator import RequirementAnalysisResult, RequirementAnalysisResponse


class RequirementAnalysisRequest(BaseModel):
    """
    Request payload from frontend for requirement analysis.
    """
    prompt: str = Field(..., description="User's high-level process requirement")
    # Optional: if frontend already collected coarse steps, we can refine them later.
    existing_steps: Optional[list[LogicalStep]] = None


class Stage0RespondRequest(BaseModel):
    """Submit MCQ answers for the next Stage 0-B turn."""
    sessionId: str
    answer: str = Field(..., description="User's MCQ selection or free-text answer")
    skipRemaining: bool = Field(
        False,
        description="When true, defer remaining WARN-level flags and complete 0-B early",
    )


class Stage0GuidanceRequest(BaseModel):
    """On-demand setup help for a single requirement flag (does not advance QnA turns)."""
    sessionId: str
    flagKey: str = Field(..., description="flag_type from detectedFlags, e.g. EMAIL_SENDER_CREDENTIALS")
    userQuestion: Optional[str] = Field(
        None,
        description="Optional free-text follow-up, e.g. 'how do I get a Gmail app password?'",
    )


class Stage0GuidanceResponse(BaseModel):
    sessionId: str
    flagKey: str
    guidanceMarkdown: str
    docLinks: list[str] = Field(default_factory=list)
    credentialNames: list[str] = Field(default_factory=list)
    source: Literal["template", "llm"] = "template"
    dependencyType: str = ""


class Stage0MCQQuestionOut(BaseModel):
    question_text: str
    options: list[str]
    flag_type: str
    severity: str
    reportIndex: Optional[int] = None
    field: Optional[str] = None


class Stage0ReportPlanningSummaryOut(BaseModel):
    status: Literal["needs_input", "complete"]
    currentReportIndex: int = 0
    turnCount: int = 0
    reports: list[dict[str, Any]] = Field(default_factory=list)
    summary: dict[str, Any] = Field(default_factory=dict)


class Stage0RequirementFlagOut(BaseModel):
    flag_type: str
    description: str
    severity: str
    resolved: bool = False
    resolved_value: Optional[str] = None


class Stage0ConfigGuidanceOut(BaseModel):
    dependency_type: str
    guide_title: str
    secret_keys: list[str]
    steps: list[str]
    provider_url: Optional[str] = None


class Stage0LogicalStepOut(BaseModel):
    step_number: int
    description: str


class Stage0RequirementSummaryOut(BaseModel):
    phase_name: str
    phase_goal: str
    logical_steps: list[Stage0LogicalStepOut]
    steps: list[LogicalStep] = Field(default_factory=list)
    llm_providers: list[str]
    integrations: list[str]
    db_schemas: list[dict[str, Any]]
    required_secrets: list[str]
    already_configured: list[str]
    config_guidance: list[Stage0ConfigGuidanceOut]
    unresolved_warns: list[str]
    planner_handoff: str = ""


class Stage0HandoffRequest(BaseModel):
    """
    Slice of Stage0Response to pass into POST /agentic/plan/scratch/preview.

    Frontend: after /stage0/respond returns status=complete, send:
      stage0Handoff: { requirementSummary }
    ``requirementSummary.planner_handoff`` is injected into scratch planning.
    """
    requirementSummary: Stage0RequirementSummaryOut


class Stage0Response(BaseModel):
    """
    Response from /stage0/start and /stage0/respond.

    Shape mirrors AgenticPlanPreviewResponse so the frontend can treat
    Stage 0 as a transparent pre-flight gate before /scratch/preview.
    """
    sessionId: str
    status: Literal["needs_input", "complete"]
    # ── Mirror of AgenticPlanPreviewResponse top-level fields ──────────────
    workflowId: str = ""
    workflowName: Optional[str] = None
    mode: Literal["prompt", "steps"] = "prompt"
    analysis_source: Optional[Literal["llm", "fallback"]] = None
    # ── Stage 0-specific fields ─────────────────────────────────────────────
    message: Optional[str] = None
    questions: list[Stage0MCQQuestionOut] = Field(default_factory=list)
    credentialCheck: Optional[CredentialCheckResult] = None
    detectedFlags: list[Stage0RequirementFlagOut] = Field(default_factory=list)
    resolvedFlags: list[Stage0RequirementFlagOut] = Field(default_factory=list)
    turnCount: int = 0
    requirementSummary: Optional[Stage0RequirementSummaryOut] = None
    warnings: list[str] = Field(default_factory=list)
    reportPlanning: Optional[Stage0ReportPlanningSummaryOut] = None
    reportExecutionPlan: Optional[str] = Field(
        None,
        description=(
            "Documentation-style execution plan for Suggested Reports planning. "
            "Present only when the request payload included a non-empty suggestedReports array."
        ),
    )
    expandedSteps: list[LogicalStep] = Field(
        default_factory=list,
        description=(
            "Prompt-mode only: enterprise steps produced before Stage 0 clarification. "
            "Empty in steps mode or when expansion falls back."
        ),
    )


class _Stage0Session(BaseModel):
    session_id: str
    workflow_id: str
    raw_prompt: str
    org_id: Optional[str] = None
    subscriber_id: Optional[str] = None
    user_id: Optional[str] = None
    state: Stage0State
    turn_count: int = 0
    # mirrors AgenticPlanPreviewResponse
    workflow_name: Optional[str] = None
    mode: Literal["prompt", "steps"] = "prompt"
    analysis_source: Optional[Literal["llm", "fallback"]] = None
    # LogicalSteps: user-provided (steps mode) OR NL enterprise expansion (prompt mode)
    provided_steps: list[LogicalStep] = Field(default_factory=list)
    expander_warnings: list[str] = Field(default_factory=list)
    original_user_prompt: Optional[str] = None
    suggested_reports: list[dict[str, Any]] = Field(default_factory=list)
    report_planning: Optional[ReportPlanningSession] = None
    # NL builder plan snapshot so /nl/plan/revise survives process restart / other workers.
    nl_plan: Optional[Dict[str, Any]] = None
    nl_plan_project_id: Optional[str] = None


_STAGE0_COLLECTION = "stage0_sessions"
_STAGE0_TTL_SECONDS = 1800  # 30 minutes


class Stage0SessionManager:
    """
    MongoDB-backed store for Stage 0 clarification sessions.

    Each session is a document in the ``stage0_sessions`` collection.
    A TTL index on ``createdAt`` automatically deletes expired sessions
    (default: 30 minutes) — no cleanup code required.

    All methods are async and safe for multi-instance deployments.
    """

    # ── Index creation ────────────────────────────────────────────────────────

    async def create_indexes(self) -> None:
        """
        Create indexes on first startup.
        - Unique index on session_id for fast O(1) lookups.
        - TTL index on createdAt for automatic expiry.
        Call from the FastAPI lifespan startup handler.
        """
        coll = Database.get_collection(_STAGE0_COLLECTION)
        await coll.create_index("session_id", unique=True)
        await coll.create_index(
            "createdAt",
            expireAfterSeconds=_STAGE0_TTL_SECONDS,
            name="stage0_ttl_idx",
        )
        logger.info(
            "stage0_sessions indexes created (TTL=%ds)", _STAGE0_TTL_SECONDS
        )

    # ── CRUD ─────────────────────────────────────────────────────────────────

    async def create(self, session: _Stage0Session) -> None:
        coll = Database.get_collection(_STAGE0_COLLECTION)
        doc = {
            "session_id": session.session_id,
            "data": session.model_dump(mode="json"),
            "createdAt": datetime.utcnow(),
            "updatedAt": datetime.utcnow(),
        }
        await coll.insert_one(doc)

    async def get(self, session_id: str) -> Optional[_Stage0Session]:
        coll = Database.get_collection(_STAGE0_COLLECTION)
        doc = await coll.find_one({"session_id": session_id})
        if doc is None:
            return None
        try:
            return _Stage0Session.model_validate(doc["data"])
        except Exception as exc:
            logger.warning("Failed to deserialise stage0 session %s: %s", session_id, exc)
            return None

    async def save(self, session: _Stage0Session) -> None:
        """Persist updated session state (called after every respond turn)."""
        coll = Database.get_collection(_STAGE0_COLLECTION)
        await coll.update_one(
            {"session_id": session.session_id},
            {
                "$set": {
                    "data": session.model_dump(mode="json"),
                    "updatedAt": datetime.utcnow(),
                }
            },
            upsert=True,
        )

    async def delete(self, session_id: str) -> None:
        coll = Database.get_collection(_STAGE0_COLLECTION)
        await coll.delete_one({"session_id": session_id})


stage0_session_manager = Stage0SessionManager()


def _serialize_phase_graph_results(phase_results: list) -> list[Dict[str, Any]]:
    return [p.model_dump(exclude={"langgraph_code"}) for p in phase_results]


def _billing_pause_error(
    exc: BillingError,
    *,
    workflow_id: Optional[str],
    subscriber_id: Optional[str],
) -> Dict[str, Any]:
    detail = billing_error_to_http_detail(exc)
    return enrich_billing_error_detail(
        detail,
        db=db,
        workflow_id=workflow_id,
        subscriber_id=subscriber_id,
    )


async def _publish_paused_credit(workflow_id: Optional[str], detail: Dict[str, Any]) -> None:
    """
    Push a paused_credit event to any live SSE subscribers for this workflow.
    Safe no-op if workflow_id is missing or nobody is currently connected —
    the connect-time checkpoint snapshot (see /agentic/workflow/stream/{id})
    is what covers the "user reconnects later" case, this only handles the
    live/real-time delivery to whoever is watching right now.
    Scope: called only from scratch/preview and execute pause sites, not
    Stage0 (Stage0 is synchronous FE-initiated, no async notification needed).
    """
    if not workflow_id:
        return
    try:
        await workflow_stream_registry.publish(
            workflow_id, {"type": "paused_credit", **detail}
        )
    except Exception:
        # Never let a stream-publish failure break the actual 402 response path.
        logger.exception(
            "workflow_stream publish failed workflow_id=%s (paused_credit)", workflow_id
        )


async def _publish_workflow_terminal(workflow_id: Optional[str], event_type: str, **extra: Any) -> None:
    """Push a 'completed' or 'error' terminal event. Same safety guarantees as above."""
    if not workflow_id:
        return
    try:
        await workflow_stream_registry.publish(
            workflow_id, {"type": event_type, "workflowId": workflow_id, **extra}
        )
    except Exception:
        logger.exception(
            "workflow_stream publish failed workflow_id=%s (%s)", workflow_id, event_type
        )


async def _checkpoint_stage0_pause(
    *,
    session: _Stage0Session,
    action: str,
    exc: BillingError,
    skip_remaining: bool = False,
    guidance_flag_key: Optional[str] = None,
    guidance_user_question: Optional[str] = None,
) -> None:
    if not session.subscriber_id:
        return
    write_checkpoint(
        db=db,
        workflow_id=session.workflow_id,
        subscriber_id=session.subscriber_id,
        org_id=session.org_id,
        user_id=session.user_id,
        status="paused_credit",
        pipeline_stage="stage0",
        phase_index=0,
        phase_total=0,
        stage0_session=session.model_dump(mode="json"),
        stage0_action=action,
        stage0_skip_remaining=skip_remaining,
        stage0_guidance_flag_key=guidance_flag_key,
        stage0_guidance_user_question=guidance_user_question,
        last_error={
            "code": exc.code,
            "at": datetime.utcnow().isoformat(),
        },
    )
    set_workflow_agentic_status(
        db=db,
        workflow_id=session.workflow_id,
        subscriber_id=session.subscriber_id,
        org_id=session.org_id,
        user_id=session.user_id,
        status="paused_credit",
    )
    await stage0_session_manager.save(session)


def _stage0_require_gemini_key() -> str:
    api_key = get_gemini_api_key()
    if not api_key:
        raise HTTPException(
            status_code=503,
            detail={
                "error": "gemini_api_key_unavailable",
                "message": "Gemini API key is not available (GCP Secret Manager / config).",
            },
        )
    return api_key


async def _stage0_refresh_credentials(
    session: _Stage0Session,
) -> tuple[CredentialCheckResult, list[str]]:
    """
    Re-read Configure Credentials from the database and update session state.

    Returns the fresh check result and names added since the last stored snapshot.
    """
    previous_names = (
        list(session.state.credential_check.configured_secret_names)
        if session.state.credential_check
        else []
    )
    cred_svc = CredentialService.optional()
    cred_result = await fetch_configured_secrets(
        session.workflow_id,
        credential_service=cred_svc,
        org_id=session.org_id,
        subscriber_id=session.subscriber_id,
    )
    newly_added = credentials_added_since(previous_names, cred_result.configured_secret_names)
    session.state.credential_check = cred_result
    if newly_added:
        logger.info(
            "Stage 0 session %s: credentials refreshed (%d total, %d new: %s)",
            session.session_id,
            len(cred_result.configured_secret_names),
            len(newly_added),
            ", ".join(newly_added),
        )
    return cred_result, newly_added


def _stage0_questions_to_out(questions: list[MCQQuestion]) -> list[Stage0MCQQuestionOut]:
    return [
        Stage0MCQQuestionOut(
            question_text=q.question_text,
            options=q.options,
            flag_type=q.flag_type,
            severity=q.severity,
        )
        for q in questions
    ]


def _report_planning_questions_to_out(
    questions: list[dict[str, Any]],
) -> list[Stage0MCQQuestionOut]:
    return [
        Stage0MCQQuestionOut(
            question_text=q["question_text"],
            options=list(q.get("options") or []),
            flag_type=str(q.get("flag_type") or q.get("field") or "REPORT"),
            severity=str(q.get("severity") or "CRITICAL"),
            reportIndex=q.get("reportIndex"),
            field=q.get("field"),
        )
        for q in questions
    ]


def _report_planning_to_out(
    session: Optional[ReportPlanningSession],
) -> Optional[Stage0ReportPlanningSummaryOut]:
    if session is None:
        return None
    data = session.to_out()
    return Stage0ReportPlanningSummaryOut(
        status=data["status"],
        currentReportIndex=data["currentReportIndex"],
        turnCount=data["turnCount"],
        reports=data["reports"],
        summary=data["summary"],
    )


def _report_execution_plan_for_session(session: _Stage0Session) -> Optional[str]:
    if not session.suggested_reports:
        return None
    return generate_suggested_reports_execution_plan(base_step=5)


def _init_session_report_planning(
    session: _Stage0Session,
    suggested_reports: Optional[list[dict[str, Any]]],
) -> None:
    reports = [r for r in (suggested_reports or []) if isinstance(r, dict)]
    session.suggested_reports = reports
    if not reports:
        session.report_planning = None
        return

    db_schemas: list[Any] = []
    clarified = session.state.clarified_requirements
    if clarified is not None and clarified.db_schemas:
        db_schemas = [s.model_dump() for s in clarified.db_schemas]

    available_schema = None
    if db_schemas:
        available_schema = build_available_schema_from_db_schemas(db_schemas)

    session.report_planning = initialize_report_planning_session(reports, available_schema)


def _refresh_session_report_planning_schema(session: _Stage0Session) -> None:
    planning = session.report_planning
    if planning is None:
        return
    clarified = session.state.clarified_requirements
    if clarified is None or not clarified.db_schemas:
        return
    refresh_report_planning_schema(
        planning,
        [s.model_dump() for s in clarified.db_schemas],
    )
    advance_report_planning(planning)


def _stage0_response_questions(
    session: _Stage0Session,
    stage0_questions: list[MCQQuestion],
) -> list[Stage0MCQQuestionOut]:
    planning = session.report_planning
    if planning is not None and report_planning_has_pending_input(planning):
        return _report_planning_questions_to_out(
            report_planning_questions_for_response(planning)
        )
    return _stage0_questions_to_out(stage0_questions)


def _stage0_report_planning_fields(
    session: _Stage0Session,
) -> tuple[Optional[Stage0ReportPlanningSummaryOut], Optional[str]]:
    return (
        _report_planning_to_out(session.report_planning),
        _report_execution_plan_for_session(session),
    )


def _stage0_report_planning_warnings(session: _Stage0Session) -> list[str]:
    planning = session.report_planning
    if planning is None:
        return []
    return list(planning.warnings)


def _stage0_report_planning_blocks_stage0(session: _Stage0Session) -> bool:
    planning = session.report_planning
    return planning is not None and not planning.complete


def _stage0_flags_to_out(flags: list[RequirementFlag]) -> list[Stage0RequirementFlagOut]:
    return [
        Stage0RequirementFlagOut(
            flag_type=f.flag_type,
            description=f.description,
            severity=f.severity,
            resolved=f.resolved,
            resolved_value=f.resolved_value,
        )
        for f in flags
    ]


def _stage0_guidance_to_out(guidance: list[Stage0ConfigGuidance]) -> list[Stage0ConfigGuidanceOut]:
    return [
        Stage0ConfigGuidanceOut(
            dependency_type=g.dependency_type,
            guide_title=g.guide_title,
            secret_keys=g.secret_keys,
            steps=g.steps,
            provider_url=g.provider_url,
        )
        for g in guidance
    ]


def _stage0_logical_steps_for_planner(summary: Stage0RequirementSummary) -> list[LogicalStep]:
    steps: list[LogicalStep] = []
    for step in summary.logical_steps:
        step_id = f"L{step.step_number}"
        steps.append(
            LogicalStep(
                stepId=step_id,
                name=f"Step {step.step_number}",
                description=step.description,
            )
        )
    return steps


def _build_stage0_planner_context(handoff: Stage0HandoffRequest) -> str:
    """Format Stage 0 structured handoff for scratch skeleton planner."""
    return format_stage0_planner_context(handoff.requirementSummary)


def _stage0_summary_to_out(summary: Stage0RequirementSummary) -> Stage0RequirementSummaryOut:
    return Stage0RequirementSummaryOut(
        phase_name=summary.phase_name,
        phase_goal=summary.phase_goal,
        logical_steps=[
            Stage0LogicalStepOut(step_number=s.step_number, description=s.description)
            for s in summary.logical_steps
        ],
        steps=_stage0_logical_steps_for_planner(summary),
        llm_providers=summary.llm_providers,
        integrations=summary.integrations,
        db_schemas=[schema.model_dump() for schema in summary.db_schemas],
        required_secrets=summary.required_secrets,
        already_configured=summary.already_configured,
        config_guidance=_stage0_guidance_to_out(summary.config_guidance),
        unresolved_warns=summary.unresolved_warns,
        planner_handoff=summary.planner_handoff,
    )


def _expanded_steps_out(session: "_Stage0Session") -> list:
    return list(session.provided_steps or []) if getattr(session, "mode", None) == "prompt" else []


def _expander_session_warnings(session: "_Stage0Session") -> list[str]:
    return list(getattr(session, "expander_warnings", None) or [])


def _stage0_steps_to_prompt(phases: list[AgenticPhaseStep]) -> str:
    """
    Synthesise a plain-English description from structured phases/subSteps
    so Stage 0-B can analyse it exactly as it would a free-text prompt.
    """
    lines: list[str] = []
    idx = 1
    for phase in phases:
        if phase.subSteps:
            for sub in phase.subSteps:
                lines.append(f"Step {idx}: {sub.name} — {sub.description}")
                idx += 1
        else:
            lines.append(f"Step {idx}: {phase.name} — {phase.description}")
            idx += 1
    return "\n".join(lines)


def _stage0_phases_to_logical_steps(phases: list[AgenticPhaseStep]) -> list[LogicalStep]:
    """Convert AgenticPhaseStep list to flat LogicalStep list (same as scratch/preview does)."""
    steps: list[LogicalStep] = []
    idx = 1
    for phase in phases:
        if phase.subSteps:
            for sub in phase.subSteps:
                kind = sub.preferredKind if sub.preferredKind in ("ui_screen", "tool") else None
                steps.append(LogicalStep(
                    stepId=sub.stepId or f"L{idx}",
                    name=sub.name,
                    description=sub.description,
                    inputs=[],
                    outputs=[],
                    preferredKind=kind,
                ))
                idx += 1
        else:
            steps.append(LogicalStep(
                stepId=phase.stepId or f"L{idx}",
                name=phase.name,
                description=phase.description or phase.name,
                inputs=[],
                outputs=[],
                preferredKind=None,
            ))
            idx += 1
    return steps


async def _stage0_finish_session(
    session: _Stage0Session,
    *,
    unresolved_warns: Optional[list[str]] = None,
) -> Stage0Response:
    """Complete QnA only — setup guidance is via POST /stage0/guidance."""
    state = session.state
    clarified = state.clarified_requirements
    if clarified is None:
        raise HTTPException(
            status_code=500,
            detail="Stage 0-B completed without clarified requirements.",
        )

    cred_result = state.credential_check
    if cred_result is None:
        raise HTTPException(status_code=500, detail="Stage 0 credential check missing from session.")

    state.clarified_requirements = ensure_clarified_requirements(
        clarified,
        state.detected_flags,
        cred_result.configured_secret_names,
    )
    clarified = state.clarified_requirements

    req_summary = build_requirement_summary(clarified, [], cred_result)
    if unresolved_warns:
        req_summary.unresolved_warns = unresolved_warns
    state.requirement_summary = req_summary
    state.stage0b_complete = True
    state.config_guidance = []
    state.stage0c_complete = False

    summary_out = _stage0_summary_to_out(req_summary)
    if getattr(session, "mode", None) == "prompt":
        # Prompt mode: only enterprise expander output. Do not ship Stage 0-B's
        # generic "Step N" rows — preview would treat 6+ of them as a real plan.
        summary_out.steps = list(session.provided_steps or [])
    elif session.provided_steps:
        summary_out.steps = session.provided_steps

    report_planning_out, execution_plan = _stage0_report_planning_fields(session)
    all_warnings = list(req_summary.unresolved_warns)
    all_warnings.extend(_stage0_report_planning_warnings(session))
    all_warnings.extend(_expander_session_warnings(session))

    response = Stage0Response(
        sessionId=session.session_id,
        status="complete",
        message=(
            "Requirement clarification complete. Use POST /stage0/guidance for setup help "
            "on any flag. Requirement summary is ready for the workflow planner."
        ),
        workflowId=session.workflow_id,
        workflowName=session.workflow_name,
        mode=session.mode,
        analysis_source=session.analysis_source,
        credentialCheck=cred_result,
        detectedFlags=_stage0_flags_to_out(state.detected_flags),
        resolvedFlags=[f for f in _stage0_flags_to_out(state.detected_flags) if f.resolved],
        turnCount=session.turn_count,
        requirementSummary=summary_out,
        warnings=all_warnings,
        reportPlanning=report_planning_out,
        reportExecutionPlan=execution_plan,
        expandedSteps=_expanded_steps_out(session),
    )
    # Keep session in Mongo until TTL so /stage0/guidance works after QnA completes.
    await stage0_session_manager.save(session)
    return response


async def _stage0_apply_b_turn(
    session: _Stage0Session,
    parsed,
    *,
    api_key: str,
    skip_remaining: bool = False,
) -> Stage0Response:
    state = session.state
    cred_names = (
        state.credential_check.configured_secret_names
        if state.credential_check
        else []
    )
    parsed, state.detected_flags = finalize_stage0b_turn(
        parsed, state.detected_flags, cred_names
    )
    state.resolved_flags = [f for f in state.detected_flags if f.resolved]
    state.conversation_turns.append(
        Stage0Turn(
            role="assistant",
            content=_format_stage0b_assistant_turn(parsed.message, parsed.questions),
        )
    )
    state.pending_questions = list(parsed.questions) if parsed.questions else []

    if parsed.clarified_requirements is not None:
        state.clarified_requirements = parsed.clarified_requirements
        _refresh_session_report_planning_schema(session)

    unresolved_critical = critical_unresolved_flags(state.detected_flags)
    unresolved = [f for f in state.detected_flags if not f.resolved]
    deferred_warns: list[str] = []

    if skip_remaining:
        for flag in unresolved:
            if flag.severity == "WARN":
                flag.resolved = True
                flag.resolved_value = "deferred"
                deferred_warns.append(flag.description)
        unresolved = [f for f in state.detected_flags if not f.resolved]
        unresolved_critical = [f for f in unresolved if f.severity == "CRITICAL"]

    report_planning_out, execution_plan = _stage0_report_planning_fields(session)
    report_warnings = _stage0_report_planning_warnings(session)
    combined_warnings = list(deferred_warns) + report_warnings + _expander_session_warnings(session)

    if _stage0_report_planning_blocks_stage0(session):
        await stage0_session_manager.save(session)
        planning = session.report_planning
        assert planning is not None
        return Stage0Response(
            sessionId=session.session_id,
            status="needs_input",
            workflowId=session.workflow_id,
            workflowName=session.workflow_name,
            mode=session.mode,
            analysis_source=session.analysis_source,
            message=(
                parsed.message
                if parsed.message
                else "Please resolve the suggested report configuration before continuing."
            ),
            questions=_stage0_response_questions(session, parsed.questions or []),
            credentialCheck=state.credential_check,
            detectedFlags=_stage0_flags_to_out(state.detected_flags),
            resolvedFlags=_stage0_flags_to_out(state.resolved_flags),
            turnCount=session.turn_count,
            warnings=combined_warnings,
            reportPlanning=report_planning_out,
            reportExecutionPlan=execution_plan,
            expandedSteps=_expanded_steps_out(session),
        )

    if parsed.is_complete and parsed.clarified_requirements is not None:
        state.clarified_requirements = parsed.clarified_requirements
        return await _stage0_finish_session(
            session,
            unresolved_warns=deferred_warns or None,
        )

    if skip_remaining and not unresolved_critical:
        state.clarified_requirements = parsed.clarified_requirements or state.clarified_requirements
        if state.clarified_requirements is None:
            cred_names = (
                state.credential_check.configured_secret_names
                if state.credential_check
                else []
            )
            state.clarified_requirements = ensure_clarified_requirements(
                None,
                state.detected_flags,
                cred_names,
            )
        return await _stage0_finish_session(session, unresolved_warns=deferred_warns)

    if not parsed.questions:
        if unresolved_critical:
            raise HTTPException(
                status_code=502,
                detail="Stage 0-B returned no questions but critical blockers remain.",
            )
        raise HTTPException(
            status_code=502,
            detail=(
                "Stage 0-B: no blocker questions remain but requirement summary was not produced. "
                "Retry /stage0/respond or call /stage0/start again."
            ),
        )

    await stage0_session_manager.save(session)

    return Stage0Response(
        sessionId=session.session_id,
        status="needs_input",
        workflowId=session.workflow_id,
        workflowName=session.workflow_name,
        mode=session.mode,
        analysis_source=session.analysis_source,
        message=parsed.message,
        questions=_stage0_response_questions(session, parsed.questions),
        credentialCheck=state.credential_check,
        detectedFlags=_stage0_flags_to_out(state.detected_flags),
        resolvedFlags=_stage0_flags_to_out(state.resolved_flags),
        turnCount=session.turn_count,
        warnings=combined_warnings,
        reportPlanning=report_planning_out,
        reportExecutionPlan=execution_plan,
        expandedSteps=_expanded_steps_out(session),
    )


def _add_model_metrics(
    models_summary: Dict[str, Dict[str, Any]],
    model_name: str,
    src: Dict[str, Any],
) -> None:
    """
    Merge per-model metrics from a source dict into the aggregate summary.
    Expected src keys (from generators/processors):
      - total_input_tokens, total_output_tokens, total_tokens
      - total_cost_usd, total_calls
    """
    if not model_name or not src:
        return

    dest = models_summary.setdefault(model_name, {
        "input_tokens": 0,
        "output_tokens": 0,
        "total_tokens": 0,
        "cost_usd": 0.0,
        "api_call_count": 0,
    })

    dest["input_tokens"] += int(src.get("total_input_tokens", 0))
    dest["output_tokens"] += int(src.get("total_output_tokens", 0))
    dest["total_tokens"] += int(src.get("total_tokens", 0))
    dest["cost_usd"] += float(src.get("total_cost_usd", 0.0))
    dest["api_call_count"] += int(src.get("total_calls", 0))


async def _persist_llm_tokens(
    *,
    project_id: str,
    screen_id: str,
    operation: str,
    version: Optional[str],
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
) -> None:
    """
    Aggregate LLM token usage across services for a single request and
    persist a summary document into the LLM_Tokens collection.
    """
    models_summary: Dict[str, Dict[str, Any]] = {}

    # 1) IR / AIProcessor (gemini-3-flash-preview + configured IR model)
    ai_metrics = ai_processor.get_session_metrics()
    if ai_metrics.get("total_calls", 0) > 0:
        src = {
            "total_input_tokens": ai_metrics.get("total_input_tokens", 0),
            "total_output_tokens": ai_metrics.get("total_output_tokens", 0),
            "total_tokens": ai_metrics.get("total_tokens", 0),
            "total_cost_usd": ai_metrics.get("total_cost_usd", 0.0),
            "total_calls": ai_metrics.get("total_calls", 0),
        }
        _add_model_metrics(models_summary, "gemini-3-flash-preview", src)

    # 2) Angular generator (may use multiple models)
    if hasattr(angular_generator, "get_token_usage_summary"):
        for model_name, m in angular_generator.get_token_usage_summary().items():
            _add_model_metrics(models_summary, model_name, m)

    # 3) Backend generator (gemini-3.6-flash)
    if hasattr(backend_generator, "get_token_usage_summary"):
        for model_name, m in backend_generator.get_token_usage_summary().items():
            _add_model_metrics(models_summary, model_name, m)

    # 4) Agent-level usage (classification, etc.)
    for model_name, m in get_agent_llm_usage().items():
        _add_model_metrics(models_summary, model_name, m)

    if not models_summary:
        return

    # Convert org_id, subscriber_id, user_id to ObjectId if provided
    org_id_obj = None
    subscriber_id_obj = None
    user_id_obj = None
    
    if org_id:
        try:
            org_id_obj = ObjectId(org_id) if isinstance(org_id, str) else org_id
        except Exception as e:
            logger.warning(f"Failed to convert org_id to ObjectId: {e}")
    
    if subscriber_id:
        try:
            subscriber_id_obj = ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id
        except Exception as e:
            logger.warning(f"Failed to convert subscriber_id to ObjectId: {e}")
    
    if user_id:
        try:
            user_id_obj = ObjectId(user_id) if isinstance(user_id, str) else user_id
        except Exception as e:
            logger.warning(f"Failed to convert user_id to ObjectId: {e}")

    doc = {
        "project_id": project_id,
        "screen_id": screen_id,
        "orgId": org_id_obj,
        "subscriberId": subscriber_id_obj,
        "userId": user_id_obj,
        "process": "ai-screen-builder",
        "operation": operation,
        "version": version,
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "models": models_summary,
    }

    try:
        collection = Database.get_collection("LLM_Tokens")
        await collection.insert_one(doc)
    except Exception as e:
        logger.warning(f"Failed to persist LLM_Tokens document: {e}")

async def classify_update_category(
    prompt: str, 
    api_key: str | None = None,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    project_id: Optional[str] = None,
    screen_id: Optional[str] = None
) -> UpdateCategory:
    """
        Classify update request using Gemini 2.5 Flash with structured output.
        
        Args:
            prompt: User's update request
            api_key: Google AI API key (optional, uses get_gemini_api_key() if not provided)
            org_id: Organization ID for tracking
            subscriber_id: Subscriber ID for tracking
            user_id: User ID for tracking
            project_id: Project ID for tracking
            screen_id: Screen ID for tracking
            
        Returns:
            UpdateCategory object with classification results
            
        Category A (UI Only):
        - Pure styling: colors, fonts, text labels, themes, borders, shadows
        - Layout adjustments: padding, margin, spacing, alignment, positioning
        - Visual changes that DON'T alter component structure
        
        Category B (Behavior):
        - Adding/removing components (forms, tables, fields, buttons, sections)
        - API integration, data sources, backend logic
        - Validation rules, business logic, workflows
        - Database queries, data models, schemas
        
        NOTE: Adding/removing components is Category B because it may require:
        - New data models (dataModels in IR schema)
        - New data sources (dataSources in IR schema)
        - New backend API functions
        - Removal of associated backend functions
    """
    if api_key is None:
        api_key = get_gemini_api_key()
    
    classification_prompt = f"""
        Analyze this UI update request and classify it into categories:

        **Category A (UI Only):**
        - Pure styling: colors, fonts, text labels, themes, borders, shadows
        - Layout adjustments: padding, margin, spacing, alignment, positioning
        - Visual changes that DON'T alter component structure
        - Fixing a chart/widget attribute like xfield, yfield, charttype, title

        **Category B (Behavior):**
        - Adding/removing components (forms, tables, fields, buttons, sections)
        - API integration, data sources, backend logic
        - Validation rules, business logic, workflows
        - Database queries, data models, schemas

        **Mixed (UI + Behavior):**
        - Blank chart / no data showing in a specific widget or report
          → The fix may require updating BOTH the frontend attribute (UI) AND the
            backend query / IR data source configuration (behavior).
        - Chart showing wrong values or wrong field mapping
        - Any report that says "data is not coming", "data is missing", "chart is blank"

        **User Request:** "{prompt}"

        **Classification Rules:**
        1. If ONLY styling/layout/attribute fix → categories: ["ui"], primary_category: "ui"
        2. If ONLY logic/components/backend → categories: ["behavior"], primary_category: "behavior"
        3. If "data not coming", "blank", "not showing", "no data", or similar → categories: ["ui", "behavior"], primary_category: "behavior"
           (These always require both UI and behavior checks because the root cause could be
            a wrong frontend attribute, a broken backend pipeline, or both.)
        4. If BOTH UI and behavior changes → categories: ["ui", "behavior"], primary_category: "behavior"
        (IMPORTANT: Mixed requests are always classified as "behavior" because behavior changes take precedence)

        Return the classification.
        """
    
    try:
        started_at = datetime.utcnow()
        response = await async_generate(
            "gemini-3.5-flash-lite",
            classification_prompt,
            config=GeminiGenerateConfig(
                temperature=0.1,
                response_mime_type="application/json",
                response_schema=UpdateCategory,
            ),
            api_key=api_key,
        )
        finished_at = datetime.utcnow()

        # Track token usage for this classification call
        usage = getattr(response, "usage_metadata", None)
        if usage:
            prompt_tokens = getattr(usage, "prompt_token_count", 0)
            completion_tokens = getattr(usage, "candidates_token_count", 0)
            total_tokens = getattr(usage, "total_token_count", 0) or (prompt_tokens + completion_tokens)
            record_agent_llm_usage(
                "gemini-3.5-flash-lite",
                prompt_tokens,
                completion_tokens,
                total_tokens,
            )
            
            # Also record to database
            record_llm_call(
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                project_id=project_id,
                screen_id=screen_id,
                operation="screen-update",
                sub_operation="classify-update-category",
                model="gemini-3.5-flash-lite",
                prompt_tokens=prompt_tokens,
                completion_tokens=completion_tokens,
                total_tokens=total_tokens,
                status="success",
                started_at=started_at,
                finished_at=finished_at
            )
        
        # The SDK automatically parses JSON into the Pydantic model
        return response.parsed
        
    except Exception as e:
        logger.warning(f"Error calling Gemini API for classification: {e}")
        
        # Record failed attempt
        record_llm_call(
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            project_id=project_id,
            screen_id=screen_id,
            operation="screen-update",
            sub_operation="classify-update-category",
            model="gemini-3.5-flash-lite",
            prompt_tokens=0,
            completion_tokens=0,
            total_tokens=0,
            status="failed",
            metadata={"error": str(e)}
        )
        
        # Fallback to keyword-based classification
        return fallback_classification(prompt)


from nl_builder.plan_generator import (
    _normalize_logical_steps,
    _fallback_requirement_analysis,
    analyze_requirements_with_llm,
)

def fallback_classification(prompt: str) -> UpdateCategory:
    """Fallback keyword-based classification if LLM fails."""
    prompt_lower = prompt.lower()
    
    behavior_keywords = [
        "add ", "remove ", "delete ", "create ",
        "api", "validation", "logic", "backend", "database",
        "field", "component", "form", "table", "section"
    ]
    
    ui_keywords = [
        "color", "theme", "font", "padding", "margin",
        "background", "border", "style", "spacing"
    ]
    
    has_behavior = any(kw in prompt_lower for kw in behavior_keywords)
    has_ui = any(kw in prompt_lower for kw in ui_keywords)
    
    categories = []
    if has_ui:
        categories.append("ui")
    if has_behavior:
        categories.append("behavior")
    
    if not categories:
        categories = ["ui"]  # Default
    
    # If ANY behavior changes exist, primary is "behavior"
    primary = "behavior" if has_behavior else "ui"
    
    return UpdateCategory(
        has_ui_changes=has_ui,
        has_behavior_changes=has_behavior,
        categories=categories,
        primary_category=primary
    )

@app.get("/")
async def root():
    """Root endpoint"""
    return {
        "message": "AI Screen Builder API",
        "version": "1.0.0"
    }


@app.post("/aiqod-agent/agent/requirements/analyze", response_model=RequirementAnalysisResponse)
async def analyze_requirements(request: RequirementAnalysisRequest, http_request: Request):
    """
    API endpoint used by the frontend to turn a natural language requirement
    into a list of logical steps.

    This endpoint:
    - Calls Gemini with a structured JSON schema to generate candidate steps.
    - Validates and normalizes those steps (IDs, fields, preferredKind).
    - Falls back to a deterministic heuristic if the LLM call fails.
    """
    # In future we can pull org/subscriber/user from headers or auth.
    org_id = http_request.headers.get("x-org-id")
    subscriber_id = http_request.headers.get("x-subscriber-id")
    user_id = http_request.headers.get("x-user-id")

    if not request.prompt or not request.prompt.strip():
        raise HTTPException(status_code=400, detail="prompt must not be empty")

    result = await analyze_requirements_with_llm(
        prompt=request.prompt,
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
    )

    return result


@app.post("/aiqod-agent/agent/stage0/start", response_model=Stage0Response)
async def stage0_start(request: AgenticPlanRequest, http_request: Request) -> Stage0Response:
    """
    Stage 0 entry point — credential check (0-A) + first clarification turn (0-B).

    Prompt mode first expands the NL request into enterprise logical steps, then
    0-B clarifies those steps (credentials, collections, review vs auto). Prefer
    passing `expandedSteps` from `/nl/expand` (and optional `/nl/steps/revise`) so
    Stage 0 does not expand again. The expanded plan is copied onto
    `requirementSummary.steps` when Stage 0 completes, for `/scratch/preview`
    via `stage0Handoff`. Steps mode is unchanged (caller-supplied steps, no expander).

    Accepts the same payload as /agentic/plan/scratch/preview so the frontend
    can call Stage 0 before workflow creation without changing its request shape:
      - `prompt`  (non-empty string) — free-text workflow description
      - `steps`   (list[AgenticPhaseStep]) — already-decomposed phases/subSteps

    Exactly one of `prompt` or `steps` must be provided — UNLESS `suggestedReports`
    is supplied on its own (dashboard-only flow: /agentic/dashboard/* callers reuse
    this same endpoint for report clarification without a workflow prompt/steps).
    `projectId` is required for credential lookup (Sub-Phase 0-A).

    Returns MCQ questions (status="needs_input") while clarification is in progress,
    or RequirementSummary (status="complete") when QnA is done. Setup help is separate:
    POST /stage0/guidance per flag. On completion, `requirementSummary.config_guidance`
    is empty; use guidance API when the user clicks "How do I set this up?"
    """
    has_prompt = bool(request.prompt and request.prompt.strip())
    has_steps = bool(request.steps)
    has_reports_only = bool(request.suggestedReports) and not has_prompt and not has_steps

    if not has_reports_only and has_prompt == has_steps:
        raise HTTPException(
            status_code=400,
            detail=(
                "Exactly one of 'prompt' (non-empty) or 'steps' must be provided "
                "(or 'suggestedReports' alone for a dashboard-only planning session)."
            ),
        )
    if not (request.projectId or "").strip():
        raise HTTPException(status_code=400, detail="projectId is required.")

    org_id = request.orgId or http_request.headers.get("x-org-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    project_id = request.projectId.strip()
    workflow_name = request.selectedName or "workflow"
    api_key = _stage0_require_gemini_key()

    _init_agentic_workflow_billing(
        project_id=project_id,
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
    )
    if subscriber_id:
        set_workflow_agentic_status(
            db=db,
            workflow_id=project_id,
            subscriber_id=subscriber_id,
            org_id=org_id,
            user_id=user_id,
            status="stage0_in_progress",
        )

    # ── Resolve raw_prompt and mode (same logic as scratch/preview) ───────────
    expander_warnings: list[str] = []
    original_user_prompt: Optional[str] = None
    if has_prompt:
        original_user_prompt = request.prompt.strip()
        raw_prompt = original_user_prompt
        mode: Literal["prompt", "steps"] = "prompt"
        analysis_source: Optional[Literal["llm", "fallback"]] = None
        provided_steps: list[LogicalStep] = []
        pre_expanded = list(request.expandedSteps or [])
        if pre_expanded:
            from nl_builder.enterprise_expander import (
                compose_expanded_steps_prompt,
                _without_io,
            )

            provided_steps = pre_expanded
            try:
                provided_steps, norm_warns = _normalize_logical_steps(
                    provided_steps, preserve_ids=True
                )
                expander_warnings.extend(norm_warns)
            except Exception:
                provided_steps = pre_expanded
            # Prompt-mode enterprise steps are capability-only; Stage 2 owns I/O.
            provided_steps = [_without_io(s) for s in provided_steps]
            if not provided_steps:
                raise HTTPException(
                    status_code=400,
                    detail="expandedSteps was provided but no valid steps remained after normalization.",
                )
            raw_prompt = compose_expanded_steps_prompt(original_user_prompt, provided_steps)
            analysis_source = "llm"
            logger.info(
                "[stage0/start] using caller expandedSteps=%d projectId=%s",
                len(provided_steps),
                project_id,
            )
        else:
            try:
                from nl_builder.enterprise_expander import (
                    expand_prompt_to_enterprise_steps,
                    compose_expanded_steps_prompt,
                )
                expanded = await expand_prompt_to_enterprise_steps(
                    original_user_prompt,
                    api_key=api_key,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    project_id=project_id,
                )
                expander_warnings = list(expanded.warnings or [])
                if expanded.steps:
                    provided_steps = expanded.steps
                    raw_prompt = compose_expanded_steps_prompt(original_user_prompt, provided_steps)
                    analysis_source = "llm" if expanded.source == "llm" else "fallback"
                    logger.info(
                        "[stage0/start] NL enterprise expand steps=%d source=%s projectId=%s",
                        len(provided_steps),
                        expanded.source,
                        project_id,
                    )
                else:
                    expander_warnings.append(
                        "Enterprise step expansion unavailable; clarifying the original prompt."
                    )
                    analysis_source = "fallback"
            except BillingError as exc:
                raise HTTPException(
                    status_code=402,
                    detail=_billing_pause_error(
                        exc, workflow_id=project_id, subscriber_id=subscriber_id
                    ),
                ) from exc
            except Exception as exc:
                logger.warning("[stage0/start] enterprise expand failed, using raw prompt: %s", exc)
                expander_warnings.append(f"Enterprise step expansion failed: {exc}")
                analysis_source = "fallback"
    elif has_reports_only:
        # Dashboard-only session: no workflow steps exist yet, so raw_prompt is
        # only used for session bookkeeping/logging. Report planning MCQs below
        # are what actually drive clarification for this flow.
        raw_prompt = _dashboard_reports_to_prompt(request.suggestedReports)
        mode = "steps"
        analysis_source = None
        provided_steps = []
    else:
        raw_prompt = _stage0_steps_to_prompt(request.steps)
        mode = "steps"
        analysis_source = None
        provided_steps = _stage0_phases_to_logical_steps(request.steps)
        norm_steps, _ = _normalize_logical_steps(provided_steps, preserve_ids=True)
        provided_steps = norm_steps

    # ── Sub-Phase 0-A: Credential Check ───────────────────────────────────────
    cred_svc = CredentialService.optional()
    cred_result = await fetch_configured_secrets(
        project_id,
        db=None,
        credential_service=cred_svc,
        org_id=org_id,
        subscriber_id=subscriber_id,
    )

    session_id = f"stage0_{uuid.uuid4().hex[:12]}"
    saved_config_params = await persist_url_config_params(
        raw_prompt,
        credential_service=cred_svc,
        workflow_id=project_id,
        org_id=org_id,
        subscriber_id=subscriber_id,
    )
    if saved_config_params:
        cred_result = await fetch_configured_secrets(
            project_id,
            db=None,
            credential_service=cred_svc,
            org_id=org_id,
            subscriber_id=subscriber_id,
        )
    state = Stage0State(workflow_id=project_id, raw_prompt=raw_prompt, credential_check=cred_result)
    session = _Stage0Session(
        session_id=session_id,
        workflow_id=project_id,
        raw_prompt=raw_prompt,
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
        state=state,
        turn_count=1,
        workflow_name=workflow_name,
        mode=mode,
        analysis_source=analysis_source,
        provided_steps=provided_steps,
        expander_warnings=expander_warnings,
        original_user_prompt=original_user_prompt,
    )
    _init_session_report_planning(session, request.suggestedReports)
    await stage0_session_manager.create(session)

    if (
        session.report_planning is not None
        and report_planning_has_pending_input(session.report_planning)
    ):
        report_planning_out, execution_plan = _stage0_report_planning_fields(session)
        await stage0_session_manager.save(session)
        return Stage0Response(
            sessionId=session.session_id,
            status="needs_input",
            workflowId=session.workflow_id,
            workflowName=session.workflow_name,
            mode=session.mode,
            analysis_source=session.analysis_source,
            message=(
                "Suggested report planning started. "
                "Please answer the report configuration questions to continue."
            ),
            questions=_stage0_response_questions(session, []),
            credentialCheck=cred_result,
            detectedFlags=[],
            resolvedFlags=[],
            turnCount=session.turn_count,
            warnings=_stage0_report_planning_warnings(session),
            reportPlanning=report_planning_out,
            reportExecutionPlan=execution_plan,
            expandedSteps=_expanded_steps_out(session),
        )

    # ── Sub-Phase 0-B: First clarification turn ────────────────────────────────
    try:
        parsed = await run_stage0b_single_turn(
            raw_prompt=raw_prompt,
            configured_secret_names=cred_result.configured_secret_names,
            api_key=api_key,
            conversation_history=[],
            unresolved_flags=[],
            model=STAGE0_DEFAULT_MODEL,
            project_id=project_id,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )
    except BillingError as exc:
        await _checkpoint_stage0_pause(session=session, action="start", exc=exc)
        raise HTTPException(
            status_code=402,
            detail=_billing_pause_error(
                exc, workflow_id=project_id, subscriber_id=subscriber_id
            ),
        ) from exc
    except RuntimeError as exc:
        await stage0_session_manager.delete(session_id)
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return await _stage0_apply_b_turn(session, parsed, api_key=api_key)


# ── Collection Schema Inference Endpoint ──────────────────────────────────────

class SchemaInferRequest(BaseModel):
    """Request payload for /aiqod-agent/agent/collection-schema/infer.

    Accepts workflow steps and/or suggested reports to infer the MongoDB
    collection(s) and their schema (field name → type) that the workflow
    or dashboard will need.
    """
    steps: Optional[list] = None
    suggestedReports: Optional[list[dict[str, Any]]] = None
    orgId: Optional[str] = None
    subscriberId: Optional[str] = None


class SchemaInferResponse(BaseModel):
    collections: list[dict[str, Any]] = Field(
        default_factory=list,
        description=(
            "List of inferred collections, each with a `name` (collection name) "
            "and a `schema` dict mapping field names to their data types."
        ),
    )


_COLLECTION_SCHEMA_INFER_PROMPT = textwrap.dedent("""\
You are a data architect. Given a set of workflow steps and/or report definitions,
infer the MongoDB collection(s) and their schema that the application will need.

For each collection, provide:
- name: a meaningful collection name (snake_case, plural)
- schema: a dict where keys are field names (snake_case) and values are the
  most appropriate MongoDB data type (string, number, boolean, date, object, array, objectId)

Rules:
1. Only include collections that are clearly provided based on the input.
2. Use standard MongoDB types: string, number, boolean, date, objectId, object, array.
3. For fields that reference another collection, use type "objectId" and name the field
   with an "_id" suffix (e.g. "user_id").
4. Include at least an "_id" field of type "objectId" in every collection.
5. If a report describes aggregations or computed fields, include the source fields
   that would be needed in the source collection.

Return ONLY valid JSON in the following format (no markdown, no code fences):
{
  "collections": [
    {
      "name": "collection_name",
      "schema": {
        "_id": "objectId",
        "field1": "string",
        "field2": "number"
      }
    }
  ]
}

Workflow Steps:
{steps_text}

""")


async def _infer_collection_schema(
    steps: Optional[list],
    suggested_reports: Optional[list[dict[str, Any]]],
    api_key: str,
) -> list[dict[str, Any]]:
    """Call Gemini to infer collection schemas from steps and reports."""
    steps_text = "None provided"
    if steps:
        lines = []
        for i, step in enumerate(steps, start=1):
            name = step.get("name", f"Step {i}")
            desc = step.get("description", "")
            phase_type = step.get("phaseType", "")
            sub_steps = step.get("subSteps") or []
            sub_lines = []
            for j, sub in enumerate(sub_steps, start=1):
                sub_name = sub.get("name", f"SubStep {j}")
                sub_desc = sub.get("description", "")
                sub_kind = sub.get("preferredKind", "")
                sub_lines.append(f"    {j}. {sub_name} ({sub_kind}): {sub_desc}")
            subs_text = "\n".join(sub_lines) if sub_lines else "    (none)"
            lines.append(f"{i}. [{phase_type}] {name}: {desc}\n{subs_text}")
        steps_text = "\n".join(lines)

    reports_text = "None provided"
    if suggested_reports:
        lines = []
        for i, r in enumerate(suggested_reports, start=1):
            name = r.get("reportName", r.get("name", f"Report {i}"))
            rtype = r.get("reportType", "Tabular")
            desc = r.get("description", "")
            # Include any source/collection hints
            source = r.get("source", r.get("collection", ""))
            source_text = f" [source: {source}]" if source else ""
            lines.append(f"{i}. {name} ({rtype}){source_text}: {desc}")
        reports_text = "\n".join(lines)

    prompt = _COLLECTION_SCHEMA_INFER_PROMPT.replace(
        "{steps_text}", steps_text
    )

    response = await async_generate(
        "gemini-3.5-flash-lite",
        prompt,
        config=GeminiGenerateConfig(
            temperature=0.1,
            response_mime_type="application/json",
            response_schema=None,
            fallback_profile="planner",
        ),
        api_key=api_key,
    )

    # Try response.parsed first — the google-genai SDK already parses JSON
    # when response_mime_type="application/json" is set.
    try:
        parsed = response.parsed
        if isinstance(parsed, dict):
            collections = parsed.get("collections", [])
            return collections if isinstance(collections, list) else []
    except Exception:
        pass

    raw_text = ""
    try:
        raw_text = response.text or ""
    except Exception:
        pass

    if not raw_text or not raw_text.strip():
        return []

    try:
        repaired = repair_json(raw_text)
        # repair_json returns a parsed Python object when input is already
        # valid JSON, or a string when it needed to repair the text.
        if isinstance(repaired, (dict, list)):
            parsed = repaired
        else:
            parsed = json.loads(repaired)
    except Exception as exc:
        logger.error("_infer_collection_schema: failed to parse response. raw_text=%r, error=%s", raw_text, exc)
        return []

    collections = parsed.get("collections", []) if isinstance(parsed, dict) else []
    return collections


@app.post("/aiqod-agent/agent/collection-schema/infer", response_model=SchemaInferResponse)
async def collection_schema_infer(request: SchemaInferRequest, http_request: Request) -> SchemaInferResponse:
    """
    Infer MongoDB collection names and schemas from workflow steps and/or
    suggested report definitions using Gemini.

    Accepts:
      - steps: list of workflow phase/step objects (same shape as AgenticPlanRequest.steps)
      - suggestedReports: list of report definition objects

    Returns:
      { "collections": [ { "name": "...", "schema": { "field": "type", ... } }, ... ] }
    """
    api_key = _stage0_require_gemini_key()

    try:
        collections = await _infer_collection_schema(
            steps=request.steps,
            suggested_reports=request.suggestedReports,
            api_key=api_key,
        )
        return SchemaInferResponse(collections=collections)
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Schema inference failed: {str(exc)}",
        ) from exc


@app.post("/aiqod-agent/agent/stage0/respond", response_model=Stage0Response)
async def stage0_respond(request: Stage0RespondRequest) -> Stage0Response:
    """
    Continue Stage 0-B with the user's MCQ answer.

    QnA only — does not generate setup guidance. When clarification completes,
    returns RequirementSummary with empty config_guidance; call POST /stage0/guidance
    per flag when the user needs setup help.
    """
    session = await stage0_session_manager.get(request.sessionId)
    if session is None:
        raise HTTPException(status_code=404, detail="Stage 0 session not found or expired.")

    if session.state.stage0b_complete:
        raise HTTPException(
            status_code=400,
            detail={
                "error": "session_qna_complete",
                "message": (
                    "QnA is already complete for this session. "
                    "Use POST /stage0/guidance for setup help, or POST /stage0/start for a new session."
                ),
            },
        )

    answer = (request.answer or "").strip()
    if not answer and not request.skipRemaining:
        raise HTTPException(status_code=400, detail="answer must not be empty")

    if session.turn_count >= 10:
        raise HTTPException(status_code=400, detail="Stage 0-B maximum turn count (10) reached.")

    _init_agentic_workflow_billing(
        project_id=session.workflow_id,
        org_id=session.org_id,
        subscriber_id=session.subscriber_id,
        user_id=session.user_id,
    )
    if session.subscriber_id:
        set_workflow_agentic_status(
            db=db,
            workflow_id=session.workflow_id,
            subscriber_id=session.subscriber_id,
            org_id=session.org_id,
            user_id=session.user_id,
            status="stage0_in_progress",
        )

    if (
        session.report_planning is not None
        and report_planning_has_pending_input(session.report_planning)
    ):
        apply_report_planning_answer(session.report_planning, answer)
        session.turn_count += 1
        await stage0_session_manager.save(session)

        report_planning_out, execution_plan = _stage0_report_planning_fields(session)
        if _stage0_report_planning_blocks_stage0(session):
            return Stage0Response(
                sessionId=session.session_id,
                status="needs_input",
                workflowId=session.workflow_id,
                workflowName=session.workflow_name,
                mode=session.mode,
                analysis_source=session.analysis_source,
                message="Please continue resolving suggested report configuration.",
                questions=_stage0_response_questions(session, []),
                credentialCheck=session.state.credential_check,
                detectedFlags=_stage0_flags_to_out(session.state.detected_flags),
                resolvedFlags=_stage0_flags_to_out(session.state.resolved_flags),
                turnCount=session.turn_count,
                warnings=_stage0_report_planning_warnings(session),
                reportPlanning=report_planning_out,
                reportExecutionPlan=execution_plan,
                expandedSteps=_expanded_steps_out(session),
            )

        api_key = _stage0_require_gemini_key()
        state = session.state
        cred_result, _ = await _stage0_refresh_credentials(session)
        try:
            parsed = await run_stage0b_single_turn(
                raw_prompt=session.raw_prompt,
                configured_secret_names=cred_result.configured_secret_names,
                api_key=api_key,
                conversation_history=state.conversation_turns,
                unresolved_flags=critical_unresolved_flags(state.detected_flags),
                model=STAGE0_DEFAULT_MODEL,
                project_id=session.workflow_id,
                org_id=session.org_id,
                subscriber_id=session.subscriber_id,
                user_id=session.user_id,
            )
        except RuntimeError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc

        return await _stage0_apply_b_turn(
            session,
            parsed,
            api_key=api_key,
            skip_remaining=request.skipRemaining,
        )
    if session.subscriber_id:
        set_workflow_agentic_status(
            db=db,
            workflow_id=session.workflow_id,
            subscriber_id=session.subscriber_id,
            org_id=session.org_id,
            user_id=session.user_id,
            status="stage0_in_progress",
        )

    api_key = _stage0_require_gemini_key()
    state = session.state
    state.conversation_turns.append(Stage0Turn(role="user", content=answer or "Skip remaining"))
    session.turn_count += 1

    _resolve_configure_later_flags(state.pending_questions, answer, state.detected_flags)
    _resolve_delegated_flags(state.pending_questions, answer, state.detected_flags)
    saved_secrets = await _resolve_raw_value_flags(
        state.pending_questions,
        answer,
        state.detected_flags,
        credential_service=CredentialService.optional(),
        workflow_id=session.workflow_id,
        conversation_text="\n".join(t.content for t in state.conversation_turns if t.content),
        org_id=session.org_id,
        subscriber_id=session.subscriber_id,
    )
    state.resolved_flags = [f for f in state.detected_flags if f.resolved]

    # User may have added secrets in Configure Credentials while answering
    cred_result, newly_added = await _stage0_refresh_credentials(session)
    if saved_secrets:
        newly_added = list(dict.fromkeys(list(newly_added) + saved_secrets))
    unresolved_flags = critical_unresolved_flags(state.detected_flags)

    try:
        parsed = await run_stage0b_single_turn(
            raw_prompt=session.raw_prompt,
            configured_secret_names=cred_result.configured_secret_names,
            api_key=api_key,
            conversation_history=state.conversation_turns,
            unresolved_flags=unresolved_flags,
            newly_configured_secrets=newly_added,
            model=STAGE0_DEFAULT_MODEL,
            project_id=session.workflow_id,
            org_id=session.org_id,
            subscriber_id=session.subscriber_id,
            user_id=session.user_id,
        )
    except BillingError as exc:
        await _checkpoint_stage0_pause(
            session=session,
            action="respond",
            exc=exc,
            skip_remaining=request.skipRemaining,
        )
        raise HTTPException(
            status_code=402,
            detail=_billing_pause_error(
                exc,
                workflow_id=session.workflow_id,
                subscriber_id=session.subscriber_id,
            ),
        ) from exc
    except RuntimeError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return await _stage0_apply_b_turn(
        session,
        parsed,
        api_key=api_key,
        skip_remaining=request.skipRemaining,
    )


@app.post("/aiqod-agent/agent/stage0/guidance", response_model=Stage0GuidanceResponse)
async def stage0_guidance(request: Stage0GuidanceRequest) -> Stage0GuidanceResponse:
    """
    On-demand setup/configuration guidance for one requirement flag.

    Works during QnA (needs_input) and after QnA completes (status=complete).
    Does not increment turn_count, mutate conversation_turns, or resolve flags.
    Session remains available until the 30-minute TTL expires.
    """
    session = await stage0_session_manager.get(request.sessionId)
    if session is None:
        raise HTTPException(status_code=404, detail="Stage 0 session not found or expired.")

    _init_agentic_workflow_billing(
        project_id=session.workflow_id,
        org_id=session.org_id,
        subscriber_id=session.subscriber_id,
        user_id=session.user_id,
    )

    await _stage0_refresh_credentials(session)

    flag_key = request.flagKey.strip()

    if is_report_field_flag_key(flag_key):
        field_name = parse_report_field_from_flag_key(flag_key) or flag_key
        return Stage0GuidanceResponse(
            sessionId=request.sessionId,
            flagKey=flag_key,
            guidanceMarkdown=guidance_for_report_field(field_name),
            docLinks=[],
            credentialNames=[],
            source="template",
            dependencyType=f"report_{field_name}",
        )

    flag = next(
        (f for f in session.state.detected_flags if f.flag_type == flag_key),
        None,
    )
    if flag is None:
        flag = next(
            (f for f in session.state.detected_flags if f.flag_type.upper() == flag_key.upper()),
            None,
        )
    if flag is None:
        raise HTTPException(
            status_code=404,
            detail=f"Flag '{flag_key}' not found in session '{request.sessionId}'.",
        )

    api_key = _stage0_require_gemini_key()
    try:
        guidance: Stage0GuidanceResult = await run_stage0_guidance_turn(
            flag=flag,
            raw_prompt=session.raw_prompt,
            api_key=api_key,
            user_question=(request.userQuestion or "").strip() or None,
            model=STAGE0_DEFAULT_MODEL,
            project_id=session.workflow_id,
            org_id=session.org_id,
            subscriber_id=session.subscriber_id,
            user_id=session.user_id,
        )
    except BillingError as exc:
        await _checkpoint_stage0_pause(
            session=session,
            action="guidance",
            exc=exc,
            guidance_flag_key=flag.flag_type,
            guidance_user_question=(request.userQuestion or "").strip() or None,
        )
        raise HTTPException(
            status_code=402,
            detail=_billing_pause_error(
                exc,
                workflow_id=session.workflow_id,
                subscriber_id=session.subscriber_id,
            ),
        ) from exc
    except RuntimeError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return Stage0GuidanceResponse(
        sessionId=request.sessionId,
        flagKey=flag.flag_type,
        guidanceMarkdown=guidance.markdown,
        docLinks=guidance.doc_links,
        credentialNames=guidance.credential_names,
        source=guidance.source,
        dependencyType=guidance.dependency_type,
    )


class Stage0SessionStateOut(BaseModel):
    """Response for GET /stage0/session/{session_id} — session recovery."""
    sessionId: str
    status: Literal["needs_input", "complete", "expired"]
    workflowId: str
    workflowName: Optional[str]
    mode: Literal["prompt", "steps"]
    turnCount: int
    credentialCheck: Optional[CredentialCheckResult]
    detectedFlags: list[Stage0RequirementFlagOut]
    resolvedFlags: list[Stage0RequirementFlagOut]
    # The questions still pending (last turn's unanswered MCQs)
    pendingQuestions: list[Stage0MCQQuestionOut]
    # Full conversation so the frontend can re-render
    conversationHistory: list[dict[str, str]]
    requirementSummary: Optional[Stage0RequirementSummaryOut]
    warnings: list[str] = Field(default_factory=list)
    reportPlanning: Optional[Stage0ReportPlanningSummaryOut] = None
    reportExecutionPlan: Optional[str] = None


@app.get("/aiqod-agent/agent/stage0/session/{session_id}", response_model=Stage0SessionStateOut)
async def stage0_get_session(session_id: str) -> Stage0SessionStateOut:
    """
    Recovery endpoint — returns the full current state of a Stage 0 session.

    The frontend stores the sessionId in localStorage. On page refresh or resume,
    it calls this endpoint to re-render the conversation from where it left off.

    Returns HTTP 404 when the session does not exist or has expired (TTL 30 min).
    """
    session = await stage0_session_manager.get(session_id)
    if session is None:
        raise HTTPException(
            status_code=404,
            detail={
                "error": "session_not_found",
                "message": (
                    f"Stage 0 session '{session_id}' not found. "
                    "It may have expired (30-minute TTL). "
                    "Call /stage0/start to begin a new session."
                ),
            },
        )

    state = session.state

    # Reflect secrets the user may have added since the last turn (page refresh / recovery)
    await _stage0_refresh_credentials(session)
    await stage0_session_manager.save(session)

    # Last assistant turn's questions are the pending MCQs
    last_questions: list[Stage0MCQQuestionOut] = []
    for turn in reversed(state.conversation_turns):
        if turn.role == "assistant":
            # We don't store the questions themselves in Turn, but
            # detectedFlags / unresolved CRITICAL ones reflect what's pending
            break
    if session.report_planning is not None and report_planning_has_pending_input(session.report_planning):
        last_questions = _report_planning_questions_to_out(
            report_planning_questions_for_response(session.report_planning)
        )

    report_planning_out, execution_plan = _stage0_report_planning_fields(session)
    session_warnings = (
        state.requirement_summary.unresolved_warns if state.requirement_summary else []
    )
    session_warnings = list(session_warnings) + _stage0_report_planning_warnings(session)

    return Stage0SessionStateOut(
        sessionId=session.session_id,
        status="needs_input" if not state.stage0b_complete else "complete",
        workflowId=session.workflow_id,
        workflowName=session.workflow_name,
        mode=session.mode,
        turnCount=session.turn_count,
        credentialCheck=state.credential_check,
        detectedFlags=_stage0_flags_to_out(state.detected_flags),
        resolvedFlags=_stage0_flags_to_out([f for f in state.detected_flags if f.resolved]),
        pendingQuestions=last_questions,
        conversationHistory=[t.model_dump() for t in state.conversation_turns],
        requirementSummary=(
            _stage0_summary_to_out(state.requirement_summary)
            if state.requirement_summary
            else None
        ),
        warnings=session_warnings,
        reportPlanning=report_planning_out,
        reportExecutionPlan=execution_plan,
    )


