def _extract_tokens(name: str, fields: list) -> set:
    """Extract word tokens from collection name and field names."""
    tokens = set(name.lower().replace("_", " ").split())
    for f in fields:
        fname = f.get("name", "").lower()
        tokens.update(fname.replace("_", " ").split())
    # Remove empty strings if any
    return {t for t in tokens if t}

def _calculate_overlap(tokens_a: set, tokens_b: set) -> float:
    """Calculate Jaccard similarity between two token sets."""
    if not tokens_a or not tokens_b:
        return 0.0
    return len(tokens_a.intersection(tokens_b)) / len(tokens_a.union(tokens_b))
# -----------------------------

def _persist_collection_store_decisions(
    *,
    project_id: Optional[str],
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
    sources: list,
) -> None:
    """
    Save WHICH store (mongodb / arcadedb) was chosen for each collection, WHY, and WHO decided,
    in the same Project_Collections document the scratch preview writes (same tenant + projectId
    filter). Stored under its own key so the preview's $set of allCollections /
    collectionMetadata / kgSelectedCollections never overwrites it. Server-side only: it does
    not depend on the UI echoing anything back. Merges by collection name across calls.
    """
    if not project_id or not sources:
        return
    tenant: Dict[str, Any] = {}
    for key, raw in (("orgId", org_id), ("subscriberId", subscriber_id), ("userId", user_id)):
        if raw is None:
            continue
        try:
            tenant[key] = ObjectId(raw) if isinstance(raw, str) else raw
        except Exception:
            tenant[key] = raw
    flt = {**tenant, "projectId": project_id}
    now = datetime.utcnow()
    coll = db["Project_Collections"]

    existing = coll.find_one(flt, {"collectionStoreDecisions": 1}) or {}
    merged: Dict[str, Any] = {
        d.get("collection"): d for d in (existing.get("collectionStoreDecisions") or []) if d.get("collection")
    }
    for src in sources:
        name = src.get("requested_name")
        if not name:
            continue
        merged[name] = {
            "collection": name,
            "target_store": src.get("target_store") or "mongodb",
            "target_store_reason": src.get("target_store_reason") or "",
            "decided_by": src.get("target_store_decided_by") or "llm_arbiter",
            "description": (
                "" if src.get("target_store_decided_by") == "registry"
                else str(src.get("description") or "")[:300]
            ),
            "user_decision": src.get("user_decision"),
            "is_kg_required": bool(src.get("is_kg_required")),
            "is_merge_suggested": bool(src.get("is_merge_suggested")),
            "merge_target": src.get("merge_target"),
            "decided_at": now,
        }
    coll.update_one(
        flt,
        {
            "$set": {
                **tenant,
                "projectId": project_id,
                "updated_at": now,
                "collectionStoreDecisions": list(merged.values()),
            },
            "$setOnInsert": {"created_at": now},
        },
        upsert=True,
    )


@app.post("/aiqod-agent/agent/agentic/plan/knowledge-sources")
async def get_knowledge_sources(request: AgenticPlanRequest, http_request: Request):
    org_id = request.orgId or http_request.headers.get("x-org-id") or http_request.headers.get("selectedorgid")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")

    # 1. Fast Extraction from Stage 0 Handoff
    requested_schemas_rich = []
    if getattr(request, "stage0Handoff", None):
        summary = request.stage0Handoff.get("requirementSummary", {})
        db_schemas = summary.get("db_schemas", [])
        for schema in db_schemas:
            if schema.get("collection_name"):
                requested_schemas_rich.append(schema)

    if not requested_schemas_rich:
        return {"success": True, "data": []}

    def _build_source(
        c_name: str, schema_def: dict, description: str, is_kg_required: bool,
        is_merge_suggested: bool = False, merge_target: Optional[str] = None,
        label_suffix: str = "New Schema", target_store: str = "mongodb",
        target_store_reason: str = "", target_store_decided_by: str = "llm_arbiter",
    ) -> dict:
        return {
            "id": f"eg_{c_name}",
            "type": "enterprise_graph",
            "requested_name": c_name,
            "name": f"{c_name} [{label_suffix}]",
            "description": description,
            "schemaMetadata": schema_def,
            "is_kg_required": is_kg_required,
            "is_merge_suggested": is_merge_suggested,
            "merge_target": merge_target,
            "target_store": target_store,
            "target_store_reason": target_store_reason,
            "target_store_decided_by": target_store_decided_by,
            "user_decision": (schema_def or {}).get("user_decision"),
        }

    # 2. Fetch Existing Inventory WITH FIELDS from ArcadeDB
    existing_schemas_rich = {}
    if subscriber_id and org_id:
        try:
            from repositories.arcadedb_repository import EnterpriseGraphRepository
            repo = EnterpriseGraphRepository()
            
            existing_names = await repo.list_all_collections(subscriber_id, org_id)
            if existing_names:
                existing_schemas_rich = await repo.get_schemas_for_collections(subscriber_id, org_id, existing_names)
                # Registry rows also carry graph labels/relationships/group as pseudo-fields;
                # keep only real properties for the overlap scoring and the LLM arbiter.
                from services.entity_resolver import split_schema_fields
                existing_schemas_rich = {
                    c: split_schema_fields(f)["props"] for c, f in existing_schemas_rich.items()
                }
                
        except Exception as e:
            logger.warning(f"Enterprise Graph check failed: {e}")

    sources = []
    collections_for_merge_prompt = []
    collections_for_kg_only_prompt = []
    candidate_schemas_for_llm = {}

    # 2b. Schemas Stage 0 already bound to EXISTING data are not "new": skip the MERGE/CREATE
    #     arbiter entirely and keep the registry's target_store (authoritative, no guessing).
    bound_existing = [s for s in requested_schemas_rich if s.get("existing")]
    if bound_existing:
        requested_schemas_rich = [s for s in requested_schemas_rich if not s.get("existing")]
        for s in bound_existing:
            sources.append(_build_source(
                c_name=s["collection_name"],
                schema_def=s,
                description="Existing data reused (bound during requirement clarification).",
                is_kg_required=True,
                label_suffix="Existing",
                target_store=s.get("target_store") or "mongodb",
                target_store_reason=(
                    "Reused existing data: the store was inherited from the schema registry "
                    "(where this entity was originally saved), not re-decided."
                ),
                target_store_decided_by="registry",
            ))
            logger.info(
                "[KnowledgeSources:Bound] %s reused as-is (target_store=%s)",
                s["collection_name"], s.get("target_store") or "mongodb",
            )

    # 3. Candidate Pre-Filtering (Token Overlap)
    if existing_schemas_rich:
        ext_tokens_map = {
            c_name: _extract_tokens(c_name, fields)
            for c_name, fields in existing_schemas_rich.items()
        }

        for req_schema in requested_schemas_rich:
            req_name = req_schema.get("collection_name")
            req_fields = req_schema.get("fields", [])
            if req_schema.get("user_decision") == "new":
                logger.info(
                    "[KnowledgeSources:Route] '%s': the user already chose to create a new collection "
                    "-> KG-ONLY (no merge suggestion)", req_name,
                )
                collections_for_kg_only_prompt.append(req_schema)
                continue
            req_tokens = _extract_tokens(req_name, req_fields)

            scores = []
            for ext_name, ext_tokens in ext_tokens_map.items():
                score = _calculate_overlap(req_tokens, ext_tokens)
                if score > 0:
                    scores.append((score, ext_name))

            # Sort scores and log the raw results
            scores.sort(key=lambda x: x[0], reverse=True)
            logger.info(f"[KnowledgeSources:Score] '{req_name}' overlap scores: {scores}")

            # Apply threshold and Top 8
            OVERLAP_THRESHOLD = 0.10
            top_candidates = [s for s in scores[:8] if s[0] >= OVERLAP_THRESHOLD]

            if top_candidates:
                logger.info(f"[KnowledgeSources:Route] '{req_name}' >= threshold ({OVERLAP_THRESHOLD}). Selected for MERGE check: {top_candidates}")
                collections_for_merge_prompt.append(req_schema)
                for _, ext_name in top_candidates:
                    candidate_schemas_for_llm[ext_name] = existing_schemas_rich[ext_name]
            else:
                max_score = scores[0][0] if scores else 0.0
                logger.info(f"[KnowledgeSources:Route] '{req_name}' max score ({max_score:.4f}) < threshold ({OVERLAP_THRESHOLD}). Routing to KG-ONLY check (Auto-CREATE).")
                collections_for_kg_only_prompt.append(req_schema)
    else:
        collections_for_kg_only_prompt = requested_schemas_rich

    # 4. LLM Arbiter: Merge & KG Evaluation (For collections with merge candidates)
    if collections_for_merge_prompt and candidate_schemas_for_llm:
        logger.info(f"[KnowledgeSources:LLM] Initiating MERGE + KG Arbiter call. Requested: {len(collections_for_merge_prompt)} | Candidates sent to LLM: {len(candidate_schemas_for_llm)}")
        req_json = json.dumps(collections_for_merge_prompt, indent=2)
        ext_json = json.dumps(candidate_schemas_for_llm, indent=2)

        prompt = f"""
        You are a Database Administrator.
        Requested NEW collections: {req_json}
        EXISTING candidate collections: {ext_json}
        
        TASK 1: Evaluate each requested collection against the existing collections. 
        Output "MERGE" if they represent the same core business entity. Output "CREATE" if fundamentally different.
        
        TASK 2: Evaluate if this data should be persisted in the Enterprise Data Catalog.
        CRITICAL RULE: Ignore the collection name. Look ONLY at the schema fields.
        
        Evaluate the fields using this strict binary classification:
        1. BUSINESS ENTITY (is_kg_required = true): The fields represent a distinct business concept, master data, configuration, tracking event, or actor.
        2. SYSTEM PLUMBING (is_kg_required = false): The fields represent purely technical, internal application state.
        
        TASK 3: Determine `target_store`. Set to "mongodb" if the collection represents independent documents, transactions, logs, or 1-hop relations. Set to "arcadedb" ONLY if the primary purpose is N-hop graph traversals for networks or hierarchies.
        Also fill `target_store_reason` with exactly ONE sentence justifying the `target_store` choice: cite the concrete
        evidence (specific field names or the access pattern, e.g. parent/child id fields needing multi-hop traversal, or plain
        independent records) and say briefly why the other store was rejected. Do not repeat the text of `reason`.
        
        Identify the core concept the fields represent in `example_user_question` (e.g., "Represents: Customer Identification").
        Then set `is_kg_required` strictly based on the classification above, and briefly state why in `reason`.
        
        Provide exactly 1 short sentence explaining your business reasoning in `reason`.
        """
        
        try:
            cfg = GeminiGenerateConfig(temperature=0.1, response_mime_type="application/json", response_schema=SchemaResolution)
            resp = await async_generate("gemini-3.5-flash-lite", prompt, config=cfg, api_key=get_gemini_api_key())
            
            if resp.parsed:
                for dec in resp.parsed.resolutions:
                    schema_def = next((s for s in requested_schemas_rich if s.get("collection_name") == dec.requested_collection), {})
                    is_merge = dec.decision.upper() == "MERGE"

                    sources.append(_build_source(
                        c_name=dec.requested_collection,
                        schema_def=schema_def,
                        description=f"Q: {dec.example_user_question} | Reason: {dec.reason}",
                        is_kg_required=dec.is_kg_required,
                        is_merge_suggested=is_merge,
                        merge_target=dec.existing_collection_to_merge_with if is_merge else None,
                        label_suffix=("MERGING with " + dec.existing_collection_to_merge_with) if is_merge else "New Schema",
                        target_store=dec.target_store,
                        target_store_reason=dec.target_store_reason,
                    ))
        except Exception as e:
            logger.warning(f"LLM Arbiter failed, falling back: {e}")
            collections_for_kg_only_prompt.extend(collections_for_merge_prompt) # Push to fallback

    # 5. LLM Arbiter: KG Evaluation Only (For auto-creates with 0 overlap)
    if collections_for_kg_only_prompt:
        kg_names = [s.get("collection_name") for s in collections_for_kg_only_prompt]
        logger.info(f"[KnowledgeSources:LLM] Initiating KG-ONLY call (standalone check) for {len(kg_names)} collection(s): {kg_names}")
        req_json = json.dumps(collections_for_kg_only_prompt, indent=2)

        prompt = f"""
        You are a Database Administrator evaluating NEW database collections
        identified from workflow requirements: {req_json}

        Evaluate whether each collection's data would be valuable to store in a Knowledge Graph 
        for use by a Virtual Assistant or dashboard analytics.
        
        CRITICAL RULE: You MUST ignore the collection name. Look ONLY at the schema fields.
        First, write a concrete `example_user_question` a business user could ask that these fields would answer.
        If you can write a valid analytical question based on the fields, set `is_kg_required` to true. If the fields are purely internal/technical state with no analytical value, set it to false.

        TASK 2: Determine `target_store`. Set to "mongodb" if the collection represents independent documents, transactions, logs, or 1-hop relations. Set to "arcadedb" ONLY if the primary purpose is N-hop graph traversals for networks or hierarchies.
        Also fill `target_store_reason` with exactly ONE sentence justifying the `target_store` choice: cite the concrete
        evidence (specific field names or the access pattern, e.g. parent/child id fields needing multi-hop traversal, or plain
        independent records) and say briefly why the other store was rejected. Do not repeat the text of `reason`.

        Provide exactly 1 short sentence explaining your reasoning in `reason`.
        """

        try:
            cfg = GeminiGenerateConfig(temperature=0.1, response_mime_type="application/json", response_schema=SchemaKgOnlyResolution)
            resp = await async_generate("gemini-3.5-flash-lite", prompt, config=cfg, api_key=get_gemini_api_key())

            if resp.parsed:
                for dec in resp.parsed.resolutions:
                    schema_def = next((s for s in requested_schemas_rich if s.get("collection_name") == dec.requested_collection), {})

                    sources.append(_build_source(
                        c_name=dec.requested_collection,
                        schema_def=schema_def,
                        description=f"Q: {dec.example_user_question} | Reason: {dec.reason}",
                        is_kg_required=dec.is_kg_required,
                        target_store=dec.target_store,
                        target_store_reason=dec.target_store_reason,
                    ))
        except Exception as e:
            logger.warning(f"LLM Arbiter (KG-only) failed, falling back to simple logic: {e}")
            for req in collections_for_kg_only_prompt:
                c_name = req.get("collection_name")
                sources.append(_build_source(
                    c_name=c_name, schema_def=req,
                    description="Database collection identified from workflow requirements.",
                    is_kg_required=True, label_suffix="New Schema (Will Create)",
                    target_store="mongodb",
                    target_store_reason="Store arbiter was unavailable; defaulted to mongodb (platform default).",
                    target_store_decided_by="fallback_default",
                ))

    try:
        await asyncio.to_thread(
            _persist_collection_store_decisions,
            project_id=request.projectId,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            sources=sources,
        )
    except Exception as exc:  # audit trail must never break the response
        logger.warning("[KnowledgeSources] could not persist store decisions: %s", exc)

    return {"success": True, "data": sources}

def _logical_steps_from_nl_plan_steps(raw_steps: Any) -> list:
    """Normalize NL plan step dicts / models into LogicalStep list."""
    out: list[LogicalStep] = []
    for i, s in enumerate(raw_steps or [], start=1):
        if isinstance(s, LogicalStep):
            out.append(s)
            continue
        raw = s.model_dump(mode="json") if hasattr(s, "model_dump") else dict(s or {})
        kind = raw.get("preferredKind")
        if kind not in ("ui_screen", "tool", "agent", None):
            kind = None
        try:
            out.append(
                LogicalStep(
                    stepId=str(raw.get("stepId") or f"L{i}"),
                    name=str(raw.get("name") or f"Step {i}"),
                    description=str(raw.get("description") or raw.get("name") or f"Step {i}"),
                    inputs=list(raw.get("inputs") or []),
                    outputs=list(raw.get("outputs") or []),
                    preferredKind=kind,
                )
            )
        except Exception as exc:
            logger.warning("[scratch/preview] skipped invalid handoff step %s: %s", i, exc)
            continue
    return out


async def _resolve_prompt_preview_steps(
    *,
    prompt: str,
    stage0_planner_context: str,
    handoff_steps: list,
    api_key: Optional[str],
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
    project_id: Optional[str],
    warnings: list[str],
) -> tuple[list, Literal["llm", "fallback"]]:
    """
    Prompt-mode preview steps — same idea as steps mode sending `steps` in the body.
    Prefer requirementSummary.steps from stage0Handoff (or request.expandedSteps).
    Only expand the prompt when those lists are empty — never overwrite a
    caller/Stage-0 step list just because it has fewer than 6 items.
    """
    from nl_builder.enterprise_expander import (
        MIN_ENTERPRISE_STEPS,
        attach_stage0_clarifications,
        expand_prompt_to_enterprise_steps,
        logical_steps_to_scratch_dicts,
    )

    steps = _logical_steps_from_nl_plan_steps(handoff_steps)
    source: Literal["llm", "fallback"] = "llm" if steps else "fallback"
    if steps:
        if len(steps) < MIN_ENTERPRISE_STEPS:
            warnings.append(
                f"Using {len(steps)} handoff step(s) (< {MIN_ENTERPRISE_STEPS}); "
                "not re-expanding because the caller already supplied a step list."
            )
    else:
        warnings.append(
            "No enterprise steps on stage0Handoff.requirementSummary.steps; "
            "expanding the original prompt."
        )
        expanded = await expand_prompt_to_enterprise_steps(
            prompt,
            api_key=api_key,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            project_id=project_id,
        )
        warnings.extend(expanded.warnings or [])
        if expanded.steps:
            steps = expanded.steps
            source = "llm" if expanded.source == "llm" else "fallback"
    dicts = attach_stage0_clarifications(
        logical_steps_to_scratch_dicts(steps),
        stage0_planner_context,
    )
    return _logical_steps_from_nl_plan_steps(dicts) or steps, source


@app.post("/aiqod-agent/agent/agentic/plan/scratch/preview", response_model=AgenticPlanPreviewResponse)
async def agentic_plan_scratch_preview(request: AgenticPlanRequest, http_request: Request) -> AgenticPlanPreviewResponse:
    """
    Dedicated preview endpoint for the scratch graph planner.

    Same for both modes — send the work in the body + optional stage0Handoff:
      - **steps:** ``{steps, stage0Handoff?}``
      - **prompt:** ``{prompt, stage0Handoff?}`` — uses ``requirementSummary.steps``
        (enterprise expansion from Stage 0 complete)

    Returns AgenticPlanPreviewResponse so /agentic/plan/execute can consume phaseGraphs.
    """
    api_key = get_gemini_api_key()

    org_id = request.orgId or http_request.headers.get("x-org-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")

    has_prompt = bool(request.prompt and request.prompt.strip())
    has_steps = bool(request.steps)
    explicit_mode = request.mode

    if has_prompt == has_steps:
        raise HTTPException(
            status_code=400,
            detail="Exactly one of 'prompt' (non-empty) or 'steps' must be provided.",
        )
    if explicit_mode == "prompt" and not has_prompt:
        raise HTTPException(status_code=400, detail="mode='prompt' requires a non-empty prompt.")
    if explicit_mode == "steps" and not has_steps:
        raise HTTPException(status_code=400, detail="mode='steps' requires a non-empty steps array.")

    def _tenant_query() -> Dict[str, Any]:
        q: Dict[str, Any] = {}
        for key, raw in (
            ("orgId", org_id),
            ("subscriberId", subscriber_id),
            ("userId", user_id),
        ):
            if raw is None:
                continue
            try:
                q[key] = ObjectId(raw) if isinstance(raw, str) else raw
            except Exception:
                q[key] = raw
        return q

    engine_type = "agentic_graph"
    process_id = request.projectId or f"agentic_{generate_numeric_id()}"
    workflow_name = request.selectedName or "workflow"
    all_warnings: list[str] = []

    _init_agentic_workflow_billing(
        project_id=process_id,
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
    )
    if subscriber_id:
        set_workflow_agentic_status(
            db=db,
            workflow_id=process_id,
            subscriber_id=subscriber_id,
            org_id=org_id,
            user_id=user_id,
            status="building",
        )

    stage0_planner_context = ""
    if request.stage0Handoff:
        try:
            handoff = Stage0HandoffRequest.model_validate(request.stage0Handoff)
            stage0_planner_context = _build_stage0_planner_context(handoff)
            logger.info(
                "[scratch/preview] Stage 0 handoff applied (%d chars planner context)",
                len(stage0_planner_context),
            )
        except Exception as exc:
            logger.warning("[scratch/preview] Invalid stage0Handoff — ignored: %s", exc)
            all_warnings.append(f"stage0Handoff ignored: {exc}")

    if request.suggestedReports:
        report_schema: dict[str, Any] = {}
        if request.stage0Handoff:
            try:
                handoff = Stage0HandoffRequest.model_validate(request.stage0Handoff)
                report_schema = build_available_schema_from_db_schemas(
                    handoff.requirementSummary.db_schemas
                )
            except Exception:
                pass
        report_snapshot = validate_suggested_reports(
            request.suggestedReports,
            available_schema=report_schema or None,
        )
        if report_snapshot.get("status") != "complete":
            summary = report_snapshot.get("summary") or {}
            all_warnings.append(
                "Suggested reports require planning via Stage 0 before preview: "
                f"{summary.get('planned', 0)}/{summary.get('total', 0)} planned."
            )
        all_warnings.extend(report_snapshot.get("summary", {}).get("warnings") or [])

    # ── Resolve logical steps + define phases ────────────────────────────────
    phases_info: list[tuple[str, str, str, list[LogicalStep], str]] = []

    if has_prompt:
        logger.info("[scratch/preview] prompt-mode: %s", request.prompt.strip()[:200])
        handoff_steps: list = []
        if request.stage0Handoff:
            try:
                handoff_steps = list(
                    Stage0HandoffRequest.model_validate(request.stage0Handoff).requirementSummary.steps or []
                )
            except Exception:
                handoff_steps = []
        if not handoff_steps and request.expandedSteps:
            handoff_steps = list(request.expandedSteps)
            all_warnings.append(
                "Preview used request.expandedSteps because stage0Handoff had no steps."
            )
        try:
            prompt_steps, analysis_source = await _resolve_prompt_preview_steps(
                prompt=request.prompt.strip(),
                stage0_planner_context=stage0_planner_context,
                handoff_steps=handoff_steps,
                api_key=api_key,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                project_id=process_id,
                warnings=all_warnings,
            )
        except BillingError as exc:
            if subscriber_id:
                early_ctx: Dict[str, Any] = {
                    "process_id": process_id,
                    "workflow_name": workflow_name,
                    "mode": "prompt",
                    "prompt": request.prompt.strip(),
                    "project_id_for_gen": process_id,
                    "stage0_planner_context": stage0_planner_context,
                    "selectedName": request.selectedName,
                    "selectedType": request.selectedType,
                    "selectedCategory": request.selectedCategory,
                    "token": request.token,
                    "phases_info": [],
                }
                write_checkpoint(
                    db=db,
                    workflow_id=process_id,
                    subscriber_id=subscriber_id,
                    org_id=org_id,
                    user_id=user_id,
                    status="paused_credit",
                    pipeline_stage="preview",
                    phase_index=0,
                    phase_total=1,
                    request_context=early_ctx,
                    last_error={
                        "code": exc.code,
                        "phase_id": "phase_1",
                        "at": datetime.utcnow().isoformat(),
                    },
                    warnings=all_warnings,
                )
                set_workflow_agentic_status(
                    db=db,
                    workflow_id=process_id,
                    subscriber_id=subscriber_id,
                    org_id=org_id,
                    user_id=user_id,
                    status="paused_credit",
                )
            _pause_detail = _billing_pause_error(
                exc, workflow_id=process_id, subscriber_id=subscriber_id
            )
            await _publish_paused_credit(process_id, _pause_detail)
            raise HTTPException(
                status_code=402,
                detail=_pause_detail,
            ) from exc
        if not prompt_steps:
            raise HTTPException(
                status_code=400,
                detail="Prompt-mode preview needs stage0Handoff.requirementSummary.steps (or expander output).",
            )
        logger.info("[scratch/preview] prompt-mode logical steps=%d source=%s", len(prompt_steps), analysis_source)
        phases_info.append((
            "phase_1",
            workflow_name,
            request.prompt.strip(),
            prompt_steps,
            "FREEZE",
        ))
        mode: Literal["prompt", "steps"] = "prompt"
        all_steps_flat = prompt_steps
    else:
        mode = "steps"
        analysis_source = None
        all_steps_flat: list[LogicalStep] = []
        idx = 1

        for phase in (request.steps or []):
            phase_steps: list[LogicalStep] = []
            phase_desc = phase.description or phase.name

            if phase.subSteps:
                for sub in phase.subSteps:
                    # Only "ui_screen"/"tool" are meaningful constraints for scratch planner.
                    sub_kind = sub.preferredKind if sub.preferredKind in ("ui_screen", "tool") else None
                    ls = LogicalStep(
                        stepId=sub.stepId or f"L{idx}",
                        name=sub.name,
                        description=sub.description,
                        inputs=[],
                        outputs=[],
                        preferredKind=sub_kind,
                    )
                    phase_steps.append(ls)
                    idx += 1
            else:
                phase_steps.append(LogicalStep(
                    stepId=phase.stepId or f"L{idx}",
                    name=phase.name,
                    description=phase_desc,
                    inputs=[],
                    outputs=[],
                    preferredKind=None,
                ))
                idx += 1

            norm_steps, phase_warns = _normalize_logical_steps(phase_steps, preserve_ids=True)
            all_warnings.extend(phase_warns)
            all_steps_flat.extend(norm_steps)
            phases_info.append((phase.stepId, phase.name, phase_desc, norm_steps, phase.phaseType))

    # ── Auto-create dashboard phase from suggestedReports ─────────────────────
    # If suggestedReports is provided and non-empty, create a dedicated dashboard
    # phase with one ui_screen substep per report, merged as the last phase.
    if request.suggestedReports and not has_prompt:
        dashboard_steps: list[LogicalStep] = []
        for i, report in enumerate(request.suggestedReports):
            report_name = report.get("reportName", f"Report {i + 1}")
            report_desc = report.get("description", "")
            report_type = report.get("reportType", "Tabular")
            required_fields: list[str] = report.get("requiredFields", [])
            optional_filters: list[str] = report.get("optionalFilters", [])
            aggregation = report.get("aggregation")

            parts = [report_desc]
            if required_fields:
                parts.append(f"Required fields: {', '.join(required_fields)}")
            if optional_filters:
                parts.append(f"Optional filters: {', '.join(optional_filters)}")
            if aggregation:
                parts.append(f"Aggregation: {aggregation}")
            parts.append(f"Report type: {report_type}")
            enriched_desc = "\n".join(parts)

            ls = LogicalStep(
                stepId=f"report_{i + 1}",
                name=report_name,
                description=enriched_desc,
                inputs=[],
                outputs=[],
                preferredKind="ui_screen",
            )
            dashboard_steps.append(ls)
            idx += 1

        if dashboard_steps:
            norm_dashboard, dash_warns = _normalize_logical_steps(dashboard_steps, preserve_ids=True)
            all_warnings.extend(dash_warns)
            all_steps_flat.extend(norm_dashboard)
            phases_info.append((
                "phase_dashboard",
                "Dashboard Reports",
                "Dashboard screen displaying all configured reports",
                norm_dashboard,
                "FREEZE",
            ))
            logger.info(
                "[scratch/preview] Auto-created dashboard phase with %d report step(s) from suggestedReports",
                len(dashboard_steps),
            )
    project_id_for_gen = request.projectId or generate_screen_id("project")
    phase_results: list[PhaseGraphResult] = []
    prior_phase_outputs: dict = {}
    workflow_registry: dict = {}

    preview_request_context: Dict[str, Any] = {
        "process_id": process_id,
        "workflow_name": workflow_name,
        "mode": mode,
        "analysis_source": analysis_source,
        "project_id_for_gen": project_id_for_gen,
        "stage0_planner_context": stage0_planner_context,
        "selectedName": request.selectedName,
        "selectedType": request.selectedType,
        "selectedCategory": request.selectedCategory,
        "token": request.token,
        "prompt": request.prompt,
        "allCollections": request.allCollections or [],
        "collectionMetadata": request.collectionMetadata or [],
        "kgSelectedCollections": request.kgSelectedCollections or [],
        "phases_info": [
            {
                "phaseId": pid,
                "phaseName": pname,
                "phaseDescription": pdesc,
                "phaseType": ptype,
                "steps": [s.model_dump() for s in (psteps or [])],
            }
            for pid, pname, pdesc, psteps, ptype in phases_info
        ],
    }
    last_scratch_checkpoint: Optional[dict] = None

    async def _write_preview_build_checkpoint(
        *,
        status: str,
        phase_index: int,
        scratch_state: Optional[dict] = None,
        last_error: Optional[dict] = None,
    ) -> None:
        if not subscriber_id:
            return
        try:
            await asyncio.to_thread(
                write_checkpoint,
                db=db,
                workflow_id=process_id,
                subscriber_id=subscriber_id,
                org_id=org_id,
                user_id=user_id,
                status=status,
                pipeline_stage="preview",
                phase_index=phase_index,
                phase_total=len(phases_info),
                phase_graphs=_serialize_phase_graph_results(phase_results),
                prior_phase_outputs=prior_phase_outputs,
                workflow_registry=workflow_registry,
                scratch_state=scratch_state,
                request_context=preview_request_context,
                last_error=last_error,
                warnings=all_warnings,
            )
            if status == "paused_credit":
                await asyncio.to_thread(
                    set_workflow_agentic_status,
                    db=db,
                    workflow_id=process_id,
                    subscriber_id=subscriber_id,
                    org_id=org_id,
                    user_id=user_id,
                    status="paused_credit",
                )
        except Exception as exc:
            logger.warning(
                "[scratch/preview] Checkpoint write failed (non-fatal): %s", exc
            )
            all_warnings.append(f"Checkpoint write failed (preview still returned): {exc}")

    async def _scratch_gap_resolver(graph_dict: Dict[str, Any]) -> Dict[str, Any]:
        graph_model = GraphDefinition(**graph_dict)
        updated_graph, _ = await _resolve_gap_generations(
            graph_model,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            project_id=project_id_for_gen,
            available_credentials=None,
        )
        return updated_graph.model_dump()

    # ── Per-phase scratch graph planning (no gap resolution) ──────────────────
    try:
        for phase_index, (phase_id, phase_name, phase_desc, phase_steps, phase_type) in enumerate(phases_info):
            phase_warnings: list[str] = []
            logger.info(f"[scratch/preview] Phase {phase_id}: planning graph (phaseType={phase_type})")
            if prior_phase_outputs:
                _log_binding_audit(
                    "scratch_preview_prior_phase_in",
                    phaseId=phase_id,
                    priorOutputNodes=len(prior_phase_outputs),
                    priorOutputs={
                        nid: entries for nid, entries in prior_phase_outputs.items()
                    },
                )

            async def _preview_checkpoint(
                state,
                sub_stage: str,
                batch_index: Optional[int] = None,
                router_id: Optional[str] = None,
                completed_router_results: Optional[list] = None,
                *,
                _phase_index: int = phase_index,
                _phase_id: str = phase_id,
            ):
                nonlocal last_scratch_checkpoint
                scratch_payload = {
                    "phase_id": _phase_id,
                    "sub_stage": sub_stage,
                    "batch_index": batch_index,
                    "router_id": router_id,
                    "completed_router_results": completed_router_results,
                    "state_snapshot": state.model_dump(mode="json"),
                }
                last_scratch_checkpoint = scratch_payload
                await _write_preview_build_checkpoint(
                    status="building",
                    phase_index=_phase_index,
                    scratch_state=scratch_payload,
                )

            try:
                scratch_dict = await plan_phase_graph_scratch(
                    phase_id=phase_id,
                    phase_name=phase_name,
                    phase_description=phase_desc,
                    steps=phase_steps,
                    prior_phase_outputs=prior_phase_outputs or None,
                    workflow_registry=workflow_registry or None,
                    stage0_context=stage0_planner_context or None,
                    api_key=api_key,
                    project_id=project_id_for_gen,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    run_gap_resolution=False,
                    run_code_emission=False,
                    gap_resolver=_scratch_gap_resolver,
                    checkpoint_fn=_preview_checkpoint,
                    collection_metadata=request.collectionMetadata
                )
                scratch_warnings = scratch_dict.pop("_planningWarnings", [])
                scratch_dict.pop("_stateSchema", None)
                scratch_dict.pop("_langgraphCode", None)
                workflow_registry = scratch_dict.pop("_workflowRegistry", workflow_registry) or workflow_registry
                phase_warnings.extend(scratch_warnings)
                graph = GraphDefinition(**scratch_dict)
                _log_binding_audit(
                    "scratch_preview_phase_planned",
                    phaseId=phase_id,
                    graphId=graph.graphId,
                    bindings=_summarize_graph_definition_bindings(graph),
                    requiredGlobalInputs=getattr(graph, "requiredGlobalInputs", []) or [],
                )
            except BillingError as exc:
                scratch_err: Dict[str, Any] = {
                    "code": exc.code,
                    "phase_id": phase_id,
                    "at": datetime.utcnow().isoformat(),
                }
                if last_scratch_checkpoint:
                    for key in ("sub_stage", "batch_index", "router_id"):
                        val = last_scratch_checkpoint.get(key)
                        if val is not None:
                            scratch_err[key] = val
                await _write_preview_build_checkpoint(
                    status="paused_credit",
                    phase_index=phase_index,
                    scratch_state=last_scratch_checkpoint,
                    last_error=scratch_err,
                )
                _pause_detail = _billing_pause_error(
                    exc, workflow_id=process_id, subscriber_id=subscriber_id
                )
                await _publish_paused_credit(process_id, _pause_detail)
                raise HTTPException(
                    status_code=402,
                    detail=_pause_detail,
                ) from exc
            except Exception as e:
                logger.warning(f"[scratch/preview] Scratch graph planner failed for phase '{phase_id}': {e}")
                raise HTTPException(
                    status_code=503,
                    detail={
                        "success": False,
                        "error": "scratch_graph_planner_unavailable",
                        "message": "Scratch graph planner was unavailable; preview cannot proceed safely.",
                        "phaseId": phase_id,
                        "phaseName": phase_name,
                        "retryable": True,
                        "provider_error": str(e),
                    },
                )

            # The scratch planner already runs its own staged validation:
            # Stage 1 skeleton validation, Stage 2b path-aware binding validation,
            # Stage 3b per-router condition validation, and Stage 4b final graph checks.
            # Do not run the generic capability-planner repair loop here; it can
            # mutate a scratch graph after those path-aware invariants were enforced.
            total_fixes = 0
            logger.info(
                f"[scratch/preview] Phase {phase_id}: "
                "scratch planner validation complete; generic preview repair skipped."
            )

            # Update cross-phase output registry for next phase.
            for node in graph.nodes:
                if node.type in ("router", "fallback_router", "end") or not node.nodeId:
                    continue
                safe_nid = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
                prior_phase_outputs[safe_nid] = _declared_outputs_as_prior_phase_entries(node)

            if phase_index + 1 < len(phases_info):
                _log_prior_phase_handoff_update(
                    completed_phase_id=phase_id,
                    next_phase_id=phases_info[phase_index + 1][0],
                    prior_phase_outputs=prior_phase_outputs,
                    context="scratch/preview",
                )

            phase_results.append(PhaseGraphResult(
                graph=copy.deepcopy(graph),
                validation_warnings=phase_warnings,
                binding_fixes_applied=total_fixes,
                phaseType=phase_type,
            ))
            await _write_preview_build_checkpoint(
                status="building",
                phase_index=phase_index + 1,
            )
    except HTTPException:
        raise

    # Scratch preview only plans the graph. Cost estimation is handled by the
    # dedicated /aiqod-agent/agent/agentic/plan/estimate endpoint.
    total_estimated_credits = 0
    cost_breakdown: list[GenerateNodeCostItem] = []
    generate_node_count = 0
    ui_count = 0
    tool_count = 0
    logger.info("[scratch/preview] Cost estimation skipped; use /agentic/plan/estimate.")

    persisted_steps_nested: list[Dict[str, Any]] = [
        {
            "stepId": phase_id or f"phase_{i + 1}",
            "name": phase_name or f"Phase {i + 1}",
            "description": phase_desc or phase_name or "",
            "phaseType": phase_type,
            "subSteps": [
                {
                    "stepId": s.stepId,
                    "name": s.name,
                    "description": s.description,
                    "inputs": list(s.inputs),
                    "outputs": list(s.outputs),
                }
                for s in (phase_steps or [])
            ],
        }
        for i, (phase_id, phase_name, phase_desc, phase_steps, phase_type) in enumerate(phases_info)
    ]

    try:
        now = datetime.utcnow()
        
        # 1. Store isolated collection metadata in a dedicated registry
        project_coll = db["Project_Collections"]
        project_coll.update_one(
            {
                **_tenant_query(),
                "projectId": request.projectId or process_id,
            },
            {
                "$set": {
                    **_tenant_query(),
                    "projectId": request.projectId or process_id,
                    "workflow_id": process_id,
                    "updated_at": now,
                    "allCollections": request.allCollections or [],
                    "collectionMetadata": request.collectionMetadata or [],
                    "kgSelectedCollections": request.kgSelectedCollections or [],
                },
                "$setOnInsert": {"created_at": now},
            },
            upsert=True,
        )

        # 2. Update Process_Configs without the collection metadata fields
        coll = db["Process_Configs"]
        coll.update_one(
            {
                **_tenant_query(),
                "engineType": engine_type,
                "agentic_process.workflow_id": process_id,
            },
            {
                "$set": {
                    **_tenant_query(),
                    "engineType": engine_type,
                    "selectedName": request.selectedName,
                    "selectedType": request.selectedType,
                    "selectedCategory": request.selectedCategory,
                    "token": request.token,
                    "updated_at": now,
                    "agentic_process": {
                        "workflow_id": process_id,
                        "workflowName": workflow_name,
                        "projectId": request.projectId,
                        "mode": mode,
                        "analysis_source": analysis_source,
                        "prompt": request.prompt,
                        "steps": persisted_steps_nested,
                        "phaseGraphs": [p.model_dump(exclude={"langgraph_code"}) for p in phase_results],
                        "warnings": all_warnings,
                        "estimatedCredits": total_estimated_credits,
                        "planner": "scratch",
                        "status": "preview",
                        "suggestedReports": request.suggestedReports or [],
                    },
                },
                "$setOnInsert": {"created_at": now},
            },
            upsert=True,
        )
    except Exception as _e:
        all_warnings.append(f"Failed to persist scratch preview databases: {_e}")
    else:
        # Only notify VR once the Process_Configs write actually succeeded.
        # True fire-and-forget: scheduled, never awaited, never blocks/fails preview.
        asyncio.create_task(
            _fire_vr_load(
                project_id=request.projectId or process_id,
                subscriber_id=subscriber_id,
                target_collections=request.kgSelectedCollections or [],
            )
        )
        logger.info(
            "[scratch/preview] Scheduled fire-and-forget /vr/load for project_id=%s subscriber_id=%s",
            request.projectId or process_id, subscriber_id,
        )

    if subscriber_id:
        delete_checkpoint(
            db=db,
            workflow_id=process_id,
            subscriber_id=subscriber_id,
        )

    if subscriber_id:
        try:
            delete_checkpoint(
                db=db,
                workflow_id=process_id,
                subscriber_id=subscriber_id,
            )
        except Exception as exc:
            logger.warning(
                "[scratch/preview] delete_checkpoint failed (non-fatal): %s", exc
            )

    prompt_estimated_cost: Optional[float] = None
    prompt_cost_estimate: Optional[Dict[str, Any]] = None
    prompt_sufficient: Optional[bool] = None
    prompt_avail: Optional[float] = None
    if mode == "prompt" and phase_results:
        try:
            from nl_builder.plan_generator import _cost_estimate_from_phase_graphs

            dumps = [
                p.model_dump(mode="json", exclude={"langgraph_code"})
                if hasattr(p, "model_dump")
                else dict(p)
                for p in phase_results
            ]
            prompt_estimated_cost, detail = _cost_estimate_from_phase_graphs(
                dumps,
                base_text=(request.prompt or "").strip(),
            )
            prompt_cost_estimate = detail.model_dump(mode="json") if detail else None
            if detail is not None:
                ui_count = int(detail.uiScreenCount or 0)
                tool_count = int(detail.toolCount or 0)
                generate_node_count = ui_count + tool_count
            if subscriber_id:
                prompt_avail = get_subscriber_available_credits(subscriber_id)
                if prompt_avail is not None and prompt_estimated_cost is not None:
                    prompt_sufficient = prompt_avail >= prompt_estimated_cost
        except Exception as exc:
            logger.warning("[scratch/preview] prompt-mode execute cost failed: %s", exc)
            all_warnings.append(f"execute cost estimate skipped: {exc}")

    return AgenticPlanPreviewResponse(
        workflowId=process_id,
        workflowName=workflow_name,
        steps=all_steps_flat,
        mode=mode,
        analysis_source=analysis_source,
        warnings=all_warnings,
        stepCapabilities=[],
        phaseGraphs=phase_results,
        estimatedCredits=total_estimated_credits,
        estimatedCreditsBreakdown=cost_breakdown,
        generateNodeCount=generate_node_count,
        uiScreenNodeCount=ui_count,
        toolNodeCount=tool_count,
        estimatedCost=prompt_estimated_cost,
        costEstimate=prompt_cost_estimate,
        sufficientBalance=prompt_sufficient,
        subscriberAvailableUsd=prompt_avail,
    )


@app.post("/aiqod-agent/agent/agentic/plan/estimate", response_model=PlanEstimateResponse)
async def plan_estimate(request: AgenticPlanRequest, http_request: Request) -> PlanEstimateResponse:
    """
    Pre-flight cost estimate (no LLM calls, no Mongo writes).

    Both modes estimate the **full remaining workflow**: Stage 0 clarification
    + scratch LangGraph definition + execute/gap codegen (UI/tool generation).

    - **steps mode:** `{steps}` — topology from each step's `preferredKind`.
    - **prompt mode:** `{prompt, expandedSteps}` — same estimator, wrapping
      expander steps as one phase. Expand/revise LLM spend is already incurred
      before this call and is not reserved again.

    Call before `/workflow/register`. After `/scratch/preview`, remaining
    execute can be refined from real GENERATE node counts (`estimatedCost`).
    """
    from services.plan_credit_estimator import (
        estimate_workflow_cost,
        estimator_phases_from_logical_steps,
    )

    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")

    has_prompt = bool(request.prompt and request.prompt.strip())
    has_steps = bool(request.steps)
    has_expanded = bool(request.expandedSteps)
    if has_prompt and has_steps:
        raise HTTPException(
            status_code=400,
            detail="Provide `steps` (steps mode) or `prompt` (prompt mode), not both.",
        )
    if not has_prompt and not has_steps and not has_expanded:
        raise HTTPException(
            status_code=400,
            detail="Provide `steps`, or `prompt` plus `expandedSteps` from /nl/expand.",
        )
    if has_prompt and not has_expanded and not has_steps:
        raise HTTPException(
            status_code=400,
            detail=(
                "Prompt mode /plan/estimate requires `expandedSteps` from "
                "/nl/expand (or /nl/steps/revise) so cost uses the confirmed step list."
            ),
        )

    mode: Literal["prompt", "steps"] = "steps" if has_steps else "prompt"

    if has_steps:
        est = estimate_workflow_cost(
            steps=request.steps,
            suggested_reports=request.suggestedReports,
        )
    else:
        est = estimate_workflow_cost(
            steps=estimator_phases_from_logical_steps(request.expandedSteps),
            suggested_reports=request.suggestedReports,
        )

    stages: list[PlanEstimateStageItem] = [
        PlanEstimateStageItem(
            kind=i.kind,
            count=i.count,
            inputTokens=i.input_tokens,
            outputTokens=i.output_tokens,
            costUsd=i.cost_usd,
            rationale=i.rationale,
        )
        for i in est.items
    ]

    subscriber_available = get_subscriber_available_credits(subscriber_id)
    sufficient = (
        subscriber_available is not None and subscriber_available >= est.predicted_cost
        if subscriber_available is not None
        else None
    )

    return PlanEstimateResponse(
        mode=mode,
        stepCount=est.step_count,
        phaseCount=est.phase_count,
        complexity=est.complexity,
        plannedNodeCount=est.planned_node_count,
        plannedEdgeCount=est.planned_edge_count,
        uiScreenCount=est.ui_screen_count,
        toolCount=est.tool_count,
        totalInputTokens=est.total_input_tokens,
        totalOutputTokens=est.total_output_tokens,
        totalCostUsd=est.total_cost_usd,
        predictedCost=est.predicted_cost,
        stage0CostUsd=est.stage0_cost_usd,
        previewCostUsd=est.preview_cost_usd,
        executeCostUsd=est.execute_cost_usd,
        dashboardReportCount=est.dashboard_report_count,
        stages=stages,
        assumptions=est.assumptions,
        subscriberAvailableUsd=subscriber_available,
        sufficientBalance=sufficient,
        subscriberCredits=subscriber_available,
    )


@app.post("/aiqod-agent/agent/agentic/workflow/register", response_model=WorkflowRegisterResponse)
async def workflow_register(request: WorkflowRegisterRequest, http_request: Request) -> WorkflowRegisterResponse:
    """
    Create Process_Configs for a workflow build.

    When ``reserveSubscriberCredits`` is true, also increments
    ``subscribers.AICredits.reserved`` by ``predictedCost``. Default is false
    (caller or queue service reserves balance separately).
    """
    if request.type != "workflow":
        raise HTTPException(status_code=400, detail="Only type='workflow' is supported.")

    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    if not subscriber_id:
        raise HTTPException(status_code=400, detail="subscriberId is required.")

    try:
        result = register_workflow_process_config(
            project_id=request.projectId,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            predicted_cost=request.predictedCost,
            workflow_name=request.workflowName,
            selected_name=request.selectedName,
            selected_type=request.selectedType,
            selected_category=request.selectedCategory,
            total_input_tokens=request.totalInputTokens,
            total_output_tokens=request.totalOutputTokens,
            suggested_reports=request.suggestedReports,
            reserve_subscriber_credits=request.reserveSubscriberCredits,
        )
    except WorkflowNotRegisteredError as exc:
        raise HTTPException(status_code=409, detail=billing_error_to_http_detail(exc))
    except PredictedCostMissingError as exc:
        raise HTTPException(status_code=400, detail=billing_error_to_http_detail(exc))
    except InsufficientSubscriberBalanceError as exc:
        raise HTTPException(status_code=402, detail=billing_error_to_http_detail(exc))

    return WorkflowRegisterResponse(
        projectId=result["projectId"],
        predictedCost=result["predictedCost"],
        reservedUsd=result["reservedUsd"],
        reservationStatus=result["reservationStatus"],
        created=bool(result.get("created", True)),
    )


@app.post("/aiqod-agent/agent/agentic/workflow/release", response_model=WorkflowReleaseResponse)
async def workflow_release(request: WorkflowReleaseRequest, http_request: Request) -> WorkflowReleaseResponse:
    """
    Release unused workflow hold (predictedCost - budgetSpentUsd) from subscribers.AICredits.reserved.
    Intended for queue cancellation or terminal failure before /execute completes.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    if not subscriber_id:
        raise HTTPException(status_code=400, detail="subscriberId is required.")

    released = release_workflow_reservation(
        project_id=request.projectId,
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
    )
    return WorkflowReleaseResponse(
        projectId=request.projectId,
        releasedUsd=released,
        reservationStatus="released",
    )


# ── Dashboard creation lifecycle (parallel to /agentic/workflow/*, /agentic/plan/*) ──

def _dashboard_estimate_from_reports(
    reports: Optional[list[Dict[str, Any]]],
    subscriber_id: Optional[str],
) -> DashboardPlanEstimateResponse:
    """Shared pre-flight estimate used by create, add, and remove report flows."""
    reports = reports or []
    in_tok, out_tok, cost_usd, detailed = estimate_reports_cost(reports)
    assembly_cost_usd = DASHBOARD_ASSEMBLY_BASE_COST_USD if len(reports) > 1 else 0.0
    predicted_cost = round((cost_usd + assembly_cost_usd) * SAFETY_BUFFER_MULTIPLIER, 6)
    subscriber_available = get_subscriber_available_credits(subscriber_id)
    sufficient = (
        subscriber_available >= predicted_cost if subscriber_available is not None else None
    )
    return DashboardPlanEstimateResponse(
        reportCount=len(reports),
        totalInputTokens=in_tok,
        totalOutputTokens=out_tok,
        totalCostUsd=cost_usd,
        assemblyCostUsd=assembly_cost_usd,
        predictedCost=predicted_cost,
        reports=[DashboardReportCostItem(**d) for d in detailed],
        subscriberAvailableUsd=subscriber_available,
        sufficientBalance=sufficient,
    )


@app.post("/aiqod-agent/agent/agentic/dashboard/plan/estimate", response_model=DashboardPlanEstimateResponse)
async def dashboard_plan_estimate(request: DashboardPlanRequest, http_request: Request) -> DashboardPlanEstimateResponse:
    """
    Pre-flight cost estimate for the dashboard-only pipeline.

    Reuses estimate_reports_cost() — the same function that prices the
    dashboard-report portion of a regular workflow /plan/estimate call. No LLM
    calls, no Mongo writes. Call once at submit, before /dashboard/register.
    """
    reports = request.reports_list()
    if not reports:
        raise HTTPException(status_code=400, detail="'report' array is required and must not be empty.")

    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    return _dashboard_estimate_from_reports(reports, subscriber_id)


@app.post("/aiqod-agent/agent/agentic/dashboard/plan/update/estimate", response_model=DashboardPlanEstimateResponse)
async def dashboard_plan_update_estimate(request: DashboardPlanRequest, http_request: Request) -> DashboardPlanEstimateResponse:
    """
    Pre-flight cost estimate for adding reports to an existing dashboard.

    Only newly added reports (not already stored on Process_Configs) are priced.
    Call before /agentic/dashboard/plan/update.
    """
    reports = request.reports_list()
    if not reports:
        raise HTTPException(status_code=400, detail="'report' array is required and must not be empty.")

    project_id = (request.projectId or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="projectId is required.")

    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    query: Dict[str, Any] = {
        "engineType": "agentic_graph",
        "agentic_process.workflow_id": project_id,
    }
    if subscriber_id:
        query["subscriberId"] = {"$in": [ObjectId(subscriber_id), subscriber_id]}
    existing_doc = db["Process_Configs"].find_one(query)
    existing_reports = ((existing_doc or {}).get("agentic_process") or {}).get("report") or []
    new_reports = diff_new_reports(existing_reports, reports)
    return _dashboard_estimate_from_reports(new_reports, subscriber_id)


@app.post("/aiqod-agent/agent/agentic/dashboard/register", response_model=DashboardRegisterResponse)
async def dashboard_register(request: DashboardRegisterRequest, http_request: Request) -> DashboardRegisterResponse:
    """
    Create Process_Configs (agentic_process.kind="dashboard") after the queue
    service reserves subscriber balance. Reuses register_workflow_process_config
    verbatim — same collection, same billing fields, same idempotent
    re-registration semantics as the workflow flow.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    if not subscriber_id:
        raise HTTPException(status_code=400, detail="subscriberId is required.")

    try:
        result = register_workflow_process_config(
            project_id=request.projectId,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            predicted_cost=request.predictedCost,
            workflow_name=request.dashboardName,
            selected_name=request.selectedName,
            selected_type=request.selectedType or "Dashboard",
            selected_category=request.selectedCategory,
            total_input_tokens=request.totalInputTokens,
            total_output_tokens=request.totalOutputTokens,
            suggested_reports=request.report,
            kind="dashboard",
            reserve_subscriber_credits=False,
        )
    except WorkflowNotRegisteredError as exc:
        raise HTTPException(status_code=409, detail=billing_error_to_http_detail(exc))
    except PredictedCostMissingError as exc:
        raise HTTPException(status_code=400, detail=billing_error_to_http_detail(exc))

    if request.workflowId:
        db["Process_Configs"].update_one(
            {"engineType": "agentic_graph", "agentic_process.workflow_id": request.projectId},
            {"$set": {"agentic_process.linkedWorkflowId": request.workflowId}},
        )

    return DashboardRegisterResponse(
        projectId=result["projectId"],
        predictedCost=result["predictedCost"],
        reservedUsd=result["reservedUsd"],
        reservationStatus=result["reservationStatus"],
        created=bool(result.get("created", True)),
    )


@app.post("/aiqod-agent/agent/agentic/dashboard/plan/scratch/preview", response_model=DashboardPlanPreviewResponse)
async def dashboard_plan_scratch_preview(request: DashboardPlanRequest, http_request: Request) -> DashboardPlanPreviewResponse:
    """
    Deterministically builds the full DashboardDefinition (widgets, Mongo
    queries, aggregation pipelines, filters, sort, chart metadata) from the
    `report` array, together with a cost breakdown. Nothing is generated or
    persisted yet — mirrors /agentic/plan/scratch/preview's "graph, no gap
    resolution" contract. Unlike workflow steps, reports are already
    structured, so no LLM call is required to produce the definition.
    """
    reports = request.reports_list()
    if not reports:
        raise HTTPException(status_code=400, detail="'report' array is required and must not be empty.")
    project_id = (request.projectId or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="projectId is required.")

    dashboard_name = request.dashboardName or request.selectedName or "Dashboard"
    dashboard_def, warnings = build_dashboard_definition(project_id, dashboard_name, reports)

    _, _, cost_usd, _ = estimate_reports_cost(reports)
    assembly_cost_usd = DASHBOARD_ASSEMBLY_BASE_COST_USD if len(reports) > 1 else 0.0
    predicted_cost = round((cost_usd + assembly_cost_usd) * SAFETY_BUFFER_MULTIPLIER, 6)

    return DashboardPlanPreviewResponse(
        projectId=project_id,
        dashboardName=dashboard_name,
        dashboard=dashboard_def,
        reportCount=len(reports),
        predictedCost=predicted_cost,
        warnings=warnings,
    )


@app.post("/aiqod-agent/agent/agentic/dashboard/plan/execute", response_model=DashboardPlanExecuteResponse)
async def dashboard_plan_execute(request: DashboardPlanExecuteRequest, http_request: Request) -> DashboardPlanExecuteResponse:
    """
    Generates a SINGLE Angular dashboard screen containing one widget per
    report (each wired to its own real MongoDB find/aggregate backend
    function — no mock data), and persists the dashboard metadata + generated
    configuration to Process_Configs. Reuses
    dashboard_router.generate_dashboard_screens_for_reports (the exact
    function already used by /agentic/plan/execute when a workflow carries
    suggestedReports) and workflow_reservation_release_scope for the same
    "release unused credit hold no matter how execution ends" guarantee.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")

    reports = request.report or []
    if not reports:
        raise HTTPException(status_code=400, detail="'report' array is required and must not be empty.")
    project_id = request.projectId.strip()
    dashboard_name = request.dashboardName or request.selectedName or "Dashboard"

    # _init_agentic_workflow_billing(
    #     project_id=project_id,
    #     org_id=org_id,
    #     subscriber_id=subscriber_id,
    #     user_id=user_id,
    # )

    warnings: list[str] = []
    dashboard_def = request.dashboard
    if dashboard_def is None:
        dashboard_def, warnings = build_dashboard_definition(project_id, dashboard_name, reports)

    async with workflow_reservation_release_scope(
        project_id=project_id,
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
    ):
        try:
            dash_result = await dashboard_router.generate_dashboard_screens_for_reports(
                workflow_id=request.workflowId or project_id,
                project_id=project_id,
                reports=reports,
                dashboard=dashboard_def,
                dashboard_name=dashboard_name,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
            )
        except Exception as exc:
            logger.exception("[dashboard/execute] Screen generation failed for project %s", project_id)
            raise HTTPException(status_code=500, detail=f"Dashboard screen generation failed: {exc}")

        # dash_result.dashboard reflects the widgets actually used for generation
        # (includes the resolved functionId per widget from backend registration).
        dashboard_def = dash_result.dashboard or dashboard_def

        screens_out = [
            DashboardScreenResultItem(
                reportId=f"report_{i + 1}",
                reportName=screen.reportName,
                reportType=screen.reportType,
                screenId=screen.screenId,
                status="generated" if screen.success else "failed",
                error=screen.error,
            )
            for i, screen in enumerate(dash_result.screens)
        ]

        now = datetime.utcnow()
        tenant_query = {
            k: v for k, v in {"orgId": org_id, "subscriberId": subscriber_id, "userId": user_id}.items() if v
        }
        db["Process_Configs"].update_one(
            {"engineType": "agentic_graph", "agentic_process.workflow_id": project_id},
            {
                "$set": {
                    **tenant_query,
                    "engineType": "agentic_graph",
                    "selectedName": request.selectedName,
                    "selectedType": request.selectedType or "Dashboard",
                    "selectedCategory": request.selectedCategory,
                    "updated_at": now,
                    "agentic_process.workflow_id": project_id,
                    "agentic_process.kind": "dashboard",
                    "agentic_process.status": "Active" if all(s.status == "generated" for s in screens_out) else "draft",
                    "agentic_process.dashboardName": dashboard_name,
                    "agentic_process.linkedWorkflowId": request.workflowId,
                    "agentic_process.report": reports,
                    "agentic_process.dashboardDefinition": dashboard_def.model_dump(),
                    "agentic_process.reports": [s.model_dump() for s in screens_out],
                    "agentic_process.dashboardScreenId": dash_result.dashboardScreenId,
                    "agentic_process.dashboardUrl": dash_result.dashboardUrl,
                },
                "$setOnInsert": {"created_at": now},
            },
            upsert=True,
        )

    all_success = all(s.status == "generated" for s in screens_out)
    return DashboardPlanExecuteResponse(
        success=all_success,
        projectId=project_id,
        dashboardName=dashboard_name,
        dashboard=dashboard_def,
        screens=screens_out,
        dashboardScreenId=dash_result.dashboardScreenId,
        dashboardUrl=dash_result.dashboardUrl,
        warnings=warnings,
    )

class DashboardUpdateRequest(BaseModel):
    """Request payload for /agentic/dashboard/plan/update."""
    projectId: str
    orgId: Optional[str] = None
    subscriberId: Optional[str] = None
    userId: Optional[str] = None
    workflowId: Optional[str] = None
    dashboardName: Optional[str] = None
    selectedName: Optional[str] = None
    selectedType: Optional[str] = None
    selectedCategory: Optional[str] = None
    report: Optional[list[dict[str, Any]]] = None
    dashboard: Optional[DashboardDefinition] = None
    # Caller-supplied collection schema; merged with any schema stored in
    # Process_Configs so LLM enhancement and validation see real field names.
    collectionSchema: Optional[list[dict[str, Any]]] = None


class DashboardUpdateResponse(BaseModel):
    success: bool = True
    projectId: str
    dashboardName: Optional[str] = None
    dashboard: DashboardDefinition
    screens: list[DashboardScreenResultItem] = Field(default_factory=list)
    dashboardScreenId: Optional[str] = None
    dashboardUrl: Optional[str] = None
    warnings: list[str] = Field(default_factory=list)


@app.post("/aiqod-agent/agent/agentic/dashboard/plan/update", response_model=DashboardUpdateResponse)
async def dashboard_plan_update(request: DashboardUpdateRequest, http_request: Request) -> DashboardUpdateResponse:
    """
    Update an existing dashboard by adding newly requested reports as widgets while
    preserving the existing screen (same dashboardScreenId, same URL, same workspace).
    Only registers backend functions for new reports and calls update_app() instead of
    generate_app(). Falls back to full generation when no prior screen exists.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")

    reports = request.report or []
    if not reports:
        raise HTTPException(status_code=400, detail="'report' array is required.")

    project_id = request.projectId.strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="projectId is required.")

    dashboard_name = request.dashboardName or request.selectedName or "Dashboard"

    # 1. Load the existing Process_Configs document
    query: Dict[str, Any] = {
        "engineType": "agentic_graph",
        "agentic_process.workflow_id": project_id,
    }
    if subscriber_id:
        query["subscriberId"] = {"$in": [ObjectId(subscriber_id), subscriber_id]}
    existing_doc = db["Process_Configs"].find_one(query)
    if not existing_doc:
        raise HTTPException(status_code=404, detail=f"Dashboard not found for projectId '{project_id}'.")

    # 2. Resolve tenant IDs from doc if not in request
    if not subscriber_id:
        sub_oid = existing_doc.get("subscriberId")
        subscriber_id = str(sub_oid) if sub_oid else None

    # _init_agentic_workflow_billing(
    #     project_id=project_id, org_id=org_id, subscriber_id=subscriber_id, user_id=user_id,
    # )

    # 3. Re-open reservation if already settled
    if existing_doc.get("reservationStatus") not in (None, "active"):
        try:
            reactivate_workflow_reservation(
                project_id=project_id, org_id=org_id, subscriber_id=subscriber_id,
                user_id=user_id, additional_predicted_cost=0.0,
            )
        except Exception as _react_err:
            logger.warning("[dashboard/update] Reservation re-activation failed (non-fatal): %s", _react_err)

    # 4. Detect whether a previously generated screen already exists
    agentic_proc: Dict[str, Any] = existing_doc.get("agentic_process") or {}
    existing_screen_id: Optional[str] = agentic_proc.get("dashboardScreenId")
    existing_def_data: Optional[Dict[str, Any]] = agentic_proc.get("dashboardDefinition")
    existing_reports_stored: list[Dict[str, Any]] = list(agentic_proc.get("report") or [])
    existing_dashboard_url: Optional[str] = agentic_proc.get("dashboardUrl")

    # 4a. Extract collection_schema from Process_Configs.
    #     Strategy: if the current document carries a linkedWorkflowId, look up
    #     the linked workflow's Process_Configs record and pull collection_schema
    #     from there (the linked workflow owns the canonical schema).  Fall back
    #     to the schema stored directly on this document if no link exists.
    collection_schema: Optional[Any] = None
    linked_workflow_id: Optional[str] = agentic_proc.get("linkedWorkflowId")
    if linked_workflow_id:
        try:
            linked_doc = db["Process_Configs"].find_one(
                {"agentic_process.workflow_id": linked_workflow_id},
                {"agentic_process.collection_schema": 1},
            )
            if linked_doc:
                collection_schema = (linked_doc.get("agentic_process") or {}).get("collection_schema") or None
                if collection_schema:
                    logger.info(
                        "[dashboard/update] Loaded collection_schema from linked workflow '%s' for project %s",
                        linked_workflow_id,
                        project_id,
                    )
                else:
                    logger.info(
                        "[dashboard/update] Linked workflow '%s' has no collection_schema; falling back to current doc",
                        linked_workflow_id,
                    )
        except Exception as _link_err:
            logger.warning(
                "[dashboard/update] Failed to load collection_schema from linked workflow '%s': %s",
                linked_workflow_id,
                _link_err,
            )

    # Fall back to the schema stored on the current document if not found via link
    if collection_schema is None:
        collection_schema = agentic_proc.get("collection_schema") or None

    if collection_schema:
        logger.info(
            "[dashboard/update] Found collection_schema for project %s: %s collection(s)",
            project_id,
            len(collection_schema) if isinstance(collection_schema, (dict, list)) else "?",
        )

    # 4a-ii. Merge request.collectionSchema with the stored schema (request takes priority)
    if request.collectionSchema:
        if collection_schema is None:
            collection_schema = request.collectionSchema
        elif isinstance(collection_schema, list) and isinstance(request.collectionSchema, list):
            stored_by_name = {
                (e.get("collection_name") or e.get("name") or ""): e
                for e in collection_schema if isinstance(e, dict)
            }
            for new_entry in request.collectionSchema:
                if isinstance(new_entry, dict):
                    key = new_entry.get("collection_name") or new_entry.get("name") or ""
                    stored_by_name[key] = new_entry
            collection_schema = list(stored_by_name.values())
        else:
            collection_schema = request.collectionSchema
        # Persist merged schema back to Process_Configs (non-fatal)
        try:
            db["Process_Configs"].update_one(
                {"_id": existing_doc["_id"]},
                {"$set": {"agentic_process.collection_schema": collection_schema}},
            )
        except Exception as _persist_err:
            logger.warning("[dashboard/update] Failed to persist merged collectionSchema: %s", _persist_err)

    # 4b. Validate incoming reports against the collection_schema (if available)
    warnings_list: list[str] = []
    if collection_schema and reports:
        # Normalize schema to dict-of-dicts format for lookup
        schema_lookup: Dict[str, Dict[str, Any]] = {}
        if isinstance(collection_schema, dict):
            for coll_name, coll_info in collection_schema.items():
                if coll_name == "__meta__":
                    continue
                if isinstance(coll_info, dict):
                    fields = coll_info.get("fields") if "fields" in coll_info else coll_info
                    schema_lookup[coll_name] = fields if isinstance(fields, dict) else {}
        elif isinstance(collection_schema, list):
            for entry in collection_schema:
                if isinstance(entry, dict):
                    coll_name = entry.get("collection_name") or entry.get("name")
                    coll_fields = entry.get("schema") or entry.get("fields") or {}
                    if coll_name and isinstance(coll_fields, dict):
                        schema_lookup[coll_name] = coll_fields

        if schema_lookup:
            for idx, rep in enumerate(reports):
                rep_name = rep.get("reportName", f"report_{idx}")
                coll_name = rep.get("collectionName", "")
                if coll_name and coll_name not in schema_lookup:
                    warnings_list.append(
                        f"Report '{rep_name}': collectionName '{coll_name}' not found in collection_schema. "
                        f"Available collections: {', '.join(sorted(schema_lookup.keys()))}"
                    )
                elif coll_name and coll_name in schema_lookup:
                    coll_fields = schema_lookup[coll_name]
                    # Validate optionalFilters against schema fields
                    for filt in (rep.get("optionalFilters") or []):
                        if isinstance(filt, str) and filt not in coll_fields:
                            # Check case-insensitive match
                            matched = any(k.lower() == filt.lower() for k in coll_fields)
                            if not matched:
                                warnings_list.append(
                                    f"Report '{rep_name}': filter field '{filt}' not found in collection '{coll_name}' schema. "
                                    f"Available fields: {', '.join(sorted(coll_fields.keys())[:20])}"
                                )
                    # Validate aggregation pipeline field references
                    agg = rep.get("aggregation")
                    if agg and isinstance(agg, list):
                        for stage in agg:
                            if isinstance(stage, dict):
                                group_body = stage.get("$group")
                                if isinstance(group_body, dict):
                                    group_id = group_body.get("_id")
                                    if isinstance(group_id, str) and group_id.startswith("$"):
                                        field_ref = group_id[1:]
                                        if field_ref not in coll_fields:
                                            matched = any(k.lower() == field_ref.lower() for k in coll_fields)
                                            if not matched:
                                                warnings_list.append(
                                                    f"Report '{rep_name}': aggregation $group._id references field '{field_ref}' "
                                                    f"not found in collection '{coll_name}' schema."
                                                )

    async with workflow_reservation_release_scope(
        project_id=project_id, org_id=org_id, subscriber_id=subscriber_id, user_id=user_id,
    ):
        # ── UPDATE PATH: existing screen found ───────────────────────────────────
        if existing_screen_id and existing_def_data:
            try:
                existing_def = DashboardDefinition(**existing_def_data)
            except Exception as parse_err:
                logger.warning(
                    "[dashboard/update] Failed to parse stored DashboardDefinition: %s — falling back to full regeneration",
                    parse_err,
                )
                existing_screen_id = None  # fall through to create path below

        if existing_screen_id and existing_def_data:
            try:
                # Identify reports that are genuinely new (not already in the stored list)
                new_reports = diff_new_reports(existing_reports_stored, reports)

                if not new_reports:
                    # Nothing new — return the existing screen state without touching Angular
                    logger.info(
                        "[dashboard/update] No new reports for project %s; returning existing screen %s unchanged.",
                        project_id, existing_screen_id,
                    )
                    existing_screens_out = [
                        DashboardScreenResultItem(
                            reportId=f"report_{i + 1}",
                            reportName=w.reportName,
                            reportType=w.reportType,
                            screenId=existing_screen_id,
                            status="generated",
                            error=None,
                        )
                        for i, w in enumerate(existing_def.widgets)
                    ]
                    return DashboardUpdateResponse(
                        success=True,
                        projectId=project_id,
                        dashboardName=dashboard_name,
                        dashboard=existing_def,
                        screens=existing_screens_out,
                        dashboardScreenId=existing_screen_id,
                        dashboardUrl=existing_dashboard_url,
                        warnings=["No new reports detected; existing screen returned unchanged."],
                    )

                # Build DashboardDefinition for new reports only, offsetting reportIds
                # so they don't collide with existing widget IDs.
                widget_offset = len(existing_def.widgets)

                # Enhance free-text / incomplete reports before building widget definitions
                # (same logic as the /update-screen path in dashboard.py).
                enhanced_new_reports = await dashboard_router.enhance_report_descriptions(
                    user_reports=list(new_reports),
                    collection_schema=collection_schema,
                    workflow_name=dashboard_name,
                )
                new_def, new_warnings = build_dashboard_definition(project_id, dashboard_name, enhanced_new_reports)
                warnings_list.extend(new_warnings)
                for idx, w in enumerate(new_def.widgets):
                    w.reportId = f"report_{widget_offset + idx + 1}"

                # Enrich widget descriptions with LLM-generated query-plan bullets
                # (same as /update-screen), then copy them onto the report objects
                # so agentic_process.report stores the LLM text, not the user prompt.
                try:
                    llm_descs = await dashboard_router._llm_build_query_plan_descriptions(new_def.widgets)
                    for w in new_def.widgets:
                        if w.reportName in llm_descs:
                            w.description = llm_descs[w.reportName]
                except Exception as _desc_err:
                    logger.warning(
                        "[dashboard/update] LLM query-plan descriptions failed (non-fatal): %s",
                        _desc_err,
                    )
                for idx, w in enumerate(new_def.widgets):
                    if idx < len(enhanced_new_reports) and w.description:
                        enhanced_new_reports[idx]["description"] = w.description
                        if w.datasource:
                            enhanced_new_reports[idx]["collectionName"] = w.datasource
                        if w.requiredFields:
                            enhanced_new_reports[idx]["requiredFields"] = w.requiredFields

                # Register backend functions only for the new widgets
                new_backend_metadata: Dict[str, Any] = {"base_path": None, "functions": []}
                try:
                    new_backend_metadata = await dashboard_router.register_dashboard_backend_functions(
                        project_id=project_id,
                        dashboard_def=new_def,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                    )
                except Exception:
                    logger.exception(
                        "[dashboard/update] Failed to register new backend functions for project %s", project_id
                    )

                # Merge: combined definition preserves all existing widgets + appends new ones
                combined_def = DashboardDefinition(
                    dashboardId=existing_def.dashboardId,
                    dashboardName=existing_def.dashboardName,
                    widgets=existing_def.widgets + new_def.widgets,
                )

                # Build a targeted update prompt that describes only the additions
                new_widgets_summary = "\n".join(
                    f"  - \"{w.title}\" ({w.widgetType}), functionId={w.functionId}, collection={w.datasource}"
                    for w in new_def.widgets
                )
                update_prompt = (
                    f'Add {len(new_reports)} new widget(s) to the existing "{combined_def.dashboardName}" dashboard.\n\n'
                    f"DO NOT remove or modify any existing widgets. Only INSERT the following new widgets:\n\n"
                    f"{new_widgets_summary}\n\n"
                    f"Follow the same visual theme, layout, and Angular patterns already present in the app.\n"
                    f"Each new widget must call its functionId via the existing ApiService pattern.\n"
                    f"Use ChangeDetectorRef.markForCheck() after every HTTP data load.\n"
                )

                # Append collection_schema to the update prompt so the Angular LLM
                # knows the actual field names available in each collection (same
                # pattern as the dashboard creation flow in routers/dashboard.py).
                if collection_schema:
                    schema_parts = ["\n\n### DATABASE COLLECTION SCHEMAS (actual field names in each collection):"]
                    if isinstance(collection_schema, dict):
                        for coll_name, coll_info in collection_schema.items():
                            if coll_name == "__meta__":
                                continue
                            fields = (coll_info or {}).get("fields") if isinstance(coll_info, dict) and "fields" in coll_info else coll_info
                            if isinstance(fields, dict) and fields:
                                type_hints = ", ".join(f"{k} ({v})" for k, v in sorted(fields.items())[:40])
                                schema_parts.append(f"  - {coll_name}: {type_hints}")
                            else:
                                schema_parts.append(f"  - {coll_name}: (no sample data)")
                    elif isinstance(collection_schema, list):
                        for entry in collection_schema:
                            if isinstance(entry, dict):
                                coll_name = entry.get("collection_name") or entry.get("name")
                                coll_fields = entry.get("schema") or entry.get("fields") or {}
                                if coll_name and isinstance(coll_fields, dict) and coll_fields:
                                    type_hints = ", ".join(f"{k} ({v})" for k, v in sorted(coll_fields.items())[:40])
                                    schema_parts.append(f"  - {coll_name}: {type_hints}")
                                else:
                                    schema_parts.append(f"  - {coll_name or 'unknown'}: (no sample data)")
                    update_prompt += "\n".join(schema_parts)

                # Updated IR schema contains ALL widgets (existing + new) for context
                updated_ir_schema: Dict[str, Any] = {
                    "screen": {"id": existing_screen_id, "name": combined_def.dashboardName},
                    "components": [
                        {
                            "id": w.reportId,
                            "type": w.widgetType,
                            "reportName": w.reportName,
                            "reportType": w.reportType,
                            "title": w.title,
                            "description": w.description,
                        }
                        for w in combined_def.widgets
                    ],
                }

                # Load the current screen doc and workspace directory from screen_generations
                # (same pattern as update_angular_screen_async)
                new_version = datetime.utcnow().strftime("%Y%m%d%H%M%S")
                current_doc = await screen_repository.get_latest_screen_doc(project_id, existing_screen_id)
                version_count = await screen_repository.count_versions(project_id, existing_screen_id)
                version_label = f"v{version_count + 1}"

                current_state = await screen_repository.get_screen_state(project_id, existing_screen_id)
                workspace_dir: Optional[str] = current_state.get("angular_workspace_directory") if current_state else None

                backend_meta_to_use = _ensure_backend_metadata(new_backend_metadata, project_id)

                # Step 5 (mirroring update_angular_screen_async): selective Angular update
                angular_result: Optional[Dict[str, Any]] = None
                if not workspace_dir:
                    logger.warning(
                        "[dashboard/update] Workspace not found for screen %s — falling back to full regeneration.",
                        existing_screen_id,
                    )
                    angular_result = await angular_generator.generate_app(
                        user_prompt=update_prompt,
                        project_id=project_id,
                        screen_id=existing_screen_id,
                        backend_metadata=backend_meta_to_use,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                        version=new_version,
                        is_update=True,
                    )
                else:
                    current_code = angular_generator._read_workspace_code(workspace_dir)
                    analysis = angular_generator.analyze_update_scope(
                        update_prompt,
                        updated_ir_schema,
                        current_code,
                        project_id=project_id,
                        screen_id=existing_screen_id,
                        version=new_version,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                    )
                    affected_files: list[Dict[str, str]] = analysis.get("affected_files", [])
                    if not affected_files:
                        # Default to main component files when analysis returns nothing
                        affected_files = [
                            {"path": "src/app/app.component.ts", "reason": "Add new widget components", "change_type": "component-add"},
                            {"path": "src/app/app.component.html", "reason": "Add new widget templates", "change_type": "component-add"},
                        ]
                    logger.info("[dashboard/update] Affected files: %s", affected_files)
                    angular_result = await angular_generator.update_app(
                        user_prompt=update_prompt,
                        project_id=project_id,
                        screen_id=existing_screen_id,
                        updated_ir_schema=updated_ir_schema,
                        affected_files=affected_files,
                        backend_metadata=backend_meta_to_use,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                        version=new_version,
                    )

                    # If Angular update was skipped (no affected files), don't create new version
                    logger.debug(
                        f"[dashboard/update] Checking skipped flag: angular_result={angular_result}, "
                        f"skipped={angular_result.get('skipped') if angular_result else 'N/A'}"
                    )
                    if angular_result and angular_result.get("skipped"):
                        logger.info(f"[dashboard/update] Angular update skipped (no file changes), keeping existing version")
                        logger.debug(f"[dashboard/update] SKIPPED: preserving dashboardUrl for existing_screen_id={existing_screen_id}")
                        dashboard_url = angular_result.get("public_url") or f"{deploy_base_url.rstrip('/')}/{existing_screen_id}"
                        angular_metadata = {
                            "workspace_directory": str(angular_result.get("workspace_directory")) if angular_result.get("workspace_directory") else None,
                            "public_url": dashboard_url,
                            "version": angular_result.get("version"),
                            "last_build_at": datetime.utcnow(),
                        }
                    else:
                        # Step 6 (mirroring update_angular_screen_async): persist to screen_generations
                        deploy_base_url = config.get("LIBERTY_FS_BASE_URL", "https://liberty-fs.gibots.com:843")
                        dashboard_url = (
                            (angular_result.get("public_url") if angular_result else None)
                            or f"{deploy_base_url.rstrip('/')}/{existing_screen_id}-v{new_version}"
                        )

                        angular_metadata = {
                            "workspace_directory": str(angular_result.get("workspace_directory")) if angular_result and angular_result.get("workspace_directory") else None,
                            "public_url": dashboard_url,
                            "version": angular_result.get("version") if angular_result else new_version,
                            "last_build_at": datetime.utcnow(),
                        }
                if current_doc:
                    v_next_doc = copy.deepcopy(current_doc)
                    v_next_doc.pop("_id", None)
                    v_next_doc["ir_schema"] = updated_ir_schema
                    v_next_doc["angular"] = angular_metadata
                    v_next_doc["screen_name"] = combined_def.dashboardName
                    v_next_doc["screen_type"] = "dashboard"
                    try:
                        await screen_repository.insert_screen_version_doc(
                            project_id,
                            existing_screen_id,
                            new_version,
                            version_label,
                            v_next_doc,
                            build_status="success",
                            is_stable=True,
                        )
                        subscriber_db_name = f"{get_main_db_name()}_sb_{subscriber_id}" if subscriber_id else None
                        await screen_repository.update_screens_pointer(
                            project_id,
                            existing_screen_id,
                            new_version,
                            org_id=org_id,
                            subscriber_id=subscriber_id,
                            subscriber_db_name=subscriber_db_name,
                            user_id=user_id,
                        )
                        try:
                            screen_doc_cap = {**v_next_doc, "screen_id": existing_screen_id, "project_id": project_id, "version": new_version}
                            await sync_screen_single(capability_repository, screen_doc_cap)
                        except Exception as cap_exc:
                            logger.warning("[dashboard/update] Capability sync failed (non-fatal): %s", cap_exc)
                    except Exception as persist_exc:
                        logger.warning("[dashboard/update] Failed to persist screen version (screen still deployed): %s", persist_exc)

                # All reports in the final state = previously stored + LLM-enriched new ones
                all_reports_combined = existing_reports_stored + list(enhanced_new_reports)
                screens_out = [
                    DashboardScreenResultItem(
                        reportId=f"report_{i + 1}",
                        reportName=w.reportName,
                        reportType=w.reportType,
                        screenId=existing_screen_id,
                        status="generated",
                        error=None,
                    )
                    for i, w in enumerate(combined_def.widgets)
                ]

                # Update Process_Configs, keeping the same dashboardScreenId
                now = datetime.utcnow()
                tenant_set: Dict[str, Any] = {}
                if org_id:
                    tenant_set["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id
                if subscriber_id:
                    tenant_set["subscriberId"] = ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id
                if user_id:
                    tenant_set["userId"] = user_id

                db["Process_Configs"].update_one(
                    {"engineType": "agentic_graph", "agentic_process.workflow_id": project_id},
                    {"$set": {
                        "updated_at": now,
                        "agentic_process.status": "Active",
                        "agentic_process.dashboardName": dashboard_name,
                        "agentic_process.report": all_reports_combined,
                        "agentic_process.dashboardDefinition": combined_def.model_dump(),
                        "agentic_process.reports": [s.model_dump() for s in screens_out],
                        "agentic_process.dashboardScreenId": existing_screen_id,
                        "agentic_process.dashboardUrl": dashboard_url,
                        **tenant_set,
                    }},
                )

            except Exception as exc:
                logger.exception("[dashboard/update] Incremental update failed for project %s", project_id)
                raise HTTPException(status_code=500, detail=f"Dashboard update failed: {exc}")

            return DashboardUpdateResponse(
                success=True,
                projectId=project_id,
                dashboardName=dashboard_name,
                dashboard=combined_def,
                screens=screens_out,
                dashboardScreenId=existing_screen_id,
                dashboardUrl=dashboard_url,
                warnings=warnings_list,
            )

        # ── CREATE PATH: no prior screen — generate from scratch ─────────────────
        # Enhance incomplete reports (empty collectionName / aggregation) before building
        if dashboard_def is None or request.dashboard is None:
            enhanced_reports_create = await dashboard_router.enhance_report_descriptions(
                user_reports=list(reports),
                collection_schema=collection_schema,
                workflow_name=dashboard_name,
            )
            reports = enhanced_reports_create

        dashboard_def = request.dashboard
        if dashboard_def is None:
            dashboard_def, warnings_list = build_dashboard_definition(project_id, dashboard_name, reports)

        try:
            dash_result = await dashboard_router.generate_dashboard_screens_for_reports(
                workflow_id=request.workflowId or project_id,
                project_id=project_id,
                reports=reports,
                dashboard=dashboard_def,
                dashboard_name=dashboard_name,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
            )
        except Exception as exc:
            logger.exception("[dashboard/update] Screen generation failed for project %s", project_id)
            raise HTTPException(status_code=500, detail=f"Dashboard update failed: {exc}")

        dashboard_def = dash_result.dashboard or dashboard_def
        # Copy LLM widget descriptions onto the persisted report array so
        # agentic_process.report[i].description matches widgets[i].description.
        if dashboard_def and dashboard_def.widgets:
            for idx, w in enumerate(dashboard_def.widgets):
                if idx < len(reports) and w.description:
                    reports[idx]["description"] = w.description
        screens_out = [
            DashboardScreenResultItem(
                reportId=f"report_{i + 1}",
                reportName=screen.reportName,
                reportType=screen.reportType,
                screenId=screen.screenId,
                status="generated" if screen.success else "failed",
                error=screen.error,
            )
            for i, screen in enumerate(dash_result.screens)
        ]

        # Persist new configuration
        now = datetime.utcnow()
        tenant_set: Dict[str, Any] = {}
        if org_id:
            tenant_set["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id
        if subscriber_id:
            tenant_set["subscriberId"] = ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id
        if user_id:
            tenant_set["userId"] = user_id

        db["Process_Configs"].update_one(
            {"engineType": "agentic_graph", "agentic_process.workflow_id": project_id},
            {"$set": {
                "engineType": "agentic_graph",
                "selectedName": request.selectedName,
                "selectedType": request.selectedType or "Dashboard",
                "selectedCategory": request.selectedCategory,
                "updated_at": now,
                "agentic_process.workflow_id": project_id,
                "agentic_process.kind": "dashboard",
                "agentic_process.status": "Active" if all(s.status == "generated" for s in screens_out) else "draft",
                "agentic_process.dashboardName": dashboard_name,
                "agentic_process.report": reports,
                "agentic_process.dashboardDefinition": dashboard_def.model_dump(),
                "agentic_process.reports": [s.model_dump() for s in screens_out],
                "agentic_process.dashboardScreenId": dash_result.dashboardScreenId,
                "agentic_process.dashboardUrl": dash_result.dashboardUrl or None,
                **tenant_set,
            }, "$setOnInsert": {"created_at": now}},
            upsert=True,
        )

    all_success = all(s.status == "generated" for s in screens_out)
    return DashboardUpdateResponse(
        success=all_success,
        projectId=project_id,
        dashboardName=dashboard_name,
        dashboard=dashboard_def,
        screens=screens_out,
        dashboardScreenId=dash_result.dashboardScreenId,
        dashboardUrl=dash_result.dashboardUrl,
        warnings=warnings_list,
    )

@app.post("/aiqod-agent/agent/agentic/workflow/progress", response_model=WorkflowProgressResponse)
async def workflow_progress(
    request: WorkflowProgressRequest,
    http_request: Request,
) -> WorkflowProgressResponse:
    """
    Return where a workflow build stopped, how far it progressed, and what remains.

    Combines Process_Configs (status, billing) with workflow_build_checkpoints
    (pipeline stage, partial graphs, scratch sub-stage, last error) and optional
    workflow_build_jobs fields (jobId / jobStatus) when an async build job exists.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    workflow_id = (request.workflowId or "").strip()

    if not subscriber_id:
        raise HTTPException(status_code=400, detail="subscriberId is required.")
    if not workflow_id:
        raise HTTPException(status_code=400, detail="workflowId is required.")

    result = build_workflow_progress(
        db=db,
        workflow_id=workflow_id,
        subscriber_id=subscriber_id,
        org_id=org_id,
        user_id=user_id,
    )
    if not result.get("found"):
        # Allow FE to poll jobStatus for async build jobs even if Process_Configs
        # is missing (e.g. job enqueued before preview creates the config row).
        if result.get("jobId"):
            return WorkflowProgressResponse.model_validate(result)
        raise HTTPException(
            status_code=404,
            detail={
                "success": False,
                "found": False,
                "workflowId": workflow_id,
                "error": result.get("error") or "Workflow not found.",
            },
        )
    return WorkflowProgressResponse.model_validate(result)


@app.post(
    "/aiqod-agent/agent/agentic/workflow/jobs",
    response_model=WorkflowBuildJobCreateResponse,
    status_code=202,
)
async def create_workflow_build_job(
    request: WorkflowBuildJobCreateRequest,
    http_request: Request,
):
    """
    Enqueue an async preview / execute / resume build job (Phase 1+).

    Returns 202 immediately. Poll POST /agentic/workflow/progress for jobStatus.
    Does not run preview/execute in this request. Sync /scratch/preview and
    /plan/execute remain available unchanged.
    """
    if create_or_get_and_enqueue is None:
        raise HTTPException(
            status_code=503,
            detail="Build job services are not available on this server.",
        )

    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = (
        request.subscriberId or http_request.headers.get("x-subscriber-id") or ""
    ).strip()
    workflow_id = (request.workflowId or request.projectId or "").strip()
    job_type = (request.jobType or "").strip().lower()

    if not subscriber_id:
        raise HTTPException(status_code=400, detail="subscriberId is required.")
    if not workflow_id:
        raise HTTPException(status_code=400, detail="workflowId is required.")
    if job_type not in VALID_JOB_TYPES:
        raise HTTPException(
            status_code=400,
            detail=f"jobType must be one of: {sorted(VALID_JOB_TYPES)}",
        )

    payload = request.payload or {}
    if job_type == "execute":
        phase_graphs = payload.get("phaseGraphs")
        if not isinstance(phase_graphs, list) or not phase_graphs:
            raise HTTPException(
                status_code=400,
                detail=(
                    "payload.phaseGraphs is required for jobType=execute "
                    "(same body as POST /plan/execute)."
                ),
            )
        if not (payload.get("workflowId") or workflow_id):
            raise HTTPException(
                status_code=400,
                detail="payload.workflowId (or workflowId) is required for execute.",
            )
        # Ensure workflowId is present inside stored request for the worker
        if not payload.get("workflowId"):
            payload = {**payload, "workflowId": workflow_id}
        if subscriber_id and not payload.get("subscriberId"):
            payload = {**payload, "subscriberId": subscriber_id}
        if org_id and not payload.get("orgId"):
            payload = {**payload, "orgId": org_id}
        if user_id and not payload.get("userId"):
            payload = {**payload, "userId": user_id}

    elif job_type == "preview":
        # Same contract as POST /scratch/preview (AgenticPlanRequest)
        has_prompt = bool(payload.get("prompt") and str(payload.get("prompt")).strip())
        has_steps = bool(payload.get("steps"))
        if has_prompt == has_steps:
            raise HTTPException(
                status_code=400,
                detail=(
                    "payload must include exactly one of 'prompt' (non-empty) "
                    "or 'steps' (same body as POST /scratch/preview)."
                ),
            )
        # Scratch preview keys off projectId === workflowId after register
        if not payload.get("projectId"):
            payload = {**payload, "projectId": workflow_id}
        if not payload.get("workflowId"):
            payload = {**payload, "workflowId": workflow_id}
        if subscriber_id and not payload.get("subscriberId"):
            payload = {**payload, "subscriberId": subscriber_id}
        if org_id and not payload.get("orgId"):
            payload = {**payload, "orgId": org_id}
        if user_id and not payload.get("userId"):
            payload = {**payload, "userId": user_id}

    elif job_type == "resume":
        # Same ids as POST /workflow/resume; checkpoint must be paused_credit
        if not payload.get("workflowId"):
            payload = {**payload, "workflowId": workflow_id}
        if subscriber_id and not payload.get("subscriberId"):
            payload = {**payload, "subscriberId": subscriber_id}
        if org_id and not payload.get("orgId"):
            payload = {**payload, "orgId": org_id}
        if user_id and not payload.get("userId"):
            payload = {**payload, "userId": user_id}
        cp = read_checkpoint(
            db=db, workflow_id=workflow_id, subscriber_id=subscriber_id
        )
        if not (cp and cp.get("status") == "paused_credit"):
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": (
                        "Workflow is not in paused_credit state. "
                        "Resume requires a paused_credit checkpoint."
                    ),
                    "workflowId": workflow_id,
                },
            )
        resume_stage = cp.get("pipeline_stage") or "execute"

    try:
        enqueue_kwargs = dict(
            db=db,
            job_type=job_type,
            workflow_id=workflow_id,
            subscriber_id=subscriber_id,
            org_id=org_id,
            user_id=user_id,
            payload=payload,
        )
        if job_type == "resume":
            enqueue_kwargs["pipeline_stage"] = resume_stage
        out = create_or_get_and_enqueue(**enqueue_kwargs)
    except RuntimeError as exc:
        # Missing valkey/redis package or connection refused after insert→fail
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except Exception as exc:
        logger.exception("[workflow/jobs] enqueue failed workflow_id=%s", workflow_id)
        raise HTTPException(
            status_code=503,
            detail=f"Failed to enqueue build job: {exc}",
        ) from exc

    status_code = 200 if out.get("reused") else 202
    body = WorkflowBuildJobCreateResponse(
        success=True,
        jobId=out["jobId"],
        workflowId=out["workflowId"],
        jobType=out["jobType"],
        status=out["status"],
        reused=bool(out.get("reused")),
        progressEndpoint=out.get(
            "progressEndpoint",
            "/aiqod-agent/agent/agentic/workflow/progress",
        ),
    )
    return JSONResponse(status_code=status_code, content=body.model_dump())


def _build_execute_resume_request(cp: dict) -> AgenticPlanExecuteRequest:
    ctx = cp.get("request_context") or {}
    ctx_clean = {
        k: v
        for k, v in ctx.items()
        if k not in ("resumePhaseIndex", "resumeCompletedPhaseGraphs")
    }
    orig = AgenticPlanExecuteRequest.model_validate(ctx_clean)
    checkpoint_graphs = [
        PhaseGraphResult.model_validate(g) for g in (cp.get("phase_graphs") or [])
    ]
    phase_index = int(cp.get("phase_index") or 0)
    completed = checkpoint_graphs[:phase_index]
    if phase_index < len(checkpoint_graphs):
        merged_graphs = [checkpoint_graphs[phase_index]] + orig.phaseGraphs[phase_index + 1 :]
    else:
        merged_graphs = orig.phaseGraphs[phase_index:]
    return orig.model_copy(
        update={
            "phaseGraphs": merged_graphs,
            "resumePhaseIndex": len(completed),
            "resumeCompletedPhaseGraphs": completed or None,
        }
    )


async def _resume_stage0_from_checkpoint(cp: dict) -> Stage0Response:
    session = _Stage0Session.model_validate(cp["stage0_session"])
    await stage0_session_manager.save(session)
    api_key = _stage0_require_gemini_key()
    action = cp.get("stage0_action") or "respond"
    skip_remaining = bool(cp.get("stage0_skip_remaining"))

    try:
        if action == "guidance":
            flag_key = (cp.get("stage0_guidance_flag_key") or "").strip()
            flag = next(
                (f for f in session.state.detected_flags if f.flag_type == flag_key),
                None,
            )
            if flag is None and flag_key:
                flag = next(
                    (
                        f for f in session.state.detected_flags
                        if f.flag_type.upper() == flag_key.upper()
                    ),
                    None,
                )
            if flag is None:
                raise HTTPException(
                    status_code=400,
                    detail=f"Flag '{flag_key}' not found in resumed stage0 session.",
                )
            await _stage0_refresh_credentials(session)
            guidance: Stage0GuidanceResult = await run_stage0_guidance_turn(
                flag=flag,
                raw_prompt=session.raw_prompt,
                api_key=api_key,
                user_question=(cp.get("stage0_guidance_user_question") or "").strip() or None,
                model=STAGE0_DEFAULT_MODEL,
                project_id=session.workflow_id,
                org_id=session.org_id,
                subscriber_id=session.subscriber_id,
                user_id=session.user_id,
            )
            if session.subscriber_id:
                delete_checkpoint(
                    db=db,
                    workflow_id=session.workflow_id,
                    subscriber_id=session.subscriber_id,
                )
            return Stage0GuidanceResponse(
                sessionId=session.session_id,
                flagKey=flag.flag_type,
                guidanceMarkdown=guidance.markdown,
                docLinks=guidance.doc_links,
                credentialNames=guidance.credential_names,
                source=guidance.source,
                dependencyType=guidance.dependency_type,
            )

        cred_result, newly_added = await _stage0_refresh_credentials(session)

        if action == "start":
            parsed = await run_stage0b_single_turn(
                raw_prompt=session.raw_prompt,
                configured_secret_names=cred_result.configured_secret_names,
                api_key=api_key,
                conversation_history=[],
                unresolved_flags=[],
                model=STAGE0_DEFAULT_MODEL,
                project_id=session.workflow_id,
                org_id=session.org_id,
                subscriber_id=session.subscriber_id,
                user_id=session.user_id,
            )
        else:
            unresolved_flags = critical_unresolved_flags(session.state.detected_flags)
            parsed = await run_stage0b_single_turn(
                raw_prompt=session.raw_prompt,
                configured_secret_names=cred_result.configured_secret_names,
                api_key=api_key,
                conversation_history=session.state.conversation_turns,
                unresolved_flags=unresolved_flags,
                newly_configured_secrets=newly_added,
                model=STAGE0_DEFAULT_MODEL,
                project_id=session.workflow_id,
                org_id=session.org_id,
                subscriber_id=session.subscriber_id,
                user_id=session.user_id,
            )

        response = await _stage0_apply_b_turn(
            session,
            parsed,
            api_key=api_key,
            skip_remaining=skip_remaining,
        )
    except BillingError as exc:
        await _checkpoint_stage0_pause(
            session=session,
            action=action,
            exc=exc,
            skip_remaining=skip_remaining,
            guidance_flag_key=cp.get("stage0_guidance_flag_key"),
            guidance_user_question=cp.get("stage0_guidance_user_question"),
        )
        raise HTTPException(
            status_code=402,
            detail=_billing_pause_error(
                exc,
                workflow_id=session.workflow_id,
                subscriber_id=session.subscriber_id,
            ),
        ) from exc

    if session.subscriber_id:
        delete_checkpoint(
            db=db,
            workflow_id=session.workflow_id,
            subscriber_id=session.subscriber_id,
        )
    return response


async def _resume_scratch_preview_from_checkpoint(
    cp: dict,
    *,
    org_id: Optional[str],
    subscriber_id: str,
    user_id: Optional[str],
) -> AgenticPlanPreviewResponse:
    ctx = cp.get("request_context") or {}
    api_key = get_gemini_api_key()
    process_id = ctx.get("process_id") or cp["workflow_id"]
    workflow_name = ctx.get("workflow_name") or "workflow"
    mode = ctx.get("mode") or "prompt"
    analysis_source = ctx.get("analysis_source")
    project_id_for_gen = ctx.get("project_id_for_gen") or process_id
    stage0_planner_context = ctx.get("stage0_planner_context") or ""
    all_warnings: list[str] = list(cp.get("warnings") or [])

    phase_results: list[PhaseGraphResult] = [
        PhaseGraphResult.model_validate(g) for g in (cp.get("phase_graphs") or [])
    ]
    prior_phase_outputs: dict = dict(cp.get("prior_phase_outputs") or {})
    workflow_registry: dict = dict(cp.get("workflow_registry") or {})

    phases_info_raw = ctx.get("phases_info") or []
    phases_info: list[tuple[str, str, str, list[LogicalStep], str]] = []
    for item in phases_info_raw:
        steps = [LogicalStep.model_validate(s) for s in (item.get("steps") or [])]
        phases_info.append((
            item.get("phaseId") or "phase_1",
            item.get("phaseName") or "Phase",
            item.get("phaseDescription") or "",
            steps,
            item.get("phaseType") or "FREEZE",
        ))

    if not phases_info and mode == "prompt" and (ctx.get("prompt") or "").strip():
        prompt_text = (ctx.get("prompt") or "").strip()
        prompt_steps, analysis_source = await _resolve_prompt_preview_steps(
            prompt=prompt_text,
            stage0_planner_context=stage0_planner_context,
            handoff_steps=[],
            api_key=api_key,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            project_id=process_id,
            warnings=all_warnings,
        )
        phases_info = [(
            "phase_1",
            workflow_name,
            prompt_text,
            prompt_steps,
            "FREEZE",
        )]
        ctx = {
            **ctx,
            "analysis_source": analysis_source,
            "phases_info": [
                {
                    "phaseId": "phase_1",
                    "phaseName": workflow_name,
                    "phaseDescription": prompt_text,
                    "phaseType": "FREEZE",
                    "steps": [s.model_dump() for s in prompt_steps],
                }
            ],
        }

    phase_index_start = int(cp.get("phase_index") or 0)
    scratch_resume = cp.get("scratch_state") or {}
    last_scratch_checkpoint: Optional[dict] = scratch_resume or None

    async def _write_preview_build_checkpoint(
        *,
        status: str,
        phase_index: int,
        scratch_state: Optional[dict] = None,
        last_error: Optional[dict] = None,
    ) -> None:
        try:
            await asyncio.to_thread(
                write_checkpoint,
                db=db,
                workflow_id=process_id,
                subscriber_id=subscriber_id,
                org_id=org_id,
                user_id=user_id,
                status=status,
                pipeline_stage="preview",
                phase_index=phase_index,
                phase_total=len(phases_info),
                phase_graphs=_serialize_phase_graph_results(phase_results),
                prior_phase_outputs=prior_phase_outputs,
                workflow_registry=workflow_registry,
                scratch_state=scratch_state,
                request_context=ctx,
                last_error=last_error,
                warnings=all_warnings,
            )
            if status == "paused_credit":
                await asyncio.to_thread(
                    set_workflow_agentic_status,
                    db=db,
                    workflow_id=process_id,
                    subscriber_id=subscriber_id,
                    org_id=org_id,
                    user_id=user_id,
                    status="paused_credit",
                )
        except Exception as exc:
            logger.warning(
                "[scratch/preview/resume] Checkpoint write failed (non-fatal): %s", exc
            )
            all_warnings.append(f"Checkpoint write failed (preview still returned): {exc}")

    all_steps_flat: list[LogicalStep] = []
    for _, _, _, phase_steps, _ in phases_info:
        all_steps_flat.extend(phase_steps)

    try:
        for phase_index in range(phase_index_start, len(phases_info)):
            phase_id, phase_name, phase_desc, phase_steps, phase_type = phases_info[phase_index]
            phase_warnings: list[str] = []
            resume_state_snapshot = None
            resume_sub_stage = None
            resume_batch_index = None
            resume_completed_router_results = None
            if phase_index == phase_index_start and scratch_resume:
                resume_state_snapshot = scratch_resume.get("state_snapshot")
                resume_sub_stage = scratch_resume.get("sub_stage")
                resume_batch_index = scratch_resume.get("batch_index")
                resume_completed_router_results = scratch_resume.get("completed_router_results")

            async def _preview_checkpoint(
                state,
                sub_stage: str,
                batch_index: Optional[int] = None,
                router_id: Optional[str] = None,
                completed_router_results: Optional[list] = None,
                *,
                _phase_index: int = phase_index,
                _phase_id: str = phase_id,
            ):
                nonlocal last_scratch_checkpoint
                scratch_payload = {
                    "phase_id": _phase_id,
                    "sub_stage": sub_stage,
                    "batch_index": batch_index,
                    "router_id": router_id,
                    "completed_router_results": completed_router_results,
                    "state_snapshot": state.model_dump(mode="json"),
                }
                last_scratch_checkpoint = scratch_payload
                await _write_preview_build_checkpoint(
                    status="building",
                    phase_index=_phase_index,
                    scratch_state=scratch_payload,
                )

            try:
                scratch_dict = await plan_phase_graph_scratch(
                    phase_id=phase_id,
                    phase_name=phase_name,
                    phase_description=phase_desc,
                    steps=phase_steps,
                    prior_phase_outputs=prior_phase_outputs or None,
                    workflow_registry=workflow_registry or None,
                    stage0_context=stage0_planner_context or None,
                    api_key=api_key,
                    project_id=project_id_for_gen,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    collection_metadata=request.collectionMetadata,
                    run_gap_resolution=False,
                    run_code_emission=False,
                    checkpoint_fn=_preview_checkpoint,
                    resume_state_snapshot=resume_state_snapshot,
                    resume_sub_stage=resume_sub_stage,
                    resume_batch_index=resume_batch_index,
                    resume_completed_router_results=resume_completed_router_results,
                )
                scratch_warnings = scratch_dict.pop("_planningWarnings", [])
                scratch_dict.pop("_stateSchema", None)
                scratch_dict.pop("_langgraphCode", None)
                workflow_registry = scratch_dict.pop("_workflowRegistry", workflow_registry) or workflow_registry
                phase_warnings.extend(scratch_warnings)
                graph = GraphDefinition(**scratch_dict)
            except BillingError as exc:
                scratch_err: Dict[str, Any] = {
                    "code": exc.code,
                    "phase_id": phase_id,
                    "at": datetime.utcnow().isoformat(),
                }
                if last_scratch_checkpoint:
                    for key in ("sub_stage", "batch_index", "router_id"):
                        val = last_scratch_checkpoint.get(key)
                        if val is not None:
                            scratch_err[key] = val
                await _write_preview_build_checkpoint(
                    status="paused_credit",
                    phase_index=phase_index,
                    scratch_state=last_scratch_checkpoint,
                    last_error=scratch_err,
                )
                _pause_detail = _billing_pause_error(
                    exc, workflow_id=process_id, subscriber_id=subscriber_id
                )
                await _publish_paused_credit(process_id, _pause_detail)
                raise HTTPException(
                    status_code=402,
                    detail=_pause_detail,
                ) from exc

            for node in graph.nodes:
                if node.type in ("router", "fallback_router", "end") or not node.nodeId:
                    continue
                safe_nid = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
                prior_phase_outputs[safe_nid] = _declared_outputs_as_prior_phase_entries(node)

            if phase_index < len(phase_results):
                phase_results[phase_index] = PhaseGraphResult(
                    graph=copy.deepcopy(graph),
                    validation_warnings=phase_warnings,
                    binding_fixes_applied=phase_results[phase_index].binding_fixes_applied,
                    phaseType=phase_type,
                )
            else:
                phase_results.append(PhaseGraphResult(
                    graph=copy.deepcopy(graph),
                    validation_warnings=phase_warnings,
                    binding_fixes_applied=0,
                    phaseType=phase_type,
                ))
            await _write_preview_build_checkpoint(
                status="building",
                phase_index=phase_index + 1,
            )
    except HTTPException:
        raise

    # Persist preview result (same as agentic_plan_scratch_preview success path)
    def _tenant_query() -> Dict[str, Any]:
        q: Dict[str, Any] = {}
        for key, raw in (
            ("orgId", org_id),
            ("subscriberId", subscriber_id),
            ("userId", user_id),
        ):
            if raw is None:
                continue
            try:
                q[key] = ObjectId(raw) if isinstance(raw, str) else raw
            except Exception:
                q[key] = raw
        return q

    engine_type = "agentic_graph"
    persisted_steps_nested: list[Dict[str, Any]] = [
        {
            "stepId": pid or f"phase_{i + 1}",
            "name": pname or f"Phase {i + 1}",
            "description": pdesc or pname or "",
            "phaseType": ptype,
            "subSteps": [
                {
                    "stepId": s.stepId,
                    "name": s.name,
                    "description": s.description,
                    "inputs": list(s.inputs),
                    "outputs": list(s.outputs),
                }
                for s in (psteps or [])
            ],
        }
        for i, (pid, pname, pdesc, psteps, ptype) in enumerate(phases_info)
    ]

    try:
        now = datetime.utcnow()
        coll = db["Process_Configs"]
        coll.update_one(
            {
                **_tenant_query(),
                "engineType": engine_type,
                "agentic_process.workflow_id": process_id,
            },
            {
                "$set": {
                    **_tenant_query(),
                    "engineType": engine_type,
                    "selectedName": ctx.get("selectedName"),
                    "selectedType": ctx.get("selectedType"),
                    "selectedCategory": ctx.get("selectedCategory"),
                    "token": ctx.get("token"),
                    "updated_at": now,
                    "agentic_process": {
                        "workflow_id": process_id,
                        "workflowName": workflow_name,
                        "projectId": ctx.get("project_id_for_gen"),
                        "mode": mode,
                        "analysis_source": analysis_source,
                        "prompt": ctx.get("prompt"),
                        "steps": persisted_steps_nested,
                        "phaseGraphs": _serialize_phase_graph_results(phase_results),
                        "warnings": all_warnings,
                        "estimatedCredits": 0,
                        "planner": "scratch",
                        "status": "preview",
                    },
                },
                "$setOnInsert": {"created_at": now},
            },
            upsert=True,
        )
    except Exception as _e:
        all_warnings.append(f"Failed to persist scratch preview in Process_Configs: {_e}")

    delete_checkpoint(db=db, workflow_id=process_id, subscriber_id=subscriber_id)

    return AgenticPlanPreviewResponse(
        workflowId=process_id,
        workflowName=workflow_name,
        steps=all_steps_flat,
        mode=mode,
        analysis_source=analysis_source,
        warnings=all_warnings,
        stepCapabilities=[],
        phaseGraphs=phase_results,
        estimatedCredits=0,
        estimatedCreditsBreakdown=[],
        generateNodeCount=0,
        uiScreenNodeCount=0,
        toolNodeCount=0,
    )


@app.post("/aiqod-agent/agent/agentic/workflow/resume")
async def workflow_resume(
    request: WorkflowResumeRequest,
    http_request: Request,
):
    """
    Resume a paused_credit workflow build. Returns the same response shape as the
    paused endpoint (stage0 / scratch/preview / execute).
    """
    _resume_log = "[workflow/resume]"
    _t_resume_start = time.monotonic()
    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId
    workflow_id = request.workflowId.strip()

    logger.info(
        "%s request received workflow_id=%s subscriber_id=%s org_id=%s user_id=%s",
        _resume_log,
        workflow_id,
        subscriber_id,
        org_id,
        user_id,
    )

    if not subscriber_id:
        raise HTTPException(status_code=400, detail="subscriberId is required.")
    if not workflow_id:
        raise HTTPException(status_code=400, detail="workflowId is required.")

    cp = read_checkpoint(db=db, workflow_id=workflow_id, subscriber_id=subscriber_id)
    cp_paused = cp is not None and cp.get("status") == "paused_credit"
    logger.info(
        "%s checkpoint lookup workflow_id=%s found=%s paused_credit=%s pipeline_stage=%s phase_index=%s",
        _resume_log,
        workflow_id,
        cp is not None,
        cp_paused,
        (cp or {}).get("pipeline_stage"),
        (cp or {}).get("phase_index"),
    )

    # Fallback: check the durable creditPauseStatus field in Process_Configs.
    # This handles cases where the checkpoint was not yet written (budget exhausted
    # before the checkpoint write) or was cleaned up, but the billing pause state
    # was recorded. External job runners only touch agentic_process.* fields and
    # never write creditPauseStatus, so this field is race-condition-safe.
    pc_doc_for_pause = None
    if not cp_paused:
        pc_doc_for_pause = db[PROCESS_CONFIGS_COLLECTION].find_one(
            _process_configs_query(
                project_id=workflow_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
            ),
            {"creditPauseStatus": 1},
        )
        if pc_doc_for_pause is None:
            # Try broader query in case org/user headers are missing.
            try:
                from bson import ObjectId as _ObjectId
                _sub_val: Any = _ObjectId(subscriber_id)
            except Exception:
                _sub_val = subscriber_id
            pc_doc_for_pause = db[PROCESS_CONFIGS_COLLECTION].find_one(
                {
                    "engineType": "agentic_graph",
                    "agentic_process.workflow_id": workflow_id,
                    "subscriberId": _sub_val,
                },
                {"creditPauseStatus": 1},
            )
        credit_pause_status = (pc_doc_for_pause or {}).get("creditPauseStatus")
        if credit_pause_status != "paused_credit":
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": (
                        "Workflow is not in paused_credit state. "
                        "No checkpoint and no creditPauseStatus found."
                    ),
                    "workflowId": workflow_id,
                },
            )
        # creditPauseStatus confirms budget exhaustion but there is no checkpoint —
        # the workflow cannot be resumed mid-phase; it must be re-executed.
        raise HTTPException(
            status_code=400,
            detail={
                "success": False,
                "error": (
                    "Workflow was paused for credit exhaustion but no resume checkpoint "
                    "is available (it may not have been written before the pause, or was "
                    "cleaned up). Please add credits and re-execute the workflow from the start."
                ),
                "workflowId": workflow_id,
                "creditPauseStatus": "paused_credit",
                "resumeEndpoint": RESUME_ENDPOINT,
            },
        )

    # ── Concurrency guard: atomically claim this paused workflow ----
    _resume_claim = db["workflow_build_checkpoints"].find_one_and_update(
        {
            "workflow_id": workflow_id,
            "subscriber_id": subscriber_id,
            "status": "paused_credit"
        },
        {"$set": {"status": "resuming"}}
    )

    if _resume_claim is None:
        _resume_claim = db[PROCESS_CONFIGS_COLLECTION].find_one_and_update(
            _process_configs_query(
                project_id=workflow_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
            )
            | {"creditPauseStatus": "paused_credit"},
            {"$set": {"creditPauseStatus": "resuming"}},
        )

    if _resume_claim is None:
        logger.info(
            "%s resume claim lost or already resumed workflow_id=%s",
            _resume_log,
            workflow_id,
        )
        raise HTTPException(
            status_code=409,
            detail={
                "success": False,
                "error": "Workflow is not paused, or a resume is already in progress.",
                "workflowId": workflow_id,
            },
        )
    logger.info("%s resume claim acquired workflow_id=%s", _resume_log, workflow_id)

    try:
        init_billing_for_resume(
            project_id=workflow_id,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )
        logger.info(
            "%s billing initialized workflow_id=%s elapsed=%.2fs",
            _resume_log,
            workflow_id,
            time.monotonic() - _t_resume_start,
        )
    except BillingError as exc:
        logger.warning(
            "%s billing init failed workflow_id=%s code=%s elapsed=%.2fs",
            _resume_log,
            workflow_id,
            exc.code,
            time.monotonic() - _t_resume_start,
        )
        raise HTTPException(
            status_code=402,
            detail=_billing_pause_error(
                exc, workflow_id=workflow_id, subscriber_id=subscriber_id
            ),
        ) from exc

    pipeline_stage = cp.get("pipeline_stage") or "preview"
    logger.info(
        "%s routing pipeline_stage=%s workflow_id=%s elapsed=%.2fs",
        _resume_log,
        pipeline_stage,
        workflow_id,
        time.monotonic() - _t_resume_start,
    )
    if pipeline_stage == "stage0":
        logger.info("%s delegating to stage0 resume workflow_id=%s", _resume_log, workflow_id)
        result = await _resume_stage0_from_checkpoint(cp)
        logger.info(
            "%s stage0 resume complete workflow_id=%s elapsed=%.2fs — returning HTTP response",
            _resume_log,
            workflow_id,
            time.monotonic() - _t_resume_start,
        )
        return result
    if pipeline_stage == "preview":
        logger.info("%s delegating to preview resume workflow_id=%s", _resume_log, workflow_id)
        result = await _resume_scratch_preview_from_checkpoint(
            cp,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )
        logger.info(
            "%s preview resume complete workflow_id=%s elapsed=%.2fs — returning HTTP response",
            _resume_log,
            workflow_id,
            time.monotonic() - _t_resume_start,
        )
        return result
    if pipeline_stage == "execute":
        exec_request = _build_execute_resume_request(cp)
        exec_request.orgId = org_id or exec_request.orgId
        exec_request.subscriberId = subscriber_id
        exec_request.userId = user_id or exec_request.userId
        logger.info(
            "%s delegating to execute resume workflow_id=%s resume_phase_index=%s "
            "completed_phases=%s remaining_phases=%s elapsed=%.2fs",
            _resume_log,
            workflow_id,
            exec_request.resumePhaseIndex,
            len(exec_request.resumeCompletedPhaseGraphs or []),
            len(exec_request.phaseGraphs or []),
            time.monotonic() - _t_resume_start,
        )
        result = await agentic_plan_execute(exec_request, http_request)
        logger.info(
            "%s execute resume complete workflow_id=%s phase_graphs=%s warnings=%s "
            "elapsed=%.2fs — returning HTTP response",
            _resume_log,
            workflow_id,
            len(result.phaseGraphs or []),
            len(result.warnings or []),
            time.monotonic() - _t_resume_start,
        )
        return result
    if pipeline_stage == "plan_update":
        logger.info("%s delegating to plan_update resume workflow_id=%s", _resume_log, workflow_id)
        # Re-call the update endpoint with the same payload from checkpoint
        # The checkpoint stores the original request in request_context
        request_context = cp.get("request_context") or {}
        # Build the update payload from the checkpoint context
        from types import SimpleNamespace
        # Convert dict to WorkflowUpdatePayload-compatible object
        # We need to call update_workflow_plan with the same payload
        # Since update_workflow_plan expects a payload object, we'll reconstruct it
        resume_payload = WorkflowUpdatePayload(**request_context)
        result = await update_workflow_plan(resume_payload, http_request)
        logger.info(
            "%s plan_update resume complete workflow_id=%s elapsed=%.2fs — returning HTTP response",
            _resume_log,
            workflow_id,
            time.monotonic() - _t_resume_start,
        )
        return result

    raise HTTPException(
        status_code=400,
        detail=f"Unknown pipeline_stage {pipeline_stage!r} in checkpoint.",
    )


@app.get("/aiqod-agent/agent/agentic/workflow/stream/{workflow_id}")
async def workflow_status_stream(
    workflow_id: str,
    http_request: Request,
    subscriberId: Optional[str] = None,
):
    """
    Real-time workflow status via SSE. Scoped to scratch/preview and execute
    only (see _publish_paused_credit / _publish_workflow_terminal call sites);
    Stage0 is not wired here as it is always a synchronous FE-initiated call.
    Multiple concurrent connections for the same workflowId are supported —
    each gets its own snapshot read and its own live queue (fan-out).
    """
    org_id = http_request.headers.get("x-org-id")
    subscriber_id = subscriberId or http_request.headers.get("x-subscriber-id")

    async def event_generator():
        # --- Step 1: connect-time snapshot (catch-up) ---
        try:
            cp = read_checkpoint(db=db, workflow_id=workflow_id, subscriber_id=subscriber_id)
            if cp is not None and cp.get("status") == "paused_credit":
                snapshot_detail = enrich_billing_error_detail(
                    cp.get("last_error") or {},
                    db=db,
                    workflow_id=workflow_id,
                    subscriber_id=subscriber_id,
                )
                snapshot_detail.setdefault("workflowId", workflow_id)
                snapshot_detail.setdefault("pipelineStage", cp.get("pipeline_stage"))
                snapshot_detail.setdefault("phaseIndex", cp.get("phase_index"))
                yield f"data: {json.dumps({'type': 'paused_credit', **snapshot_detail})}\n\n"
        except Exception:
            logger.exception(
                "workflow_stream snapshot read failed workflow_id=%s", workflow_id
            )

        # --- Step 2: live tail ---
        q = await workflow_stream_registry.subscribe(workflow_id)
        try:
            while True:
                try:
                    event = await asyncio.wait_for(q.get(), timeout=15)
                except asyncio.TimeoutError:
                    yield ": heartbeat\n\n"
                    continue
                yield f"data: {json.dumps(event)}\n\n"
                if event.get("type") in TERMINAL_EVENT_TYPES:
                    break
        finally:
            await workflow_stream_registry.unsubscribe(workflow_id, q)

    return StreamingResponse(event_generator(), media_type="text/event-stream")


@app.post("/aiqod-agent/agent/agentic/plan/execute", response_model=AgenticPlanResponse)
async def agentic_plan_execute(request: AgenticPlanExecuteRequest, http_request: Request) -> AgenticPlanResponse:
    """
    Phase 2 of the two-phase agentic planning pipeline.

    Accepts the validated phaseGraphs returned by /agentic/plan/scratch/preview
    (GENERATE:* nodes still intact) and executes:
      7+8. Gap resolution  — GENERATE:* → ui_screen (Angular codegen) | tool (LLM + registry)
      6p.  Post-gap re-validation
           Tool node enrichment (source / class_path metadata)
      9.   LangGraph code generation (per-phase + combined)
    """
    api_key = get_gemini_api_key()

    org_id = request.orgId or http_request.headers.get("x-org-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")

    if not subscriber_id:
        raise HTTPException(
            status_code=400,
            detail="subscriberId is required.",
        )

    def _tenant_query() -> Dict[str, Any]:
        q: Dict[str, Any] = {}
        for key, raw in (
            ("orgId", org_id),
            ("subscriberId", subscriber_id),
            ("userId", user_id),
        ):
            if raw is None:
                continue
            try:
                q[key] = ObjectId(raw) if isinstance(raw, str) else raw
            except Exception:
                q[key] = raw
        return q

    tenant: Dict[str, Optional[str]] = {
        "orgId": org_id,
        "subscriberId": subscriber_id,
        "userId": user_id,
    }
    engine_type = "agentic_graph"
    process_id = (request.projectId or request.workflowId).strip()
    workflow_name = request.workflowName or request.selectedName or "workflow"
    all_warnings: list[str] = []
    mode = request.mode
    analysis_source = request.analysis_source
    _is_resume = request.resumeCompletedPhaseGraphs is not None
    _exec_log = "[execute/resume]" if _is_resume else "[execute]"
    _t_execute_start = time.monotonic()
    logger.info(
        "%s start process_id=%s workflow_name=%s resume=%s resume_phase_index=%s "
        "total_phase_graphs=%s",
        _exec_log,
        process_id,
        workflow_name,
        _is_resume,
        request.resumePhaseIndex,
        len(request.phaseGraphs or []),
    )

    if get_billing_context() is None:
        _init_agentic_workflow_billing(
            project_id=request.projectId,
            workflow_id=request.workflowId,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )
    if subscriber_id and not request.resumeCompletedPhaseGraphs:
        set_workflow_agentic_status(
            db=db,
            workflow_id=process_id,
            subscriber_id=subscriber_id,
            org_id=org_id,
            user_id=user_id,
            status="building",
        )

    logger.info(
        "%s entering billing scope process_id=%s elapsed=%.2fs",
        _exec_log,
        process_id,
        time.monotonic() - _t_execute_start,
    )
    async with workflow_reservation_release_scope(
        project_id=process_id,
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
    ):
        logger.info(
            "%s inside billing scope process_id=%s elapsed=%.2fs",
            _exec_log,
            process_id,
            time.monotonic() - _t_execute_start,
        )
        # Fetch credentials for gap-generation LLM context.
        plan_available_credentials: List[Dict[str, Any]] = []
        _plan_cred_svc = CredentialService.optional()
        if _plan_cred_svc and request.projectId:
            try:
                plan_available_credentials = await _plan_cred_svc.list_credentials(
                    request.projectId,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                )
                if not plan_available_credentials and (org_id or subscriber_id):
                    plan_available_credentials = await _plan_cred_svc.list_credentials(request.projectId)
                logger.info(
                    f"[agentic/plan/execute] Loaded {len(plan_available_credentials)} credential(s) "
                    f"for project='{request.projectId}'."
                )
            except Exception as _cred_err:
                logger.warning(f"[agentic/plan/execute] Failed to list credentials: {_cred_err}")

        project_id_for_gen = request.projectId or process_id

        def _save_process_to_process_configs(
            *,
            phase_results_local: list[PhaseGraphResult],
            persisted_steps_nested: list[Dict[str, Any]],
            warnings_local: list[str],
            combined_file_path_local: Optional[str],
            reports_local: Optional[list[Dict[str, Any]]] = None,
            dashboard_screen_id_local: Optional[str] = None,
            dashboard_url_local: Optional[str] = None,
        ) -> None:
            _t_save = time.monotonic()
            logger.info(
                "%s _save_process_to_process_configs start process_id=%s phases=%s steps=%s",
                _exec_log,
                process_id,
                len(phase_results_local),
                len(persisted_steps_nested),
            )
            import os as _os
            if combined_file_path_local:
                combined_file_path_local = _os.path.abspath(combined_file_path_local)
            now = datetime.utcnow()
            coll = db["Process_Configs"]
            query = {
                **_tenant_query(),
                "engineType": engine_type,
                "agentic_process.workflow_id": process_id,
            }
            process_doc = {
                "workflow_id": process_id,
                "workflowName": workflow_name,
                "projectId": request.projectId,
                "mode": mode,
                "analysis_source": analysis_source,
                "prompt": request.prompt,
                "steps": persisted_steps_nested,
                "phaseGraphs": [p.model_dump(exclude={"langgraph_code"}) for p in phase_results_local],
                "combined_file_path": combined_file_path_local,
                "warnings": warnings_local,
                "status": "draft",
                "version": 1,
                "suggestedReports": request.suggestedReports or [],
                "reports": reports_local or [],
                "dashboardScreenId": dashboard_screen_id_local,
                "allCollections": request.allCollections or [],
                "collectionMetadata": request.collectionMetadata or [],
                "kgSelectedCollections": request.kgSelectedCollections or [],
                "dashboardUrl": dashboard_url_local,
            }
            coll.update_one(
                query,
                {
                    "$set": {
                        **_tenant_query(),
                        "engineType": engine_type,
                        "selectedName": request.selectedName,
                        "selectedType": request.selectedType,
                        "selectedCategory": request.selectedCategory,
                        "token": request.token,
                        "updated_at": now,
                        "agentic_process": process_doc,
                    },
                    "$unset": {
                        "engineVersion": "",
                        "schemaVersion": "",
                    },
                    "$setOnInsert": {
                        "created_at": now,
                    },
                },
                upsert=True,
            )
            logger.info(
                "%s _save_process_to_process_configs done process_id=%s duration=%.2fs",
                _exec_log,
                process_id,
                time.monotonic() - _t_save,
            )

        async def _upsert_agentic_workflow_capability(
            *,
            workflow_id: str,
            phase_results_local: list[PhaseGraphResult],
        ) -> None:
            _t_cap = time.monotonic()
            logger.info(
                "%s _upsert_agentic_workflow_capability start workflow_id=%s phases=%s",
                _exec_log,
                workflow_id,
                len(phase_results_local),
            )
            phase_names = [
                (pr.graph.phaseName or pr.graph.phaseId or "").strip()
                for pr in phase_results_local
                if getattr(pr, "graph", None) is not None
            ]
            phase_names = [p for p in phase_names if p]
            if request.prompt and request.prompt.strip():
                desc_core = request.prompt.strip()
            elif phase_names:
                desc_core = f"Agentic workflow with phases: {', '.join(phase_names)}"
            else:
                desc_core = f"Agentic workflow {workflow_name}"

            capability_id = f"agent:workflow:{workflow_id}"
            capability_doc: Dict[str, Any] = {
                "capabilityId": capability_id,
                "kind": "agent",
                "name": workflow_name,
                "description": desc_core,
                "inputParameters": [],
                "outputParameters": [],
                "version": "1",
                "isLatest": True,
                "status": "active",
                "source": {
                    "sourceType": "workflow_details",
                    "sourceRef": {"workflowId": workflow_id},
                    "sourceUpdatedAt": datetime.utcnow(),
                    "syncedAt": datetime.utcnow(),
                },
                "runtime": {
                    "agent": {
                        "workflowId": workflow_id,
                        "workflowName": workflow_name,
                        "agentState": "stable",
                    }
                },
                "searchText": f"{workflow_name} {desc_core}".strip(),
                "tags": ["agentic", "graph", "workflow"],
            }
            await capability_repository.upsert_capability(tenant, capability_doc)
            await capability_repository.set_is_latest_for_capability(tenant, capability_id)
            logger.info(
                "%s _upsert_agentic_workflow_capability done workflow_id=%s duration=%.2fs",
                _exec_log,
                workflow_id,
                time.monotonic() - _t_cap,
            )

        # ── Steps 7+8, 6p, enrichment: per-phase gap resolution ──────────────────
        if request.resumeCompletedPhaseGraphs is not None:
            completed_phase_results = list(request.resumeCompletedPhaseGraphs)
            start_phase_index = request.resumePhaseIndex or len(completed_phase_results)
            # phaseGraphs from _build_execute_resume_request is already trimmed to
            # remaining work (in-progress + later phases). Do not re-slice by
            # start_phase_index or between-phase resumes skip every remaining phase.
            graphs_to_process = request.phaseGraphs
            logger.info(
                "%s resume state loaded process_id=%s completed_phases=%s "
                "start_phase_index=%s graphs_to_process=%s",
                _exec_log,
                process_id,
                len(completed_phase_results),
                start_phase_index,
                len(graphs_to_process),
            )
        else:
            completed_phase_results = []
            start_phase_index = 0
            graphs_to_process = request.phaseGraphs

        prior_phase_outputs: dict = {}

        if completed_phase_results:
            for done_pr in completed_phase_results:
                for node in done_pr.graph.nodes:
                    if node.type in ("router", "fallback_router", "end") or not node.nodeId:
                        continue
                    safe_nid = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
                    prior_phase_outputs[safe_nid] = _declared_outputs_as_prior_phase_entries(node)

        execute_request_context = request.model_dump(
            mode="json",
            exclude={"resumePhaseIndex", "resumeCompletedPhaseGraphs"},
        )
        last_execute_snapshot: Dict[str, Any] = {
            "phase_index": start_phase_index if request.resumeCompletedPhaseGraphs else 0,
            "phase_graphs": [],
            "prior_phase_outputs": {},
            "phase_id": None,
            "node_id": None,
        }

        async def _write_execute_build_checkpoint(
            *,
            status: str,
            phase_index: int,
            phase_graphs_snapshot: list,
            prior_outputs: dict,
            last_error: Optional[dict] = None,
            current_node_id: Optional[str] = None,
        ) -> None:
            _t_cp = time.monotonic()
            logger.info(
                "%s write_checkpoint start process_id=%s status=%s phase_index=%s "
                "snapshot_phases=%s current_node_id=%s",
                _exec_log,
                process_id,
                status,
                phase_index,
                len(phase_graphs_snapshot),
                current_node_id,
            )
            # Run sync PyMongo writes in a thread so the event loop is never blocked.
            # Blocking the event loop freezes Starlette 0.50's anyio MemoryObjectSendStream
            # and the HTTP response is never delivered even after all work completes.
            try:
                await asyncio.to_thread(
                    write_checkpoint,
                    db=db,
                    workflow_id=process_id,
                    subscriber_id=subscriber_id,
                    org_id=org_id,
                    user_id=user_id,
                    status=status,
                    pipeline_stage="execute",
                    phase_index=phase_index,
                    phase_total=len(request.phaseGraphs),
                    phase_graphs=phase_graphs_snapshot,
                    prior_phase_outputs=prior_outputs,
                    request_context=execute_request_context,
                    last_error=last_error,
                    warnings=all_warnings,
                    current_node_id=current_node_id,
                )
            except Exception as cp_exc:
                # Progress UI depends on checkpoints; do not abort the build if Mongo blips.
                logger.warning(
                    "%s write_checkpoint failed (non-fatal) process_id=%s error=%s",
                    _exec_log,
                    process_id,
                    cp_exc,
                )
                return
            if status == "paused_credit":
                await asyncio.to_thread(
                    set_workflow_agentic_status,
                    db=db,
                    workflow_id=process_id,
                    subscriber_id=subscriber_id,
                    org_id=org_id,
                    user_id=user_id,
                    status="paused_credit",
                )
            logger.info(
                "%s write_checkpoint done process_id=%s status=%s phase_index=%s duration=%.2fs",
                _exec_log,
                process_id,
                status,
                phase_index,
                time.monotonic() - _t_cp,
            )

        try:
            for offset, pr in enumerate(graphs_to_process):
                phase_index = start_phase_index + offset
                graph = pr.graph
                phase_id = graph.phaseId or "unknown_phase"
                _t_phase = time.monotonic()
                logger.info(
                    "%s phase start process_id=%s phase_id=%s phase_index=%s offset=%s nodes=%s",
                    _exec_log,
                    process_id,
                    phase_id,
                    phase_index,
                    offset,
                    len(graph.nodes or []),
                )
                phase_type = pr.phaseType
                user_context = graph.description or graph.goal or graph.phaseName or phase_id
            # Carry forward any validation warnings from the preview phase.
                phase_warnings: list[str] = list(pr.validation_warnings)
                last_execute_snapshot["phase_id"] = phase_id
                last_execute_snapshot["phase_index"] = phase_index

                phase_start_snapshot = _serialize_phase_graph_results(completed_phase_results) + [
                    PhaseGraphResult(
                        graph=copy.deepcopy(graph),
                        validation_warnings=list(phase_warnings),
                        binding_fixes_applied=pr.binding_fixes_applied,
                        phaseType=phase_type,
                    ).model_dump(exclude={"langgraph_code"})
                ]
                last_execute_snapshot["phase_graphs"] = phase_start_snapshot
                last_execute_snapshot["prior_phase_outputs"] = dict(prior_phase_outputs)
                # Write immediately so /workflow/progress can show pipelineStage=execute
                # before the first gap node finishes (can take many minutes).
                await _write_execute_build_checkpoint(
                    status="building",
                    phase_index=phase_index,
                    phase_graphs_snapshot=phase_start_snapshot,
                    prior_outputs=prior_phase_outputs,
                    current_node_id=None,
                )

                async def _gap_node_start(node_id: str) -> None:
                    last_execute_snapshot["node_id"] = node_id or None
                    await _write_execute_build_checkpoint(
                        status="building",
                        phase_index=phase_index,
                        phase_graphs_snapshot=last_execute_snapshot["phase_graphs"],
                        prior_outputs=prior_phase_outputs,
                        current_node_id=node_id or None,
                    )

                async def _node_checkpoint(
                    in_progress_graph: GraphDefinition,
                    resolved_node_id: str,
                    *,
                    _phase_index: int = phase_index,
                    _phase_type: str = phase_type,
                    _phase_warnings: list[str] = phase_warnings,
                    _binding_fixes: int = pr.binding_fixes_applied,
                ) -> None:
                    in_progress = PhaseGraphResult(
                        graph=copy.deepcopy(in_progress_graph),
                        validation_warnings=list(_phase_warnings),
                        binding_fixes_applied=_binding_fixes,
                        phaseType=_phase_type,
                    )
                    snapshot = _serialize_phase_graph_results(completed_phase_results) + (
                        _serialize_phase_graph_results([in_progress])
                    )
                    last_execute_snapshot["phase_index"] = _phase_index
                    last_execute_snapshot["phase_graphs"] = snapshot
                    last_execute_snapshot["prior_phase_outputs"] = dict(prior_phase_outputs)
                    last_execute_snapshot["node_id"] = resolved_node_id
                    await _write_execute_build_checkpoint(
                        status="building",
                        phase_index=_phase_index,
                        phase_graphs_snapshot=snapshot,
                        prior_outputs=prior_phase_outputs,
                        current_node_id=resolved_node_id,
                    )

            # ── Steps 7+8: Gap resolution ─────────────────────────────────────────
                try:
                    graph, gen_ids = await _resolve_gap_generations(
                        graph,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                        project_id=project_id_for_gen,
                        available_credentials=plan_available_credentials,
                        node_checkpoint_fn=_node_checkpoint,
                        node_gap_start_fn=_gap_node_start,
                    )
                except UnresolvedGapGenerationError as gap_err:
                    raise HTTPException(
                        status_code=422,
                        detail={
                            "error": "unresolved_gap_generation",
                            "phaseId": gap_err.phase_id or phase_id,
                            "message": str(gap_err),
                            "unresolvedNodes": gap_err.unresolved,
                            "failures": gap_err.failures,
                        },
                    ) from gap_err
                logger.info(f"[execute] Phase '{phase_id}': {len(gen_ids)} gap(s) resolved.")

            # ── Step 6p: Post-gap re-validation ────────────────────────────────────
                if gen_ids:
                    graph = await _revalidate_after_gap_gen(
                        graph, gen_ids,
                        user_context=user_context,
                        global_caps=[],  # kept for call-site compat; not used internally
                        max_rounds=2,
                        project_id=project_id_for_gen,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                        api_key=api_key,
                        available_credentials=plan_available_credentials,
                    )
                    logger.info(f"[execute] Phase '{phase_id}': post-gap re-validation complete.")

            # ── Tool node enrichment ───────────────────────────────────────────────
                graph = await _enrich_tool_nodes_with_source_and_class_path(graph, tenant=tenant)

                # Update cross-phase output registry for subsequent phases.
                for node in graph.nodes:
                    if node.type in ("router", "fallback_router", "end") or not node.nodeId:
                        continue
                    safe_nid = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
                    prior_phase_outputs[safe_nid] = _declared_outputs_as_prior_phase_entries(node)

                completed_phase_results.append(PhaseGraphResult(
                    graph=copy.deepcopy(graph),
                    validation_warnings=phase_warnings,
                    binding_fixes_applied=pr.binding_fixes_applied,
                    gap_generations=gen_ids,
                    phaseType=phase_type,
                ))
                phase_snapshot = _serialize_phase_graph_results(completed_phase_results)
                last_execute_snapshot["phase_index"] = phase_index + 1
                last_execute_snapshot["phase_graphs"] = phase_snapshot
                last_execute_snapshot["prior_phase_outputs"] = dict(prior_phase_outputs)
                await _write_execute_build_checkpoint(
                    status="building",
                    phase_index=phase_index + 1,
                    phase_graphs_snapshot=phase_snapshot,
                    prior_outputs=prior_phase_outputs,
                )
                logger.info(
                    "%s phase complete process_id=%s phase_id=%s phase_index=%s "
                    "gaps_resolved=%s duration=%.2fs elapsed=%.2fs",
                    _exec_log,
                    process_id,
                    phase_id,
                    phase_index,
                    len(gen_ids),
                    time.monotonic() - _t_phase,
                    time.monotonic() - _t_execute_start,
                )
                

        # ── Dashboard report screen generation ────────────────────────────────
        # Generates a single Angular dashboard screen with one widget per
        # suggested report, each wired to its own real MongoDB find/aggregate
        # backend function (no mock data). Runs after gap resolution so it
        # never blocks or fails the underlying workflow — failures are recorded
        # as warnings and the workflow still completes successfully (graceful
        # degradation).
            dashboard_reports_out: list[Dict[str, Any]] = []
            dashboard_screen_id: Optional[str] = None
            dashboard_url: Optional[str] = None
            if request.suggestedReports:
                try:
                    dash_result = await dashboard_router.generate_dashboard_screens_for_reports(
                        workflow_id=request.workflowId,
                        project_id=project_id_for_gen,
                        reports=request.suggestedReports,
                        dashboard_name=workflow_name,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                    )
                    dashboard_reports_out = [
                        {
                            "reportId": f"report_{i + 1}",
                            "reportName": screen.reportName,
                            "reportType": screen.reportType,
                            "screenId": screen.screenId,
                            "status": "generated" if screen.success else "failed",
                            "error": screen.error,
                        }
                        for i, screen in enumerate(dash_result.screens)
                    ]
                    dashboard_screen_id = dash_result.dashboardScreenId
                    dashboard_url = dash_result.dashboardUrl
                    logger.info(
                        "[execute] Generated %d/%d dashboard report screen(s) for workflow %s; dashboardScreenId=%s",
                        sum(1 for s in dash_result.screens if s.success),
                        len(dash_result.screens),
                        process_id,
                        dashboard_screen_id,
                    )
                except Exception as _dash_err:
                    logger.exception("[execute] Dashboard screen generation failed")
                    all_warnings.append(f"Dashboard generation failed: {_dash_err}")

        # ── Step 9: LangGraph code generation ─────────────────────────────────────
        # global_caps is not passed here — capability descriptions are not needed for
        # code gen after gap resolution (nodes already have real capability IDs).
            logger.info(
                "%s all phases processed process_id=%s completed_phases=%s elapsed=%.2fs",
                _exec_log,
                process_id,
                len(completed_phase_results),
                time.monotonic() - _t_execute_start,
            )
            _t_codegen = time.monotonic()
            logger.info("%s LangGraph code generation start process_id=%s", _exec_log, process_id)
            try:
                combined_code = _generate_langgraph_code_for_phases(
                    completed_phase_results, workflow_name, global_caps=None
                )
            except Exception as _cg_err:
                all_warnings.append(f"LangGraph code generation failed: {_cg_err}")
                combined_code = ""
            logger.info(
                "%s LangGraph code generation done process_id=%s combined_code_len=%s duration=%.2fs",
                _exec_log,
                process_id,
                len(combined_code or ""),
                time.monotonic() - _t_codegen,
            )

            for pr in completed_phase_results:
                try:
                    pr.langgraph_code = _generate_langgraph_code_for_phases(
                        [pr], workflow_name, global_caps=None
                    )
                except Exception:
                    pr.langgraph_code = ""

            # ── Persist generated code to disk ─────────────────────────────────────────
            code_artifacts: Dict[str, Any] = {"savePath": None, "combinedFile": None}
            langgraph_savepath = config.get("langgraph_savepath")
            if langgraph_savepath:
                try:
                    os.makedirs(langgraph_savepath, exist_ok=True)
                    ts = datetime.utcnow().strftime("%Y%m%d%H%M%S")
                    code_artifacts["savePath"] = langgraph_savepath

                    def _safe_filename(part: str) -> str:
                        part = (part or "").strip() or "unknown"
                        return "".join(
                            ch if (ch.isalnum() or ch in ("-", "_", ".")) else "_" for ch in part
                        )

                    project_id_part = _safe_filename(request.projectId or project_id_for_gen)
                    combined_file = os.path.join(
                        langgraph_savepath,
                        f"pr_{project_id_part}_{ts}.py",
                    )
                    with open(combined_file, "w", encoding="utf-8") as f:
                        f.write(combined_code or "")
                    code_artifacts["combinedFile"] = combined_file

                    if combined_code:
                        try:
                            combined_code, postgen_warnings = await _postgen_validate_and_fix(
                                combined_code,
                                combined_file,
                                max_rounds=2,
                                api_key=api_key,
                                project_id=project_id_for_gen,
                                org_id=org_id,
                                subscriber_id=subscriber_id,
                                user_id=user_id,
                            )
                            all_warnings.extend(postgen_warnings)
                        except Exception as _pg_exc:
                            all_warnings.append(f"Post-generation validation error: {_pg_exc}")
                except Exception as _disk_err:
                    all_warnings.append(f"Failed to save LangGraph code files: {_disk_err}")

        # Build step persistence structure from phase graphs + flat steps.
            _step_by_id = {s.stepId: s for s in (request.steps or [])}
            persisted_steps_nested: list[Dict[str, Any]] = []
            for i, pr in enumerate(completed_phase_results):
                # Collect stepIds referenced by this phase's nodes (preserving order,
                # excluding system nodes like "end" and routers which have stepId=None).
                _seen: set[str] = set()
                _phase_step_ids: list[str] = []
                for node in pr.graph.nodes:
                    sid = node.stepId
                    if sid and sid not in _seen:
                        _phase_step_ids.append(sid)
                        _seen.add(sid)
                persisted_steps_nested.append({
                    "stepId": pr.graph.phaseId or f"phase_{i + 1}",
                    "name": pr.graph.phaseName or f"Phase {i + 1}",
                    "description": pr.graph.description or pr.graph.goal or "",
                    "phaseType": pr.phaseType,
                    "subSteps": [
                        {
                            "stepId": _step_by_id[sid].stepId,
                            "name": _step_by_id[sid].name,
                            "description": _step_by_id[sid].description,
                            "inputs": list(_step_by_id[sid].inputs),
                            "outputs": list(_step_by_id[sid].outputs),
                        }
                        for sid in _phase_step_ids
                        if sid in _step_by_id
                    ],
                })


            _validate_phase_graphs_gaps_resolved(completed_phase_results)
            logger.info(
                "%s finalization start process_id=%s — persisting Process_Configs",
                _exec_log,
                process_id,
            )

            try:
                await asyncio.to_thread(
                    _save_process_to_process_configs,
                    phase_results_local=completed_phase_results,
                    persisted_steps_nested=persisted_steps_nested,
                    warnings_local=all_warnings,
                    combined_file_path_local=code_artifacts.get("combinedFile"),
                    reports_local=dashboard_reports_out,
                    dashboard_screen_id_local=dashboard_screen_id,
                    dashboard_url_local=dashboard_url,
                )   
            except Exception as _e:
                all_warnings.append(f"Failed to persist process in Process_Configs: {_e}")
                logger.exception(
                    "%s Process_Configs persist failed process_id=%s",
                    _exec_log,
                    process_id,
                )
            logger.info(
                "%s upserting workflow capability process_id=%s",
                _exec_log,
                process_id,
            )
            try:
                await _upsert_agentic_workflow_capability(
                    workflow_id=process_id,
                    phase_results_local=completed_phase_results,
                )
            except Exception as _e:
                all_warnings.append(f"Failed to upsert workflow capability: {_e}")
                logger.exception(
                    "%s workflow capability upsert failed process_id=%s",
                    _exec_log,
                    process_id,
                )

            # Fix Bug 3: Create Workflow_Versions entry for v1 with screen_version_mapping
            # This captures the screen versions at workflow creation time, before any updates.
            # CRITICAL: For v1, we must capture the EARLIEST version of each screen from screen_generations,
            # NOT from the screens pointer (which may have been updated to a later version).
            try:
                # Capture current screen version mapping
                screen_version_mapping = {}
                project_id_for_screens = process_id  # process_id is the workflowId
                screens_coll = db["screens"]
                screen_gens_coll = db["screen_generations"]
                for phase_result in completed_phase_results:
                    if hasattr(phase_result, 'graph') and phase_result.graph and hasattr(phase_result.graph, 'nodes'):
                        for node in phase_result.graph.nodes:
                            cap_ref = getattr(node, 'capabilityRef', None)
                            if cap_ref and isinstance(cap_ref, dict):
                                cap_id = cap_ref.get("capabilityId", "")
                                if cap_id and cap_id.startswith("ui:"):
                                    screen_id = cap_id[3:]
                                    # For v1 snapshot: find the EARLIEST version from screen_generations
                                    # This ensures we capture the original v1 version, not a later update
                                    earliest = screen_gens_coll.find_one(
                                        {"screen_id": screen_id, "project_id": project_id_for_screens},
                                        sort=[("created_at", 1)]
                                    )
                                    if earliest and earliest.get("version"):
                                        screen_version_mapping[screen_id] = earliest["version"]
                                        logger.info(f"[execute/v1_snapshot] Captured EARLIEST screen version for {screen_id}: {earliest['version']}")
                                    else:
                                        # Fallback to screens pointer if screen_generations is empty
                                        pointer = screens_coll.find_one({"screen_id": screen_id, "project_id": project_id_for_screens})
                                        if pointer and pointer.get("current_version"):
                                            screen_version_mapping[screen_id] = pointer["current_version"]
                                            logger.warning(f"[execute/v1_snapshot] No screen_generations found for {screen_id}, falling back to pointer: {pointer['current_version']}")
                                        else:
                                            logger.warning(f"[execute/v1_snapshot] No screen_generations or pointer found for screen {screen_id}")

                # Save v1 workflow version with screen_version_mapping
                from bson import ObjectId as _ObjectId
                tenant_obj = {}
                if org_id:
                    try:
                        tenant_obj["orgId"] = _ObjectId(org_id) if isinstance(org_id, str) else org_id
                    except Exception:
                        pass
                if subscriber_id:
                    try:
                        tenant_obj["subscriberId"] = _ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id
                    except Exception:
                        pass
                if user_id:
                    try:
                        tenant_obj["userId"] = _ObjectId(user_id) if isinstance(user_id, str) else user_id
                    except Exception:
                        pass

                # Get the agentic_process from Process_Configs to save in version
                config_doc = db["Process_Configs"].find_one({
                    "engineType": "agentic_graph",
                    "agentic_process.workflow_id": process_id,
                    **tenant_obj
                })
                if config_doc and config_doc.get("agentic_process"):
                    agentic_process_for_version = copy.deepcopy(config_doc["agentic_process"])
                    # Ensure version is 1
                    agentic_process_for_version["version"] = 1

                    db["Workflow_Versions"].update_one(
                        {"workflowId": process_id, "version": 1},
                        {"$setOnInsert": {
                            "workflowId": process_id,
                            **tenant_obj,
                            "version": 1,
                            "saved_at": datetime.utcnow(),
                            "saved_by": user_id,
                            "reason": "initial_creation",
                            "agentic_process": agentic_process_for_version,
                            "screen_version_mapping": screen_version_mapping,
                        }},
                        upsert=True,
                    )
                    logger.info(f"[execute/v1_snapshot] Created Workflow_Versions v1 for {process_id} with screen_version_mapping: {screen_version_mapping}")
            except Exception as v1_snap_err:
                logger.warning(f"[execute/v1_snapshot] Failed to create v1 workflow version: {v1_snap_err}")

            _t_delete_cp = time.monotonic()
            logger.info("%s deleting checkpoint process_id=%s", _exec_log, process_id)
            await asyncio.to_thread(
                delete_checkpoint,
                db=db,
                workflow_id=process_id,
                subscriber_id=subscriber_id,
            )
            logger.info(
                "%s checkpoint deleted process_id=%s duration=%.2fs",
                _exec_log,
                process_id,
                time.monotonic() - _t_delete_cp,
            )
            await _publish_workflow_terminal(process_id, "completed")

            logger.info(
                "%s building AgenticPlanResponse process_id=%s phase_graphs=%s "
                "combined_code_len=%s elapsed=%.2fs",
                _exec_log,
                process_id,
                len(completed_phase_results),
                len(combined_code or ""),
                time.monotonic() - _t_execute_start,
            )
            response = AgenticPlanResponse(
                workflowName=workflow_name,
                steps=request.steps or [],
                mode=mode,
                analysis_source=analysis_source,
                warnings=all_warnings,
                stepCapabilities=[],
                phaseGraphs=completed_phase_results,
                combinedLanggraphCode=combined_code,
                reports=dashboard_reports_out,
                dashboardScreenId=dashboard_screen_id,
                dashboardUrl=dashboard_url,
            )
            logger.info(
                "%s AgenticPlanResponse built process_id=%s — exiting billing scope "
                "elapsed=%.2fs",
                _exec_log,
                process_id,
                time.monotonic() - _t_execute_start,
            )
            return response
        except BillingError as exc:
            logger.warning(
                "%s BillingError process_id=%s code=%s phase_id=%s node_id=%s elapsed=%.2fs",
                _exec_log,
                process_id,
                exc.code,
                last_execute_snapshot.get("phase_id"),
                last_execute_snapshot.get("node_id"),
                time.monotonic() - _t_execute_start,
            )
            # Signal to workflow_reservation_release_scope to keep the hold active.
            _billing_ctx = get_billing_context()
            if _billing_ctx is not None:
                _billing_ctx.billing_error_occurred = True
            graphs_snapshot = last_execute_snapshot["phase_graphs"]
            await _write_execute_build_checkpoint(
                status="paused_credit",
                phase_index=last_execute_snapshot["phase_index"],
                phase_graphs_snapshot=graphs_snapshot,
                prior_outputs=last_execute_snapshot["prior_phase_outputs"],
                last_error={
                    "code": exc.code,
                    "phase_id": last_execute_snapshot.get("phase_id"),
                    "node_id": last_execute_snapshot.get("node_id"),
                    "at": datetime.utcnow().isoformat(),
                },
            )
            await asyncio.to_thread(
                set_workflow_agentic_status,
                db=db,
                workflow_id=process_id,
                subscriber_id=subscriber_id,
                org_id=org_id,
                user_id=user_id,
                status="paused_credit",
            )
            _pause_detail = _billing_pause_error(
                exc, workflow_id=process_id, subscriber_id=subscriber_id
            )
            await _publish_paused_credit(process_id, _pause_detail)
            raise HTTPException(
                status_code=402,
                detail=_pause_detail,
            ) from exc


def _agentic_workflow_tenant_query(
    *,
    org_id: Optional[str],
    subscriber_id: Optional[str],
    user_id: Optional[str],
) -> Dict[str, Any]:
    q: Dict[str, Any] = {"engineType": "agentic_graph"}
    for key, raw in (
        ("orgId", org_id),
        ("subscriberId", subscriber_id),
        ("userId", user_id),
    ):
        if raw is None:
            continue
        try:
            q[key] = ObjectId(raw) if isinstance(raw, str) else raw
        except Exception:
            q[key] = raw
    return q


def _format_agentic_workflow_list_item(doc: Dict[str, Any]) -> AgenticWorkflowListItem:
    agentic = doc.get("agentic_process") if isinstance(doc.get("agentic_process"), dict) else {}
    workflow_id = (
        agentic.get("workflow_id")
        or doc.get("workflow_id")
        or ""
    )
    phase_graphs = agentic.get("phaseGraphs") or []
    created = doc.get("created_at")
    updated = doc.get("updated_at")
    return AgenticWorkflowListItem(
        workflowId=str(workflow_id),
        workflowName=agentic.get("workflowName") or doc.get("selectedName"),
        projectId=agentic.get("projectId"),
        selectedName=doc.get("selectedName"),
        selectedCategory=doc.get("selectedCategory"),
        selectedType=doc.get("selectedType"),
        status=agentic.get("status"),
        mode=agentic.get("mode"),
        planner=agentic.get("planner"),
        phaseCount=len(phase_graphs) if isinstance(phase_graphs, list) else 0,
        created_at=created.isoformat() if hasattr(created, "isoformat") else (str(created) if created else None),
        updated_at=updated.isoformat() if hasattr(updated, "isoformat") else (str(updated) if updated else None),
    )


@app.post("/aiqod-agent/agent/agentic/workflows/list", response_model=AgenticWorkflowListResponse)
async def agentic_workflows_list(
    request: AgenticWorkflowListRequest,
    http_request: Request,
) -> AgenticWorkflowListResponse:
    """
    List workflow-builder workflows already saved in Process_Configs.

    Returns documents with ``engineType: "agentic_graph"`` (created by
    ``/agentic/plan/scratch/preview`` and ``/agentic/plan/execute``).

    Use on the frontend **My workflows** screen. Filter by tenant ids; optional
    ``status`` filter: ``preview`` (graph only) or ``draft`` (built, ready to run).
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")

    if not subscriber_id:
        raise HTTPException(status_code=400, detail="subscriberId is required.")
    if not org_id:
        raise HTTPException(status_code=400, detail="orgId is required.")

    query = _agentic_workflow_tenant_query(
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
    )
    if request.status != "all":
        query["agentic_process.status"] = request.status

    projection = {
        "_id": 0,
        "selectedName": 1,
        "selectedCategory": 1,
        "selectedType": 1,
        "created_at": 1,
        "updated_at": 1,
        "agentic_process.workflow_id": 1,
        "agentic_process.workflowName": 1,
        "agentic_process.projectId": 1,
        "agentic_process.status": 1,
        "agentic_process.mode": 1,
        "agentic_process.planner": 1,
        "agentic_process.phaseGraphs": 1,
    }

    cursor = db["Process_Configs"].find(query, projection).sort("updated_at", -1)
    items = [_format_agentic_workflow_list_item(doc) for doc in cursor if doc]
    return AgenticWorkflowListResponse(workflows=items, total=len(items))


@app.get("/aiqod-agent/agent/agentic/workflows/{workflow_id}", response_model=AgenticWorkflowListItem)
async def agentic_workflow_get(workflow_id: str, http_request: Request) -> AgenticWorkflowListItem:
    """
    Fetch summary metadata for one agentic workflow by ``workflow_id``.

    For the full Process_Configs document (phaseGraphs, etc.) use
    ``GET /aiqod-agent/agent/configdetails`` with header ``workflow-id``.
    """
    wf_id = (workflow_id or "").strip()
    if not wf_id:
        raise HTTPException(status_code=400, detail="workflow_id must not be empty.")

    org_id = http_request.headers.get("x-org-id")
    subscriber_id = http_request.headers.get("x-subscriber-id")

    query: Dict[str, Any] = {
        "engineType": "agentic_graph",
        "agentic_process.workflow_id": wf_id,
    }
    if org_id:
        try:
            query["orgId"] = ObjectId(org_id)
        except Exception:
            query["orgId"] = org_id
    if subscriber_id:
        try:
            query["subscriberId"] = ObjectId(subscriber_id)
        except Exception:
            query["subscriberId"] = subscriber_id

    doc = db["Process_Configs"].find_one(
        query,
        {
            "_id": 0,
            "selectedName": 1,
            "selectedCategory": 1,
            "selectedType": 1,
            "created_at": 1,
            "updated_at": 1,
            "agentic_process.workflow_id": 1,
            "agentic_process.workflowName": 1,
            "agentic_process.projectId": 1,
            "agentic_process.status": 1,
            "agentic_process.mode": 1,
            "agentic_process.planner": 1,
            "agentic_process.phaseGraphs": 1,
        },
    )
    if not doc:
        raise HTTPException(status_code=404, detail=f"Workflow '{wf_id}' not found.")
    return _format_agentic_workflow_list_item(doc)


async def regeneration_llm_caller(
    system_prompt: str,
    user_prompt: str,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    workflow_id: Optional[str] = None,
) -> str:
    logger.info(f"[regeneration_llm_caller] System Prompt:\n{system_prompt}")
    logger.info(f"[regeneration_llm_caller] User Prompt:\n{user_prompt}")
    started_at = datetime.utcnow()
    try:
        response = await async_generate(
            REGENERATION_MODEL,
            [system_prompt, user_prompt],
            config=GeminiGenerateConfig(temperature=0.2),
        )
        finished_at = datetime.utcnow()
        tokens = extract_token_usage_from_response(response)
        record_llm_call(
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            operation="agentic-workflow-update",
            sub_operation="schema-regeneration",
            model=REGENERATION_MODEL,
            prompt_tokens=tokens.get("prompt_tokens", 0),
            completion_tokens=tokens.get("completion_tokens", 0),
            total_tokens=tokens.get("total_tokens", 0),
            status="success",
            started_at=started_at,
            finished_at=finished_at,
            metadata={"workflow_id": workflow_id} if workflow_id else {},
        )
        return response.text
    except Exception as exc:
        finished_at = datetime.utcnow()
        record_llm_call(
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            operation="agentic-workflow-update",
            sub_operation="schema-regeneration",
            model=REGENERATION_MODEL,
            prompt_tokens=0,
            completion_tokens=0,
            total_tokens=0,
            status="failed",
            started_at=started_at,
            finished_at=finished_at,
            metadata={"workflow_id": workflow_id, "error": str(exc)},
        )
        raise

@app.post("/aiqod-agent/agent/agentic/plan/update")
async def update_workflow_plan(payload: WorkflowUpdatePayload, http_request: Request):
    try:
        org_id = payload.orgId or http_request.headers.get("x-org-id")
        subscriber_id = payload.subscriberId or http_request.headers.get("x-subscriber-id")
        user_id = http_request.headers.get("x-user-id")

        if not subscriber_id:
            raise HTTPException(status_code=400, detail="subscriberId is required.")

        # ── 1. Load workflow document ──────────
        # workflowId === projectId (same stable key stored as agentic_process.workflow_id)
        query = {
            "engineType": "agentic_graph",
            "agentic_process.workflow_id": payload.workflowId,
            "subscriberId": ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id,
        }
        if org_id:
            query["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id

        doc = db["Process_Configs"].find_one(query)
        if not doc:
            raise HTTPException(status_code=404, detail="Workflow not found in Process_Configs.")

        agentic_process = doc.get("agentic_process", {})
        phase_graphs = agentic_process.get("phaseGraphs", [])
        steps = agentic_process.get("steps", [])
        workflow_name = agentic_process.get("workflowName") or doc.get("selectedName") or "workflow"
        project_id = getattr(payload, "projectId", None) or agentic_process.get("projectId") or payload.workflowId
        current_version = agentic_process.get("version", 1)

        # ── Preview-only mode: run Phase 1 (impact analysis) only and cache for reuse ─────
        if getattr(payload, "preview_only", False):
            logger.info(f"[plan/update] preview_only=True — running impact analysis only for workflow {payload.workflowId}")

            # Build updated_node_ids and proposed_changes from operations (same as main flow)
            order_map = {"DELETE": 0, "UPDATE": 1, "INSERT": 2}
            normalized_operations = _coerce_operations(getattr(payload, "operations", []) or [])
            normalized_operations.sort(key=lambda x: order_map.get(str(x.get("action") or "").upper(), 99))
            updated_node_ids: set[str] = set()

            for op in normalized_operations:
                if op.get("targetStepId"):
                    op["targetStepId"] = resolve_internal_id(op["targetStepId"], phase_graphs)
                if str(op.get("action") or "").upper() == "UPDATE":
                    target_node_id = op.get("targetStepId")
                    for phase in phase_graphs:
                        for node in phase.get("graph", {}).get("nodes", []):
                            if node.get("nodeId") == target_node_id:
                                cfg = node.get("config")
                                if not isinstance(cfg, dict):
                                    cfg = {}
                                    node["config"] = cfg
                                cfg["_requires_regeneration"] = True
                                if op.get("prompt"):
                                    new_prompt = op["prompt"]
                                    cfg["_update_request"] = new_prompt
                                    applied = cfg.get("_applied_update_prompts")
                                    if isinstance(applied, list) and new_prompt not in applied:
                                        cfg["_applied_update_prompts"] = []
                                updated_node_ids.add(target_node_id)

            # Build proposed_changes from UPDATED node configs
            proposed_changes: Dict[str, Dict[str, Any]] = {}
            for op in normalized_operations:
                if str(op.get("action") or "").upper() == "UPDATE" and op.get("targetStepId"):
                    for phase in phase_graphs:
                        graph = phase.get("graph", {})
                        for node in graph.get("nodes", []):
                            if node.get("nodeId") == op.get("targetStepId"):
                                proposed_changes.update(
                                    create_proposed_changes_from_node_update(node, op.get("prompt", ""))
                                )
                                break

            # Get actual proposed schemas from LLM (dry run) - same as /plan/update/impact-analysis
            if updated_node_ids:
                from regeneration import get_proposed_node_schemas
                from services.gemini_service import extract_text

                async def llm_caller(system_prompt: str, user_prompt: str, sub_op: str = "") -> str:
                    response = await async_generate(
                        "gemini-3-flash-preview",
                        f"{system_prompt}\n\n{user_prompt}",
                        config=GeminiGenerateConfig(temperature=0.2)
                    )
                    return extract_text(response)

                llm_result = await get_proposed_node_schemas(phase_graphs, updated_node_ids, llm_caller, proposed_changes)

                if isinstance(llm_result, tuple) and llm_result:
                    llm_schemas = llm_result[0] if len(llm_result) > 0 else {}
                else:
                    llm_schemas = llm_result

                # Merge LLM-proposed outputs into proposed_changes
                for node_id, schema in llm_schemas.items():
                    if node_id in proposed_changes:
                        proposed_changes[node_id]["inputBindings"] = schema.get("inputBindings", proposed_changes[node_id]["inputBindings"])
                        proposed_changes[node_id]["declaredOutputs"] = schema.get("declaredOutputs", proposed_changes[node_id]["declaredOutputs"])

            # Run Phase 1: Impact Analysis only
            # run_impact_analysis_fn and format_impact_report_for_user are already imported at module level
            global_inputs = _extract_global_inputs(phase_graphs)

            # Build screen_metadata for LLM-based impact analysis
            screen_metadata = {}
            screen_repo = ScreenRepository()
            for pg in phase_graphs:
                for node in pg.get("graph", {}).get("nodes", []):
                    cap_ref = node.get("capabilityRef") or {}
                    if isinstance(cap_ref, dict) and cap_ref.get("capabilityId", "").startswith("ui:"):
                        screen_id = cap_ref["capabilityId"][3:]
                        # Fetch backend functions from screen document (authoritative source)
                        screen_state = await screen_repo.get_screen_state(project_id, screen_id)
                        backend_metadata = screen_state.get("backend", {}) if screen_state else {}
                        backend_functions = backend_metadata.get("functions", [])
                        # Fallback to node config if screen document has no backend functions
                        if not backend_functions:
                            backend_functions = node.get("config", {}).get("backendFunctions", [])

                        screen_metadata[screen_id] = {
                            "node_id": node.get("nodeId"),
                            "backend_functions": backend_functions,
                            "input_bindings": node.get("config", {}).get("inputBindings", {}),
                            "declared_outputs": node.get("config", {}).get("declaredOutputs", []),
                        }

            # Load current codebase for LLM analysis
            current_codebase = await _load_current_codebase(project_id, payload.workflowId, phase_graphs)

            impact_report = await run_impact_analysis_fn(
                phase_graphs=phase_graphs,
                updated_node_ids=updated_node_ids,
                proposed_changes=proposed_changes,
                use_llm_analysis=True,
                llm_caller=llm_caller,
                current_codebase=current_codebase,
                screen_metadata=screen_metadata,
                project_id=project_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                workflow_id=payload.workflowId,
            )

            impact_summary = format_impact_report_for_user(impact_report)

            # Cache the preview data in the workflow document for reuse on approval
            preview_cache = {
                "operations": normalized_operations,  # Store operations for matching on approval
                "proposed_changes": proposed_changes,
                "impact_report": impact_report.to_dict(),
                "updated_node_ids": list(updated_node_ids),
                "created_at": datetime.utcnow(),
            }

            db["Process_Configs"].update_one(
                {"_id": doc["_id"]},
                {"$set": {"agentic_process.pending_update_preview": preview_cache}}
            )

            logger.info(f"[plan/update] Preview impact analysis cached for workflow {payload.workflowId}")

            return {
                "success": True,
                "message": "Impact analysis complete. Review and approve to apply changes.",
                "workflowId": payload.workflowId,
                "preview": True,
                "impact_report": impact_report.to_dict(),
                "impact_summary": impact_summary,
                "user_approval_required": impact_report.user_approval_required,
                "updated_nodes": list(updated_node_ids),
            }

        # ── Check for cached preview and reuse if operations match ─────
        cached_preview = agentic_process.get("pending_update_preview")
        preview_reused = False
        if not getattr(payload, "preview_only", False) and cached_preview:
            # Check if the operations match (same targetStepIds and prompts for UPDATEs)
            cached_ops = cached_preview.get("operations", [])
            current_ops = _coerce_operations(getattr(payload, "operations", []) or [])

            def _ops_signature(ops: list) -> str:
                sigs = []
                for op in ops:
                    action = str(op.get("action") or "").upper()
                    if action == "UPDATE":
                        sigs.append(f"UPDATE:{op.get('targetStepId')}:{op.get('prompt','')}")
                    elif action == "INSERT":
                        sigs.append(f"INSERT:{op.get('afterStepId')}:{op.get('prompt','')}")
                    elif action == "DELETE":
                        sigs.append(f"DELETE:{op.get('targetStepId')}")
                return "|".join(sigs)

            if _ops_signature(cached_ops) == _ops_signature(current_ops):
                logger.info(f"[plan/update] Reusing cached preview for workflow {payload.workflowId}")
                proposed_changes = cached_preview.get("proposed_changes", {})
                updated_node_ids = set(cached_preview.get("updated_node_ids", []))
                # We'll also reuse the impact_report to skip Phase 1
                # Mark that we're reusing preview so we can skip impact analysis
                preview_reused = True
                # Clear the cache since we're consuming it
                db["Process_Configs"].update_one(
                    {"_id": doc["_id"]},
                    {"$unset": {"agentic_process.pending_update_preview": ""}}
                )
            else:
                logger.info(f"[plan/update] Cached preview operations don't match, running fresh analysis")

        if doc.get("reservationStatus") not in (None, "active"):
            update_steps: list[Dict[str, Any]] = []
            for op in (payload.operations or []):
                target_id = getattr(op, "targetStepId", None)
                op_prompt = getattr(op, "prompt", None) or ""
                meta_name = "Workflow Update"
                for phase in steps:
                    for sub in (phase.get("subSteps") or []):
                        if sub.get("stepId") == target_id:
                            meta_name = sub.get("name") or meta_name
                            break
                update_steps.append({
                    "stepId": str(uuid.uuid4()),
                    "name": meta_name,
                    "description": "Targeted update to an existing workflow step.",
                    "phaseType": "FREEZE",
                    "subSteps": [{
                        "stepId": str(target_id or uuid.uuid4()),
                        "name": meta_name,
                        "description": op_prompt,
                    }],
                })
            update_est = estimate_workflow_cost(steps=update_steps or steps)
            reactivate_workflow_reservation(
                project_id=project_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                additional_predicted_cost=update_est.predicted_cost,
            )

        _init_agentic_workflow_billing(
            project_id=project_id,
            workflow_id=payload.workflowId,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            use_subscriber_credits=getattr(payload, "useSubscriberCredits", False),
        )


        if payload.version is not None and payload.version != current_version:
            raise HTTPException(
                status_code=409,
                detail={
                    "error": "Version conflict. The workflow was updated by someone else.",
                    "currentVersion": current_version,
                    "yourVersion": payload.version,
                },
            )

        global_snapshot = copy.deepcopy(agentic_process)

        tenant: Dict[str, Optional[str]] = {
            "orgId": org_id,
            "subscriberId": subscriber_id,
            "userId": user_id,
        }

        # Initialize all_warnings EARLY — the integrated pipeline validates before the
        # gap-resolution phase, and validation issues need to land in this same list
        # that is later persisted on the agentic_process doc. (Declared before first use.)
        all_warnings: list[str] = []

        # Track which pipeline path executed so frontend can see whether the integrated
        # 3-phase pipeline ran successfully, legacy fallback fired, or no update path ran.
        # Settled to "integrated" / "legacy_fallback" inside the `if updated_node_ids:`
        # block below; initialized to "none" so a payload with zero UPDATEs reports it.
        pipeline_used: str = "none"

        # ── 3. Fetch credentials (same as /execute) ───────────────────────────
        plan_available_credentials: List[Dict[str, Any]] = []
        _plan_cred_svc = CredentialService.optional()
        if _plan_cred_svc and project_id:
            try:
                plan_available_credentials = await _plan_cred_svc.list_credentials(
                    project_id, org_id=org_id, subscriber_id=subscriber_id,
                )
                if not plan_available_credentials and (org_id or subscriber_id):
                    plan_available_credentials = await _plan_cred_svc.list_credentials(project_id)
                logger.info(
                    f"[plan/update] Loaded {len(plan_available_credentials)} credential(s) "
                    f"for project='{project_id}'."
                )
            except Exception as _cred_err:
                logger.warning(f"[plan/update] Failed to list credentials: {_cred_err}")

        async def _tracked_llm_caller(system_prompt: str, user_prompt: str, sub_op: str = "regeneration") -> str:
            prompt_content = f"{system_prompt}\n\n{user_prompt}"
            started_at = datetime.utcnow()
            response = await async_generate(
                REGENERATION_MODEL,
                prompt_content,
                config=GeminiGenerateConfig(temperature=0.2),
            )
            finished_at = datetime.utcnow()
            
            usage = extract_token_usage_from_response(response)
            record_llm_call(
                project_id=project_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                operation="workflow-update",
                sub_operation=sub_op,
                model=REGENERATION_MODEL,
                prompt_tokens=usage.get("prompt_tokens", 0),
                completion_tokens=usage.get("completion_tokens", 0),
                total_tokens=usage.get("total_tokens", 0),
                status="success",
                started_at=started_at,
                finished_at=finished_at,
                metadata={"workflow_id": payload.workflowId}
            )
            return response.text or ""

        order_map = {"DELETE": 0, "UPDATE": 1, "INSERT": 2}
        normalized_operations = _coerce_operations(getattr(payload, "operations", []) or [])
        normalized_operations.sort(key=lambda x: order_map.get(str(x.get("action") or "").upper(), 99))
        updated_node_ids: set[str] = set()

        for op in normalized_operations:
            if op.get("targetStepId"):
                op["targetStepId"] = resolve_internal_id(op["targetStepId"], phase_graphs)
            if op.get("afterStepId"):
                op["afterStepId"] = resolve_internal_id(op["afterStepId"], phase_graphs)
            if op.get("beforeStepId"):
                op["beforeStepId"] = resolve_internal_id(op["beforeStepId"], phase_graphs)

            if str(op.get("action") or "").upper() == "DELETE":
                target_node_id = op.get("targetStepId")
                router_id = f"{target_node_id}_router"
                for phase in phase_graphs:
                    graph = phase.get("graph", {})
                    nodes, edges = graph.get("nodes", []), graph.get("edges", [])
                    graph["nodes"] = [n for n in nodes if n.get("nodeId") not in [target_node_id, router_id]]
                    incoming, outgoing, keep = [], [], []
                    for edge in edges:
                        if edge.get("to") in [target_node_id, router_id]:
                            incoming.append(edge.get("fromNode"))
                        elif edge.get("fromNode") in [target_node_id, router_id]:
                            outgoing.append(edge.get("to"))
                        else:
                            keep.append(edge)
                    for inc in set(incoming):
                        for out in set(outgoing):
                            if inc and out and inc not in [target_node_id, router_id] and out not in [target_node_id, router_id]:
                                keep.append({"fromNode": inc, "to": out, "kind": "sequential", "condition": None})
                    graph["edges"] = keep

            elif str(op.get("action") or "").upper() == "UPDATE":
                target_node_id = op.get("targetStepId")
                for phase in phase_graphs:
                    for node in phase.get("graph", {}).get("nodes", []):
                        if node.get("nodeId") == target_node_id:
                            cfg = node.get("config")
                            if not isinstance(cfg, dict):
                                cfg = {}
                                node["config"] = cfg
                            cfg["_requires_regeneration"] = True
                            if op.get("prompt"):
                                new_prompt = op["prompt"]
                                cfg["_update_request"] = new_prompt
                                # If the user's prompt for THIS request is not in the
                                # applied-prompts bucket, this is a genuinely new UPDATE —
                                # clear the bucket so the integrated pipeline can apply it.
                                # If the prompt IS in the bucket, leave it alone so retries
                                # skip re-application (Option B idempotency).
                                applied = cfg.get("_applied_update_prompts")
                                if isinstance(applied, list) and new_prompt not in applied:
                                    cfg["_applied_update_prompts"] = []
                            updated_node_ids.add(target_node_id)

            elif str(op.get("action") or "").upper() == "INSERT":
                if op.get("afterStepId"):
                    anchor_id, target_router = op["afterStepId"], None
                    for phase in phase_graphs:
                        graph = phase.get("graph", {})
                        nodes_dict = {n["nodeId"]: n for n in graph.get("nodes", [])}
                        for edge in graph.get("edges", []):
                            if edge.get("fromNode") == anchor_id:
                                dest = nodes_dict.get(edge.get("to"))
                                if dest and dest.get("type") == "router":
                                    target_router = dest
                                    break
                        if target_router:
                            break

                    if target_router:
                        if op.get("clarificationAnswers") and isinstance(op.get("clarificationAnswers"), list) and len(op["clarificationAnswers"]) > 0:
                            op["clarificationAnswers"] = [op["clarificationAnswers"][0]]
                        else:
                            system_prompt = f"""You are a workflow routing assistant.
Available Branches:\n{get_router_branches_text(target_router)}\nUser Request: "{op.get('prompt', '')}"
Respond ONLY with JSON: {{"is_ambiguous": boolean, "resolved_branch_target": string|null, "clarification_question": string|null}}"""
                            response_text = await _tracked_llm_caller(system_prompt, op.get("prompt") or "", sub_op="router-clarification")
                            llm_result = repair_json(response_text, return_objects=True)
                            logger.info(f"[plan/update] INSERT router resolution for workflowId {payload.workflowId}: {llm_result}")
                            if llm_result.get("is_ambiguous"):
                                raise HTTPException(status_code=400, detail={
                                    "error": "Ambiguous insertion point.",
                                    "action_required": "clarification",
                                    "question": llm_result.get("clarification_question"),
                                })
                            op["clarificationAnswers"] = [llm_result.get("resolved_branch_target")]

        # ── 5. Integrated 3-phase regeneration pipeline (Phase 1 + 2 + 3) ─────
        # Frontend handles the user-approval gate (per spec); backend auto-approves
        # via `run_regeneration_with_auto_approval`, which:
        #   Phase 1: impact analysis (bidirectional blast radius, Tarjan cycle detection,
        #            severity classification) — surfaces downstream + cycle-retry impact.
        #   Phase 2: surgical editing with a 3-iteration self-healing loop
        #            (edit → apply → validate).
        #   Phase 3: 6-category validation + auto-repair (incl. cycle-contract compliance
        #            per spec).
        # Replaces the legacy dual-path (legacy pipeline + ad-hoc surgical edits) which
        # raced against itself and left phase_graphs / combined_file_path in inconsistent
        # state — the proximate cause of the restore mismatch bug.
        if updated_node_ids:
            # Build proposed_changes from UPDATED node configs (this is what Phase 2 uses
            # to compute minimal search/replace diffs).
            # Use create_proposed_changes_from_node_update to parse the user's prompt
            # (e.g., "add one more number") and compute the desired declaredOutputs.
            proposed_changes: Dict[str, Dict[str, Any]] = {}
            for op in normalized_operations:
                if str(op.get("action") or "").upper() == "UPDATE" and op.get("targetStepId"):
                    for phase in phase_graphs:
                        graph = phase.get("graph", {})
                        for node in graph.get("nodes", []):
                            if node.get("nodeId") == op.get("targetStepId"):
                                # Use the helper to parse update_request and compute desired outputs
                                proposed_changes.update(
                                    create_proposed_changes_from_node_update(node, op.get("prompt", ""))
                                )
                                break

            global_inputs = _extract_global_inputs(phase_graphs)
            current_codebase = await _load_current_codebase(project_id, payload.workflowId, phase_graphs)

            logger.info(
                f"[plan/update] Starting integrated pipeline (Phase 1+2+3, max 3 iter) "
                f"for workflow {payload.workflowId}, "
                f"{len(updated_node_ids)} updated node(s), {len(proposed_changes)} proposed change(s)."
            )

            # pipeline_used is initialized at function level (default "none").
            # Update it as we go:
            #   "integrated"      → Phase 1+2+3 ran via the orchestrator
            #   "legacy_fallback" → integrated failed/timeout; legacy regeneration ran
            pipeline_used = "legacy_fallback"  # will be flipped to "integrated" on success
            budget_errors: List[str] = []

            try:
                from integrated_pipeline import run_regeneration_with_auto_approval, ImpactReport

                # Cap max_iterations at 1 to prevent "add one more number" prompts
                # from snowballing into multiple additions when validation retries
                # the surgical-edit LLM. If validation actually fails, we fall back
                # to legacy regeneration which has its own (conservative) retry logic.

                # If preview was reused, pass the precomputed impact report to skip Phase 1
                precomputed_impact_report = None
                if preview_reused and cached_preview:
                    try:
                        cached_impact_dict = cached_preview.get("impact_report")
                        if cached_impact_dict:
                            precomputed_impact_report = ImpactReport.from_dict(cached_impact_dict)
                            logger.info(f"[plan/update] Using precomputed impact report from cached preview")
                    except Exception as _precomp_err:
                        logger.warning(f"[plan/update] Failed to reconstruct precomputed impact report: {_precomp_err}")

                # Build screen_metadata for LLM-based impact analysis
                screen_metadata = {}
                screen_repo = ScreenRepository()
                for pg in phase_graphs:
                    for node in pg.get("graph", {}).get("nodes", []):
                        cap_ref = node.get("capabilityRef") or {}
                        if isinstance(cap_ref, dict) and cap_ref.get("capabilityId", "").startswith("ui:"):
                            screen_id = cap_ref["capabilityId"][3:]
                            # Fetch backend functions from screen document (authoritative source)
                            screen_state = await screen_repo.get_screen_state(project_id, screen_id)
                            backend_metadata = screen_state.get("backend", {}) if screen_state else {}
                            backend_functions = backend_metadata.get("functions", [])
                            # Fallback to node config if screen document has no backend functions
                            if not backend_functions:
                                backend_functions = node.get("config", {}).get("backendFunctions", [])

                            screen_metadata[screen_id] = {
                                "node_id": node.get("nodeId"),
                                "backend_functions": backend_functions,
                                "input_bindings": node.get("config", {}).get("inputBindings", {}),
                                "declared_outputs": node.get("config", {}).get("declaredOutputs", []),
                            }

                pipeline_state = await run_regeneration_with_auto_approval(
                    phase_graphs=phase_graphs,
                    updated_node_ids=updated_node_ids,
                    proposed_changes=proposed_changes,
                    current_codebase=current_codebase,
                    global_inputs=global_inputs,
                    llm_caller=_tracked_llm_caller,
                    max_iterations=1,
                    precomputed_impact_report=precomputed_impact_report,
                    screen_metadata=screen_metadata,
                    project_id=project_id,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    workflow_id=payload.workflowId,
                )

                if pipeline_state.success:
                    logger.info(
                        f"[plan/update] ✅ Integrated pipeline completed "
                        f"({pipeline_state.iteration}/{pipeline_state.max_iterations} iteration(s))."
                    )
                    pipeline_used = "integrated"

                    # Phase 1 (impact analysis) — surface report as warnings/info
                    if pipeline_state.impact_report:
                        impact_summary = format_impact_report_for_user(pipeline_state.impact_report)
                        logger.info(
                            f"[plan/update] Phase 1 impact report:\n{impact_summary}"
                        )
                        if pipeline_state.impact_report.user_approval_required:
                            logger.warning(
                                f"[plan/update] Phase 1 reported breaking changes "
                                f"(frontend is responsible for the user-approval gate)."
                            )

                    # Phase 2 (surgical editing) — apply edit plans back to phase_graphs so
                    # downstream gap resolution / LangGraph compile sees the new schemas.
                    if pipeline_state.edit_plans:
                        _apply_edit_plans_to_phase_graphs(
                            phase_graphs, pipeline_state.edit_plans, updated_node_ids, proposed_changes,
                        )

                        # NEW: Update DIRECTLY MODIFIED screens' declaredOutputs from impact report
                        # This ensures the Angular generator sees the new outputs when building gen_prompt
                        # The impact report knows about new outputs (e.g., "New output 'number_3' added")
                        # but edit plans may not include declaredOutputs changes. We sync them here.
                        logger.info(f"[plan/update] DEBUG: pipeline_state.impact_report exists: {pipeline_state.impact_report is not None}")
                        if pipeline_state.impact_report:
                            logger.info(f"[plan/update] DEBUG: all_affected_nodes count: {len(pipeline_state.impact_report.all_affected_nodes)}")
                            for impact in pipeline_state.impact_report.all_affected_nodes:
                                logger.info(f"[plan/update] DEBUG: impact node_id={impact.node_id}, is_directly_modified={impact.is_directly_modified}, changes={impact.changes}")
                                if not impact.is_directly_modified:
                                    continue
                                # Find the node in phase_graphs
                                target_node = None
                                for pg in phase_graphs:
                                    for node in pg.get("graph", {}).get("nodes", []):
                                        if node.get("nodeId") == impact.node_id:
                                            target_node = node
                                            break
                                    if target_node:
                                        break
                                if not target_node:
                                    continue

                                # Extract new outputs from impact report changes
                                # NodeImpact.changes contains entries with type="output_added" and output_name
                                new_outputs_from_impact = []
                                for change in getattr(impact, "changes", []):
                                    if change.get("type") == "output_added" and change.get("output_name"):
                                        new_outputs_from_impact.append(change["output_name"])

                                # Fallback: parse from regeneration_reason text if available
                                if not new_outputs_from_impact:
                                    impact_text = str(getattr(impact, "regeneration_reason", "") or "")
                                    import re
                                    new_outputs_from_impact = re.findall(r"New output '([^']+)' added", impact_text)

                                if new_outputs_from_impact:
                                    cfg = target_node.get("config")
                                    if not isinstance(cfg, dict):
                                        cfg = {}
                                        target_node["config"] = cfg
                                    existing_declared = cfg.get("declaredOutputs", [])
                                    existing_names = {o.get("name") for o in existing_declared if isinstance(o, dict) and o.get("name")}
                                    for out_name in new_outputs_from_impact:
                                        if out_name not in existing_names:
                                            existing_declared.append({
                                                "name": out_name,
                                                "dataType": "number",  # default, will be refined by LLM/IR
                                                "required": True,
                                                "description": f"Auto-detected new output from impact analysis"
                                            })
                                    cfg["declaredOutputs"] = existing_declared
                                    logger.info(
                                        f"[plan/update] Synced declaredOutputs for directly modified {impact.node_id} "
                                        f"from impact report: {[o.get('name') for o in existing_declared]}"
                                    )

                        # UI screens: invoke the Angular generator's
                        # `update_angular_screen_async` path for every ui_screen affected
                        # by an UPDATE. This does TWO things in one call:
                        #   1. Runs the Angular generator on the user's prompt, so the
                        #      screen content actually reflects the requested change
                        #      (e.g. "add one more number" must produce a 3rd input).
                        #   2. Creates a NEW screen_generations row under a NEW
                        #      screen_id — guarantees per-version rollback safety.
                        # The naive "clone current row + bump version" approach was
                        # discarding the user's prompt; this re-uses the legacy path.
                        screen_bumps: Dict[str, str] = {}
                        ui_updates_by_node: Dict[str, Dict[str, Any]] = {}
                        for op in normalized_operations:
                            if str(op.get("action") or "").upper() != "UPDATE":
                                continue
                            target_id = op.get("targetStepId")
                            if not target_id or target_id not in updated_node_ids:
                                continue
                            ui_updates_by_node[target_id] = {
                                "prompt": op.get("prompt") or "",
                                "screen_name": "",
                            }
                        if ui_updates_by_node:
                            for phase in phase_graphs:
                                graph = phase.get("graph") or {}
                                for node in graph.get("nodes") or []:
                                    if node.get("nodeId") not in ui_updates_by_node:
                                        continue
                                    if node.get("type") != "ui_screen":
                                        continue
                                    cap_ref = node.get("capabilityRef") or {}
                                    old_cap_id = (
                                        cap_ref.get("capabilityId")
                                        if isinstance(cap_ref, dict) else ""
                                    )
                                    if not old_cap_id or not old_cap_id.startswith("ui:"):
                                        continue
                                    old_screen_id = old_cap_id[3:]
                                    info = ui_updates_by_node[node["nodeId"]]
                                    info["screen_name"] = (
                                        node.get("name") or info["screen_name"]
                                    )

                                    # Build gen_prompt with I/O contract from GenerationSpec (synced from declaredOutputs)
                                    # For directly modified screens, also use config.declaredOutputs as source of truth
                                    # since edit plans update declaredOutputs but may not update generation.outputs if generation dict doesn't exist
                                    cfg = node.get("config", {})
                                    gen_spec = cfg.get("generation") or {}  # Defensive: ensure dict, not None
                                    declared_outputs = cfg.get("declaredOutputs", [])

                                    # FIX: After a workflow restore (e.g., budget exhaustion + resume),
                                    # the phase_graphs may contain an old version of the screen config.
                                    # Fetch the ACTUAL current screen state from screen_generations to get
                                    # the true declaredOutputs (which may have more fields from previous updates).
                                    try:
                                        screen_repo = ScreenRepository()
                                        latest_screen_doc = await screen_repo.get_latest_screen_doc(project_id, old_screen_id)
                                        if latest_screen_doc:
                                            # Get declaredOutputs from the screen document's IR schema (authoritative)
                                            ir_schema = latest_screen_doc.get("ir_schema") or {}
                                            ir_outputs = ir_schema.get("outputParameters") or []
                                            if ir_outputs:
                                                # Convert IR outputParameters to declaredOutputs format
                                                db_declared_outputs = []
                                                for ir_out in ir_outputs:
                                                    if isinstance(ir_out, dict) and ir_out.get("name"):
                                                        db_declared_outputs.append({
                                                            "name": ir_out["name"],
                                                            "dataType": ir_out.get("dataType", "Any"),
                                                            "required": ir_out.get("required", True),
                                                            "description": ir_out.get("description", "") or ""
                                                        })
                                                if db_declared_outputs:
                                                    logger.info(
                                                        f"[plan/update] Using ACTUAL screen state from DB for {node['nodeId']} "
                                                        f"(screen_id={old_screen_id}): {[o['name'] for o in db_declared_outputs]} "
                                                        f"vs workflow config: {[o.get('name') for o in declared_outputs if isinstance(o, dict)]}"
                                                    )
                                                    declared_outputs = db_declared_outputs
                                            else:
                                                # Fallback: try generation spec from screen doc
                                                gen_doc = latest_screen_doc.get("generation") or {}
                                                gen_outputs = gen_doc.get("outputs") or []
                                                if gen_outputs:
                                                    db_declared_outputs = []
                                                    for o in gen_outputs:
                                                        if isinstance(o, dict) and o.get("name"):
                                                            db_declared_outputs.append(o)
                                                    if db_declared_outputs:
                                                        logger.info(
                                                            f"[plan/update] Using ACTUAL screen generation outputs from DB for {node['nodeId']}: "
                                                            f"{[o['name'] for o in db_declared_outputs]}"
                                                        )
                                                        declared_outputs = db_declared_outputs
                                    except Exception as _e:
                                        logger.debug(f"[plan/update] Could not fetch latest screen doc for {old_screen_id}: {_e}")

                                    def _io_params(params: list) -> list:
                                        out = []
                                        for p in (params or []):
                                            if p is None:
                                                logger.warning(f"[plan/update] _io_params: skipping None item in params")
                                                continue
                                            try:
                                                if isinstance(p, dict):
                                                    out.append({
                                                        "name": p.get("name", ""),
                                                        "dataType": p.get("dataType") or p.get("datatype") or "Any",
                                                        "required": bool(p.get("required", False)),
                                                        "description": p.get("description", "") or "",
                                                        **_list_item_io_fields(p),
                                                    })
                                                else:
                                                    out.append({
                                                        "name": getattr(p, "name", ""),
                                                        "dataType": _io_data_type(p),
                                                        "required": bool(getattr(p, "required", False)),
                                                        "description": getattr(p, "description", "") or "",
                                                        **_list_item_io_fields(p),
                                                    })
                                            except Exception as e:
                                                logger.error(f"[plan/update] _io_params failed for item {p}: {e}")
                                                raise
                                        return out

                                    # For directly modified screens, use declaredOutputs as the source of truth
                                    # for outputParameters, since it's been synced from impact report
                                    # with new outputs (e.g., number_3). gen_spec.outputs may be stale.
                                    output_params = declared_outputs
                                    # Handle both dict and Pydantic model cases
                                    output_names = []
                                    for o in output_params:
                                        if isinstance(o, dict):
                                            name = o.get('name')
                                        else:
                                            name = getattr(o, 'name', None)
                                        if name:
                                            output_names.append(name)
                                    logger.info(f"[plan/update] Using declaredOutputs as outputParameters for {node['nodeId']}: {output_names}")

                                    # DEBUG: Log what we're passing to _io_params
                                    logger.debug(f"[plan/update] gen_spec={gen_spec}, type={type(gen_spec)}, output_params={output_params}, type={type(output_params)}")

                                    io_rows = {
                                        "inputParameters": _io_params(gen_spec.get("inputs", []) if gen_spec else []),
                                        "outputParameters": _io_params(output_params),
                                    }
                                    _user_update_prompt = (info.get("prompt") or "").strip()
                                    _prev_screen_desc = (gen_spec.get("description") or "").strip() if gen_spec else ""
                                    gen_prompt = (
                                        f"USER REQUEST (implement exactly these changes — preserve everything else verbatim):\n"
                                        f"{_user_update_prompt}\n\n"
                                        f"PREVIOUS SCREEN DESCRIPTION (context only — describes what the screen currently is; "
                                        f"DO NOT re-emit any heading, title, label, or UI chrome that is not explicitly mentioned in the USER REQUEST above):\n"
                                        f"{_prev_screen_desc}\n\n"
                                        f"{WORKFLOW_IO_CONTRACT_SCREEN_MARKER}\n"
                                        f"{json.dumps(io_rows, indent=2)}\n\n"
                                        f"{_NO_GENERIC_OUTPUTS_CONSTRAINT}\n"
                                        f"\n\nUI CHROME PROHIBITION (HARD CONSTRAINT):\n"
                                        f"- Do NOT introduce new page-level <h1>/<h2> headings, top-of-page title bars, breadcrumbs, "
                                        f"or section dividers UNLESS the USER REQUEST above explicitly quotes the exact text to display.\n"
                                        f"- If the existing screen has no heading today, do NOT add one now.\n"
                                        f"- Preserve the existing component scaffold, layout, Tailwind classes, div nesting, "
                                        f"button sizes, and visual hierarchy exactly as they currently are.\n"
                                        f"- Minimal surgical changes only — do NOT 'improve', reformat, or restructure.\n"
                                    ).strip()

                                    try:
                                        result = await update_angular_screen_async({
                                            "project_id": project_id,
                                            "screen_id": old_screen_id,
                                            "screen_name": info["screen_name"],
                                            "prompt": gen_prompt,
                                            "orgId": org_id,
                                            "subscriberId": subscriber_id,
                                            "userId": user_id,
                                            "impact_report": pipeline_state.impact_report.to_dict() if pipeline_state.impact_report else None,
                                        })
                                    except WorkflowBudgetExhaustedError as _budget_err:
                                        budget_errors.append(f"Angular update budget exhausted: {_budget_err}")
                                        logger.warning(
                                            f"[plan/update] Angular update budget exhausted for "
                                            f"{old_screen_id}: {_budget_err}"
                                        )
                                        # Re-raise to let global exception handler enrich with full billing details
                                        raise
                                    except Exception as _ua_err:
                                        logger.warning(
                                            f"[plan/update] Angular update failed for "
                                            f"{old_screen_id}: {_ua_err}; falling back to bump clone."
                                        )
                                        result = None
                                    await _finalize_ui_screen_update(
                                        phase_graphs=phase_graphs,
                                        node=node,
                                        old_screen_id=old_screen_id,
                                        result=result,
                                        org_id=org_id,
                                        subscriber_id=subscriber_id,
                                        user_id=user_id,
                                        project_id=project_id,
                                        bumped_map=screen_bumps,
                                        all_warnings=all_warnings,
                                    )

                                    # Regenerate generationDescription using FINAL declaredOutputs from Angular
                                    try:
                                        from regeneration import regenerate_gap_resolution, build_available_vars_register, build_node_batch_plan
                                        pg_graph = phase.get("graph", {})
                                        global_inputs = [{"name": g, "dataType": "string"} for g in pg_graph.get("requiredGlobalInputs", [])]
                                        node_batch_plan = build_node_batch_plan(pg_graph)
                                        available_vars = build_available_vars_register(pg_graph, node_batch_plan, global_inputs)

                                        cfg = node.get("config")
                                        if not isinstance(cfg, dict):
                                            cfg = {}
                                            node["config"] = cfg
                                        cfg["_update_request"] = proposed_changes.get(node["nodeId"], {}).get("_update_request", "")
                                        # Also persist the extracted force_include_names as a
                                        # typed field so it survives Pydantic model_dump.
                                        try:
                                            _ui_prompt = cfg.get("_update_request") or ""
                                            node["config"]["force_include_names"] = list(
                                                _extract_force_include_names(_ui_prompt)
                                            )
                                        except Exception:
                                            pass
                                        logger.info(f"[plan/update] Calling regenerate_gap_resolution for {node['nodeId']} with declaredOutputs: {[o.get('name') for o in node.get('config', {}).get('declaredOutputs', [])]}")
                                        new_desc = await regenerate_gap_resolution(node, available_vars, _tracked_llm_caller)
                                        logger.info(f"[plan/update] regenerate_gap_resolution returned: {new_desc[:200]}...")
                                        kept = _frozen_intent_description(cfg)
                                        if kept and not _is_generic_io_summary_description(kept):
                                            # User UX/domain intent must survive plan/update. The LLM
                                            # rewrite is I/O-oriented and must not replace it.
                                            if _is_generic_io_summary_description(cfg.get("generationDescription")):
                                                cfg["generationDescription"] = kept
                                            logger.info(
                                                f"[plan/update] Kept original generationDescription for "
                                                f"{node['nodeId']} ({len(kept)} chars); ignored I/O rewrite."
                                            )
                                        else:
                                            node["config"]["generationDescription"] = new_desc
                                            if "generation" not in node["config"] or not isinstance(node["config"]["generation"], dict):
                                                node["config"]["generation"] = {}
                                            node["config"]["generation"]["description"] = new_desc
                                            logger.info(f"[plan/update] Regenerated generationDescription for {node['nodeId']} via LLM (post-angular-update)")
                                    except WorkflowBudgetExhaustedError as _budget_err:
                                        budget_errors.append(f"GenerationDescription regeneration budget exhausted: {_budget_err}")
                                        logger.warning(f"[plan/update] Regeneration budget exhausted for {node['nodeId']}: {_budget_err}")
                                        # Re-raise to let global exception handler enrich with full billing details
                                        raise
                                    except Exception as _regen_err:
                                        logger.warning(f"[plan/update] Failed to regenerate generationDescription via LLM (post-angular-update): {_regen_err}")
                                        import traceback
                                        logger.warning(f"[plan/update] Traceback: {traceback.format_exc()}")
                                        # Programmatic fallback: generate basic description from declaredOutputs
                                        # so the description at least matches the outputs count
                                        try:
                                            kept = _frozen_intent_description(node.get("config") or {})
                                            if kept and not _is_generic_io_summary_description(kept):
                                                logger.info(
                                                    f"[plan/update] Skipping programmatic I/O fallback; "
                                                    f"original description still present for {node['nodeId']}"
                                                )
                                            else:
                                                declared_outputs = node.get("config", {}).get("declaredOutputs", [])
                                                if declared_outputs:
                                                    output_names = [o.get("name", "") for o in declared_outputs if o.get("name")]
                                                    if output_names:
                                                        if len(output_names) == 1:
                                                            outputs_desc = f"one output: `{output_names[0]}`"
                                                        elif len(output_names) == 2:
                                                            outputs_desc = f"two outputs: `{output_names[0]}` and `{output_names[1]}`"
                                                        else:
                                                            outputs_desc = f"{len(output_names)} outputs: " + ", ".join(f"`{n}`" for n in output_names[:-1]) + f", and `{output_names[-1]}`"
                                                        fallback_desc = f"This UI screen presents input fields and returns {outputs_desc}."
                                                        node["config"]["generationDescription"] = fallback_desc
                                                        if "generation" not in node["config"] or not isinstance(node["config"]["generation"], dict):
                                                            node["config"]["generation"] = {}
                                                        node["config"]["generation"]["description"] = fallback_desc
                                                        logger.info(f"[plan/update] Used programmatic fallback for generationDescription: {fallback_desc}")
                                        except Exception as _fallback_err:
                                            logger.warning(f"[plan/update] Programmatic fallback also failed: {_fallback_err}")
                        if screen_bumps:
                            all_warnings.append(
                                f"[Screens] Bumped {len(screen_bumps)} ui_screen(s) to "
                                f"fresh screen_generations row(s) for rollback safety."
                            )

                        # ============================================================
                        # REGENERATE DOWNSTREAM IMPACTED NODES (from impact report)
                        # ============================================================
                        # After direct updates succeed, also regenerate downstream nodes
                        # that the impact report flagged as requiring regeneration.
                        # This implements the user-approved cascade: preview → approve →
                        # update direct + impacted nodes.
                        if pipeline_state.impact_report:
                            downstream_to_regenerate = [
                                n for n in pipeline_state.impact_report.all_affected_nodes
                                if not n.is_directly_modified and n.requires_regeneration
                            ]
                            if downstream_to_regenerate:
                                all_warnings.append(
                                    f"[Downstream] Regenerating {len(downstream_to_regenerate)} "
                                    f"impacted downstream node(s) per approved impact analysis."
                                )
                                logger.info(
                                    f"[plan/update] Regenerating downstream nodes: "
                                    f"{[(n.node_id, n.node_name, n.severity.value) for n in downstream_to_regenerate]}"
                                )
                                # Track downstream tool nodes for regeneration pipeline
                                downstream_tool_ids: Set[str] = set()
                                # Process each downstream node
                                for downstream_impact in downstream_to_regenerate:
                                    downstream_node_id = downstream_impact.node_id
                                    downstream_node_type = downstream_impact.node_type

                                    # Find the node in phase_graphs
                                    downstream_node = None
                                    for pg in phase_graphs:
                                        for node in pg.get("graph", {}).get("nodes", []):
                                            if node.get("nodeId") == downstream_node_id:
                                                downstream_node = node
                                                break
                                        if downstream_node:
                                            break

                                    if not downstream_node:
                                        logger.warning(f"[plan/update] Downstream node {downstream_node_id} not found in phase_graphs")
                                        continue

                                    if downstream_node_type == "ui_screen":
                                        # Regenerate downstream UI screen to update input bindings
                                        await _regenerate_downstream_ui_screen(
                                            downstream_node=downstream_node,
                                            phase_graphs=phase_graphs,
                                            updated_node_ids=updated_node_ids,
                                            proposed_changes=proposed_changes,
                                            impact_report=pipeline_state.impact_report,
                                            project_id=project_id,
                                            org_id=org_id,
                                            subscriber_id=subscriber_id,
                                            user_id=user_id,
                                            all_warnings=all_warnings,
                                            screen_bumps=screen_bumps,
                                        )
                                    elif downstream_node_type == "tool":
                                        # Mark tool for gap resolution regeneration
                                        cfg = downstream_node.get("config")
                                        if not isinstance(cfg, dict):
                                            cfg = {}
                                            downstream_node["config"] = cfg
                                        cfg["_requires_regeneration"] = True
                                        # Preserve the update context for gap resolution
                                        cfg["_downstream_update"] = True
                                        # Track for regeneration pipeline
                                        downstream_tool_ids.add(downstream_node_id)
                                        logger.info(f"[plan/update] Marked downstream tool {downstream_node_id} for regeneration")
                                    # Other node types (router, agent:workflow) handled by gap resolution

                                # Run update regeneration pipeline for downstream tools
                                if downstream_tool_ids:
                                    try:
                                        from regeneration import run_update_regeneration_pipeline
                                        # Combine original updated nodes with downstream tools
                                        all_regen_nodes = updated_node_ids | downstream_tool_ids
                                        await run_update_regeneration_pipeline(
                                            phase_graphs=phase_graphs,
                                            updated_node_ids=all_regen_nodes,
                                            llm_caller=_tracked_llm_caller,
                                        )
                                        logger.info(f"[plan/update] Regeneration pipeline completed for downstream tools: {downstream_tool_ids}")
                                    except WorkflowBudgetExhaustedError as _budget_err:
                                        budget_errors.append(f"Downstream tool regeneration budget exhausted: {_budget_err}")
                                        logger.warning(f"[plan/update] Downstream tool regeneration budget exhausted: {_budget_err}")
                                        raise
                                    except Exception as _regen_err:
                                        logger.warning(f"[plan/update] Downstream tool regeneration failed: {_regen_err}")
                                        all_warnings.append(f"[Downstream] Tool regeneration failed: {_regen_err}")

                        # UI screens: trigger Angular generator via gap_generations.
                        # screen_generations history preservation is handled by the
                        # update_angular_screen_async path (called downstream of gap
                        # resolution for ui:* nodes). Each UPDATE produces a NEW
                        # screen_id with a fresh version row — old rows are untouched,
                        # and /plan/restore shifts the capabilityRef back to the
                        # prior screen_id.
                        # Pass already-updated screen IDs to avoid double-processing
                        already_updated = set(screen_bumps.values())
                        _trigger_angular_updates_for_ui_screens(
                            phase_graphs,
                            updated_node_ids,
                            plans=pipeline_state.edit_plans,
                            proposed_changes=proposed_changes,
                            already_updated_screen_ids=already_updated,
                        )

                    # Phase 3 (validation & repair) — surface errors + applied fixes
                    if pipeline_state.validation_report and pipeline_state.validation_report.issues:
                        for issue in pipeline_state.validation_report.issues:
                            all_warnings.append(f"[Validation] {issue.message}")
                    if pipeline_state.applied_fixes:
                        successful_fixes = sum(
                            1 for f in pipeline_state.applied_fixes if f.get("success")
                        )
                        all_warnings.append(
                            f"[Validation] {successful_fixes}/{len(pipeline_state.applied_fixes)} "
                            f"auto-fix(es) applied successfully."
                        )
                else:
                    # Validation didn't pass after max_iterations — treat as failure and
                    # fall through to legacy fallback.
                    # Log detailed validation issues for debugging
                    if pipeline_state.validation_report and pipeline_state.validation_report.issues:
                        for issue in pipeline_state.validation_report.issues:
                            logger.warning(
                                f"[plan/update] Validation FAILED: "
                                f"severity={issue.severity.value} category={issue.category.value} "
                                f"node={issue.node_id} message={issue.message}"
                            )
                            all_warnings.append(
                                f"[Validation-FAILED] {issue.category.value}: "
                                f"{issue.message} (node: {issue.node_id or 'N/A'})"
                            )
                    raise RuntimeError(
                        f"Integrated pipeline did not pass validation after "
                        f"{pipeline_state.iteration}/{pipeline_state.max_iterations} iteration(s): "
                        f"{pipeline_state.error_message}"
                    )

            except WorkflowBudgetExhaustedError as _budget_err:
                budget_errors.append(f"Integrated pipeline budget exhausted: {_budget_err}")
                logger.warning(
                    f"[plan/update] Integrated pipeline budget exhausted: {_budget_err}"
                )
                # Re-raise to let global exception handler enrich with full billing details
                raise

            except Exception as _ipe:
                # NO LEGACY FALLBACK - re-raise to surface the actual error
                logger.error(
                    f"[plan/update] Integrated pipeline failed "
                    f"({type(_ipe).__name__}: {_ipe}); NO FALLBACK - re-raising."
                )
                all_warnings.append(
                    f"[Error] Integrated pipeline failed: "
                    f"{type(_ipe).__name__}: {_ipe}"
                )
                raise

        pre_gap_phase_results: list[PhaseGraphResult] = []
        for pg in phase_graphs:
            try:
                graph_def = GraphDefinition(**pg["graph"])
            except Exception as _pg_err:
                logger.warning(f"[plan/update] Could not parse graph for phase, skipping gap resolution: {_pg_err}")
                continue
            pre_gap_phase_results.append(PhaseGraphResult(
                graph=graph_def,
                gap_generations=pg.get("gap_generations", []),
                phaseType=pg.get("phaseType"),
                validation_warnings=[],
                binding_fixes_applied=pg.get("binding_fixes_applied", 0),
            ))

        # ── 7+8. Gap resolution — GENERATE:* → real tool / ui_screen ─────────
        # NOTE: `all_warnings` was initialized earlier (right after the `tenant` dict) so
        # the integrated pipeline's validation issues land on the same list that gets
        # persisted on the agentic_process doc. Do NOT redeclare it here.
        completed_phase_results: list[PhaseGraphResult] = []

        for pr in pre_gap_phase_results:
            graph = pr.graph
            phase_id = graph.phaseId or graph.graphId or "unknown_phase"
            phase_warnings: list[str] = list(pr.validation_warnings)
            user_context = graph.description or graph.goal or graph.phaseName or phase_id

            try:
                graph, gen_ids = await _resolve_gap_generations(
                    graph,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    project_id=project_id,
                    available_credentials=plan_available_credentials,
                )
            except WorkflowBudgetExhaustedError as _budget_err:
                budget_errors.append(f"Gap resolution budget exhausted: {_budget_err}")
                logger.warning(f"[plan/update] Gap resolution budget exhausted: {_budget_err}")
                # Re-raise to let global exception handler enrich with full billing details
                raise
            except UnresolvedGapGenerationError as gap_err:
                fallback_ids, fallback_warnings = _fallback_resolve_unresolved_gap_nodes(graph)
                if fallback_ids:
                    all_warnings.extend(fallback_warnings)
                    gen_ids = fallback_ids
                    logger.warning(
                        "[plan/update] Fallback-resolved %d unresolved gap node(s) for phase '%s' after gap generation failure: %s",
                        len(fallback_ids),
                        phase_id,
                        ", ".join(fallback_ids),
                    )
                else:
                    raise HTTPException(
                        status_code=422,
                        detail={
                            "error": "unresolved_gap_generation",
                            "phaseId": gap_err.phase_id or phase_id,
                            "message": str(gap_err),
                            "unresolvedNodes": gap_err.unresolved,
                            "failures": gap_err.failures,
                        },
                    ) from gap_err
            logger.info(f"[plan/update] Phase '{phase_id}': {len(gen_ids)} gap(s) resolved.")

            # ── Step 6p: Post-gap re-validation ──────────
            if gen_ids:
                graph = await _revalidate_after_gap_gen(
                    graph, gen_ids,
                    user_context=user_context,
                    global_caps=[],
                    max_rounds=2,
                    project_id=project_id,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    api_key=get_gemini_api_key(),
                    available_credentials=plan_available_credentials,
                )
                logger.info(f"[plan/update] Phase '{phase_id}': post-gap re-validation complete.")

            # ── Downstream tool reconciliation ──────────────────────────
            # When a target node (e.g. screen_1) gained a new declaredOutput
            # in this /plan/update, push a re-bind into downstream tool nodes
            # (e.g. tool_1) so they actually consume the new upstream output.
            try:
                # Capture pre-edit declaredOutputs from the original Mongo doc so
                # _compute_unbound_upstream_outputs can diff against the real
                # previous state (proposed_changes is heuristic and unreliable —
                # see _compute_unbound_upstream_outputs docstring for the bug
                # story).
                _pre_edit_declared_outputs: Dict[str, set] = {}
                for _pg in global_snapshot.get("phaseGraphs", []):
                    try:
                        for _node in (_pg.get("graph", {}).get("nodes") or []):
                            _nid = _node.get("nodeId") or _node.get("id")
                            if not _nid:
                                continue
                            _existing = _pre_edit_declared_outputs.setdefault(_nid, set())
                            for _o in ((_node.get("config") or {}).get("declaredOutputs") or []):
                                _onm = (
                                    _o.get("name") if isinstance(_o, dict)
                                    else getattr(_o, "name", None)
                                )
                                if _onm:
                                    _existing.add(_onm)
                    except Exception:
                        continue
                _reconciled = await _reconcile_tool_inputs_from_upstream(
                    graph,
                    proposed_changes,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    project_id=project_id,
                    available_credentials=plan_available_credentials,
                    pre_edit_declared_outputs=_pre_edit_declared_outputs,
                )
                if _reconciled:
                    all_warnings.append(
                        f"[Phase {phase_id}] Reconciled {_reconciled} downstream "
                        f"tool node(s) to newly available upstream output(s)."
                    )
            except BillingError:
                # Don't swallow billing errors - let them propagate so checkpoint can be saved
                raise
            except Exception as _recon_err:
                logger.warning(
                    f"[plan/update] Tool reconciliation failed for phase "
                    f"'{phase_id}': {_recon_err}"
                )

            # ── Tool node enrichment ───────────
            graph = await _enrich_tool_nodes_with_source_and_class_path(graph, tenant=tenant)

            completed_phase_results.append(PhaseGraphResult(
                graph=copy.deepcopy(graph),
                validation_warnings=phase_warnings,
                binding_fixes_applied=pr.binding_fixes_applied,
                gap_generations=gen_ids,
                phaseType=pr.phaseType,
            ))
            all_warnings.extend(phase_warnings)

        # ── Preserve _update_request from original phase_graphs to completed_phase_results ──
        # The original phase_graphs (list of dicts) has _update_request set during update flow.
        # Gap resolution creates new GraphDefinition objects; ensure _update_request is copied over.
        try:
            for pg_idx, pg in enumerate(phase_graphs):
                if pg_idx >= len(completed_phase_results):
                    break
                orig_graph = pg.get("graph", {})
                orig_nodes = {n.get("nodeId"): n for n in orig_graph.get("nodes", [])}
                completed_graph = completed_phase_results[pg_idx].graph
                for completed_node in completed_graph.nodes:
                    orig_node = orig_nodes.get(completed_node.nodeId)
                    if orig_node and isinstance(orig_node.get("config"), dict):
                        # Read from dict (uses alias "_update_request"), write to Pydantic model (uses field name "update_request")
                        update_request = orig_node["config"].get("_update_request")
                        if update_request:
                            completed_node.config.update_request = update_request
        except Exception as _preserve_err:
            logger.warning(f"[plan/update] Failed to preserve _update_request: {_preserve_err}")

        # ── 9. LangGraph code generation ────────────
        combined_code = ""
        try:
            combined_code = _generate_langgraph_code_for_phases(
                completed_phase_results, workflow_name, global_caps=None
            )
        except Exception as _cg_err:
            all_warnings.append(f"LangGraph code generation failed: {_cg_err}")

        for pr in completed_phase_results:
            try:
                pr.langgraph_code = _generate_langgraph_code_for_phases(
                    [pr], workflow_name, global_caps=None
                )
            except Exception:
                pr.langgraph_code = ""

        # ── 10. Persist generated code to disk and run postgen validation ─────
        code_artifacts: Dict[str, Any] = {"savePath": None, "combinedFile": None}
        langgraph_savepath = config.get("langgraph_savepath")
        if langgraph_savepath and combined_code:
            try:
                os.makedirs(langgraph_savepath, exist_ok=True)
                ts = datetime.utcnow().strftime("%Y%m%d%H%M%S")

                def _safe_filename(part: str) -> str:
                    part = (part or "").strip() or "unknown"
                    return "".join(ch if (ch.isalnum() or ch in ("-", "_", ".")) else "_" for ch in part)

                project_id_part = _safe_filename(project_id)
                combined_file = os.path.join(
                    langgraph_savepath,
                    f"pr_{project_id_part}_{ts}.py",
                )
                with open(combined_file, "w", encoding="utf-8") as f:
                    f.write(combined_code)
                code_artifacts["combinedFile"] = combined_file
                code_artifacts["savePath"] = langgraph_savepath
                logger.info(
                    f"[plan/update] Wrote combined file={combined_file} size={os.path.getsize(combined_file)}"
                )

                try:
                    combined_code, postgen_warnings = await _postgen_validate_and_fix(
                        combined_code,
                        combined_file,
                        max_rounds=2,
                        api_key=get_gemini_api_key(),
                        project_id=project_id,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                    )
                    all_warnings.extend(postgen_warnings)
                except Exception as _pg_exc:
                    all_warnings.append(f"Post-generation validation error: {_pg_exc}")
            except Exception as _disk_err:
                all_warnings.append(f"Failed to save LangGraph code files: {_disk_err}")

        # ── 11. Validate all gaps are resolved before saving ─────
        _validate_phase_graphs_gaps_resolved(completed_phase_results)

        # Capture current screen version mapping for UI screen nodes
        screen_version_mapping = {}
        try:
            project_id_for_screens = agentic_process.get("projectId") or payload.workflowId
            screens_coll = db["screens"]
            for phase in agentic_process.get("phaseGraphs", []):
                graph = phase.get("graph", {})
                for node in graph.get("nodes", []):
                    cap_ref = node.get("capabilityRef") or {}
                    if isinstance(cap_ref, dict):
                        cap_id = cap_ref.get("capabilityId", "")
                        if cap_id and cap_id.startswith("ui:"):
                            screen_id = cap_id[3:]
                            # Get current screen pointer version (sync PyMongo)
                            pointer = screens_coll.find_one({"screen_id": screen_id, "project_id": project_id_for_screens})
                            if pointer and pointer.get("current_version"):
                                screen_version_mapping[screen_id] = pointer["current_version"]
                                logger.info(f"[plan/update] Captured screen version for {screen_id}: {pointer['current_version']}")
                            else:
                                logger.warning(f"[plan/update] No pointer found for screen {screen_id} during pre-update capture")
        except Exception as _sv_err:
            logger.warning(f"[plan/update] Failed to capture screen version mapping: {_sv_err}")

        try:
            # IMPORTANT: unique key includes `reason` so pre_update_snapshot is a
            # distinct record from initial_creation / post_update_snapshot /
            # earlier pre_update_snapshots at the same version slot. Otherwise
            # $setOnInsert + upsert silently no-ops when the slot is occupied
            # and we permanently lose the pre-state we need for rollback.
            db["Workflow_Versions"].update_one(
                {
                    "workflowId": payload.workflowId,
                    "version": current_version,
                    "reason": "pre_update_snapshot",
                },
                {"$setOnInsert": {
                    "workflowId": payload.workflowId,
                    "orgId": ObjectId(org_id) if isinstance(org_id, str) else org_id,
                    "subscriberId": ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id,
                    "version": current_version,
                    "saved_at": datetime.utcnow(),
                    "saved_by": user_id,
                    "reason": "pre_update_snapshot",
                    "agentic_process": global_snapshot,
                    "screen_version_mapping": screen_version_mapping,  # NEW: store screen version mapping
                }},
                upsert=True,
            )
            
            highest_history_doc = db["Workflow_Versions"].find_one(
                {"workflowId": payload.workflowId},
                sort=[("version", -1)]
            )
            highest_history_version = highest_history_doc["version"] if highest_history_doc else current_version
            new_version = max(current_version, highest_history_version) + 1

            old_versions = list(
                db["Workflow_Versions"]
                .find({"workflowId": payload.workflowId}, {"_id": 1})
                .sort("version", 1)
            )
            if len(old_versions) > 100:
                ids_to_delete = [v["_id"] for v in old_versions[:len(old_versions) - 100]]
                db["Workflow_Versions"].delete_many({"_id": {"$in": ids_to_delete}})
        except Exception as _ver_err:
            logger.error(f"[plan/update] Failed to save version snapshot: {_ver_err}")
            new_version = current_version + 1
            
        now = datetime.utcnow()
        updated_phase_graphs_serialized = [
            p.model_dump(exclude={"langgraph_code"}) for p in completed_phase_results
        ]
        # Final safety net: drop generic placeholders (``formOutput`` /
        # ``output`` / ``result`` / blank names) from each ui_screen node's
        # declaredOutputs and stateWrites so users never see a confusing
        # fallback name. The primary fix lives in the LLM prompt constraint
        # (FORBIDDEN_OUTPUT_NAMES below), but if a future regression lets one
        # slip through, this strips it before persistence.
        for _pg in updated_phase_graphs_serialized:
            for _n in (_pg.get("graph") or {}).get("nodes") or []:
                if (_n.get("type") or "").lower() not in ("ui_screen",):
                    continue
                _cfg = _n.get("config") or {}
                if not isinstance(_cfg, dict):
                    continue
                _outs = _cfg.get("declaredOutputs")
                if isinstance(_outs, list):
                    _stripped = _strip_generic_declared_outputs(_outs)
                    # LLM generates outputs; no supplementer needed
                    _force_strip = list(dict.fromkeys(
                        list(_extract_force_include_names(_cfg.get("_update_request") or ""))
                        + list(_cfg.get("force_include_names") or [])
                    ))
                    # Hard-append: user force-names survive even when IR drift
                    # has dropped them from adopted
                    _existing_post_strip = {
                        (o.get("name") if isinstance(o, dict) else getattr(o, "name", "")) or ""
                        for o in (_stripped or [])
                    }
                    logger.info(
                        f"[plan/update strip-safety] node={(_n.get('nodeId') or '?')!r} "
                        f"user_prompt={(_cfg.get('_update_request') or '')[:120]!r} "
                        f"force_strip={_force_strip!r} "
                        f"pre_strip_names={[o.get('name') for o in _stripped]!r}"
                    )
                    for _fn in (_force_strip or []):
                        if _fn and _fn not in _existing_post_strip:
                            _stripped.append({
                                "name": _fn,
                                "dataType": "string",
                                "required": False,
                                "description": "Restored from user UPDATE prompt force_include_names.",
                            })
                            _existing_post_strip.add(_fn)
                            logger.info(
                                f"[plan/update strip-safety] HARD-APPENDED {_fn!r} to "
                                f"node={(_n.get('nodeId') or '?')!r}"
                            )
                    if len(_stripped) != len(_outs):
                        logger.info(
                            f"[plan/update] strip-safety: dropped {len(_outs) - len(_stripped)} "
                            f"generic output(s) from node {(_n.get('nodeId') or '?')!r} before persistence"
                        )
                    _cfg["declaredOutputs"] = _stripped
                _writes = _cfg.get("stateWrites")
                if isinstance(_writes, list):
                    _node_id = (_n.get("nodeId") or "")
                    _generic_state_suffixes = frozenset(
                        f"{_node_id}__{n}" for n in _GENERIC_DECLARED_OUTPUT_NAMES
                    )
                    _cleaned = [
                        sw for sw in _writes
                        if not any(sw.endswith(suf) for suf in _generic_state_suffixes)
                    ]
                    if len(_cleaned) != len(_writes):
                        logger.info(
                            f"[plan/update] strip-safety: dropped {len(_writes) - len(_cleaned)} "
                            f"generic state-write(s) from node {_node_id!r} before persistence"
                        )
                    _cfg["stateWrites"] = _cleaned
        # Resolve combined_file_path: prefer the freshly-generated file from this update;
        # fall back to current Process_Configs only if regeneration didn't produce one.
        # CRITICAL: when we fall back, log a loud warning — execution at this new version
        # will run code from a previous version, which is a correctness regression.
        regenerated_combined_file = code_artifacts.get("combinedFile")
        current_combined_file_path = doc.get("agentic_process", {}).get("combined_file_path")

        if regenerated_combined_file:
            new_combined_file_path = regenerated_combined_file
            logger.info(f"[plan/update] Using freshly generated combined_file_path: {new_combined_file_path}")
        else:
            new_combined_file_path = current_combined_file_path
            if current_combined_file_path:
                logger.warning(
                    f"[plan/update] ⚠️ LangGraph code regeneration did NOT produce a new file for "
                    f"workflow {payload.workflowId} version {new_version}. Falling back to existing "
                    f"combined_file_path={current_combined_file_path}. Execution at this version will "
                    f"run code from the prior version — this is usually a sign that _generate_langgraph_code "
                    f"returned empty or that langgraph_savepath could not be written."
                )

        # Fallback: if still null, find latest Workflow_Version with valid path
        if not new_combined_file_path:
            latest_with_path = db["Workflow_Versions"].find_one(
                {"workflowId": payload.workflowId, "agentic_process.combined_file_path": {"$ne": None}},
                sort=[("version", -1)]
            )
            if latest_with_path and latest_with_path.get("agentic_process", {}).get("combined_file_path"):
                new_combined_file_path = latest_with_path["agentic_process"]["combined_file_path"]
                logger.warning(
                    f"[plan/update] ⚠️ No combined_file_path at all for workflow {payload.workflowId} "
                    f"version {new_version}; using historical fallback from v{latest_with_path.get('version')}: "
                    f"{new_combined_file_path[:80]}..."
                )

        logger.info(f"[plan/update] Final combined_file_path for v{new_version}: {new_combined_file_path}")

        try:
            db["Process_Configs"].update_one(
                {"_id": doc["_id"]},
                {
                    "$set": {
                        "agentic_process.phaseGraphs": updated_phase_graphs_serialized,
                        "agentic_process.combined_file_path": new_combined_file_path,
                        "agentic_process.warnings": all_warnings,
                        "agentic_process.version": new_version,
                        # Persist which pipeline path executed so the next time the workflow
                        # is opened (read-only — without re-calling /plan/update), the UI can
                        # surface a banner / icon if the latest update used legacy fallback.
                        "agentic_process.last_update_pipeline": pipeline_used,
                        "agentic_process.last_update_at": now,
                        "updated_at": now,
                    },
                    # Clear any stale preview cache after successful update
                    "$unset": {"agentic_process.pending_update_preview": ""},
                },
            )
            logger.info(f"[plan/update] Workflow '{payload.workflowId}' persisted to Process_Configs as version {new_version}.")

            # Capture updated screen version mapping for the new version
            new_screen_version_mapping = {}
            try:
                project_id_for_screens = agentic_process.get("projectId") or payload.workflowId
                screens_coll = db["screens"]

                # Get screen IDs from the completed phase graphs (after gap resolution)
                screen_ids = set()
                for pr in completed_phase_results:
                    if hasattr(pr, 'graph') and pr.graph and hasattr(pr.graph, 'nodes'):
                        for node in pr.graph.nodes:
                            cap_ref = getattr(node, 'capabilityRef', None)
                            if cap_ref and isinstance(cap_ref, dict):
                                cap_id = cap_ref.get("capabilityId", "")
                                if cap_id and cap_id.startswith("ui:"):
                                    screen_ids.add(cap_id[3:])

                # Also check updated_phase_graphs_serialized as fallback
                if not screen_ids:
                    for phase in updated_phase_graphs_serialized:
                        graph = phase.get("graph", {})
                        for node in graph.get("nodes", []):
                            cap_ref = node.get("capabilityRef") or {}
                            if isinstance(cap_ref, dict):
                                cap_id = cap_ref.get("capabilityId", "")
                                if cap_id and cap_id.startswith("ui:"):
                                    screen_ids.add(cap_id[3:])

                logger.info(f"[plan/update] Found screen IDs to capture mapping: {screen_ids}")

                for screen_id in screen_ids:
                    pointer = screens_coll.find_one({"screen_id": screen_id, "project_id": project_id_for_screens})
                    if pointer and pointer.get("current_version"):
                        new_screen_version_mapping[screen_id] = pointer["current_version"]
                        logger.info(f"[plan/update] New version screen mapping for {screen_id}: {pointer['current_version']}")
                    else:
                        logger.warning(f"[plan/update] No pointer found for screen {screen_id}")

            except Exception as _sv_err:
                logger.warning(f"[plan/update] Failed to capture new screen version mapping: {_sv_err}")

            # ── NEW: Save the new version snapshot with FINAL state (including combined_file_path) ─────
            try:
                final_agentic_process = doc.get("agentic_process", {}).copy()
                final_agentic_process["phaseGraphs"] = updated_phase_graphs_serialized
                # Mirror the resolution done for Process_Configs so the post-update
                # snapshot and the working document agree on which file is executable.
                final_agentic_process["combined_file_path"] = new_combined_file_path
                logger.info(f"[plan/update] Saving combined_file_path: {final_agentic_process['combined_file_path']}")
                final_agentic_process["warnings"] = all_warnings
                final_agentic_process["version"] = new_version
                final_agentic_process["last_update_pipeline"] = pipeline_used
                final_agentic_process["last_update_at"] = now

                db["Workflow_Versions"].update_one(
                    {"workflowId": payload.workflowId, "version": new_version},
                    {"$set": {
                        "workflowId": payload.workflowId,
                        "orgId": ObjectId(org_id) if isinstance(org_id, str) else org_id,
                        "subscriberId": ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id,
                        "version": new_version,
                        "saved_at": datetime.utcnow(),
                        "saved_by": user_id,
                        "reason": "post_update_snapshot",
                        "agentic_process": final_agentic_process,
                        "screen_version_mapping": new_screen_version_mapping,  # NEW: store screen version mapping
                    }},
                    upsert=True,
                )
                logger.info(f"[plan/update] Saved post-update version snapshot for version {new_version}")
            except Exception as _ver_err:
                logger.warning(f"[plan/update] Failed to save post-update version snapshot: {_ver_err}")

        except Exception as _db_err:
            all_warnings.append(f"Failed to persist updated workflow: {_db_err}")
            logger.error(f"[update] DB persist failed for '{payload.workflowId}': {_db_err}")

        # ── 13. Upsert workflow-level capability ─────────
        try:
            phase_names = [
                (pr.graph.phaseName or pr.graph.phaseId or "").strip()
                for pr in completed_phase_results
                if getattr(pr, "graph", None) is not None
            ]
            phase_names = [p for p in phase_names if p]
            desc_core = (
                (agentic_process.get("prompt") or "").strip()
                or (f"Agentic workflow with phases: {', '.join(phase_names)}" if phase_names else f"Agentic workflow {workflow_name}")
            )
            capability_doc: Dict[str, Any] = {
                "capabilityId": f"agent:workflow:{payload.workflowId}",
                "kind": "agent",
                "name": workflow_name,
                "description": desc_core,
                "inputParameters": [],
                "outputParameters": [],
                "version": "1",
                "isLatest": True,
                "status": "active",
                "source": {
                    "sourceType": "workflow_details",
                    "sourceRef": {"workflowId": payload.workflowId},
                    "sourceUpdatedAt": now,
                    "syncedAt": now,
                },
                "runtime": {
                    "agent": {
                        "workflowId": payload.workflowId,
                        "workflowName": workflow_name,
                        "agentState": "stable",
                    }
                },
                "searchText": f"{workflow_name} {desc_core}".strip(),
                "tags": ["agentic", "graph", "workflow"],
            }
            await capability_repository.upsert_capability(tenant, capability_doc)
            await capability_repository.set_is_latest_for_capability(tenant, f"agent:workflow:{payload.workflowId}")

            # ── NEW: Explicitly fix isLatest flags for ALL screen capabilities in this workflow ─────
            # This prevents DB inconsistency where multiple versions have isLatest=True.
            # We iterate over all screen IDs found in the workflow and call
            # set_is_latest_for_capability for each one. This is idempotent and safe.
            try:
                screen_cap_ids = set()
                for pr in completed_phase_results:
                    if hasattr(pr, 'graph') and pr.graph and hasattr(pr.graph, 'nodes'):
                        for node in pr.graph.nodes:
                            cap_ref = getattr(node, 'capabilityRef', None)
                            if cap_ref and isinstance(cap_ref, dict):
                                cap_id = cap_ref.get("capabilityId", "")
                                if cap_id and cap_id.startswith("ui:"):
                                    screen_cap_ids.add(cap_id)
                # Also check updated_phase_graphs_serialized as fallback
                if not screen_cap_ids:
                    for phase in updated_phase_graphs_serialized:
                        graph = phase.get("graph", {})
                        for node in graph.get("nodes", []):
                            cap_ref = node.get("capabilityRef") or {}
                            if isinstance(cap_ref, dict):
                                cap_id = cap_ref.get("capabilityId", "")
                                if cap_id and cap_id.startswith("ui:"):
                                    screen_cap_ids.add(cap_id)

                logger.info(f"[plan/update] Explicitly fixing isLatest flags for {len(screen_cap_ids)} screen capabilities")
                for screen_cap_id in screen_cap_ids:
                    try:
                        await capability_repository.set_is_latest_for_capability(tenant, screen_cap_id)
                    except Exception as _sc_err:
                        logger.warning(f"[plan/update] Failed to fix isLatest for {screen_cap_id}: {_sc_err}")
            except Exception as _sc_outer_err:
                logger.warning(f"[plan/update] Failed to fix isLatest flags for screen capabilities: {_sc_outer_err}")
        except Exception as _cap_err:
            all_warnings.append(f"Failed to upsert workflow capability: {_cap_err}")

        return {
            "success": True,
            "message": "Update transaction complete.",
            "workflowId": payload.workflowId,
            "version": new_version,
            "updatedNodes": list(updated_node_ids),
            "warnings": all_warnings,
            "phaseGraphs": updated_phase_graphs_serialized,
            "combinedLanggraphCode": combined_code,
            # Pipeline signal so frontend can tell which path ran:
            #   "integrated"      → Phase 1+2+3 succeeded via orchestrator
            #   "legacy_fallback" → integrated failed; legacy run_update_regeneration_pipeline ran
            #   "none"            → no updated nodes (e.g. pure DELETE/INSERT); no edit pipeline ran
            "pipelineUsed": pipeline_used,
            "hadFallback": pipeline_used == "legacy_fallback",
            # Budget exhaustion errors (if any) so frontend can surface them
            "budgetErrors": budget_errors if budget_errors else None,
        }

    except HTTPException:
        raise
    except BillingError as _bill_err:
        # Save checkpoint for resume before re-raising
        try:
            # Build phase graphs snapshot from completed_phase_results if available,
            # otherwise from the current state
            if 'completed_phase_results' in locals() and completed_phase_results:
                phase_graphs_snapshot = [
                    p.model_dump(exclude={"langgraph_code"}) for p in completed_phase_results
                ]
            elif 'pre_gap_phase_results' in locals() and pre_gap_phase_results:
                phase_graphs_snapshot = [
                    p.model_dump(exclude={"langgraph_code"}) for p in pre_gap_phase_results
                ]
            else:
                phase_graphs_snapshot = phase_graphs  # original from DB

            # Get prior phase outputs
            prior_outputs = {}
            if 'prior_phase_outputs' in locals() and prior_phase_outputs:
                prior_outputs = prior_phase_outputs

            # Get the current node being processed (for tool reconciliation)
            current_node_id = last_execute_snapshot.get("node_id") if 'last_execute_snapshot' in locals() else None

            # Write checkpoint with plan_update stage
            await asyncio.to_thread(
                write_checkpoint,
                db=db,
                workflow_id=payload.workflowId,
                subscriber_id=subscriber_id,
                org_id=org_id,
                user_id=user_id,
                status="paused_credit",
                pipeline_stage="plan_update",
                phase_index=0,  # plan_update is a single stage
                phase_total=1,
                phase_graphs=phase_graphs_snapshot,
                prior_phase_outputs=prior_outputs,
                request_context=payload.model_dump(),
                last_error={
                    "code": _bill_err.code,
                    "message": str(_bill_err),
                    "at": datetime.utcnow().isoformat(),
                },
                current_node_id=current_node_id,
            )

            # Update workflow status
            await asyncio.to_thread(
                set_workflow_agentic_status,
                db=db,
                workflow_id=payload.workflowId,
                subscriber_id=subscriber_id,
                org_id=org_id,
                user_id=user_id,
                status="paused_credit",
            )

            # Publish paused credit event
            _pause_detail = _billing_pause_error(
                _bill_err, workflow_id=payload.workflowId, subscriber_id=subscriber_id
            )
            await _publish_paused_credit(payload.workflowId, _pause_detail)

            logger.info(
                f"[plan/update] Saved paused_credit checkpoint for workflow {payload.workflowId} "
                f"due to budget exhaustion: {_bill_err}"
            )
        except Exception as _cp_err:
            logger.warning(f"[plan/update] Failed to save budget exhaustion checkpoint: {_cp_err}")

        raise
    except Exception as e:
        if "doc" in locals() and doc:
            logger.error(f"[update] Unhandled error for '{payload.workflowId}', rolling back: {e}")
            try:
                db["Process_Configs"].update_one(
                    {"_id": doc["_id"]},
                    {"$set": {"agentic_process": global_snapshot, "updated_at": datetime.utcnow()}},
                )
            except Exception as _rb_err:
                logger.error(f"[update] Rollback also failed: {_rb_err}")
        raise HTTPException(status_code=500, detail={"error": "Update failed. Workflow rolled back.", "reason": str(e)})
    finally:
        if "project_id" in locals() and project_id:
            try:
                release_workflow_reservation(
                    project_id=project_id,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                )
            except Exception as _rel_err:
                logger.warning(f"[update] Failed to release workflow reservation: {_rel_err}")


# Restore Payload Model
class WorkflowRestorePayload(BaseModel):
    workflowId: str
    version: int

# Restore Workflow Route
@app.post("/aiqod-agent/agent/agentic/plan/restore")
async def restore_workflow_plan(
    payload: WorkflowRestorePayload,
    http_request: Request,
):
    try:
        org_id = http_request.headers.get("x-org-id")
        subscriber_id = http_request.headers.get("x-subscriber-id")
        user_id = http_request.headers.get("x-user-id")

        if not subscriber_id:
            raise HTTPException(status_code=400, detail="subscriberId is required.")

        query = {
            "engineType": "agentic_graph",
            "agentic_process.workflow_id": payload.workflowId,
            "subscriberId": ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id,
        }
        if org_id:
            query["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id

        doc = db["Process_Configs"].find_one(query)
        if not doc:
            raise HTTPException(status_code=404, detail="Workflow not found in Process_Configs.")

        workflow_version_doc = db["Workflow_Versions"].find_one({
            "workflowId": payload.workflowId,
            "version": payload.version,
        })
        if not workflow_version_doc:
            raise HTTPException(status_code=404, detail=f"Version {payload.version} not found for workflow '{payload.workflowId}'.")

        current_agentic_process = doc.get("agentic_process", {})
        restored_agentic_process = copy.deepcopy(workflow_version_doc["agentic_process"])

        # Deduplication Check
        current_compare = copy.deepcopy(current_agentic_process)
        target_compare = copy.deepcopy(restored_agentic_process)
        current_compare.pop("version", None)
        target_compare.pop("version", None)

        if current_compare == target_compare:
            return {
                "success": True,
                "message": f"Workflow is already structurally identical to version {payload.version}. No restoration needed.",
                "workflowId": payload.workflowId,
                "restoredVersion": payload.version,
                "activeVersion": current_agentic_process.get("version", 1)
            }

        current_version = current_agentic_process.get("version", 1)

        # Save Current State Snapshot
        try:
            db["Workflow_Versions"].update_one(
                {"workflowId": payload.workflowId, "version": current_version},
                {"$setOnInsert": {
                    "workflowId": payload.workflowId,
                    "orgId": ObjectId(org_id) if isinstance(org_id, str) else org_id,
                    "subscriberId": ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id,
                    "version": current_version,
                    "saved_at": datetime.utcnow(),
                    "saved_by": user_id,
                    "reason": "pre_restore_snapshot",
                    "agentic_process": copy.deepcopy(current_agentic_process),
                }},
                upsert=True,
            )
            
            old_versions = list(
                db["Workflow_Versions"]
                .find({"workflowId": payload.workflowId}, {"_id": 1})
                .sort("version", 1)
            )
            if len(old_versions) > 100:
                ids_to_delete = [v["_id"] for v in old_versions[:len(old_versions) - 100]]
                db["Workflow_Versions"].delete_many({"_id": {"$in": ids_to_delete}})
        except Exception as _ver_err:
            logger.error(f"[plan/restore] Failed to save pre-restore snapshot: {_ver_err}")

        # Resolve combined_file_path: prefer the path stored in the restored snapshot
        # (so executing v=N actually runs v=N's compiled code). Only fall back to a
        # recompile when the historical .py is no longer on disk.
        restored_combined_file_path = restored_agentic_process.get("combined_file_path")

        # ── NEW: Transactional pre-flight — every restored tool cap_ref MUST
        # map to an extant on-disk tool JSON file. We fail-fast (HTTP 409)
        # here, BEFORE any Mongo write, so the restore can never leave the
        # workflow pointing at a tool whose implementation has been pruned
        # from disk. Existing on-disk tool files are NEVER deleted.
        try:
            _tools_path = (config.get("tools_path") or "tools").strip() or "tools"
            if not os.path.isabs(_tools_path):
                # tools_path in config.json is relative to backend/; resolve
                # CWD-independently so this works under uvicorn reload too.
                _tools_path = os.path.abspath(_tools_path)
            _target_tool_stems: List[Tuple[str, str]] = []  # (cap_id, expected_stem)
            for _phase in restored_agentic_process.get("phaseGraphs", []) or []:
                for _node in (_phase.get("graph") or {}).get("nodes") or []:
                    _cref = _node.get("capabilityRef") or {}
                    _cid = (str(_cref.get("capabilityId") or "")).strip()
                    if _cid.startswith("tool:"):
                        _target_tool_stems.append((_cid, _cid[5:]))
            _orphan_tool_refs: List[Dict[str, str]] = []
            if _target_tool_stems:
                try:
                    _tool_files = os.listdir(_tools_path)
                except FileNotFoundError:
                    _tool_files = []
                _tool_files = [f for f in _tool_files if f.endswith(".json")]
                for _cap_id, _stem in _target_tool_stems:
                    _matches = [f for f in _tool_files if _stem in f]
                    if not _matches:
                        _orphan_tool_refs.append({
                            "capabilityId": _cap_id,
                            "expected_file_glob": f"*{_stem}*.json",
                            "tools_dir": _tools_path,
                        })
            if _orphan_tool_refs:
                logger.error(
                    f"[plan/restore] Aborting — restore targets {len(_orphan_tool_refs)} "
                    f"tool capabilityRef(s) with no matching on-disk JSON file(s): "
                    f"{[o['capabilityId'] for o in _orphan_tool_refs]}"
                )
                raise HTTPException(
                    status_code=409,
                    detail={
                        "error": (
                            "Restore aborted: required tool implementation file is "
                            "missing on disk. On-disk tool files are NEVER deleted by "
                            "this endpoint; restore is aborted instead of leaving the "
                            "workflow pointing at a non-existent tool."
                        ),
                        "orphans": _orphan_tool_refs,
                        "remediation": (
                            "Re-generate the missing tool from any source that has the "
                            "tool's capability (e.g. re-run the UPDATE that produced it), "
                            "or restore to an earlier workflow version whose tool JSON "
                            "files are still on disk."
                        ),
                    },
                )
        except HTTPException:
            raise
        except Exception as _pf_err:
            # Defensive: never let a config-glitch abort the user-facing restore
            # unless we are SURE about the orphan status. Log loud, continue.
            logger.warning(
                f"[plan/restore] Pre-flight cap_ref verification skipped due to "
                f"unexpected error: {_pf_err}"
            )
        if restored_combined_file_path and os.path.exists(restored_combined_file_path):
            logger.info(
                f"[plan/restore] Using restored-version combined_file_path: {restored_combined_file_path}"
            )
        elif restored_combined_file_path:
            logger.warning(
                f"[plan/restore] Restored-version combined_file_path is missing on disk: "
                f"{restored_combined_file_path}. Will recompile from phaseGraphs."
            )
            restored_combined_file_path = None

        if not restored_combined_file_path:
            try:
                langgraph_savepath = config.get("langgraph_savepath")
                if not langgraph_savepath:
                    raise RuntimeError(
                        "langgraph_savepath is not configured; cannot recompile restored workflow."
                    )
                _restored_phase_results: list[PhaseGraphResult] = []
                for _pg in restored_agentic_process.get("phaseGraphs", []):
                    try:
                        _gd = GraphDefinition(**_pg["graph"])
                    except Exception as _pg_parse_err:
                        logger.warning(
                            f"[plan/restore] Skipping unparseable phase during recompile: {_pg_parse_err}"
                        )
                        continue
                    _restored_phase_results.append(PhaseGraphResult(
                        graph=_gd,
                        gap_generations=_pg.get("gap_generations", []),
                        phaseType=_pg.get("phaseType"),
                        validation_warnings=[],
                        binding_fixes_applied=_pg.get("binding_fixes_applied", 0),
                    ))
                _restored_code = _generate_langgraph_code_for_phases(
                    _restored_phase_results,
                    restored_agentic_process.get("workflowName")
                    or doc.get("selectedName")
                    or payload.workflowId,
                    global_caps=None,
                )
                _restored_project_id = (
                    restored_agentic_process.get("projectId") or payload.workflowId
                )
                _restored_project_id_part = "".join(
                    ch if (ch.isalnum() or ch in ("-", "_", ".")) else "_"
                    for ch in (_restored_project_id or "").strip() or "unknown"
                )
                _ts = datetime.utcnow().strftime("%Y%m%d%H%M%S")
                _recombined_file = os.path.join(
                    langgraph_savepath,
                    f"pr_{_restored_project_id_part}_{_ts}.py",
                )
                os.makedirs(langgraph_savepath, exist_ok=True)
                with open(_recombined_file, "w", encoding="utf-8") as _f:
                    _f.write(_restored_code)
                restored_combined_file_path = _recombined_file
                logger.info(
                    f"[plan/restore] Recompiled restored workflow to {restored_combined_file_path} "
                    f"size={os.path.getsize(restored_combined_file_path)}"
                )
            except Exception as _restore_cg_err:
                logger.error(
                    f"[plan/restore] Failed to recompile restored workflow: {_restore_cg_err}"
                )
                raise HTTPException(
                    status_code=500,
                    detail={
                        "error": "Restored version's compiled file is missing and could not be "
                                 "regenerated. Restore aborted.",
                        "reason": str(_restore_cg_err),
                    },
                )

        restored_agentic_process["combined_file_path"] = restored_combined_file_path

        # Pointer Shift Re-assignment
        restored_agentic_process["version"] = payload.version

        db["Process_Configs"].update_one(
            {"_id": doc["_id"]},
            {
                "$set": {
                    "agentic_process": restored_agentic_process,
                    "updated_at": datetime.utcnow()
                }
            },
        )
        logger.info(f"[plan/restore] Workflow '{payload.workflowId}' pointer shifted to view version {payload.version}.")

        # ── NEW: Restore screen versions using stored mapping (exact versions from snapshot) ─────────────
        restored_screens = []
        try:
            from repositories.screen_repository import ScreenRepository
            screen_repo = ScreenRepository()

            # Get the screen version mapping from the workflow version snapshot
            # This contains the EXACT screen versions that were active when this workflow version was created
            screen_version_mapping = workflow_version_doc.get("screen_version_mapping", {}) if isinstance(workflow_version_doc, dict) else {}
            logger.info(f"[plan/restore] Using screen_version_mapping from snapshot: {screen_version_mapping}")

            project_id = restored_agentic_process.get("projectId") or payload.workflowId

            # Find all UI screen nodes in the restored graph
            for phase in restored_agentic_process.get("phaseGraphs", []):
                graph = phase.get("graph", {})
                for node in graph.get("nodes", []):
                    cap_ref = node.get("capabilityRef") or {}
                    if isinstance(cap_ref, dict):
                        cap_id = cap_ref.get("capabilityId", "")
                        if cap_id and cap_id.startswith("ui:"):
                            screen_id = cap_id[3:]

                            # Use the EXACT screen version from the snapshot mapping
                            target_screen_version = screen_version_mapping.get(screen_id)

                            if target_screen_version:
                                logger.info(f"[plan/restore] Restoring screen {screen_id} to exact version from snapshot: {target_screen_version}")
                                screen_version_doc = await screen_repo.get_screen_version_data(project_id, screen_id, target_screen_version)
                                if screen_version_doc:
                                    await screen_repo.update_screens_pointer(
                                        project_id, screen_id, screen_version_doc["version"],
                                        org_id=org_id, subscriber_id=subscriber_id, user_id=user_id
                                    )
                                    # ── NEW: Update isLatest flag in capability_repository ─────────────
                                    # The frontend reads screen content via get_latest_capability_by_id
                                    # which prefers isLatest=True. We must flip the flag to point to the
                                    # restored version, otherwise the frontend will still show v2 content.
                                    try:
                                        from repositories.capability_repository import CapabilityRepository
                                        cap_repo = CapabilityRepository()
                                        cap_coll = cap_repo.get_collection()
                                        # Build tenant filter that matches BOTH docs with userId set
                                        # AND docs with userId=None (some capability docs are written
                                        # without a userId, e.g. system-generated ones).
                                        tenant_filter_base: Dict[str, Any] = {"capabilityId": cap_id}
                                        if org_id:
                                            tenant_filter_base["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id
                                        if subscriber_id:
                                            tenant_filter_base["subscriberId"] = ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id
                                        if user_id:
                                            try:
                                                tenant_filter_base["userId"] = {"$in": [ObjectId(user_id), None]}
                                            except Exception:
                                                tenant_filter_base["userId"] = {"$in": [user_id, None]}
                                        else:
                                            tenant_filter_base["userId"] = None
                                        # Set isLatest=True on the restored version
                                        await cap_coll.update_one(
                                            {**tenant_filter_base, "version": screen_version_doc["version"]},
                                            {"$set": {"isLatest": True, "updatedAt": datetime.utcnow()}},
                                        )
                                        # Set isLatest=False on all other versions of the same capability
                                        await cap_coll.update_many(
                                            {**tenant_filter_base, "version": {"$ne": screen_version_doc["version"]}},
                                            {"$set": {"isLatest": False, "updatedAt": datetime.utcnow()}},
                                        )
                                        logger.info(f"[plan/restore] Updated isLatest flag for capability {cap_id} to version {screen_version_doc['version']}")
                                    except Exception as _cap_err:
                                        logger.warning(f"[plan/restore] Failed to update isLatest for {cap_id}: {_cap_err}")

                                    restored_screens.append({
                                        "screen_id": screen_id,
                                        "restored_version": screen_version_doc["version"],
                                        "deployed_url": screen_version_doc.get("angular", {}).get("public_url")
                                    })
                                    logger.info(f"[plan/restore] Successfully restored screen {screen_id} to version {screen_version_doc['version']}")
                                else:
                                    logger.warning(f"[plan/restore] Screen version data not found for {screen_id} version {target_screen_version}")
                            else:
                                logger.warning(f"[plan/restore] No screen version mapping found for {screen_id} in snapshot - falling back to timestamp lookup")
                                # Fallback to timestamp-based lookup
                                versions = await screen_repo.get_screen_versions(project_id, screen_id)
                                if versions:
                                    workflow_saved_at = workflow_version_doc.get("saved_at") if isinstance(workflow_version_doc, dict) else None
                                    matching_version = None
                                    if workflow_saved_at:
                                        for v in versions:
                                            v_created = v.get("created_at")
                                            if v_created and v_created <= workflow_saved_at:
                                                matching_version = v.get("version")
                                                break
                                    if not matching_version and versions:
                                        matching_version = versions[0].get("version")

                                    if matching_version:
                                        screen_version_doc = await screen_repo.get_screen_version_data(project_id, screen_id, matching_version)
                                        if screen_version_doc:
                                            await screen_repo.update_screens_pointer(
                                                project_id, screen_id, screen_version_doc["version"],
                                                org_id=org_id, subscriber_id=subscriber_id, user_id=user_id
                                            )
                                            # ── NEW: Update isLatest flag in capability_repository (fallback path) ─────────────
                                            try:
                                                from repositories.capability_repository import CapabilityRepository
                                                cap_repo = CapabilityRepository()
                                                cap_coll = cap_repo.get_collection()
                                                # Build tenant filter that matches BOTH docs with userId set
                                                # AND docs with userId=None (some capability docs are written
                                                # without a userId, e.g. system-generated ones).
                                                tenant_filter_base: Dict[str, Any] = {"capabilityId": cap_id}
                                                if org_id:
                                                    tenant_filter_base["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id
                                                if subscriber_id:
                                                    tenant_filter_base["subscriberId"] = ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id
                                                if user_id:
                                                    try:
                                                        tenant_filter_base["userId"] = {"$in": [ObjectId(user_id), None]}
                                                    except Exception:
                                                        tenant_filter_base["userId"] = {"$in": [user_id, None]}
                                                else:
                                                    tenant_filter_base["userId"] = None
                                                await cap_coll.update_one(
                                                    {**tenant_filter_base, "version": screen_version_doc["version"]},
                                                    {"$set": {"isLatest": True, "updatedAt": datetime.utcnow()}},
                                                )
                                                await cap_coll.update_many(
                                                    {**tenant_filter_base, "version": {"$ne": screen_version_doc["version"]}},
                                                    {"$set": {"isLatest": False, "updatedAt": datetime.utcnow()}},
                                                )
                                                logger.info(f"[plan/restore] Fallback: Updated isLatest flag for capability {cap_id} to version {screen_version_doc['version']}")
                                            except Exception as _cap_err:
                                                logger.warning(f"[plan/restore] Fallback: Failed to update isLatest for {cap_id}: {_cap_err}")

                                            restored_screens.append({
                                                "screen_id": screen_id,
                                                "restored_version": screen_version_doc["version"],
                                                "deployed_url": screen_version_doc.get("angular", {}).get("public_url")
                                            })
                                            logger.info(f"[plan/restore] Fallback restored screen {screen_id} to version {screen_version_doc['version']}")

        except Exception as screen_restore_err:
            logger.warning(f"[plan/restore] Screen restoration failed (non-fatal): {screen_restore_err}")

        # Fix Bug 2: Update isLatest flag in capability_repository for the workflow capability
        try:
            tenant = {"orgId": org_id, "subscriberId": subscriber_id, "userId": user_id}
            capability_id = f"agent:workflow:{payload.workflowId}"
            await capability_repository.set_is_latest_for_capability(tenant, capability_id)
            logger.info(f"[plan/restore] Updated isLatest flag for capability {capability_id}")
        except Exception as cap_err:
            logger.warning(f"[plan/restore] Failed to update isLatest flag for capability: {cap_err}")

        # ── NEW: Hot-reload LocalToolRegistry so the next execute_dynamic_tool
        # sees any cap_ref the restore just re-pointed at. We never modify
        # on-disk tool JSON here (per user constraint); we only ask the
        # registry to re-scan its directory.
        #
        # Implementation note: calling into executor.py requires the heavy
        # runtime stack (langgraph.types, valkey, fastapi, etc.), most of
        # which isn't loaded by the agent_new uvicorn process. To avoid a
        # ImportError cascade, we exec the executor source in a stripped
        # namespace (only stdlib + typing / dataclasses imports) and pull
        # out ``LocalToolRegistry`` for instantiation. If even that fails
        # (e.g. missing BaseTool / ToolParameter types), we log a warning
        # AND log a directory snapshot so the operator can verify what the
        # executor's own runtime hot-reload at execute_tool() will pick up.
        try:
            import sys as _sys
            _ex_path = os.path.abspath(
                os.path.join(
                    os.path.dirname(__file__),
                    "..", "langgraph", "app", "executor.py"
                )
            )
            if not os.path.exists(_ex_path):
                raise FileNotFoundError(f"executor.py not at {_ex_path}")
            _safe_prefixes = (
                "import os", "import json", "import time",
                "import asyncio", "import logging", "import sys",
                "import importlib", "import inspect",
                "import re", "import threading",
                "import datetime", "import enum",
                "import uuid", "import textwrap", "import traceback",
                "from typing", "from dataclasses",
                "from pydantic", "from abc", "from enum",
                # Optional/runtime-only: keep pymongo (try/except already wraps it)
                "from pymongo",
            )
            with open(_ex_path, "r", encoding="utf-8") as _f:
                _stripped_src_lines: List[str] = []
                for _line in _f.read().splitlines():
                    _stripped = _line.lstrip()
                    if _stripped.startswith("import ") or _stripped.startswith("from "):
                        if any(_stripped.startswith(p) for p in _safe_prefixes):
                            _stripped_src_lines.append(_line)
                        continue
                    _stripped_src_lines.append(_line)
            _stub_src = "\n".join(_stripped_src_lines)
            import types as _types
            _reg_module = _types.ModuleType("agent_new_tool_registry_compat")
            _sys.modules["agent_new_tool_registry_compat"] = _reg_module
            try:
                exec(_stub_src, _reg_module.__dict__)
                _RegCls = getattr(_reg_module, "LocalToolRegistry", None)
                if _RegCls is None:
                    raise RuntimeError("LocalToolRegistry not found in stub")
                _reg = _RegCls(json_dir=(config.get("tools_path") or "tools"))
                logger.info(
                    f"[plan/restore] Hot-reloaded LocalToolRegistry: "
                    f"{len(_reg.available_tools)} tool(s) now in memory"
                )
            except Exception as _stub_err:
                _json_dir = config.get("tools_path") or "tools"
                if not os.path.isabs(_json_dir):
                    _json_dir = os.path.abspath(_json_dir)
                _tool_files = (
                    sorted(f for f in os.listdir(_json_dir) if f.endswith(".json"))
                    if os.path.isdir(_json_dir) else []
                )
                logger.warning(
                    f"[plan/restore] LocalToolRegistry stub-exec failed "
                    f"({_stub_err}); executor's execute_tool() hot-reload "
                    f"will still pick these up at next call. Found "
                    f"{len(_tool_files)} tool json(s) in {_json_dir}: "
                    f"{_tool_files[:5]}{'...' if len(_tool_files) > 5 else ''}"
                )
        except Exception as _reg_err:
            logger.warning(
                f"[plan/restore] LocalToolRegistry hot-reload skipped: {_reg_err}"
            )

        return {
            "success": True,
            "message": f"Workflow restored to version {payload.version}.",
            "workflowId": payload.workflowId,
            "restoredVersion": payload.version,
            "activeVersion": payload.version,
            "restoredScreens": restored_screens
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail={"error": "Restore failed.", "reason": str(e)})

# Version History Endpoint
@app.get("/aiqod-agent/agent/agentic/plan/versions/{workflowId}")
async def get_workflow_versions(workflowId: str, http_request: Request, screen_id: str = None, step_index: int = None, substep_index: int = None):
    import logging
    logger = logging.getLogger(__name__)
    logger.info(f"[DEBUG] get_workflow_versions called: workflowId={workflowId}, screen_id={screen_id}, step_index={step_index}, substep_index={substep_index}")
    try:
        versions = list(
            db["Workflow_Versions"]
            .find(
                {
                    "workflowId": workflowId,
                    # `pre_update_snapshot` is an internal pre-state saved for rollback
                    # at every UPDATE; without this filter the same `(workflowId, version)`
                    # would appear twice in the listing — once as `initial_creation`
                    # (v=1) or `post_update_snapshot` (v>=2), and once as `pre_update_snapshot`.
                    "reason": {"$ne": "pre_update_snapshot"},
                },
                {"_id": 0, "version": 1, "saved_at": 1, "saved_by": 1, "agentic_process": 1}
            )
            .sort("version", -1)
        )


        node_index = None
        phase_graph_idx = None

        # Use Process_Configs to find node_index/phase_graph_idx once (current workflow structure)
        if screen_id:
            logger.info(f"[DEBUG] Looking up screen_id={screen_id} in Process_Configs")
            current_config = db["Process_Configs"].find_one(
                {"agentic_process.workflow_id": workflowId},
                {"agentic_process": 1}
            )
            if current_config and "agentic_process" in current_config:
                ap = current_config["agentic_process"]
                # Helper to check if capabilityId matches screen_id (handles both ui: and tool: prefixes)
                def cap_matches_screen(cap_id, screen_id):
                    if not cap_id:
                        return False
                    if cap_id.startswith("ui:") and cap_id[3:] == screen_id:
                        return True
                    if cap_id.startswith("tool:") and cap_id[5:] == screen_id:
                        return True
                    return False

                # Try phaseGraphs first
                if "phaseGraphs" in ap:
                    for pg_idx, pg in enumerate(ap["phaseGraphs"]):
                        if pg and "graph" in pg and "nodes" in pg["graph"]:
                            nodes = pg["graph"]["nodes"]
                            for node_idx, node in enumerate(nodes):
                                if node:  # Defensive: nodes array may contain null values
                                    cap_ref = node.get("capabilityRef") or {}
                                    cap_id = cap_ref.get("capabilityId", "")
                                    if cap_matches_screen(cap_id, screen_id):
                                        node_index = node_idx
                                        phase_graph_idx = pg_idx
                                        logger.info(f"[DEBUG] Found screen_id={screen_id} at phaseGraphs[{pg_idx}].graph.nodes[{node_idx}] in Process_Configs")
                                        break
                        if node_index is not None:
                            break

                # If not found in phaseGraphs, try steps/subSteps
                if node_index is None and "steps" in ap and ap["steps"]:
                    for step_idx, step in enumerate(ap["steps"]):
                        if step and "subSteps" in step and step["subSteps"]:
                            for substep_idx, substep in enumerate(step["subSteps"]):
                                if substep:  # Defensive: substeps array may contain null values
                                    cap_ref = substep.get("capabilityRef") or {}
                                    cap_id = cap_ref.get("capabilityId", "")
                                    if cap_matches_screen(cap_id, screen_id):
                                        node_index = substep_idx
                                        phase_graph_idx = step_idx
                                        logger.info(f"[DEBUG] Found screen_id={screen_id} at steps[{step_idx}].subSteps[{substep_idx}] in Process_Configs")
                                        break
                            if node_index is not None:
                                break
                        if node_index is not None:
                            break

            logger.info(f"[DEBUG] Process_Configs lookup complete: node_index={node_index}, phase_graph_idx={phase_graph_idx}")


        for v in versions:
            prompt = ""
            version_screen_id = None
            user_update_prompt = None

            if "agentic_process" in v and isinstance(v["agentic_process"], dict):
                ap = v["agentic_process"]
                logger.info(f"[DEBUG] Version {v.get('version')}: agentic_process keys={list(ap.keys())}")

                # Use the SAME phase_graph_idx and node_index for all versions
                # Try phaseGraphs first
                if node_index is not None and "phaseGraphs" in ap:
                    if 0 <= phase_graph_idx < len(ap.get("phaseGraphs", [])):
                        pg = ap["phaseGraphs"][phase_graph_idx]
                        if "graph" in pg and "nodes" in pg["graph"]:
                            nodes = pg["graph"]["nodes"]
                            if 0 <= node_index < len(nodes):
                                node = nodes[node_index]
                                if node:  # Defensive: nodes array may contain null values
                                    cap_ref = node.get("capabilityRef") or {}
                                    cap_id = cap_ref.get("capabilityId", "")
                                    is_tool_node = cap_id and cap_id.startswith("tool:")
                                    if cap_id and cap_id.startswith("ui:"):
                                        version_screen_id = cap_id[3:]
                                    elif is_tool_node:
                                        version_screen_id = cap_id[5:]
                                    if version_screen_id:
                                        logger.info(f"[DEBUG] Version {v.get('version')}: Found screen_id={version_screen_id} at phaseGraphs[{phase_graph_idx}].graph.nodes[{node_index}]")
                                        # Extract user's update prompt from node config
                                        node_config = node.get("config", {})
                                        # Try both field names for backward compatibility
                                        user_update_prompt = node_config.get("update_request") or node_config.get("_update_request")
                                        # If not in node config, try matching by stepId to subStep description (user's original prompt)
                                        if not user_update_prompt:
                                            node_step_id = node.get("stepId")
                                            if node_step_id and "steps" in ap and ap["steps"]:
                                                for step in ap["steps"]:
                                                    if step and "subSteps" in step and step["subSteps"]:
                                                        for substep in step["subSteps"]:
                                                            if substep and substep.get("stepId") == node_step_id:
                                                                user_update_prompt = substep.get("description", "")
                                                                break
                                                        if user_update_prompt:
                                                            break
                                        # Last resort for tool nodes: generationDescription (LLM-generated prompt)
                                        if not user_update_prompt and is_tool_node:
                                            user_update_prompt = node_config.get("generationDescription", "")

                # Fallback to steps/subSteps using same index
                if not version_screen_id and "steps" in ap and ap["steps"] and node_index is not None:
                    # If we found it in phaseGraphs, use phase_graph_idx for step index
                    # Otherwise fall back to steps directly
                    step_idx = phase_graph_idx if phase_graph_idx is not None else 0
                    if 0 <= step_idx < len(ap["steps"]):
                        step = ap["steps"][step_idx]
                        if step and "subSteps" in step and step["subSteps"]:
                            substeps = step["subSteps"]
                            if 0 <= node_index < len(substeps):
                                substep = substeps[node_index]
                                if substep:  # Defensive: substeps array may contain null values
                                    cap_ref = substep.get("capabilityRef") or {}
                                    cap_id = cap_ref.get("capabilityId", "")
                                    is_tool_substep = cap_id and cap_id.startswith("tool:")
                                    if cap_id and cap_id.startswith("ui:"):
                                        version_screen_id = cap_id[3:]
                                    elif is_tool_substep:
                                        version_screen_id = cap_id[5:]
                                    if version_screen_id:
                                        logger.info(f"[VERSION_HISTORY] Version {v.get('version')}: Found screen_id={version_screen_id} at steps[{step_idx}].subSteps[{node_index}]")
                                        # Extract user's update prompt from substep config
                                        substep_config = substep.get("config", {})
                                        user_update_prompt = substep_config.get("_update_request")
                                        # If not in substep config, try subStep description (user's original prompt)
                                        if not user_update_prompt:
                                            user_update_prompt = substep.get("description", "")
                                        # Last resort for tool substeps: generationDescription (LLM-generated prompt)
                                        if not user_update_prompt and is_tool_substep:
                                            user_update_prompt = substep.get("generationDescription", "")
                                            
                # If we found a version-specific screen_id, query screen_generations
                if version_screen_id:
                    logger.info(f"[DEBUG] Version {v.get('version')}: Querying screen_generations with screen_id={version_screen_id}")
                    screen_gen = db["screen_generations"].find_one(
                        {"screen_id": version_screen_id},
                        {"_id": 0, "prompt": 1}
                    )
                    logger.info(f"[DEBUG] Version {v.get('version')}: screen_gen result: {screen_gen}")
                    if screen_gen and screen_gen.get("prompt"):
                        prompt = screen_gen["prompt"]
                        logger.info(f"[DEBUG] Version {v.get('version')}: Found prompt in screen_generations: {prompt[:100]}...")

                # Fallback: workflow-level prompt extraction
                if not prompt:
                    prompt = ap.get("prompt") or ap.get("description") or ""
                if not prompt:
                    prompt = ap.get("workflowName") or ap.get("name") or ""
                if not prompt and "steps" in ap and ap["steps"]:
                    step_names = [
                        s.get("name") or s.get("description")
                        for s in ap["steps"]
                        if s and (s.get("name") or s.get("description"))
                    ]
                    if step_names:
                        prompt = f"Workflow with {len(ap['steps'])} step(s): {', '.join(step_names[:3])}" + ("..." if len(step_names) > 3 else "")
                if not prompt:
                    prompt = f"Version {v.get('version', '')}"

                # For version 1 (initial_creation), user's prompt = selected screen's subStep description
            if v.get("version") == 1 and not user_update_prompt:
                # Use version's own screen_id (version_screen_id) not the current screen_id
                target_screen_id = version_screen_id

                # First, find the node in phaseGraphs to get its stepId
                matched_node = None
                matched_pg_idx = None
                matched_node_idx = None
                if target_screen_id and "phaseGraphs" in ap:
                    for pg_idx, pg in enumerate(ap.get("phaseGraphs", [])):
                        if "graph" in pg and "nodes" in pg["graph"]:
                            nodes = pg["graph"]["nodes"]
                            for node_idx, node in enumerate(nodes):
                                if node:  # Defensive: nodes array may contain null values
                                    cap_ref = node.get("capabilityRef") or {}
                                    cap_id = cap_ref.get("capabilityId", "")
                                    if cap_id and (cap_id == f"ui:{target_screen_id}" or cap_id == target_screen_id):
                                        matched_node = node
                                        matched_pg_idx = pg_idx
                                        matched_node_idx = node_idx
                                        break
                        if matched_node:
                            break

                # For v1, prefer subStep description (user's prompt) over generationDescription (LLM prompt)
                # Match by stepId between phaseGraphs node and subSteps
                if matched_node and "steps" in ap and ap["steps"]:
                    node_step_id = matched_node.get("stepId")
                    if node_step_id:
                        for step in ap["steps"]:
                            if step and "subSteps" in step and step["subSteps"]:
                                for substep in step["subSteps"]:
                                    if substep and substep.get("stepId") == node_step_id:
                                        user_update_prompt = substep.get("description", "")
                                        break
                                if user_update_prompt:
                                    break
                        if user_update_prompt:
                            # Successfully found user's prompt from subStep
                            pass

                # If not found via stepId matching, fall back to phaseGraphs config
                if not user_update_prompt and matched_node:
                    node_config = matched_node.get("config", {})
                    # Try update_request/_update_request first (user's explicit prompt), then description, then generationDescription (LLM prompt)
                    user_update_prompt = (node_config.get("update_request") or
                                          node_config.get("_update_request") or
                                          node_config.get("description") or
                                          node_config.get("generationDescription"))

                # Fallback: use workflow-level prompt (user's original request) ONLY if still not found
                if not user_update_prompt:
                    user_update_prompt = ap.get("prompt") or ap.get("description") or ""

            # Extract LLM-generated prompt from generationDescription
            llm_generated_prompt = ""
            if "agentic_process" in v and isinstance(v["agentic_process"], dict):
                ap = v["agentic_process"]
                # Try to get generationDescription from the matched node/substep
                if node_index is not None and "phaseGraphs" in ap:
                    if 0 <= phase_graph_idx < len(ap.get("phaseGraphs", [])):
                        pg = ap["phaseGraphs"][phase_graph_idx]
                        if "graph" in pg and "nodes" in pg["graph"]:
                            nodes = pg["graph"]["nodes"]
                            if 0 <= node_index < len(nodes):
                                node = nodes[node_index]
                                if node:
                                    node_config = node.get("config", {})
                                    llm_generated_prompt = node_config.get("generationDescription", "")

            del v["agentic_process"]
            # Use LLM-generated prompt in "prompt" key, fallback to screen_generations prompt
            v["prompt"] = llm_generated_prompt if llm_generated_prompt else prompt
            v["user_update_prompt"] = user_update_prompt
            v["llm_generated_prompt"] = llm_generated_prompt
            
        logger.info(f"[DEBUG] Returning {len(versions)} versions with user_update_prompt")
        return {
            "success": True,
            "workflowId": workflowId,
            "versions": versions
        }
    except Exception as e:
        import traceback
        logger.error(f"[ERROR] get_workflow_versions failed: {e}\n{traceback.format_exc()}")
        raise HTTPException(status_code=500, detail={"error": "Failed to fetch versions.", "reason": str(e)})

@app.post("/aiqod-agent/agent/agentic/gap-tool/generate")
async def agentic_gap_tool_generate(request: GapToolGenerateRequest, http_request: Request) -> Dict[str, Any]:
    """
    Generate a dynamic tool from a natural-language description and io_contract.

    Calls `_generate_gap_tool_and_upsert_capability` to LLM-write the tool, persist it
    under `backend/data/tools/`, register it in the in-process registry, and upsert the capability.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")

    _init_subscriber_billing_if_absent(subscriber_id, org_id=org_id, user_id=user_id)

    # Fetch credential metadata for LLM context (secret values never sent to LLM).
    plan_available_credentials: List[Dict[str, Any]] = []
    _plan_cred_svc = CredentialService.optional()
    if _plan_cred_svc and request.projectId:
        try:
            plan_available_credentials = await _plan_cred_svc.list_credentials(
                request.projectId,
                org_id=org_id,
                subscriber_id=subscriber_id,
            )
            if not plan_available_credentials and (org_id or subscriber_id):
                plan_available_credentials = await _plan_cred_svc.list_credentials(request.projectId)
        except Exception as _cred_err:
            logger.warning(f"[agentic/gap-tool/generate] Failed to list credentials: {_cred_err}")

    node = GraphNode(
        nodeId=(request.nodeId or "gap_tool_node").strip(),
        type="tool",
        name=(request.nodeName or "Generated Tool").strip(),
        stepId=(request.stepId or None),
        capabilityRef=GraphCapabilityRef(capabilityId="GENERATE:GapTool", kind="tool"),
        config=GraphNodeConfig(),
    )
    gen = GenerationSpec(
        kind="tool",
        stepId=(request.stepId or request.nodeId or "").strip(),
        description=(request.description or "").strip(),
        inputs=[],
        outputs=[],
    )
    # If caller provides a toolKey, still enforce subscriber scoping by suffixing `_sb_<short_sub_id>`.
    # This is required so:
    #   - tool names can be reused across subscribers without collision
    #   - runtime `get_available_tools(subscriber_id=...)` can reliably hide other subscribers' tools
    raw_tool_key = (request.toolKey or "").strip()
    if raw_tool_key:
        tool_key = raw_tool_key.replace(" ", "")
        sub_short = _subscriber_short_id(subscriber_id)
        if sub_short and not re.search(rf"_sb_{re.escape(sub_short)}$", tool_key):
            tool_key = f"{tool_key}_sb_{sub_short}"
    else:
        tool_key = _gap_unique_dynamic_tool_key(node, subscriber_id=subscriber_id)

    try:
        upsert_meta = await _generate_gap_tool_and_upsert_capability(
            node=node,
            gen=gen,
            tool_key=tool_key,
            io_contract=request.io_contract or {},
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            project_id=request.projectId,
            max_attempts=max(1, int(request.max_attempts or 5)),
            available_credentials=plan_available_credentials,
        )
        cap_id = upsert_meta["capabilityId"]
    except RuntimeError as exc:
        raise HTTPException(
            status_code=422,
            detail={
                "success": False,
                "error": str(exc),
                "toolKey": tool_key,
            },
        ) from exc

    # Best-effort return of the in-memory tool definition that was registered.
    tool_def = tool_registry.tool_definitions.get(tool_key.replace(" ", ""))
    tool_def_payload: Optional[Dict[str, Any]] = None
    if tool_def:
        tool_def_payload = {
            "name": tool_def.name,
            "description": tool_def.description,
            "parameters": [
                {
                    "name": p.name,
                    "param_type": getattr(p.param_type, "value", str(p.param_type)),
                    "description": p.description,
                    "required": p.required,
                    "default_value": p.default_value,
                }
                for p in (tool_def.parameters or [])
            ],
            "outputParameters": tool_def.output_parameters or [],
            "keywords": tool_def.keywords or [],
            "function_code": tool_def.function_code,
            "imports": tool_def.imports or [],
        }

    tool_path = tool_registry._find_tool_json_path(tool_key.replace(" ", ""))

    return {
        "capabilityId": cap_id,
        "version": upsert_meta.get("version"),
        "class_path": upsert_meta.get("class_path"),
        "toolKey": tool_key,
        "toolPath": tool_path,
        "toolDefinition": tool_def_payload,
    }


@app.post("/aiqod-agent/agent/agentic/gap-tool/save")
async def agentic_gap_tool_save(request: GapToolSaveRequest, http_request: Request) -> Dict[str, Any]:
    """
    Save a user-authored tool (function_code + imports) without calling the LLM.

    Validates, registers the tool in the in-process registry + JSON backing store
    (backend/data/tools/), and upserts a capability document — identical to what
    _generate_gap_tool_and_upsert_capability does after LLM generation.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")

    function_code = (request.function_code or "").strip()
    if not function_code:
        raise HTTPException(status_code=400, detail={"success": False, "error": "function_code is required"})

    # Optional mock/placeholder guard (same rules as LLM-generated tools).
    if request.validateCode:
        rejection = _detect_mock_code(function_code)
        if rejection:
            raise HTTPException(
                status_code=422,
                detail={
                    "success": False,
                    "error": f"function_code appears to contain mock/placeholder code: {rejection}",
                },
            )

    # ── Derive tool key ───────────────────────────────────────────────────────
    raw_tool_key = (request.toolKey or "").strip()
    if raw_tool_key:
        tool_key = raw_tool_key.replace(" ", "")
        sub_short = _subscriber_short_id(subscriber_id)
        if sub_short and not re.search(rf"_sb_{re.escape(sub_short)}$", tool_key):
            tool_key = f"{tool_key}_sb_{sub_short}"
    else:
        node_slug = GraphNode(
            nodeId=(request.nodeId or "custom_tool_node").strip(),
            type="tool",
            name=(request.nodeName or "Custom Tool").strip(),
            stepId=(request.stepId or None),
            capabilityRef=GraphCapabilityRef(capabilityId="GENERATE:GapTool", kind="tool"),
            config=GraphNodeConfig(),
        )
        tool_key = _gap_unique_dynamic_tool_key(node_slug, subscriber_id=subscriber_id)

    # ── Build the parsed dict in the same format register_tool expects ────────
    raw_imports: List[str] = [str(x).strip() for x in (request.imports or []) if str(x).strip()]

    parsed: Dict[str, Any] = {
        "name": tool_key,
        "description": (request.description or "").strip(),
        "function_code": function_code,
        "imports": raw_imports,
        "parameters": request.parameters or [],
        "outputParameters": request.outputParameters or [],
        "keywords": list(request.keywords or []) + ["user_authored", "agentic"],
    }

    # Honour io_contract parameter types when caller didn't supply explicit parameters.
    io_contract = request.io_contract or {}
    if not parsed["parameters"] and io_contract.get("inputParameters"):
        type_map = {
            "text": "string", "string": "string", "number": "float", "integer": "integer",
            "float": "float", "boolean": "boolean", "bool": "boolean",
            "object": "dict", "dict": "dict", "array": "list", "list": "list", "any": "any",
        }
        contract_params = []
        for p in io_contract["inputParameters"]:
            if not isinstance(p, dict) or not p.get("name"):
                continue
            dt = str(p.get("dataType") or "Any").strip().lower()
            contract_params.append({
                "name": str(p["name"]),
                "param_type": type_map.get(dt, "any"),
                "description": str(p.get("description") or ""),
                "required": bool(p.get("required", False)),
                "default_value": None,
            })
        parsed["parameters"] = contract_params

    if not parsed["outputParameters"] and io_contract.get("outputParameters"):
        parsed["outputParameters"] = normalize_output_parameters(io_contract["outputParameters"])

    if not register_tool(parsed, save=True):
        raise HTTPException(
            status_code=500,
            detail={"success": False, "error": f"register_tool failed for user-authored tool '{tool_key}'"},
        )

    # ── Upsert capability document (same tenant logic as _generate_gap_tool_and_upsert_capability) ──
    if subscriber_id and str(subscriber_id).strip():
        tenant_for_tool: Dict[str, Optional[str]] = {
            "orgId": org_id or None,
            "subscriberId": subscriber_id,
            "userId": None,
        }
    else:
        tenant_for_tool = _get_platform_tenant()

    inp_params = normalize_input_parameters(parsed["parameters"])
    out_params = normalize_output_parameters(parsed["outputParameters"])
    now = datetime.utcnow()
    cap_id = f"tool:{tool_key}"
    capability_doc: Dict[str, Any] = {
        "capabilityId": cap_id,
        "kind": "tool",
        "name": tool_key,
        "description": parsed["description"],
        "inputParameters": inp_params,
        "outputParameters": out_params,
        "version": "1",
        "isLatest": True,
        "status": "active",
        "source": {
            "sourceType": "user_authored",
            "sourceRef": {
                "projectId": request.projectId,
                "nodeId": request.nodeId or "",
                "toolKey": tool_key,
                "class_path": dynamic_tool_class_path(tool_key),
            },
            "sourceUpdatedAt": now,
            "syncedAt": now,
        },
        "runtime": {"tool": {"toolName": tool_key}},
        "class_path": dynamic_tool_class_path(tool_key),
        "searchText": " ".join(filter(None, [
            tool_key,
            parsed["description"],
            request.nodeName or "",
            request.nodeId or "",
        ])).strip(),
        "tags": list(parsed["keywords"]),
        "usageCount": 0,
    }

    await capability_repository.upsert_capability(tenant_for_tool, capability_doc)
    await capability_repository.set_is_latest_for_capability(tenant_for_tool, cap_id)

    # ── Build response ────────────────────────────────────────────────────────
    tool_def = tool_registry.tool_definitions.get(tool_key.replace(" ", ""))
    tool_def_payload: Optional[Dict[str, Any]] = None
    if tool_def:
        tool_def_payload = {
            "name": tool_def.name,
            "description": tool_def.description,
            "parameters": [
                {
                    "name": p.name,
                    "param_type": getattr(p.param_type, "value", str(p.param_type)),
                    "description": p.description,
                    "required": p.required,
                    "default_value": p.default_value,
                }
                for p in (tool_def.parameters or [])
            ],
            "outputParameters": tool_def.output_parameters or [],
            "keywords": tool_def.keywords or [],
            "function_code": tool_def.function_code,
            "imports": tool_def.imports or [],
        }

    tool_path = tool_registry._find_tool_json_path(tool_key.replace(" ", ""))

    return {
        "capabilityId": cap_id,
        "toolKey": tool_key,
        "toolPath": tool_path,
        "toolDefinition": tool_def_payload,
    }


# Deprecated: /agentic/plan has been split into /agentic/plan/preview and /agentic/plan/execute.
# The function body is preserved below for reference but the route is no longer registered.
async def agentic_plan(request: AgenticPlanRequest, http_request: Request) -> AgenticPlanResponse:
    """
    Full design-time planning pipeline for agentic workflows.

    Contract (input):
      - Exactly one of `prompt` or `steps` must be provided.
      - `prompt` mode: LLM Requirement Analyzer derives logical steps; all steps
        form a single phase.
      - `steps` mode: each AgenticPhaseStep (with optional subSteps) forms one
        phase; subSteps become the LogicalSteps for that phase.

    Pipeline (executed for every phase):
      2. Requirement analysis  — prompt → LLM | steps → direct flatten
      3. Capability retrieval  — semantic/text/tag search + scoring (no kind filter)
      5. Graph planner LLM     — builds a per-phase GraphDefinition with nodes,
                                  edges, router nodes, inputBindings; marks gaps
                                  as GENERATE:*
      6a. Graph validator      — checks inputBinding keys match capability params;
                                  auto-renames closest match.
      6b. Binding fixer LLM   — validates {{nodeId.param}} references; fixes via LLM.
      7+8. Gap resolution      — for GENERATE:*: ui_screen → generate_angular_app_async;
                                  tool → LLM tool JSON + register_tool + capability upsert.
      9. LangGraph code gen    — emits Python LangGraph code per phase + combined.
    """
    api_key = get_gemini_api_key()

    # Prefer explicit IDs from body; fall back to headers.
    org_id = request.orgId or http_request.headers.get("x-org-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    user_id = request.userId or http_request.headers.get("x-user-id")

    has_prompt = bool(request.prompt and request.prompt.strip())
    has_steps = bool(request.steps)

    if has_prompt == has_steps:
        raise HTTPException(
            status_code=400,
            detail="Exactly one of 'prompt' (non-empty) or 'steps' must be provided.",
        )

    tenant: Dict[str, Optional[str]] = {
        "orgId": org_id,
        "subscriberId": subscriber_id,
        "userId": user_id,
    }
    engine_type = "agentic_graph"
    process_id = request.projectId or f"agentic_{generate_numeric_id()}"
    workflow_name = request.selectedName or "workflow"
    all_warnings: list[str] = []

    # Fetch project credentials once for use as LLM context during gap generation.
    # Only credential metadata (name/type/service) is sent to the LLM — secret values
    # are never included in prompts. Actual values are injected at runtime via request_meta.
    plan_available_credentials: List[Dict[str, Any]] = []
    _plan_cred_svc = CredentialService.optional()
    if _plan_cred_svc and request.projectId:
        try:
            plan_available_credentials = await _plan_cred_svc.list_credentials(
                request.projectId,
                org_id=org_id,
                subscriber_id=subscriber_id,
            )
            # If scoped query returned nothing, fall back to all project credentials
            # (covers the case where credentials were stored without org/subscriber tags).
            if not plan_available_credentials and (org_id or subscriber_id):
                plan_available_credentials = await _plan_cred_svc.list_credentials(request.projectId)
            logger.info(
                f"[agentic/plan] Loaded {len(plan_available_credentials)} credential(s) "
                f"for project='{request.projectId}' org='{org_id}' subscriber='{subscriber_id}'."
            )
        except Exception as _cred_err:
            logger.warning(f"[agentic/plan] Failed to list credentials for gap generation context: {_cred_err}")

    def _tenant_query() -> Dict[str, Any]:
        q: Dict[str, Any] = {}
        for key, raw in (
            ("orgId", org_id),
            ("subscriberId", subscriber_id),
            ("userId", user_id),
        ):
            if raw is None:
                continue
            try:
                q[key] = ObjectId(raw) if isinstance(raw, str) else raw
            except Exception:
                q[key] = raw
        return q

    def _save_process_to_process_configs(
        *,
        phase_results_local: list[PhaseGraphResult],
        persisted_steps_nested: list[Dict[str, Any]],
        warnings_local: list[str],
        combined_file_path_local: Optional[str],
    ) -> None:
        
        import os
        if combined_file_path_local:
            combined_file_path_local = os.path.abspath(combined_file_path_local)
        now = datetime.utcnow()
        coll = db["Process_Configs"]
        query = {
            **_tenant_query(),
            "engineType": engine_type,
            "agentic_process.workflow_id": process_id,
        }
        process_doc = {
            "workflow_id": process_id,
            "workflowName": workflow_name,
            "projectId": request.projectId,
            "mode": mode if "mode" in locals() else None,
            "analysis_source": analysis_source if "analysis_source" in locals() else None,
            "prompt": request.prompt,
            "steps": persisted_steps_nested,
            "phaseGraphs": [p.model_dump(exclude={"langgraph_code"}) for p in phase_results_local],
            "combined_file_path": combined_file_path_local,
            "warnings": warnings_local,
            "status": "draft",
        }
        coll.update_one(
            query,
            {
                "$set": {
                    **_tenant_query(),
                    "engineType": engine_type,
                    "selectedName": request.selectedName,
                    "selectedType": request.selectedType,
                    "selectedCategory": request.selectedCategory,
                    "token": request.token,
                    "updated_at": now,
                    "agentic_process": process_doc,
                },
                "$unset": {
                    "engineVersion": "",
                    "schemaVersion": "",
                },
                "$setOnInsert": {
                    "created_at": now,
                },
            },
            upsert=True,
        )

    async def _upsert_agentic_workflow_capability(
        *,
        workflow_id: str,
        phase_results_local: list[PhaseGraphResult],
    ) -> None:
        # Keep the capability description concise and searchable.
        phase_names = [
            (pr.graph.phaseName or pr.graph.phaseId or "").strip()
            for pr in phase_results_local
            if getattr(pr, "graph", None) is not None
        ]
        phase_names = [p for p in phase_names if p]
        if request.prompt and request.prompt.strip():
            desc_core = request.prompt.strip()
        elif phase_names:
            desc_core = f"Agentic workflow with phases: {', '.join(phase_names)}"
        else:
            desc_core = f"Agentic workflow {workflow_name}"

        capability_id = f"agent:workflow:{workflow_id}"
        capability_doc: Dict[str, Any] = {
            "capabilityId": capability_id,
            "kind": "agent",
            "name": workflow_name,
            "description": desc_core,
            "inputParameters": [],
            "outputParameters": [],
            "version": "1",
            "isLatest": True,
            "status": "active",
            "source": {
                "sourceType": "workflow_details",
                "sourceRef": {"workflowId": workflow_id},
                "sourceUpdatedAt": datetime.utcnow(),
                "syncedAt": datetime.utcnow(),
            },
            "runtime": {
                "agent": {
                    "workflowId": workflow_id,
                    "workflowName": workflow_name,
                    "agentState": "stable",
                }
            },
            "searchText": f"{workflow_name} {desc_core}".strip(),
            "tags": ["agentic", "graph", "workflow"],
        }
        await capability_repository.upsert_capability(tenant, capability_doc)
        await capability_repository.set_is_latest_for_capability(tenant, capability_id)

    # ── Step 2: Resolve logical steps + define phases ─────────────────────────

    # phases_info = list of (phase_id, phase_name, phase_description, [LogicalStep], phaseType)
    phases_info: list[tuple[str, str, str, list[LogicalStep], str]] = []

    if has_prompt:
        logger.info(f"Analyzing requirements with prompt: {request.prompt.strip()}")
        analysis = await analyze_requirements_with_llm(
            prompt=request.prompt.strip(),
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )
        all_warnings.extend(analysis.warnings or [])
        # Single phase containing all steps — prompt mode is always FREEZE.
        phases_info.append((
            "phase_1",
            workflow_name,
            request.prompt.strip(),
            analysis.steps,
            "FREEZE",
        ))
        mode: Literal["prompt", "steps"] = "prompt"
        analysis_source: Optional[Literal["llm", "fallback"]] = analysis.source
        all_steps_flat = analysis.steps

    else:
        logger.info(f"Analyzing requirements with steps: {request.steps}")
        mode = "steps"
        analysis_source = None
        all_steps_flat: list[LogicalStep] = []
        idx = 1

        for phase in (request.steps or []):
            logger.info(f"Analyzing phase: {phase}")
            phase_steps: list[LogicalStep] = []
            phase_desc = phase.description or phase.name

            if phase.subSteps:
                for sub in phase.subSteps:
                    ls = LogicalStep(
                        stepId=sub.stepId or f"L{idx}",
                        name=sub.name,
                        description=sub.description,
                        inputs=[],
                        outputs=[],
                        preferredKind=None,
                    )
                    phase_steps.append(ls)
                    idx += 1
            else:
                phase_steps.append(LogicalStep(
                    stepId=phase.stepId or f"L{idx}",
                    name=phase.name,
                    description=phase_desc,
                    inputs=[],
                    outputs=[],
                    preferredKind=None,
                ))
                idx += 1

            logger.info(f"Normalizing logical steps: {phase_steps}")
            # For phase-based flows, preserve the original stepIds (e.g. phase_1_step_1)
            # so they remain unique and traceable across phases.
            norm_steps, phase_warns = _normalize_logical_steps(phase_steps, preserve_ids=True)
            logger.info(f"Normalized logical steps: {norm_steps}")
            all_warnings.extend(phase_warns)
            all_steps_flat.extend(norm_steps)
            phases_info.append((phase.stepId, phase.name, phase_desc, norm_steps, phase.phaseType))
            logger.info(f"Phase info: {phases_info}")

    # ── Step 3: Capability retrieval (all steps at once for efficiency) ───────
    all_step_caps = await _match_capabilities_for_steps(all_steps_flat, tenant=tenant)
    # Global pool of tools/screens/agents, deduped and filtered by min score.
    # Reduce planner context: only top 5 candidates per logical step are eligible
    # to enter the global pool that is shown to the LLM.
    global_caps = _collect_global_capability_candidates(
        all_step_caps,
        min_score=2.0,
        top_n_per_step=5,
    )
    _log_capability_audit(
        global_caps,
        all_step_caps=all_step_caps,
        log_prefix="[agentic/plan] capabilities",
    )
    # ── Steps 5-9: Per-phase graph pipeline ───────────────────────────────────
    project_id_for_gen = request.projectId or generate_screen_id("project")
    phase_results: list[PhaseGraphResult] = []
    logger.info(f"Phase results: {phase_results}")
    # Running registry of {nodeId: [output_keys]} from all completed phases.
    # Passed to the planner and repair LLM for each subsequent phase so they
    # can produce correct {{nodeId.outputParam}} cross-phase bindings instead of
    # inventing fake namespaces like {{__graph__.param}}.
    prior_phase_outputs: dict = {}

    for phase_id, phase_name, phase_desc, phase_steps, phase_type in phases_info:
        phase_warnings: list[str] = []
        logger.info(f"Phase steps for {phase_id}: {phase_steps} (phaseType={phase_type})")
        # Step 5 — Graph Planner LLM
        try:
            graph = await _plan_phase_graph_with_llm(
                phase_id=phase_id,
                phase_name=phase_name,
                phase_description=phase_desc,
                steps=phase_steps,
                global_caps=global_caps,
                prior_phase_outputs=prior_phase_outputs or None,
                project_id=project_id_for_gen,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                api_key=api_key,
            )
            # logger.info(f"Graph for phase {phase_id}: {graph}")
        except Exception as e:
            logger.warning(f"[agentic/plan/execute] Graph planner failed for phase '{phase_id}': {e}")
            raise HTTPException(
                status_code=503,
                detail={
                    "success": False,
                    "error": "graph_planner_unavailable",
                    "message": "Graph planner LLM was unavailable; execution cannot proceed safely.",
                    "phaseId": phase_id,
                    "phaseName": phase_name,
                    "retryable": True,
                    "provider_error": str(e),
                },
            )

        user_context = phase_desc or phase_name

        # ── Step 6s: Structural validation + targeted repair ─────────────────
        graph, struct_errors = _validate_graph_structure(graph)
        auto_struct = [e for e in struct_errors if e.autoFixed]
        need_repair = [e for e in struct_errors if not e.autoFixed]
        if auto_struct:
            logger.info(f"[6s] {len(auto_struct)} structural issue(s) auto-fixed.")
        if need_repair:
            phase_warnings.extend(e.message for e in need_repair)
            logger.warning(f"[6s] {len(need_repair)} structural issue(s) need LLM repair.")
            graph = await _repair_graph_structure_with_llm(
                graph, need_repair, global_caps, phase_steps,
                project_id=project_id_for_gen, org_id=org_id,
                subscriber_id=subscriber_id, user_id=user_id, api_key=api_key,
            )
            # One final structural check — if still broken, fail fast.
            _, remaining_struct = _validate_graph_structure(graph)
            still_broken = [e for e in remaining_struct if not e.autoFixed]
            if still_broken:
                remaining_messages = [e.message for e in still_broken]
                logger.error(
                    f"[6s] Structural repair failed for phase '{phase_id}': "
                    f"{len(still_broken)} issue(s) remain."
                )
                # Stop the pipeline here: structural issues mean the graph is not safe
                # to proceed into binding validation/codegen.
                raise HTTPException(
                    status_code=422,
                    detail={
                        "error": "structural_validation_failed",
                        "phaseId": phase_id,
                        "graphId": graph.graphId,
                        "message": "Graph still has structural errors after repair.",
                        "errors": remaining_messages[:50],
                    },
                )
        logger.info(f"Graph after structural validation: {graph}")

        # ── Steps 6a+6b: Programmatic fix → LLM repair loop (max 3 rounds) ──
        graph, total_fixes, remaining_issues = await _validate_and_fix_loop(
            graph,
            user_context=user_context,
            global_caps=global_caps,
            prior_phase_outputs=prior_phase_outputs or None,
            max_rounds=3,
            project_id=project_id_for_gen,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
            api_key=api_key,
        )
        phase_warnings.extend(e.message for e in remaining_issues)
        logger.info(
            f"Graph after validation loop: {total_fixes} total issue(s) processed, "
            f"{len(remaining_issues)} unresolved."
        )
        _log_capability_audit(
            global_caps,
            graph=graph,
            log_prefix=f"[agentic/plan] capabilities phase={phase_id}",
            log_pool=False,
        )

        # ── Steps 7+8: Gap resolution (GENERATE:* → ui via Angular, or tool via LLM+registry)
        try:
            graph, gen_ids = await _resolve_gap_generations(
                graph,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                project_id=project_id_for_gen,
                available_credentials=plan_available_credentials,
            )
        except UnresolvedGapGenerationError as gap_err:
            raise HTTPException(
                status_code=422,
                detail={
                    "error": "unresolved_gap_generation",
                    "phaseId": gap_err.phase_id or phase_id,
                    "message": str(gap_err),
                    "unresolvedNodes": gap_err.unresolved,
                    "failures": gap_err.failures,
                },
            ) from gap_err

        # ── Step 6p: Post-gap re-validation ──────────────────────────────────
        if gen_ids:
            graph = await _revalidate_after_gap_gen(
                graph, gen_ids,
                user_context=user_context,
                global_caps=global_caps,
                max_rounds=2,
                project_id=project_id_for_gen,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                api_key=api_key,
                available_credentials=plan_available_credentials,
            )
            logger.info(f"Graph after post-gap re-validation: {graph}")

        # ── Enrich tool nodes with execution metadata (source/class_path) ────
        graph = await _enrich_tool_nodes_with_source_and_class_path(
            graph,
            tenant=tenant,
        )
        logger.info(f"Graph after gap resolution and enrichment: {graph}")

        # ── Update prior_phase_outputs for subsequent phases ──────────────────
        # Collect every non-router/non-end node's declared output keys so the
        # next phase's planner and repair LLM can produce correct cross-phase
        # bindings like {{validate_form_data.ekyc_record_id}}.
        for node in graph.nodes:
            if node.type in ("router", "fallback_router", "end") or not node.nodeId:
                continue
            safe_nid = re.sub(r"[^a-zA-Z0-9_]", "_", node.nodeId)
            prior_phase_outputs[safe_nid] = _declared_outputs_as_prior_phase_entries(node)

        phase_results.append(PhaseGraphResult(
            # Defensive copy: some planner/validators may reuse the same model
            # instance across iterations; ensure one immutable snapshot per phase.
            graph=copy.deepcopy(graph),
            validation_warnings=phase_warnings,
            binding_fixes_applied=total_fixes,
            gap_generations=gen_ids,
            phaseType=phase_type,
        ))
    # logger.info(f"Phase results: {phase_results}")
    ########################################################################
    # Step 9 — LangGraph code generation (manual vs LLM compare)
    # from llm_freeze_codegen import generate_langgraph_code_for_phases_via_llm
    # import os
    # import re
    # import difflib

    # ── Manual (original) generator ──────────────────────────────────────
    try:
        combined_code = _generate_langgraph_code_for_phases(
            phase_results, workflow_name, global_caps=global_caps
        )
    except Exception as e:
        all_warnings.append(f"LangGraph code generation (manual) failed: {e}")
        combined_code = ""

    for pr in phase_results:
        try:
            pr.langgraph_code = _generate_langgraph_code_for_phases(
                [pr], workflow_name, global_caps=global_caps
            )
        except Exception:
            pr.langgraph_code = ""

    # # ── LLM generator ────────────────────────────────────────────────────
    # try:
    #     combined_code_llm = generate_langgraph_code_for_phases_via_llm(
    #         phase_results, workflow_name, global_caps=global_caps
