    #             [pr], workflow_name, global_caps=global_caps
    #         )
    #     except Exception:
    #         pr.langgraph_code_llm = ""

    # # ── Save both to files for comparison ────────────────────────────────
    # try:
    #     _debug_dir = os.path.join(os.getcwd(), "codegen_debug")
    #     os.makedirs(_debug_dir, exist_ok=True)

    #     _manual_path = os.path.join(_debug_dir, f"{workflow_name}_combined_MANUAL.py")
    #     _llm_path = os.path.join(_debug_dir, f"{workflow_name}_combined_LLM.py")

    #     with open(_manual_path, "w", encoding="utf-8") as f:
    #         f.write(combined_code_manual or "")

    #     with open(_llm_path, "w", encoding="utf-8") as f:
    #         f.write(combined_code_llm or "")

    #     logger.info(f"[COMPARE] Manual combined code saved → {_manual_path}")
    #     logger.info(f"[COMPARE] LLM combined code saved   → {_llm_path}")

    #     # Per-phase files
    #     for pr in phase_results:
    #         raw_phase_id = getattr(pr.graph, "phaseId", None) or "phase"
    #         safe_pid = re.sub(r"\W", "_", str(raw_phase_id))

    #         _phase_manual_path = os.path.join(_debug_dir, f"{workflow_name}_{safe_pid}_MANUAL.py")
    #         _phase_llm_path = os.path.join(_debug_dir, f"{workflow_name}_{safe_pid}_LLM.py")

    #         with open(_phase_manual_path, "w", encoding="utf-8") as f:
