    #         if len(_diff) > 80:
    #             logger.info("[COMPARE] ... diff truncated, full output in saved files.")
    #     else:
    #         logger.info("[COMPARE] Manual and LLM combined outputs are IDENTICAL.")
    # except Exception as e:
    #     all_warnings.append(f"Failed to compute/log manual vs LLM diff: {e}")

    # # ── Use LLM output as canonical going forward ───────────────────────
    # combined_code = combined_code_llm
    # for pr in phase_results:
