@app.post("/aiqod-agent/agent/generate-screen")
async def generate_screen(request: Request):
    """Generate screen from prompt"""
    try:
        # Get request data
        data = await request.json()
        
        # Run async logic directly
        result = await generate_screen_async(data)
        
        return result
    except Exception as e:
        print(f"Error: {str(e)}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={"success": False, "error": str(e)})

async def generate_screen_async(data):
    """
    Main endpoint: Convert natural language prompt to UI components
    """
    try:
        # data parameter is already passed from the calling function

        if not data or 'prompt' not in data:
            raise HTTPException(
                status_code=400,
                detail="Missing 'prompt' in request body"
            )

        prompt = data.get('prompt')
        screen_id = data.get('screen_id')
        project_id = data.get('project_id')
        theme_preferences = data.get('theme_preferences')
        # Optional workflow context passed from orchestrator
        workflow_context = data.get('workflow_context')
        
        # Generate version timestamp for tracking
        version = datetime.utcnow().strftime("%Y%m%d%H%M%S")

        # Generate unique IDs if not provided
        if screen_id and project_id:
            screen_id = screen_id
            project_id = project_id
        else:
            screen_id = generate_screen_id("screen")
            project_id = generate_screen_id("project")

        # Step 1: Process natural language prompt
        print("\n--------------------------------")
        print("request = ", data)

        raw_ir_schema = await ai_processor.process_prompt(
            prompt=prompt,
            screen_type=None,
            theme_preferences=theme_preferences,
            workflow_context=workflow_context,
        )

        if not isinstance(raw_ir_schema, dict):
            raise ValueError("AI processor returned an invalid IR schema payload")
        components = raw_ir_schema.get("components", [])

        backend_result = {"base_path": None, "functions": [], "models_source": None}
        try:
            backend_result = await backend_generator.generate_backend(
                project_id,
                raw_ir_schema.get("dataModels", {}) if isinstance(raw_ir_schema, dict) else {},
                raw_ir_schema.get("dataSources", []) if isinstance(raw_ir_schema, dict) else [],
                screen_id=screen_id,
                version=version
            )
        except Exception as backend_error:
            print(f"[BackendGenerator] Failed: {backend_error}")

        return {
            "success": True,
            "screen_id": screen_id,
            "project_id": project_id,
            "components": components,
            "ir_schema": raw_ir_schema,
            "backend": backend_result,
            "api_base_path": backend_result.get("base_path"),
            "error": None
        }

    except Exception as e:
        print(f"Error in generate_screen: {str(e)}")
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail={
                "success": False,
                "screen_id": None,
                "project_id": None,
                "components": None,
                "ir_schema": None,
                "error": str(e)
            }
        )


@app.post("/aiqod-agent/agent/dynamic/execute/{project_id}")
async def execute_dynamic_function(project_id: str, request: Request):
    """Execute dynamic backend function"""
    try:
        # Get request data
        payload = await request.json() or {}
        header_subscriber_id = request.headers.get("x-subscriber-id")
        header_user_id = request.headers.get("x-user-id")
        header_org_id = request.headers.get("x-org-id")
        referer = request.headers.get("referer") or request.headers.get("Referer")

        # Run async logic directly
        result = await execute_dynamic_function_async(
            project_id,
            payload,
            header_subscriber_id=header_subscriber_id,
            header_user_id=header_user_id,
            header_org_id=header_org_id,
            referer=referer,
        )

        return result  # Already a proper response
    except HTTPException:
        # Re-raise HTTPException as-is so the original status code and detail are preserved
        raise
    except Exception as e:
        print(f"Error: {str(e)}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={"success": False, "error": str(e)})


def truncate_large_base64_strings(obj: Any, max_string_length: int = 500) -> Any:
    """
    Recursively truncate large base64 strings in nested dictionaries/lists to prevent token limit issues.
    
    Args:
        obj: The object to process (dict, list, or any other type)
        max_string_length: Maximum length for strings before truncation
    
    Returns:
        A copy of the object with large strings truncated
    """
    if isinstance(obj, dict):
        result = {}
        for key, value in obj.items():
            if isinstance(value, str):
                # Check if it looks like base64 (long string, alphanumeric with +/=)
                if len(value) > max_string_length and all(c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=' for c in value[:100]):
                    # Truncate base64 string
                    truncated = value[:max_string_length]
                    original_size = len(value)
                    result[key] = f"{truncated}... [TRUNCATED: original size {original_size} characters, appears to be base64-encoded data]"
                    logger.debug(f"Truncated base64 string in key '{key}': {original_size} -> {max_string_length} characters")
                else:
                    # Regular string - truncate if too long
                    if len(value) > max_string_length:
                        result[key] = f"{value[:max_string_length]}... [TRUNCATED: original size {len(value)} characters]"
                        logger.debug(f"Truncated string in key '{key}': {len(value)} -> {max_string_length} characters")
                    else:
                        result[key] = value
            else:
                # Recursively process nested structures
                result[key] = truncate_large_base64_strings(value, max_string_length)
        return result
    elif isinstance(obj, list):
        return [truncate_large_base64_strings(item, max_string_length) for item in obj]
    else:
        # For other types (int, float, bool, None, etc.), return as-is
        return obj


def _stderr_indicates_runtime_error(stderr_output: Optional[str]) -> bool:
    """
    Return True if stderr contains indicators of a runtime error (exception, traceback, etc.).
    Used when sandbox reports success=True but the function logged an error to stderr
    (e.g. caught exception, or error in a library that only logs to stderr).
    """
    if not stderr_output or not stderr_output.strip():
        return False
    s = stderr_output.strip().lower()
    return (
        "traceback" in s
        or "error:" in s
        or "error parsing" in s
        or "exception" in s
        or "jsondecodeerror" in s
        or "valueerror" in s
        or "typeerror" in s
        or "keyerror" in s
        or "attributeerror" in s
        or "runtimeerror" in s
        or (" line " in s and "error" in s)
    )


def _is_mongo_cursor_await_error(error_text: Optional[str]) -> bool:
    """Detect sandbox Motor-vs-PyMongo cursor misuse from error/stderr text."""
    if not error_text:
        return False
    s = error_text.lower()
    return (
        ("coroutine" in s and "to_list" in s)
        or ("asynccursor" in s and "await" in s)
        or ("asynccommandcursor" in s and "await" in s)
        or ("asynccollection.aggregate" in s and "never awaited" in s)
    )


def _apply_mongo_cursor_await_fix(source_code: str) -> Optional[str]:
    """Deterministically rewrite bad aggregate/find await patterns. Returns new code or None."""
    if not source_code:
        return None
    try:
        fixed = BackendGenerator._fix_mongo_async_cursor_patterns(source_code)
    except Exception as exc:
        logger.warning("Mongo cursor await deterministic fix failed: %s", exc)
        return None
    if not fixed or fixed == source_code:
        return None
    if "from services.database import Database" not in fixed and "Database.cursor_to_list" in fixed:
        fixed = BackendGenerator._fix_runtime_contract_deterministic(
            fixed, requires_schema_probe=True
        )
    return fixed if fixed != source_code else None


async def _save_function_error_log(
    project_id: str,
    function_id: str,
    *,
    error_message: str,
    error_type: str,
    retry_attempts: int = 1,
    params: Any = None,
    traceback: Optional[str] = None,
    stderr_output: Optional[str] = None,
    execution_time_ms: Optional[float] = None,
    validation_errors: Optional[Any] = None,
    response_received: Optional[Any] = None,
    llm_fix_attempted: bool = False,
    llm_fix_successful: Optional[bool] = None,
    llm_fix_applied: bool = False,
) -> None:
    """Persist a backend function error to MongoDB (kept even if later auto-fixed)."""
    try:
        error_logs: Dict[str, Any] = {
            "error_message": error_message,
            "error_type": error_type,
            "traceback": traceback,
            "stderr_output": stderr_output,
            "execution_time_ms": execution_time_ms,
            "retry_attempts": retry_attempts,
            "llm_fix_attempted": llm_fix_attempted,
            "llm_fix_successful": llm_fix_successful,
            "llm_fix_applied": llm_fix_applied,
            "timestamp": datetime.utcnow(),
            "params": truncate_large_base64_strings(copy.deepcopy(params), max_string_length=500)
            if params is not None
            else None,
        }
        if validation_errors is not None:
            error_logs["validation_errors"] = truncate_large_base64_strings(
                copy.deepcopy(validation_errors), max_string_length=500
            )
        if response_received is not None:
            error_logs["response_received"] = truncate_large_base64_strings(
                copy.deepcopy(response_received), max_string_length=500
            )
        await backend_generator.function_repository.save_error_logs(
            project_id, function_id, error_logs
        )
    except Exception as log_error:
        logger.error(f"Failed to save error logs: {log_error}")


async def _mark_function_error_llm_outcome(
    project_id: str,
    function_id: str,
    *,
    attempted: bool,
    successful: bool,
) -> None:
    try:
        await backend_generator.function_repository.mark_last_error_llm_outcome(
            project_id,
            function_id,
            attempted=attempted,
            successful=successful,
        )
    except Exception as log_error:
        logger.error(f"Failed to update LLM fix outcome on error log: {log_error}")


def strip_markdown_code_fences(code: str) -> str:
    """
    Strip markdown code fences (```python, ```, etc.) from code string.
    
    Args:
        code: Code string that may contain markdown code fences
    
    Returns:
        Code string with markdown fences removed
    """
    if not code:
        return code
    
    code = code.strip()
    
    # Remove markdown code fences if present
    # Handle cases like: ```python\ncode\n``` or ```\ncode\n```
    if code.startswith("```"):
        # Find the first newline after the opening fence
        first_newline = code.find("\n")
        if first_newline != -1:
            # Remove opening fence (```python or ```)
            code = code[first_newline + 1:]
        else:
            # No newline, just remove the opening ```
            code = code[3:]
    
    # Remove closing fence if present
    if code.endswith("```"):
        code = code[:-3]
    
    return code.strip()


def remove_model_class_references(code: str, input_model_name: str, response_model_name: str) -> str:
    """
    Remove references to model classes that are not available in function execution context.
    
    Model classes like FileInput, FileContent, etc. are not available at runtime.
    Functions receive params as a plain dict, not as model instances.
    
    Args:
        code: Source code that may contain model class references
        input_model_name: Name of the input model (to detect references)
        response_model_name: Name of the response model (to detect references)
    
    Returns:
        Code with model class references removed/replaced
    """
    if not code:
        return code
    
    lines = code.split('\n')
    fixed_lines = []
    
    # Common model class name patterns to detect
    model_patterns = [
        r'\bFileInput\b',
        r'\bFileContent\b',
        r'\bFileUpload\b',
        r'\bUploadFile\b',
        r'\bFileData\b',
        r'\bFileModel\b',
    ]
    
    # Add input_model_name if provided
    if input_model_name:
        model_patterns.append(r'\b' + re.escape(input_model_name) + r'\b')
    
    # Add response_model_name if provided
    if response_model_name:
        model_patterns.append(r'\b' + re.escape(response_model_name) + r'\b')
    
    for line in lines:
        original_line = line
        # Check if line contains model class instantiation or isinstance checks
        # Pattern: ModelName(...) or isinstance(..., ModelName)
        for pattern in model_patterns:
            if re.search(pattern, line):
                # Check for common patterns that need fixing
                # Pattern 1: Model instantiation: ModelName(**params) or ModelName(params)
                if re.search(rf'{pattern}\s*\(', line):
                    # This is likely a model instantiation - comment it out or remove
                    # For now, we'll try to replace with dict access
                    logger.warning(f"Detected model class instantiation in line: {line.strip()}")
                    # Skip this line or replace with appropriate dict access
                    # Since we can't always infer the correct replacement, we'll skip it
                    line = f"# REMOVED: {line.strip()}  # Model classes not available - use params dict directly"
                
                # Pattern 2: isinstance checks: isinstance(params, ModelName)
                elif re.search(rf'isinstance\s*\([^,]+,\s*{pattern}', line):
                    logger.warning(f"Detected isinstance check with model class in line: {line.strip()}")
                    # Replace isinstance checks with dict checks
                    line = re.sub(
                        rf'isinstance\s*\(([^,]+),\s*{pattern}\s*\)',
                        r'isinstance(\1, dict)',
                        line
                    )
                
                # Pattern 3: Type hints or annotations: param: ModelName
                elif re.search(rf':\s*{pattern}\b', line):
                    logger.warning(f"Detected model class type hint in line: {line.strip()}")
                    # Replace with dict type hint
                    line = re.sub(
                        rf':\s*{pattern}\b',
                        ': dict',
                        line
                    )
        
        fixed_lines.append(line)
    
    fixed_code = '\n'.join(fixed_lines)
    
    # If we made changes, log them
    if fixed_code != code:
        logger.info("Removed model class references from generated code")
    
    return fixed_code


def convert_attribute_access_to_dict_access(code: str) -> str:
    """
    Convert attribute access patterns (params.attribute) to dict access (params.get("attribute")).
    
    Functions receive params as a dict, not a model instance, so attribute access will fail.
    
    Args:
        code: Source code that may contain attribute access patterns
    
    Returns:
        Code with attribute access converted to dict access
    """
    if not code:
        return code
    
    lines = code.split('\n')
    fixed_lines = []
    
    for line in lines:
        original_line = line
        
        # Pattern: params.attribute or params.nested.attribute
        # Convert to: params.get("attribute") or params.get("nested", {}).get("attribute")
        # But skip if it's already params.get( or params[
        if re.search(r'\bparams\s*\.', line) and not re.search(r'\bparams\s*\.\s*(get|\[)', line):
            # Find all params.xxx patterns (attribute access, not method calls or indexing)
            def replace_attr_access(match):
                full_match = match.group(0)
                # Extract the attribute chain (e.g., "file.content" from "params.file.content")
                attr_chain = full_match.replace('params.', '')
                attrs = attr_chain.split('.')
                
                if len(attrs) == 1:
                    # Simple: params.file -> params.get("file")
                    return f'params.get("{attrs[0]}")'
                else:
                    # Nested: params.file.content -> params.get("file", {}).get("content")
                    result = 'params'
                    for i, attr in enumerate(attrs[:-1]):
                        result = f'{result}.get("{attr}", {{}})'
                    result = f'{result}.get("{attrs[-1]}")'
                    return result
            
            # Replace params.xxx patterns (attribute access)
            # Match params. followed by identifier(s) separated by dots
            # Exclude if followed by ( or [ (method calls or indexing)
            # Also exclude if the line already contains params.get( or params[
            line = re.sub(
                r'\bparams\s*\.\s*([a-zA-Z_][a-zA-Z0-9_]*(?:\.[a-zA-Z_][a-zA-Z0-9_]*)*)(?![\[\(])',
                replace_attr_access,
                line
            )
        
        fixed_lines.append(line)
    
    fixed_code = '\n'.join(fixed_lines)
    
    # If we made changes, log them
    if fixed_code != code:
        logger.info("Converted attribute access to dict access in generated code")
    
    return fixed_code


def validate_code_compilation(source_code: str, function_id: str) -> tuple[bool, Optional[str]]:
    """
    Validate that source code can be compiled without syntax errors.
    This is a basic check - it doesn't validate imports or runtime errors.
    
    Args:
        source_code: Python source code to validate
        function_id: Function identifier for error messages
    
    Returns:
        Tuple of (is_valid, error_message)
        - is_valid: True if code compiles, False otherwise
        - error_message: Error message if compilation failed, None if successful
    """
    if not source_code or not source_code.strip():
        return False, "Source code is empty"
    
    try:
        # Try to compile the code
        compile(source_code, f"<function_{function_id}>", "exec")
        return True, None
    except SyntaxError as e:
        error_msg = f"Syntax error in {function_id}: {e.msg} at line {e.lineno}"
        if e.text:
            error_msg += f"\n  {e.text.strip()}"
        return False, error_msg
    except Exception as e:
        return False, f"Compilation error in {function_id}: {str(e)}"


# Runtime LLM rewrite on /dynamic/execute (sandbox / stderr / response.error).
# Off by default — false positives can rewrite working functions. Set True to re-enable.
# Input ValidationError fixing via fix_source_code_with_llm is unaffected.
ENABLE_EXECUTION_ERROR_LLM_FIX = False


async def fix_execution_error_with_llm(
    params: Dict[str, Any],
    execution_error: str,
    error_type: str,
    source_code: str,
    models_source: str,
    input_model_name: str,
    response_model_name: str,
    function_id: str,
    data_source: Optional[Dict[str, Any]] = None,
    response_received: Optional[Any] = None,
    request_payload: Optional[Dict[str, Any]] = None,
    stderr_output: Optional[str] = None,
    project_id: Optional[str] = None,
) -> Optional[Dict[str, str]]:
    """
    Use LLM to fix function execution errors by fixing specific logical issues.
    
    Args:
        params: Validated input parameters that were used in the failed execution
        execution_error: Error message from execution failure
        error_type: Type of error (e.g., "NameError", "TypeError", "ValueError")
        source_code: Current function source code
        models_source: Current Pydantic models source
        input_model_name: Name of the input model class
        response_model_name: Name of the response model class
        function_id: Function identifier for context
        data_source: Data source configuration from IR schema (describes what function should do)
        response_received: Any partial response received before error (if any)
        request_payload: Original request payload from frontend
        stderr_output: Full stderr output from sandbox execution (contains tracebacks and error logs)
    
    Returns:
        Dict with 'source_code' and 'models_source' keys, or None if fixing failed
    """
    if not ENABLE_EXECUTION_ERROR_LLM_FIX:
        logger.info(
            "Execution-error LLM fix skipped (ENABLE_EXECUTION_ERROR_LLM_FIX=False)",
            extra={"function_id": function_id, "error_type": error_type},
        )
        return None

    started_at = datetime.utcnow()
    try:
        # Prepare data source info with function purpose
        data_source_info = ""
        if data_source:
            description = data_source.get("description", "N/A")
            database_logic = data_source.get("databaseLogic", "")
            operation = data_source.get("operation", {})
            config = data_source.get("config", {})
            
            data_source_info = f"""
            DATA SOURCE CONFIGURATION (What this function is meant to do):
            - Description: {description}
            - Database Logic: {database_logic}
            - Operation: {json.dumps(operation, indent=2) if operation else "N/A"}
            - Config: {json.dumps(config, indent=2) if config else "N/A"}
            - Full Data Source: {json.dumps(data_source, indent=2)}
            """
        
        # Prepare available credential info (so LLM can fix wrong names/usage)
        credential_info = ""
        if project_id:
            cred_svc = CredentialService.optional()
            if cred_svc:
                try:
                    cred_list = await cred_svc.list_credentials(project_id)
                    if cred_list:
                        credential_info = f"""
            AVAILABLE PROJECT CREDENTIALS (from credentials collection):
            {json.dumps(cred_list, indent=2)}

            CREDENTIAL USAGE RULES:
            - Read secrets ONLY from request_meta["credentials"] using the exact 'name' from the list above.
            - If a required credential is missing at runtime (None or empty), return a clear error like:
              {{"success": False, "message": "Missing credential 'smtp_credentials'. Configure it in project credentials.", "error": "Missing credential 'smtp_credentials'"}}
            - For email/SMTP functions: prefer a credential whose service or type is 'Email' or 'SMTP', and use it as described in the EMAIL/SMTP credentials rule below.
                        """
                except Exception as e:
                    logger.warning("Failed to list credentials for execution-error fix: %s", e)
        
        # Prepare response info
        response_info = ""
        if response_received is not None:
            # Truncate large base64 strings in response as well
            truncated_response = truncate_large_base64_strings(copy.deepcopy(response_received), max_string_length=500)
            response_info = f"""
            PARTIAL RESPONSE RECEIVED (before error):
            {json.dumps(truncated_response, indent=2, default=str)}
            """
        
        # Prepare request payload info
        # Truncate large base64 strings to prevent token limit issues
        request_info = ""
        if request_payload:
            # Create a truncated copy of the payload to avoid token limit issues with large base64 strings
            truncated_payload = truncate_large_base64_strings(copy.deepcopy(request_payload), max_string_length=500)
            request_info = f"""
            ORIGINAL REQUEST PAYLOAD FROM FRONTEND:
            {json.dumps(truncated_payload, indent=2, default=str)}
            """
        
        # Prepare stderr output info (contains full traceback)
        stderr_info = ""
        if stderr_output:
            stderr_info = f"""
            FULL STDERR OUTPUT (contains complete traceback and error details):
            ```
            {stderr_output}
            ```
            """
        
        prompt = f"""You are a Python debugging expert. A backend function failed during execution due to a LOGICAL ERROR. Your task is to fix ONLY the specific logical issue, NOT rewrite the entire function.

            Function ID: {function_id}
            Input Model Name: {input_model_name}
            Response Model Name: {response_model_name}
            Error Type: {error_type}
            
            {request_info}
            
            VALIDATED INPUT PARAMETERS (used in execution):
            {json.dumps(truncate_large_base64_strings(copy.deepcopy(params), max_string_length=500), indent=2, default=str)}
            
            ⚠️ CRITICAL - PARAMS IS A DICT, NOT A MODEL INSTANCE:
            - Functions receive `params` as a plain Python dict, NOT as a Pydantic model instance
            - Models are ONLY used for validation before/after execution, NOT during execution
            - Model classes (like FileContent, FileInput, etc.) are NOT available in the execution context
            - The sandbox execution environment does NOT have access to model class definitions
            - ❌ WRONG: params.file.content or params.file or file_obj = params.file
            - ❌ WRONG: if isinstance(params, FileInput): ...
            - ✅ CORRECT: params.get("file", {{}}).get("content") or params["file"]["content"]
            - ✅ CORRECT: file_obj = params.get("file", {{}})
            - ✅ CORRECT: content = file_obj.get("content") if isinstance(file_obj, dict) else None
            - Always use dict access methods: params.get("key"), params["key"], or params.get("key", {{}}).get("nested_key")
            - NEVER use attribute access like params.attribute or params.nested.attribute
            
            ⚠️ CRITICAL - USE FLAT SCHEMAS:
            - DO NOT create nested Pydantic model classes (e.g., FileContent, FileInput, FileData)
            - For nested structures, use Dict[str, Any] in the model definition
            - Example:
              ❌ WRONG:
                class FileContent(BaseModel):
                    content: str
                class UploadPdfRequest(BaseModel):
                    file: FileContent  # Nested model - DON'T DO THIS
            
              ✅ CORRECT:
                class UploadPdfRequest(BaseModel):
                    file: Dict[str, Any]  # Flat schema using Dict
            
            ⚠️ CRITICAL - EMPTY PARAMS DETECTION:
            - If "VALIDATED INPUT PARAMETERS" shows {{}} or is empty, but "ORIGINAL REQUEST PAYLOAD" has data in params:
              * This means the Pydantic model ({input_model_name}) is REJECTING or DROPPING all fields during validation
              * The model is likely empty (just "pass") or missing required fields
              * YOU MUST UPDATE THE MODEL to accept the fields from request_payload["params"]
              * Example: If request_payload["params"] has {{"file": {{"filename": "...", "content": "..."}}}}, 
                then {input_model_name} must have a "file" field that accepts this structure
              * Use Dict[str, Any] for nested structures - DO NOT create nested model classes
              * After fixing the model, the function code will receive the correct params structure
              * In function code, access via: params.get("file", {{}}).get("content")
            
            {data_source_info}
            
            {credential_info}
            
            EXECUTION ERROR:
            {execution_error}
            
            {stderr_info}
            
            {response_info}
            
            CURRENT PYDANTIC MODELS:
            ```python
            {models_source}
            ```
            
            CURRENT FUNCTION SOURCE CODE:
            ```python
            {source_code}
            ```
            
            TASK:
            Analyze the error and fix ONLY the specific logical issue. Do NOT rewrite the entire function.
            
            ⚠️ CRITICAL - WHEN TO MODIFY MODELS:
            - MODIFY models_source IF:
              * "VALIDATED INPUT PARAMETERS" is empty {{}} BUT "ORIGINAL REQUEST PAYLOAD" has data in params
              * This means the model is rejecting/dropping fields - you MUST fix the model
              * Add the missing fields to {input_model_name} using Dict[str, Any] for nested structures
              * Example: If request_payload["params"] = {{"file": {{"filename": "...", "content": "..."}}}}
                Then {input_model_name} should have: file: Dict[str, Any] = Field(..., description="File data")
              * After fixing the model, also update the function code to handle the correct params structure
            - DO NOT modify models_source IF:
              * "VALIDATED INPUT PARAMETERS" has data - the model is working, fix only the function code
              * The error is about function logic, not validation
            
            COMMON LOGICAL ERRORS TO FIX:
            
            1. MongoDB Collection Boolean Checks:
               ❌ WRONG: if not collection:
               ✅ CORRECT: if collection is None:
               MongoDB collection objects are truthy even when empty, so use explicit None check.
            
            2. Missing Directory Creation:
               ❌ WRONG: 
               with open(file_path, "wb") as f:
                   f.write(file_bytes)
               ✅ CORRECT:
               import os
               os.makedirs(os.path.dirname(file_path), exist_ok=True)
               with open(file_path, "wb") as f:
                   f.write(file_bytes)
            
            3. ObjectId Conversion Issues:
               ❌ WRONG: 
               doc = await collection.find_one({{"_id": params.get("documentId")}})
               ✅ CORRECT:
               from bson import ObjectId
               from bson.errors import InvalidId
               
               doc_id = params.get("documentId")
               if doc_id:
                   try:
                       # Try to convert string to ObjectId if it's a valid 24-char hex string
                       if isinstance(doc_id, str) and len(doc_id) == 24:
                           doc_id = ObjectId(doc_id)
                       elif not isinstance(doc_id, ObjectId):
                           doc_id = ObjectId(doc_id)
                   except (InvalidId, ValueError):
                       # Keep as string if conversion fails
                       pass
                   doc = await collection.find_one({{"_id": doc_id}})
            
            4. Missing Imports / ImportError:
               - If error mentions undefined name, add the import INSIDE the function body
               - Common: import os, import logging, from bson import ObjectId, etc.
               - CRITICAL for database access:
                 ❌ WRONG: from services.database import get_default_async_db_client, get_async_db_client, get_db_client
                 ✅ CORRECT: from services.database import Database
                 ✅ Then use: collection = Database.get_collection("collection_name")
                 - The Database class is the ONLY way to access the database
                 - DO NOT try to import any other functions from services.database
                 - If you see ImportError for get_*_db_client functions, replace with Database.get_collection()
            
            5. Database Wrapper is None:
               - Functions receive db_wrapper parameter, but it may be None
               - If db_wrapper is None, you can STILL access the database directly
               - ❌ WRONG (trying to import non-existent functions):
                 ```python
                 if db_wrapper is None:
                     from services.database import get_default_async_db_client  # This doesn't exist!
                     client = get_default_async_db_client()
                 ```
               - ✅ CORRECT (use Database.get_collection() directly):
                 ```python
                 from services.database import Database
                 
                 # Whether db_wrapper is None or not, you can always use:
                 collection = Database.get_collection("collection_name")
                 doc = await collection.find_one({{"_id": doc_id}})
                 ```
               - The Database class handles connection automatically - no need for db_wrapper
               - If you see errors about "db_wrapper is None" or "Cannot import get_*_db_client", 
                 replace with direct Database.get_collection() usage
               - Example fix:
                 ```python
                 # Before (wrong - tries to import non-existent function):
                 if db_wrapper is None:
                     from services.database import get_async_db_client
                     client = get_async_db_client()
                 
                 # After (fixed - use Database directly):
                 from services.database import Database
                 collection = Database.get_collection("your_collection_name")
                 # Now use collection with await for all operations
                 ```
            
            6. Type Mismatches:
               - Check if variables are used with wrong types (e.g., string vs int)
               - Ensure proper type conversions before operations
            
            7. Undefined Variables:
               - If NameError, ensure variable is defined before use
               - Check for typos in variable names
            
            7.5. KeyError with Database.insert_one() (CRITICAL):
               - If KeyError occurs when accessing result["_id"] after db.insert_one():
               - Database.insert_one() returns {{"inserted_id": str(...)}}, NOT {{"_id": ...}}
               - ❌ WRONG: result = await db.insert_one(...); record_id = result["_id"]
               - ❌ WRONG: result = await db.insert_one(...); record_id = str(result["_id"])
               - ✅ CORRECT: result = await db.insert_one(...); record_id = result["inserted_id"]
               - The inserted_id is ALREADY a string, so use it directly without str() conversion
               - Example fix:
                 ```python
                 # Before (wrong - causes KeyError: '_id'):
                 result = await db.insert_one(collection_name, document)
                 record_id = str(result["_id"])
                 
                 # After (fixed - use inserted_id):
                 result = await db.insert_one(collection_name, document)
                 record_id = result["inserted_id"]  # Already a string
                 ```
            
            7.6. Database.update_one() double $set (WriteError code 52):
               - Database.update_one(collection, filters, fields) wraps plain fields in $set automatically
               - ❌ WRONG: await Database.update_one(coll, query, {{"$set": update_fields}})
               - ✅ CORRECT: await Database.update_one(coll, query, update_fields)
               - If using collection.update_one directly: pass {{"$set": fields}} once only, not nested $set
            
            8. Threading / event loop (RuntimeError: can't start new thread / no current event loop):
               - Caused by sync pymongo, run_in_executor, or asyncio.to_thread on Motor/Database in sandbox subprocess
               - ❌ WRONG: loop.run_in_executor(None, ...); asyncio.to_thread(coll.find_one, ...); collection.find_one(...) without await
               - ❌ WRONG: resolve_field_name with sample find_one per field before a simple insert — remove it; use param snake_case keys directly
               - ❌ WRONG: Database() instantiation — use class methods only
               - ✅ CORRECT: result = await Database.insert_one(collection_name, document); record_id = result["inserted_id"]
               - ✅ CORRECT: doc = await collection.find_one(query)  # only on main async path, never in a thread pool
               - For simple inserts matching snake_case params, delete resolve_field_name entirely and use one insert_one call

            8.5. MongoDB find/aggregate cursors (CRITICAL — sandbox uses PyMongo native async):
               - Errors: 'coroutine' object has no attribute 'to_list'; AsyncCursor/AsyncCommandCursor can't be used in 'await' expression
               - ❌ WRONG: docs = await collection.aggregate(pipeline).to_list(length=None)
               - ❌ WRONG: docs = await collection.aggregate(pipeline)
               - ❌ WRONG: docs = await collection.find(query)
               - ✅ CORRECT: docs = await Database.cursor_to_list(collection.aggregate(pipeline))
               - ✅ CORRECT: docs = await Database.aggregate_to_list("collection_name", pipeline)
               - ✅ CORRECT: docs = await Database.cursor_to_list(collection.find(query), length=100)
               - ✅ CORRECT: cursor = collection.find(query); docs = await cursor.to_list(length=100)
               - ✅ CORRECT: doc = await Database.find_one(collection_name, filters)
               - ✅ CORRECT: docs = await Database.find_to_list(collection_name, filters, length=100)
               - ❌ NEVER: await Database.find(...)  # class method does not exist
               - Value-returning Database helpers (await the class method): find_one, insert_one, update_one, delete_one
               - Also OK: await collection.find_one(query) after collection = Database.get_collection(...)
            
            9. Memory Errors (MemoryError):
               - Occurs when processing large files/images
               - For image processing: resize images before processing if they're too large
               - For file operations: process in chunks for large files
               - Example fix for PIL images:
                 ```python
                 from PIL import Image
                 
                 # Before (wrong - might cause MemoryError for large images):
                 image = Image.open(image_path)
                 text = pytesseract.image_to_string(image)
                 
                 # After (fixed - resize if too large):
                 image = Image.open(image_path)
                 # Resize if image is too large (e.g., > 2000px on any side)
                 max_size = 2000
                 if image.width > max_size or image.height > max_size:
                     image.thumbnail((max_size, max_size), Image.Resampling.LANCZOS)
                 text = pytesseract.image_to_string(image)
                 ```
            
            10. Simulated Code is not allowed. 
            If there is any placeholder code, simulated code or TODOs or user expected edits, you need to fix the code by adding the missing code.
            Users have NO ACCESS to modify this code - it must work as-is.
            
            11. HTTP Requests - DO NOT USE secure_http (CRITICAL):
               - ❌ NEVER use secure_http parameter - it may not be available and is NOT reliable
               - ❌ WRONG: if secure_http is None: return {{"error": "secure_http is required"}}
               - ❌ WRONG: response = await secure_http.request(url, method="GET")
               - ❌ WRONG: if secure_http is None: raise ValueError("secure_http is required")
               - ✅ ALWAYS use requests or httpx directly - they are already installed
               - ✅ CORRECT: import requests; response = requests.get(url, headers=headers, timeout=10)
               - ✅ CORRECT: import httpx; async with httpx.AsyncClient() as client: response = await client.get(url)
               - If you see errors about "secure_http is not available" or "secure_http object is not available", 
                 replace ALL secure_http usage with direct requests/httpx imports and calls
               - Example fix:
                 ```python
                 # Before (wrong - uses secure_http):
                 if secure_http is None:
                     return {{"error": "secure_http is required"}}
                 response = await secure_http.request(url, method="GET", headers=headers)
                 
                 # After (fixed - uses requests directly):
                 import requests
                 response = requests.get(url, headers=headers, timeout=10)
                 response.raise_for_status()
                 data = response.json()
                 ```
            
            12. Model Classes Are NOT Available (CRITICAL):
               - The Pydantic models shown above (like {input_model_name}, {response_model_name}, FileInput, FileContent, FileUpload, etc.) are ONLY for reference
               - Model classes are NOT available in the function execution context
               - Functions receive `params` as a plain Python dict, NOT as a model instance
               - ❌ WRONG: file_input = {input_model_name}(**params) or FileInput(**params) or isinstance(params, FileInput)
               - ❌ WRONG: filename = file_input.filename or file_input.file.filename
               - ❌ WRONG: if isinstance(params, FileInput): ...
               - ✅ CORRECT: filename = params.get("file", {{}}).get("filename") or params.get("fileName")
               - ✅ CORRECT: file_obj = params.get("file", {{}})
               - ✅ CORRECT: filename = file_obj.get("filename") if isinstance(file_obj, dict) else None
               - Always access data via params.get() or params["key"] - NEVER instantiate or reference model classes
               - If you see code like "FileInput", "FileContent", "FileUpload", "{input_model_name}", etc., replace it with direct params dict access
               - If the error is "name 'FileInput' is not defined" or similar, the fix MUST remove all references to model classes and use params dict access instead
            
            13. During document extraction, the document may be text-based or scanned. First attempt text extraction. If the extracted text is empty or contains only form-feed characters (\f), classify the document as scanned and perform OCR. For OCR, convert PDF pages to images at 300 DPI and extract text using Tesseract with --oem 1 --psm 6
            
            14. Email/SMTP credentials (when the function sends email - fix missing or wrong credential usage):
               - PREFERRED: If DATA SOURCE CONFIG above has "credentials" (list) or "email_credential_name", read from request_meta["credentials"] using that name. The value may be a JSON string with keys: sender, password, smtp_server, smtp_port. Parse with json.loads if it is a string.
               - ❌ WRONG: reading from global config/config.json; hardcoding email_sender, email_password; or assuming config is from a module that is not in scope.
               - ✅ CORRECT: In the function, obtain config from the data source (the DATA SOURCE CONFIGURATION above shows it; the generated code may have it as a literal dict or from a closure). Then:
                 * cred_name = config.get("email_credential_name") or (config.get("credentials") or [None])[0]
                 * If cred_name: creds = (request_meta or {{}}).get("credentials") or {{}}; val = creds.get(cred_name); if isinstance(val, str): import json; val = json.loads(val); sender = val.get("sender"); password = val.get("password"); smtp_server = val.get("smtp_server") or "smtp.gmail.com"; smtp_port = val.get("smtp_port") or 587
                 * Else: sender = config.get("email_sender"); password = config.get("email_password"); smtp_server = config.get("smtp_server") or "smtp.gmail.com"; smtp_port = config.get("smtp_port", 587)
                 * If not sender or not password: return {{"error": "Email credentials not configured. Add in project credentials or provide in prompt.", ...}}
                 * Then use sender, password, smtp_server, smtp_port for smtplib.
               - FALLBACK: If config has email_sender, email_password, smtp_server, smtp_port (from user prompt), use those.
               - If the error is about missing email_sender/email_password/smtp or 'coroutine' object, apply the pattern above (request_meta["credentials"] or config).
            
            CRITICAL RULES:
            - Fix ONLY the logical error causing the failure
            - Keep the function structure, logic flow, and overall implementation intact
            - Only modify the specific lines that cause the error
            - Preserve all existing functionality
            - Maintain exact indentation and formatting
            - Keep all comments, docstrings, and existing error handling
            - Add missing imports INSIDE the function body if needed
            - Only update models if field types are fundamentally wrong (rare)
            - Do NOT add unnecessary try-except blocks to hide errors
            - Do NOT rewrite the entire function logic
            - No simulated code or TODOs or user expected edits or placeholder code.
            
            FIXING STRATEGY:
            1. Identify the exact line/operation causing the error
            2. Fix that specific logical issue (e.g., add None check, create directory, convert ObjectId)
            3. Ensure the fix maintains the original function's intent
            4. Test the fix mentally: would this resolve the error?
            
            Respond in this EXACT XML format (no markdown, no JSON, no explanation):
            <response>
            <models_source>
            complete models source code here
            - If "VALIDATED INPUT PARAMETERS" is empty but "ORIGINAL REQUEST PAYLOAD" has data: UPDATE the model to accept those fields
            - Otherwise: return EXACTLY as shown above (unchanged)
            - Use Dict[str, Any] for nested structures, NOT nested model classes
            </models_source>
            <source_code>
            complete updated function source code here (with ONLY the logical fix applied)
            </source_code>
            </response>"""

        # Call LLM
        response = await async_llm_call(prompt)
        # response = llm.call(prompt)
        finished_at = datetime.utcnow()
        response_text = response.strip()
        prompt_tokens = len(prompt) // 4
        completion_tokens = len(response_text) // 4
        total_tokens = prompt_tokens + completion_tokens
        record_llm_call(
            project_id=project_id,
            operation="agent-dynamic-execute",
            sub_operation="fix-execution-error",
            model="gemini-3.6-flash",
            prompt_tokens=prompt_tokens,
            completion_tokens=completion_tokens,
            total_tokens=total_tokens,
            status="success",
            started_at=started_at,
            finished_at=finished_at,
            metadata={"function_id": function_id, "error_type": error_type},
        )
        
        logger.debug(f"Raw LLM response for execution error fix: {response_text[:500]}...")
        
        # Parse XML response
        try:
            # Extract content between XML tags
            models_match = re.search(r'<models_source>(.*?)</models_source>', response_text, re.DOTALL)
            source_match = re.search(r'<source_code>(.*?)</source_code>', response_text, re.DOTALL)
            
            if not source_match:
                logger.error("Could not extract source_code from LLM response")
                return None
            
            # Extract and clean code (strip markdown fences if present)
            extracted_source_code = source_match.group(1).strip()
            extracted_source_code = strip_markdown_code_fences(extracted_source_code)
            # Remove model class references (model classes are not available at runtime)
            extracted_source_code = remove_model_class_references(extracted_source_code, input_model_name, response_model_name)
            # Convert attribute access to dict access (params.xxx -> params.get("xxx"))
            extracted_source_code = convert_attribute_access_to_dict_access(extracted_source_code)
            
            extracted_models_source = models_match.group(1).strip() if models_match else None
            if extracted_models_source:
                extracted_models_source = strip_markdown_code_fences(extracted_models_source)
            
            # Models are optional - if not provided, keep original
            fixed_code = {
                "models_source": extracted_models_source if extracted_models_source else models_source,
                "source_code": extracted_source_code
            }
            
        except Exception as parse_error:
            logger.error(f"XML parsing failed: {str(parse_error)}")
            # Fallback: try JSON parsing
            try:
                # Remove markdown if present
                if "```json" in response_text:
                    response_text = response_text.split("```json")[1].split("```")[0].strip()
                elif "```" in response_text:
                    response_text = response_text.split("```")[1].split("```")[0].strip()
                
                # Try to repair and parse JSON
                fixed_code = json.loads(repair_json(response_text))
                
                # Strip markdown code fences from code fields if present
                if "source_code" in fixed_code and isinstance(fixed_code["source_code"], str):
                    fixed_code["source_code"] = strip_markdown_code_fences(fixed_code["source_code"])
                    # Remove model class references
                    fixed_code["source_code"] = remove_model_class_references(fixed_code["source_code"], input_model_name, response_model_name)
                if "models_source" in fixed_code and isinstance(fixed_code["models_source"], str):
                    fixed_code["models_source"] = strip_markdown_code_fences(fixed_code["models_source"])
            except Exception as json_error:
                logger.error(f"JSON parsing also failed: {str(json_error)}")
                return None
        
        # Validate response structure
        if "source_code" not in fixed_code:
            logger.error("LLM response missing source_code", extra={
                "function_id": function_id,
                "response_keys": list(fixed_code.keys())
            })
            return None
        
        # Validate and handle models_source
        # If LLM didn't provide models_source or it's empty/invalid, use original
        llm_models_source = fixed_code.get("models_source", "").strip()
        if not llm_models_source or llm_models_source == models_source.strip():
            # LLM didn't update models or returned same - use original
            fixed_code["models_source"] = models_source
            logger.debug("Using original models_source (LLM didn't update models)")
        else:
            # LLM provided updated models - validate it's not empty
            if len(llm_models_source) < 10:  # Too short to be valid model code
                logger.warning("LLM returned suspiciously short models_source, using original")
                fixed_code["models_source"] = models_source
            else:
                fixed_code["models_source"] = llm_models_source
                logger.debug("Using LLM-updated models_source")
        
        # Validate that the code is not empty
        if not fixed_code["source_code"].strip():
            logger.error("LLM returned empty source code")
            return None
        
        logger.info("LLM execution error fixing completed", extra={
            "function_id": function_id,
            "models_length": len(fixed_code.get("models_source", "")),
            "source_length": len(fixed_code.get("source_code", "")),
            "models_updated": fixed_code.get("models_source", "") != models_source
        })
        return fixed_code
        
    except Exception as e:
        finished_at = datetime.utcnow()
        record_llm_call(
            project_id=project_id,
            operation="agent-dynamic-execute",
            sub_operation="fix-execution-error",
            model="gemini-3.6-flash",
            prompt_tokens=0,
            completion_tokens=0,
            total_tokens=0,
            status="failed",
            started_at=started_at,
            finished_at=finished_at,
            metadata={"function_id": function_id, "error": str(e)},
        )
        logger.error(f"LLM execution error fixing failed: {str(e)}", extra={
            "function_id": function_id,
            "error": str(e)
        })
        traceback.print_exc()
        return None


async def fix_source_code_with_llm(
    params: Dict[str, Any],
    validation_errors: List[Dict],
    source_code: str,
    models_source: str,
    input_model_name: str,
    function_id: str,
    project_id: Optional[str] = None,
) -> Optional[Dict[str, str]]:
    """
    Use LLM to modify source code and models to accept the incoming parameters.
    
    Args:
        params: Incoming parameters that failed validation
        validation_errors: Pydantic validation errors
        source_code: Current function source code
        models_source: Current Pydantic models source
        input_model_name: Name of the input model class
        function_id: Function identifier for context
    
    Returns:
        Dict with 'source_code' and 'models_source' keys, or None if fixing failed
    """
    try:
        # Truncate large base64 strings in params to prevent token limit issues
        truncated_params = truncate_large_base64_strings(copy.deepcopy(params), max_string_length=500)
        # Also truncate validation_errors as they may contain the full input values with base64 strings
        truncated_validation_errors = truncate_large_base64_strings(copy.deepcopy(validation_errors), max_string_length=500)
        
        # Log sizes for debugging
        logger.info(f"Preparing LLM prompt for source code fix", extra={
            "function_id": function_id,
            "source_code_size": len(source_code),
            "models_source_size": len(models_source),
            "truncated_params_size": len(json.dumps(truncated_params, default=str)),
            "truncated_validation_errors_size": len(json.dumps(truncated_validation_errors, default=str))
        })
        
        # Prepare prompt for LLM - use XML tags for clearer structure
        prompt = f"""You are a Python code refactoring expert. Your task is to modify the Pydantic model and function source code to accept the incoming parameters.

            Function ID: {function_id}
            Input Model Name: {input_model_name}

            INCOMING PARAMETERS (that we need to accept):
            {json.dumps(truncated_params, indent=2, default=str)}

            VALIDATION ERRORS:
            {json.dumps(truncated_validation_errors, indent=2, default=str)}

            CURRENT PYDANTIC MODELS:
            ```python
            {models_source}
            ```

            CURRENT FUNCTION SOURCE CODE:
            ```python
            {source_code}
            ```

            ⚠️ CRITICAL - PARAMS IS A DICT, NOT A MODEL INSTANCE:
            - Functions receive `params` as a plain Python dict, NOT as a Pydantic model instance
            - Models are ONLY used for validation before/after execution, NOT during execution
            - Model classes (like FileContent, FileInput, etc.) are NOT available in the execution context
            - The sandbox execution environment does NOT have access to model class definitions
            
            ⚠️ CRITICAL - USE FLAT SCHEMAS:
            - DO NOT create nested Pydantic model classes (e.g., FileContent, FileInput, FileData)
            - For nested structures, use Dict[str, Any] in the model definition
            - Example:
              ❌ WRONG:
                class FileContent(BaseModel):
                    content: str
                class UploadPdfRequest(BaseModel):
                    file: FileContent  # Nested model - DON'T DO THIS
            
              ✅ CORRECT:
                class UploadPdfRequest(BaseModel):
                    file: Dict[str, Any]  # Flat schema using Dict
                    # This accepts {{"content": "base64..."}} as a dict
            
            ⚠️ CRITICAL - PARAMS ACCESS PATTERNS:
            - ❌ WRONG: params.file.content or params.file or file_obj = params.file
            - ❌ WRONG: if isinstance(params, FileInput): ...
            - ✅ CORRECT: params.get("file", {{}}).get("content") or params["file"]["content"]
            - ✅ CORRECT: file_obj = params.get("file", {{}})
            - ✅ CORRECT: content = file_obj.get("content") if isinstance(file_obj, dict) else None
            - Always use dict access methods: params.get("key"), params["key"], or params.get("key", {{}}).get("nested_key")
            - NEVER use attribute access like params.attribute or params.nested.attribute

            TASK:
            1. Identify the parameter name mismatches from the validation errors
            2. Update the Pydantic model ({input_model_name}) to use the incoming parameter names. Use FLAT SCHEMA with Dict[str, Any] for nested structures
            3. Update ALL references in function code to use dict access (params.get("key")) instead of attribute access
            4. Convert ANY attribute access (params.xxx) to dict access (params.get("xxx") or params["xxx"])
            5. Ensure variable names (snake_case) are also updated consistently
            6. Keep all other logic, types, and functionality exactly the same

            CRITICAL RULES:
            - Use Dict[str, Any] for nested structures in models - NEVER create nested model classes
            - Only change parameter/field names, not types or logic
            - Update params.get("old_name") to params.get("new_name")
            - Update dictionary keys in the code
            - Update variable names (e.g., old_param -> new_param)
            - Convert params.attribute to params.get("attribute") or params["attribute"]
            - For nested access: params.file.content → params.get("file", {{}}).get("content")
            - Maintain exact indentation and formatting
            - Keep all imports, comments, and docstrings

            Respond in this EXACT XML format (no markdown, no JSON, no explanation):
            <response>
            <models_source>
            complete updated models source code here
            </models_source>
            <source_code>
            complete updated function source code here
            </source_code>
            </response>"""

        # Call LLM with error handling
        started_at = datetime.utcnow()
        try:
            # Log prompt size for debugging (but don't log the full prompt as it might be huge)
            prompt_size = len(prompt)
            logger.info(f"Calling LLM for source code fix (prompt size: {prompt_size} characters)", extra={
                "function_id": function_id,
                "prompt_size": prompt_size
            })
            
            response = await async_llm_call(prompt)
            # response = llm.call(prompt)
            finished_at = datetime.utcnow()
            if not response:
                logger.error("LLM call returned empty response")
                record_llm_call(
                    project_id=project_id,
                    operation="agent-dynamic-execute",
                    sub_operation="fix-source-code-error",
                    model="gemini-3.6-flash",
                    prompt_tokens=len(prompt) // 4,
                    completion_tokens=0,
                    total_tokens=len(prompt) // 4,
                    status="failed",
                    started_at=started_at,
                    finished_at=finished_at,
                    metadata={"function_id": function_id, "error": "empty response"},
                )
                return None
                
            response_text = response.strip()
            prompt_tokens = len(prompt) // 4
            completion_tokens = len(response_text) // 4
            total_tokens = prompt_tokens + completion_tokens
            record_llm_call(
                project_id=project_id,
                operation="agent-dynamic-execute",
                sub_operation="fix-source-code-error",
                model="gemini-3.6-flash",
                prompt_tokens=prompt_tokens,
                completion_tokens=completion_tokens,
                total_tokens=total_tokens,
                status="success",
                started_at=started_at,
                finished_at=finished_at,
                metadata={"function_id": function_id},
            )
            
            logger.debug(f"Raw LLM response: {response_text[:500]}...")
        except Exception as llm_error:
            finished_at = datetime.utcnow()
            logger.error(f"LLM call failed: {str(llm_error)}", extra={
                "function_id": function_id,
                "error_type": type(llm_error).__name__
            })
            record_llm_call(
                project_id=project_id,
                operation="agent-dynamic-execute",
                sub_operation="fix-source-code-error",
                model="gemini-3.6-flash",
                prompt_tokens=len(prompt) // 4,
                completion_tokens=0,
                total_tokens=len(prompt) // 4,
                status="failed",
                started_at=started_at,
                finished_at=finished_at,
                metadata={"function_id": function_id, "error": str(llm_error)},
            )
            traceback.print_exc()
            return None
        
        # Parse XML response
        try:
            # Extract content between XML tags
            models_match = re.search(r'<models_source>(.*?)</models_source>', response_text, re.DOTALL)
            source_match = re.search(r'<source_code>(.*?)</source_code>', response_text, re.DOTALL)
            
            if not models_match or not source_match:
                logger.error("Could not extract XML tags from LLM response")
                return None
            
            # Extract and clean code (strip markdown fences if present)
            extracted_source_code = source_match.group(1).strip()
            extracted_source_code = strip_markdown_code_fences(extracted_source_code)
            # Remove model class references (model classes are not available at runtime)
            # Note: fix_source_code_with_llm doesn't have response_model_name, so we only use input_model_name
            extracted_source_code = remove_model_class_references(extracted_source_code, input_model_name, "")
            # Convert attribute access to dict access (params.xxx -> params.get("xxx"))
            extracted_source_code = convert_attribute_access_to_dict_access(extracted_source_code)
            
            extracted_models_source = models_match.group(1).strip()
            extracted_models_source = strip_markdown_code_fences(extracted_models_source)
            
            fixed_code = {
                "models_source": extracted_models_source,
                "source_code": extracted_source_code
            }
            
        except Exception as parse_error:
            logger.error(f"XML parsing failed: {str(parse_error)}")
            # Fallback: try JSON parsing
            try:
                # Remove markdown if present
                if "```json" in response_text:
                    response_text = response_text.split("```json")[1].split("```")[0].strip()
                elif "```" in response_text:
                    response_text = response_text.split("```")[1].split("```")[0].strip()
                
                # Try to repair and parse JSON
                fixed_code = json.loads(repair_json(response_text))
                
                # Strip markdown code fences from code fields if present
                if "source_code" in fixed_code and isinstance(fixed_code["source_code"], str):
                    fixed_code["source_code"] = strip_markdown_code_fences(fixed_code["source_code"])
                    # Remove model class references
                    fixed_code["source_code"] = remove_model_class_references(fixed_code["source_code"], input_model_name, "")
                if "models_source" in fixed_code and isinstance(fixed_code["models_source"], str):
                    fixed_code["models_source"] = strip_markdown_code_fences(fixed_code["models_source"])
            except Exception as json_error:
                logger.error(f"JSON parsing also failed: {str(json_error)}")
                return None
        
        # Validate response structure
        if "models_source" not in fixed_code or "source_code" not in fixed_code:
            logger.error("LLM response missing required keys", extra={
                "function_id": function_id,
                "response_keys": list(fixed_code.keys())
            })
            return None
        
        # Validate that the code is not empty
        if not fixed_code["models_source"].strip() or not fixed_code["source_code"].strip():
            logger.error("LLM returned empty code")
            return None
        
        logger.info("LLM source code fixing completed", extra={
            "function_id": function_id,
            "models_length": len(fixed_code.get("models_source", "")),
            "source_length": len(fixed_code.get("source_code", ""))
        })
        print('Fixed code',fixed_code)
        return fixed_code
        
    except Exception as e:
        logger.error(f"LLM source code fixing failed: {str(e)}", extra={
            "function_id": function_id,
            "error": str(e)
        })
        traceback.print_exc()
        return None





async def execute_dynamic_function_async(
    path_project_id: str,
    payload: Dict[str, Any],
    header_subscriber_id: Optional[str] = None,
    header_user_id: Optional[str] = None,
    header_org_id: Optional[str] = None,
    referer: Optional[str] = None,
):
    """
    Dispatch generated backend functions through a universal endpoint.
    """
    request_id = str(uuid.uuid4())[:8]
    routing_project_id = _routing_project_id_for_execute(path_project_id, payload)
    project_id = routing_project_id  # registry, credentials, and logs use routed id
    logger.info(f"[{request_id}] Dynamic function execution started", extra={
        "path_project_id": path_project_id,
        "routing_project_id": routing_project_id,
        "endpoint": "execute_dynamic_function",
    })
    
    try:
        function_id = payload.get("function_id")
        params = payload.get("params", {}) or {}
        request_meta = payload.get("request_meta", {}) or {}
        if not isinstance(request_meta, dict):
            request_meta = {}
        if header_user_id and not (request_meta.get("user_id") or request_meta.get("userId")):
            request_meta["user_id"] = header_user_id
            request_meta["userId"] = header_user_id
        if header_org_id and not (request_meta.get("org_id") or request_meta.get("orgId")):
            request_meta["org_id"] = header_org_id
            request_meta["orgId"] = header_org_id
        # Discover screen_id from Angular archive/public URL when FE omits it.
        # public_url shape: .../screen_<id>-v<version>
        if referer and not (request_meta.get("screen_id") or request_meta.get("screenId")):
            import re as _re
            m = _re.search(r"(screen_[0-9]+_[0-9a-fA-F]+)", str(referer))
            if m:
                request_meta["screen_id"] = m.group(1)
        
        subscriber_id = header_subscriber_id or _subscriber_id_from_project_id(routing_project_id)
        main_db_name = get_main_db_name()
        subscriber_db_name = f"{main_db_name}_sb_{subscriber_id}" if subscriber_id else None
        logger.info(
            "Resolved subscriber routing for dynamic execute",
            extra={
                "path_project_id": path_project_id,
                "routing_project_id": routing_project_id,
                "subscriber_id": subscriber_id,
                "subscriber_db_name": subscriber_db_name,
                "main_db_name": main_db_name,
            },
        )
        if subscriber_db_name:
            logger.info(
                "Sandbox data will use subscriber DB %s (not main DB %s)",
                subscriber_db_name,
                main_db_name,
            )
        else:
            logger.warning(
                "No subscriber DB for execute — data will use main DB %s (check project_id has _sb_ suffix)",
                main_db_name,
            )

        if not function_id:
            logger.warning("Missing function_id in request")
            raise HTTPException(status_code=400, detail={"error": "function_id is required"})

        logger.info("Looking up function", extra={
            "routing_project_id": routing_project_id,
            "function_id": function_id
        })

        # Lookup function in registry
        entry = FunctionRegistry.get(routing_project_id, function_id)

        # 2. If missing, try "Lazy Load" from Database
        if not entry:
            logger.info(f"Function '{function_id}' not found in registry. Attempting lazy load from DB...", extra={
                "routing_project_id": routing_project_id,
                "function_id": function_id
            })
            try:
                # Instantiate generator to reload this specific function
                # We create a new instance to ensure we can access the DB method
                temp_generator = BackendGenerator()
                await temp_generator.reload_single_function(routing_project_id, function_id)
                
                # 3. Check registry again (It should be there now)
                entry = FunctionRegistry.get(routing_project_id, function_id)
                
                if entry:
                    logger.info(f"Successfully lazy-loaded function '{function_id}'", extra={
                        "routing_project_id": routing_project_id,
                        "function_id": function_id
                    })
            except Exception as e:
                logger.error(f"Failed to lazy-load function '{function_id}': {e}", extra={
                    "routing_project_id": routing_project_id,
                    "function_id": function_id
                })
        if not entry:
            logger.error("Function not found", extra={
                "routing_project_id": routing_project_id,
                "function_id": function_id
            })
            raise HTTPException(status_code=404, detail={"error": f"Function '{function_id}' not found"})

        # Validate input parameters with Pydantic (with LLM source code fix retry)
        validated_params = None
        attempt = 0
        max_attempts = 2  # Original + 1 LLM fix attempt
        
        while attempt < max_attempts and validated_params is None:
            try:
                logger.debug(f"Validating input params (attempt {attempt + 1})", extra={
                    "function_id": function_id
                })
                validated_params = entry.input_model(**params)
                
            except ValidationError as ve:
                if attempt == 0:
                    # First failure - try LLM source code fixing
                    logger.info("Initial validation failed, attempting LLM source code fixing", extra={
                        "function_id": function_id,
                        "errors": ve.errors()
                    })

                    await _save_function_error_log(
                        project_id,
                        function_id,
                        error_message=f"Parameter validation failed: {str(ve)}",
                        error_type="ValidationError",
                        retry_attempts=attempt + 1,
                        params=params,
                        validation_errors=ve.errors(),
                    )
                    
                    # Get current function record for source code
                    record = await backend_generator.function_repository.get_function(project_id, function_id)
                    if not record:
                        logger.error("Could not retrieve function for fixing")
                        raise HTTPException(status_code=422, detail={
                            "error": "validation_error",
                            "details": ve.errors(),
                            "message": "Parameter validation failed and function could not be retrieved for fixing"
                        })
                    
                    # Try to fix source code with LLM
                    fixed_code = await fix_source_code_with_llm(
                        params=params,
                        validation_errors=ve.errors(),
                        source_code=record.get("source_code", ""),
                        models_source=record.get("models_source", ""),
                        input_model_name=record.get("input_model_name", ""),
                        function_id=function_id,
                        project_id=project_id,
                    )
                    
                    if fixed_code:
                        # Update and reload the function
                        logger.info("Updating function with LLM-fixed source code")
                        reload_success = await backend_generator.reload_single_function_and_update(project_id, function_id, fixed_code['models_source'], fixed_code['source_code'])
                        
                        if reload_success:
                            
                            # Get updated entry from registry
                            entry = FunctionRegistry.get(project_id, function_id)
                            if not entry:
                                raise HTTPException(status_code=500, detail={
                                    "error": "reload_failed",
                                    "message": "Function was updated but failed to reload into registry"
                                })
                            await _mark_function_error_llm_outcome(
                                project_id, function_id, attempted=True, successful=True
                            )
                            attempt += 1
                        else:
                            # Reload failed
                            logger.error("Failed to reload function after LLM fix")
                            raise HTTPException(status_code=500, detail={
                                "error": "reload_failed",
                                "message": "Function source was updated but failed to reload"
                            })
                    else:
                        # LLM fixing failed
                        logger.warning("LLM source code fixing unsuccessful")
                        await _mark_function_error_llm_outcome(
                            project_id, function_id, attempted=True, successful=False
                        )
                        
                        # Truncate validation errors in HTTPException detail to prevent huge error responses
                        truncated_details = truncate_large_base64_strings(copy.deepcopy(ve.errors()), max_string_length=500)
                        raise HTTPException(status_code=422, detail={
                            "error": "validation_error",
                            "details": truncated_details,
                            "message": "Parameter validation failed and automatic source code fixing was unsuccessful"
                        })
                else:
                    # Second failure after LLM fix - give up
                    logger.warning("Validation failed after LLM fixing", extra={
                        "errors": ve.errors(),
                        "function_id": function_id
                    })

                    # Store error logs in database
                    await _save_function_error_log(
                        project_id,
                        function_id,
                        error_message=f"Parameter validation failed: {str(ve)}",
                        error_type="ValidationError",
                        retry_attempts=attempt + 1,
                        params=params,
                        validation_errors=ve.errors(),
                        llm_fix_attempted=True,
                        llm_fix_successful=False,
                    )

                    # Truncate validation errors in HTTPException detail to prevent huge error responses
                    truncated_details = truncate_large_base64_strings(copy.deepcopy(ve.errors()), max_string_length=500)
                    raise HTTPException(status_code=422, detail={
                        "error": "validation_error",
                        "details": truncated_details,
                        "message": "Parameter validation failed even after automatic source code fixing"
                    })

        # Get non-restrictive sandbox worker pool
        # Check if system is overloaded
        function_worker_pool = get_function_worker_pool()
        if function_worker_pool._semaphore and function_worker_pool._semaphore._value == 0:
            # All workers busy
            logger.warning("All workers busy, rejecting request")
            raise HTTPException(status_code=503, detail={
                "error": "service_overloaded",
                "message": "Server is at capacity. Please retry in a moment.",
                "retry_after": 5,
            })

        # Prepare configuration for sandbox (optional - functions have full freedom)
        # db_wrapper and secure_http are provided for backward compatibility only
        # Functions can choose to ignore them and use direct imports instead:
        # - Use Database.get_collection() directly (no collection restrictions)
        # - Use requests/httpx/aiohttp directly (no domain restrictions)
        # - Import and use ANY library (OCR, PDF parsers, Stripe, etc.)
        db_wrapper_config: Optional[Dict] = None
        secure_http_config: Optional[Dict] = None

        # Note: We're NOT passing restrictive configs anymore
        # Functions have complete freedom to use any library or access database directly
        # These are only provided if functions want to use the convenience wrappers
        
        # Execute function inside non-restrictive sandbox (with LLM error recovery retry)
        logger.info("Executing function in non-restrictive sandbox", extra={
            "function_id": function_id,
            "sandbox_type": entry.type
        })

        # Inject credentials and config into request_meta (server-side; client cannot override)
        request_meta = dict(request_meta)
        cred_svc = CredentialService.optional()
        if cred_svc:
            credentials_dict = {}
            credentials_metadata = []
            logger.info(f"Loading credentials for project_id: {project_id}")
            cred_list = await cred_svc.list_credentials(project_id)
            logger.info(f"Found {len(cred_list)} credentials for project {project_id}: {[c['name'] for c in cred_list]}")
            for cred_meta in cred_list:
                value = await cred_svc.get_credential_value(project_id, cred_meta["name"])
                if value:
                    credentials_dict[cred_meta["name"]] = value
                    logger.debug(f"Loaded credential: {cred_meta['name']} (length: {len(value)})")
                else:
                    logger.warning(f"Failed to decrypt credential: {cred_meta['name']}")
                credentials_metadata.append(
                    {"name": cred_meta["name"], "type": cred_meta["type"], "service": cred_meta["service"]}
                )
            request_meta["credentials"] = credentials_dict
            request_meta["credentials_metadata"] = credentials_metadata
            logger.info(f"Injected {len(credentials_dict)} credentials into request_meta: {list(credentials_dict.keys())}")
        else:
            logger.warning("CredentialService not available (CRED_MASTER_KEY not set)")
            request_meta.setdefault("credentials", {})
            request_meta.setdefault("credentials_metadata", [])
        if "config" not in request_meta or not isinstance(request_meta["config"], dict):
            request_meta["config"] = {}
        request_meta["config"].update({
            "ai_agent_base_path": config.get("ai_agent_base_path", "/aiqod-agent/agent"),
            "LIBERTY_FS_BASE_URL": config.get("LIBERTY_FS_BASE_URL"),
            "ai_agent_base_url": config.get("ai_agent_base_url"),
            "fileUploadPath": config.get("fileUploadPath", "/data/publicfolder/liberty-fs/uploads"),
            "LIBERTY_FS_ROOT": config.get("LIBERTY_FS_ROOT")
        })
        request_meta["project_id"] = routing_project_id
        if subscriber_id is not None:
            request_meta["subscriber_id"] = subscriber_id
        if subscriber_db_name is not None:
            request_meta["subscriber_db_name"] = subscriber_db_name
        else:
            request_meta.pop("subscriber_db_name", None)

        # Correlate UI backend spans to workflow trace when FE passes execution context.
        # Older generated Angular apps often omit execution_id; recover from the live
        # paused LangGraph instance so ui_function / llm_ui spans still attach.
        try:
            request_meta = enrich_request_meta_from_pending_ui(
                request_meta,
                params=params if isinstance(params, dict) else {},
            )
        except Exception:
            pass

        # Execute function with retry logic for execution errors
        sandbox_result = None
        execution_attempt = 0
        max_execution_attempts = 3  # Original + 2 LLM fix attempt

        try:
            prepare_dynamic_function_observation(
                request_meta=request_meta,
                function_id=function_id,
                project_id=project_id,
            )
        except Exception:
            pass
        
        while execution_attempt < max_execution_attempts and (sandbox_result is None or not sandbox_result.success):
            # Execute function in isolated sandbox subprocess (no code restrictions)
            sandbox_result = await function_worker_pool.execute(
                function_source=entry.source_code,
                function_name=function_id,
                params=validated_params.model_dump(),
                db_wrapper_config=db_wrapper_config,
                secure_http_config=secure_http_config,
                request_meta=request_meta,
            )
            
            logger.info("Sandbox execution finished", extra={
                "function_id": function_id,
                "success": sandbox_result.success,
                "execution_time_ms": sandbox_result.execution_time_ms,
                "attempt": execution_attempt + 1
            })
            
            # Check sandbox execution result
            if not sandbox_result.success:
                error_msg = sandbox_result.error or "Unknown sandbox error"
                error_type = sandbox_result.error_type or 'ExecutionError'
                
                # Log the error with full details
                logger.error(
                    f"Function {function_id} execution failed (attempt {execution_attempt + 1}/{max_execution_attempts}): {error_type}: {error_msg}",
                    extra={
                        "function_id": function_id,
                        "error": error_msg,
                        "error_type": error_type,
                        "execution_time_ms": sandbox_result.execution_time_ms,
                        "attempt": execution_attempt + 1
                    }
                )

                params_to_log = validated_params.model_dump() if validated_params else params
                await _save_function_error_log(
                    project_id,
                    function_id,
                    error_message=error_msg,
                    error_type=error_type,
                    retry_attempts=execution_attempt + 1,
                    params=params_to_log,
                    traceback=sandbox_result.traceback,
                    stderr_output=sandbox_result.stderr_output,
                    execution_time_ms=sandbox_result.execution_time_ms,
                )
                
                # Skip retry for certain error types (timeout, permission, etc.)
                skip_retry = (
                    "timeout" in error_msg.lower() or
                    "permission" in error_msg.lower() or
                    "blocked" in error_msg.lower() or
                    "overloaded" in error_msg.lower()
                )
                
                if (
                    skip_retry
                    or not ENABLE_EXECUTION_ERROR_LLM_FIX
                    or execution_attempt >= max_execution_attempts - 1
                ):
                    # Don't retry for these errors or if we've exhausted attempts
                    logger.error("Sandbox execution failed (no retry)", extra={
                        "function_id": function_id,
                        "error": error_msg,
                        "execution_time_ms": sandbox_result.execution_time_ms,
                        "skip_retry": skip_retry
                    })

                    try:
                        observe_dynamic_function_execution(
                            request_meta=request_meta,
                            function_id=function_id,
                            success=False,
                            latency_ms=sandbox_result.execution_time_ms,
                            error=error_msg,
                            project_id=project_id,
                        )
                    except Exception:
                        pass

                    status_code = 500
                    if "timeout" in error_msg.lower():
                        status_code = 504
                    elif "permission" in error_msg.lower() or "blocked" in error_msg.lower():
                        status_code = 403

                    raise HTTPException(
                        status_code=status_code,
                        detail={
                            "error": "execution_failed",
                            "message": error_msg,
                            "execution_time_ms": sandbox_result.execution_time_ms,
                        }
                    )
                
                try:
                    observe_dynamic_function_execution(
                        request_meta=request_meta,
                        function_id=function_id,
                        success=False,
                        latency_ms=sandbox_result.execution_time_ms,
                        error=error_msg,
                        project_id=project_id,
                    )
                except Exception:
                    pass
                
                # First failure - try LLM execution error fixing
                if execution_attempt == 0:
                    # Truncate params for logging
                    params_to_log = validated_params.model_dump() if validated_params else params
                    truncated_params_for_log = truncate_large_base64_strings(copy.deepcopy(params_to_log), max_string_length=500)
                    logger.info("Execution failed, attempting LLM error fixing", extra={
                        "function_id": function_id,
                        "error": error_msg,
                        "error_type": error_type,
                        "params": truncated_params_for_log
                    })
                    
                    # Get current function record for source code and data source
                    record = await backend_generator.function_repository.get_function(project_id, function_id)
                    if not record:
                        logger.error("Could not retrieve function for error fixing")
                        raise HTTPException(status_code=500, detail={
                            "error": "execution_failed",
                            "message": error_msg,
                            "fix_error": "Function could not be retrieved for error fixing"
                        })
                    
                    # Get data source from metadata if available
                    data_source = record.get("metadata", {}).get("data_source")
                    
                    # Get any partial response (if function returned something before error)
                    response_received = None
                    if sandbox_result.result is not None:
                        response_received = sandbox_result.result
                    
                    # Build comprehensive error message including traceback if available
                    full_error_msg = error_msg
                    if sandbox_result.traceback:
                        full_error_msg = f"{error_msg}\n\nTraceback:\n{sandbox_result.traceback}"
                    elif "traceback" in error_msg.lower():
                        # Traceback might already be in error_msg
                        full_error_msg = error_msg

                    # Deterministic fix for Motor-vs-sandbox cursor await misuse (no LLM needed)
                    cursor_err_blob = "\n".join(
                        filter(
                            None,
                            [
                                full_error_msg,
                                sandbox_result.stderr_output or "",
                                sandbox_result.traceback or "",
                            ],
                        )
                    )
                    if _is_mongo_cursor_await_error(cursor_err_blob):
                        det_fixed = _apply_mongo_cursor_await_fix(
                            record.get("source_code", "")
                        )
                        if det_fixed:
                            logger.info(
                                "Applied deterministic Mongo cursor await fix for %s (skipping LLM)",
                                function_id,
                            )
                            reload_success = await backend_generator.reload_single_function_and_update(
                                project_id,
                                function_id,
                                record.get("models_source", ""),
                                det_fixed,
                            )
                            if reload_success:
                                entry = FunctionRegistry.get(project_id, function_id)
                                if entry:
                                    await _mark_function_error_llm_outcome(
                                        project_id,
                                        function_id,
                                        attempted=True,
                                        successful=True,
                                    )
                                    execution_attempt += 1
                                    continue
                    
                    # Try to fix execution error with LLM
                    # If validated_params is empty but payload has params, use original params to help LLM fix the model
                    params_to_pass = validated_params.model_dump() if validated_params else {}
                    if not params_to_pass and payload and payload.get("params"):
                        # Params is empty but request has data - pass original params so LLM can fix the model
                        params_to_pass = payload.get("params", {})
                    
                    fixed_code = await fix_execution_error_with_llm(
                        params=params_to_pass,
                        execution_error=full_error_msg,
                        error_type=error_type,
                        source_code=record.get("source_code", ""),
                        models_source=record.get("models_source", ""),
                        input_model_name=record.get("input_model_name", ""),
                        response_model_name=record.get("response_model_name", ""),
                        function_id=function_id,
                        data_source=data_source,
                        response_received=response_received,
                        request_payload=payload,
                        stderr_output=sandbox_result.stderr_output,
                        project_id=project_id,
                    )
                    
                    if fixed_code:
                        # Update and reload the function
                        logger.info("Updating function with LLM-fixed source code after execution error")
                        
                        # Ensure we have valid models_source - fall back to existing if LLM version is invalid
                        models_source_to_use = fixed_code.get('models_source', '')
                        if not models_source_to_use or len(models_source_to_use.strip()) < 10:
                            # LLM didn't provide valid models_source, use existing from DB
                            logger.warning("LLM models_source invalid or empty, using existing from DB")
                            models_source_to_use = record.get("models_source", "")
                        
                        reload_success = await backend_generator.reload_single_function_and_update(
                            project_id, 
                            function_id, 
                            models_source_to_use, 
                            fixed_code['source_code']
                        )
                        
                        if reload_success:
                            # Get updated entry from registry
                            entry = FunctionRegistry.get(project_id, function_id)
                            if not entry:
                                raise HTTPException(status_code=500, detail={
                                    "error": "reload_failed",
                                    "message": "Function was updated but failed to reload into registry"
                                })
                            await _mark_function_error_llm_outcome(
                                project_id, function_id, attempted=True, successful=True
                            )
                            execution_attempt += 1
                            # Continue loop to retry execution
                            continue
                        else:
                            # Reload failed
                            logger.error("Failed to reload function after LLM execution error fix")
                            raise HTTPException(status_code=500, detail={
                                "error": "reload_failed",
                                "message": "Function source was updated but failed to reload",
                                "original_error": error_msg
                            })
                    else:
                        # LLM fixing failed
                        logger.warning("LLM execution error fixing unsuccessful")
                        await _mark_function_error_llm_outcome(
                            project_id, function_id, attempted=True, successful=False
                        )
                        
                        raise HTTPException(status_code=500, detail={
                            "error": "execution_failed",
                            "message": error_msg,
                            "fix_error": "Automatic error fixing was unsuccessful"
                        })
                else:
                    # Second failure after LLM fix - give up (error already saved above)
                    logger.warning("Execution failed after LLM fixing", extra={
                        "error": error_msg,
                        "function_id": function_id
                    })
                    
                    raise HTTPException(
                        status_code=500,
                        detail={
                            "error": "execution_failed",
                            "message": error_msg,
                            "execution_time_ms": sandbox_result.execution_time_ms,
                            "fix_attempted": True
                        }
                    )
            else:
                # Sandbox reported success - check if stderr indicates a runtime error
                # (e.g. function caught exception and returned a result, but logged error to stderr)
                if (
                    ENABLE_EXECUTION_ERROR_LLM_FIX
                    and sandbox_result.stderr_output
                    and _stderr_indicates_runtime_error(sandbox_result.stderr_output)
                    and execution_attempt < max_execution_attempts - 1
                ):
                    # Treat as execution failure and try LLM fix using stderr as the error source
                    error_msg = (
                        "Runtime error detected in stderr (function may have caught exception and returned): "
                        + (sandbox_result.stderr_output[:2000] if sandbox_result.stderr_output else "")
                    )
                    if sandbox_result.stderr_output and len(sandbox_result.stderr_output) > 2000:
                        error_msg += "\n... [truncated]"
                    logger.warning(
                        f"Function {function_id} reported success but stderr contains runtime error; attempting LLM fix",
                        extra={
                            "function_id": function_id,
                            "stderr_preview": (sandbox_result.stderr_output or "")[:500],
                        },
                    )
                    params_to_log = validated_params.model_dump() if validated_params else params
                    await _save_function_error_log(
                        project_id,
                        function_id,
                        error_message=error_msg,
                        error_type="StderrRuntimeError",
                        retry_attempts=execution_attempt + 1,
                        params=params_to_log,
                        stderr_output=sandbox_result.stderr_output,
                        execution_time_ms=sandbox_result.execution_time_ms,
                        response_received=sandbox_result.result,
                    )
                    record = await backend_generator.function_repository.get_function(project_id, function_id)
                    if record:
                        data_source = record.get("metadata", {}).get("data_source")
                        params_to_pass = validated_params.model_dump() if validated_params else {}
                        if not params_to_pass and payload and payload.get("params"):
                            params_to_pass = payload.get("params", {})

                        # Prefer deterministic cursor fix over LLM for known sandbox await misuse
                        if _is_mongo_cursor_await_error(
                            "\n".join(
                                filter(
                                    None,
                                    [error_msg, sandbox_result.stderr_output or ""],
                                )
                            )
                        ):
                            det_fixed = _apply_mongo_cursor_await_fix(
                                record.get("source_code", "")
                            )
                            if det_fixed:
                                logger.info(
                                    "Applied deterministic Mongo cursor await fix for %s (stderr path)",
                                    function_id,
                                )
                                reload_success = await backend_generator.reload_single_function_and_update(
                                    project_id,
                                    function_id,
                                    record.get("models_source", ""),
                                    det_fixed,
                                )
                                if reload_success:
                                    entry = FunctionRegistry.get(project_id, function_id)
                                    if entry:
                                        await _mark_function_error_llm_outcome(
                                            project_id,
                                            function_id,
                                            attempted=True,
                                            successful=True,
                                        )
                                        execution_attempt += 1
                                        continue

                        fixed_code = await fix_execution_error_with_llm(
                            params=params_to_pass,
                            execution_error=error_msg,
                            error_type="StderrRuntimeError",
                            source_code=record.get("source_code", ""),
                            models_source=record.get("models_source", ""),
                            input_model_name=record.get("input_model_name", ""),
                            response_model_name=record.get("response_model_name", ""),
                            function_id=function_id,
                            data_source=data_source,
                            response_received=sandbox_result.result,
                            request_payload=payload,
                            stderr_output=sandbox_result.stderr_output,
                            project_id=project_id,
                        )
                        if fixed_code:
                            models_source_to_use = fixed_code.get("models_source", "") or record.get("models_source", "")
                            if not models_source_to_use or len(models_source_to_use.strip()) < 10:
                                models_source_to_use = record.get("models_source", "")
                            reload_success = await backend_generator.reload_single_function_and_update(
                                project_id, function_id, models_source_to_use, fixed_code["source_code"]
                            )
                            if reload_success:
                                entry = FunctionRegistry.get(project_id, function_id)
                                if entry:
                                    await _mark_function_error_llm_outcome(
                                        project_id, function_id, attempted=True, successful=True
                                    )
                                    execution_attempt += 1
                                    continue  # Retry with fixed function
                            await _mark_function_error_llm_outcome(
                                project_id, function_id, attempted=True, successful=False
                            )
                    # Fix not attempted or failed - continue with current result (same as before)
                break

        # Normalize response fields to match model structure
        normalized_result = backend_generator._normalize_response_fields(
            sandbox_result.result, entry.response_model
        )
        
        # Check if response contains an error field indicating logical failure
        # Even though execution succeeded (no exception), the function may have returned an error
        response_error = None
        if isinstance(normalized_result, dict):
            error_value = normalized_result.get("error")
            if error_value and isinstance(error_value, str) and error_value.strip():
                # Function returned an error - treat as failure for LLM fixing
                response_error = error_value.strip()
                logger.warning(
                    f"Function {function_id} returned error in response: {response_error}",
                    extra={
                        "function_id": function_id,
                        "error": response_error,
                        "response": normalized_result
                    }
                )

                params_to_log = validated_params.model_dump() if validated_params else params
                await _save_function_error_log(
                    project_id,
                    function_id,
                    error_message=response_error,
                    error_type="ResponseError",
                    retry_attempts=execution_attempt + 1,
                    params=params_to_log,
                    stderr_output=sandbox_result.stderr_output,
                    execution_time_ms=sandbox_result.execution_time_ms,
                    response_received=normalized_result,
                )
                
                # Try LLM fix for response errors (one attempt)
                if (
                    ENABLE_EXECUTION_ERROR_LLM_FIX
                    and execution_attempt < max_execution_attempts
                ):
                    logger.info("Function returned error in response, attempting LLM error fixing", extra={
                        "function_id": function_id,
                        "error": response_error,
                        "attempt": execution_attempt + 1
                    })
                    
                    # Get current function record for source code and data source
                    record = await backend_generator.function_repository.get_function(project_id, function_id)
                    if record:
                        # Get data source from metadata if available
                        data_source = record.get("metadata", {}).get("data_source")
                        
                        # Build error message for LLM (response error, not execution exception)
                        error_msg = f"Function returned error in response: {response_error}"

                        # Deterministic fix for known sandbox cursor await misuse.
                        # This block runs after the execution retry while-loop, so retry
                        # must be inline (cannot use continue).
                        det_response_fix_applied = False
                        if _is_mongo_cursor_await_error(
                            "\n".join(
                                filter(
                                    None,
                                    [response_error, sandbox_result.stderr_output or ""],
                                )
                            )
                        ):
                            det_fixed = _apply_mongo_cursor_await_fix(
                                record.get("source_code", "")
                            )
                            if det_fixed:
                                logger.info(
                                    "Applied deterministic Mongo cursor await fix for %s (response-error path)",
                                    function_id,
                                )
                                reload_success = await backend_generator.reload_single_function_and_update(
                                    project_id,
                                    function_id,
                                    record.get("models_source", ""),
                                    det_fixed,
                                )
                                if reload_success:
                                    entry = FunctionRegistry.get(project_id, function_id)
                                    if entry:
                                        await _mark_function_error_llm_outcome(
                                            project_id,
                                            function_id,
                                            attempted=True,
                                            successful=True,
                                        )
                                        execution_attempt += 1
                                        logger.info(
                                            "Retrying function execution after deterministic Mongo cursor fix (response-error path)"
                                        )
                                        sandbox_result = await function_worker_pool.execute(
                                            function_source=entry.source_code,
                                            function_name=function_id,
                                            params=validated_params.model_dump(),
                                            db_wrapper_config=db_wrapper_config,
                                            secure_http_config=secure_http_config,
                                            request_meta=request_meta,
                                        )
                                        if sandbox_result.success:
                                            normalized_result = backend_generator._normalize_response_fields(
                                                sandbox_result.result, entry.response_model
                                            )
                                            new_error = (
                                                normalized_result.get("error")
                                                if isinstance(normalized_result, dict)
                                                else None
                                            )
                                            if new_error and isinstance(new_error, str) and new_error.strip():
                                                logger.warning(
                                                    f"Function still returns error after deterministic fix: {new_error}"
                                                )
                                                response_error = new_error.strip()
                                            else:
                                                logger.info(
                                                    "Function error fixed by deterministic Mongo cursor fix, retry successful"
                                                )
                                                response_error = None
                                        else:
                                            logger.warning(
                                                "Retry execution failed after deterministic Mongo cursor fix"
                                            )
                                        det_response_fix_applied = True

                        if not det_response_fix_applied:
                            # If validated_params is empty but payload has params, use original params to help LLM fix the model
                            params_to_pass = validated_params.model_dump() if validated_params else {}
                            if not params_to_pass and payload and payload.get("params"):
                                # Params is empty but request has data - pass original params so LLM can fix the model
                                params_to_pass = payload.get("params", {})

                            # Try to fix execution error with LLM
                            fixed_code = await fix_execution_error_with_llm(
                                params=params_to_pass,
                                execution_error=error_msg,
                                error_type="ResponseError",
                                source_code=record.get("source_code", ""),
                                models_source=record.get("models_source", ""),
                                input_model_name=record.get("input_model_name", ""),
                                response_model_name=record.get("response_model_name", ""),
                                function_id=function_id,
                                data_source=data_source,
                                response_received=normalized_result,
                                request_payload=payload,
                                stderr_output=sandbox_result.stderr_output,
                                project_id=project_id,
                            )

                            if fixed_code:
                                # Update and reload the function
                                logger.info("Updating function with LLM-fixed source code after response error")

                                # Ensure we have valid models_source - fall back to existing if LLM version is invalid
                                models_source_to_use = fixed_code.get('models_source', '')
                                if not models_source_to_use or len(models_source_to_use.strip()) < 10:
                                    logger.warning("LLM models_source invalid or empty, using existing from DB")
                                    models_source_to_use = record.get("models_source", "")

                                reload_success = await backend_generator.reload_single_function_and_update(
                                    project_id,
                                    function_id,
                                    models_source_to_use,
                                    fixed_code['source_code']
                                )

                                if reload_success:
                                    # Get updated entry from registry
                                    entry = FunctionRegistry.get(project_id, function_id)
                                    if entry:
                                        # Retry execution with fixed function
                                        logger.info("Retrying function execution with fixed code after response error")
                                        execution_attempt += 1

                                        # Retry execution
                                        sandbox_result = await function_worker_pool.execute(
                                            function_source=entry.source_code,
                                            function_name=function_id,
                                            params=validated_params.model_dump(),
                                            db_wrapper_config=db_wrapper_config,
                                            secure_http_config=secure_http_config,
                                            request_meta=request_meta,
                                        )

                                        if sandbox_result.success:
                                            # Re-normalize the new result
                                            normalized_result = backend_generator._normalize_response_fields(
                                                sandbox_result.result, entry.response_model
                                            )

                                            # Check again for errors in the retry
                                            new_error = normalized_result.get("error") if isinstance(normalized_result, dict) else None
                                            if new_error and isinstance(new_error, str) and new_error.strip():
                                                logger.warning(f"Function still returns error after LLM fix: {new_error}")
                                                await _mark_function_error_llm_outcome(
                                                    project_id, function_id, attempted=True, successful=False
                                                )
                                                await _save_function_error_log(
                                                    project_id,
                                                    function_id,
                                                    error_message=new_error.strip(),
                                                    error_type="ResponseError",
                                                    retry_attempts=execution_attempt + 1,
                                                    params=validated_params.model_dump() if validated_params else params,
                                                    stderr_output=sandbox_result.stderr_output,
                                                    execution_time_ms=sandbox_result.execution_time_ms,
                                                    response_received=normalized_result,
                                                    llm_fix_attempted=True,
                                                    llm_fix_successful=False,
                                                )
                                                response_error = new_error
                                            else:
                                                # Success after fix
                                                logger.info("Function error fixed by LLM, retry successful")
                                                await _mark_function_error_llm_outcome(
                                                    project_id, function_id, attempted=True, successful=True
                                                )
                                                response_error = None
                                        else:
                                            logger.warning("Retry execution failed after LLM fix")
                                            await _mark_function_error_llm_outcome(
                                                project_id, function_id, attempted=True, successful=False
                                            )
                                            retry_error = sandbox_result.error or "Retry execution failed after LLM fix"
                                            await _save_function_error_log(
                                                project_id,
                                                function_id,
                                                error_message=retry_error,
                                                error_type=sandbox_result.error_type or "ExecutionError",
                                                retry_attempts=execution_attempt + 1,
                                                params=validated_params.model_dump() if validated_params else params,
                                                traceback=sandbox_result.traceback,
                                                stderr_output=sandbox_result.stderr_output,
                                                execution_time_ms=sandbox_result.execution_time_ms,
                                                llm_fix_attempted=True,
                                                llm_fix_successful=False,
                                            )
                                    else:
                                        logger.error("Failed to get updated entry after reload")
                                        # Keep original error
                                else:
                                    logger.error("Failed to reload function after LLM fix")
                                    # Keep original error
                            else:
                                logger.warning("LLM fixing failed for response error")
                                await _mark_function_error_llm_outcome(
                                    project_id, function_id, attempted=True, successful=False
                                )

                                # Keep original error
        
        # Validate response with Pydantic
        try:
            validated_response = entry.response_model(**normalized_result)
            
            # Log success or error
            if response_error:
                logger.warning("Function executed but returned error in response", extra={
                    "function_id": function_id,
                    "error": response_error
                })

            else:
                logger.info("Dynamic function executed successfully", extra={
                    "project_id": project_id,
                    "function_id": function_id
                })

            try:
                observe_dynamic_function_execution(
                    request_meta=request_meta,
                    function_id=function_id,
                    success=not bool(response_error),
                    latency_ms=sandbox_result.execution_time_ms if sandbox_result else None,
                    error=response_error,
                    project_id=project_id,
                )
            except Exception:
                pass

            return {
                **validated_response.model_dump(),
                "_meta": {
                    "execution_time_ms": round(sandbox_result.execution_time_ms, 2) if sandbox_result else 0,
                }
            }
        except ValidationError as ve:
            logger.warning("Response validation failed", extra={
                "errors": ve.errors(),
                "function_id": function_id,
                "original_result": sandbox_result.result if sandbox_result else None,
                "normalized_result": normalized_result
            })
            # Store error logs in database
            await _save_function_error_log(
                project_id,
                function_id,
                error_message=f"Response validation failed: {str(ve)}",
                error_type="ResponseValidationError",
                retry_attempts=execution_attempt,
                params=validated_params.model_dump() if validated_params else params,
                stderr_output=sandbox_result.stderr_output if sandbox_result else None,
                execution_time_ms=sandbox_result.execution_time_ms if sandbox_result else 0,
                validation_errors=ve.errors(),
                response_received=normalized_result,
            )
            
            raise HTTPException(status_code=500, detail={
                "error": "response_validation_error",
                "details": ve.errors(),
                "execution_time_ms": sandbox_result.execution_time_ms if sandbox_result else 0,
            })
    except PermissionError as pe:
        raise HTTPException(status_code=403, detail={"error": "permission_error", "message": str(pe)})
    except Exception as exc:
        traceback.print_exc()
        # Log the FULL error
        logger.error(
            f"[{request_id}] Request failed: {type(exc).__name__}: {str(exc)}",
            exc_info=True,
            extra={
                "project_id": project_id,
                "function_id": payload.get("function_id"),
            }
        )
        raise HTTPException(status_code=500, detail={"error": "execution_failed", "message": str(exc)})
