@app.get("/aiqod-agent/agent/admin/functions/{project_id}")
async def list_project_functions(project_id: str):
    """List all functions registered for a project."""
    try:
        function_ids = FunctionRegistry.list_functions(project_id)
        functions = []
        for func_id in function_ids:
            entry = FunctionRegistry.get(project_id, func_id)
            if entry:
                functions.append({
                    "function_id": func_id,
                    "type": entry.type,
                    "description": entry.description,
                    "input_model": entry.input_model.__name__ if entry.input_model else None,
                    "response_model": entry.response_model.__name__ if entry.response_model else None,
                })

        return {
            "success": True,
            "project_id": project_id,
            "functions": functions,
            "count": len(functions)
        }
    except Exception as e:
        print(f"Error listing functions: {str(e)}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={
            "success": False,
            "error": str(e)
        })


