@app.post("/aiqod-agent/agent/admin/capabilities/rebuild")
async def rebuild_capabilities_endpoint(request: Request):
    """
    Full rebuild of capability_repository from tools, screen_generations, and Workflow_details.
    Body: optional { "orgId": "...", "subscriberId": "...", "userId": "..." }. If omitted, screens/agents are not tenant-filtered (all synced).
    """
    try:
        body = await request.json() if request.headers.get("content-type", "").startswith("application/json") else {}
        org_id = body.get("orgId") or body.get("org_id")
        subscriber_id = body.get("subscriberId") or body.get("subscriber_id")
        user_id = body.get("userId") or body.get("user_id")
        counts = await rebuild_capability_repository(
            capability_repository,
            get_available_tools,
            config.get("tools_path", ""),
            screen_repository,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )
        return {
            "success": True,
            "message": "Capability repository rebuilt",
            "counts": counts,
        }
    except Exception as e:
        logger.exception("Capability rebuild failed: %s", e)
        raise HTTPException(status_code=500, detail={"success": False, "error": str(e)})


@app.post("/aiqod-agent/agent/admin/capabilities/migrate-tenant")
async def migrate_capability_tenant_endpoint(request: Request):
    """
    One-time migration: re-tag all capability_repository documents that have
    orgId=null / subscriberId=null with the platform tenant from config.json.

    Body (optional JSON):
        { "dryRun": true }   → counts matched rows but writes nothing (default: false)

    Returns:
        { "matched": N, "modified": N, "dryRun": bool }
    """
    try:
        body: Dict[str, Any] = {}
        if request.headers.get("content-type", "").startswith("application/json"):
            body = await request.json()
        dry_run: bool = bool(body.get("dryRun", False))

        platform_tenant = _get_platform_tenant()
        plat_org = platform_tenant.get("orgId")
        plat_sub = platform_tenant.get("subscriberId")
        if not plat_org or not plat_sub:
            raise HTTPException(
                status_code=500,
                detail="aiqod_orgId / aiqod_subscriberId not configured in config.json.",
            )

        from bson import ObjectId as _ObjId

        def _to_oid(v: str):
            try:
                return _ObjId(v)
            except Exception:
                return None

        org_obj = _to_oid(plat_org)
        sub_obj = _to_oid(plat_sub)
        if org_obj is None or sub_obj is None:
            raise HTTPException(
                status_code=500,
                detail="aiqod_orgId / aiqod_subscriberId must be valid 24-char hex ObjectId strings.",
            )

        col = Database.get_collection("capability_repository")
        null_filter: Dict[str, Any] = {"orgId": None, "subscriberId": None}
        matched = await col.count_documents(null_filter)

        if dry_run or matched == 0:
            return {"matched": matched, "modified": 0, "dryRun": dry_run}

        result = await col.update_many(
            null_filter,
            {"$set": {"orgId": org_obj, "subscriberId": sub_obj}},
        )
        logger.info(
            "[migrate-tenant] capability_repository: matched=%d modified=%d  "
            "orgId=%s subscriberId=%s",
            result.matched_count, result.modified_count, plat_org, plat_sub,
        )
        return {
            "matched": result.matched_count,
            "modified": result.modified_count,
            "dryRun": False,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("Capability tenant migration failed: %s", e)
        raise HTTPException(status_code=500, detail={"success": False, "error": str(e)})


@app.post("/aiqod-agent/agent/admin/update-function")
async def update_function_endpoint(request: UpdateFunctionRequest):
    """
    Update a backend function with new source code and optionally new models source.
    This endpoint saves the updated function to the database and loads it into the runtime cache.
    
    Args:
        request: UpdateFunctionRequest containing:
            - project_id: Project identifier
            - function_id: Function identifier
            - source_code: Updated function source code (required)
            - models_source: Updated models source code (optional, will use existing if not provided)
    
    Returns:
        Success response with updated function details
    """
    try:
        # Validate required fields
        if not request.source_code or len(request.source_code.strip()) == 0:
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": "source_code is required and cannot be empty"
                }
            )
        
        # Call reload_single_function_and_update which handles:
        # - Validating models_source (uses existing from DB if invalid/not provided)
        # - Recompiling models
        # - Compiling function
        # - Saving to database
        # - Loading into runtime cache
        success = await backend_generator.reload_single_function_and_update(
            project_id=request.project_id,
            function_id=request.function_id,
            models_source=request.models_source or "",
            source_code=request.source_code
        )
        
        if success:
            return {
                "success": True,
                "project_id": request.project_id,
                "function_id": request.function_id,
                "message": f"Function {request.function_id} updated and reloaded successfully",
                "saved_to_db": True,
                "loaded_to_cache": True
            }
        else:
            raise HTTPException(
                status_code=404,
                detail={
                    "success": False,
                    "project_id": request.project_id,
                    "function_id": request.function_id,
                    "error": f"Function {request.function_id} not found or failed to update. Check that the function exists and models can be compiled."
                }
            )
    except HTTPException:
        # Re-raise HTTP exceptions as-is
        raise
    except Exception as e:
        print(f"Error updating function: {str(e)}")
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail={
                "success": False,
                "project_id": request.project_id,
                "function_id": request.function_id,
                "error": str(e)
            }
        )


