@app.get("/aiqod-agent/agent/screen-functions/{project_id}/{screen_id}")
async def get_screen_backend_functions(project_id: str, screen_id: str):
    """
    Get all backend functions created for a specific screen.
    Returns complete function details including source code, models, and metadata.
    
    Args:
        project_id: Project identifier
        screen_id: Screen identifier
    
    Returns:
        List of backend functions with full details:
        - function_id
        - type
        - description
        - source_code
        - models_source
        - input_model_name
        - response_model_name
        - input_model (schema)
        - response_model (schema)
        - metadata
        - created_at
        - updated_at
    """
    try:
        # Get screen state to extract backend metadata
        state = await screen_repository.get_screen_state(project_id, screen_id)
        
        if not state:
            raise HTTPException(
                status_code=404,
                detail={
                    "success": False,
                    "error": f"Screen {screen_id} not found for project {project_id}"
                }
            )
        
        # Extract backend metadata
        backend_metadata = state.get("backend", {})
        functions_list = backend_metadata.get("functions", [])
        
        if not functions_list:
            return {
                "success": True,
                "project_id": project_id,
                "screen_id": screen_id,
                "functions": [],
                "count": 0,
                "message": "No backend functions found for this screen"
            }
        
        # Get full function details from database
        functions_with_details = []
        for func_info in functions_list:
            function_id = func_info.get("function_id")
            if not function_id:
                continue
            
            # Get full function record from database
            function_record = await backend_generator.function_repository.get_function(
                project_id, function_id
            )
            
            if function_record:
                # Get runtime entry for model schemas if available
                runtime_entry = FunctionRegistry.get(project_id, function_id)
                
                # Build input and response model schemas
                input_model_schema = None
                response_model_schema = None
                
                if runtime_entry:
                    try:
                        if runtime_entry.input_model:
                            # Try Pydantic v2 method first, fallback to v1
                            if hasattr(runtime_entry.input_model, 'model_json_schema'):
                                input_model_schema = runtime_entry.input_model.model_json_schema()
                            elif hasattr(runtime_entry.input_model, 'schema'):
                                input_model_schema = runtime_entry.input_model.schema()
                        if runtime_entry.response_model:
                            # Try Pydantic v2 method first, fallback to v1
                            if hasattr(runtime_entry.response_model, 'model_json_schema'):
                                response_model_schema = runtime_entry.response_model.model_json_schema()
                            elif hasattr(runtime_entry.response_model, 'schema'):
                                response_model_schema = runtime_entry.response_model.schema()
                    except Exception as schema_error:
                        logger.warning(f"Failed to get schema for {function_id}: {schema_error}")
                
                # Compile full function details
                function_detail = {
                    "function_id": function_id,
                    "type": function_record.get("type", func_info.get("type")),
                    "description": function_record.get("description", func_info.get("description")),
                    "source_code": function_record.get("source_code"),
                    "models_source": function_record.get("models_source"),
                    "input_model_name": function_record.get("input_model_name", func_info.get("input_model")),
                    "response_model_name": function_record.get("response_model_name", func_info.get("response_model")),
                    "input_model_schema": input_model_schema,
                    "response_model_schema": response_model_schema,
                    "metadata": function_record.get("metadata", {}),
                    "created_at": function_record.get("created_at"),
                    "updated_at": function_record.get("updated_at"),
                    "version": function_record.get("version"),
                    # Include error logs for debugging
                    "error_logs": function_record.get("error_logs", []),  # Full history of errors
                    "last_error": function_record.get("last_error"),  # Latest error for quick access
                }
                functions_with_details.append(function_detail)
            else:
                # Function not found in DB, but listed in screen metadata
                # Return basic info from screen metadata
                logger.warning(f"Function {function_id} listed in screen metadata but not found in database")
                function_detail = {
                    "function_id": function_id,
                    "type": func_info.get("type"),
                    "description": func_info.get("description"),
                    "input_model_name": func_info.get("input_model"),
                    "response_model_name": func_info.get("response_model"),
                    "source_code": None,
                    "models_source": None,
                    "metadata": {},
                    "warning": "Function not found in database"
                }
                functions_with_details.append(function_detail)
        
        return {
            "success": True,
            "project_id": project_id,
            "screen_id": screen_id,
            "functions": functions_with_details,
            "count": len(functions_with_details),
            "backend_base_path": backend_metadata.get("base_path")
        }
        
    except HTTPException:
        raise
    except Exception as e:
        print(f"Error getting screen backend functions: {str(e)}")
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail={
                "success": False,
                "project_id": project_id,
                "screen_id": screen_id,
                "error": str(e)
            }
        )


