class UpdateScreenMetadataRequest(BaseModel):
    """Patch whitelisted fields on the current (or specified) screen_generations version."""

    model_config = ConfigDict(extra="forbid")

    project_id: str
    screen_id: str
    version: Optional[str] = Field(
        default=None,
        description="screen_generations version id; omit to use screens.current_version or latest snapshot",
    )
    screen_name: Optional[str] = None
    description: Optional[str] = None
    tags: Optional[List[str]] = None
    screen_type: Optional[str] = None
    permissions: Optional[Dict[str, Any]] = None
    theme_preferences: Optional[Dict[str, Any]] = None

    @model_validator(mode="after")
    def at_least_one_metadata_field(self):
        if all(
            v is None
            for v in (
                self.screen_name,
                self.description,
                self.tags,
                self.screen_type,
                self.permissions,
                self.theme_preferences,
            )
        ):
            raise ValueError(
                "At least one of: screen_name, description, tags, screen_type, permissions, theme_preferences"
            )
        return self


