class ToolParameter(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    
    name: str
    param_type: ParameterType = Field(default=ParameterType.ANY, alias='type')
    description: str = ""
    required: bool = True
    default_value: Optional[Any] = None
    inputVarDesc: str = ""
    
    @field_validator('param_type', mode='before')
    @classmethod
    def validate_param_type(cls, v):
        """Convert string to ParameterType enum if needed"""
        if isinstance(v, str):
            try:
                # Try to match by value
                for param_type in ParameterType:
                    if param_type.value == v.lower():
                        return param_type
                # If no match, default to ANY
                return ParameterType.ANY
            except (ValueError, AttributeError):
                return ParameterType.ANY
        elif isinstance(v, ParameterType):
            return v
        return ParameterType.ANY


