@app.post("/aiqod-agent/agent/update-screen")
async def update_screen(request: UpdateScreenRequest):
    """
    Legacy endpoint: Update an existing screen's IR schema based on user modifications.
    (Kept for backward compatibility)
    """
    try:
        data = request.model_dump()
        
        prompt = data.get('prompt')
        chat_history = data.get('chat_history')
        screen_id = data.get('screen_id')
        project_id = data.get('project_id')
        current_ir_schema = data.get('current_ir_schema')
        theme_preferences = data.get('theme_preferences')
        org_id = data.get('orgId') or data.get('org_id')
        subscriber_id = data.get('subscriberId') or data.get('subscriber_id')
        user_id = data.get('userId') or data.get('user_id')
        
        # Generate version timestamp for tracking
        version = datetime.utcnow().strftime("%Y%m%d%H%M%S")

        print("\n" + "="*60)
        print("UPDATE SCREEN REQUEST")
        print("="*60)
        print(f"Screen ID: {screen_id}")
        print(f"Modification: {prompt}")
        print(f"Chat history messages: {len(chat_history) if chat_history else 0}")

        # Step 1: Update IR schema using AI processor
        # Parse workflow I/O contract from prompt (for downstream screens)
        try:
            from services.ai_processor import parse_workflow_io_contract_from_prompt
            workflow_io_contract = parse_workflow_io_contract_from_prompt(prompt)
            if workflow_io_contract:
                if workflow_io_contract.get("inputParameters"):
                    current_ir_schema["inputParameters"] = workflow_io_contract["inputParameters"]
                    logger.info(f"[update_screen] Pre-updated IR inputParameters from workflow contract: {[p.get('name') for p in workflow_io_contract['inputParameters']]}")
                if workflow_io_contract.get("outputParameters"):
                    current_ir_schema["outputParameters"] = workflow_io_contract["outputParameters"]
                    logger.info(f"[update_screen] Pre-updated IR outputParameters from workflow contract: {[p.get('name') for p in workflow_io_contract['outputParameters']]}")
        except Exception as _e:
            logger.debug(f"[update_screen] Could not parse workflow I/O contract: {_e}")

        updated_ir_schema, changes_summary = await ai_processor.update_screen_ir(
            prompt=prompt,
            current_ir_schema=current_ir_schema,
            chat_history=chat_history,
            theme_preferences=theme_preferences,
            project_id=project_id,
            screen_id=screen_id,
            version=version,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id
        )

        print(f"Changes made: {changes_summary.get('description', 'No description')}")

        if not updated_ir_schema:
            raise Exception("Failed to generate updated IR schema")

        components = updated_ir_schema.get("components", []) if isinstance(updated_ir_schema, dict) else []

        backend_result = {"base_path": None, "functions": [], "models_source": None}
        try:
            try:
                from services.persistence_link import (
                    extract_persistence_links_from_text,
                    stamp_persistence_links_on_datasources,
                )
                _persist_links = extract_persistence_links_from_text(prompt or "")
                stamp_persistence_links_on_datasources(
                    updated_ir_schema.get("dataSources") or []
                    if isinstance(updated_ir_schema, dict)
                    else [],
                    _persist_links,
                )
            except Exception:
                pass
            backend_result = await backend_generator.generate_backend(
                project_id,
                updated_ir_schema.get("dataModels", {}) if isinstance(updated_ir_schema, dict) else {},
                updated_ir_schema.get("dataSources", []) if isinstance(updated_ir_schema, dict) else [],
                screen_id=screen_id,
                version=version
            )
        except Exception as backend_error:
            print(f"[BackendGenerator] Failed: {backend_error}")

        print("IR Schema updated successfully")
        print("="*60 + "\n")

        return {
            "success": True,
            "screen_id": screen_id,
            "project_id": project_id,
            "updated_ir_schema": updated_ir_schema,
            "components": components,
            "changes_made": changes_summary,
            "backend": backend_result,
            "api_base_path": backend_result.get("base_path"),
            "error": None
        }

    except Exception as e:
        print(f"Error in update_screen: {str(e)}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={
            "success": False,
            "screen_id": request.screen_id if request else None,
            "project_id": request.project_id if request else None,
            "updated_ir_schema": None,
            "components": None,
            "changes_made": None,
            "error": str(e)
        })


