def _ensure_backend_metadata(backend_metadata: Optional[Dict[str, Any]], project_id: str) -> Dict[str, Any]:
    """Ensure backend_metadata always has a base_path, constructing fallback if needed."""
    if not backend_metadata:
        backend_metadata = {}
    
    if not backend_metadata.get("base_path"):
        fallback_path = f"/aiqod-agent/agent/dynamic/execute/{project_id}"
        backend_metadata["base_path"] = fallback_path
        logger.warning("Backend base_path was missing, using fallback: %s", fallback_path)
    
    # Ensure project_id is set
    if "project_id" not in backend_metadata:
        backend_metadata["project_id"] = project_id
    
    return backend_metadata

def _extract_actual_output_fields_from_source(source_code: str) -> Optional[Dict[str, Any]]:
    """
    Parse a generated backend function's Python source to determine the ACTUAL
    field names it outputs without running the code.

    Handles two common patterns produced by the backend generator:

    Pattern A — $project literal array → $unwind → $replaceRoot:
        pipeline = [
            {'$group': ...},
            {'$project': {'_id': 0, 'data': [{'x_field': '...', 'y_field': '$col'}, ...]}},
            {'$unwind': '$data'},
            {'$replaceRoot': {'newRoot': '$data'}},
        ]
        → output fields = keys of first array element (e.g. ['aging_bucket', 'total_amount'])

    Pattern B — standard $project rename:
        {'$project': {'_id': 0, 'x_key': '$_id', 'y_key': '$count'}}
        → output fields = non-zero projection keys (e.g. ['x_key', 'y_key'])

    Returns:
        {'x_field': '...', 'y_field': '...', 'all_fields': [...]}
        or None if parsing fails.
    """
    import re as _re
    import ast as _ast

    # ── Locate the pipeline literal in the source code ─────────────────────────
    # Use bracket-counting to correctly handle nested arrays/dicts inside the
    # pipeline literal.  The old non-greedy regex (\[[\s\S]*?\]) fails on
    # pipelines that contain nested lists (e.g. Pattern-A $project arrays) because
    # it stops at the first ] it encounters rather than the matching outer ].
    def _find_pipeline_literal(src: str) -> Optional[str]:
        """Return the full '[...]' string of the 'pipeline = [...]' assignment."""
        m = _re.search(r'pipeline\s*=\s*\[', src)
        if not m:
            return None
        start = m.end() - 1  # index of the opening '['
        depth = 0
        in_str: Optional[str] = None  # current string delimiter ('"' or "'")
        escape_next = False
        i = start
        while i < len(src):
            ch = src[i]
            if escape_next:
                escape_next = False
            elif in_str:
                if ch == '\\':
                    escape_next = True
                elif ch == in_str:
                    in_str = None
            else:
                if ch in ('"', "'"):
                    in_str = ch
                elif ch == '[':
                    depth += 1
                elif ch == ']':
                    depth -= 1
                    if depth == 0:
                        return src[start:i + 1]
            i += 1
        return None  # unmatched bracket (shouldn't happen in valid source)

    pipeline_str = _find_pipeline_literal(source_code)
    if not pipeline_str:
        return None

    try:
        pipeline = _ast.literal_eval(pipeline_str)
    except Exception:
        return None

    if not isinstance(pipeline, list):
        return None

    # ── Pattern A: $replaceRoot → find preceding $project with literal array ───
    for i, stage in enumerate(pipeline):
        if not (isinstance(stage, dict) and "$replaceRoot" in stage):
            continue
        rr = stage["$replaceRoot"]
        new_root = rr.get("newRoot", "") if isinstance(rr, dict) else ""
        if not (isinstance(new_root, str) and new_root.startswith("$")):
            continue
        root_field = new_root[1:]
        for prev in reversed(pipeline[:i]):
            if not (isinstance(prev, dict) and "$project" in prev):
                continue
            proj = prev["$project"]
            if not (isinstance(proj, dict) and root_field in proj):
                break
            array_val = proj[root_field]
            if not (isinstance(array_val, list) and array_val):
                break
            first_elem = array_val[0]
            if not isinstance(first_elem, dict):
                break
            keys = list(first_elem.keys())
            return {
                "all_fields": keys,
                "x_field": keys[0] if len(keys) >= 1 else None,
                "y_field": keys[1] if len(keys) >= 2 else None,
            }

    # ── Pattern B: last $project stage with simple renames ────────────────────
    last_project = None
    for stage in reversed(pipeline):
        if isinstance(stage, dict) and "$project" in stage:
            last_project = stage["$project"]
            break

    if last_project and isinstance(last_project, dict):
        fields = [
            k for k, v in last_project.items()
            if k != "_id" and v not in (0, False, None)
        ]
        if fields:
            return {
                "all_fields": fields,
                "x_field": fields[0],
                "y_field": fields[1] if len(fields) >= 2 else None,
            }

    return None


def _read_angular_chart_widget_fields(
    workspace_dir: str,
    function_id: str,
) -> tuple[Optional[str], Optional[str]]:
    """
    Scan the Angular workspace HTML files and return the CURRENT xfield and yfield
    attribute values of the <app-chart-widget> that references `function_id`.

    Returns (current_xfield, current_yfield) or (None, None) if not found.
    """
    import re as _re
    from pathlib import Path as _Path

    workspace_path = _Path(workspace_dir)
    exclude_dirs = {"node_modules", "dist", ".angular", ".git", "out-tsc"}

    for html_file in workspace_path.rglob("*.html"):
        if any(ex in html_file.parts for ex in exclude_dirs):
            continue
        try:
            content = html_file.read_text(encoding="utf-8")
        except Exception:
            continue

        if function_id.lower() not in content.lower():
            continue

        # Find all <app-chart-widget ...> tags
        for tag_match in _re.finditer(r'<app-chart-widget\b[^>]*>', content, flags=_re.DOTALL | _re.IGNORECASE):
            tag_body = tag_match.group(0)
            if function_id.lower() not in tag_body.lower():
                continue
            x_m = _re.search(r'(?i)xfield\s*=\s*["\']([^"\']*)["\']', tag_body)
            y_m = _re.search(r'(?i)yfield\s*=\s*["\']([^"\']*)["\']', tag_body)
            return (
                x_m.group(1) if x_m else None,
                y_m.group(1) if y_m else None,
            )

    return None, None


def _patch_angular_chart_widget_in_workspace(
    workspace_dir: str,
    function_id: str,
    correct_x_field: Optional[str],
    correct_y_field: Optional[str],
) -> list[str]:
    """
    Walk the Angular workspace HTML files and surgically patch any
    <app-chart-widget> that references `function_id` with mismatched
    xfield / yfield attributes.

    Returns a list of file paths that were patched.
    """
    import re as _re
    from pathlib import Path as _Path

    patched: list[str] = []
    workspace_path = _Path(workspace_dir)
    exclude_dirs = {"node_modules", "dist", ".angular", ".git", "out-tsc"}

    for html_file in workspace_path.rglob("*.html"):
        if any(ex in html_file.parts for ex in exclude_dirs):
            continue
        try:
            content = html_file.read_text(encoding="utf-8")
        except Exception:
            continue

        # Only process files that reference this function
        if function_id.lower() not in content.lower():
            continue

        new_content = content

        # Patch yfield attribute when it doesn't match the correct value
        if correct_y_field:
            # Replace yfield="anything" inside a tag that has functionid="function_id"
            # Strategy: use a two-pass approach
            # Pass 1: find the tag block(s) containing this functionid
            # Pass 2: replace yfield inside those blocks only

            def _patch_tag(m: "_re.Match") -> str:
                tag_body = m.group(0)
                if function_id.lower() not in tag_body.lower():
                    return tag_body
                # Replace yfield="..."  (case-insensitive attribute name)
                tag_body = _re.sub(
                    r'(?i)(yfield\s*=\s*["\'])([^"\']*?)(["\'])',
                    lambda mm: mm.group(1) + correct_y_field + mm.group(3),
                    tag_body,
                )
                return tag_body

            # Match <app-chart-widget ... > (possibly multiline)
            new_content = _re.sub(
                r'<app-chart-widget\b[^>]*>',
                _patch_tag,
                new_content,
                flags=_re.DOTALL | _re.IGNORECASE,
            )

        # Patch xfield attribute when it doesn't match the correct value
        if correct_x_field:
            def _patch_tag_x(m: "_re.Match") -> str:
                tag_body = m.group(0)
                if function_id.lower() not in tag_body.lower():
                    return tag_body
                tag_body = _re.sub(
                    r'(?i)(xfield\s*=\s*["\'])([^"\']*?)(["\'])',
                    lambda mm: mm.group(1) + correct_x_field + mm.group(3),
                    tag_body,
                )
                return tag_body

            new_content = _re.sub(
                r'<app-chart-widget\b[^>]*>',
                _patch_tag_x,
                new_content,
                flags=_re.DOTALL | _re.IGNORECASE,
            )

        if new_content != content:
            try:
                html_file.write_text(new_content, encoding="utf-8")
                patched.append(str(html_file))
            except Exception:
                pass

    return patched


def _restore_non_targeted_data_sources(
    original_ir: Dict[str, Any],
    updated_ir: Dict[str, Any],
    target_ds_id: str,
) -> Dict[str, Any]:
    """
    After the LLM updates the IR for a targeted data-issue fix, revert every
    dataSource whose id != target_ds_id back to the original version.

    This prevents collateral backend-regeneration of all other reports when the
    user only asked to fix one specific widget.
    """
    import copy as _copy
    merged = _copy.deepcopy(updated_ir)
    original_by_id = {
        ds.get("id"): ds
        for ds in (original_ir.get("dataSources") or [])
        if ds.get("id")
    }
    restored = []
    for ds in (updated_ir.get("dataSources") or []):
        ds_id = ds.get("id")
        if ds_id and ds_id != target_ds_id and ds_id in original_by_id:
            # Revert to original so the backend diff sees no change for this DS
            restored.append(_copy.deepcopy(original_by_id[ds_id]))
        else:
            restored.append(ds)
    merged["dataSources"] = restored
    return merged


def _build_diagnostic_context_for_data_issue(
    prompt: str,
    current_ir_schema: Dict[str, Any],
    backend_metadata: Dict[str, Any],
) -> tuple[Optional[str], Optional[str]]:
    """
    For prompts that mention a specific widget having blank / missing data, extract
    the relevant backend function source_code and IR dataSource config and return:
      - A self-contained diagnostic block string for the LLM to fix FE/BE mismatches.
      - The matched dataSource id (so the caller can scope the IR change to that DS only).

    Returns (None, None) when the prompt does not appear to be a data-issue report.
    """
    data_issue_keywords = [
        "data is not coming", "data not coming", "no data", "blank", "empty",
        "not showing data", "not loading", "not displaying data", "chart is blank",
        "report is blank", "widget is blank", "data not found", "no results",
        "showing nothing", "data is missing", "missing data", "data is empty",
        "no chart data", "chart not showing", "graph is blank", "graph not showing",
        "table is empty", "kpi not showing", "value not showing",
    ]
    prompt_lower = prompt.lower()
    is_data_issue = any(kw in prompt_lower for kw in data_issue_keywords)
    if not is_data_issue:
        return None, None

    # ── Extract the mentioned widget name ──────────────────────────────────────
    # Strategy: everything BEFORE the first data-issue keyword, stripping
    # trailing filler words ("in this report", "chart", etc.)
    import re as _re
    mentioned_name: Optional[str] = None
    for kw in sorted(data_issue_keywords, key=len, reverse=True):
        idx = prompt_lower.find(kw)
        if idx > 0:
            prefix = prompt[:idx].strip()
            prefix = _re.sub(
                r'\s+(in this report|in the report|in this|in the|for the|for this'
                r'|chart|report|widget|graph|table|kpi|card)$',
                "",
                prefix,
                flags=_re.IGNORECASE,
            ).strip()
            if prefix:
                mentioned_name = prefix
                break

    if not mentioned_name:
        return None, None

    # ── Find the matching dataSource in the IR schema ──────────────────────────
    data_sources = current_ir_schema.get("dataSources") or []
    mentioned_lower = mentioned_name.lower()

    def _name_score(ds: Dict[str, Any]) -> int:
        """Return a similarity score (higher = better match).

        Checks multiple name fields including nested chartMeta.title and
        reportName so that dashboard dataSources (which store the human-readable
        title inside chartMeta, not at the top level) are matched correctly.
        """
        chart_meta = ds.get("chartMeta") or {}
        candidates = [
            ds.get("name") or "",
            ds.get("reportName") or "",          # agentic dashboard DSes use reportName
            ds.get("title") or "",               # some DSes have top-level title
            chart_meta.get("title") or "",       # most dashboard DSes store title here
            ds.get("description") or "",
            ds.get("functionId") or "",          # e.g. "report_2_query"
            ds.get("id") or "",
        ]
        # De-duplicate and remove empties
        seen: set[str] = set()
        unique_candidates = []
        for c in candidates:
            if c and c not in seen:
                seen.add(c)
                unique_candidates.append(c)

        m_words = set(mentioned_lower.split())
        best = 0
        for c in unique_candidates:
            c_lower = c.lower()
            if mentioned_lower == c_lower:
                return 3                         # exact match — stop immediately
            if mentioned_lower in c_lower or c_lower in mentioned_lower:
                best = max(best, 2)
                continue
            # Word-level overlap (need majority of mention words to match)
            c_words = set(c_lower.split())
            overlap = m_words & c_words
            if overlap and len(overlap) >= max(1, len(m_words) // 2):
                best = max(best, 1)
        return best

    scored = [(ds, _name_score(ds)) for ds in data_sources]
    scored.sort(key=lambda x: x[1], reverse=True)
    matching_ds = scored[0][0] if scored and scored[0][1] > 0 else None

    if not matching_ds:
        return None, None

    ds_id = matching_ds.get("id") or ""

    # ── Find the matching backend function source_code ─────────────────────────
    functions = (backend_metadata or {}).get("functions") or []
    matching_func: Optional[Dict[str, Any]] = None
    for fn in functions:
        fn_id = fn.get("id") or fn.get("function_id") or ""
        if fn_id and (fn_id == ds_id or fn_id in ds_id or ds_id in fn_id):
            matching_func = fn
            break

    # ── Build the diagnostic block ─────────────────────────────────────────────
    chart_meta = matching_ds.get("chartMeta") or {}
    x_field    = chart_meta.get("xField", "N/A")
    y_field    = chart_meta.get("yField", "N/A")
    y_fields   = chart_meta.get("yFields") or []
    aggregation = matching_ds.get("aggregationPipeline") or []
    required_fields = matching_ds.get("requiredFields") or []
    report_type = matching_ds.get("type") or matching_ds.get("reportType") or "unknown"

    lines = [
        "",
        "=== AUTO-DIAGNOSTIC: DATA ISSUE DETECTED ===",
        f"User complained about blank/missing data in widget: \"{mentioned_name}\"",
        f"Matched dataSource → id='{ds_id}', type='{report_type}'",
        "",
        "IR schema currently expects these fields from this dataSource:",
        f"  chartMeta.xField  = '{x_field}'",
        f"  chartMeta.yField  = '{y_field}'" + (f"  (yFields = {y_fields})" if y_fields else ""),
        f"  requiredFields    = {required_fields}",
    ]

    if aggregation:
        lines.append(f"  aggregationPipeline = {json.dumps(aggregation)}")

    if matching_func and matching_func.get("source_code"):
        code = matching_func["source_code"]
        if len(code) > 4000:
            code = code[:4000] + "\n# ... [truncated for brevity]"
        lines += [
            "",
            f"Backend function source code (id='{ds_id}'):",
            "```python",
            code,
            "```",
            "",
            "DIAGNOSIS INSTRUCTIONS:",
            "  1. Read the backend function above carefully.",
            "     Look at the aggregation pipeline's final stages ($project, $replaceRoot, $unwind)",
            "     and any Python-level reshaping to determine the ACTUAL field names returned",
            "     in each data item (e.g. 'total_amount', 'aging_bucket').",
            "  2. Compare those actual output fields with the IR schema's chartMeta.xField",
            "     and chartMeta.yField above.",
            "  3. If there is a mismatch (e.g. yField='current' but backend outputs 'total_amount'),",
            "     fix it by updating ONLY this dataSource's chartMeta inside the IR schema:",
            "       - Set chartMeta.yField to the actual field name the backend returns.",
            "       - Set chartMeta.xField to the actual x-axis field name the backend returns.",
            "     OR, if the pipeline itself is broken, also update the aggregationPipeline",
            "     so the backend regenerates with the correct output fields.",
            "  4. Fix ONLY this specific dataSource (id='{}').".format(ds_id),
            "     Do NOT modify any other dataSources, components, or IR keys.",
            "  5. After the fix the chart MUST receive items where item[xField] and item[yField]",
            "     both resolve to real values.",
        ]
    else:
        lines += [
            "",
            "No backend function source code available for this dataSource.",
            "Check the aggregationPipeline above and fix chartMeta.xField/yField if they",
            "do not match the pipeline's final $project output fields.",
            "Fix ONLY this dataSource (id='{}').".format(ds_id),
        ]

    lines.append("=== END AUTO-DIAGNOSTIC ===")
    return "\n".join(lines), ds_id


def _extract_actual_output_fields_from_source(source_code: str) -> Optional[Dict[str, Any]]:
    """
    Parse a generated backend function's Python source to determine the ACTUAL
    field names it outputs without running the code.

    Handles two common patterns produced by the backend generator:

    Pattern A — $project literal array → $unwind → $replaceRoot:
        pipeline = [
            {'$group': ...},
            {'$project': {'_id': 0, 'data': [{'x_field': '...', 'y_field': '$col'}, ...]}},
            {'$unwind': '$data'},
            {'$replaceRoot': {'newRoot': '$data'}},
        ]
        → output fields = keys of first array element (e.g. ['aging_bucket', 'total_amount'])

    Pattern B — standard $project rename:
        {'$project': {'_id': 0, 'x_key': '$_id', 'y_key': '$count'}}
        → output fields = non-zero projection keys (e.g. ['x_key', 'y_key'])

    Returns:
        {'x_field': '...', 'y_field': '...', 'all_fields': [...]}
        or None if parsing fails.
    """
    import re as _re
    import ast as _ast

    # ── Locate the pipeline literal in the source code ─────────────────────────
    # Use bracket-counting to correctly handle nested arrays/dicts inside the
    # pipeline literal.  The old non-greedy regex (\[[\s\S]*?\]) fails on
    # pipelines that contain nested lists (e.g. Pattern-A $project arrays) because
    # it stops at the first ] it encounters rather than the matching outer ].
    def _find_pipeline_literal(src: str) -> Optional[str]:
        """Return the full '[...]' string of the 'pipeline = [...]' assignment."""
        m = _re.search(r'pipeline\s*=\s*\[', src)
        if not m:
            return None
        start = m.end() - 1  # index of the opening '['
        depth = 0
        in_str: Optional[str] = None  # current string delimiter ('"' or "'")
        escape_next = False
        i = start
        while i < len(src):
            ch = src[i]
            if escape_next:
                escape_next = False
            elif in_str:
                if ch == '\\':
                    escape_next = True
                elif ch == in_str:
                    in_str = None
            else:
                if ch in ('"', "'"):
                    in_str = ch
                elif ch == '[':
                    depth += 1
                elif ch == ']':
                    depth -= 1
                    if depth == 0:
                        return src[start:i + 1]
            i += 1
        return None  # unmatched bracket (shouldn't happen in valid source)

    pipeline_str = _find_pipeline_literal(source_code)
    if not pipeline_str:
        return None

    try:
        pipeline = _ast.literal_eval(pipeline_str)
    except Exception:
        return None

    if not isinstance(pipeline, list):
        return None

    # ── Pattern A: $replaceRoot → find preceding $project with literal array ───
    for i, stage in enumerate(pipeline):
        if not (isinstance(stage, dict) and "$replaceRoot" in stage):
            continue
        rr = stage["$replaceRoot"]
        new_root = rr.get("newRoot", "") if isinstance(rr, dict) else ""
        if not (isinstance(new_root, str) and new_root.startswith("$")):
            continue
        root_field = new_root[1:]
        for prev in reversed(pipeline[:i]):
            if not (isinstance(prev, dict) and "$project" in prev):
                continue
            proj = prev["$project"]
            if not (isinstance(proj, dict) and root_field in proj):
                break
            array_val = proj[root_field]
            if not (isinstance(array_val, list) and array_val):
                break
            first_elem = array_val[0]
            if not isinstance(first_elem, dict):
                break
            keys = list(first_elem.keys())
            return {
                "all_fields": keys,
                "x_field": keys[0] if len(keys) >= 1 else None,
                "y_field": keys[1] if len(keys) >= 2 else None,
            }

    # ── Pattern B: last $project stage with simple renames ────────────────────
    last_project = None
    for stage in reversed(pipeline):
        if isinstance(stage, dict) and "$project" in stage:
            last_project = stage["$project"]
            break

    if last_project and isinstance(last_project, dict):
        fields = [
            k for k, v in last_project.items()
            if k != "_id" and v not in (0, False, None)
        ]
        if fields:
            return {
                "all_fields": fields,
                "x_field": fields[0],
                "y_field": fields[1] if len(fields) >= 2 else None,
            }

    return None


def _read_angular_chart_widget_fields(
    workspace_dir: str,
    function_id: str,
) -> tuple[Optional[str], Optional[str]]:
    """
    Scan the Angular workspace HTML files and return the CURRENT xfield and yfield
    attribute values of the <app-chart-widget> that references `function_id`.

    Returns (current_xfield, current_yfield) or (None, None) if not found.
    """
    import re as _re
    from pathlib import Path as _Path

    workspace_path = _Path(workspace_dir)
    exclude_dirs = {"node_modules", "dist", ".angular", ".git", "out-tsc"}

    for html_file in workspace_path.rglob("*.html"):
        if any(ex in html_file.parts for ex in exclude_dirs):
            continue
        try:
            content = html_file.read_text(encoding="utf-8")
        except Exception:
            continue

        if function_id.lower() not in content.lower():
            continue

        # Find all <app-chart-widget ...> tags
        for tag_match in _re.finditer(r'<app-chart-widget\b[^>]*>', content, flags=_re.DOTALL | _re.IGNORECASE):
            tag_body = tag_match.group(0)
            if function_id.lower() not in tag_body.lower():
                continue
            x_m = _re.search(r'(?i)xfield\s*=\s*["\']([^"\']*)["\']', tag_body)
            y_m = _re.search(r'(?i)yfield\s*=\s*["\']([^"\']*)["\']', tag_body)
            return (
                x_m.group(1) if x_m else None,
                y_m.group(1) if y_m else None,
            )

    return None, None


def _patch_angular_chart_widget_in_workspace(
    workspace_dir: str,
    function_id: str,
    correct_x_field: Optional[str],
    correct_y_field: Optional[str],
) -> list[str]:
    """
    Walk the Angular workspace HTML files and surgically patch any
    <app-chart-widget> that references `function_id` with mismatched
    xfield / yfield attributes.

    Returns a list of file paths that were patched.
    """
    import re as _re
    from pathlib import Path as _Path

    patched: list[str] = []
    workspace_path = _Path(workspace_dir)
    exclude_dirs = {"node_modules", "dist", ".angular", ".git", "out-tsc"}

    for html_file in workspace_path.rglob("*.html"):
        if any(ex in html_file.parts for ex in exclude_dirs):
            continue
        try:
            content = html_file.read_text(encoding="utf-8")
        except Exception:
            continue

        # Only process files that reference this function
        if function_id.lower() not in content.lower():
            continue

        new_content = content

        # Patch yfield attribute when it doesn't match the correct value
        if correct_y_field:
            # Replace yfield="anything" inside a tag that has functionid="function_id"
            # Strategy: use a two-pass approach
            # Pass 1: find the tag block(s) containing this functionid
            # Pass 2: replace yfield inside those blocks only

            def _patch_tag(m: "_re.Match") -> str:
                tag_body = m.group(0)
                if function_id.lower() not in tag_body.lower():
                    return tag_body
                # Replace yfield="..."  (case-insensitive attribute name)
                tag_body = _re.sub(
                    r'(?i)(yfield\s*=\s*["\'])([^"\']*?)(["\'])',
                    lambda mm: mm.group(1) + correct_y_field + mm.group(3),
                    tag_body,
                )
                return tag_body

            # Match <app-chart-widget ... > (possibly multiline)
            new_content = _re.sub(
                r'<app-chart-widget\b[^>]*>',
                _patch_tag,
                new_content,
                flags=_re.DOTALL | _re.IGNORECASE,
            )

        # Patch xfield attribute when it doesn't match the correct value
        if correct_x_field:
            def _patch_tag_x(m: "_re.Match") -> str:
                tag_body = m.group(0)
                if function_id.lower() not in tag_body.lower():
                    return tag_body
                tag_body = _re.sub(
                    r'(?i)(xfield\s*=\s*["\'])([^"\']*?)(["\'])',
                    lambda mm: mm.group(1) + correct_x_field + mm.group(3),
                    tag_body,
                )
                return tag_body

            new_content = _re.sub(
                r'<app-chart-widget\b[^>]*>',
                _patch_tag_x,
                new_content,
                flags=_re.DOTALL | _re.IGNORECASE,
            )

        if new_content != content:
            try:
                html_file.write_text(new_content, encoding="utf-8")
                patched.append(str(html_file))
            except Exception:
                pass

    return patched


def _restore_non_targeted_data_sources(
    original_ir: Dict[str, Any],
    updated_ir: Dict[str, Any],
    target_ds_id: str,
) -> Dict[str, Any]:
    """
    After the LLM updates the IR for a targeted data-issue fix, revert every
    dataSource whose id != target_ds_id back to the original version.

    This prevents collateral backend-regeneration of all other reports when the
    user only asked to fix one specific widget.
    """
    import copy as _copy
    merged = _copy.deepcopy(updated_ir)
    original_by_id = {
        ds.get("id"): ds
        for ds in (original_ir.get("dataSources") or [])
        if ds.get("id")
    }
    restored = []
    for ds in (updated_ir.get("dataSources") or []):
        ds_id = ds.get("id")
        if ds_id and ds_id != target_ds_id and ds_id in original_by_id:
            # Revert to original so the backend diff sees no change for this DS
            restored.append(_copy.deepcopy(original_by_id[ds_id]))
        else:
            restored.append(ds)
    merged["dataSources"] = restored
    return merged


def _build_diagnostic_context_for_data_issue(
    prompt: str,
    current_ir_schema: Dict[str, Any],
    backend_metadata: Dict[str, Any],
) -> tuple[Optional[str], Optional[str]]:
    """
    For prompts that mention a specific widget having blank / missing data, extract
    the relevant backend function source_code and IR dataSource config and return:
      - A self-contained diagnostic block string for the LLM to fix FE/BE mismatches.
      - The matched dataSource id (so the caller can scope the IR change to that DS only).

    Returns (None, None) when the prompt does not appear to be a data-issue report.
    """
    data_issue_keywords = [
        "data is not coming", "data not coming", "no data", "blank", "empty",
        "not showing data", "not loading", "not displaying data", "chart is blank",
        "report is blank", "widget is blank", "data not found", "no results",
        "showing nothing", "data is missing", "missing data", "data is empty",
        "no chart data", "chart not showing", "graph is blank", "graph not showing",
        "table is empty", "kpi not showing", "value not showing",
    ]
    prompt_lower = prompt.lower()
    is_data_issue = any(kw in prompt_lower for kw in data_issue_keywords)
    if not is_data_issue:
        return None, None

    # ── Extract the mentioned widget name ──────────────────────────────────────
    # Strategy: everything BEFORE the first data-issue keyword, stripping
    # trailing filler words ("in this report", "chart", etc.)
    import re as _re
    mentioned_name: Optional[str] = None
    for kw in sorted(data_issue_keywords, key=len, reverse=True):
        idx = prompt_lower.find(kw)
        if idx > 0:
            prefix = prompt[:idx].strip()
            prefix = _re.sub(
                r'\s+(in this report|in the report|in this|in the|for the|for this'
                r'|chart|report|widget|graph|table|kpi|card)$',
                "",
                prefix,
                flags=_re.IGNORECASE,
            ).strip()
            if prefix:
                mentioned_name = prefix
                break

    if not mentioned_name:
        return None, None

    # ── Find the matching dataSource in the IR schema ──────────────────────────
    data_sources = current_ir_schema.get("dataSources") or []
    mentioned_lower = mentioned_name.lower()

    def _name_score(ds: Dict[str, Any]) -> int:
        """Return a similarity score (higher = better match).

        Checks multiple name fields including nested chartMeta.title and
        reportName so that dashboard dataSources (which store the human-readable
        title inside chartMeta, not at the top level) are matched correctly.
        """
        chart_meta = ds.get("chartMeta") or {}
        candidates = [
            ds.get("name") or "",
            ds.get("reportName") or "",          # agentic dashboard DSes use reportName
            ds.get("title") or "",               # some DSes have top-level title
            chart_meta.get("title") or "",       # most dashboard DSes store title here
            ds.get("description") or "",
            ds.get("functionId") or "",          # e.g. "report_2_query"
            ds.get("id") or "",
        ]
        # De-duplicate and remove empties
        seen: set[str] = set()
        unique_candidates = []
        for c in candidates:
            if c and c not in seen:
                seen.add(c)
                unique_candidates.append(c)

        m_words = set(mentioned_lower.split())
        best = 0
        for c in unique_candidates:
            c_lower = c.lower()
            if mentioned_lower == c_lower:
                return 3                         # exact match — stop immediately
            if mentioned_lower in c_lower or c_lower in mentioned_lower:
                best = max(best, 2)
                continue
            # Word-level overlap (need majority of mention words to match)
            c_words = set(c_lower.split())
            overlap = m_words & c_words
            if overlap and len(overlap) >= max(1, len(m_words) // 2):
                best = max(best, 1)
        return best

    scored = [(ds, _name_score(ds)) for ds in data_sources]
    scored.sort(key=lambda x: x[1], reverse=True)
    matching_ds = scored[0][0] if scored and scored[0][1] > 0 else None

    if not matching_ds:
        return None, None

    ds_id = matching_ds.get("id") or ""

    # ── Find the matching backend function source_code ─────────────────────────
    functions = (backend_metadata or {}).get("functions") or []
    matching_func: Optional[Dict[str, Any]] = None
    for fn in functions:
        fn_id = fn.get("id") or fn.get("function_id") or ""
        if fn_id and (fn_id == ds_id or fn_id in ds_id or ds_id in fn_id):
            matching_func = fn
            break

    # ── Build the diagnostic block ─────────────────────────────────────────────
    chart_meta = matching_ds.get("chartMeta") or {}
    x_field    = chart_meta.get("xField", "N/A")
    y_field    = chart_meta.get("yField", "N/A")
    y_fields   = chart_meta.get("yFields") or []
    aggregation = matching_ds.get("aggregationPipeline") or []
    required_fields = matching_ds.get("requiredFields") or []
    report_type = matching_ds.get("type") or matching_ds.get("reportType") or "unknown"

    lines = [
        "",
        "=== AUTO-DIAGNOSTIC: DATA ISSUE DETECTED ===",
        f"User complained about blank/missing data in widget: \"{mentioned_name}\"",
        f"Matched dataSource → id='{ds_id}', type='{report_type}'",
        "",
        "IR schema currently expects these fields from this dataSource:",
        f"  chartMeta.xField  = '{x_field}'",
        f"  chartMeta.yField  = '{y_field}'" + (f"  (yFields = {y_fields})" if y_fields else ""),
        f"  requiredFields    = {required_fields}",
    ]

    if aggregation:
        lines.append(f"  aggregationPipeline = {json.dumps(aggregation)}")

    if matching_func and matching_func.get("source_code"):
        code = matching_func["source_code"]
        if len(code) > 4000:
            code = code[:4000] + "\n# ... [truncated for brevity]"
        lines += [
            "",
            f"Backend function source code (id='{ds_id}'):",
            "```python",
            code,
            "```",
            "",
            "DIAGNOSIS INSTRUCTIONS:",
            "  1. Read the backend function above carefully.",
            "     Look at the aggregation pipeline's final stages ($project, $replaceRoot, $unwind)",
            "     and any Python-level reshaping to determine the ACTUAL field names returned",
            "     in each data item (e.g. 'total_amount', 'aging_bucket').",
            "  2. Compare those actual output fields with the IR schema's chartMeta.xField",
            "     and chartMeta.yField above.",
            "  3. If there is a mismatch (e.g. yField='current' but backend outputs 'total_amount'),",
            "     fix it by updating ONLY this dataSource's chartMeta inside the IR schema:",
            "       - Set chartMeta.yField to the actual field name the backend returns.",
            "       - Set chartMeta.xField to the actual x-axis field name the backend returns.",
            "     OR, if the pipeline itself is broken, also update the aggregationPipeline",
            "     so the backend regenerates with the correct output fields.",
            "  4. Fix ONLY this specific dataSource (id='{}').".format(ds_id),
            "     Do NOT modify any other dataSources, components, or IR keys.",
            "  5. After the fix the chart MUST receive items where item[xField] and item[yField]",
            "     both resolve to real values.",
        ]
    else:
        lines += [
            "",
            "No backend function source code available for this dataSource.",
            "Check the aggregationPipeline above and fix chartMeta.xField/yField if they",
            "do not match the pipeline's final $project output fields.",
            "Fix ONLY this dataSource (id='{}').".format(ds_id),
        ]

    lines.append("=== END AUTO-DIAGNOSTIC ===")
    return "\n".join(lines), ds_id


async def update_angular_screen_async(data: Dict[str, Any], progress_callback: Optional[Callable] = None):
    """Async implementation of Angular screen update with progress reporting."""
    new_version: Optional[str] = None
    billing_owned = False
    try:
        required_fields = ['prompt', 'screen_id', 'project_id']
        for field in required_fields:
            if field not in data:
                return {"success": False, "error": f"Missing required field: {field}", "status_code": 400}

        prompt = data.get('prompt')
        screen_id = data.get('screen_id')
        project_id = data.get('project_id')
        theme_preferences = data.get('theme_preferences')
        impact_report = data.get('impact_report')  # Optional: Phase 1 impact analysis for scope guidance

        get_tracker().set_request_prompts(user_prompt=prompt)

        org_id = data.get("orgId") or data.get("org_id")
        subscriber_id = data.get("subscriberId") or data.get("subscriber_id")
        user_id = data.get("userId") or data.get("user_id")

        billing_owned = get_billing_context() is None
        if billing_owned and subscriber_id:
            init_subscriber_billing(subscriber_id, org_id=org_id, user_id=user_id)

        # Version for this update (v2, v3, ...). We work with a copy of current version in memory;
        # the new version doc is inserted only when the build succeeds (no delete access on server).
        new_version = datetime.utcnow().strftime("%Y%m%d%H%M%S")

        if progress_callback:
            await progress_callback("INFO", "Initializing update process...")

        # Step 0: Load current version (v1) as our working copy. Do not insert v2 yet.
        current_doc = await screen_repository.get_latest_screen_doc(project_id, screen_id)
        if not current_doc:
            return {"success": False, "error": f"Screen {screen_id} not found", "status_code": 404}
        version_count = await screen_repository.count_versions(project_id, screen_id)
        version_label = f"v{version_count + 1}"

        # Reset metrics
        ai_processor.reset_metrics()
        if hasattr(angular_generator, "reset_token_usage"):
            angular_generator.reset_token_usage()
        reset_agent_llm_usage()

        # Step 1: Load current state (still v1 for IR/backend context; v2 is the doc we will update)
        if progress_callback:
            await progress_callback("INFO", "Loading current screen state...")

        current_state = await screen_repository.get_screen_state(project_id, screen_id)
        if not current_state:
            return {"success": False, "error": f"Screen {screen_id} not found", "status_code": 404}
        
        current_ir_schema = current_state.get("current_ir_schema")
        if not current_ir_schema:
            return {"success": False, "error": "Current IR schema not found", "status_code": 404}
        
        previous_ir_schema = current_ir_schema.copy()
        previous_backend_metadata = current_state.get("backend", {})

        # Build chat_history for AI from persisted chat_history.messages (last 5, with metadata)
        persisted_chat = current_state.get("chat_history") or {}
        persisted_messages = persisted_chat.get("messages") or []
        chat_history: Optional[List[Dict[str, Any]]] = None
        if isinstance(persisted_messages, list) and persisted_messages:
            # Use only the last 5 messages for context
            window = persisted_messages[-5:]
            chat_history = []
            for msg in window:
                if not isinstance(msg, dict):
                    continue
                base_content = msg.get("content")
                if not base_content:
                    continue

                # Attach useful metadata inline for better LLM context
                meta_parts = []
                if msg.get("category"):
                    meta_parts.append(f"category={msg.get('category')}")
                if "applied" in msg:
                    meta_parts.append(f"applied={msg.get('applied')}")
                if msg.get("version"):
                    meta_parts.append(f"version={msg.get('version')}")
                if msg.get("changes_summary"):
                    meta_parts.append(f"changes_summary={msg.get('changes_summary')}")
                if msg.get("timestamp"):
                    meta_parts.append(f"timestamp={msg.get('timestamp')}")

                meta_str = ", ".join(str(p) for p in meta_parts if p is not None)
                if meta_str:
                    content = f"{base_content}\n\n[meta: {meta_str}]"
                else:
                    content = base_content

                # Map to AIProcessor expected shape: role + enriched content
                chat_history.append({
                    "role": "user",
                    "content": content,
                })
        
        # Step 2: Classify update
        if progress_callback:
            await progress_callback("INFO", "Classifying update type...")

        category_result = await classify_update_category(
            prompt=prompt,
            project_id=project_id,
            screen_id=screen_id,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id
        )
        print(f"Category identified: {category_result}")
        category = category_result.primary_category
        
        # Step 2.5: For "data not coming / blank widget" prompts:
        #   a) Parse the backend function source to find the ACTUAL output fields.
        #   b) If they differ from the IR chartMeta.xField / yField, apply a
        #      SURGICAL PATCH directly to the Angular workspace HTML — no LLM call
        #      needed for a pure attribute fix.
        #   c) Also inject a diagnostic block into the LLM prompt so the IR is
        #      updated correctly for future regenerations.
        enriched_prompt = prompt
        _diag_target_ds_id: Optional[str] = None  # dataSource id targeted by diagnosis
        _diag_fn_id: Optional[str] = None          # functionId (Angular template attr) for the target DS
        _surgical_fe_fix_applied: bool = False     # True when HTML was patched directly
        try:
            diagnostic_ctx, _diag_target_ds_id = _build_diagnostic_context_for_data_issue(
                prompt=prompt,
                current_ir_schema=current_ir_schema,
                backend_metadata=previous_backend_metadata,
            )
            if diagnostic_ctx and _diag_target_ds_id:
                enriched_prompt = prompt + diagnostic_ctx
                category = "behavior"
                if progress_callback:
                    await progress_callback("INFO", "Data issue detected — diagnosing FE/BE field mismatch...")
                logger.info(
                    "[update_angular_screen] Injected diagnostic context for data issue "
                    "(prompt=%r, target_ds=%s, screen=%s, project=%s)",
                    prompt[:80], _diag_target_ds_id, screen_id, project_id,
                )

                # ── Always resolve the Angular functionId for this DS ─────────
                # This is used both by the surgical patch AND by the fallback
                # force-inject path in Step 5, so we compute it here regardless.
                _target_ds_ir_for_fn = next(
                    (ds for ds in (current_ir_schema.get("dataSources") or [])
                     if ds.get("id") == _diag_target_ds_id),
                    None,
                )
                _diag_fn_id = (
                    (_target_ds_ir_for_fn or {}).get("functionId")
                    or _diag_target_ds_id
                )

                # ── Surgical FE patch ─────────────────────────────────────────
                # Try to resolve the mismatch by directly patching the Angular
                # HTML without going through the full LLM regeneration cycle.
                # Use _get_workspace_path() (latest on disk) rather than the
                # stored DB path which may be stale after a previous partial run.
                _latest_ws = angular_generator._get_workspace_path(project_id, screen_id)
                workspace_dir_for_patch = str(_latest_ws) if _latest_ws else current_state.get("angular_workspace_directory")
                if workspace_dir_for_patch:
                    # Find the backend function source_code for the target DS.
                    # First check the cached backend_metadata; if source_code is
                    # absent there (it is NOT stored in screen docs), fall back to
                    # a live DB look-up via function_repository.
                    _be_functions = (previous_backend_metadata or {}).get("functions") or []
                    _target_fn = next(
                        (
                            f for f in _be_functions
                            if (f.get("id") or f.get("function_id") or "") == _diag_target_ds_id
                        ),
                        None,
                    )
                    _src = (_target_fn or {}).get("source_code") or ""

                    # ── DB fallback: fetch source_code when not in cached meta ─
                    if not _src and _diag_fn_id:
                        try:
                            _fn_record = await backend_generator.function_repository.get_function(
                                project_id, _diag_fn_id
                            )
                            if _fn_record:
                                _src = _fn_record.get("source_code") or ""
                                logger.info(
                                    "[update_angular_screen] Fetched source_code from DB for "
                                    "surgical patch (functionId=%s, len=%d)",
                                    _diag_fn_id, len(_src),
                                )
                        except Exception as _db_src_err:
                            logger.warning(
                                "[update_angular_screen] DB source_code fetch failed (non-fatal): %s",
                                _db_src_err,
                            )

                    _actual_fields = _extract_actual_output_fields_from_source(_src) if _src else None

                    # ── Resolve the target DS IR and its chartMeta once ───────
                    _target_ds_ir = next(
                        (ds for ds in (current_ir_schema.get("dataSources") or [])
                         if ds.get("id") == _diag_target_ds_id),
                        None,
                    )
                    _chart_meta = (_target_ds_ir or {}).get("chartMeta") or {}
                    _ir_x = _chart_meta.get("xField")
                    _ir_y = _chart_meta.get("yField")

                    # Resolve the functionId used in the Angular template
                    _fn_id_for_patch = (
                        (_target_ds_ir or {}).get("functionId")
                        or (_target_fn or {}).get("function_id")
                        or _diag_target_ds_id
                    )
                    # Keep _diag_fn_id in sync with what the patch uses
                    _diag_fn_id = _fn_id_for_patch

                    # ── Check 1: IR-vs-backend mismatch ──────────────────────
                    # IR says one field but backend actually outputs a different one.
                    _needs_x_fix = False
                    _needs_y_fix = False
                    _correct_x: Optional[str] = None
                    _correct_y: Optional[str] = None

                    if _actual_fields:
                        _actual_x = _actual_fields.get("x_field")
                        _actual_y = _actual_fields.get("y_field")
                        if _actual_x and _ir_x and _actual_x != _ir_x:
                            _needs_x_fix = True
                            _correct_x = _actual_x
                        if _actual_y and _ir_y and _actual_y != _ir_y:
                            _needs_y_fix = True
                            _correct_y = _actual_y

                    # ── Check 2: FE-HTML-vs-IR mismatch ──────────────────────
                    # The IR is already correct, but the Angular template was
                    # never regenerated to match (e.g. IR was fixed in a
                    # previous run but the HTML still carries the old values).
                    _html_x_current, _html_y_current = _read_angular_chart_widget_fields(
                        workspace_dir=workspace_dir_for_patch,
                        function_id=_fn_id_for_patch,
                    )
                    if _ir_x and _html_x_current and _html_x_current != _ir_x:
                        _needs_x_fix = True
                        _correct_x = _ir_x  # bring HTML in line with IR
                        logger.info(
                            "[update_angular_screen] FE-HTML-vs-IR xfield mismatch detected: "
                            "HTML has '%s', IR expects '%s' (functionId=%s)",
                            _html_x_current, _ir_x, _fn_id_for_patch,
                        )
                    if _ir_y and _html_y_current and _html_y_current != _ir_y:
                        _needs_y_fix = True
                        _correct_y = _ir_y  # bring HTML in line with IR
                        logger.info(
                            "[update_angular_screen] FE-HTML-vs-IR yfield mismatch detected: "
                            "HTML has '%s', IR expects '%s' (functionId=%s)",
                            _html_y_current, _ir_y, _fn_id_for_patch,
                        )

                    if _needs_x_fix or _needs_y_fix:
                        _patched_files = _patch_angular_chart_widget_in_workspace(
                            workspace_dir=workspace_dir_for_patch,
                            function_id=_fn_id_for_patch,
                            correct_x_field=_correct_x if _needs_x_fix else None,
                            correct_y_field=_correct_y if _needs_y_fix else None,
                        )
                        if _patched_files:
                            _surgical_fe_fix_applied = True
                            logger.info(
                                "[update_angular_screen] Surgical FE patch applied: "
                                "functionId=%s xfield %s→%s, yfield %s→%s, files=%s",
                                _fn_id_for_patch,
                                _html_x_current, _correct_x if _needs_x_fix else _html_x_current,
                                _html_y_current, _correct_y if _needs_y_fix else _html_y_current,
                                _patched_files,
                            )
                            if progress_callback:
                                await progress_callback(
                                    "INFO",
                                    f"Surgical FE fix applied: yfield "
                                    f"'{_html_y_current}' → '{_correct_y or _html_y_current}'"
                                    f" in {len(_patched_files)} file(s)."
                                )
        except Exception as _diag_err:
            logger.warning("[update_angular_screen] Diagnostic step failed (non-fatal): %s", _diag_err)

        # Step 3: Update IR
        if progress_callback:
            await progress_callback("INFO", f"Updating IR Schema ({category})...")

        previous_prompt = current_state.get("prompt")

        # Parse workflow I/O contract from prompt (for downstream screens)
        # This extracts inputParameters/outputParameters from the WORKFLOW_IO_CONTRACT_SCREEN_MARKER
        # and pre-updates the IR schema so the LLM preserves them
        try:
            from services.ai_processor import parse_workflow_io_contract_from_prompt
            workflow_io_contract = parse_workflow_io_contract_from_prompt(enriched_prompt)
            if workflow_io_contract:
                # Pre-update the IR schema with the authoritative workflow I/O contract
                if workflow_io_contract.get("inputParameters"):
                    current_ir_schema["inputParameters"] = workflow_io_contract["inputParameters"]
                    logger.info(f"[update_angular_screen] Pre-updated IR inputParameters from workflow contract: {[p.get('name') for p in workflow_io_contract['inputParameters']]}")
                if workflow_io_contract.get("outputParameters"):
                    current_ir_schema["outputParameters"] = workflow_io_contract["outputParameters"]
                    logger.info(f"[update_angular_screen] Pre-updated IR outputParameters from workflow contract: {[p.get('name') for p in workflow_io_contract['outputParameters']]}")
        except Exception as _e:
            logger.debug(f"[update_angular_screen] Could not parse workflow I/O contract: {_e}")

        updated_ir_schema, changes_summary = await ai_processor.update_screen_ir_async(
            prompt=enriched_prompt,
            current_ir_schema=current_ir_schema,
            chat_history=chat_history,
            theme_preferences=theme_preferences,
            category=category,
            previous_prompt=previous_prompt,
            project_id=project_id,
            screen_id=screen_id,
            version=new_version,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id
        )
        
        if not updated_ir_schema:
            return {"success": False, "error": "Failed to generate updated IR schema", "status_code": 500}

        # Step 3.5: If this was a targeted diagnostic fix, restore every OTHER
        # dataSource back to its original value.  This ensures only the one
        # mentioned widget is regenerated — the backend diff won't see any
        # changes in the other 10 dataSources, so they are NOT rebuilt.
        if _diag_target_ds_id:
            try:
                updated_ir_schema = _restore_non_targeted_data_sources(
                    original_ir=current_ir_schema,
                    updated_ir=updated_ir_schema,
                    target_ds_id=_diag_target_ds_id,
                )
                logger.info(
                    "[update_angular_screen] Scoped IR change to dataSource '%s' only — "
                    "all other dataSources restored to original.",
                    _diag_target_ds_id,
                )
            except Exception as _scope_err:
                logger.warning(
                    "[update_angular_screen] Scope-restoration failed (non-fatal): %s", _scope_err
                )
        
        # Step 4: Handle backend updates
        backend_result = None
        backend_updated = False

        if progress_callback:
            await progress_callback("INFO", "Checking for backend changes...")

        try:
            backend_diff = backend_generator.diff_ir_for_backend_changes(previous_ir_schema, updated_ir_schema)

            changed_ds = backend_diff.get("changed_data_sources") or []
            new_ds = backend_diff.get("new_data_sources") or []
            changed_models_set = set(backend_diff.get("changed_models") or [])
            data_sources_to_process = list(changed_ds) + list(new_ds)
            processed_ids = {ds.get("id") for ds in data_sources_to_process}

            for ds in updated_ir_schema.get("dataSources", []):
                if ds.get("id") in processed_ids:
                    continue
                if ds.get("inputModel") in changed_models_set or ds.get("responseModel") in changed_models_set:
                    data_sources_to_process.append(ds)
                    processed_ids.add(ds.get("id"))

            all_models = updated_ir_schema.get("dataModels") or {}
            model_names_needed = set()
            for ds in data_sources_to_process:
                if ds.get("inputModel"):
                    model_names_needed.add(ds.get("inputModel"))
                if ds.get("responseModel"):
                    model_names_needed.add(ds.get("responseModel"))

            existing_functions = previous_backend_metadata.get("functions") or []
            existing_function_ids = {f.get("function_id") or f.get("id") for f in existing_functions}
            for ds in updated_ir_schema.get("dataSources", []):
                ds_id = ds.get("id")
                ds_function_id = ds.get("functionId") or ds_id
                if ds_id not in processed_ids and ds_function_id not in existing_function_ids:
                    data_sources_to_process.append(ds)
                    processed_ids.add(ds_id)

            data_models_subset = {k: all_models[k] for k in model_names_needed if k in all_models}

            if data_sources_to_process:
                if progress_callback:
                    await progress_callback("INFO", "Updating backend definitions...")

                removed_ids = [ds.get("id") for ds in (backend_diff.get("removed_data_sources") or []) if ds.get("id")]
                logger.info("Updating backend...")
                backend_result = await backend_generator.generate_backend(
                    project_id,
                    data_models_subset,
                    data_sources_to_process,
                    screen_id=screen_id,
                    version=new_version,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    is_update=True,
                    removed_data_source_ids=removed_ids,
                    previous_backend_metadata=previous_backend_metadata,
                    full_data_sources=updated_ir_schema.get("dataSources", []),
                )
                if not backend_result.get("base_path"):
                    backend_result["base_path"] = f"/aiqod-agent/agent/dynamic/execute/{project_id}"
                backend_updated = True
        except Exception as backend_error:
            return {"success": False, "error": f"Backend update failed: {str(backend_error)}", "rollback": True, "status_code": 500}

        # Step 5: Handle Angular updates
        angular_result = None
        try:
            # Generate new_screen_id BEFORE calling Angular generator so the deployment
            # uses the correct screen_id (not the old one). The new screen_id follows
            # the pattern: screen_{version}_{uuid}
            new_screen_id = f"screen_{new_version}_{uuid.uuid4().hex[:8]}"

            workspace_dir = current_state.get("angular_workspace_directory")
            backend_meta_to_use = _ensure_backend_metadata(backend_result or previous_backend_metadata, project_id)

            if not workspace_dir:
                if progress_callback:
                    await progress_callback("WARNING", "Workspace not found. Performing full regeneration...")

                angular_result = await angular_generator.generate_app(
                    user_prompt=prompt,
                    project_id=project_id,
                    screen_id=new_screen_id,
                    ir_schema=updated_ir_schema,
                    backend_metadata=backend_meta_to_use,
                    progress_callback=progress_callback,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    version=new_version,
                    is_update=True,
                )
            else:
                if progress_callback:
                    await progress_callback("INFO", "Performing selective Angular update...")
                
                if _surgical_fe_fix_applied:
                    # ── Fast path for surgical FE patches ────────────────────────
                    # The HTML was already patched on disk (yfield attribute fixed).
                    # Skip LLM regeneration entirely — affected_files=[] means
                    # _update_app_sync just copies the patched workspace to a new
                    # versioned dir and rebuilds/redeploys without touching any files.
                    affected_files = []
                    if progress_callback:
                        await progress_callback(
                            "INFO",
                            "Surgical FE fix already applied — skipping LLM regeneration, rebuilding workspace..."
                        )
                    logger.info(
                        "[update_angular_screen] Surgical FE fix path: "
                        "affected_files=[] to preserve patch (no LLM regeneration)."
                    )
                else:
                    # Normal path: ask LLM which files need regenerating
                    current_code = angular_generator._read_workspace_code(workspace_dir)
                    analysis = angular_generator.analyze_update_scope(
                        enriched_prompt,
                        updated_ir_schema,
                        current_code,
                        project_id=project_id,
                        screen_id=new_screen_id,
                        version=new_version,
                        org_id=org_id,
                        subscriber_id=subscriber_id,
                        user_id=user_id,
                        impact_report=impact_report,
                    )
                    affected_files = analysis.get("affected_files", [])

                    # ── Fallback force-inject for data-issue fixes ────────────
                    # When the surgical patch could not fire (e.g. source_code
                    # unavailable) but we know which widget needs fixing, we
                    # guarantee that the Angular HTML component file(s) containing
                    # that chart widget are included in the regeneration scope.
                    # Without this, the LLM scope analysis often misses the HTML
                    # template update needed to correct yfield/xfield attributes.
                    if _diag_target_ds_id and _diag_fn_id:
                        try:
                            from pathlib import Path as _Path
                            _existing_paths = {f.get("path") for f in affected_files}
                            _ws_path_obj = _Path(workspace_dir)
                            _skip_dirs = {"node_modules", "dist", ".angular", ".git", "out-tsc"}
                            for _html_f in _ws_path_obj.rglob("*.html"):
                                if any(ex in _html_f.parts for ex in _skip_dirs):
                                    continue
                                try:
                                    _fc = _html_f.read_text(encoding="utf-8")
                                except Exception:
                                    continue
                                if _diag_fn_id.lower() in _fc.lower():
                                    _rel = str(_html_f.relative_to(_ws_path_obj))
                                    if _rel not in _existing_paths:
                                        affected_files.append({
                                            "path": _rel,
                                            "reason": (
                                                f"Chart widget for functionId='{_diag_fn_id}' has "
                                                f"a wrong yfield/xfield attribute — must be updated "
                                                f"to match the actual backend output fields described "
                                                f"in the diagnostic context above."
                                            ),
                                            "change_type": "style",
                                        })
                                        _existing_paths.add(_rel)
                                        logger.info(
                                            "[update_angular_screen] Force-added HTML to affected_files "
                                            "for data-issue fix: %s (functionId=%s)",
                                            _rel, _diag_fn_id,
                                        )
                        except Exception as _fi_err:
                            logger.warning(
                                "[update_angular_screen] Force-inject affected_files failed (non-fatal): %s",
                                _fi_err,
                            )
                print(f"Affected files: {affected_files}")

                # Use workspace directory from current_state to avoid screen_id mismatch
                # (screen_id changes per update for versioning, but workspace uses old screen_id)
                existing_workspace_dir = current_state.get("angular_workspace_directory")

                angular_result = await angular_generator.update_app(
                    user_prompt=enriched_prompt,
                    project_id=project_id,
                    screen_id=new_screen_id,
                    updated_ir_schema=updated_ir_schema,
                    affected_files=affected_files,
                    backend_metadata=backend_meta_to_use,
                    progress_callback=progress_callback,
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    user_id=user_id,
                    version=new_version,
                    existing_workspace_dir=existing_workspace_dir,
                )
            
        except WorkflowBudgetExhaustedError:
            # Let global exception handler catch this for 402 with billing details & resume info
            raise
        except AngularBuildError as build_error:
            raise HTTPException(
                status_code=500,
                detail={
                    "success": False,
                    "error": f"Angular build failed: {str(build_error)}",
                    "rollback": True,
                    "recovery_attempts": build_error.attempts
                }
            )
        except Exception as angular_error:
            raise HTTPException(
                status_code=500,
                detail={
                    "success": False,
                    "error": f"Angular update failed: {str(angular_error)}",
                    "rollback": True
                }
            )
        
        # T8 FE↔BE contract audit now runs inside angular_generator._generate_app_sync
        # (before npm build) — no separate post-generate call needed here.

        # If Angular update was skipped (no affected files), don't create new screen document or update dashboardUrl
        logger.debug(
            f"[update_angular_screen] Checking skipped flag: angular_result={angular_result}, "
            f"skipped={angular_result.get('skipped') if angular_result else 'N/A'}"
        )
        if angular_result and angular_result.get("skipped"):
            logger.info(f"[update_angular_screen] Angular update skipped (no file changes), returning early without creating new version")
            logger.debug(f"[update_angular_screen] SKIPPED: returning original screen_id={screen_id}, version={angular_result.get('version')}")
            return {
                "success": True,
                "skipped": True,
                "screen_id": screen_id,  # Return original screen_id since no new version created
                "version": angular_result.get("version"),
                "public_url": angular_result.get("public_url"),
                "message": angular_result.get("message", "No file changes needed - only contract/bindings updated")
            }

        # Step 6: Persist updated state — insert new version doc only now (build succeeded)
        try:
            deploy_base_url = config.get("LIBERTY_FS_BASE_URL", "https://liberty-fs.gibots.com:843")
            # Prefer Angular's computed public_url (which includes the concrete version suffix)
            public_url = angular_result.get("public_url") if angular_result else None
            if not public_url:
                # Fallback: build URL that points directly to the versioned folder
                # Use new_screen_id (generated before Angular call) not old screen_id
                public_url = f"{deploy_base_url.rstrip('/')}/{new_screen_id}-v{new_version}"
            
            angular_metadata = {
                "workspace_directory": str(angular_result.get("workspace_directory")) if angular_result.get("workspace_directory") else None,
                "public_url": public_url,  # Always point to latest concrete version path
                "version": angular_result.get("version"),
                "last_build_at": datetime.utcnow(),
            }
            
            backend_metadata_save = None
            if backend_updated and backend_result:
                # Stored metadata uses "function_id"; backend_result may use "id". Preserve both.
                backend_metadata_save = {
                    "base_path": backend_result.get("base_path"),
                    "functions": [
                        {
                            "function_id": func.get("function_id") or func.get("id"),
                            "type": func.get("type"),
                            "description": func.get("description"),
                            "input_model": func.get("input_model"),
                            "response_model": func.get("response_model"),
                            "version": func.get("version"),
                            "version_label": func.get("version_label"),
                        }
                        for func in backend_result.get("functions", [])
                    ]
                }
            screen_name = data.get("screen_name") or current_state.get("screen_name")
            
            # Build chat history entry for this update (UI or behavior)
            changes_description = ""
            if isinstance(changes_summary, dict):
                changes_description = changes_summary.get("description") or ""

            chat_history_entry = {
                "id": uuid.uuid4().hex,
                "content": prompt,
                "timestamp": datetime.utcnow(),
                "category": category,
                "applied": True,
                "version": new_version,
                "changes_summary": changes_description,
            }

            # Build v2 doc from current (v1) and insert only on success (no delete on server)
            v2_doc = copy.deepcopy(current_doc)
            v2_doc.pop("_id", None)

            # Refresh IR schema with correct outputParameters inferred from the
            # generated screen (generation description + user prompt). The initial
            # IR update may have failed or missed new fields added by Angular.
            try:
                from services.ai_processor import AIProcessor
                ai_proc = AIProcessor()
                # Ensure workflow IO parameters are inferred from components
                updated_ir_schema = ai_proc._ensure_workflow_io_parameters(updated_ir_schema)
                # Also supplement from generation description and user prompt
                # Use current_doc's config (screen config) instead of undefined 'node'
                screen_config = current_doc.get("config", {}) if isinstance(current_doc.get("config"), dict) else {}
                gen_desc = screen_config.get("generationDescription", "")
                user_prompt = data.get("prompt", "")
                # LLM generates outputs; no supplementer needed
            except Exception as _ir_refresh_err:
                logger.warning(f"[update_angular_screen] Failed to refresh IR outputParameters: {_ir_refresh_err}")

            v2_doc["ir_schema"] = updated_ir_schema
            v2_doc["angular"] = angular_metadata
            v2_doc["backend"] = backend_metadata_save if backend_metadata_save else (current_doc.get("backend") or {})
            v2_doc["screen_name"] = screen_name
            existing_chat = (current_doc.get("chat_history") or {}).copy()
            max_messages = existing_chat.get("max_messages") or 10
            if not isinstance(max_messages, int) or max_messages <= 0:
                max_messages = 10
            existing_messages = list(existing_chat.get("messages") or [])
            existing_messages.append(chat_history_entry)
            if len(existing_messages) > max_messages:
                existing_messages = existing_messages[-max_messages:]
            v2_doc["chat_history"] = {"max_messages": max_messages, "messages": existing_messages}

            # new_screen_id was already generated before Angular generator call
            # (screen_{version}_{uuid}) to ensure deployment uses correct screen_id

            await screen_repository.insert_screen_version_doc(
                project_id,
                new_screen_id,
                new_version,
                version_label,
                v2_doc,
                build_status="success",
                is_stable=True,
            )

            # Point current version to this successful update (v2) under the NEW screen_id
            subscriber_db_name = f"{get_main_db_name()}_sb_{subscriber_id}" if subscriber_id else None
            await screen_repository.update_screens_pointer(
                project_id,
                new_screen_id,
                new_version,
                org_id=org_id,
                subscriber_id=subscriber_id,
                subscriber_db_name=subscriber_db_name,
                user_id=user_id,
            )
            try:
                screen_doc = {
                    **v2_doc,
                    "screen_id": new_screen_id,
                    "project_id": project_id,
                    "version": new_version,
                    "orgId": ObjectId(org_id) if org_id else None,
                    "subscriberId": ObjectId(subscriber_id) if subscriber_id else None,
                    "userId": ObjectId(user_id) if user_id else None,
                }
                await sync_screen_single(capability_repository, screen_doc)
            except Exception as cap_exc:
                logger.warning("Capability sync after screen update failed: %s", cap_exc)
            # Update Process_Configs.agentic_process.dashboardUrl with the new public_url
            try:
                if public_url:
                    db["Process_Configs"].update_one(
                        {"engineType": "agentic_graph", "agentic_process.workflow_id": project_id},
                        {"$set": {
                            "agentic_process.dashboardUrl": public_url,
                            "updated_at": datetime.utcnow(),
                        }},
                    )
                    logger.info(
                        "[update_angular_screen] Updated Process_Configs.agentic_process.dashboardUrl "
                        "for project_id=%s → %s",
                        project_id, public_url,
                    )
            except Exception as pc_exc:
                logger.warning(
                    "[update_angular_screen] Failed to update Process_Configs.dashboardUrl "
                    "(non-fatal): %s", pc_exc,
                )
        except Exception as persist_error:
            logger.error(f"Failed to persist screen state: {persist_error}")
        
        # Persist LLM token usage to LLM_Tokens collection
        try:
            await _persist_llm_tokens(
                project_id=project_id,
                screen_id=screen_id,
                operation="update-angular-screen",
                version=angular_result.get("version"),
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id
            )
        except Exception as token_save_exc:
            logger.warning(f"Failed to persist LLM tokens: {token_save_exc}")

        # Aggregate screen cost summary for this update
        try:
            await aggregate_screen_cost(
                project_id=project_id,
                screen_id=screen_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                status="completed",
            )
        except Exception as cost_agg_exc:
            logger.warning(
                "Failed to aggregate screen cost for update-angular-screen project_id=%s, screen_id=%s: %s",
                project_id,
                screen_id,
                cost_agg_exc,
            )

        return {
            "success": True,
            "screen_id": new_screen_id,
            "project_id": project_id,
            "updated_ir_schema": updated_ir_schema,
            "changes_made": changes_summary,
            "backend": backend_result if backend_updated else None,
            "angular": {
                "public_url": angular_result.get("public_url"),
                "changed_files": angular_result.get("changed_files", []),
                "version": angular_result.get("version")
            },
            "category": category,
            "error": None
        }
        
    except BillingError:
        raise
    except Exception as e:
        # No delete on server: we never inserted v2 on failure, so v1 remains current
        logger.error(f"Error in update_angular_screen: {str(e)}")
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail={
                "success": False,
                "screen_id": data.get('screen_id'),
                "error": str(e),
                "rollback": True
            }
        )
    finally:
        if billing_owned:
            clear_billing_context()
        get_tracker().clear_request_prompts()


@app.post("/aiqod-agent/agent/save-screen")
async def save_screen(request: SaveScreenRequest):
    """
    Save IR schema and screen generation to database
    """
    try:
        data = request.model_dump()

        project_id = data.get('project_id')
        screen_name = data.get('screen_name')
        screen_id = data.get('screen_id')

        # Logic to check if we are confirming a draft (update current/latest version only)
        existing_record = await screen_repository.get_latest_screen_doc(project_id, screen_id)

        if existing_record:
            update_fields = {"status": "active"}
            if screen_name:
                update_fields["screen_name"] = screen_name
            if data.get('description'):
                update_fields["description"] = data.get('description')
            if data.get('ir_schema'):
                update_fields["ir_schema"] = data.get('ir_schema')

            db["screen_generations"].update_one(
                {"_id": existing_record["_id"]},
                {"$set": update_fields}
            )
            print(f"Screen {screen_id} status updated to active")
            
            return {
                "success": True,
                "screen_id": screen_id,
                "project_id": project_id,
                "message": "Screen saved and activated successfully"
            }

        # Fallback to creating new if it doesn't exist (original logic)
        # For creating a new screen, prompt, ir_schema, and screen_name are required
        prompt = data.get('prompt')
        ir_schema_payload = data.get('ir_schema')
        if not prompt or not ir_schema_payload or not screen_name:
            raise HTTPException(
                status_code=400,
                detail="For creating a new screen, 'prompt', 'ir_schema', and 'screen_name' are required. For updating status to active on an existing screen, only 'screen_id' and 'project_id' are required."
            )
        if project_id and screen_name:
            # Pass screen_id to exclude itself during updates
            exists = await check_screen_name_exists(project_id, screen_name, exclude_screen_id=screen_id)
            if exists:
                 raise HTTPException(
                    status_code=400, 
                    detail=f"Screen name '{screen_name}' already exists in this project."
                )

        print("\n--------------------------------")
        print("Saving new screen to database...")

        ir_schema_payload = ir_schema_payload or {}
        components_payload = data.get('components') or ir_schema_payload.get('components', [])

        record_id = await screen_repository.create_screen_generation(
            prompt=prompt,
            ir_schema=ir_schema_payload,
            screen_spec=data.get('screen_spec') or {},
            components=components_payload,
            screen_id=data.get('screen_id'),
            project_id=data.get('project_id'),
            screen_name=screen_name,
            description=data.get('description'),  # Add description field
            screen_type=data.get('screen_type'),
            theme_preferences=data.get('theme_preferences'),
            permissions=data.get('permissions'),
        )

        # Ensure the new record is active (update by latest for this screen)
        latest_after = await screen_repository.get_latest_screen_doc(project_id, data.get('screen_id'))
        if latest_after:
            db["screen_generations"].update_one(
                {"_id": latest_after["_id"]},
                {"$set": {"status": "active"}}
            )
            try:
                sync_doc = dict(latest_after)
                sync_doc["_id"] = str(latest_after.get("_id", ""))
                await sync_screen_single(capability_repository, sync_doc)
            except Exception as cap_exc:
                logger.warning("Capability sync after screen save failed: %s", cap_exc)

        print(f"Screen saved successfully with screen_id: {data.get('screen_id')}")

        return {
            "success": True,
            "screen_id": data.get('screen_id'),
            "project_id": data.get('project_id'),
            "message": "Screen saved successfully"
        }

    except Exception as e:
        print(f"Error in save_screen: {str(e)}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={
            "success": False,
            "error": str(e)
        })


