async def detect_flow_io_for_steps(
    prompt_steps: List[Dict[str, Any]],
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Use LLM to detect inputParameters and outputParameters for an ordered list of prompt steps.

    Returns a list of step dicts with at least: order, stepKey (if provided), screenName,
    inputParameters, outputParameters.
    """
    # Normalize and sort steps by order for a stable contract
    normalized_steps = sorted(
        [
            {
                "order": step.get("order"),
                "stepKey": step.get("stepKey") or step.get("step_key"),
                "screenName": step.get("screenName") or step.get("screen_name"),
                "prompt": step.get("prompt", ""),
            }
            for step in prompt_steps
        ],
        key=lambda s: s.get("order") or 0,
    )

    detection_payload = {
        "steps": normalized_steps,
    }

    detection_prompt = (
        "You are an expert workflow IO contract designer.\n"
        "Analyze the following ordered UI screen steps and determine how data flows "
        "from one step to the next.\n\n"
        "For each step, you MUST infer:\n"
        "1. inputParameters: what this step receives from previous steps (or external context).\n"
        "2. outputParameters: what this step produces that can be used by later steps.\n\n"
        "CRITICAL RULES:\n"
        "- Respect the order of steps. Later steps may depend on earlier outputs.\n"
        "- Use the screen prompts and names to understand what each step does.\n"
        "- Prefer reusing identifiers across steps (e.g. ekyc_record_id) instead of inventing new ones.\n"
        "- Do NOT include credentials, API keys, or secrets as parameters.\n"
        "- Parameters represent business data (ids, names, urls, flags, etc.).\n"
        "- Keep structure FLAT (no nested objects), just an array of parameter objects.\n"
        "- Each parameter object MUST have: name, type, description, example.\n"
        "- type MUST be one of: string, number, boolean, array, object.\n"
        "- If a step does not need any external inputs, use an empty array for inputParameters.\n"
        "- If a step does not produce anything useful for later steps, use an empty array for outputParameters. \n\n"
        "INPUT STEPS JSON (ordered):\n"
        f"{json.dumps(detection_payload, indent=2)}\n\n"
        "Return ONLY valid JSON in this exact shape (no markdown, no comments):\n"
        "{\n"
        '  \"steps\": [\n'
        "    {\n"
        "      \"order\": 1,\n"
        "      \"stepKey\": \"optional_stable_key\",\n"
        "      \"screenName\": \"User form\",\n"
        "      \"inputParameters\": [\n"
        "        {\n"
        "          \"name\": \"ekyc_record_id\",\n"
        "          \"type\": \"string\",\n"
        "          \"description\": \"Unique identifier of the eKYC record created in the database.\",\n"
        "          \"example\": \"65f2c8a9e12d4a0012ab98cd\"\n"
        "        }\n"
        "      ],\n"
        "      \"outputParameters\": [\n"
        "        {\n"
        "          \"name\": \"ekyc_record_id\",\n"
        "          \"type\": \"string\",\n"
        "          \"description\": \"Unique identifier of the eKYC record created in the database.\",\n"
        "          \"example\": \"65f2c8a9e12d4a0012ab98cd\"\n"
        "        }\n"
        "      ]\n"
        "    }\n"
        "  ]\n"
        "}\n"
    )

    started_at = datetime.utcnow()
    raw_response = await async_llm_call(detection_prompt)
    finished_at = datetime.utcnow()

    response_text = raw_response.strip() if isinstance(raw_response, str) else str(raw_response)

    prompt_tokens = len(detection_prompt) // 4
    completion_tokens = len(response_text) // 4

    # Track LLM usage for observability
    record_llm_call(
        org_id=org_id,
        subscriber_id=subscriber_id,
        user_id=user_id,
        operation="workflow-io-detector",
        sub_operation="multi-step-io",
        model="gemini-3-flash-preview",
        prompt_tokens=prompt_tokens,
        completion_tokens=completion_tokens,
        total_tokens=prompt_tokens + completion_tokens,
        status="success",
        started_at=started_at,
        finished_at=finished_at,
        metadata={},
    )

    try:
        # Extract JSON if wrapped in ```json fences
        regex_pattern = r"```json(.*?)```"
        match = re.findall(regex_pattern, response_text, flags=re.S)
        if match:
            json_str = match[0].strip()
        else:
            json_str = response_text

        json_str = repair_json(json_str)
        parsed = json.loads(json_str)
        steps = parsed.get("steps") if isinstance(parsed, dict) else parsed
        if not isinstance(steps, list):
            raise ValueError("LLM IO detector returned invalid structure (expected 'steps' array).")
        return steps
    except Exception as e:
        logger.error(f"Failed to parse workflow IO detector response: {e}")
        logger.debug(f"Raw IO detector response: {response_text[:1000]}")
        raise HTTPException(
            status_code=500,
            detail={"success": False, "error": "Failed to detect input/output parameters for steps."},
        )


@app.post("/aiqod-agent/agent/generate-angular-flow")
async def generate_angular_flow(request: Request):
    """
    New batch flow:
    1) Accept an ordered list of promptSteps (no screens generated yet).
    2) Call a multi-step IO detector once to infer inputParameters/outputParameters per step.
    3) Append those IO contracts into each step's prompt.
    4) Generate Angular screens for each step by calling the existing generate_angular_app_async
       pipeline in parallel.
    """
    try:
        body = await request.json() or {}
        prompt_steps = body.get("promptSteps") or body.get("prompt_steps")

        if not isinstance(prompt_steps, list) or not prompt_steps:
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": "Missing or invalid 'promptSteps'. Provide a non-empty array of steps.",
                },
            )

        # Global identifiers (optional, can be overridden per-step)
        root_org_id = body.get("orgId") or body.get("org_id")
        root_subscriber_id = body.get("subscriberId") or body.get("subscriber_id")
        root_user_id = body.get("userId") or body.get("user_id")

        if root_subscriber_id:
            init_subscriber_billing(
                root_subscriber_id,
                org_id=root_org_id,
                user_id=root_user_id,
            )

        # Sort steps by order for deterministic behavior
        ordered_steps = sorted(
            prompt_steps,
            key=lambda s: s.get("order") or 0,
        )

        # Step 1: Detect IO contracts across the full flow
        detected_steps = await detect_flow_io_for_steps(
            ordered_steps,
            org_id=root_org_id,
            subscriber_id=root_subscriber_id,
            user_id=root_user_id,
        )

        # Build lookup by (order, stepKey) for robust mapping
        io_index: Dict[Tuple[Optional[int], Optional[str]], Dict[str, Any]] = {}
        for step in detected_steps:
            key = (
                step.get("order"),
                (step.get("stepKey") or step.get("step_key")),
            )
            io_index[key] = step

        enriched_steps: List[Dict[str, Any]] = []
        generation_tasks = []

        for step in ordered_steps:
            order = step.get("order")
            step_key = step.get("stepKey") or step.get("step_key")
            screen_name = step.get("screenName") or step.get("screen_name")

            io_step = io_index.get((order, step_key)) or io_index.get((order, None)) or {}
            input_params = io_step.get("inputParameters", []) or []
            output_params = io_step.get("outputParameters", []) or []

            # Enrich step with detected IO
            enriched_step = {
                **step,
                "inputParameters": input_params,
                "outputParameters": output_params,
            }
            enriched_steps.append(enriched_step)

            base_prompt = step.get("prompt") or ""
            # Append IO contract into the prompt so the IR/Angular pipeline can respect it
            if input_params or output_params:
                io_contract = {
                    "inputParameters": input_params,
                    "outputParameters": output_params,
                }
                base_prompt = (
                    f"{base_prompt}\n\n"
                    f"{WORKFLOW_IO_CONTRACT_STEP_MARKER}\n"
                    f"{json.dumps(io_contract, indent=2)}"
                )

            project_id = (
                step.get("projectId")
                or step.get("project_id")
                or body.get("projectId")
                or body.get("project_id")
            )
            if not project_id:
                raise HTTPException(
                    status_code=400,
                    detail={
                        "success": False,
                        "error": f"Missing projectId for step with order={order} and screenName={screen_name}",
                    },
                )

            screen_id = step.get("screenId") or step.get("screen_id") or generate_screen_id("screen")

            org_id = step.get("orgId") or step.get("org_id") or root_org_id
            subscriber_id = (
                step.get("subscriberId") or step.get("subscriber_id") or root_subscriber_id
            )
            user_id = step.get("userId") or step.get("user_id") or root_user_id

            payload = {
                "prompt": base_prompt,
                "project_id": project_id,
                "screen_id": screen_id,
                "screen_name": screen_name,
                "orgId": org_id,
                "org_id": org_id,
                "subscriberId": subscriber_id,
                "subscriber_id": subscriber_id,
                "userId": user_id,
                "user_id": user_id,
            }

            generation_tasks.append(
                (order, step_key, screen_name, project_id, screen_id, org_id, subscriber_id, user_id, payload)
            )

        async def _run_generation(task_tuple):
            (
                order,
                step_key,
                screen_name,
                project_id,
                screen_id,
                org_id,
                subscriber_id,
                user_id,
                payload,
            ) = task_tuple
            try:
                result = await generate_angular_app_async(payload)
                return {
                    "order": order,
                    "stepKey": step_key,
                    "screenName": screen_name,
                    "project_id": project_id,
                    "screen_id": screen_id,
                    "success": True,
                    "public_url": result.get("public_url"),
                    "version": result.get("version"),
                    "file_count": result.get("file_count", 0),
                }
            except HTTPException as http_exc:
                detail = getattr(http_exc, "detail", str(http_exc))
                return {
                    "order": order,
                    "stepKey": step_key,
                    "screenName": screen_name,
                    "project_id": project_id,
                    "screen_id": screen_id,
                    "success": False,
                    "error": detail,
                }
            except Exception as exc:
                logger.error(f"Error generating screen for step {order}: {exc}")
                return {
                    "order": order,
                    "stepKey": step_key,
                    "screenName": screen_name,
                    "project_id": project_id,
                    "screen_id": screen_id,
                    "success": False,
                    "error": str(exc),
                }

        # Run all screen generations in parallel for faster execution
        screen_results = await asyncio.gather(
            *[_run_generation(task) for task in generation_tasks]
        )

        return {
            "success": True,
            "steps": enriched_steps,
            "screens": screen_results,
        }
    except HTTPException:
        raise
    except BillingError:
        raise
    except Exception as exc:
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail={"success": False, "error": str(exc)},
        )


@app.post("/aiqod-agent/agent/generate-angular-app")
async def generate_angular_app(request: Request):
    try:
        payload = await request.json() or {}
        project_id = payload.get("project_id")
        screen_id = payload.get("screen_id")
        screen_name = payload.get("screen_name")
        org_id = payload.get("orgId") or payload.get("org_id")
        subscriber_id = payload.get("subscriberId") or payload.get("subscriber_id")
        user_id = payload.get("userId") or payload.get("user_id")
        
        prompt = payload.get("prompt", "")
        figma_link = payload.get("figma_link")
        user_figma_token = payload.get("figma_token")
        target_figma_url = None
        logger.info(f"Payload: {payload}")
        # 1. Detect Link
        if figma_link and "figma.com" in figma_link:
            target_figma_url = figma_link
            print(f"🔍 Figma link detected in direct payload: {target_figma_url}")
        elif "figma.com" in prompt:
            match = re.search(r"(https?://www\.figma\.com/\S+)", prompt)
            if match:
                target_figma_url = match.group(1)
                print(f"🔍 Figma link extracted from prompt: {target_figma_url}")

        # 2. Process Link (Safe Mode with Logging)
        if target_figma_url:
            # Determine which service instance to use
            active_service = figma_service
            
            # Authentication Logging
            if active_service:
                print("🔹 System Figma Token found in config.")
            
            # If system has no token, but user provided one, create a temporary service instance
            if not active_service and user_figma_token:
                print("🔹 Using provided User Figma Token.")
                try:
                    active_service = FigmaService(user_figma_token)
                except Exception as e:
                    print(f"Failed to init temp Figma service: {e}")

            if active_service:
                try:
                    print("Starting Figma Data Fetch...")
                    
                    # Fetch Image
                    image_data = await active_service.get_node_image_async(target_figma_url, user_token=user_figma_token)
                    if image_data:
                        print(f"Figma Image captured successfully ({len(image_data)} bytes).")
                        payload["figma_image_data"] = image_data
                    else:
                        print("Figma Image fetch returned None.")

                    # Fetch Data ("Anima Mode")
                    node_data = await active_service.get_node_data_async(target_figma_url, user_token=user_figma_token)
                    if node_data:
                        print("Figma JSON Data captured successfully.")
                        payload["figma_json_data"] = json.dumps(node_data)
                    else:
                        print("Figma JSON fetch returned None (Check Figma Service logs for API errors).")
                        
                except Exception as figma_err:
                    print(f"Failed Figma Fetch: {figma_err}")
                    traceback.print_exc()
            else:
                print(" Skipping Figma: No system token and no user token provided.")
        else:
            print("ℹ No Figma URL found in request.")
        if not project_id or not screen_id:
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": "Missing required field(s): project_id, screen_id",
                },
            )

        if project_id and screen_name:
            exists = await check_screen_name_exists(project_id, screen_name)
            if exists:
                raise HTTPException(
                    status_code=400, 
                    detail=f"Screen name '{screen_name}' already exists in this project."
                )

        user_prompt = payload.get("prompt") or build_prompt_from_payload(payload)
        if not user_prompt:
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": "Missing prompt. Provide 'prompt' or structured fields.",
                },
            )

        # 1. Create Job
        job_id = job_manager.create_job()
        asyncio.create_task(
            background_generator_task(
                job_id, generate_angular_app_async, payload=payload
            )
        )

        return {"success": True, "job_id": job_id}

    except Exception as exc:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={"success": False, "error": str(exc)})


