@app.get("/aiqod-agent/agent/stream/{job_id}")
async def stream_job_status(job_id: str):
    """
    SSE Endpoint. Frontend connects here to listen for logs, retries, and the final result.
    """
    queue = job_manager.get_queue(job_id)
    if not queue:
        raise HTTPException(status_code=404, detail="Job not found")

    async def event_generator():
        try:
            while True:
                # Wait for next event
                data = await queue.get()
                
                if data is None: # Sentinel for end of stream
                    break
                
                # Format as SSE (data: json_string\n\n)
                yield f"data: {json.dumps(data)}\n\n"
        finally:
            job_manager.cleanup_job(job_id)

    return StreamingResponse(event_generator(), media_type="text/event-stream")

async def generate_angular_app_async(payload: Dict[str, Any], progress_callback: Optional[Callable] = None):
    """Async implementation of Angular app generation with metadata persistence and Figma extraction."""
    billing_owned = False
    try:
        required_fields = ["project_id", "screen_id"]
        missing_fields = [field for field in required_fields if not payload.get(field)]

        if missing_fields:
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": f"Missing required field(s): {', '.join(missing_fields)}"
                }
            )

        # 1. Capture the metadata from your payload
        # Preserve the raw prompt exactly as provided by the frontend for persistence.
        # The generation prompt may be enhanced/augmented later (e.g., with workflow IO contract).
        raw_frontend_prompt = payload.get("prompt")
        prompt = raw_frontend_prompt
        screen_name = payload.get("screen_name")
        description = payload.get("description") or prompt
        figma_image_data = payload.get("figma_image_data")
        figma_json_data = payload.get("figma_json_data")

        # 2. Prompt Fallback Logic (Restored)
        if not prompt:
            prompt = build_prompt_from_payload(payload)

        if not prompt:
            raise HTTPException(
                status_code=400,
                detail={
                    "success": False,
                    "error": "Missing prompt. Provide 'prompt' or structured fields."
                }
            )

        # Persisted prompt should remain the exact frontend-entered prompt when available.
        prompt_for_persistence = raw_frontend_prompt or prompt

        # 3. Setup LLM Tracking Prompts (Restored)
        get_tracker().set_request_prompts(user_prompt=prompt)

        project_id = payload["project_id"]
        screen_id = payload["screen_id"]
        theme_preferences = payload.get("theme_preferences")
        workflow_context = payload.get("workflow_context")
        
        org_id = payload.get("orgId") or payload.get("org_id")
        subscriber_id = payload.get("subscriberId") or payload.get("subscriber_id")
        user_id = payload.get("userId") or payload.get("user_id")

        billing_owned = get_billing_context() is None
        if billing_owned and subscriber_id:
            init_subscriber_billing(subscriber_id, org_id=org_id, user_id=user_id)

        # Use timestamp + short unique suffix so parallel flow steps (same project, same second)
        # do not collide on screen_generations unique index (project_id, function_id, version)
        version = datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:8]

        if progress_callback:
            await progress_callback("INFO", "Initializing generation parameters...")

        # Reset LLM metrics
        ai_processor.reset_metrics()
        if hasattr(angular_generator, "reset_token_usage"):
            angular_generator.reset_token_usage()
        if hasattr(backend_generator, "reset_token_usage"):
            backend_generator.reset_token_usage()
        reset_agent_llm_usage()

        # Step 1: Generate IR schema
        if progress_callback:
            await progress_callback("INFO", "Generating IR Schema from prompt...")

        raw_ir_schema = await ai_processor.generate_ir_schema_async(
            prompt=prompt,
            image_data=figma_image_data,
            figma_json_str=figma_json_data,
            screen_type=None,
            theme_preferences=theme_preferences,
            workflow_context=workflow_context,
            project_id=project_id,
            screen_id=screen_id,
            version=version,
            org_id=org_id,
            subscriber_id=subscriber_id,
            user_id=user_id,
        )

        if not isinstance(raw_ir_schema, dict):
            raise ValueError("Failed to generate a structured IR schema.")

        logger.info(f"Raw IR schema generated.")

        # Step 1.5: Fetch Figma Image Assets (New Feature)
        assets_data = {}
        target_figma_url = payload.get("figma_link")
        user_figma_token = payload.get("figma_token")
        
        if figma_json_data and target_figma_url:
            if progress_callback:
                await progress_callback("INFO", "Scanning IR Schema for exact requested image IDs...")
            
            # Extract exact IDs from IR Schema
            requested_image_ids = []
            def extract_requested_figma_ids(schema: Any) -> List[str]:
                found_ids = []
                if isinstance(schema, dict):
                    for k, v in schema.items():
                        if isinstance(v, str) and 'assets/figma_' in v:
                            import re
                            match = re.search(r'figma_([a-zA-Z0-9_]+)\.(?:png|jpg|svg|jpeg)', v)
                            if match:
                                figma_id = match.group(1).replace('_', ':')
                                found_ids.append(figma_id)
                        else:
                            found_ids.extend(extract_requested_figma_ids(v))
                elif isinstance(schema, list):
                    for item in schema:
                        found_ids.extend(extract_requested_figma_ids(item))
                return found_ids

            requested_image_ids = extract_requested_figma_ids(raw_ir_schema)
            logger.info(f"🔍 Found {len(requested_image_ids)} requested image IDs in Schema: {requested_image_ids}")

            if requested_image_ids:
                if progress_callback:
                    await progress_callback("INFO", f"Downloading {len(requested_image_ids)} Figma assets...")
                
                active_service = figma_service
                if not active_service and user_figma_token:
                    active_service = FigmaService(user_figma_token)
                
                if active_service:
                    assets_data = await active_service.extract_and_download_assets(
                        figma_json_str=figma_json_data, 
                        target_figma_url=target_figma_url,
                        requested_image_ids=requested_image_ids
                    )
                
        # Step 2: Materialize backend
        if progress_callback:
            await progress_callback("INFO", "Generating Backend definitions...")

        backend_result = {"base_path": None, "functions": [], "models_source": None}
        try:
            try:
                from services.persistence_link import (
                    extract_persistence_links_from_text,
                    stamp_persistence_links_on_datasources,
                )
                _persist_links = extract_persistence_links_from_text(prompt or "")
                stamp_persistence_links_on_datasources(
                    raw_ir_schema.get("dataSources") or [],
                    _persist_links,
                )
            except Exception:
                pass
            backend_result = await backend_generator.generate_backend(
                project_id=project_id,
                data_models=raw_ir_schema.get("dataModels", {}),
                data_sources=raw_ir_schema.get("dataSources", []),
                screen_id=screen_id,
                version=version,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id
            )
        except BillingError:
            raise
        except Exception as backend_error:
            logger.error(f"Backend generation failed: {backend_error}")
            if progress_callback:
                await progress_callback("WARNING", f"Backend generation issue: {backend_error}")

        if not backend_result.get("base_path"):
            fallback_path = f"/aiqod-agent/agent/dynamic/execute/{project_id}"
            backend_result["base_path"] = fallback_path

        # Restored Backend Context wrapper to ensure api_base_url is passed
        backend_context = {
            **(backend_result or {}),
            "project_id": project_id,
            "screen_id": screen_id,
            "api_base_url": config.get("ai_agent_base_url"),
        }

        is_figma_mode = bool(figma_json_data and target_figma_url)

        # Step 3: Generate Angular App
        if progress_callback:
            await progress_callback("INFO", "Starting Angular App generation...")

        try:
            result = await angular_generator.generate_app(
                user_prompt=prompt,
                project_id=project_id,
                screen_id=screen_id,
                ir_schema=raw_ir_schema,
                backend_metadata=backend_context,
                progress_callback=progress_callback,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id,
                assets_data=assets_data,
                is_figma_mode=is_figma_mode,
                version=version,
                is_update=False,
            )
        except AngularBuildError as build_exc:
            raise HTTPException(
                status_code=500,
                detail={
                    "success": False,
                    "error": str(build_exc),
                    "recovery_attempts": build_exc.attempts,
                }
            )

        # T8 FE↔BE contract audit now runs inside angular_generator._generate_app_sync
        # (before npm build) — no separate post-generate call needed here.

        # 4. Insert v1 into screen_generations and update screens pointer (single collection versioning)
        try:
            original_prompt_enhanced = getattr(ai_processor, "last_enhanced_prompt", None)
            deploy_base_url = config.get("LIBERTY_FS_BASE_URL", "https://liberty-fs.gibots.com:843")
            # Prefer Angular's computed public_url (which includes the concrete version suffix)
            public_url = result.get("public_url") if result else None
            if not public_url:
                # Fallback: build URL that points directly to the versioned folder
                public_url = f"{deploy_base_url.rstrip('/')}/{screen_id}-v{version}"
            
            angular_metadata = {
                "workspace_directory": result.get("workspace_directory"),
                "public_url": public_url,  # Always point to latest concrete version path
                "version": result.get("version"),
                "last_build_at": datetime.utcnow(),
            }
            backend_metadata_save = {
                "base_path": backend_result.get("base_path"),
                "functions": [
                    {
                        "function_id": func.get("id"),
                        "type": func.get("type"),
                        "description": func.get("description"),
                        "input_model": func.get("input_model"),
                        "response_model": func.get("response_model"),
                        "version": func.get("version"),
                        "version_label": func.get("version_label"),
                    }
                    for func in backend_result.get("functions", [])
                ],
            }
            v1_doc: Dict[str, Any] = {
                "ir_schema": raw_ir_schema,
                "angular": angular_metadata,
                "backend": backend_metadata_save,
                "prompt": prompt_for_persistence,
                "screen_name": screen_name,
                "description": description or prompt_for_persistence,
                "original_prompt_enhanced": original_prompt_enhanced or "",
                "screen_spec": {},
                "components": raw_ir_schema.get("components", []),
                "permissions": None,
                "theme_preferences": None,
                "screen_type": None,
                "status": "draft",
                "chat_history": {"max_messages": 10, "messages": []},
            }
            if org_id is not None:
                try:
                    v1_doc["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id
                except Exception:
                    pass
            if subscriber_id is not None:
                try:
                    v1_doc["subscriberId"] = ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id
                except Exception:
                    pass
            if user_id is not None:
                try:
                    v1_doc["userId"] = ObjectId(user_id) if isinstance(user_id, str) else user_id
                except Exception:
                    pass
            await screen_repository.insert_screen_version_doc(
                project_id,
                screen_id,
                version,
                "v1",
                v1_doc,
                build_status="success",
                is_stable=True,
            )
            subscriber_db_name = f"{get_main_db_name()}_sb_{subscriber_id}" if subscriber_id else None
            await screen_repository.update_screens_pointer(
                project_id,
                screen_id,
                version,
                org_id=org_id,
                subscriber_id=subscriber_id,
                subscriber_db_name=subscriber_db_name,
                user_id=user_id,
            )
            try:
                screen_doc = {
                    **v1_doc,
                    "screen_id": screen_id,
                    "project_id": project_id,
                    "version": version,
                    "orgId": ObjectId(org_id) if org_id else None,
                    "subscriberId": ObjectId(subscriber_id) if subscriber_id else None,
                    "userId": ObjectId(user_id) if user_id else None,
                }
                await sync_screen_single(capability_repository, screen_doc)
            except Exception as cap_exc:
                logger.warning("Capability sync after screen generate failed: %s", cap_exc)
        except Exception as save_exc:
            logger.warning(f"Failed to persist v1 screen generation: {save_exc}")

        # Persist LLM token usage (Restored)
        try:
            await _persist_llm_tokens(
                project_id=project_id,
                screen_id=screen_id,
                operation="generate-angular-app",
                version=result.get("version"),
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=user_id
            )
        except Exception as token_save_exc:
            logger.warning(f"Failed to persist LLM tokens: {token_save_exc}")

        # Aggregate and persist per-screen cost summary
        try:
            await aggregate_screen_cost(
                project_id=project_id,
                screen_id=screen_id,
                org_id=org_id,
                subscriber_id=subscriber_id,
                status="completed",
            )
        except Exception as cost_agg_exc:
            logger.warning(
                "Failed to aggregate screen cost for project_id=%s, screen_id=%s: %s",
                project_id,
                screen_id,
                cost_agg_exc,
            )

        return {
            "success": True,
            "project_id": project_id,
            "screen_id": screen_id,
            "ir_schema": raw_ir_schema,
            "version": result.get("version"),
            "public_url": result.get("public_url"),
            "file_count": result.get("file_count", 0),
            "recovery_attempts": result.get("recovery_attempts", []),
        }

    except BillingError:
        raise
    except Exception as exc:
        logger.error(f"Error in generate_angular_app_async: {str(exc)}")
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail={
                "success": False,
                "screen_id": payload.get('screen_id'),
                "error": str(exc)
            }
        )
    finally:
        if billing_owned:
            clear_billing_context()
        get_tracker().clear_request_prompts()


@app.post("/aiqod-agent/agent/validate-ir-schema")
async def validate_ir_schema_endpoint(ir_schema: Dict):
    """
    Validate IR schema before generation
    """
    try:
        if not ir_schema:
            raise HTTPException(status_code=400, detail={
                "valid": False,
                "errors": ["No IR schema provided"],
                "component_count": 0
            })

        validation = gemini_generator.validate_ir_schema(ir_schema)

        if not validation.get('valid'):
            return {
                "valid": False,
                "errors": validation.get('errors', []),
                "component_count": 0
            }

        return {
            "valid": True,
            "errors": [],
            "component_count": validation.get('component_count', 0)
        }

    except Exception as e:
        print(f"Error in validate_ir_schema: {str(e)}")
        raise HTTPException(status_code=500, detail={
            "error": "Validation failed",
            "message": str(e)
        })


def serialize_mongo_document(doc):
    """Recursively convert ObjectId to string in a document."""
    if isinstance(doc, list):
        return [serialize_mongo_document(item) for item in doc]
    if isinstance(doc, dict):
        return {k: serialize_mongo_document(v) for k, v in doc.items()}
    if isinstance(doc, ObjectId):
        return str(doc)
    return doc


@app.get("/aiqod-agent/agent/screen-versions")
async def list_screen_versions(
    project_id: str = Query(...),
    screen_id: str = Query(...),
):
    """
    List versions for a specific screen from `screen_generations`, newest first.

    This endpoint exists to support the frontend rollback picker UX.
    It filters out deleted versions and returns enough metadata for the UI
    to disable invalid rollback targets (build_status != success or is_stable == false).
    """
    try:
        screens_collection = _get_screens_collection()
        generations_collection = Database.get_collection("screen_generations")

        pointer = await screens_collection.find_one(
            {"project_id": project_id, "screen_id": screen_id}
        )
        current_version = (pointer or {}).get("current_version")

        cursor = generations_collection.find(
            {
                "project_id": project_id,
                "screen_id": screen_id,
                "deleted": {"$ne": True},
            },
            {
                "_id": 0,
                "version": 1,
                "version_label": 1,
                "created_at": 1,
                "build_status": 1,
                "is_stable": 1,
                "status": 1,
                "angular.public_url": 1,
            },
        ).sort([("version", -1), ("created_at", -1)])

        docs = await cursor.to_list(length=None)

        versions = []
        for doc in docs:
            angular = doc.get("angular") or {}
            versions.append(
                {
                    "version": doc.get("version"),
                    "created_at": doc.get("created_at"),
                    "build_status": doc.get("build_status") or "success",
                    "is_stable": doc.get("is_stable", True),
                    "version_label": doc.get("version_label"),
                    "status": doc.get("status"),
                    "public_url": angular.get("public_url"),
                    "is_current": bool(current_version and doc.get("version") == current_version),
                }
            )

        return {
            "success": True,
            "project_id": project_id,
            "screen_id": screen_id,
            "current_version": current_version,
            "versions": serialize_mongo_document(versions),
        }
    except Exception as e:
        logger.error("Error listing screen versions: %s", e, exc_info=True)
        raise HTTPException(status_code=500, detail={"success": False, "error": str(e)})


@app.post("/aiqod-agent/agent/update-screen-metadata")
async def update_screen_metadata_endpoint(request: UpdateScreenMetadataRequest):
    """
    Update display/list metadata on a screen snapshot in `screen_generations`.

    Targets `screens.current_version` when present, otherwise the latest non-deleted row.
    Optional `version` pins the row to update. Does not modify IR, Angular, or backend blobs.
    """
    try:
        payload = request.model_dump(exclude_unset=True)
        project_id = payload.pop("project_id")
        screen_id = payload.pop("screen_id")
        version = payload.pop("version", None)

        if "screen_name" in payload and payload.get("screen_name"):
            exists = await check_screen_name_exists(
                project_id, payload["screen_name"], exclude_screen_id=screen_id
            )
            if exists:
                raise HTTPException(
                    status_code=400,
                    detail={
                        "success": False,
                        "error": f"Screen name '{payload['screen_name']}' already exists in this project.",
                    },
                )

        updated, err = await screen_repository.update_screen_metadata(
            project_id,
            screen_id,
            payload,
            version=version,
        )
        if err == "no_allowed_fields":
            raise HTTPException(
                status_code=400,
                detail={"success": False, "error": "No valid metadata fields to update"},
            )
        if err == "not_found" or not updated:
            raise HTTPException(
                status_code=404,
                detail={
                    "success": False,
                    "error": f"Screen {screen_id} not found for project {project_id}",
                },
            )

        try:
            sync_doc = dict(updated)
            sync_doc["_id"] = str(updated.get("_id", ""))
            await sync_screen_single(capability_repository, sync_doc)
        except Exception as cap_exc:
            logger.warning("Capability sync after update-screen-metadata failed: %s", cap_exc)

        touched = list(payload.keys())
        return serialize_mongo_document(
            {
                "success": True,
                "project_id": project_id,
                "screen_id": screen_id,
                "version": updated.get("version"),
                "updated_fields": touched,
                "metadata": {k: updated.get(k) for k in touched},
            }
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error("Error in update-screen-metadata: %s", e, exc_info=True)
        raise HTTPException(status_code=500, detail={"success": False, "error": str(e)})


@app.get("/aiqod-agent/agent/credits")
async def get_subscriber_credits(
    http_request: Request,
    subscriberId: Optional[str] = Query(None),
    orgId: Optional[str] = Query(None),
    userId: Optional[str] = Query(None),
):
    """
    Return subscriber wallet snapshot for sidebar / billing UI.

    Reads ``subscribers.AICredits`` (USD): limit, used, reserved.
    ``available_credits`` = limit - used - reserved.
    """
    subscriber_id = (
        subscriberId
        or http_request.headers.get("x-subscriber-id")
        or ""
    ).strip()
    if not subscriber_id:
        raise HTTPException(
            status_code=400,
            detail={"success": False, "error": "subscriberId is required"},
        )

    try:
        snapshot = get_subscriber_credits_snapshot(subscriber_id)
    except ValueError as exc:
        raise HTTPException(
            status_code=400,
            detail={"success": False, "error": str(exc)},
        )
    except RuntimeError as exc:
        raise HTTPException(
            status_code=503,
            detail={"success": False, "error": str(exc)},
        )

    if snapshot is None:
        raise HTTPException(
            status_code=404,
            detail={
                "success": False,
                "error": f"Subscriber '{subscriber_id}' not found",
            },
        )

    return {"success": True, "data": snapshot}


class SubscriberCreditsTopUpRequest(BaseModel):
    subscriberId: Optional[str] = None
    orgId: Optional[str] = None
    userId: Optional[str] = None
    amountUsd: float = Field(..., gt=0, description="USD amount to add to AICredits.limit")
    note: Optional[str] = Field(None, max_length=500)


@app.post("/aiqod-agent/agent/credits/top-up")
async def top_up_subscriber_credits(
    body: SubscriberCreditsTopUpRequest,
    http_request: Request,
):
    """
    Top up subscriber wallet by increasing ``subscribers.AICredits.limit``.

    Does not modify ``used`` or ``reserved``. After a successful top-up, call
    ``GET /aiqod-agent/agent/credits`` (or use the returned snapshot) to refresh UI.
    """
    subscriber_id = (
        body.subscriberId
        or http_request.headers.get("x-subscriber-id")
        or ""
    ).strip()
    if not subscriber_id:
        raise HTTPException(
            status_code=400,
            detail={"success": False, "error": "subscriberId is required"},
        )

    try:
        snapshot = top_up_subscriber_wallet(
            subscriber_id,
            body.amountUsd,
            note=body.note,
        )
    except ValueError as exc:
        raise HTTPException(
            status_code=400,
            detail={"success": False, "error": str(exc)},
        )
    except LookupError as exc:
        raise HTTPException(
            status_code=404,
            detail={"success": False, "error": str(exc)},
        )
    except RuntimeError as exc:
        raise HTTPException(
            status_code=503,
            detail={"success": False, "error": str(exc)},
        )

    return {"success": True, "data": snapshot}


@app.get("/aiqod-agent/agent/ui-list")
async def ui_list():
    """
    Fetch one row per screen (latest non-draft version) from screen_generations.
    """
    try:
        collection = Database.get_collection("screen_generations")
        pipeline = [
            # Only consider non-deleted, non-draft versions
            {"$match": {"deleted": {"$ne": True}, "status": {"$ne": "draft"}}},
            {"$sort": {"version": -1, "created_at": -1}},
            {"$group": {"_id": {"project_id": "$project_id", "screen_id": "$screen_id"}, "doc": {"$first": "$$ROOT"}}},
            {"$replaceRoot": {"newRoot": "$doc"}},
            {"$project": {"_id": 1, "project_id": 1, "screen_id": 1, "screen_name": 1}},
        ]
        cursor = collection.aggregate(pipeline)
        records_list = await cursor.to_list(length=None)
        records_list = serialize_mongo_document(records_list)

        print(f"✓ Found {len(records_list)} active screens (current version each)")
        return {"success": True, "data": records_list}

    except Exception as e:
        print(f"Error in ui_list: {str(e)}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={"success": False, "error": str(e)})


@app.get("/aiqod-agent/agent/ui-screen/{screen_id}")
async def ui_screen(screen_id: str, project_id: Optional[str] = None):
    """
    Fetch the current version for a screen, using the `screens` pointer
    to respect versioning and rollback. Falls back to latest non-deleted
    version if no pointer exists.
    """
    try:
        screens_collection = _get_screens_collection()
        generations_collection = Database.get_collection("screen_generations")

        # 1. Resolve pointer from `screens` collection
        pointer_query: Dict[str, Any] = {"screen_id": screen_id}
        if project_id:
            pointer_query["project_id"] = project_id

        pointer = await screens_collection.find_one(pointer_query)

        record = None
        if pointer and pointer.get("current_version"):
            # 2. Load the exact version the pointer refers to
            version = pointer["current_version"]
            gen_query: Dict[str, Any] = {
                "screen_id": screen_id,
                "version": version,
                "deleted": {"$ne": True},
            }
            if pointer.get("project_id"):
                gen_query["project_id"] = pointer["project_id"]
            elif project_id:
                gen_query["project_id"] = project_id

            record = await generations_collection.find_one(
                gen_query,
                sort=[("created_at", -1)],
            )

        # 3. Fallback: no pointer or version not found → use latest non-deleted doc
        if record is None:
            record = await screen_repository.get_screen_generation(screen_id)

        if not record:
            raise HTTPException(
                status_code=404,
                detail={
                    "success": False,
                    "error": f"Record with screen_id '{screen_id}' not found"
                }
            )
        record = serialize_mongo_document(record)

        print(f"✓ Found record with screen_id '{screen_id}'")

        return {"success": True, "data": record}

    except Exception as e:
        print(f"Error in ui_screen: {str(e)}")
        traceback.print_exc()
        raise HTTPException(
            status_code=500,
            detail={"success": False, "error": str(e)}
        )

