@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException):
    """
    Preserve HTTPException detail from route handlers.

    The previous blanket 404 handler turned every 404 (including
    'session not found') into 'Endpoint not found', which made /stage0/guidance
    look unregistered when the session had expired.
    """
    detail = exc.detail
    if exc.status_code == 404 and detail in ("Not Found", "Not found"):
        return JSONResponse(
            status_code=404,
            content={"success": False, "error": "Endpoint not found"},
        )
    if isinstance(detail, dict):
        body: dict[str, Any] = {"success": False, **detail}
    else:
        body = {"success": False, "error": detail}
    return JSONResponse(status_code=exc.status_code, content=body)

