@app.post('/aiqod-agent/agent/test')
async def run_agent(request: TestAgentRequest):
    start_time = time.time()
    agent_id = request.agent_id
    input_data = request.input_data
    task_description = request.task_description
    agent = agent_store.get(agent_id)
    if not agent:
        raise HTTPException(status_code=404, detail={"error": "Agent not found"})
    print(agent)
    task = Task(
        description=f'Description:{task_description}\nInput:{input_data}',
        expected_output="Formatted_String",
        agent=agent
    )

    crew = Crew(
        agents=[agent],
        tasks=[task]
    )

    crew_output = crew.kickoff()
    task_output = task.output
    print(f"Task Description: {task_output.description}")
    print(f"Task Summary: {task_output.summary}")
    print(f"Raw Output: {task_output.raw}")
    if task_output.json_dict:
        print(f"JSON Output: {json.dumps(task_output.json_dict, indent=2)}")
    if task_output.pydantic:
        print(f"Pydantic Output: {task_output.pydantic}")

    execution_time = time.time() - start_time

    return {"success":True,"data":{"output": task_output.raw,"execution_time":f'{execution_time:.6f}',"status":"success"}}


def _extract_agent_config(agent):
    """Extract agent configuration into a serializable dictionary"""
    config = {
        # Basic agent properties
        'id': str(getattr(agent, 'id', '')),
        'role': getattr(agent, 'role', ''),
        'goal': getattr(agent, 'goal', ''),
        'backstory': getattr(agent, 'backstory', ''),

        # Configuration options
        'config': getattr(agent, 'config', None),
        'cache': getattr(agent, 'cache', True),
        'verbose': getattr(agent, 'verbose', False),
        'max_rpm': getattr(agent, 'max_rpm', None),
        'allow_delegation': getattr(agent, 'allow_delegation', False),
        'max_iter': getattr(agent, 'max_iter', 25),
        'max_tokens': getattr(agent, 'max_tokens', None),
        'max_execution_time': getattr(agent, 'max_execution_time', None),
        'max_retry_limit': getattr(agent, 'max_retry_limit', 2),

        # Knowledge and memory
        'knowledge': getattr(agent, 'knowledge', None),
        'knowledge_sources': getattr(agent, 'knowledge_sources', None),
        'knowledge_storage': getattr(agent, 'knowledge_storage', None),
        'knowledge_config': getattr(agent, 'knowledge_config', None),

        # Templates and prompts
        'system_template': getattr(agent, 'system_template', None),
        'prompt_template': getattr(agent, 'prompt_template', None),
        'response_template': getattr(agent, 'response_template', None),
        'use_system_prompt': getattr(agent, 'use_system_prompt', True),

        # Execution options
        'allow_code_execution': getattr(agent, 'allow_code_execution', False),
        'code_execution_mode': getattr(agent, 'code_execution_mode', 'safe'),
        'respect_context_window': getattr(agent, 'respect_context_window', True),
        'multimodal': getattr(agent, 'multimodal', False),

        # Agent operations
        'agent_ops_agent_name': getattr(agent, 'agent_ops_agent_name', None),
        'agent_ops_agent_id': getattr(agent, 'agent_ops_agent_id', None),
        'adapted_agent': getattr(agent, 'adapted_agent', False),
        'from_repository': getattr(agent, 'from_repository', None),

        # Callbacks and handlers
        'step_callback': getattr(agent, 'step_callback', None) is not None,
        'callbacks': len(getattr(agent, 'callbacks', [])) if hasattr(agent, 'callbacks') else 0,
    }

    # Handle tools with detailed information
    if hasattr(agent, 'tools') and agent.tools:
        config['tools'] = []
        for tool in agent.tools:
            tool_info = {
                'name': getattr(tool, 'name', str(tool)),
                'description': getattr(tool, 'description', ''),
                'type': type(tool).__name__,
                'args_schema': str(getattr(tool, 'args_schema', None)),
                'description_updated': getattr(tool, 'description_updated', False),
                'result_as_answer': getattr(tool, 'result_as_answer', False),
            }
            config['tools'].append(tool_info)

    # Handle LLM info (basic info only, not the actual LLM object)
    if hasattr(agent, 'llm') and agent.llm:
        llm_info = {
            'type': type(agent.llm).__name__,
            'model_name': getattr(agent.llm, 'model_name', None),
            'temperature': getattr(agent.llm, 'temperature', None),
            'max_tokens': getattr(agent.llm, 'max_tokens', None),
            'model': getattr(agent.llm, 'model', None),
        }
        # Remove None values
        config['llm'] = {k: v for k, v in llm_info.items() if v is not None}

    # Handle function calling LLM
    if hasattr(agent, 'function_calling_llm') and agent.function_calling_llm:
        config['function_calling_llm'] = {
            'type': type(agent.function_calling_llm).__name__,
            'model_name': getattr(agent.function_calling_llm, 'model_name', None),
        }

    # Handle embedder
    if hasattr(agent, 'embedder') and agent.embedder:
        config['embedder'] = {
            'type': type(agent.embedder).__name__,
        }

    # Handle security config
    if hasattr(agent, 'security_config') and agent.security_config:
        security_config = agent.security_config
        config['security_config'] = {
            'version': getattr(security_config, 'version', None),
            'fingerprint_uuid': str(getattr(security_config.fingerprint, 'uuid_str', '')) if hasattr(security_config, 'fingerprint') else None,
            'fingerprint_created_at': str(getattr(security_config.fingerprint, 'created_at', '')) if hasattr(security_config, 'fingerprint') else None,
        }

    # Remove None values and empty strings from main config
    return {k: v for k, v in config.items() if v is not None and v != ''}




