def load_agent_config(yaml_file_path):
    if not os.path.exists(yaml_file_path):
        raise FileNotFoundError(f"Agent configuration file not found: {yaml_file_path}")
    
    with open(yaml_file_path, 'r', encoding='utf-8') as file:
        agents_data = yaml.safe_load(file) or {}

    if not agents_data:
        raise ValueError(f"Empty or invalid agent configuration in {yaml_file_path}")
    
    agent_name = next(iter(agents_data))

    return agents_data[agent_name], agent_name

def recreate_agent(yaml_file_path, llm, tools=None):

    config,agent_name = load_agent_config(yaml_file_path)

    # Create agent with basic config
    agent_params = {
        'role': config.get('role', ''),
        'goal': config.get('goal', ''),
        'backstory': config.get('backstory', ''),
        'llm': llm,
    }

    # Add all the configuration parameters
    config_mapping = {
        'verbose': 'verbose',
        'allow_delegation': 'allow_delegation',
        'max_iter': 'max_iter',
        'max_tokens': 'max_tokens',
        'max_execution_time': 'max_execution_time',
        'max_retry_limit': 'max_retry_limit',
        'cache': 'cache',
        'max_rpm': 'max_rpm',
        'system_template': 'system_template',
        'prompt_template': 'prompt_template',
        'response_template': 'response_template',
        'use_system_prompt': 'use_system_prompt',
        'allow_code_execution': 'allow_code_execution',
        'code_execution_mode': 'code_execution_mode',
        'respect_context_window': 'respect_context_window',
        'multimodal': 'multimodal',
        'agent_ops_agent_name': 'agent_ops_agent_name',
        'agent_ops_agent_id': 'agent_ops_agent_id',
        'adapted_agent': 'adapted_agent',
        'from_repository': 'from_repository',
        'knowledge': 'knowledge',
        'knowledge_sources': 'knowledge_sources',
        'knowledge_storage': 'knowledge_storage',
        'knowledge_config': 'knowledge_config',
        'function_calling_llm': 'function_calling_llm',
        'embedder': 'embedder',
        'tools': 'tools'
    }

    for yaml_key, agent_param in config_mapping.items():
        if yaml_key in config:
            agent_params[agent_param] = config[yaml_key]

    # Add tools if provided, otherwise note that tools need to be provided separately
    tools_final = []
    available_tools = get_available_tools()


    if tools:
        agent_params['tools'] = tools
    elif 'tools' in config:
        print(f"Warning: Agent '{agent_name}' had {len(config['tools'])} tools saved.")
        print("Tool info saved but actual tool objects need to be provided via 'tools' parameter")
        print("Saved tools:")

        for tool in config['tools']:
            print(f"  - {tool['name']}: {tool['description']}")
            if tool['type'] in available_tools.keys():
                tools_final.append(available_tools[tool['type']])

        agent_params['tools'] = tools_final
    print(agent_params['tools'])
    return Agent(**agent_params)

