@app.post('/aiqod-agent/agent/executeagent')
async def execute_agent(request: ExecuteAgentRequest):
    start_time = time.time()
    yaml_file_path = request.input.savedAgentPath
    agent_description = request.input.task_description
    input_data = request.input.model_dump()

    # 1. Recreate Agent (this might be fast enough to keep here, or move to thread if slow)
    # Note: If recreate_agent does heavy file I/O, consider moving it inside the thread too.
    agent = recreate_agent(yaml_file_path, llm)
    if not agent:
        raise HTTPException(status_code=404, detail={"error": "Agent not found"})

    output_format = request.input.outputParamsFormat if request.input.outputParamsFormat else {'output': 'string'}
    output_format = json.loads(repair_json(output_format)) if isinstance(output_format, str) else output_format
    if isinstance(output_format, dict):
        output_format['executionStatus'] = 'Success/Failed'

    # 2. Get the running event loop
    loop = asyncio.get_running_loop()

    # 3. Offload the blocking execution to a thread pool
    try:
        task_output = await loop.run_in_executor(
            None,  # None uses the default ThreadPoolExecutor
            _run_crew_sync,  # The function to run
            agent, 
            agent_description, 
            input_data, 
            output_format
        )
    except Exception as e:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={"error": str(e)})

    execution_time = time.time() - start_time

    # 4. Process response (fast CPU operation, safe to do in main loop)
    try:
        output_data = json.loads(task_output.raw)
        output_data['statusCode'] = '200'
        if 'executionStatus' in output_data and output_data['executionStatus'].lower() != 'success':
            output_data['statusCode'] = '202'
    except Exception as e:
        output_data = {}
        output_data['statusCode'] = '202'

    return {"success": True, "data": {"output": task_output.raw, "execution_time": f'{execution_time:.6f}', "status": "success"}}

