def load_and_execute_orchestrator_with_verification(code_file_path: str, input_data: dict, 
                                                     selected_tools: list, 
                                                     verify_inputs: bool = True) -> dict:
    start_time = time.time()
    
    try:
        # 1. Read Code
        with open(code_file_path, 'r', encoding='utf-8') as file:
            orchestrator_code = file.read()

        # Clean Markdown if present
        if "```" in orchestrator_code:
            match = re.search(r"```python\s*(.*?)\s*```", orchestrator_code, re.DOTALL)
            orchestrator_code = match.group(1) if match else orchestrator_code.replace("```", "")

        # 2. Wrap Tools for Debugging
        # We create a dictionary where keys map to the WRAPPED tool
        tool_instances = {}
        for tool in selected_tools:
            # Wrap the tool
            debug_tool = ToolDebugWrapper(tool)
            
            # Map strict name
            tool_instances[tool.name] = debug_tool
            # Map clean name
            clean_name = tool.name.lower().replace(" ", "").replace("_", "")
            tool_instances[clean_name] = debug_tool
            # Map underscore name
            tool_instances[tool.name.replace(" ", "_")] = debug_tool

        # 3. Execution Environment
        namespace = {
            'tool_instances': tool_instances,
            'json': json,
            'time': time,
            'print': print
        }

        # 4. Compile
        print("⚙️ Compiling Orchestrator Code...")
        exec(orchestrator_code, namespace)
        
        execute_func = namespace.get('execute_orchestrator')
        if not execute_func:
            return {'executionStatus': 'Failed', 'error': 'Function not found'}
        
        # 5. Execute
        print("🚀 Starting Execution...")
        result = execute_func(input_data, tool_instances)
        
        print(f"🏁 Execution Result: {result}")
        return result

    except Exception as e:
        traceback.print_exc()
        return {
            'executionStatus': 'Failed',
            'error': f'System Error: {str(e)}',
            'statusCode': '500'
        }

