def get_tools_by_names(tool_names: List[str]) -> List[BaseTool]:
    """
    Retrieve tool instances by their names using the existing tool_registry.
    Includes DEEP DEBUGGING to find missing tools.
    """
    # 1. Get all tools currently in memory
    available_tools = tool_registry.get_all_tools()
    
    selected_tools = []
    
    # Helper to normalize names
    def normalize(s: str) -> str:
        if not s: return ""
        return s.lower().strip().replace(' ', '').replace('\xa0', '').replace('_', '')
        
    # 2. Build the map
    tool_name_map = {}
    for key, tool in available_tools.items():
        # Store by normalized tool.name
        norm_name = normalize(tool.name)
        tool_name_map[norm_name] = tool
    
    # 3. Lookup Loop
    for name in tool_names:
        search_key = normalize(name)
        
        if search_key in tool_name_map:
            selected_tools.append(tool_name_map[search_key])
        else:
            # --- DIAGNOSTIC FAILURE BLOCK ---
            print(f"\n[CRITICAL ERROR] Tool lookup failed for: '{name}'")
            print(f"  > Search Key: '{search_key}'")
            print(f"  > Registry Status: Contains {len(tool_name_map)} tools.")
            
            if len(tool_name_map) == 0:
                print("  > CAUSE: THE REGISTRY IS EMPTY! Tools were not saved during initialization.")
            else:
                print(f"  > Available Keys in Registry: {list(tool_name_map.keys())}")
                
                # Check if it's there under a different name
                similar = [k for k in tool_name_map.keys() if 'ocr' in k]
                if similar:
                    print(f"  > Did you mean one of these? {similar}")
            print("-" * 50)
            
    return selected_tools

def verify_and_fix_input_params(code_file_path: str, input_data: dict, llm_instance, org_id: Optional[str] = None, subscriber_id: Optional[str] = None) -> tuple[str, bool]:
    """
    Verify if orchestrator code expects the input parameters provided.
    If mismatch found, automatically fix the code using LLM.
    """
    # Read existing code
    with open(code_file_path, 'r', encoding='utf-8') as file:
        existing_code = file.read()
    
    fix_prompt = f"""Update the orchestrator code to work with the actual input/output parameters being provided.

CURRENT CODE:
```python
{existing_code}
```

ACTUAL INPUT DATA:
{json.dumps(input_data, indent=2)}

INSTRUCTIONS:
1. Update all input_data.get() calls to use the ACTUAL parameter names from input_data
2. Map the actual parameters to the logic the code expects
3. If a parameter is missing, use a reasonable default or handle gracefully
4. Keep all tool execution logic and error handling intact
5. Maintain the function signature: def execute_orchestrator(input_data: dict, tool_instances: dict) -> dict
6. Update the output dictionary structure if needed to reflect any changes
7. Make sure the output variables expected are same as outputParamsFormat.

EXAMPLE:
If code has: place = input_data.get('place')
But actual input has: 'city_name' instead of 'place'
Change to: place = input_data.get('city_name')

Return ONLY the complete updated Python function code, no explanations."""

    # Track LLM call
    started_at = datetime.utcnow()
    # Use the passed LLM instance
    fix_response = llm_instance.call(fix_prompt)
    finished_at = datetime.utcnow()
    
    # Record token usage (estimate based on prompt/response length)
    prompt_tokens = len(fix_prompt) // 4
    completion_tokens = len(fix_response) // 4
    total_tokens = prompt_tokens + completion_tokens
    
    record_llm_call(
        org_id=org_id,
        subscriber_id=subscriber_id,
        operation="agent-task",
        sub_operation="verify-fix-input-params",
        model="gemini-3-flash-preview",
        prompt_tokens=prompt_tokens,
        completion_tokens=completion_tokens,
        total_tokens=total_tokens,
        status="success",
        started_at=started_at,
        finished_at=finished_at,
        metadata={"code_file": code_file_path}
    )
    
    # Extract fixed code
    fixed_code = fix_response.strip()
    if fixed_code.startswith('```python'):
        fixed_code = fixed_code.split('```python')[1].split('```')[0].strip()
    elif fixed_code.startswith('```'):
        fixed_code = fixed_code.split('```')[1].split('```')[0].strip()
    
    # Create backup
    backup_path = code_file_path.replace('.py', f'_backup_{int(time.time())}.py')
    with open(backup_path, 'w', encoding='utf-8') as file:
        file.write(existing_code)
    
    # Save fixed code
    with open(code_file_path, 'w', encoding='utf-8') as file:
        file.write(fixed_code)
    
    # Update metadata
    metadata_path = code_file_path.replace('.py', '_metadata.json')
    try:
        if os.path.exists(metadata_path):
            with open(metadata_path, 'r') as f:
                metadata = json.load(f)
            
            if 'fixes' not in metadata:
                metadata['fixes'] = []
            
            metadata['fixes'].append({
                'timestamp': time.time(),
                'backup_path': backup_path,
            })
            metadata['lastUpdated'] = time.time()
            
            with open(metadata_path, 'w') as f:
                json.dump(metadata, f, indent=2)
    except Exception as e:
        print(f"Warning: Could not update metadata: {e}")
    
    print(f'✓ Code fixed and saved. Backup: {backup_path}')
    return code_file_path, True

