@app.post('/aiqod-agent/agent/runnew')
async def exec_agent_code(request: Request):
    """
    Execute saved orchestrator code (Non-Blocking).
    """
    start_time = time.time()
    
    try:
        data = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail={"error": "Invalid JSON body"})
    
    # 1. Parse Data
    input_payload = data.get('input', {})
    code_file_path = input_payload.get('savedAgentPath')
    
    if not code_file_path:
        raise HTTPException(status_code=400, detail={"error": "savedAgentPath not provided"})
    
    # 2. Load Metadata / Tools (Fast I/O)
    metadata_path = code_file_path.replace('.py', '_metadata.json')
    tool_names = []
    try:
        if os.path.exists(metadata_path):
            with open(metadata_path, 'r') as f:
                metadata = json.load(f)
            tool_names = metadata.get('toolNames', [])
    except Exception:
        pass # Handle gracefully
    
    selected_tools = get_tools_by_names(tool_names)
    
    agent_input = input_payload.copy()
    if 'savedAgentPath' in agent_input:
        del agent_input['savedAgentPath']

    # 3. RUN CODE IN THREAD (Non-Blocking Fix)
    loop = asyncio.get_running_loop()
    try:
        output_data = await loop.run_in_executor(
            None,
            _execute_orchestrator_sync, # Call the helper
            code_file_path,
            agent_input,
            selected_tools
            # Note: Removed extra args projectId/botId if they aren't in signature of _execute_orchestrator_sync
            # If your helper needs them, verify its signature. Assuming standard signature from imports.
        )
    except Exception as e:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail={"error": str(e)})

    execution_time = time.time() - start_time
    if 'execution_time' not in output_data:
        output_data['execution_time'] = f'{execution_time:.6f}'

    # 4. Prepare Output & Callback
    orch_output = output_data.get('output', '')
    
    # --- LOGIC FIX START: Parse and Inject StatusCode (Matching Flask) ---
    final_output_params = orch_output

    # Attempt to parse string JSON if needed
    if isinstance(orch_output, str):
        try:
            if orch_output.strip(): # Check if not empty string
                final_output_params = json.loads(orch_output)
            else:
                final_output_params = {}
        except Exception:
            final_output_params = {} # Fallback to empty dict on parse error
    elif orch_output is None:
        final_output_params = {}
    elif isinstance(orch_output, dict):
        final_output_params = orch_output
    else:
        # If it's a list or other type, wrap or leave as is (Flask logic implies dict expectation)
        final_output_params = {}

    # Ensure it is a dictionary before setting statusCode
    if not isinstance(final_output_params, dict):
        final_output_params = {}

    # Inject statusCode exactly like Flask
    if not orch_output:
        final_output_params['statusCode'] = output_data.get('statusCode', '201')
    else:
        final_output_params['statusCode'] = output_data.get('statusCode', '200')
    # --- LOGIC FIX END ---
    
    # Callback logic
    try:
        default_orch = config.get('web_url', '')
        orch_base_url = input_payload.get('orch_url', default_orch)
        if orch_base_url and not orch_base_url.endswith('/'):
            orch_base_url += '/'
            
        ioWriteURL = orch_base_url + 'gibots-orch/orchestrator/botsiowrite'
        
        taskData = {
            'projectId': data.get('projectId'),
            'botId': data.get('botId'),
            'eventId': input_payload.get('eventId'),
            'status': 'Complete',
            'outputParameters': final_output_params,
            'iterationId': data.get('iterationId')
        }
        
        token = data.get('token')
        headers = {'authorization': token, 'content-type': "application/json"}
        
        # Log exactly what Flask logged for verification
        print('output to orch', taskData['outputParameters'])
        
        response = requests.post(
            ioWriteURL, 
            verify=False, 
            data=json.dumps(taskData, default=str), 
            headers=headers
        )
        
        print(f"Response from Server: {response.text}")
        
    except Exception as e:
        print(f"Orchestrator callback failed: {e}")
        traceback.print_exc()
    
    return {
        "success": True,
        "data": {
            "output": output_data.get('output', ''),
            "execution_time": output_data['execution_time'],
            "status": "success" if output_data.get('executionStatus') == 'Success' else "failed",
            "full_output": output_data
        }
    }


