# Helper function to get tools by names
def get_tools_by_names(tool_names: List[str], subscriber_id: Optional[str] = None) -> List:
    """
    Retrieve tool instances by their names, filtered to those the subscriber is allowed to use.
    """
    available_tools = get_available_tools(subscriber_id=subscriber_id)
    selected_tools = []
    
    def normalize(s: str) -> str:
        return s.lower().replace(' ', '').replace('_', '')

    tool_name_map = {
        normalize(tool.name): tool
        for tool in available_tools.values()
    }

    for name in tool_names:
        key = normalize(name)
        if key in tool_name_map:
            selected_tools.append(tool_name_map[key])
        else:
            print('Tool not found:', name)
    
    return selected_tools
