@app.post('/aiqod-agent/agent/toolcreate')
async def create_agent(request: CreateToolRequest):
    try:
        org_id = request.orgId
        subscriber_id = request.subscriberId

        _init_subscriber_billing_if_absent(subscriber_id, org_id=org_id)
        
        # Register the tool
        sample_out = {
            "name": "Prime finder",
            "description": "find if a number is prime",
            "parameters": [
                {
                    "name": "n",
                    "type": "Any",
                    "description": "input number",
                    "required": True
                }
            ],
            "keywords": ["prime finder"],
            "function_code": "if n <= 1:\n    return False\nelse:\n    is_prime = True\n    for i in range(2, int(math.sqrt(n)) + 1):\n        if n % i == 0:\n            isPrime=False\n            break\n    return isPrime",
            "imports": ["import math","from typing import Any"]
        }
        prompt = f'''Create a python code using this instruction.
        Name: {request.name}
        Description: {request.description}
        Instruction: {request.instructions}

        and return the output in following json format.

        Sample output format:
        {json.dumps(sample_out,indent=2)}

        Instructions:
        1. Populate the imports only if necessary.
        2. Include 'from typing import Any' in imports always.
        3. Makesure the indents(4 space) and newline is correctly placed in function_code.
        4. Makesure the code and type mentioned are according to python standards.
        5. function_code should directly start with the code and not the function name definition.
        Respond only the json.
        Parameters put type as Any for all.
        '''
        
        # Track LLM call
        started_at = datetime.utcnow()
        response = (await async_llm_call(prompt)).strip()
        finished_at = datetime.utcnow()
        
        # Record token usage (estimate based on prompt/response length)
        prompt_tokens = len(prompt) // 4
        completion_tokens = len(response) // 4
        total_tokens = prompt_tokens + completion_tokens
        
        record_llm_call(
            org_id=org_id,
            subscriber_id=subscriber_id,
            operation="agent-task",
            sub_operation="tool-create",
            model="gemini-3.6-flash",
            prompt_tokens=prompt_tokens,
            completion_tokens=completion_tokens,
            total_tokens=total_tokens,
            status="success",
            started_at=started_at,
            finished_at=finished_at,
            metadata={"tool_name": request.name[:100]}
        )
        
        print('Default values response:', response)
        regex_pattern = r'```json(.*?)```'
        match = re.findall(regex_pattern, response, flags=re.S)
        success = False
        if match:
            try:
                default_values = json.loads(match[0].strip())
                default_values['name'] = default_values['name'].replace(' ','')
                success = True
            except json.JSONDecodeError as e:
                print(f"Error decoding JSON: {e}")
        if success:
            return {
                'success': True,
                'message': f'Tool "{request.name}" created successfully',
                'tool_name': request.name,
                'tool': default_values,
                'status':200
            }
        else:
            raise HTTPException(status_code=500, detail={
                'success': False,
                'error': 'Failed to register tool'
            })

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail={
            'success': False,
            'error': str(e)
        })

def _run_crew_sync_wrapper(crew_instance):
    """Simple wrapper to run crew kickoff in thread"""
    return crew_instance.kickoff()


@app.post('/aiqod-agent/agent/tooltest')
async def run_tool(request: TestToolRequest):
    start_time = time.time()
    tool = request.tool
    input_data = request.input

    if not tool:
        raise HTTPException(status_code=404, detail={"error": "Tool not found"})

    success = register_tool(tool,save=False)
    if (success):
        # Subscriber tools (keys ending with _sb_<shortId>) are omitted unless subscriber_id matches.
        available_tools = get_available_tools(subscriber_id=request.subscriberId)
        selected_tools = []
        if tool['name'] in available_tools:
            selected_tools = [available_tools[tool['name']]]
        if not selected_tools:
            raise HTTPException(status_code=400, detail={'status': 400, 'error': f"No valid tools found for task {tool['description']}"})
        tool_desc = tool['name']
        task_description = tool['description']
        agent = Agent(
            role="Orchestrator",
            goal=f"Chain the tools ({tool_desc}) to {task_description}",
            backstory="You are a reasoning agent that uses multiple custom tools in sequence to complete tasks.",
            tools=selected_tools,
            llm=llm,
            verbose=True
        )


        task = Task(
            description=f'Description:{task_description}\nInput:{input_data}',
            expected_output="String",
            agent=agent
        )

        crew = Crew(
            agents=[agent],
            tasks=[task]
        )

        crew_output = await run_sync(_run_crew_sync_wrapper, crew)
        task_output = task.output
        print(f"Task Description: {task_output.description}")
        print(f"Task Summary: {task_output.summary}")
        print(f"Raw Output: {task_output.raw}")
        if task_output.json_dict:
            print(f"JSON Output: {json.dumps(task_output.json_dict, indent=2)}")
        if task_output.pydantic:
            print(f"Pydantic Output: {task_output.pydantic}")

        execution_time = time.time() - start_time

        return {"success":True,"data":{"output": task_output.raw,"execution_time":f'{execution_time:.6f}',"status":"success"}}
    else:
        raise HTTPException(status_code=400, detail={"success":False})



