@app.post('/aiqod-agent/agent/getconfigs')
async def fetchConfig(request: GetConfigsRequest):
    try:

        collection = db['Process_Configs']
        users_collection = db['users']

        # 1. Check User Role
        user_info = users_collection.find_one({"_id": ObjectId(request.userId)})
        is_subscriber = False
        if user_info and user_info.get('type') == 'taxpayer':
            is_subscriber = True

        # 2. Fetch All Organization Documents (Required for merging)
        # We fetch everything under the Organization first
        org_docs = list(collection.find({
            "orgId": ObjectId(request.orgId),
            "subscriberId": ObjectId(request.subscriberId)
        }))

        if not org_docs:
             raise HTTPException(status_code=404, detail={'status': 404, 'error': 'No process configurations found'})

        # 3. Determine the "Base" Document
        # If Standard User: We MUST find their specific document to return their specific ID/metadata.
        # If Subscriber: We can use their doc if it exists, otherwise just the first one found.
        target_doc = None
        for doc in org_docs:
            if str(doc.get('userId')) == request.userId:
                target_doc = doc
                break
        
        # If user has no doc yet (but others exist), we still need a base structure
        if not target_doc:
            if not is_subscriber:
                # Standard user with no doc -> 404 (or return empty structure if preferred)
                raise HTTPException(status_code=404, detail={'status': 404, 'error': 'No configuration found for this user'})
            target_doc = org_docs[0] # Subscriber can view others' structure

        # 4. Merge Lists Based on Role
        final_specialist_agents = []
        final_process_configs = []
        
        # Helper to track duplicates
        seen_templates = set()

        for doc in org_docs:
            # A. Specialist Agents (categoryConfigs): SHARED for Everyone
            for agent in doc.get('categoryConfigs', []):
                t_name = agent.get('templateName')
                if t_name and t_name not in seen_templates:
                    final_specialist_agents.append(agent)
                    seen_templates.add(t_name)
                elif not t_name:
                    final_specialist_agents.append(agent)

            # B. AI Agents (processConfigs): MERGED for Subscriber, PRIVATE for User
            if is_subscriber:
                # Subscriber sees everyone's processes
                final_process_configs.extend(doc.get('processConfigs', []))
        
        # If Standard User, they only see what is inside their own 'target_doc'
        if not is_subscriber:
            final_process_configs = target_doc.get('processConfigs', [])
        
        workflow_collection = db['Workflow_details']
        for p_config in final_process_configs:
            p_config['isProductionReady'] = False 
            
            # 2. Update it if the workflow exists in the DB
            if p_config.get('workflow_id'):
                wf_doc = workflow_collection.find_one({"workflow_json.workflowId": p_config['workflow_id']})
                if wf_doc:
                    p_config['isProductionReady'] = wf_doc.get('isProductionReady', False)

        # 5. Prepare Response
        # Copy target doc to avoid mutating DB cache
        response_data = copy.deepcopy(target_doc)
        response_data['categoryConfigs'] = final_specialist_agents
        response_data['processConfigs'] = final_process_configs

        return json.loads(json.dumps({'status': 200, 'data': response_data}, default=str))

    except HTTPException:
        raise
    except Exception as e:
        print(f"Error fetching process config: {e}")
        raise HTTPException(status_code=400, detail={'status': 400, 'error': str(e)})


def safe_object_id(oid_str):
    if not oid_str:
        return None
    try:
        return ObjectId(oid_str)
    except (TypeError, ValueError, bson.errors.InvalidId):
        return None

@app.get("/aiqod-agent/agent/configmetadata")
def get_config_metadata(
    subscriberId: str = Header(..., alias="subscriberid"),
    orgId: str = Header(..., alias="selectedorgid")
):
    try:
        s_id = safe_object_id(subscriberId)
        o_id = safe_object_id(orgId)
        
        if not s_id or not o_id:
            return {"status": 200, "data": []}
            
        query = {
            "subscriberId": s_id,
            "orgId": o_id,
            "agentic_process.kind": {"$ne": "dashboard"}
        }
            
        projection = {
            "_id": 0,
            "selectedCategory": 1,
            "selectedName": 1,
            "selectedType": 1,
            "agentic_process": 1
        }
        
        cursor = db.Process_Configs.find(query, projection)
        results = list(cursor)
        
        return {"status": 200, "data": serialize_mongo_document(results)}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/aiqod-agent/agent/configdetails")
def get_config_details(
    workflow_id: str = Header(..., alias="workflow-id")
):
    try:
        clean_workflow_id = workflow_id.strip()
        query = {
            "agentic_process.workflow_id": clean_workflow_id
        }

        result = db.Process_Configs.find_one(query)
        serialized_result = serialize_mongo_document(result) if result else None
        linked_query = {
            "agentic_process.linkedWorkflowId": clean_workflow_id
        }
        linked_doc = db.Process_Configs.find_one(linked_query)
        if linked_doc and serialized_result:
            linked_report = linked_doc.get("agentic_process", {}).get("report")
            dashboardScreenId = linked_doc.get("agentic_process", {}).get("dashboardScreenId")
            if linked_report:
                if "agentic_process" not in serialized_result:
                    serialized_result["agentic_process"] = {}
                serialized_result["agentic_process"]["reports"] = linked_report
                serialized_result["agentic_process"]["dashboardScreenId"] = dashboardScreenId
                serialized_result["agentic_process"]["dashboardworkflowId"] = linked_doc.get("agentic_process", {}).get("workflow_id")
                serialized_result["agentic_process"]["dashboardUrl"] = linked_doc.get("agentic_process", {}).get("dashboardUrl")
                

        return {"status": 200, "data": serialized_result}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))




x, y = 505, 65

def generate_xml_data(input_array):
    global x, y

    # Create root element
    root = Element('mxGraphModel')
    graph_root = SubElement(root, 'root')

    # Add default cells
    SubElement(graph_root, 'mxCell', {'id': '0'})
    SubElement(graph_root, 'mxCell', {'id': '1', 'parent': '0'})

    for index, item in enumerate(input_array):
        cell = SubElement(graph_root, 'mxCell', {
            'id': str(item['graphId']),
            'value': item['statusName']
        })

        # Calculate position
        if index == 0:
            x = str(x)
            y = str(y)
        elif index % 2 == 0:
            x = str(int(x) - 50)
            y = str(int(y) + 90)
        else:
            x = str(int(x) + 50)
            y = str(int(y) + 90)

        if item['statusName'] == "End":
            x = "1000"

        geometry = SubElement(cell, 'mxGeometry', {
            'x': x,
            'y': y,
            'width': '140',
            'height': '50',
            'as': 'geometry'
        })

        if item['category'] == "conditional-loop":
            cell.set('edge', '1')
            cell.set('parent', '1')
            geometry.set('relative', '1')
        else:
            cell.set('vertex', '1')
            cell.set('parent', '1')

            # Set styles based on category
            if item['statusName'] in ["Start", "End"]:
                cell.set('style',
                    "whiteSpace=wrap;fillColor=white;strokeColor=#80FF00;fontColor=black;rounded=1;arcSize=50;strokeWidth=2;")
            elif item['category'] == "conditional":
                cell.set('style',
                    "shape=rhombus;perimeter=rhombusPerimeter;fillColor=white;strokeColor=#9ecaed;fontColor=black")
            elif item['category'] in ["startLoop", "endLoop"]:
                cell.set('style',
                    "whiteSpace=wrap;fillColor=white;fontColor=black;shape=ellipse;perimeter=ellipsePerimeter;strokeWidth=2;")
            else:
                cell.set('style',
                    "shape=image;image=data:image/png,;align=center;fontColor=#000000;imageAlign=center;imageHeight=108;imageVerticalAlign=top;imageWidth=108;spacing=8;spacingTop=56;strokeColor=#000000;verticalAlign=top;")

        # Handle conditional-loop edges
        if item['category'] == "conditional-loop":
            cell.set('edge', '1')
            cell.set('source', str(item['orPredecessor'][0]))
            cell.set('target', str(item['successor'][0]))
            cell.set('style', 'edgeStyle=orthogonalEdgeStyle;')

        # Handle other edges (successors)
        if item['category'] != "conditional-loop" and item['statusName'] != "End":
            for successor in item['successor']:
                cell_id = random.randint(100000, 999999)
                edge_cell = SubElement(graph_root, 'mxCell', {
                    'id': str(cell_id),
                    'value': ''
                })
                edge_cell.set('edge', '1')
                edge_cell.set('parent', '1')

                edge_geometry = SubElement(edge_cell, 'mxGeometry', {
                    'x': x,
                    'y': y,
                    'width': '140',
                    'height': '50',
                    'as': 'geometry'
                })
                edge_geometry.set('relative', '1')

                edge_cell.set('source', str(item['graphId']))
                if successor:
                    edge_cell.set('target', str(successor))
                edge_cell.set('style',
                    'edgeStyle=orthogonalEdgeStyle;orthogonalLoop=1;jettySize=auto;html=1;startArrow=classic;startFill=1;targetPerimeterSpacing=8;sourcePerimeterSpacing=8;strokeColor=#aaaaaa;strokeWidth=2;curved=1;')

    return root

def prettify_xml(elem):
    """Return a pretty-printed XML string for the Element."""
    rough_string = tostring(elem, 'unicode')
    reparsed = minidom.parseString(rough_string)
    return reparsed.toprettyxml(indent="  ")

