def generate_numeric_id():
    """Generate a numeric ID between 1000000000000 and 9999999999999"""
    return random.randint(1000000000000, 9999999999999)

def create_workflow_nodes_llm(maintasks):
    try:
        """
        Generate workflow nodes including start, main task, and end nodes.

        Args:
            main_task (dict): The main task configuration dictionary

        Returns:
            list: A list containing [main_task, start_node, end_node]
        """

        print('Creating workflow nodes for LLM',len(maintasks))
        def generate_numeric_id():
            """Generate a numeric ID between 1000000000000 and 9999999999999"""
            return random.randint(1000000000000, 9999999999999)

        # Create Start Node

        start_bot_id = generate_numeric_id()

        start_node = {

            "taskTitle": "Start",
            "botShape": "start",
            "graphId": str(start_bot_id),
            "inputParameters": copy.deepcopy(maintasks[0]["inputParameters"]),
            "outputParameters": copy.deepcopy(maintasks[0]["outputParameters"]),
            "successor": [maintasks[0]["botId"]],
            "andPredecessor": [],
            "orPredecessor": [],
            "isDeleted": False,
            "isDependent": False,
            "isProcessActive": False,
            "conditionResult": {"true": [], "false": []},
            "botId": start_bot_id,
            "isStart": True,
            "isEnd": False,
            "statusName": "Start",
            "isSaveMapping": False,
            "leaf": True,
            "isBack": False,
            "category": ""
        }
        print('created start')

        # Create End Node
        end_bot_id = generate_numeric_id()

        end_node = {
            "taskTitle": "End",
            "botShape": "end",
            "graphId": str(end_bot_id),
            "inputParameters": copy.deepcopy(maintasks[len(maintasks)-1]["inputParameters"]),
            "outputParameters": copy.deepcopy(maintasks[len(maintasks)-1]["outputParameters"]),
            "successor": [],
            "andPredecessor": [maintasks[len(maintasks)-1]["botId"]],
            "orPredecessor": [],
            "isDeleted": False,
            "isDependent": False,
            "isProcessActive": False,
            "conditionResult": {"true": [], "false": []},
            "botId": end_bot_id,
            "isStart": False,
            "isEnd": True,
            "statusName": "End",
            "isSaveMapping": True,
            "botMappingList": [
                {
                    "label": "empty",
                    "value": param["name"],
                    "category": ""
                }
                for param in maintasks[len(maintasks)-1]["inputParameters"]
            ],
            "isProcess": True,
            "botsRelation": "",
            "conditionReslt": "",
            "leaf": True,
            "isBack": False,
            "category": ""
        }

        print ('Created start and end node')


        for i,task in enumerate(maintasks):
            if i < len(maintasks) - 1:
                task["successor"] = [maintasks[i + 1]["botId"]]
            else:
                task["successor"] = [end_node["botId"]]
            task["andPredecessor"] = [start_node["botId"]] if i == 0 else [maintasks[i - 1]["botId"]]
            task["orPredecessor"] = []
            task["leaf"] = True
            task["isBack"] = False
            # task["isProcessActive"] = False
            # task["conditionResult"] = {"true": [], "false": []}
        # main_task["orPredecessor"] = []

        # main_task["leaf"] = True

        return [ start_node, *maintasks, end_node]
    except Exception as e:
        print(f"Error creating workflow nodes: {e}")
        return []


async def bot_level_addinfo_and_default_value_assign(bot_data,tool,db):
    if 'uiComponent' in bot_data:
        additional_details = tool['details']
        if additional_details:
            identify_templatenameprompt = f'From this information, identify the template name: {additional_details}. Return only the name of the template. It should be explicitly mentioned in the information. If not, return an empty string.'
            print('here')
            try:
                started_at_tpl = datetime.utcnow()
                response = (await async_llm_call(identify_templatenameprompt)).strip()
                # response = llm.call(identify_templatenameprompt).strip()
                finished_at_tpl = datetime.utcnow()
                record_llm_call(
                    org_id=None,
                    subscriber_id=None,
                    operation="agent-task",
                    sub_operation="bot-identify-template-name",
                    model="gemini-3-flash-preview",
                    prompt_tokens=len(identify_templatenameprompt) // 4,
                    completion_tokens=len(response) // 4 if response else 0,
                    total_tokens=len(identify_templatenameprompt) // 4 + (len(response) // 4 if response else 0),
                    status="success",
                    started_at=started_at_tpl,
                    finished_at=finished_at_tpl,
                    metadata={"details_preview": (additional_details or "")[:100]},
                )
            except Exception as e:
                print(e)
                response = ''
            print(response)
            if(response):
                print('Found template name:', response)
                additional_info = db['additionalinfos'].find_one({"templateName": response, "isDeleted": False})
                if additional_info:
                    variable_list = additional_info['additionalInfo']
                    for item in variable_list:
                        name = item['name']
                        dataType = item.get('dataType', 'Any')
                        bot_data['inputParameters'].append({"tags": [], "name": name, "type": item['type'], "regex": "", "value": "","label":name, "displayName": name})
                        bot_data['outputParameters'].append({"tags": [], "name": name, "type": item['type'], "regex": "", "value": "","label":name, "displayNameOutput": name})
                    bot_data['templateId'] = additional_info['_id']
    input_params = [param['name'] for param in bot_data['inputParameters']]
    defaultvalues_prompt = f'From this information, identify the default values for the input parameters:{input_params} using this information {tool["details"]}. Return a JSON object with parameter names as keys and their default values as values. If not mentioned explicitly, set the value to "".'
    started_at_def = datetime.utcnow()
    # response = llm.call(defaultvalues_prompt).strip()
    response = (await async_llm_call(defaultvalues_prompt)).strip()
    finished_at_def = datetime.utcnow()
    record_llm_call(
        org_id=None,
        subscriber_id=None,
        operation="agent-task",
        sub_operation="bot-default-values",
        model="gemini-3-flash-preview",
        prompt_tokens=len(defaultvalues_prompt) // 4,
        completion_tokens=len(response) // 4 if response else 0,
        total_tokens=len(defaultvalues_prompt) // 4 + (len(response) // 4 if response else 0),
        status="success",
        started_at=started_at_def,
        finished_at=finished_at_def,
        metadata={"input_params_preview": str(input_params)[:100]},
    )
    print('Default values response:', response)
    regex_pattern = r'```json(.*?)```'
    match = re.findall(regex_pattern, response, flags=re.S)
    if match:
        try:
            default_values = json.loads(match[0].strip())
            for i,param in enumerate(bot_data['inputParameters']):
                if param['name'] in default_values and default_values[param['name']]:
                    param['value'] = default_values[param['name']]
            print(bot_data['inputParameters'])
        except json.JSONDecodeError as e:
            print(f"Error decoding JSON: {e}")

    return bot_data


