def save_orchestrator_code(code: str, tasks, saved_processconfig) -> str:
    """
    Save the generated orchestrator code to a file
    """
    # Determine save path
    find_saved_process_config = []
    if saved_processconfig:
        logger.info("save_orchestrator_code: checking saved_processconfig for existing orchestrator file")
        # Safely check if processConfigs exists and is a list
        if isinstance(saved_processconfig, dict) and 'processConfigs' in saved_processconfig:
            process_configs = saved_processconfig['processConfigs']
            if isinstance(process_configs, list):
                find_saved_process_config = [
                    config_item for config_item in process_configs 
                    if isinstance(config_item, dict) and config_item.get('idRef') == tasks.get('idRef')
                ]
                logger.info(f"save_orchestrator_code: found {len(find_saved_process_config)} matching config(s) for idRef: {tasks.get('idRef')}")
            else:
                logger.warning(f"save_orchestrator_code: processConfigs is not a list (type: {type(process_configs).__name__})")
        else:
            logger.warning("save_orchestrator_code: saved_processconfig missing 'processConfigs' key or not a dict")
    else:
        logger.info("save_orchestrator_code: no saved_processconfig found, will create new orchestrator file")
    
    if find_saved_process_config and isinstance(find_saved_process_config[0], dict) and 'codeFilePath' in find_saved_process_config[0]:
        code_file_path = find_saved_process_config[0]['codeFilePath']
        logger.info(f"save_orchestrator_code: reusing existing orchestrator file: {code_file_path}")
    else:
        timestamp = int(time.time())
        code_file_path = f"{config['code_savepath']}orchestrator_{timestamp}.py"
        logger.info(f"save_orchestrator_code: creating new orchestrator file: {code_file_path}")
    
    # Save code to file
    with open(code_file_path, 'w', encoding='utf-8') as file:
        file.write(code)
    
    print(f"Orchestrator code saved to {code_file_path}")
    return code_file_path


async def convert_tool_to_orchestrator_code(tasks, saved_processconfig, selected_tools, org_id: Optional[str] = None, subscriber_id: Optional[str] = None, process_execution_id: Optional[str] = None):
    """
    Main function to generate and save orchestrator code
    Replaces convert_tool_to_agent function
    """
    
    # Generate orchestrator code using LLM (one-time cost)
    orchestrator_code = await generate_orchestrator_code(
        tasks, 
        selected_tools, 
        llm,
        org_id=org_id,
        subscriber_id=subscriber_id,
        process_execution_id=process_execution_id
    )
    
    # Save the code
    code_file_path = save_orchestrator_code(orchestrator_code, tasks, saved_processconfig)
    
    # Save tool names for later retrieval
    tool_names = [tool['name'] if isinstance(tool, dict) else tool.name for tool in selected_tools]

    
    # Save metadata
    metadata = {
        'idRef': tasks['idRef'],
        'taskName': tasks['taskName'],
        'taskDescription': tasks['instructionToLLM'],
        'codeFilePath': code_file_path,
        'toolNames': tool_names,
        'createdAt': time.time()
    }
    
    metadata_path = code_file_path.replace('.py', '_metadata.json')
    logger.info(f'code path,{code_file_path}')
    with open(metadata_path, 'w', encoding='utf-8') as file:
        json.dump(metadata, file, indent=2)
    
    return code_file_path, metadata_path


def convert_tool_to_agent(tasks, saved_processconfig, selected_tools):
    tool_desc = ", ".join([f"{tool.name}" for tool in selected_tools])


    task_description = tasks['taskName'] + 'Instructions: ' + tasks['instructionToLLM']
    orch_agent = Agent(
        role="Orchestrator",
        goal=f"Chain the tools ({tool_desc}) to {task_description}. {tasks['instructionToLLM']}",
        backstory="You are a reasoning agent that uses multiple custom tools in sequence to complete tasks.",
        tools=selected_tools,
        llm=llm,
        verbose=True
    )
    find_saved_process_config = []
    if saved_processconfig:
        logger.info("convert_tool_to_agent: checking saved_processconfig for existing agent yaml")
        # Safely check if processConfigs exists and is a list
        if isinstance(saved_processconfig, dict) and 'processConfigs' in saved_processconfig:
            process_configs = saved_processconfig['processConfigs']
            if isinstance(process_configs, list):
                find_saved_process_config = [
                    config for config in process_configs 
                    if isinstance(config, dict) and config.get('idRef') == tasks.get('idRef')
                ]
                logger.info(f"convert_tool_to_agent: found {len(find_saved_process_config)} matching config(s) for idRef: {tasks.get('idRef')}")
            else:
                logger.warning(f"convert_tool_to_agent: processConfigs is not a list (type: {type(process_configs).__name__})")
        else:
            logger.warning("convert_tool_to_agent: saved_processconfig missing 'processConfigs' key or not a dict")
    else:
        logger.info("convert_tool_to_agent: no saved_processconfig found, will create new agent yaml")
    
    if find_saved_process_config and isinstance(find_saved_process_config[0], dict) and 'yamlFilePath' in find_saved_process_config[0]:
        yaml_file_path = find_saved_process_config[0]['yamlFilePath']
        logger.info(f"convert_tool_to_agent: reusing existing agent yaml: {yaml_file_path}")
    else:
        yaml_file_path = f'{config["agent_savepath"]}myagent_{orch_agent.id}.yaml'
        logger.info(f"convert_tool_to_agent: creating new agent yaml: {yaml_file_path}")
    
    # Ensure the agents directory exists
    os.makedirs(config["agent_savepath"], exist_ok=True)
    
    agents_data = {}
    agent_config = _extract_agent_config(orch_agent)

    # Add to agents data
    agents_data[orch_agent.role] = agent_config

    # Save to YAML file
    with open(yaml_file_path, 'w', encoding='utf-8') as file:
        yaml.dump(agents_data, file, default_flow_style=False, indent=2)

    print(f"Agent '{orch_agent.role}' saved to {yaml_file_path}")
    return yaml_file_path, task_description, find_saved_process_config

