async def assign_bot(bot_data, details, org_id: Optional[str] = None, subscriber_id: Optional[str] = None):
    prompt = f"""Using this instruction provided by the user: '{details}', understand if the details mention about users or roles. If yes provide the usernames or rolenames in the json format.
    Sample output:
    {{"users": ["user1", "user2"], "roles": ["role1", "role2"]}}
    If no users or roles are mentioned, return empty lists."""
    print('her')
    
    # Track LLM call
    started_at = datetime.utcnow()
    response = (await async_llm_call(prompt)).strip()
    finished_at = datetime.utcnow()
    
    # Record token usage (estimate based on prompt/response length)
    prompt_tokens = len(prompt) // 4
    completion_tokens = len(response) // 4
    total_tokens = prompt_tokens + completion_tokens
    
    record_llm_call(
        org_id=org_id,
        subscriber_id=subscriber_id,
        operation="agent-task",
        sub_operation="assign-bot",
        model="gemini-3-flash-preview",
        prompt_tokens=prompt_tokens,
        completion_tokens=completion_tokens,
        total_tokens=total_tokens,
        status="success",
        started_at=started_at,
        finished_at=finished_at,
        metadata={"details": details[:100] if details else ""}
    )
    
    print('Assign bot response:', response)
    regex_pattern = r'```json(.*?)```'
    match = re.findall(regex_pattern, response, flags=re.S)
    if match:
        try:
            assign_data = json.loads(match[0].strip())
            users = assign_data.get('users', [])
            roles = assign_data.get('roles', [])
            print ('Parsed assign data:', assign_data)
            user_details = []
            for user in users:

                user_obj = db['users'].find_one({
                    "personalInfo.name": {
                        "$regex": user,
                        "$options": "i"
                    },
                    "isDeleted": False
                })
                if user_obj:
                    print('Found user:', user_obj['personalInfo']['name'])
                    user_details.append({"_id": str(user_obj['_id']), "name": user_obj['personalInfo']['name'], "type": "users"})

            if user_details:
                for det in user_details:
                    if not 'selectedAssignToList' in bot_data:
                        bot_data['selectedAssignToList'] = []
                        bot_data['selectedAssignToName'] = []
                    bot_data['selectedAssignToName'].append(det['name'])
                    bot_data['selectedAssignToList'].append(det['_id'])

            if roles:
                bot_data['selectedRoleList'] = roles


            print('Final assigned details:', json.dumps(bot_data,default=str))
        except json.JSONDecodeError as e:
            print(f"Error decoding JSON: {e}")
    return bot_data

async def enrich_rule_descriptions(rules, description, org_id=None, subscriber_id=None):
    """
    Pre-processes each rule's description + message into a structured, 
    code-generation-ready prompt saved in rule['enrichedDescription'].
    Runs before generate_ruleexpression_new.
    """
    local_llm = LLM(
        model="gemini-3-flash-preview",
        provider="gemini",
        temperature=0.0,
        api_key=get_gemini_api_key()
    )

    for rule in rules:
        prompt = f"""You are a technical specification writer for Python code generation.

Convert the rule description and message below into a detailed, structured implementation spec
that a code generator can follow precisely to write Python code.

**Global Context (data model + business rules):**
{description}

**Rule Name:** {rule['ruleName']}

**User Rule Description:**
{rule['ruleDescription']}

**User Expected Message/Output Format:**
{rule.get('message', 'Not specified')}

**Your task:**
Produce a numbered, step-by-step implementation spec that covers:
1. What fields to read from `input_data` (with exact key names)
2. What MongoDB collections to query and with what filters
3. What logic/conditions to apply (if/else, comparisons, calculations)
4. What to write back to `input_data` (field name + value)
5. When to append to `DocumentLevelError` and `DocumentLevelException` (exact field_name + message format)
6. Edge cases: missing fields, empty values, no DB match, conversion failures

**Rules for the spec:**
- Use exact field names from the global context and rule description
- Be explicit about numeric conversions (float/int) and string cleaning steps
- Specify the exact error/exception message format using the user's message as reference
- Keep it concise but complete — no vague instructions like "handle errors"
- Do NOT write Python code — write a numbered spec only

Return ONLY the numbered spec, no preamble:"""

        try:
            started_at = datetime.utcnow()
            enriched = (await run_sync(local_llm.call, prompt)).strip()
            finished_at = datetime.utcnow()

            prompt_tokens = len(prompt) // 4
            completion_tokens = len(enriched) // 4

            record_llm_call(
                org_id=org_id,
                subscriber_id=subscriber_id,
                operation="agent-task",
                sub_operation="enrich-rule-description",
                model="gemini-3-flash-preview",
                prompt_tokens=prompt_tokens,
                completion_tokens=completion_tokens,
                total_tokens=prompt_tokens + completion_tokens,
                status="success",
                started_at=started_at,
                finished_at=finished_at,
                metadata={"rule_name": rule.get('ruleName', '')[:100]}
            )

            rule['enrichedDescription'] = enriched
            print(f"[enrich_rule_descriptions] '{rule['ruleName']}' enriched successfully")

        except Exception as e:
            print(f"[enrich_rule_descriptions] Error for rule '{rule.get('ruleName')}': {e}")
            # Fallback — use original description so generation still works
            rule['enrichedDescription'] = rule.get('ruleDescription', '')
            record_llm_call(
                org_id=org_id, subscriber_id=subscriber_id,
                operation="agent-task", sub_operation="enrich-rule-description",
                model="gemini-3-flash-preview",
                prompt_tokens=0, completion_tokens=0, total_tokens=0,
                status="failed",
                metadata={"rule_name": rule.get('ruleName', '')[:100], "error": str(e)}
            )

    return rules

async def generate_ruleexpression(rules, description, org_id: Optional[str] = None, subscriber_id: Optional[str] = None):
    local_llm = LLM(
        model="gemini-3-flash-preview",
        provider="gemini",
        temperature=0.0,
        api_key=get_gemini_api_key()
    )
    for rule in rules:
        # ================================================================
        # PASS 1: Generate additionalInfoCode (existing logic, unchanged)
        # ================================================================
        prompt = f"""You are a Python code generator for data processing rules. Generate executable Python code based on the rule description below.

        **Global Context:**
        {description}

        **Rule Name:** {rule['ruleName']}

        **Rule Description:**
        {rule['ruleDescription']}

        **Requirements:**
        1. The code must be executable within the provided safe_globals environment
        2. Available variables: `db` (MongoDB database), `input_data` (dict), `datetime`, `timedelta`, `json`, `re`
        3. You can access MongoDB collections using: `db['collection_name']`
        4. Store the final result in a variable called `additional_data`
        5. The result should be a dict, list, or simple value that will be appended to input_data['additional_data']
        6. Handle errors gracefully with try-except blocks
        7. Add clear comments explaining each step
        8. Use MongoDB queries like: `db['collection_name'].find_one({{'field': value}})`
        9. For string operations, use Python's built-in methods
        10. Do NOT include any markdown formatting, backticks, or explanatory text - ONLY the Python code
        11. Consider the global context when interpreting field names, collection names, and business logic
        12. The global description provides overall context about the data model and business rules that apply to all rules
        13. **CRITICAL - Numeric Field Handling:** If numeric fields are involved from input_data, you MUST:
            - First check if the field exists in input_data
            - Check if the value is not None
            - Check if the value is not an empty string ('')
            - Only then convert to appropriate numeric type (int() or float())
            - Example pattern:
        ```
            value = input_data.get('field_name')
            if value is not None and value != '':
                numeric_value = float(value)  # or int(value)
                # Now use numeric_value for comparison or calculation
        ```
            - Always handle conversion errors with try-except
            - This applies to ALL numeric comparisons, calculations, and operations
        14. If no external information is needed, respond with the single, exact line: additional_data = None

        **Code Structure:**
        ```python
        # Step-by-step implementation
        try:
            # Your code here
            additional_data = {{}}  # Final result
        except Exception as e:
            additional_data = {{'error': str(e), 'rule': '{rule['ruleName']}' }}
        ```

        Generate ONLY the Python code without explanations:"""
        try:
            started_at = datetime.utcnow()
            cleaned_response = (await run_sync(local_llm.call, prompt)).strip()
            finished_at = datetime.utcnow()
            
            prompt_tokens = len(prompt) // 4
            completion_tokens = len(cleaned_response) // 4
            total_tokens = prompt_tokens + completion_tokens
            
            record_llm_call(
                org_id=org_id,
                subscriber_id=subscriber_id,
                operation="agent-task",
                sub_operation="generate-rule-expression",
                model="gemini-3-flash-preview",
                prompt_tokens=prompt_tokens,
                completion_tokens=completion_tokens,
                total_tokens=total_tokens,
                status="success",
                started_at=started_at,
                finished_at=finished_at,
                metadata={"rule_name": rule.get('ruleName', '')[:100]}
            )
            
            regex_pattern = r'```python(.*?)```'
            match = re.findall(regex_pattern, cleaned_response, flags=re.S)
            if match:
                rule['additionalInfoCode'] = match[0]
            else:
                rule['additionalInfoCode'] = str(cleaned_response)
                rule['rulefailed'] = 'true'

        except Exception as error:
            print('Error while generating rule')
            rule['additionalInfoCode'] = ''
            rule['rulefailed'] = error
            record_llm_call(
                org_id=org_id,
                subscriber_id=subscriber_id,
                operation="agent-task",
                sub_operation="generate-rule-expression",
                model="gemini-3-flash-preview",
                prompt_tokens=0,
                completion_tokens=0,
                total_tokens=0,
                status="failed",
                metadata={"rule_name": rule.get('ruleName', '')[:100], "error": str(error)}
            )

    # ================================================================
    # PASS 2: Generate inputSchema ONCE at rule-set level
    # Aggregate all rule descriptions + generated code together
    # ================================================================
    rules_summary = "\n\n".join([
        f"Rule '{r['ruleName']}':\n"
        f"  Description: {r['ruleDescription']}\n"
        f"  Code:\n{r.get('additionalInfoCode', '# not available')}"
        for r in rules
    ])

    schema_prompt = f"""Analyze these data rules to extract the combined input field requirements for the entire rule set.

Global Context: {description}

Rules:
{rules_summary}

A field is "required" if any rule reads it from `input_data` and cannot produce a meaningful result without it.

Return ONLY a JSON object, no markdown:
{{
    "required": ["field1", "field2"],
    "fieldMap": {{
        "field1": "collection.nested.path",
        "field2": "collection.nested.path"
    }},
    "optional": ["field3"],
    "description": "one line summary of what input this rule set needs"
}}

If no fields are required: {{"required": [], "fieldMap": {{}}, "optional": [], "description": "No input fields required"}}"""

    try:
        started_at = datetime.utcnow()
        schema_response = (await run_sync(local_llm.call, schema_prompt)).strip()
        finished_at = datetime.utcnow()

        prompt_tokens = len(schema_prompt) // 4
        completion_tokens = len(schema_response) // 4

        record_llm_call(
            org_id=org_id,
            subscriber_id=subscriber_id,
            operation="agent-task",
            sub_operation="generate-rule-input-schema",
            model="gemini-3-flash-preview",
            prompt_tokens=prompt_tokens,
            completion_tokens=completion_tokens,
            total_tokens=prompt_tokens + completion_tokens,
            status="success",
            started_at=started_at,
            finished_at=finished_at,
            metadata={"rules_count": len(rules)}
        )

        schema_response = re.sub(r'```json|```', '', schema_response).strip()
        start_idx = schema_response.find('{')
        end_idx = schema_response.rfind('}') + 1

        if start_idx != -1 and end_idx > start_idx:
            input_schema = json.loads(schema_response[start_idx:end_idx])
            print(f"[inputSchema] Rule set schema generated: required={input_schema.get('required', [])}")
        else:
            input_schema = {"required": [], "fieldMap": {}, "optional": [], "description": "Could not parse schema"}
            print("[inputSchema] Schema parse failed, using empty fallback")

    except Exception as schema_error:
        print(f"[inputSchema] Error generating rule set schema: {schema_error}")
        input_schema = {"required": [], "fieldMap": {}, "optional": [], "description": str(schema_error)}
        record_llm_call(
            org_id=org_id,
            subscriber_id=subscriber_id,
            operation="agent-task",
            sub_operation="generate-rule-input-schema",
            model="gemini-3-flash-preview",
            prompt_tokens=0,
            completion_tokens=0,
            total_tokens=0,
            status="failed",
            metadata={"error": str(schema_error)}
        )

    # Return both rules and the top-level inputSchema
    return rules, input_schema

async def generate_ruleexpression_new(rules, description, org_id: Optional[str] = None, subscriber_id: Optional[str] = None, schema_only=False):
    local_llm = LLM(
        model="gemini-3-flash-preview",
        provider="gemini",
        temperature=0.0,
        api_key=get_gemini_api_key()
    )
    if not schema_only:
        for rule in rules:
            prompt = f"""You are a Python code generator for data validation and enrichment rules.
    Generate a single `process_rules(input_data: dict) -> dict` function that implements ONLY the rule below.

    **Global Context:**
    {description}

    **Rule Name:** {rule['ruleName']}
    **Rule Description:** {rule['ruleDescription']}
    **Expected Message Format:** {rule.get('message', '')}

    **Available variables inside the function:** `db` (MongoDB), `datetime`, `timedelta`, `json`, `re`

    **Output rules:**
    - VALIDATION ERROR → `input_data["DocumentLevelError"].append({{"field_name": "error message"}})`
    - EXCEPTION condition → `input_data["DocumentLevelException"].append({{"field_name": "exception message"}})`
    - LOOKUP / POPULATE field → set directly: `input_data["field_name"] = fetched_value`
    - ADD new field → `input_data["new_field"] = value`
    - field_name in errors/exceptions must match an existing key in input_data. If no match, use the closest relevant key.
    - Use the Expected Message Format to construct error/exception messages.

    **Numeric field handling (CRITICAL):**
    ```python
    value = input_data.get('field_name')
    if value is not None and value != '':
        try:
            numeric_value = float(value)
        except (ValueError, TypeError):
            numeric_value = None
    ```

    **Required structure:**
    ```python
    def process_rules(input_data: dict) -> dict:
        try:
            input_data.setdefault("DocumentLevelError", [])
            input_data.setdefault("DocumentLevelException", [])

            # --- Rule: {rule['ruleName']} ---
            try:
                # implement rule logic here
                pass
            except Exception as e:
                input_data["DocumentLevelError"].append({{"{rule['ruleName']}": str(e)}})

            # Clean up empty lists
            if not input_data["DocumentLevelError"]:
                del input_data["DocumentLevelError"]
            if not input_data["DocumentLevelException"]:
                del input_data["DocumentLevelException"]

            return input_data

        except Exception as e:
            input_data.setdefault("DocumentLevelError", [])
            input_data["DocumentLevelError"].append({{"process_rules": str(e)}})
            return input_data
    ```

    Generate ONLY the Python function, no explanations, no markdown:"""

            try:
                started_at = datetime.utcnow()
                cleaned_response = (await run_sync(local_llm.call, prompt)).strip()
                finished_at = datetime.utcnow()

                prompt_tokens = len(prompt) // 4
                completion_tokens = len(cleaned_response) // 4

                record_llm_call(
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    operation="agent-task",
                    sub_operation="generate-rule-expression",
                    model="gemini-3-flash-preview",
                    prompt_tokens=prompt_tokens,
                    completion_tokens=completion_tokens,
                    total_tokens=prompt_tokens + completion_tokens,
                    status="success",
                    started_at=started_at,
                    finished_at=finished_at,
                    metadata={"rule_name": rule.get('ruleName', '')[:100]}
                )

                regex_pattern = r'```python(.*?)```'
                match = re.findall(regex_pattern, cleaned_response, flags=re.S)
                rule['additionalInfoCode'] = match[0].strip() if match else cleaned_response

            except Exception as error:
                print(f"[generate_ruleexpression] Error for rule '{rule.get('ruleName')}': {error}")
                rule['additionalInfoCode'] = ''
                rule['rulefailed'] = str(error)
                record_llm_call(
                    org_id=org_id,
                    subscriber_id=subscriber_id,
                    operation="agent-task",
                    sub_operation="generate-rule-expression",
                    model="gemini-3-flash-preview",
                    prompt_tokens=0, completion_tokens=0, total_tokens=0,
                    status="failed",
                    metadata={"rule_name": rule.get('ruleName', '')[:100], "error": str(error)}
                )

    # ================================================================
    # PASS 2: Generate inputSchema ONCE at rule-set level
    # ================================================================
    input_schema = None
    if schema_only:
        rules_summary = "\n\n".join([
            f"Rule '{r['ruleName']}':\n"
            f"  Description: {r['ruleDescription']}\n"
            f"  Code:\n{r.get('additionalInfoCode', '# not available')}"
            for r in rules
        ])

        schema_prompt = f"""Analyze these data rules to extract the combined input field requirements for the entire rule set.

    Global Context: {description}

    Rules:
    {rules_summary}

    A field is "required" if any rule reads it from `input_data` and cannot produce a meaningful result without it.

    Return ONLY a JSON object, no markdown:
    {{
        "required": ["field1", "field2"],
        "fieldMap": {{
            "field1": "collection.nested.path",
            "field2": "collection.nested.path"
        }},
        "optional": ["field3"],
        "description": "one line summary of what input this rule set needs"
    }}

    If no fields are required: {{"required": [], "fieldMap": {{}}, "optional": [], "description": "No input fields required"}}"""

        try:
            started_at = datetime.utcnow()
            schema_response = (await run_sync(local_llm.call, schema_prompt)).strip()
            finished_at = datetime.utcnow()

            prompt_tokens = len(schema_prompt) // 4
            completion_tokens = len(schema_response) // 4

            record_llm_call(
                org_id=org_id,
                subscriber_id=subscriber_id,
                operation="agent-task",
                sub_operation="generate-rule-input-schema",
                model="gemini-3-flash-preview",
                prompt_tokens=prompt_tokens,
                completion_tokens=completion_tokens,
                total_tokens=prompt_tokens + completion_tokens,
                status="success",
                started_at=started_at,
                finished_at=finished_at,
                metadata={"rules_count": len(rules)}
            )

            schema_response = re.sub(r'```json|```', '', schema_response).strip()
            start_idx = schema_response.find('{')
            end_idx = schema_response.rfind('}') + 1

            if start_idx != -1 and end_idx > start_idx:
                input_schema = json.loads(schema_response[start_idx:end_idx])
                print(f"[inputSchema] required={input_schema.get('required', [])}")
            else:
                input_schema = {"required": [], "fieldMap": {}, "optional": [], "description": "Could not parse schema"}
                print("[inputSchema] Schema parse failed, using empty fallback")

        except Exception as schema_error:
            print(f"[inputSchema] Error: {schema_error}")
            input_schema = {"required": [], "fieldMap": {}, "optional": [], "description": str(schema_error)}
            record_llm_call(
                org_id=org_id, subscriber_id=subscriber_id,
                operation="agent-task", sub_operation="generate-rule-input-schema",
                model="gemini-3-flash-preview",
                prompt_tokens=0, completion_tokens=0, total_tokens=0,
                status="failed", metadata={"error": str(schema_error)}
            )

    return rules, input_schema

@app.post("/aiqod-agent/agent/rules/generate-expressions")
async def generate_rule_expressions(request: Request):
    try:
        body = await request.json()
        _init_subscriber_billing_if_absent(
            body.get("subscriber_id") or body.get("subscriberId"),
            org_id=body.get("org_id") or body.get("orgId"),
        )
        rules = await generate_ruleexpression(
            rules=body["rules"],
            description=body["description"],
            org_id=body.get("org_id"),
            subscriber_id=body.get("subscriber_id"),
        )
        return {"success": True, "rules": rules}
    except HTTPException:
        raise
    except BillingError as _bill_err:
        # Save checkpoint for resume before re-raising
        try:
            # Build phase graphs snapshot from completed_phase_results if available,
            # otherwise from the current state
            if 'completed_phase_results' in locals() and completed_phase_results:
                phase_graphs_snapshot = [
                    p.model_dump(exclude={"langgraph_code"}) for p in completed_phase_results
                ]
            elif 'pre_gap_phase_results' in locals() and pre_gap_phase_results:
                phase_graphs_snapshot = [
                    p.model_dump(exclude={"langgraph_code"}) for p in pre_gap_phase_results
                ]
            else:
                phase_graphs_snapshot = phase_graphs  # original from DB

            # Get prior phase outputs
            prior_outputs = {}
            if 'prior_phase_outputs' in locals() and prior_phase_outputs:
                prior_outputs = prior_phase_outputs

            # Get the current node being processed (for tool reconciliation)
            current_node_id = last_execute_snapshot.get("node_id") if 'last_execute_snapshot' in locals() else None

            # Write checkpoint with plan_update stage
            await asyncio.to_thread(
                write_checkpoint,
                db=db,
                workflow_id=payload.workflowId,
                subscriber_id=subscriber_id,
                org_id=org_id,
                user_id=user_id,
                status="paused_credit",
                pipeline_stage="plan_update",
                phase_index=0,  # plan_update is a single stage
                phase_total=1,
                phase_graphs=phase_graphs_snapshot,
                prior_phase_outputs=prior_outputs,
                request_context=payload.model_dump(),
                last_error={
                    "code": _bill_err.code,
                    "message": str(_bill_err),
                    "at": datetime.utcnow().isoformat(),
                },
                current_node_id=current_node_id,
            )

            # Update workflow status
            await asyncio.to_thread(
                set_workflow_agentic_status,
                db=db,
                workflow_id=payload.workflowId,
                subscriber_id=subscriber_id,
                org_id=org_id,
                user_id=user_id,
                status="paused_credit",
            )

            # Publish paused credit event
            _pause_detail = _billing_pause_error(
                _bill_err, workflow_id=payload.workflowId, subscriber_id=subscriber_id
            )
            await _publish_paused_credit(payload.workflowId, _pause_detail)

            logger.info(
                f"[plan/update] Saved paused_credit checkpoint for workflow {payload.workflowId} "
                f"due to budget exhaustion: {_bill_err}"
            )
        except Exception as _cp_err:
            logger.warning(f"[plan/update] Failed to save budget exhaustion checkpoint: {_cp_err}")

        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

