def serialize(doc: dict) -> dict:
    doc = dict(doc)
    doc.pop('_id', None)
    return doc

async def decompose_rule_from_prompt(
    prompt: str,
    org_id: Optional[str] = None,
    subscriber_id: Optional[str] = None,
    user_id: Optional[str] = None,
    project_id: Optional[str] = None, 
) -> Dict[str, Any]:
    """
    Takes a single high-level requirement string and decomposes it into
    the sub-rule structure the existing rule pipeline expects:
      {
        overallRuleName: str,
        description:     str,   # global context fed to each sub-rule's code gen
        ruleType:        str,   # "validation" | "enrichment" | "lookup"
        rules: [
          { ruleName: str, ruleDescription: str, message: str }
        ]
      }
    NOTE: No additionalInfoCode here — the existing enrich + generate pipeline
    handles that exactly as before on each returned sub-rule.
    """
    local_llm = LLM(
        model="gemini-3-flash-preview",
        provider="gemini",
        temperature=0.0,
        api_key=get_gemini_api_key()
    )

    decompose_prompt = f"""You are a rule designer for a data validation and enrichment system.

A user has described a requirement in plain text. Your job is to:
1. Give the overall rule set a short, descriptive name (PascalCase, no spaces).
2. Write a concise global context description that covers the data model and business rules
   shared across ALL sub-rules (field names, collections, relationships).
3. Classify the dominant type: "validation" | "enrichment" | "lookup"
4. Break the requirement into individual sub-rules — one sub-rule per distinct check,
   enrichment, or lookup. Keep each sub-rule focused on exactly ONE thing.

USER REQUIREMENT:
{prompt}

For each sub-rule produce:
- ruleName     : short PascalCase identifier (e.g. "CheckInvoiceAmount")
- ruleDescription : 1-3 sentences describing WHAT to check/compute and HOW
  (mention exact field names, threshold values, DB collections if implied)
- message      : the exact error/exception message format the rule should use
  (e.g. "Invoice amount must be greater than 0")

Return ONLY a JSON object, no markdown:
{{
  "overallRuleName": "ShortDescriptiveName",
  "description": "Global context: field names, collections, business rules shared by all sub-rules",
  "ruleType": "validation",
  "rules": [
    {{
      "ruleName": "CheckFieldName",
      "ruleDescription": "Detailed description of what to check and how",
      "message": "Error message format"
    }}
  ]
}}"""

    started_at = datetime.utcnow()
    raw = (await run_sync(local_llm.call, decompose_prompt)).strip()
    finished_at = datetime.utcnow()

    prompt_tokens     = len(decompose_prompt) // 4
    completion_tokens = len(raw) // 4
    record_llm_call(
        org_id=org_id,
        subscriber_id=subscriber_id,
        operation="agent-task",
        sub_operation="decompose-rule-prompt",
        model="gemini-3-flash-preview",
        prompt_tokens=prompt_tokens,
        completion_tokens=completion_tokens,
        total_tokens=prompt_tokens + completion_tokens,
        status="success",
        started_at=started_at,
        finished_at=finished_at,
        metadata={"prompt_preview": prompt[:120]},
        user_id=user_id,
        project_id=project_id,
    )

    cleaned = re.sub(r'```json|```', '', raw).strip()
    start   = cleaned.find('{')
    end     = cleaned.rfind('}') + 1
    if start == -1 or end <= start:
        raise ValueError(f"decompose_rule_from_prompt: could not find JSON in LLM response: {raw[:300]}")

    try:
        result = json.loads(cleaned[start:end])
    except json.JSONDecodeError:
        result = json.loads(repair_json(cleaned[start:end]))

    # Sanity: must have at least one sub-rule
    if not result.get('rules'):
        raise ValueError("decompose_rule_from_prompt: LLM returned no sub-rules")

    print(f"[decompose_rule_from_prompt] decomposed into {len(result['rules'])} sub-rule(s): "
          f"{[r.get('ruleName') for r in result['rules']]}")
    return result

@app.post("/aiqod-agent/agent/rules")
async def create_rule(request: Request):
    try:
        body = await request.json()
        if not body:
            raise HTTPException(status_code=400, detail='Request body is required')

        subscriber_id = (body.get('subscriberId') or '').strip()
        org_id        = (body.get('orgId') or '').strip()

        if not subscriber_id or not org_id:
            raise HTTPException(status_code=400, detail='subscriberId and orgId are required in body')

        prompt_text = (body.get('prompt') or '').strip()
        if prompt_text and not body.get('rules'):
            decomposed = await decompose_rule_from_prompt(
                prompt=prompt_text,
                org_id=org_id,
                subscriber_id=subscriber_id,
                user_id=body.get('userId'),
                project_id=body.get('projectId'),
            )
            # Only fill fields that the caller did not explicitly provide
            if not (body.get('overallRuleName') or '').strip():
                body['overallRuleName'] = decomposed.get('overallRuleName', '')
            if not (body.get('description') or '').strip():
                body['description'] = decomposed.get('description', '')
            body['rules']    = decomposed.get('rules', [])
            body['ruleType'] = decomposed.get('ruleType', 'validation')
        rule_name = (body.get('overallRuleName') or '').strip()
        if not rule_name:
            raise HTTPException(status_code=400, detail='overallRuleName is required')

        rule_id = body.get('id') or f"rule_{int(datetime.utcnow().timestamp() * 1000)}"
        input_schema = body.get('input_schema')
        # Prevent duplicate name within same org
        existing = db.agent_rules.find_one({
            'subscriberId':    subscriber_id,
            'orgId':           org_id,
            'overallRuleName': rule_name,
            'isDeleted':       {'$ne': True}
        })
        if existing:
            raise HTTPException(status_code=409, detail=f'A rule named "{rule_name}" already exists')

        # Generate additionalInfoCode for rules missing it
        rules = body.get('rules', [])
        needs_generation = [r for r in rules if not r.get('additionalInfoCode')]
        # create_rule
        if needs_generation:
            needs_generation = await enrich_rule_descriptions(
                rules=needs_generation,
                description=body.get('description', ''),
                org_id=org_id,
                subscriber_id=subscriber_id
            )
            generated, _ = await generate_ruleexpression_new(
                rules=needs_generation,
                description=body.get('description', ''),
                org_id=org_id,
                subscriber_id=subscriber_id,
                schema_only=False
            )
            # Merge generated codes back into full rules list first
            gen_map = {r['ruleName']: r.get('additionalInfoCode', '') for r in generated}
            for r in rules:
                if not r.get('additionalInfoCode'):
                    r['additionalInfoCode'] = gen_map.get(r['ruleName'], '')

        # Always generate schema from the FULL rules list after codes are merged
        _, input_schema = await generate_ruleexpression_new(
            rules=rules,       
            description=body.get('description', ''),
            org_id=org_id,
            subscriber_id=subscriber_id,
            schema_only=True
        )

        now = datetime.utcnow().isoformat()
        rule_doc = {
            'id':              rule_id,
            'overallRuleName': rule_name,
            'description':     body.get('description', ''),
            'input_schema':    input_schema,
            'rules':           rules,
            'subscriberId':    subscriber_id,
            'orgId':           org_id,
            'isDeleted':       False,
            'createdAt':       now,
            'updatedAt':       now,
        }

        db.agent_rules.insert_one(rule_doc)

        return {'success': True, 'message': 'Rule created successfully', 'data': serialize(rule_doc)}

    except HTTPException:
        raise
    except Exception:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail='Failed to create rule')

@app.put("/aiqod-agent/agent/rules/{rule_id}")
async def update_rule(rule_id: str, request: Request):
    try:
        logger.info(f'updating rule {rule_id}')
        body = await request.json()
        if not body:
            raise HTTPException(status_code=400, detail='Request body is required')

        subscriber_id = (body.get('subscriberId') or '').strip()
        org_id        = (body.get('orgId') or '').strip()

        if not subscriber_id or not org_id:
            raise HTTPException(status_code=400, detail='subscriberId and orgId are required in body')

        # Verify rule exists and belongs to this org
        existing = db.agent_rules.find_one({
            'id':           rule_id,
            'subscriberId': subscriber_id,
            'orgId':        org_id,
            'isDeleted':    {'$ne': True}
        })
        if not existing:
            raise HTTPException(status_code=404, detail='Rule not found')

        rule_name = (body.get('overallRuleName') or '').strip()
        if not rule_name:
            raise HTTPException(status_code=400, detail='overallRuleName is required')

        # Prevent renaming to a name used by a different rule in the same org
        name_conflict = db.agent_rules.find_one({
            'subscriberId':    subscriber_id,
            'orgId':           org_id,
            'overallRuleName': rule_name,
            'id':              {'$ne': rule_id},
            'isDeleted':       {'$ne': True}
        })
        if name_conflict:
            raise HTTPException(status_code=409, detail=f'A rule named "{rule_name}" already exists')

        # Generate additionalInfoCode for rules missing it
        rules = body.get('rules', existing.get('rules', []))
        input_schema = existing.get('input_schema')
        existing_rules_map = {r['ruleName']: r for r in existing.get('rules', [])}
        incoming_rules_map = {r['ruleName']: r for r in rules}

        # Carry over existing code into incoming rules that don't have it
        for r in rules:
            existing_rule = existing_rules_map.get(r['ruleName'], {})
            if existing_rule.get('additionalInfoCode'):
                r['additionalInfoCode'] = existing_rule['additionalInfoCode']

        # Preserve rules not included in the incoming payload
        for rule_name, existing_rule in existing_rules_map.items():
            if rule_name not in incoming_rules_map:
                rules.append(existing_rule)

        # Only regenerate code for new or changed rules
        needs_generation = [
            r for r in rules
            if not r.get('additionalInfoCode')
            or r.get('ruleDescription') != existing_rules_map.get(r['ruleName'], {}).get('ruleDescription')
        ]

        description_changed = body.get('description', '') != existing.get('description', '')

        if needs_generation:
            needs_generation = await enrich_rule_descriptions(
                rules=needs_generation,
                description=body.get('description', existing.get('description', '')),
                org_id=org_id,
                subscriber_id=subscriber_id
            )
            generated, _ = await generate_ruleexpression_new(
                rules=needs_generation,
                description=body.get('description', existing.get('description', '')),
                org_id=org_id,
                subscriber_id=subscriber_id,
                schema_only=False
            )
            gen_map = {r['ruleName']: r.get('additionalInfoCode', '') for r in generated}
            for r in rules:
                if r['ruleName'] in gen_map:
                    r['additionalInfoCode'] = gen_map[r['ruleName']]

        if needs_generation or description_changed:
            _, input_schema = await generate_ruleexpression_new(
                rules=rules,
                description=body.get('description', existing.get('description', '')),
                org_id=org_id,
                subscriber_id=subscriber_id,
                schema_only=True
            )
        update_fields = {
            'overallRuleName': rule_name,
            'description':     body.get('description', existing.get('description', '')),
            'input_schema':    input_schema,
            'rules':           rules,
            'updatedAt':       datetime.utcnow().isoformat(),
        }

        db.agent_rules.update_one(
            {'id': rule_id, 'subscriberId': subscriber_id, 'orgId': org_id},
            {'$set': update_fields}
        )

        updated_doc = {**serialize(existing), **update_fields}
        return {'success': True, 'message': 'Rule updated successfully', 'data': updated_doc}

    except HTTPException:
        raise
    except Exception:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail='Failed to update rule')



