def default_obj_ui_screen_new(screen_data):
    """
    FIXED HELPER: Syncs Screen IR Schema IO with Workflow Node definitions.
    Ensures input/output parameters are Lists (not Dicts) so the Workflow Engine can read them.
    """
    bot_id = generate_numeric_id()
    
    # 1. Basic Extraction
    screen_id = screen_data.get('screen_id', '') or screen_data.get('screenId', '')
    project_id = screen_data.get('project_id', '') or screen_data.get('projectId', '')
    title = screen_data.get('screen_name', screen_data.get('name', screen_id))
    description = screen_data.get('description', 'UI Screen Interaction')

    # 2. IO Extraction from IR Schema
    ir_schema = screen_data.get('ir_schema', {})
    workflow_input_params = []
    workflow_output_params = []
    
    # --- INPUT FIX: Convert to List of Objects ---
    # We explicitly convert the dictionary format to the List format required by the Workflow Engine.
    input_params = ir_schema.get('inputParameters', [])
    if isinstance(input_params, list):
        for param in input_params:
            if isinstance(param, dict) and 'name' in param:
                workflow_input_params.append({
                    "name": param['name'],
                    "dataType": param.get('dataType', 'String'),
                    "value": param.get('value', ''),
                    "label": param.get('label', param['name']),
                    "description": param.get('description', '')
                })

    # --- OUTPUT FIX: Force Sync Backend with IR Schema ---
    # This is the critical fix. We take the 'outputParameters' from the Screen Schema
    # (e.g., 'submittedNumber') and explicitly add them to the Workflow Node.
    output_params = ir_schema.get('outputParameters', [])
    if isinstance(output_params, list):
        for param in output_params:
            if isinstance(param, dict) and 'name' in param:
                workflow_output_params.append({
                    "name": param['name'],
                    "dataType": param.get('dataType', 'String'),
                    "value": param.get('value', ''),
                    "label": param.get('label', param['name']),
                    "description": param.get('description', '')
                })

    # 3. Construct Workflow Node
    default_obj = {
        "taskTitle": title,
        "taskDesc": description,
        "description": description,
        "category": "_ui",
        "botCategory": "UI Screens",
        # FIX: Now passing the populated LISTS instead of empty Dicts
        "inputParameters": workflow_input_params, 
        "outputParameters": workflow_output_params, 
        "botId": bot_id,
        "graphId": str(bot_id),
        "screenId": screen_id,      
        "projectId": project_id, 
        "isRemote": False, 
        "isProcess": True,
        "uiComponent": { 
            "type": "angular_screen",
            "screen_id": screen_id,
            "project_id": project_id
        },
        "isDeleted": False,
        "isNotification": False,
        "isAddInfo": False,
        "isReports": False,
        "botShape": "rectangle",
        "statusName": title,
        "isDependent": False,
        "isStart": False,
        "isEnd": False,
        "isSaveMapping": True,
        "botMappingList": [],
        "leaf": True,
        "isBack": False
    }
    
    return default_obj
 

@app.post('/aiqod-agent/agent/evaluateAIRuleOld')
async def evaluateAIRuleOld(request: EvaluateAIRuleRequest):
    try:
        data = request.model_dump()
        
        if 'rulesSetValue' not in data or 'airule' not in data:
             # Just in case model_dump includes Nones or incomplete data
             raise HTTPException(status_code=400, detail={'status': 400, 'error': 'input and airule are required fields'})

        input_data = data['rulesSetValue']
        airule = data['airule']['rules']
        
        # FIX 1: Enhanced Description Lookup (Check ruleDescription first, then fallback)
        description = data['airule'].get('ruleDescription', '')
        if not description:
            description = data['airule'].get('description', '')
            
        if description:
            for rule in airule:
                expression = rule.get('additionalInfoCode', '')
                if expression:
                    cleaned_response = expression
                    try:
                        # Create a safe execution environment
                        safe_globals = {
                            'db': db,
                            'input_data': input_data,
                            'list': list,
                            'dict': dict,
                            'str': str,
                            'int': int,
                            'float': float,
                            'datetime': datetime,
                            'timedelta': timedelta,
                            'json': json,
                            're': re,
                            'repair_json': repair_json,
                            'llm': llm,
                            'additional_data': None
                        }

                        # Execute the dynamic query code
                        exec(cleaned_response, safe_globals)
                        exec_result = safe_globals.get('additional_data')
                        # Convert cursor to list if it's a MongoDB cursor
                        if hasattr(exec_result, '__iter__') and not isinstance(exec_result, (str, dict)):
                            additional_data = list(exec_result)
                        else:
                            additional_data = exec_result

                        print(f'Additional data retrieved: {additional_data}')
                        if 'additional_data' not in input_data:
                            input_data['additional_data'] = []

                        input_data['additional_data'].append(additional_data)

                    except Exception as e:
                        print(f'Error executing dynamic query: {str(e)}')
                        # Matches Flask behavior: clear/reset additional_data on error
                        input_data['additional_data'] = []

        # FIX 2: Clean the rules (Deep Copy & Remove code) to avoid token waste/confusion
        formatted_airule = copy.deepcopy(airule)
        for rule in formatted_airule:
            rule.pop('additionalInfoCode', None)

        # FIX 3: Use formatted_airule in prompt
        evaluation_prompt = f'''Evaluate the following list of rules: "{formatted_airule}" on this input: "{input_data}". Provide a concise summary of the evaluation result.

        IMPORTANT: If a rule's purpose is a data lookup (e.g., fetch/lookup a field from a collection), 
        and the corresponding field in the input is empty or missing, check the additional_data field. 
        If additional_data contains the required value, populate/overwrite the empty field in the output 
        with that value. Do NOT raise a DocumentLevelError in this case — the lookup succeeded.

        If the rule mentions above an error then add the error message in the format of "DocumentLevelError":[{{"$field_name":"$error message"}}].
        If the rule mentions it as exception then add the exception messages in the format of "DocumentLevelException":[{{"$field_name":"$error message"}}].
        Always use the DocumentLevelError to display the error message.
        Always use the DocumentLevelException to display the exception message.
        Use the additional_data field in the input for any external information needed for the evaluation. 
        If additional data for a rule is not available, ignore the condition.
        DocumentLevelError/DocumentLevelException field_name should always be the same from input_data. 
        If no appropriate field is found, choose a relevant field from the input data to associate with the error message.
        Return the result in JSON without ignoring any keys from the input. If a key from the input is not mentioned in the rule, retain its original value.'''
        print(evaluation_prompt)
        started_at_eval = datetime.utcnow()
        response = llm.call(evaluation_prompt).strip()
        finished_at_eval = datetime.utcnow()
        prompt_tokens_eval = len(evaluation_prompt) // 4
        completion_tokens_eval = len(response) // 4 if response else 0
        record_llm_call(
            org_id=None,
            subscriber_id=None,
            operation="agent-task",
            sub_operation="evaluate-ai-rule",
            model="gemini-3-flash-preview",
            prompt_tokens=prompt_tokens_eval,
            completion_tokens=completion_tokens_eval,
            total_tokens=prompt_tokens_eval + completion_tokens_eval,
            status="success",
            started_at=started_at_eval,
            finished_at=finished_at_eval,
            metadata={},
        )
        print('AI Rule Evaluation response:', response)
        regex_pattern = r'```json(.*?)```'
        match = re.findall(regex_pattern, response, flags=re.S)
        if match:
            try:
                value = repair_json(match[0].strip())
                default_values = json.loads(value)
            except json.JSONDecodeError as e:
                print(f"Error decoding JSON: {e}")
                default_values = {}
            response = default_values
        else:
            response = {"output": response}           
        return {'status': 0, 'data': response}       
    except Exception as e:
        print(f"Error evaluating AI rule: {e}")
        raise HTTPException(status_code=400, detail={'status': 400, 'error': str(e)})

@app.post('/aiqod-agent/agent/evaluateAIRule')
async def evaluateAIRule(request: EvaluateAIRuleRequest):
    try:
        data = request.model_dump()
        input_data = data['rulesSetValue']
        rule_id = data['id']
        existing = db.agent_rules.find_one({
            'id':           rule_id,
            'isDeleted':    {'$ne': True}
        })
        if not existing:
            raise HTTPException(status_code=404, detail='Rule not found')
        rules = existing['rules']
        safe_globals_base = {
            'db': db, 'list': list, 'dict': dict, 'str': str,
            'int': int, 'float': float,
            'datetime': datetime, 'timedelta': timedelta,
            'json': json, 're': re,
        }

        # Chain rules — each rule receives the output of the previous
        for rule in rules:
            code = rule.get('additionalInfoCode', '').strip()
            if not code:
                continue
            try:
                safe_globals = {**safe_globals_base, 'input_data': input_data}
                exec(code, safe_globals)
                process_fn = safe_globals.get('process_rules')
                if callable(process_fn):
                    input_data = process_fn(input_data)  # output feeds next rule
                print('Result of rule',input_data)
            except Exception as e:
                print(f"[evaluateAIRule] Error in rule '{rule.get('ruleName')}': {e}")
                input_data.setdefault('DocumentLevelError', [])
                input_data['DocumentLevelError'].append({rule.get('ruleName', 'unknown'): str(e)})

        return {'status': 0, 'data': json.loads(json.dumps(input_data,default=str))}

    except Exception as e:
        print(f"Error evaluating AI rule: {e}")
        raise HTTPException(status_code=400, detail={'status': 400, 'error': str(e)})

@app.post('/aiqod-agent/agent/tooledit')
async def api_edit_tool(tool_data: EditToolRequest):
    """
    Edit an existing dynamic tool.

    Expected JSON format is the same as tool registration, but the 'name'
    must match an existing tool.
    """
    try:
        # Call the new edit method in the tool registry
        success = tool_registry.edit_tool(tool_data.model_dump())

        if success:
            return {
                'success': True,
                'message': f'Tool "{tool_data.name}" updated successfully.'
            }
        else:
            raise HTTPException(status_code=404, detail={
                'success': False,
                'error': f'Failed to update tool "{tool_data.name}". It might not exist or there was an internal error.'
            })

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail={
            'success': False,
            'error': str(e)
        })

@app.post('/aiqod-agent/agent/tooleditinfo')
async def api_fetch_tool_definition(request: FetchToolRequest):
    """
    Fetches the full JSON definition of a dynamically created tool from its saved file.
    This is used to populate the editing modal.
    """
    try:
        tool_name = request.name
        if not tool_name:
            raise HTTPException(status_code=400, detail={'success': False, 'error': 'Tool name required'})

        # Use the existing registry logic to find the file path
        json_path = tool_registry._find_tool_json_path(tool_name)

        if not json_path:
            # If no JSON file is found, it's either a static tool or doesn't exist
            raise HTTPException(status_code=404, detail={'success': False, 'error': 'Tool not found or is a static system tool.'})

        with open(json_path, 'r', encoding='utf-8') as f:
            tool_data = json.load(f)

        return {'success': True, 'data': tool_data}
    except HTTPException:
        raise
    except Exception as e:
        print(f"Error fetching tool definition: {e}")
        raise HTTPException(status_code=500, detail={'success': False, 'error': str(e)})

