class ToolRegenerateRequest(BaseModel):
    name: str
    prompt: str
    userId: Optional[str] = None
    subscriberId: Optional[str] = None
    orgId: Optional[str] = None


class GetBackendFunctionRequest(BaseModel):
    project_id: str
    function_id: str


# TOOL REGENERATE ENDPOINT
@app.post("/aiqod-agent/agent/tool-regenerate")
async def regenerate_backend_tool_endpoint(request: ToolRegenerateRequest):
    try:
        tool_name = request.name
        user_prompt = request.prompt

        _init_subscriber_billing_if_absent(
            request.subscriberId,
            org_id=request.orgId,
            user_id=request.userId,
        )
        
        tool_path = tool_registry._find_tool_json_path(tool_name)
        if not tool_path:
            raise HTTPException(status_code=404, detail=f"Tool {tool_name} not found")
            
        with open(tool_path, 'r') as f:
            trusted_tool_data = json.load(f)
        
        llm_prompt = f"""You are a Python backend developer. 
You need to update the logic of a LangChain-compatible tool based on the user's instruction.
YOU MUST ONLY UPDATE THE `function_code` AND `imports`.
DO NOT change the parameters or outputs.

USER INSTRUCTION:
{user_prompt}

CURRENT TOOL DEFINITION:
{json.dumps(trusted_tool_data, indent=2)}

Task: Rewrite the 'function_code' to fulfill the user's instruction.
NO mock data. It MUST be a synchronous Python function body.
DO NOT use `await`.

Respond ONLY with a JSON object containing EXACTLY these two keys:
{{
  "function_code": "new python code...",
  "imports": ["import json", "import time"]
}}
"""
        response = await async_llm_call(llm_prompt)
        raw_json = _strip_llm_json_fences(response.strip())
        
        try:
            llm_output = json.loads(raw_json)
        except json.JSONDecodeError:
            llm_output = json.loads(repair_json(raw_json))
            
        # STRICT MERGE LOGIC
        merged_tool_data = trusted_tool_data.copy()
        if "function_code" in llm_output:
            merged_tool_data["function_code"] = llm_output["function_code"]
        if "imports" in llm_output:
            merged_tool_data["imports"] = llm_output["imports"]
            
        return {"success": True, "data": merged_tool_data}
        
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error regenerating tool: {e}")
        return {"success": False, "error": str(e)}


@app.post("/aiqod-agent/agent/get-backend-function")
async def get_backend_function_endpoint(request: GetBackendFunctionRequest):
    """
    Query the backend_functions collection and return the latest version document
    by project_id and function_id.
    """
    try:
        project_id = request.project_id
        function_id = request.function_id

        if not project_id or not function_id:
            raise HTTPException(
                status_code=400,
                detail={"success": False, "error": "project_id and function_id are required"}
            )
        function_doc = db["backend_functions"].find_one(
            {
                "project_id": project_id,
                "function_id": function_id
            },
            sort=[("version", -1)]  # Get the document with the highest version
        )
        if not function_doc:
            # Try sorting by _id as fallback
            function_doc = db["backend_functions"].find_one(
                {
                    "project_id": project_id,
                    "function_id": function_id
                },
                sort=[("_id", -1)]
            )

        if not function_doc:
            raise HTTPException(
                status_code=404,
                detail={
                    "success": False,
                    "error": f"No function found for project_id='{project_id}' and function_id='{function_id}'"
                }
            )

        # Serialize the document (convert ObjectId to string)
        serialized = serialize_mongo_document(function_doc)

        return {
            "success": True,
            "data": serialized
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error fetching backend function: {e}")
        raise HTTPException(
            status_code=500,
            detail={"success": False, "error": str(e)}
        )


