class PromptExtractor:
    """
    Generic prompt and LLM call extractor.

    Uses heuristic-based detection rather than hardcoded framework-specific patterns.
    Detects:
    - String assignments to variables with semantic names (prompt, instruction, template, etc.)
    - Function calls that appear to invoke LLMs (based on naming patterns and context)
    - LangChain-style message constructs (SystemMessage, HumanMessage, AIMessage)
    - Common LLM client instantiation patterns
    """

    # Configurable semantic keywords - can be extended without code changes
    PROMPT_VAR_KEYWORDS = [
        'prompt', 'instruction', 'system_message', 'template', 'system_prompt',
        'user_prompt', 'system_instruction', 'preamble', 'persona', 'role',
        'task_description', 'context', 'guidance', 'directive',
        'query', 'question', 'input_text', 'conversation',
        'few_shot', 'examples', 'prefix', 'suffix', 'prefix_prompt',
        'meta_prompt', 'base_prompt', 'default_prompt', 'custom_prompt'
    ]

