@app.post("/aiqod-agent/agent/agentic/plan/update/impact-analysis")
async def run_impact_analysis(request: ImpactAnalysisRequest, http_request: Request):
    """Run impact analysis only - shows what will change without applying."""
    try:
        org_id = request.orgId or http_request.headers.get("x-org-id")
        subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
        user_id = request.userId or http_request.headers.get("x-user-id")

        if not subscriber_id:
            raise HTTPException(status_code=400, detail="subscriberId is required.")

        # Load workflow
        query = {
            "engineType": "agentic_graph",
            "agentic_process.workflow_id": request.workflowId,
            "subscriberId": ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id,
        }
        if org_id:
            query["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id

        doc = db["Process_Configs"].find_one(query)
        if not doc:
            raise HTTPException(status_code=404, detail="Workflow not found.")

        phase_graphs = doc.get("agentic_process", {}).get("phaseGraphs", [])
        updated_node_ids = {op.get("targetStepId") for op in request.operations if op.get("targetStepId")}

        # Build initial proposed changes with update_request
        proposed_changes = {}
        for op in request.operations:
            action = op.get("action")
            target_step_id = op.get("targetStepId")
            if action == "UPDATE" and target_step_id:
                prompt = op.get("prompt") or ""

                # Get current node config
                current_node = None
                for phase in phase_graphs:
                    for node in phase.get("graph", {}).get("nodes", []):
                        if node.get("nodeId") == target_step_id:
                            current_node = node
                            break

                current_outputs = []
                if current_node:
                    current_outputs = current_node.get("config", {}).get("declaredOutputs", [])

                input_bindings = op.get("inputBindings") or {}
                if isinstance(input_bindings, str):
                    input_bindings = {}
                elif not isinstance(input_bindings, dict):
                    input_bindings = {}

                has_prompt = bool(prompt and prompt.strip())

                proposed_changes[target_step_id] = {
                    "inputBindings": op.get("inputBindings") if isinstance(op.get("inputBindings"), dict) else input_bindings,
                    "declaredOutputs": [] if has_prompt else current_outputs,
                    "generationDescription": prompt if isinstance(prompt, str) else "",
                    "_update_request": prompt if isinstance(prompt, str) else ""
                }

        # Get actual proposed schemas from LLM (dry run)
        llm_debug = {}
        if updated_node_ids:
            from regeneration import get_proposed_node_schemas
            from services.ai_processor import async_generate
            from services.ai_processor import GeminiGenerateConfig
            from services.gemini_service import extract_text

            async def llm_caller(system_prompt: str, user_prompt: str, sub_op: str = "") -> str:
                response = await async_generate(
                    "gemini-3-flash-preview",
                    f"{system_prompt}\n\n{user_prompt}",
                    config=GeminiGenerateConfig(temperature=0.2)
                )
                return extract_text(response)

            llm_result = await get_proposed_node_schemas(phase_graphs, updated_node_ids, llm_caller, proposed_changes)

            if isinstance(llm_result, tuple) and llm_result:
                llm_schemas = llm_result[0] if len(llm_result) > 0 else {}
                debug_info = llm_result[1] if len(llm_result) > 1 else {}
                llm_debug = {"proposed_schemas": llm_schemas, **debug_info}
            else:
                llm_schemas = llm_result
                llm_debug = {"proposed_schemas": llm_schemas}

            # Merge LLM-proposed outputs into proposed_changes
            for node_id, schema in llm_schemas.items():
                if node_id in proposed_changes:
                    proposed_changes[node_id]["inputBindings"] = schema.get("inputBindings", proposed_changes[node_id]["inputBindings"])
                    proposed_changes[node_id]["declaredOutputs"] = schema.get("declaredOutputs", proposed_changes[node_id]["declaredOutputs"])

        from impact_analysis import run_impact_analysis
        report = await run_impact_analysis(phase_graphs, updated_node_ids, proposed_changes)

        response = {"success": True, "impact_report": report.to_dict()}
        if llm_debug:
            response["debug_llm"] = llm_debug
        return response

    except HTTPException:
        raise
    except Exception as e:
        import traceback
        logger.error(f"Impact analysis failed: {e}\n{traceback.format_exc()}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/aiqod-agent/agent/agentic/plan/update/edit-plans")
async def generate_edit_plans(request: EditPlanRequest, http_request: Request):
    """Generate surgical edit plans without applying them."""
    import logging
    logger = logging.getLogger(__name__)
    try:
        org_id = request.orgId or http_request.headers.get("x-org-id")
        subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
        user_id = request.userId or http_request.headers.get("x-user-id")

        if not subscriber_id:
            raise HTTPException(status_code=400, detail="subscriberId is required.")

        # Load workflow
        query = {
            "engineType": "agentic_graph",
            "agentic_process.workflow_id": request.workflowId,
            "subscriberId": ObjectId(subscriber_id) if isinstance(subscriber_id, str) else subscriber_id,
        }
        if org_id:
            query["orgId"] = ObjectId(org_id) if isinstance(org_id, str) else org_id

        doc = db["Process_Configs"].find_one(query)
        if not doc:
            raise HTTPException(status_code=404, detail="Workflow not found.")

        phase_graphs = doc.get("agentic_process", {}).get("phaseGraphs", [])

        # Build proposed changes
        proposed_changes = {}
        updated_node_ids = set()
        for op in request.operations:
            action = op.get("action")
            target_step_id = op.get("targetStepId")
            if action == "UPDATE" and target_step_id:
                updated_node_ids.add(target_step_id)
                prompt = op.get("prompt") or ""

                # Get current node config to preserve existing outputs
                current_node = None
                for phase in phase_graphs:
                    for node in phase.get("graph", {}).get("nodes", []):
                        if node.get("nodeId") == target_step_id:
                            current_node = node
                            break

                current_outputs = []
                if current_node:
                    current_outputs = current_node.get("config", {}).get("declaredOutputs", [])

                proposed_changes[target_step_id] = {
                    "inputBindings": op.get("inputBindings") if isinstance(op.get("inputBindings"), dict) else {},
                    "declaredOutputs": current_outputs,  # PRESERVE existing outputs
                    "generationDescription": prompt if isinstance(prompt, str) else "",
                    "_update_request": prompt if isinstance(prompt, str) else ""
                }

        from surgical_editing import generate_surgical_edit_plan
        plans = await generate_surgical_edit_plan(
            phase_graphs, updated_node_ids, proposed_changes, {}, {}, lambda s, u, so: ""
        )

        return {"success": True, "edit_plans": [p.__dict__ for p in plans]}

    except HTTPException:
        raise
    except Exception as e:
        import traceback
        logger.error(f"Edit plan generation failed: {e}\n{traceback.format_exc()}")
        raise HTTPException(status_code=500, detail=str(e))


