@app.get("/aiqod-agent/agent/agentic/plan/update/stream/{workflowId}")
async def pipeline_status_stream(workflowId: str, subscriberId: str):
    """SSE stream for pipeline progress."""
    from sse_starlette.sse import EventSourceResponse
    import asyncio
    import json

    async def event_generator():
        # This would typically connect to a message queue or use a shared state
        # For now, we'll simulate progress updates
        phases = [
            ("impact_analysis", "Analyzing impact of changes..."),
            ("user_approval", "Breaking changes detected. Awaiting approval..."),
            ("surgical_editing", "Generating surgical edits..."),
            ("validation_repair", "Running validation & repair..."),
            ("complete", "Pipeline completed successfully!"),
        ]

        for i, (phase, message) in enumerate(phases):
            data = {
                "phase": phase,
                "message": message,
                "iteration": 1,
                "data": {"step": phase}
            }
            yield f"data: {json.dumps(data)}\n\n"
            await asyncio.sleep(1)  # Simulate work

        # Keep connection alive
        while True:
            await asyncio.sleep(5)
            yield f": keepalive\n\n"

    return EventSourceResponse(event_generator())

