@app.post("/aiqod-agent/agent/agentic/reports/remove/estimate", response_model=DashboardPlanEstimateResponse)
async def estimate_remove_report_from_process_config(request: RemoveReportRequest, http_request: Request) -> DashboardPlanEstimateResponse:
    """
    Pre-flight cost estimate for removing a report widget from an existing dashboard.
    No LLM calls, no Mongo writes. Call before /agentic/reports/remove.
    """
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")
    query: Dict[str, Any] = {"agentic_process.workflow_id": request.workflowId}
    if subscriber_id:
        try:
            query["subscriberId"] = {"$in": [ObjectId(subscriber_id), subscriber_id]}
        except Exception:
            query["subscriberId"] = subscriber_id

    doc = db["Process_Configs"].find_one(query)
    agentic_process = (doc or {}).get("agentic_process") or {}
    stored_report = (
        find_report_by_name(agentic_process.get("report"), request.reportName)
        or find_report_by_name(agentic_process.get("reports"), request.reportName)
        or find_report_by_name(agentic_process.get("suggestedReports"), request.reportName)
        or {"reportName": request.reportName, "reportType": "table"}
    )
    return _dashboard_estimate_from_reports([stored_report], subscriber_id)


@app.post("/aiqod-agent/agent/agentic/reports/remove")
async def remove_report_from_process_config(request: RemoveReportRequest, http_request: Request):
    """
    Remove a report from Process_Configs.agentic_process.reports,
    agentic_process.suggestedReports, and agentic_process.report arrays by reportName,
    and also removes the corresponding widget from the generated Angular screen.
    """
    org_id = request.orgId or http_request.headers.get("x-org-id")
    user_id = request.userId or http_request.headers.get("x-user-id")
    subscriber_id = request.subscriberId or http_request.headers.get("x-subscriber-id")

    try:
        collection = db["Process_Configs"]

        query: Dict[str, Any] = {"agentic_process.workflow_id": request.workflowId}
        if subscriber_id:
            try:
                query["subscriberId"] = {
                    "$in": [ObjectId(subscriber_id), subscriber_id]
                }
            except Exception:
                query["subscriberId"] = subscriber_id

        doc = collection.find_one(query)
        if not doc:
            raise HTTPException(
                status_code=404,
                detail=f"Process config not found for workflowId '{request.workflowId}'",
            )

        agentic_process = doc.get("agentic_process", {}) or {}

        if not subscriber_id:
            sub_oid = doc.get("subscriberId")
            subscriber_id = str(sub_oid) if sub_oid else None

        # ── 1. Update all DB arrays (reports, suggestedReports, report) ──────────

        current_reports = agentic_process.get("reports") or []
        updated_reports = [
            r for r in current_reports if r.get("reportName") != request.reportName
        ]

        current_suggested = agentic_process.get("suggestedReports") or []
        updated_suggested = [
            r for r in current_suggested if r.get("reportName") != request.reportName
        ]

        # Mark the matching entry as removed instead of deleting it
        current_report = agentic_process.get("report") or []
        updated_report = [
            {**r, "reportRemoved": True} if r.get("reportName") == request.reportName else r
            for r in current_report
        ]

        # ── 2. Update generated Angular screen if one exists ─────────────────────

        existing_screen_id: Optional[str] = agentic_process.get("dashboardScreenId")
        existing_def_data: Optional[Dict[str, Any]] = agentic_process.get("dashboardDefinition")
        existing_dashboard_url: Optional[str] = agentic_process.get("dashboardUrl")
        dashboard_name: str = agentic_process.get("dashboardName") or "Dashboard"

        screen_update_warnings: list[str] = []
        updated_def_data: Optional[Dict[str, Any]] = existing_def_data
        new_dashboard_url: Optional[str] = existing_dashboard_url

        if existing_screen_id and existing_def_data:
            try:
                existing_def = DashboardDefinition(**existing_def_data)

                # Build updated definition without the removed widget
                remaining_widgets = [
                    w for w in existing_def.widgets
                    if w.reportName != request.reportName
                ]
                updated_def = DashboardDefinition(
                    dashboardId=existing_def.dashboardId,
                    dashboardName=existing_def.dashboardName,
                    widgets=remaining_widgets,
                )

                if not remaining_widgets:
                    # No widgets left — skip Angular update, just clear the definition
                    logger.info(
                        "[reports/remove] No widgets remaining after removal for project %s; skipping Angular update.",
                        request.workflowId,
                    )
                    updated_def_data = updated_def.model_dump()
                else:
                    # Build removal prompt
                    removed_widget_summary = (
                        f'Remove the widget named "{request.reportName}" '
                        f'(reportName="{request.reportName}") from the dashboard.\n\n'
                        f"DO NOT remove or modify any other existing widgets. "
                        f"Only DELETE all references to this specific widget: its component "
                        f"declaration, HTML template block, CSS styles, and any service calls "
                        f"exclusive to it. Preserve the layout and theme for all other widgets.\n"
                    )

                    updated_ir_schema: Dict[str, Any] = {
                        "screen": {"id": existing_screen_id, "name": updated_def.dashboardName},
                        "components": [
                            {
                                "id": w.reportId,
                                "type": w.widgetType,
                                "reportName": w.reportName,
                                "reportType": w.reportType,
                                "title": w.title,
                                "description": w.description,
                            }
                            for w in updated_def.widgets
                        ],
                    }

                    new_version = datetime.utcnow().strftime("%Y%m%d%H%M%S")
                    current_doc = await screen_repository.get_latest_screen_doc(
                        request.workflowId, existing_screen_id
                    )
                    version_count = await screen_repository.count_versions(
                        request.workflowId, existing_screen_id
                    )
                    version_label = f"v{version_count + 1}"

                    current_state = await screen_repository.get_screen_state(
                        request.workflowId, existing_screen_id
                    )
                    workspace_dir: Optional[str] = (
                        current_state.get("angular_workspace_directory")
                        if current_state
                        else None
                    )

                    backend_meta_to_use = _ensure_backend_metadata({}, request.workflowId)

                    angular_result: Optional[Dict[str, Any]] = None
                    if not workspace_dir:
                        logger.warning(
                            "[reports/remove] Workspace not found for screen %s — falling back to full regeneration.",
                            existing_screen_id,
                        )
                        angular_result = await angular_generator.generate_app(
                            user_prompt=removed_widget_summary,
                            project_id=request.workflowId,
                            screen_id=existing_screen_id,
                            backend_metadata=backend_meta_to_use,
                            org_id=org_id,
                            subscriber_id=subscriber_id,
                            user_id=user_id,
                            version=new_version,
                            is_update=True,
                        )
                    else:
                        current_code = angular_generator._read_workspace_code(workspace_dir)
                        analysis = angular_generator.analyze_update_scope(
                            removed_widget_summary,
                            updated_ir_schema,
                            current_code,
                            project_id=request.workflowId,
                            screen_id=existing_screen_id,
                            version=new_version,
                            org_id=org_id,
                            subscriber_id=subscriber_id,
                            user_id=user_id,
                        )
                        affected_files: list[Dict[str, str]] = analysis.get("affected_files", [])
                        if not affected_files:
                            affected_files = [
                                {"path": "src/app/app.component.ts", "reason": "Remove widget component", "change_type": "component-remove"},
                                {"path": "src/app/app.component.html", "reason": "Remove widget template block", "change_type": "component-remove"},
                            ]
                        logger.info("[reports/remove] Affected files for removal: %s", affected_files)
                        angular_result = await angular_generator.update_app(
                            user_prompt=removed_widget_summary,
                            project_id=request.workflowId,
                            screen_id=existing_screen_id,
                            updated_ir_schema=updated_ir_schema,
                            affected_files=affected_files,
                            backend_metadata=backend_meta_to_use,
                            org_id=org_id,
                            subscriber_id=subscriber_id,
                            user_id=user_id,
                            version=new_version,
                        )

                    deploy_base_url = config.get("LIBERTY_FS_BASE_URL", "https://liberty-fs.gibots.com:843")
                    new_dashboard_url = (
                        (angular_result.get("public_url") if angular_result else None)
                        or f"{deploy_base_url.rstrip('/')}/{existing_screen_id}-v{new_version}"
                    )

                    angular_metadata = {
                        "workspace_directory": str(angular_result.get("workspace_directory")) if angular_result and angular_result.get("workspace_directory") else None,
                        "public_url": new_dashboard_url,
                        "version": angular_result.get("version") if angular_result else new_version,
                        "last_build_at": datetime.utcnow(),
                    }

                    if current_doc:
                        v_next_doc = copy.deepcopy(current_doc)
                        v_next_doc.pop("_id", None)
                        v_next_doc["ir_schema"] = updated_ir_schema
                        v_next_doc["angular"] = angular_metadata
                        v_next_doc["screen_name"] = updated_def.dashboardName
                        v_next_doc["screen_type"] = "dashboard"
                        try:
                            await screen_repository.insert_screen_version_doc(
                                request.workflowId,
                                existing_screen_id,
                                new_version,
                                version_label,
                                v_next_doc,
                                build_status="success",
                                is_stable=True,
                            )
                            subscriber_db_name = f"{get_main_db_name()}_sb_{subscriber_id}" if subscriber_id else None
                            await screen_repository.update_screens_pointer(
                                request.workflowId,
                                existing_screen_id,
                                new_version,
                                org_id=org_id,
                                subscriber_id=subscriber_id,
                                subscriber_db_name=subscriber_db_name,
                                user_id=user_id,
                            )
                            try:
                                screen_doc_cap = {**v_next_doc, "screen_id": existing_screen_id, "project_id": request.workflowId, "version": new_version}
                                await sync_screen_single(capability_repository, screen_doc_cap)
                            except Exception as cap_exc:
                                logger.warning("[reports/remove] Capability sync failed (non-fatal): %s", cap_exc)
                        except Exception as persist_exc:
                            logger.warning("[reports/remove] Failed to persist screen version (screen still deployed): %s", persist_exc)
                            screen_update_warnings.append(f"Screen version persistence failed: {persist_exc}")

                    updated_def_data = updated_def.model_dump()

            except Exception as screen_exc:
                logger.warning(
                    "[reports/remove] Angular screen update failed (non-fatal, DB removal will still proceed): %s",
                    screen_exc,
                    exc_info=True,
                )
                screen_update_warnings.append(f"Screen update failed: {screen_exc}")

        # ── 3. Persist all DB changes ─────────────────────────────────────────────

        db_set: Dict[str, Any] = {
            "agentic_process.reports": updated_reports,
            "agentic_process.suggestedReports": updated_suggested,
            "agentic_process.report": updated_report,
            "updated_at": datetime.utcnow(),
        }
        if updated_def_data is not None and updated_def_data != existing_def_data:
            db_set["agentic_process.dashboardDefinition"] = updated_def_data
        if new_dashboard_url and new_dashboard_url != existing_dashboard_url:
            db_set["agentic_process.dashboardUrl"] = new_dashboard_url

        collection.update_one({"_id": doc["_id"]}, {"$set": db_set})

        logger.info(
            "[reports/remove] Removed report '%s' from workflowId '%s'. Screen updated: %s",
            request.reportName,
            request.workflowId,
            existing_screen_id is not None,
        )
        return {
            "success": True,
            "message": f"Report '{request.reportName}' removed successfully",
            "workflowId": request.workflowId,
            "screenUpdated": existing_screen_id is not None and bool(existing_def_data),
            "dashboardUrl": new_dashboard_url,
            "warnings": screen_update_warnings,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error("Error in remove_report_from_process_config: %s", e, exc_info=True)
        raise HTTPException(
            status_code=500, detail={"success": False, "error": str(e)}
        )

core_logic = app


# 2. Create a new "Root" app that will serve as the entry point
app = FastAPI(
    title="AI Screen Builder Gateway",
    version="1.0.0"
)

# 3. Mount the core logic under the configured prefix
print(f"🚀 Mounting application at context path: {API_PREFIX}")
app.mount(API_PREFIX, core_logic)

# Example usage
if __name__ == "__main__":
    import uvicorn
    # Use reload=False to avoid file watch limit issues
